//! Bytecode -> AST decompiler.
//!
//! Strategy (pycdc-inspired, fully normalized):
//! * the instruction stream is pre-decoded by `bytecode::decode_instructions`,
//!   so this module never deals with wordcode/EXTENDED_ARG/CACHE/jump-unit
//!   differences — only canonical `Op` values and absolute byte targets
//! * a simulated value stack builds expressions; a block stack builds
//!   statements and control flow (if/while/for/try/with) from jump-target
//!   arithmetic
//! * anything unhandled degrades gracefully into `Stmt::Unimplemented` and
//!   sets `clean = false`, which the CLI reports as a warning comment

use std::collections::{HashMap, HashSet};
use std::rc::Rc;

use crate::ast::*;
use crate::bytecode::{binary_op_name, compare_op_index, Instruction};
use crate::code::CodeObject;
use crate::object::{ObjectRef, PyObject};
use crate::opcode::{table_for, OpcodeTable};
use crate::version::PythonVersion;

pub struct Decompiled {
    pub body: Vec<Stmt>,
    /// False when at least one construct could not be fully recovered.
    pub clean: bool,
    /// the bytecode tail holds the implicit `LOAD None; RETURN` pair
    /// right after a preceding return — the source's last statement was
    /// an all-arms-returning if/else; a flattened rendering must append
    /// an explicit `return None` to regenerate the pair (sig fidelity)
    pub tail_pair: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BlockType {
    Main,
    If,
    Else,
    Try,
    #[allow(dead_code)]
    TryElse,
    Except,
    Finally,
    While,
    WhileElse,
    For,
    ForElse,
    With,
    /// try/finally container (SETUP_FINALLY era and 3.11+ exception table)
    Container,
}

#[derive(Debug, Clone)]
struct Block {
    kind: BlockType,
    /// First byte offset covered by this block.
    #[allow(dead_code)]
    start: usize,
    /// Region end (exclusive); the block is closed when the stream reaches it.
    end: usize,
    stmts: Vec<Stmt>,
    cond: Option<ExprRef>,
    /// for loops
    target: Option<ExprRef>,
    iter: Option<ExprRef>,
    is_async: bool,
    /// except blocks
    handler_type: Option<ExprRef>,
    handler_name: Option<ExprRef>,
    /// if blocks: end of the else branch (set by the closing JUMP_FORWARD)
    else_end: Option<usize>,
    /// loops: end of the else branch
    loop_else_end: Option<usize>,
    /// try blocks: where the finally handler begins
    finally_target: Option<usize>,
    /// with blocks: the context item
    with_item: Option<WithItem>,
    /// whether the loop/if condition has been filled in
    cond_set: bool,
    /// for rotated 3.8+ while loops: end offset of the cond jump instr
    cond_end: usize,
    /// stack depth when the block was created (value-flow merge detection)
    stack_depth: usize,
    /// block opened by COPY + cond jump: closing merges stack values into
    /// BoolOp (and/or chains) or chained comparisons
    value_merge: Option<BoolOpKind>,
    /// SETUP_LOOP-era For with for-else: the original SETUP_LOOP target
    /// (loop pop). The block end is lowered to the FOR_ITER exhaustion
    /// exit so the else region [exit, setup_end) collects separately.
    for_setup_end: Option<usize>,
    /// the branch region ended with a backward jump fused into the
    /// enclosing loop's back edge: an elif/else boundary follows here
    folded_exit: bool,
    /// this Else block is an elif continuation
    is_elif: bool,
    /// conditional jump polarity that opened this If block
    jump_if_true: bool,
    /// Some(or_form) when the block merges a JUMP_IF_*_OR_POP short circuit
    short_circuit: Option<bool>,
    /// 3.12+ chained-comparison link (COPY + PJIF + SWAP/POP else arm)
    chain_link: bool,
    /// direct-form guard If spanning to its loop's end: the body's final
    /// iteration edge is NOT a folded chain exit — exempt from jfold
    /// spine marking (csv 3.13 _guess_delimiter: the JB-to-loop-top at
    /// the body tail marked the span If folded_exit, opening a phantom
    /// Else[MAX] that swallowed the while tail)
    no_fold: bool,
    /// value-merge block whose cond was stored POSITIVE (the 3.12+ COPY
    /// idiom contributes the operand as-is): close-time must NOT run the
    /// statement-guard simplify_not polarity restore on it
    merge_pos: bool,
    /// chain-exit clamp: the guard's cond jump originally targeted this
    /// offset (the chain-tail trampoline) but the block end was clamped
    /// to the arm's local merge. A split-condition `if a and b:` merge
    /// requires both cond jumps to share ONE target - a clamped guard's
    /// opening jump flies elsewhere, so a second jump landing on the
    /// clamped end is an independent nested guard, not an and-link
    /// (_strptime 3.3 ampm chain: `elif ampm == pm:` + `if hour != 12:`
    /// merged to `and`, recompiling the second PJIF to the chain tail
    /// instead of the local merge)
    clamp_from: Option<usize>,
}

impl Block {
    fn new(kind: BlockType, start: usize, end: usize) -> Block {
        Block {
            kind,
            start,
            end,
            stmts: Vec::new(),
            cond: None,
            target: None,
            iter: None,
            is_async: false,
            handler_type: None,
            handler_name: None,
            else_end: None,
            loop_else_end: None,
            finally_target: None,
            with_item: None,
            cond_set: true,
            cond_end: usize::MAX,
            stack_depth: 0,
            value_merge: None,
            for_setup_end: None,
            folded_exit: false,
            is_elif: false,
            jump_if_true: false,
            short_circuit: None,
            chain_link: false,
            no_fold: false,
            merge_pos: false,
            clamp_from: None,
        }
    }
}

/// A value on the simulated stack.
#[derive(Debug, Clone)]
enum Sv {
    E(ExprRef),
    /// NULL marker pushed before callables (3.11+)
    Null,
    /// IMPORT_NAME result awaiting IMPORT_FROM / IMPORT_STAR / store
    ImportModule {
        level: u32,
        module: String,
        /// pending `from x import (a, b)` name list being built
        fromlist: Option<ExprRef>,
    },
    /// One name of a pending `from x import a, b` (IMPORT_FROM result)
    ImportFrom {
        level: u32,
        module: String,
        name: String,
    },
}

/// A PEP 709 inline comprehension being recognized (3.12+). The whole
/// instruction region is pre-scanned, so `end` (the END_FOR offset of the
/// outermost loop) and all FOR_ITER offsets are known up front.
#[derive(Debug, Clone)]
struct InlineComp {
    kind: CompKind,
    /// offset where the comprehension's prologue begins (py2 nesting)
    start: usize,
    #[allow(dead_code)]
    iter: ExprRef,
    /// offset just past the outermost END_FOR
    end: usize,
    for_iter_offsets: Vec<usize>,
    gens: Vec<Comprehension>,
    /// generator currently being filled by the main loop
    cur: Option<PartialGen>,
    elt: Option<ExprRef>,
    key: Option<ExprRef>,
    cleared_vars: Vec<String>,
    target_seen: bool,
}

/// Pre-3.11 try statement collected across its handler chain.
#[derive(Debug, Clone)]
struct LegacyTry {
    body: Vec<Stmt>,
    handlers: Vec<ExceptHandler>,
    orelse: Vec<Stmt>,
    finalbody: Vec<Stmt>,
    /// offset where the handler chain begins
    handler_start: usize,
    has_finally: bool,
    /// when the try body ends with a forward jump over the handler chain,
    /// the else region spans [else_start, else_stop)
    else_start: Option<usize>,
    else_stop: usize,
    /// handler chain fully parsed (END_FINALLY passed); emit on next jump
    chain_done: bool,
    /// mismatch-jump targets of clauses opened via open_except_block; a
    /// pending target still holding a DUP_TOP clause head means the chain
    /// continues past this point and a backward jump here is a handler
    /// body's loop back edge, not the try's emit point
    pending_mismatch: Vec<usize>,
    /// enclosing block's statement count when this chain's inline
    /// finally region opened — stmts past the mark are the inline body
    else_stmt_mark: usize,
}

#[derive(Debug, Clone)]
struct LegacyHandler {
    type_: Option<ExprRef>,
    name: Option<ExprRef>,
    body: Vec<Stmt>,
    /// block-stack depth when the handler opened; statements only collect
    /// into `body` when no handler-internal block (If/While/...) is open
    block_depth: usize,
    /// 3.9 puts POP_EXCEPT before a terminating handler body; the fold is
    /// deferred until the body's RETURN/jump-out
    pop_seen: bool,
    /// 3.10+ ends a bare-except handler with a plain RAISE_VARARGS (no
    /// POP_EXCEPT/RERAISE/END_FINALLY follows to close it) — fold the
    /// handler at the NEXT instruction so the dispatch for the raise first
    /// lands Stmt::Raise in the handler body
    bare_raise_fold: bool,
}

/// Saved outer legacy-chain state while a nested chain (a try inside an
/// except body, <=3.7) parses in the single legacy_try/legacy_handler slots
struct LegacyNest {
    outer_try: Option<LegacyTry>,
    outer_handler: Option<LegacyHandler>,
    outer_handler_end: Option<usize>,
    outer_prelude: bool,
    depth: usize,
    /// region [start, end) of the nested handler chain the body-end jump
    /// flew over (parsed by sub-walk): a handler-exit jump inside it that
    /// lands on the OUTER else_start retracts the outer else region
    skipped_chain: Option<(usize, usize)>,
}

/// Reconstructed try-statement region (3.11+ exception-table driven).
#[derive(Debug, Clone)]
struct TryCtx {
    /// first protected offset
    start: usize,
    /// end of the try body (first except/else boundary)
    body_end: usize,
    /// end of the whole protected region (else end / finally start)
    region_end: usize,
    except_handler: Option<usize>,
    finally_handler: Option<usize>,
    /// 3.12+ zero-block finally with an early-exit (break) path: the
    /// protected range splits into [start, body_end) and this second
    /// fragment; the gap between them is the exit path's inlined finally
    /// copy ending in the exit jump
    split_body2: Option<(usize, usize)>,
}

impl TryCtx {
    fn cover_end(&self) -> usize {
        self.region_end
    }
}

#[derive(Debug, Clone)]
struct PartialGen {
    target: Option<ExprRef>,
    iter: ExprRef,
    ifs: Vec<ExprRef>,
    if_break: bool,
}

/// Per-unpack-frame collected targets (inner Vec per open frame).
struct FrameTargets(Vec<Vec<(ExprRef, bool)>>);

struct Ctx<'a> {
    code: &'a CodeObject,
    table: &'a OpcodeTable,
    version: PythonVersion,
    instrs: Vec<Instruction>,
    idx_of: HashMap<usize, usize>,
    targets: HashSet<usize>,
    stack: Vec<Sv>,
    blocks: Vec<Block>,
    clean: bool,
    /// unpack frames (remaining, count, star_at, value)
    unpack_frames: Vec<(usize, usize, Option<usize>, ExprRef)>,
    /// next STORE_* is a comprehension loop target: consumes no stack value
    comp_target_store: bool,
    /// GET_AWAITABLE seen: the next YIELD_VALUE is an `await`
    await_mode: bool,
    /// context expression stashed by BEFORE_ASYNC_WITH (<=3.9)
    pending_async_with_ctx: Option<ExprRef>,
    /// the END_SEND after an await yield must not pop
    skip_end_send: bool,
    /// the with-exit recognizer just swallowed an async-with __aexit__
    /// call: the following GET_AWAITABLE..YIELD_VALUE protocol has no
    /// awaitable left and must be dropped without a stack underflow
    with_exit_await_drop: bool,
    /// <=3.10 SETUP_WITH/SETUP_ASYNC_WITH handler starts: the normal-exit
    /// JUMP_FORWARD right before one must skip the whole handler region
    with_handler_starts: std::collections::HashSet<usize>,
    /// 3.5-3.7 async-for: the per-iteration StopAsyncIteration guard
    /// (SETUP_EXCEPT handler start, unwind tail start, loop exit offset)
    async_for_guard: Option<(usize, usize, usize)>,
    /// <=3.7 nested try inside an open legacy handler body: saved outer
    /// chain states (innermost last) while nested chains parse in the
    /// single slots
    legacy_nest: Vec<LegacyNest>,
    /// >0 while a skipped nested chain parses in a region sub-walk: the
    /// py2 implicit-as store there binds an extra exception placeholder
    /// instead of capturing the clause name
    legacy_nest_depth: usize,
    /// 2.6 compiler synthetic temps (`_[N]`): with-as targets and inline
    /// comprehension accumulators stash/reload through them
    py26_temps: HashMap<String, Sv>,
    /// completed py2 inline comprehension regions [start, end]: a nested
    /// comprehension's iterable can be one, and the outer detection scan
    /// must hop over it
    completed_comp_regions: Vec<(usize, usize)>,
    last_py26_temp: Option<String>,
    /// 3.3-3.7 swallowed `as`-cleanup wrappers: (SETUP offset, cleanup
    /// END_FINALLY offset) — that END_FINALLY must not be mistaken for
    /// the chain end, and the setup's normal-exit POP_BLOCK belongs to
    /// the wrapper, not the enclosing try
    as_cleanup_wrappers: Vec<(usize, usize)>,
    /// a py2 sub-walk bound `sys.exc_info()[1]` — ensure `import sys`
    used_exc_info: bool,
    /// a region sub-walk whose statements must collect into the region
    /// root and be returned to the caller — never route them into a
    /// (possibly stashed) legacy handler body (audiodev 2.7 AudioDev:
    /// the flown-over else spans parsed by parse_skipped_nested_chain
    /// leaked into the outer handler ahead of the nested Try)
    region_collect_only: bool,
    /// the offset the walk landed on when a nested try's body-end jump
    /// flew over its handler chain (parse_skipped_nested_chain): the
    /// function-tail epilogue reached THIS way is machinery, while an
    /// explicit `return` walked linearly inside a handler is source
    skipped_chain_landing: Option<usize>,
    pending_gen_code: Option<std::rc::Rc<crate::code::CodeObject>>,
    recent_code_const: Option<std::rc::Rc<crate::code::CodeObject>>,
    /// class expression for a no-dup `case Cls(...)` whose LOAD cls was
    /// already consumed by the main loop before the MATCH_CLASS dispatch
    pending_match_class: Option<ExprRef>,
    /// pending kw names for the next CALL (3.11/3.12 KW_NAMES)
    last_kw_names: Vec<Option<String>>,
    /// `global`/`nonlocal` collection (emitted at top of function bodies)
    globals: Vec<String>,
    nonlocals: Vec<String>,
    exc_entries: Vec<crate::code::ExceptionEntry>,
    /// pre-retain exception table: chain-extent closure needs entries the
    /// cleanup filter dropped (chain-internal redirects)
    raw_exc_entries: Vec<crate::code::ExceptionEntry>,
    /// reconstructed try regions keyed by body start offset (3.11+)
    try_ctxs: HashMap<usize, TryCtx>,
    /// first offset of out-of-line handler code (main pass stops here)
    handler_zone: Option<usize>,
    chain_heads: std::collections::HashSet<usize>,
    /// with-body regions from the exception table (3.11+): start -> end
    with_regions: HashMap<usize, usize>,
    /// try context whose body block is currently open
    active_try: Option<TryCtx>,
    /// enclosing active_try contexts saved when a genuinely NESTED region
    /// opens under a live one; restored when the nested block closes
    active_try_stack: Vec<TryCtx>,
    /// body_end of the most recently emitted exception-table try — the
    /// tail-return recovery in emit_return uses it to verify the stray
    /// return starts exactly at the body end (narrowed protected range)
    last_try_body_end: Option<usize>,
    /// 3.11+ with-in-try: the protected body splits around the with
    /// machinery and the Try folds at an early fragment boundary while
    /// the body's real tail (post-with `break` / pass-through jump) lies
    /// UNWALKED between the machinery and the chain head — (start, end)
    /// of that tail; the main walk folds it into the Try body on arrival
    pending_try_tail: Option<(usize, usize)>,
    /// 3.12+ shared fall-through terminator moved out of a folded Try's
    /// body: pushed to the enclosing block once the chain skip is
    /// consumed so it renders AFTER the Try
    pending_post_chain_stmt: Option<Stmt>,
    /// offset of the implicit tail `LOAD None` when the instruction tail
    /// is `RETURN; LOAD None; RETURN` — proves the source's last
    /// statement was an if/else whose arms all return, so function-tail
    /// If closes with no jump-built Else must reconstruct one ending here
    tail_pair_at: Option<usize>,
    /// try context awaiting else/finally emission
    pending_try_ctx: Option<TryCtx>,
    /// (copy start, out-of-line handler head) of an inline finally copy
    /// a mirror probe confirmed and armed into skip_until - the zone-hop
    /// re-validates against it before lowering the skip (pending_try_ctx
    /// is already consumed by then)
    fin_copy_guard: Option<(usize, usize)>,
    /// finally body of the enclosing try in a nested-chain wrap, consumed
    /// by the next emit_try_tail
    pending_nested_finally: Option<Vec<Stmt>>,
    /// inner try's clauses in a nested-chain wrap, consumed by the next
    /// emit_try_tail (which nests the region body inside an inner Try)
    /// nested-chain wrap stack (3.11+): each adjacent enclosed chain
    /// pushes its clauses; emit_try_tail wraps innermost-last outward
    nested_inner_handlers: Vec<Vec<ExceptHandler>>,
    /// pre-3.11 try awaiting its out-of-line handler chain
    legacy_try: Option<LegacyTry>,
    /// pre-3.11 except clause being collected
    legacy_handler: Option<LegacyHandler>,
    /// where the current legacy handler body ends (mismatch jump target)
    legacy_handler_end: Option<usize>,
    /// next STORE_* is the `except ... as name` binding (swallow it)
    legacy_handler_name_store: bool,
    /// next STORE_*/DELETE_* is the implicit handler-name cleanup
    legacy_handler_cleanup: bool,
    /// a swallowed implicit-cleanup STORE (`e = None`) expects the
    /// matching `del e` right after - only THAT delete is cleanup; a
    /// bare DELETE of the handler name is an explicit source `del`
    swallowed_cleanup_del: Option<String>,
    /// inside the exception-bookkeeping prelude of a legacy handler
    in_handler_prelude: bool,

    // side tables used while blocks are open
    pending_then: Vec<Vec<Stmt>>,
    pending_handlers: Vec<ExceptHandler>,
    pending_try_body: Vec<Vec<Stmt>>,
    /// statement count of the enclosing block when a deferred 3.11+ try
    /// body closed — the else region starts there; statements BEFORE the
    /// mark are pre-try code and must not be stolen as orelse
    pending_orelse_mark: Option<usize>,
    /// legacy swap-in fold: handler_start of the chain whose BODY should
    /// receive the next push_legacy_try statement (the swapped-out chain
    /// that was active while this one parsed)
    legacy_body_redirect: Option<usize>,
    /// 3.8-3.10 loop bodies that ARE a legacy try chain: the back edge
    /// precedes the out-of-line handler in layout — defer the loop close
    /// until the chain folds so the Try lands inside the loop body
    pending_loop_close_at_chain: Option<usize>,
    /// a chain Try folded at the POP_BLOCK that CREATED a new chain
    /// while the enclosing loop stays open for that new chain: the Try
    /// belongs to the new chain's body, not the enclosing block — hold
    /// it here and let push_legacy_try absorb it at the new chain's fold
    /// (code 3.10 interact: the outer try's POP_BLOCK folds the inner
    /// EOFError chain; pushing that Try into the loop body ordered it
    /// BEFORE the outer Try emitted at the back edge — rotated body)
    chain_absorb_body: Option<Vec<Stmt>>,
    /// offset of a 3.10 sunk value-return copy suppressed by
    /// sunk_value_return_mirror — an If whose then arm ends with it had
    /// its else-skip jump replaced by the sink, so the else region must
    /// be rebuilt at the If close (cProfile 3.10 main)
    sunk_return_fold_at: Option<usize>,
    /// batch-101: a 3.10 for-break sunk value-return was folded to
    /// Break — the ForElse close must lift the else arm's trailing
    /// mirror Return out to function level (copy _deepcopy_tuple)
    sunk_loop_return_lift: bool,
    /// batch-111: legacy tail-position try with the post-try return sunk
    /// into both exits — (handler mirror start, resume offset): skip the
    /// handler-side copy when the walk reaches it
    sunk_pair_drop: Option<(usize, usize)>,
    /// batch-103: a `while True:` loop whose source-level post-loop
    /// `return v` was sunk into EVERY break path ([NOP] loads RETURN
    /// copies, no physical tail return past the back edge) — the first
    /// folded copy records (loop top, value expr); the lift emits
    /// `return v` after the loop closes (codecs readline family)
    sunk_while_lift: Option<(usize, ExprRef)>,
    /// 3.12+ relocated chains: a nested region whose chain head lies
    /// past its enclosing merged region's body end defers its own
    /// emit_try_tail — the enclosing rebuild parses the nested chain
    /// and emits the nested Try (code 3.12 interact: the inner tail at
    /// its body end ran its else-span walk into the function-tail
    /// chains, rendering `if AttributeError:` garbage and skipping the
    /// outer body end so the outer tail never fired)
    nested_tail_defer: bool,
    pending_try_handlers: Vec<Vec<ExceptHandler>>,
    pending_loop: Vec<(Option<ExprRef>, Option<ExprRef>, Option<ExprRef>, Vec<Stmt>, bool)>,
    pending_with: Vec<Vec<WithItem>>,
    pending_try_orelse: Vec<Vec<Stmt>>,
    with_exits: usize,
    pending_print: Vec<(usize, ExprRef)>,
    pending_print_dest: Option<ExprRef>,
    unpack_targets: FrameTargets,
    /// per-frame store line numbers mirroring unpack_targets (the
    /// source's line-wrap positions inside a multi-line unpack target)
    unpack_target_lines: Vec<Vec<Option<u32>>>,
    /// wrap positions for the NEXT single-target Assign flush
    pending_unpack_wrap: Vec<u16>,
    awaiting_for_target: bool,
    #[allow(dead_code)]
    pending_if_stmts: Vec<Vec<Stmt>>,
    cur_offset: usize,
    cur_next: usize,
    prev_op: Option<Op>,
    prev_op_at_exec: Option<Op>,
    /// instruction offsets to skip (false-path cleanup of value merges)
    skip_until: Option<usize>,
    /// 3.8+ compiler tail-duplication: a cond jump's else path can hold
    /// a verbatim copy of a terminating body (raise/return) instead of
    /// a jump to the shared one. redirect maps the jump target to the
    /// original body start; skip lists (copy_start, copy_end) regions
    /// the walk must not enter.
    dup_copy_redirect: HashMap<usize, usize>,
    dup_copy_skip: Vec<(usize, usize)>,
    /// loop top of a loop that saw BREAK_LOOP: dead back edges after the
    /// break (<=3.7 padding) must not mark the output unclean
    broken_loop_top: Option<usize>,
    /// 3.11/3.12: the import-star intrinsic's placeholder result is
    /// discarded by the POP_TOP right after it — swallow that pop
    /// instead of emitting a stray `None` expression statement
    import_star_pop_pending: bool,
    /// cond-jump offset -> normalized target when the raw target landed
    /// on a loop back edge (3.8+ continue threading); the fused
    /// continue-chain scanner compares raw jump targets against block
    /// ends built from normalized ones
    cond_jump_redirect: std::collections::HashMap<usize, usize>,
    /// py2 `if` statement: offset of the else-branch POP_TOP absorbed by
    /// the JUMP_IF_FALSE/TRUE rewrite (it must not pop a real value)
    py2_else_pop_at: Option<usize>,
    /// 3.5: BUILD_MAP_UNPACK_WITH_CALL set the with-call flag — the next
    /// CALL_FUNCTION_KW 0 pops the merged dict as **kwargs
    pending_star_kw_call: bool,
    /// offsets of jumps recognized as a nested loop's threaded `break`
    /// (jump onto the enclosing loop's back edge)
    threaded_break_at: HashSet<usize>,
    /// loop tops whose loop already closed via their back edge: later dead
    /// back edges to the same top are padding, not `continue`
    closed_loop_tops: Vec<usize>,
    /// 3.8+ unconditional `while True` loops found by the back-edge
    /// prescan: loop top -> back-edge instruction end (loop region end)
    while_true_loops: Vec<(usize, usize)>,
    /// or-rotated while re-eval spans [start, end): cond-jump copies of
    /// a `while A or B:` tail re-evaluation whose mid-links target the
    /// next region instead of the loop exit — the walk must drop them
    /// (the final back edge still closes the loop)
    or_rot_revals: Vec<(usize, usize)>,
    /// the try being tail-emitted is a BARE try/except (no else span,
    /// no finally, no except*): only then may a legacy-shape clause's
    /// sunk post-try resume be split out of the handler body and
    /// rendered after the Try (else/finally/star tails interleave the
    /// resume with their own spans — splitting there tore b05/b15/
    /// v311_exceptstar and codeop/crypt apart)
    bare_try_parse: bool,
    /// sunk post-try continuation split out of a bare-try handler
    /// clause; emitted right after the Try statement
    handler_sunk_tail: Vec<Stmt>,
    /// skip target set by a successful try_dup_tail_ternary fold
    dup_tail_ternary_skip: Option<usize>,
    /// `except E as name` cleanup (`name = None; del name`) that follows a
    /// folded handler: the None-store is held until the matching delete
    /// confirms it (a real `x = None` statement must not be swallowed)
    pending_as_cleanup: Option<String>,
    /// except* (3.11+): post-try main flow sunk into the handler region
    /// after the PREP_RERAISE_STAR epilogue's inline POP_EXCEPT — emitted
    /// right after the Try statement
    star_tail: Vec<Stmt>,
    /// end offset of the star_tail span — the main walk skips it when the
    /// resume is laid out after the chain (3.11)
    star_tail_end: Option<usize>,
    /// last value left on the stack by the most recent decompile_region
    /// (expression spans like a split-finally's if-condition)
    region_result_expr: Option<ExprRef>,
    held_cleanup_store: Option<(ExprRef, ExprRef)>,
    /// enclosing class names for private-name (PEP 8 mangling) restoration
    class_scope: Vec<String>,
    /// PEP 709 inline comprehension state (3.12+ listcomp/setcomp/dictcomp)
    inline_comp: Option<InlineComp>,
    inline_comp_stack: Vec<InlineComp>,
    /// variables whose post-comprehension restore store must be swallowed
    pending_restore_vars: Vec<String>,
    /// ALL variables ever cleared by an inline comprehension (never
    /// consumed). A 3.12+ inline comprehension duplicates its variable
    /// restore on the normal exit (STORE; RETURN — consumed from
    /// pending_restore_vars) AND the exception cleanup (STORE; RERAISE —
    /// pending already empty). The exception copy pops from a drained
    /// stack, so a store of one of these names with an empty stack is the
    /// duplicate cleanup, not a genuine assignment (annotationlib 3.14
    /// call_annotate_function dict comp leaked `val = key = None`).
    comp_restore_vars: Vec<String>,
    cur_line: Option<u32>,
    pending_stores: Vec<(ExprRef, ExprRef)>,
    last_store_line: Option<u32>,
    /// offset where the current store group began
    group_start: usize,
    /// offset of the last statement flush (group scan window start)
    last_flush_offset: usize,
    flushing: bool,
    pending_aug: Option<(ExprRef, BinaryOp)>,
    pending_decorators: Vec<ExprRef>,
    pending_class_decorators: Vec<ExprRef>,
    pending_py2_class: Option<(ExprRef, ExprRef, ExprRef)>,
    /// collected `from ... import` names while building one statement
    import_names: Vec<(String, Option<String>)>,
    import_module: Option<(u32, String)>,
}

pub fn decompile(code: &CodeObject, version: PythonVersion) -> crate::Result<Decompiled> {
    decompile_in_scope(code, version, &[])
}

/// Decompile with an explicit enclosing-class scope stack (for private
/// name unmangling).
pub fn decompile_in_scope(
    code: &CodeObject,
    version: PythonVersion,
    class_scope: &[String],
) -> crate::Result<Decompiled> {
    let table = table_for(version)?;
    let instrs = crate::bytecode::decode_instructions(code, table, version);
    let mut idx_of = HashMap::new();
    let mut targets = HashSet::new();
    for (i, inst) in instrs.iter().enumerate() {
        idx_of.insert(inst.offset, i);
        idx_of.insert(inst.end(), i);
        if let Some(t) = inst.target {
            targets.insert(t);
        }
    }
    let mut exc_entries = code.exception_entries().to_vec();
    let raw_exc_entries = exc_entries.clone();
    // Filter out entries whose handler is pure interpreter cleanup
    // (generators, inline comprehensions, with statements): these do not
    // correspond to a source-level try/finally.
    {
        let cleanup_ops = |op: Op| {
            matches!(
                op,
                Op::SWAP
                    | Op::COPY
                    | Op::POP_TOP
                    | Op::RERAISE
                    | Op::CALL_INTRINSIC_1
                    | Op::CALL_INTRINSIC_2
                    | Op::END_ASYNC_FOR
                    | Op::CLEANUP_THROW
                    | Op::PREP_RERAISE_STAR
                    | Op::POP_EXCEPT
                    | Op::POP_BLOCK
                    | Op::NOP
                    | Op::CACHE
                    | Op::RETURN_VALUE
                    | Op::RETURN_CONST
                    | Op::LOAD_CONST
                    | Op::STORE_FAST
                    | Op::STORE_NAME
                    | Op::STORE_DEREF
            )
        };
        exc_entries.retain(|e| {
            let Some(&hi) = idx_of.get(&e.target) else {
                return true;
            };
            let mut saw_reraise = false;
            for ins in instrs.iter().skip(hi).take(14) {
                if matches!(ins.op, Op::RERAISE) {
                    saw_reraise = true;
                }
                if !cleanup_ops(ins.op) {
                    return true; // user code in handler -> real try
                }
                if ins.is_backward && ins.target.unwrap_or(0) <= e.start {
                    break;
                }
            }
            !saw_reraise
        });
    }

    // classify exception-table targets: handlers starting with PUSH_EXC_INFO
    // are out-of-line handler regions; CHECK_EXC_MATCH inside => except
    // dispatch, otherwise => finally handler.
    // target -> handler kind: true = except dispatch, false = finally.
    // `with` cleanup handlers (WITH_EXCEPT_START) are tracked separately.
    let mut handler_kind: HashMap<usize, bool> = HashMap::new();
    let mut with_regions: HashMap<usize, usize> = HashMap::new(); // body start -> end
    let mut all_handler_targets: Vec<usize> = Vec::new();
    for e in &exc_entries {
        if let Some(&hi) = idx_of.get(&e.target) {
            // anchor classification at the handler head: a 40-insn window
            // from a CLEANUP_THROW/END_ASYNC_FOR trampoline can run through
            // main flow into a LATER async-with's WITH_EXCEPT_START,
            // misclassifying the stub and dragging handler_zone forward
            // (truncating the walk). Real with-handlers always start with
            // PUSH_EXC_INFO.
            if instrs.get(hi).map(|x| x.op) != Some(Op::PUSH_EXC_INFO) {
                continue;
            }
            // bound the classification window at the chain's own
            // terminating RERAISE: a FINALLY handler's inline body copy
            // can be followed by a NESTED except dispatch whose
            // CHECK_EXC_MATCH sits inside a flat 40-insn window and
            // misclassifies the finally as an except chain
            // (_bootsubprocess 3.11 check_output: the outer try's
            // finally copy of `try: os.unlink except OSError: pass`
            // carried the nested chain's CHECK_EXC_MATCH into the
            // window - the Try rendered without its finalbody)
            let mut window: Vec<_> = Vec::new();
            for x in instrs.iter().skip(hi).take(40) {
                window.push(x);
                if x.op == Op::RERAISE {
                    break;
                }
            }
            if window.iter().any(|x| x.op == Op::WITH_EXCEPT_START) {
                with_regions.insert(e.start, e.end);
                all_handler_targets.push(e.target);
                continue;
            }
            let is_except = window
                .iter()
                .any(|x| x.op == Op::CHECK_EXC_MATCH || x.op == Op::CHECK_EG_MATCH)
                || {
                    // bare `except:` (3.11+): the handler discards the
                    // exception value right away (PUSH_EXC_INFO; POP_TOP)
                    // and never runs CHECK_EXC_MATCH. A finally handler
                    // keeps the value for its RERAISE — its head is the
                    // body copy or RERAISE itself, never a POP_TOP.
                    window
                        .iter()
                        .skip(1)
                        .find(|x| !matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE))
                        .map_or(false, |x| x.op == Op::POP_TOP)
                };
            handler_kind.insert(e.target, is_except);
            all_handler_targets.push(e.target);
        }
    }
    // handler zone: everything from the first handler target that covers
    // MAIN-FLOW code to the end is out-of-line handler code. Chains that
    // protect only handler-zone code (nested tries inside an except body)
    // must NOT define the zone — the main walk has to reach the outer
    // chain's dispatch, and nested chains are folded by the handler-body
    // sub-walks instead.
    // handler zone: everything from the first classified handler target to
    // the end of the code is out-of-line handler/cleanup code
    let handler_zone = all_handler_targets.iter().min().copied();
    // chain heads: out-of-line dispatch regions are parsed on demand (by
    // emit_try_tail / nested wraps) — the main walk skips them wherever
    // they sit, since protected bodies may FOLLOW their chain (a whole-
    // function try whose handler was laid out before the body)
    let chain_heads: std::collections::HashSet<usize> =
        all_handler_targets.iter().copied().collect();
    let mut ctx = Ctx {
        code,
        table,
        version,
        instrs,
        idx_of,
        targets,
        stack: Vec::new(),
        blocks: vec![Block::new(BlockType::Main, 0, usize::MAX)],
        clean: true,
        unpack_frames: Vec::new(),
        comp_target_store: false,
        await_mode: false,
        pending_async_with_ctx: None,
        skip_end_send: false,
        with_exit_await_drop: false,
        with_handler_starts: std::collections::HashSet::new(),
        async_for_guard: None,
        legacy_nest: Vec::new(),
        legacy_nest_depth: 0,
        py26_temps: HashMap::new(),
        completed_comp_regions: Vec::new(),
        last_py26_temp: None,
        as_cleanup_wrappers: Vec::new(),
        used_exc_info: false,
        region_collect_only: false,
        skipped_chain_landing: None,
        pending_gen_code: None,
        recent_code_const: None,
        pending_match_class: None,
        last_kw_names: Vec::new(),
        globals: Vec::new(),
        nonlocals: Vec::new(),
        exc_entries: exc_entries.clone(),
        raw_exc_entries,
        try_ctxs: HashMap::new(),
        handler_zone,
        chain_heads,
        with_regions: with_regions.clone(),
        active_try: None,
        active_try_stack: Vec::new(),
        last_try_body_end: None,
        pending_try_tail: None,
        pending_post_chain_stmt: None,
        tail_pair_at: None,
        pending_try_ctx: None,
        fin_copy_guard: None,
        pending_nested_finally: None,
        nested_inner_handlers: Vec::new(),
        legacy_try: None,
        legacy_handler: None,
        legacy_handler_end: None,
        legacy_handler_name_store: false,
        legacy_handler_cleanup: false,
        swallowed_cleanup_del: None,
        in_handler_prelude: false,
        pending_then: Vec::new(),
        pending_handlers: Vec::new(),
        pending_try_body: Vec::new(),
        pending_orelse_mark: None,
        legacy_body_redirect: None,
        pending_loop_close_at_chain: None,
        chain_absorb_body: None,
        sunk_return_fold_at: None,
        sunk_loop_return_lift: false,
        sunk_pair_drop: None,
        sunk_while_lift: None,
        nested_tail_defer: false,
        pending_try_handlers: Vec::new(),
        pending_loop: Vec::new(),
        pending_with: Vec::new(),
        pending_try_orelse: Vec::new(),
        with_exits: 0,
        pending_print: Vec::new(),
        pending_print_dest: None,
        unpack_targets: FrameTargets(Vec::new()),
        unpack_target_lines: Vec::new(),
        pending_unpack_wrap: Vec::new(),
        awaiting_for_target: false,
        pending_if_stmts: Vec::new(),
        cur_offset: 0,
        cur_next: 0,
        prev_op: None,
        prev_op_at_exec: None,
        skip_until: None,
        import_star_pop_pending: false,
        cond_jump_redirect: std::collections::HashMap::new(),
        dup_copy_redirect: HashMap::new(),
        dup_copy_skip: Vec::new(),
        broken_loop_top: None,
        py2_else_pop_at: None,
        pending_star_kw_call: false,
        threaded_break_at: HashSet::new(),
        closed_loop_tops: Vec::new(),
        while_true_loops: Vec::new(),
        or_rot_revals: Vec::new(),
        bare_try_parse: false,
        handler_sunk_tail: Vec::new(),
        dup_tail_ternary_skip: None,
        pending_as_cleanup: None,
        star_tail: Vec::new(),
        star_tail_end: None,
        region_result_expr: None,
        held_cleanup_store: None,
        class_scope: class_scope.to_vec(),
        inline_comp: None,
        inline_comp_stack: Vec::new(),
        pending_restore_vars: Vec::new(),
        comp_restore_vars: Vec::new(),
        cur_line: None,
        pending_stores: Vec::new(),
        last_store_line: None,
        group_start: 0,
        last_flush_offset: 0,
        flushing: false,
        pending_aug: None,
        pending_decorators: Vec::new(),
        pending_class_decorators: Vec::new(),
        pending_py2_class: None,
        import_names: Vec::new(),
        import_module: None,
    };

    // chained try-region grouping (3.11+): entries in the main flow, ordered
    // by start; an entry starting where the current region ends extends it
    if version.at_least(3, 11) {
        // entries inside the handler zone belong to NESTED tries living in
        // out-of-line handler bodies — the region sub-walks consult the
        // same ctx map, so include them (the main walk never reaches the
        // zone; pure-cleanup handlers were already dropped by the retain)
        let _ = handler_zone;
        // handler-exit machinery covered by an enclosing finally (the
        // clause's JUMP_BACKWARD_NO_INTERRUPT to the inline finally body,
        // zero-depth POP_EXCEPT stubs) is not a nested try — drop ranges
        // made entirely of cleanup/jump ops
        let exit_frag = |e: &crate::code::ExceptionEntry| -> bool {
            match ctx.idx_of.get(&e.start) {
                Some(&si) => {
                    let span: Vec<_> = ctx.instrs[si..]
                        .iter()
                        .take_while(|x| x.offset < e.end)
                        .collect();
                    // an empty range or a lone jump EXTENDS a region (the
                    // body-exit JUMP_FORWARD of a 3.11 try/else is covered
                    // by the finally) — not droppable machinery; anything
                    // else made purely of cleanup ops is handler exit glue
                    if span.is_empty() {
                        return false;
                    }
                    if span.len() == 1
                        && matches!(
                            span[0].op,
                            Op::JUMP_FORWARD
                                | Op::JUMP
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                    {
                        return false;
                    }
                    // a lone-NOP range is droppable padding UNLESS it is
                    // the HEAD marker of a split finally family wrapping
                    // a loop: the same handler gets a later entry whose
                    // span holds a backward jump landing at/below this
                    // marker (the wrapped loop's back edge). Dropping the
                    // head orphans the tail fragment into a phantom
                    // region whose body is the bare back edge (code 3.13
                    // interact: [594,596)->1340 head + [748,752)->1340
                    // back edge sandwich the KI body region; the orphan
                    // rendered `try: continue finally: <copy>` INSIDE
                    // the loop and the loop escaped the try/finally)
                    if span.len() == 1 && span[0].op == Op::NOP {
                        let wraps_loop = exc_entries.iter().any(|e2| {
                            e2.target == e.target
                                && e2.start > e.end
                                && ctx
                                    .idx_of
                                    .get(&e2.start)
                                    .map_or(false, |&si2| {
                                        ctx.instrs[si2..]
                                            .iter()
                                            .take_while(|x| x.offset < e2.end)
                                            .any(|x| {
                                                x.is_backward
                                                    && matches!(
                                                        x.op,
                                                        Op::JUMP_BACKWARD
                                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                            | Op::JUMP_ABSOLUTE
                                                            | Op::JUMP
                                                    )
                                                    && x.target
                                                        .map_or(false, |t| {
                                                            t <= e.start + 2
                                                        })
                                            })
                                    })
                        });
                        if wraps_loop {
                            return false;
                        }
                    }
                    span.iter().all(|x| {
                        matches!(
                            x.op,
                            Op::JUMP_BACKWARD_NO_INTERRUPT
                                | Op::COPY
                                | Op::SWAP
                                | Op::POP_EXCEPT
                                | Op::POP_TOP
                                | Op::RERAISE
                                | Op::NOP
                                | Op::NOT_TAKEN
                                // an await protocol resume trampoline:
                                // CLEANUP_THROW + the backward resume
                                // hop is continuation glue for the
                                // statement that owns the await - its
                                // entry must not donate a (reused)
                                // handler to whatever region it abuts
                                // (contextlib 3.12-3.14 __aexit__: the
                                // tail try/finally's trampoline entry
                                // mapped to the FIRST branch's
                                // StopAsyncIteration clause and the
                                // tail grew a phantom
                                // `except StopAsyncIteration: return
                                // False`)
                                | Op::CLEANUP_THROW
                        )
                    })
                }
                None => false,
            }
        };
        let mut main_entries: Vec<_> = exc_entries
            .iter()
            .filter(|e| handler_kind.contains_key(&e.target))
            .filter(|e| !exit_frag(e))
            .collect();
        main_entries.sort_by_key(|e| e.start);
        let mut regions: Vec<TryCtx> = Vec::new();
        // 3.12+ resume protocols split a protected range in two: the
        // YIELD_VALUE suspension point is covered by an entry targeting a
        // CLEANUP_THROW trampoline (dropped from classification), so the
        // two halves of ONE source-level try arrive as separate entries
        // with the same handler — bridge the protocol-only gap instead of
        // opening a duplicate try
        let protocol_only = |from: usize, to: usize| -> bool {
            match (ctx.idx_of.get(&from), ctx.idx_of.get(&to)) {
                (Some(&fi), Some(&ti)) => ctx.instrs[fi..ti].iter().all(|x| {
                    matches!(
                        x.op,
                        Op::YIELD_VALUE
                            | Op::RESUME
                            | Op::RESUME_CHECK
                            | Op::SEND
                            | Op::END_SEND
                            | Op::CLEANUP_THROW
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                            | Op::LOAD_CONST
                            | Op::NOP
                            | Op::NOT_TAKEN
                    )
                }),
                _ => false,
            }
        };
        // compiler padding between protected fragments (the 3.11 NOP
        // line markers between statements) does not break a tiled span
        let is_pad_gap = |from: usize, to: usize| -> bool {
            if from > to {
                return false;
            }
            match (ctx.idx_of.get(&from), ctx.idx_of.get(&to)) {
                (Some(&fi), Some(&ti)) => ctx.instrs[fi..ti]
                    .iter()
                    .all(|x| matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)),
                _ => false,
            }
        };
        // terminating-arm gap: 3.11+ excludes a trailing bare RETURN
        // from the protected range, splitting one source-level try into
        // same-handler fragments around it (`try: if A: ...; return x
        // else: return y except KI:` - the if arm's `return success`
        // sits unprotected between the fragments). Pads + bare returns
        // only: the fragments are still ONE try (compileall 3.11 main:
        // the unmerged else fragment grew a duplicate try with its own
        // KeyboardInterrupt clause)
        let is_term_gap = |from: usize, to: usize| -> bool {
            if from > to {
                return false;
            }
            match (ctx.idx_of.get(&from), ctx.idx_of.get(&to)) {
                (Some(&fi), Some(&ti)) => {
                    let span = &ctx.instrs[fi..ti];
                    span.iter().any(|x| {
                        matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST)
                    }) && span.iter().all(|x| {
                        matches!(
                            x.op,
                            Op::NOP | Op::NOT_TAKEN
                                | Op::CACHE
                                | Op::RETURN_VALUE
                                | Op::RETURN_CONST
                        )
                    })
                }
                _ => false,
            }
        };
        // with-in-try: a `with` inside the try body splits the protected
        // range around BEFORE_WITH / the with body (protected by the
        // with's OWN handler, excluded from main_entries) / the __exit__
        // call. Bridge same-handler fragments when the gap is entirely
        // with-protocol material and actually contains with machinery
        // (_bootsubprocess 3.11 check_output: the FileNotFoundError try's
        // fragments [360,390)/[434,456) never merged and its chain was
        // left unparsed — the with rendered bare)
        let with_bridge = |from: usize, to: usize| -> bool {
            match (ctx.idx_of.get(&from), ctx.idx_of.get(&to)) {
                (Some(&fi), Some(&ti)) => {
                    let span = &ctx.instrs[fi..ti];
                    // with machinery marker: the entry protocol
                    // (BEFORE_WITH) or the out-of-line cleanup
                    // (WITH_EXCEPT_START 3.11-3.13 / LOAD_SPECIAL
                    // __exit__ 3.14) — cgitb 3.11 handle: the same-
                    // handler fragments [690,800)/[816,832) sandwich
                    // the with CLEANUP span, not the entry protocol
                    let has_with = span.iter().any(|x| {
                        matches!(
                            x.op,
                            Op::BEFORE_WITH
                                | Op::BEFORE_ASYNC_WITH
                                | Op::WITH_EXCEPT_START
                                | Op::LOAD_SPECIAL
                        ) || with_regions.iter().any(|(ws, we)| {
                                x.offset >= *ws && x.offset < *we
                            })
                    });
                    has_with
                        && span.iter().all(|x| {
                            matches!(
                                x.op,
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE
                            ) || with_regions.iter().any(|(ws, we)| {
                                x.offset >= *ws && x.offset < *we
                            }) || matches!(
                                x.op,
                                Op::BEFORE_WITH
                                    | Op::BEFORE_ASYNC_WITH
                                    | Op::STORE_FAST
                                    | Op::STORE_NAME
                                    | Op::STORE_DEREF
                                    | Op::POP_TOP
                                    | Op::SWAP
                                    | Op::COPY
                                    | Op::LOAD_CONST
                                    // out-of-line with cleanup span
                                    | Op::PUSH_EXC_INFO
                                    | Op::WITH_EXCEPT_START
                                    | Op::LOAD_SPECIAL
                                    | Op::POP_EXCEPT
                                    | Op::RERAISE
                                    | Op::POP_JUMP_IF_TRUE
                                    | Op::POP_JUMP_IF_FALSE
                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                    | Op::LOAD_FAST
                                    | Op::LOAD_FAST_BORROW
                            )
                        })
                }
                _ => false,
            }
        };
        // region extension must never swallow a LATER entry's protected
        // range (overlapping region nesting breaks the tail order)
        let mut all_starts: Vec<usize> = main_entries.iter().map(|e2| e2.start).collect();
        all_starts.sort_unstable();
        // note: `all_starts` must EXCLUDE the candidate entry's own start
        // — a fragmented region's next fragment legitimately starts past
        // cover_end, and counting it as an intervening sibling caps every
        // bridged merge (the cap's intent is a THIRD entry's protected
        // range starting strictly between the region end and the
        // candidate's end)
        let other_start_after_ex =
            |r: &TryCtx, e: &crate::code::ExceptionEntry| -> Option<usize> {
                all_starts
                    .iter()
                    .copied()
                    .find(|s| *s > r.cover_end() && *s != e.start)
            };
        for e in &main_entries {
            let is_exc = handler_kind[&e.target];
            let same_fin = |r: &TryCtx| r.finally_handler == Some(e.target);
            let same_exc = |r: &TryCtx| r.except_handler == Some(e.target);
            let mut bridged = false;
            let mut bridged2 = false;
            // 1) contiguous / protocol-bridged extension of the LAST
            //    region (historical semantics, capped so a later entry's
            //    protected range is never swallowed)
            let extends = regions
                .last()
                .map(|r| {
                    let same_handler0 = if is_exc { same_exc(r) } else { same_fin(r) };
                    // the cap guards against swallowing a LATER sibling's
                    // protected range; when the region's own handler gets
                    // another fragment at/after this entry, the
                    // intervening starts are nested chains inside the
                    // body and the merge stays ordered
                    // (_bootsubprocess 3.11 check_output: the outer
                    // finally's fragments sandwich the inner with-try,
                    // and the with-try's own second fragment trips the
                    // naive cap)
                    let resumes_past = same_handler0
                        && main_entries.iter().any(|e3| {
                            (if is_exc {
                                r.except_handler == Some(e3.target)
                            } else {
                                r.finally_handler == Some(e3.target)
                            }) && e3.start >= e.end
                        });
                    let capped = other_start_after_ex(r, e)
                        .map_or(false, |s| e.end > s && !resumes_past);
                    if capped {
                        return false;
                    }
                    if r.cover_end() == e.start {
                        if same_handler0 {
                            return true;
                        }
                        // a contiguous entry with a DIFFERENT handler may
                        // be the next fragment of an EARLIER region's
                        // split family — but ONLY when the gap between
                        // that region and this entry tiles exactly with
                        // the nested regions in between (code 3.11
                        // interact: the outer KI fragment [492,534)->612
                        // abuts the inner EOF region end 492, and the
                        // outer fragment [394,446) plus the inner region
                        // tile the gap). Otherwise keep the historical
                        // extension: a break-exit split's second
                        // fragment abuts its own region's end with the
                        // inlined exit path in between and must NOT be
                        // body-merged (_sitebuiltins 3.12 Quitter: the
                        // try/with/break collapsed to `pass` under the
                        // wide form)
                        let family = regions.iter().rposition(|r2| {
                            (if is_exc {
                                r2.except_handler == Some(e.target)
                            } else {
                                r2.finally_handler == Some(e.target)
                            }) && r2.region_end <= e.start
                        });
                        let split_family = family.map_or(false, |fi| {
                            let mut cur = regions[fi].region_end;
                            if cur >= e.start {
                                return false;
                            }
                            for r2 in &regions[fi + 1..] {
                                if r2.start != cur && !is_pad_gap(cur, r2.start)
                                {
                                    return false;
                                }
                                if r2.region_end > e.start {
                                    return false;
                                }
                                cur = r2.region_end;
                            }
                            cur == e.start
                                || (cur < e.start && is_pad_gap(cur, e.start))
                        });
                        return !split_family;
                    }
                    let same_handler = if is_exc { same_exc(r) } else { same_fin(r) };
                    let b = same_handler
                        && e.start > r.cover_end()
                        && (protocol_only(r.cover_end(), e.start)
                            || with_bridge(r.cover_end(), e.start));
                    if b {
                        bridged = true;
                    }
                    b
                })
                .unwrap_or(false);
            // 2) deep search for the FINALLY family: the same-handler
            //    region may sit BELOW nested except-chain regions (a
            //    nested try/except inside a try/finally body —
            //    _bootsubprocess 3.11 check_output: the outer finally's
            //    fragments [232,356)/[480,480)/[506,516) sandwich the
            //    inner with-try's regions). Never cross another finally
            //    region (nested finally fragments must stay separate —
            //    b15/b18/b22/exceptstar/asyncgen duplicate finally
            //    bodies when merged).
            let mut deep_idx: Option<usize> = None;
            if !extends && !is_exc {
                let mut cand: Option<usize> = None;
                for (ri, r) in regions.iter().enumerate().rev() {
                    if same_fin(r) {
                        cand = Some(ri);
                        break;
                    }
                    if r.finally_handler.is_some() {
                        break;
                    }
                    if r.start < e.start && r.region_end <= e.start {
                        continue;
                    }
                    break;
                }
                if let Some(ri) = cand {
                    // the span [regions[ri].end, e.start) must tile with
                    // entries of OTHER handlers (nested chains that are
                    // part of this body); compiler padding gaps are fine
                    let mut cur = regions[ri].region_end;
                    let mut any = false;
                    let mut ok = cur < e.start;
                    while ok && cur < e.start {
                        let nxt = ctx.exc_entries.iter().find(|x| {
                            x.start >= cur && x.end <= e.start
                        });
                        match nxt {
                            Some(e2) => {
                                if e2.target == e.target {
                                    ok = false;
                                } else if e2.start != cur && !is_pad_gap(cur, e2.start) {
                                    ok = false;
                                } else {
                                    cur = e2.end;
                                    any = true;
                                }
                            }
                            None => ok = false,
                        }
                    }
                    if ok && any && cur < e.start && is_pad_gap(cur, e.start) {
                        cur = e.start;
                    }
                    if ok && any && cur == e.start {
                        deep_idx = Some(ri);
                        bridged2 = true;
                    }
                }
            }
            // same-handler forward extension: an earlier except region
            // whose handler gets ANOTHER fragment past nested regions —
            // the fragments belong to one source-level try split by the
            // nesting (code 3.11 interact: [394,446) and [492,534) both
            // -> 612, sandwiching the inner EOFError region). The
            // `resumes_past` cap on the contiguous path already proves
            // the family continues; extend the body across the nested
            // region (it stays its own TryCtx and the walk nests it)
            let mut deep_exc_idx: Option<usize> = None;
            if !extends && !bridged && is_exc {
                if let Some(ri) = regions.iter().enumerate().rev().find(|(_, r)| {
                    same_exc(r) && r.start < e.start && e.start >= r.region_end
                }).map(|(ri, _)| ri) {
                    // the gap must tile exactly with the intervening
                    // regions (nested tries inside the body) — an
                    // untiled gap is a break-exit or protocol split,
                    // not a nesting split
                    let mut cur = regions[ri].region_end;
                    let mut ok = cur < e.start;
                    for r2 in &regions[ri + 1..] {
                        if !ok {
                            break;
                        }
                        if r2.start != cur && !is_pad_gap(cur, r2.start) {
                            ok = false;
                            break;
                        }
                        if r2.region_end > e.start {
                            ok = false;
                            break;
                        }
                        cur = r2.region_end;
                    }
                    if ok
                        && (cur == e.start
                            || (cur < e.start
                                && (is_pad_gap(cur, e.start)
                                    || is_term_gap(cur, e.start))))
                    {
                        deep_exc_idx = Some(ri);
                    }
                }
            }
            // same-handler forward extension, FINALLY variant: an
            // outer try/finally wrapping a loop lays its protected
            // range as fragments AROUND the loop body's own chain
            // regions (code 3.13 interact: [594,596)->1340 loop-head
            // marker + [748,752)->1340 back edge, sandwiching the
            // KI/EOF body region [598,748)->930). Unmerged, the tail
            // fragment becomes a phantom region whose "body" is the
            // bare back edge - rendered inside the loop as
            // `try: continue finally: <copy>` with the real loop body
            // stranded outside any try. Same tiling discipline as the
            // except variant: the gap must tile exactly with the
            // intervening nested regions.
            let mut deep_fin_idx: Option<usize> = None;
            if !extends && !bridged && !is_exc {
                if let Some(ri) = regions.iter().enumerate().rev().find(|(_, r)| {
                    same_fin(r) && r.start < e.start && e.start >= r.region_end
                }).map(|(ri, _)| ri) {
                    let mut cur = regions[ri].region_end;
                    let mut ok = cur < e.start;
                    for r2 in &regions[ri + 1..] {
                        if !ok {
                            break;
                        }
                        if r2.start != cur && !is_pad_gap(cur, r2.start) {
                            ok = false;
                            break;
                        }
                        if r2.region_end > e.start {
                            ok = false;
                            break;
                        }
                        cur = r2.region_end;
                    }
                    if ok
                        && (cur == e.start
                            || (cur < e.start
                                && (is_pad_gap(cur, e.start)
                                    || is_term_gap(cur, e.start))))
                    {
                        deep_fin_idx = Some(ri);
                    }
                }
            }
            if let Some(ri) = deep_exc_idx {
                let e2 = e.end.max(e.start);
                regions[ri].body_end = regions[ri].body_end.max(e2);
                regions[ri].region_end = regions[ri].region_end.max(e2);
            } else if let Some(ri) = deep_fin_idx {
                let e2 = e.end.max(e.start);
                regions[ri].body_end = regions[ri].body_end.max(e2);
                regions[ri].region_end = regions[ri].region_end.max(e2);
            } else if extends {
                let r = regions.last_mut().unwrap();
                if is_exc {
                    r.except_handler.get_or_insert(e.target);
                    if bridged {
                        // the protocol gap is part of the try body (the
                        // await statement finishes after the suspension
                        // point) — extend the body, not an else region
                        r.body_end = e.end;
                        r.region_end = e.end;
                    }
                } else {
                    r.finally_handler.get_or_insert(e.target);
                    r.region_end = e.end;
                }
            } else if let Some(ri) = deep_idx {
                let r = &mut regions[ri];
                r.finally_handler.get_or_insert(e.target);
                r.body_end = e.end;
                r.region_end = e.end;
            } else {
                let mut r = TryCtx {
                    start: e.start,
                    body_end: e.end,
                    region_end: e.end,
                    except_handler: None,
                    finally_handler: None,
                    split_body2: None,
                };
                if is_exc {
                    r.except_handler = Some(e.target);
                } else {
                    r.finally_handler = Some(e.target);
                }
                regions.push(r);
            }
        }
        // nested try/except inside a try/finally body: a middle fragment
        // of the finally region carries its OWN except handler and forms
        // a separate region — merge it back so the finally region's body
        // spans the nested try (its statements fold into the body and the
        // inline finally decomposes at the true body end, not at the
        // first fragment's edge: _bootsubprocess 3.11 check_output)
        {
            let mut i = 0;
            while i + 1 < regions.len() {
                let merge = {
                    let (r1, r2) = (&regions[i], &regions[i + 1]);
                    r1.finally_handler.is_some()
                        && r1.except_handler.is_none()
                        && r2.finally_handler == r1.finally_handler
                        && r2.except_handler.is_some()
                        && r2.start >= r1.region_end
                };
                if merge {
                    let e2 = regions[i + 1].body_end.max(regions[i + 1].region_end);
                    let eh = regions[i + 1].except_handler;
                    regions[i].except_handler = eh;
                    regions[i].body_end = regions[i].body_end.max(e2);
                    regions[i].region_end = regions[i].region_end.max(e2);
                    regions.remove(i + 1);
                } else {
                    i += 1;
                }
            }
        }
        // 3.12+ split finally (break-in-try): two finally-only fragments
        // sharing one handler, the first ending at an exit-jump gap —
        // merge them into ONE region so the walk never enters the gap
        {
            let mut i = 0;
            while i + 1 < regions.len() {
                let paired = {
                    let (r1, r2) = (&regions[i], &regions[i + 1]);
                    if r1.except_handler.is_none()
                        && r1.finally_handler.is_some()
                        && r1.finally_handler == r2.finally_handler
                        && r2.start > r1.region_end
                    {
                        match ctx.idx_of.get(&r1.region_end) {
                            Some(&gi) => {
                                let exit = ctx.instrs[gi..]
                                    .iter()
                                    .take(40)
                                    .find(|x| {
                                        matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                            && x.target.map_or(false, |t| t > x.offset)
                                    });
                                match exit {
                                    Some(x) => {
                                        let next_off = ctx
                                            .instrs
                                            .iter()
                                            .find(|y| y.offset > x.offset)
                                            .map(|y| y.offset);
                                        next_off == Some(r2.start)
                                    }
                                    None => false,
                                }
                            }
                            None => false,
                        }
                    } else {
                        false
                    }
                };
                if paired {
                    let b2 = (regions[i + 1].start, regions[i + 1].body_end);
                    regions[i].split_body2 = Some(b2);
                    regions.remove(i + 1);
                } else {
                    i += 1;
                }
            }
        }
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            for r in &regions {
                eprintln!(
                    "EG region start={} body_end={} region_end={} exc={:?} fin={:?} split={:?}",
                    r.start, r.body_end, r.region_end, r.except_handler, r.finally_handler, r.split_body2
                );
            }
        }
        // dedupe: keep regions with at least a body
        for r in regions {
            ctx.try_ctxs.insert(r.start, r);
        }
    }

    ctx.tail_pair_at = tail_pair_load_offset(code, &ctx.instrs, version);
    ctx.run();

    // a legacy try whose emission stayed deferred for the else region:
    // the walk can end (function-tail return inside the else region)
    // before the emission point — flush it now
    while !ctx.legacy_nest.is_empty() {
        ctx.close_legacy_region_arms();
        // fold a nested handler still open at walk end (terminating return)
        if let Some(h) = ctx.legacy_handler.take() {
            if let Some(lt) = ctx.legacy_try.as_mut() {
                lt.handlers.push(crate::ast::ExceptHandler {
                    type_: h.type_,
                    name: h.name,
                    body: h.body,
                    is_star: false,
                });
            }
        }
        let nested = ctx.legacy_try.take();
        ctx.restore_legacy_nest();
        if let Some(l) = nested {
            // finally-only chains count too: a nested try/finally inside
            // an outer finally body (bz2 3.10 close) ends the walk with
            // the OUTER chain still stashed — dropping it lost the whole
            // structure
            if !l.handlers.is_empty() || l.has_finally {
                let mut orelse = l.orelse;
                if matches!(orelse.last(), Some(Stmt::Return(None))) {
                    orelse.pop();
                }
                let mut finalbody = l.finalbody;
                if matches!(finalbody.last(), Some(Stmt::Return(None))) {
                    finalbody.pop();
                }
                ctx.push_stmt(Stmt::Try {
                    body: l.body,
                    handlers: l.handlers,
                    orelse,
                    finalbody,
                });
            }
        }
        // the restored outer handler was open when the nest began: if the
        // walk ended before its chain closed, fold it now
        if let Some(h) = ctx.legacy_handler.take() {
            if let Some(lt) = ctx.legacy_try.as_mut() {
                lt.handlers.push(crate::ast::ExceptHandler {
                    type_: h.type_,
                    name: h.name,
                    body: h.body,
                    is_star: false,
                });
            }
        }
    }
    if ctx.used_exc_info {
        let has_sys = ctx.blocks.first().map_or(false, |b| {
            b.stmts.iter().any(|st| match st {
                Stmt::Import { names } => names.iter().any(|(m, _)| m == "sys"),
                _ => false,
            })
        });
        if !has_sys {
            if let Some(root) = ctx.blocks.first_mut() {
                root.stmts.insert(0, Stmt::Import { names: vec![("sys".to_string(), None)] });
            }
        }
    }
    // a handler still open at walk end (its chain never reached the
    // fold point — the body-end jump of a nested try flew over the
    // whole tail): fold it into its chain before the final flush
    // (audiodev 2.7 AudioDev: handler1 of the outer chain)
    if let Some(h) = ctx.legacy_handler.take() {
        if let Some(lt) = ctx.legacy_try.as_mut() {
            lt.handlers.push(crate::ast::ExceptHandler {
                type_: h.type_,
                name: h.name,
                body: h.body,
                is_star: false,
            });
        }
    }
    ctx.close_legacy_region_arms();
    if let Some(l) = ctx.legacy_try.take() {
        if !l.handlers.is_empty() || l.has_finally {
            let mut orelse = l.orelse;
            let mut finalbody = l.finalbody;
            // the implicit function epilogue `return None` is not an
            // else/finally clause
            if matches!(orelse.last(), Some(Stmt::Return(None))) {
                orelse.pop();
            }
            if matches!(finalbody.last(), Some(Stmt::Return(None))) {
                finalbody.pop();
            }
            ctx.flush_pending_stores();
            let try_stmt = Stmt::Try {
                body: l.body,
                handlers: l.handlers,
                orelse,
                finalbody,
            };
            // statements the walk pushed after the chain (the function
            // epilogue / trailing returns) chronologically FOLLOW the try
            // — insert it before them
            let top = ctx.blocks.last_mut().unwrap();
            let mut at = top.stmts.len();
            while at > 0 && matches!(top.stmts[at - 1], Stmt::Return(_)) {
                at -= 1;
            }
            top.stmts.insert(at, try_stmt);
        }
    }

    // Fold any blocks still open at EOF into statements.
    // a function-tail `return v` trapped in an unclosed folded-chain
    // region: the chain has no collecting back edge (every arm
    // terminates), so the EOF fold would seal the return inside the
    // last arm — record it for relocation to function level after the
    // assembly (ast 3.6 NodeTransformer.generic_visit `return node`)
    let trapped_tail_return = {
        let trapped = match ctx.blocks.last() {
            Some(b) if !matches!(b.kind, BlockType::Main) && b.end == usize::MAX => {
                match b.stmts.last() {
                    Some(Stmt::Return(v)) => Some(Stmt::Return(v.clone())),
                    _ => None,
                }
            }
            _ => None,
        };
        trapped
    };
    while ctx.blocks.len() > 1 {
        let pos = ctx.instrs.last().map(|i| i.end()).unwrap_or(0);
        // an open chained-comparison link at EOF: its else arm (the last
        // real execution path) yields the link's own condition value
        if let Some(top) = ctx.blocks.last() {
            if top.chain_link && top.stmts.is_empty() {
                if let Some(c) = top.cond.clone() {
                    ctx.blocks.pop();
                    ctx.push(c);
                    continue;
                }
            }
        }
        ctx.force_close_top(pos);
    }
    ctx.flush_stack();

    let mut root = ctx.blocks.remove(0);
    let mut body = std::mem::take(&mut root.stmts);

    // relocate the trapped tail return: pop it from wherever the EOF
    // fold sealed it (possibly nested through folded If/Else arms) and
    // re-append at function level. Only value returns are relocated — a
    // bare trailing `return None` stays where it is (postprocess strips
    // it, and relocating would expose it as a sibling of a loop that
    // lexically encloses it, 'return outside loop').
    if let Some(Stmt::Return(Some(_))) = trapped_tail_return {
        fn pop_trailing_return(stmts: &mut Vec<Stmt>) -> Option<Stmt> {
            match stmts.last_mut() {
                Some(Stmt::Return(Some(_))) => stmts.pop(),
                Some(Stmt::If { orelse, .. }) if !orelse.is_empty() => {
                    pop_trailing_return(orelse)
                }
                Some(Stmt::If { body, .. }) if !body.is_empty() => {
                    pop_trailing_return(body)
                }
                Some(Stmt::While { orelse, .. }) if !orelse.is_empty() => {
                    pop_trailing_return(orelse)
                }
                Some(Stmt::While { body, .. }) if !body.is_empty() => {
                    pop_trailing_return(body)
                }
                Some(Stmt::For { orelse, .. }) if !orelse.is_empty() => {
                    pop_trailing_return(orelse)
                }
                Some(Stmt::For { body, .. }) if !body.is_empty() => {
                    pop_trailing_return(body)
                }
                _ => None,
            }
        }
        if pop_trailing_return(&mut body).is_some() {
            if let Some(ret) = trapped_tail_return {
                body.push(ret);
            }
        }
    }

    // `global`/`nonlocal` declarations first (only meaningful in functions)
    if code.name != "<module>" {
        if !ctx.globals.is_empty() {
            body.insert(0, Stmt::Global(std::mem::take(&mut ctx.globals)));
        }
        if !ctx.nonlocals.is_empty() {
            body.insert(0, Stmt::Nonlocal(std::mem::take(&mut ctx.nonlocals)));
        }
    }

    let tail_pair = bytecode_tail_return_pair(code, &ctx.instrs, version);
    let mut body = postprocess_body(body, code);
    // `from __future__ import annotations` leaves NO bytecode — only the
    // CO_FUTURE_ANNOTATIONS flag. Re-emit it at the module head (after a
    // leading docstring) so the annotations we rendered as raw source
    // text recompile to the stored string forms (_colorize 3.13)
    if code.name == "<module>"
        && code.flags & crate::code::CO_FUTURE_ANNOTATIONS != 0
        && !body.iter().any(|st| {
            matches!(st, Stmt::ImportFrom { module, .. } if module == "__future__")
        })
    {
        let at = match body.first() {
            Some(Stmt::Expr(e))
                if matches!(&**e, Expr::Const(o) if matches!(&**o, PyObject::Str(_))) =>
            {
                1
            }
            _ => 0,
        };
        body.insert(
            at,
            Stmt::ImportFrom {
                module: "__future__".to_string(),
                level: 0,
                names: vec![("annotations".to_string(), None)],
            },
        );
    }
    Ok(Decompiled {
        body,
        clean: ctx.clean,
        tail_pair,
    })
}

impl<'a> Ctx<'a> {
    fn run(&mut self) {
        self.pending_try_tail = None;
        self.pending_post_chain_stmt = None;
        self.active_try_stack.clear();
        self.prescan_while_true();
        self.prescan_dup_copies();
        let mut pc = 0usize;
        let mut past_chains = false;
        while pc < self.instrs.len() {
            let inst = self.instrs[pc];
            let pos = inst.offset;
            // tail-duplicated body copy: never walk into it (the jump
            // that targeted it was redirected to the original)
            if let Some(&(s, e)) = self.dup_copy_skip.iter().find(|&&(s, _)| s == pos) {
                if let Some(&ei) = self.idx_of.get(&e) {
                    pc = ei;
                    continue;
                }
                if e >= self.instrs.last().map_or(0, |x| x.end()) {
                    break;
                }
            }
            // batch-111: skip the handler-side sunk copy of a tail
            // try's post-try return (the function-level return renders
            // from the success-side copy)
            if let Some((ds, de)) = self.sunk_pair_drop {
                if pos == ds {
                    self.sunk_pair_drop = None;
                    self.skip_until = Some(de);
                    pc += 1;
                    continue;
                }
            }
            if self.chain_heads.contains(&pos) && inst.op == Op::PUSH_EXC_INFO {
                // out-of-line handler chain head: fold any Try block
                // ending here FIRST (its tail parses the chain), then
                // skip the whole chain region — the walk resumes after
                // it (protected body continuation, another chain, or
                // sunk post-try main flow)
                let mut after = self.chain_extent(pos);
                // 3.11 star chains exit through a JUMP_FORWARD trampoline
                // laid out after the dead stubs — skip over outward
                // trampolines so the walk resumes at the real flow
                loop {
                    let tramp = self
                        .idx_of
                        .get(&after)
                        .and_then(|&ti| self.instrs.get(ti))
                        .map(|x| {
                            matches!(x.op, Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::NOT_TAKEN)
                                && x.target.map_or(false, |t| t > x.offset)
                        })
                        .unwrap_or(false);
                    if !tramp {
                        break;
                    }
                    let ti = self.idx_of[&after];
                    let t = self.instrs[ti].target.unwrap();
                    if t <= after {
                        break;
                    }
                    // a forward jump PRECEDED BY an uncovered POP_TOP is
                    // a `break` (the POP_TOP drops the loop iterator):
                    // the tail of a protected body lying between the
                    // chain's dead stubs and the next chain head —
                    // hopping it strands the POP_TOP inside the skip and
                    // the break is lost (_sitebuiltins 3.11 __setup:
                    // `try: with ...; break` rendered without the break,
                    // the handler's loop back edge flipping FOR_ITER's
                    // exit). A COVERED POP_TOP is with-machinery cleanup
                    // (_bootsubprocess 3.11 check_output: the inner
                    // with-chain's exit stubs feed the enclosing
                    // finally's chain head through exactly this
                    // trampoline) — hop it.
                // a forward jump PRECEDED BY an uncovered POP_TOP is
                // a `break` (the POP_TOP drops the loop iterator): the
                // tail of a protected body between the chain's machinery
                // and the resume point — hopping it strands the POP_TOP
                // inside the skip and the break is lost (_sitebuiltins
                // 3.11 __setup: `try: with ...; break` rendered without
                // the break). Require the POP_TOP to be the chain's LAST
                // consumed instruction (the extent already swallowed it):
                // an interior POP_TOP followed by live resume flow is
                // with-machinery cleanup (_bootsubprocess 3.11
                // check_output hops the inner chain's exit trampoline
                // into the enclosing finally's flow).
                if ti > 0
                    && self.instrs[ti - 1].op == Op::POP_TOP
                    && self.instrs[ti - 1].end() == after
                    && !self.exc_entries.iter().any(|e| {
                        e.start <= self.instrs[ti - 1].offset
                            && self.instrs[ti - 1].offset < e.end
                    })
                {
                    break;
                }
                after = t;
                }
                // a try whose tail was deferred (3.11 star: the else
                // region extends past the chain head) folds at its
                // region_end. When the chain skip carries the walk past
                // that point, retarget the tail to the resume offset —
                // the inline-finally/else spans start there.
                let defer_tail = self
                    .pending_try_ctx
                    .as_ref()
                    .map_or(false, |tc| tc.region_end == pos);
                if defer_tail {
                    // the resume offset is where the epilogue's exit
                    // trampoline lands (after POP_EXCEPT). chain_extent
                    // may stop short at a body-stop (the protected
                    // else/finally flow that FOLLOWS the chain) — find
                    // the epilogue JUMP_FORWARD and use its target.
                    let resume = self
                        .idx_of
                        .get(&pos)
                        .and_then(|&hi| {
                            let win: Vec<_> = self.instrs[hi..].iter().take(70).collect();
                            // the epilogue marker first — clause-internal
                            // JUMP_FORWARDs (cleanup hops) come before it
                            let prep = win.iter().position(|x| {
                                x.op == Op::PREP_RERAISE_STAR
                                    || (x.op == Op::CALL_INTRINSIC_2 && x.arg == 1)
                            })?;
                            win[prep..]
                                .iter()
                                .find(|x| {
                                    matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                        && x.target.map_or(false, |t| t > x.offset)
                                })
                                .and_then(|x| x.target)
                        })
                        .filter(|t| *t > after)
                        .unwrap_or(after);
                    if resume > pos {
                        if let Some(tc) = self.pending_try_ctx.as_mut() {
                            tc.region_end = resume;
                        }
                        after = resume;
                    }
                } else {
                    self.close_blocks_at(pos);
                }
                // an emit that already folded the region may have armed
                // a LONGER skip (past the chain AND the inline finally
                // copy that follows it) - lowering to the chain extent
                // re-walks the copy at function level (code 3.13
                // interact: the finally emit armed 1340 = the out-of-line
                // handler head, the zone hop lowered it to the KI chain's
                // extent 1140 and the restore/exitmsg copy rendered
                // twice). Keep it ONLY for a mirror-validated copy span:
                // the hop lands before the recorded copy start
                // (intermediate chain extents keep transitively) or at/
                // inside it with the span mirroring the out-of-line
                // chain. Any other longer skip lowers as before - a
                // blanket keep stranded real mainline flow (cmd 3.11
                // do_help lost the nohelp write). A shorter or absent
                // skip always raises to the resume point (b05_exceptions
                // / v33_yieldfrom need the raise when an earlier emit
                // left a stale lower skip).
                match self.skip_until {
                    Some(sk) if sk > after => {
                        let copy_span = self
                            .fin_copy_guard
                            .map_or(false, |(cs, fh)| {
                                fh == sk
                                    && (after < cs
                                        || (after >= cs
                                            && self.finally_copy_mirror(
                                                after, fh,
                                            )))
                            });
                        if !copy_span {
                            self.skip_until = Some(after);
                        }
                    }
                    _ => self.skip_until = Some(after),
                }
                past_chains = true;
            } else if let Some(zone) = self.handler_zone {
                // a protected body may legitimately START inside the zone
                // (its handler chain was laid out before it) — the main
                // walk must open the try there instead of breaking
                if pos >= zone && !past_chains && !self.try_ctxs.contains_key(&pos) {
                    break;
                }
            }
            // a folded 3.11+ try's un-walked body tail (with-split
            // protected region): walk it now and attach it to the Try's
            // body — statements pushed after the fold would land in the
            // enclosing block, rendering the tail outside the try
            if let Some((ts, te)) = self.pending_try_tail {
                if pos == ts {
                    self.pending_try_tail = None;
                    // `break` tail: the region sub-walk swaps the block
                    // stack and cannot see the loop — rebuild the Break
                    // while the live blocks are still on the stack
                    let mut cut = if te == 0 { usize::MAX } else { te };
                    let mut is_break = false;
                    if let Some(&si) = self.idx_of.get(&ts) {
                        let ei = if te == 0 {
                            si + 1
                        } else {
                            self.idx_of.get(&te).copied().unwrap_or(si)
                        };
                        for j in si..ei.max(si) {
                            let x = self.instrs[j];
                            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                && !x.is_backward
                                && x.target.map_or(false, |t| {
                                    t > x.offset && self.find_loop_exit(t).is_some()
                                })
                            {
                                cut = x.offset;
                                is_break = true;
                                break;
                            }
                        }
                    }
                    let mut tail = if cut > ts && cut != usize::MAX {
                        self.decompile_region(ts, cut)
                    } else {
                        Vec::new()
                    };
                    if is_break {
                        tail.push(Stmt::Break);
                    }
                    if !tail.is_empty() {
                        if let Some(top) = self.blocks.last_mut() {
                            if let Some(Stmt::Try {
                                body, finalbody, ..
                            }) = top.stmts.last_mut()
                            {
                                if finalbody.is_empty() {
                                    body.extend(tail);
                                }
                            }
                        }
                    }
                    if te > 0 {
                        self.skip_until = Some(te);
                    } else if is_break {
                        // consume the tail jump itself — executing it
                        // would emit a SECOND Break at loop level and
                        // tear the loop down
                        if let Some(&si) = self.idx_of.get(&ts) {
                            let je = self.instrs[si].end();
                            if self.skip_until.map_or(true, |s| s < je) {
                                self.skip_until = Some(je);
                            }
                        }
                    }
                } else if pos > ts {
                    // jumped over — the tail is unreachable in this flow
                    self.pending_try_tail = None;
                }
            }
            if let Some(skip) = self.skip_until {
                if pos < skip {
                    pc += 1;
                    continue;
                }
                self.skip_until = None;
                // a shared fall-through terminator moved out of a folded
                // Try body renders now — right after the chain skip
                // landed, so it follows the Try statement
                if let Some(stmt) = self.pending_post_chain_stmt.take() {
                    self.cur_offset = pos;
                    self.push_stmt(stmt);
                }
            }
            self.cur_offset = pos;
            self.cur_next = inst.end();
            if let Some(l) = inst.line {
                self.cur_line = Some(l);
            }
            if std::env::var("PYCDC_STACK").is_ok() {
                eprintln!(
                    "ST {:>4} {:?} stack={:?}",
                    pos,
                    inst.op,
                    self.stack.iter().map(short).collect::<Vec<_>>()
                );
            }
            if std::env::var("PYCDC_TRACE2").is_ok() {
                eprintln!("T2 {:>4} {:?} blocks={:?} skip={:?} lh={:?} lt={:?}", pos, inst.op,
                    self.blocks.iter().map(|b| format!("{:?}[{},{}]", b.kind, b.start, b.end)).collect::<Vec<_>>(),
                    self.skip_until,
                    self.legacy_handler.is_some(),
                    self.legacy_try.as_ref().map(|l| (l.handler_start, l.handlers.len(), l.else_start, l.chain_done)));
            }

            // py2 inline comprehension: region ends at the FOR_ITER exit
            if self.version.major == 2 {
                let end_hit = self
                    .inline_comp
                    .as_ref()
                    .map(|c| pos >= c.end && c.end != usize::MAX)
                    .unwrap_or(false);
                if end_hit {
                    // py2 FOR_ITER leaves the iterator on the stack at
                    // exit — one leftover per generator for multi-for
                    // comprehensions
                    let npops = self
                        .inline_comp
                        .as_ref()
                        .map(|c| {
                            if self.version.major == 2 {
                                c.for_iter_offsets.len().max(1)
                            } else {
                                1
                            }
                        })
                        .unwrap_or(1);
                    for _ in 0..npops {
                        self.pop();
                    }
                    self.finish_inline_comp();
                }
            }

            // 3.5-3.7 async-for: the per-iteration StopAsyncIteration
            // guard handler is loop machinery — never walk it; skip from
            // its head past the END_FINALLY into the loop body
            if self
                .async_for_guard
                .map_or(false, |(h, _, _)| h == pos && inst.op == Op::DUP_TOP)
            {
                if let Some(&hi) = self.idx_of.get(&pos) {
                    for ins in self.instrs[hi..].iter().take(10) {
                        if ins.op == Op::END_FINALLY {
                                                        self.skip_until = Some(ins.end());
                            break;
                        }
                    }
                }
            }
            // pre-3.11 handler-chain bookkeeping
            self.legacy_chain_step(&inst);
            // a bare-except chain whose try body ended in a RETURN has no
            // body-end POP_BLOCK: the Try block (and its LegacyTry chain)
            // is created by the close triggered AT the handler's first
            // POP_TOP — which the chain step above ran ahead of. Re-run
            // the step now so the bare-entry check (pos == handler_start)
            // sees the live chain (codecs 3.7 open: the handler was never
            // opened, its `file.close(); raise` flattened to function
            // level and the teardown DROPPED the whole try body).
            if !self.version.at_least(3, 11)
                && inst.op == Op::POP_TOP
                && self.legacy_handler.is_none()
                && self.legacy_nest.is_empty()
                && self.legacy_try.is_none()
            {
                self.close_blocks_at(pos);
                if self
                    .legacy_try
                    .as_ref()
                    .map_or(false, |l| l.handler_start == pos)
                {
                    self.legacy_chain_step(&inst);
                }
            }
            // an if/else branch may have closed exactly at this offset
            // while the chain step ran (the fused or-continue chain skips
            // ahead into its body); close it before executing here
            if matches!(
                inst.op,
                Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP | Op::POP_TOP
                    | Op::ROT_TWO | Op::ROT_THREE | Op::SWAP
            ) {
                self.close_blocks_at(pos);
                // py2.6 chained comparison: the close merged the chain
                // value and armed a skip covering this else-arm cleanup
                // instruction — honor it instead of letting the shuffle
                // corrupt the merged value on the live stack.
                if let Some(skip) = self.skip_until {
                    if pos < skip {
                        pc += 1;
                        continue;
                    }
                }
            }
            // chain fully parsed (END_FINALLY passed) but no jump emitted it
            // yet: flush before the continuation executes so statement order
            // and block targeting stay correct
            // a body-end jump that flew over an unparsed chain: parse it
            // now so the deferred emission below sees the handlers
            if !self.legacy_nest.is_empty()
                && self.legacy_handler.is_none()
                && self.legacy_try.as_ref().map_or(false, |l| {
                    !l.chain_done && l.handlers.is_empty() && pos > l.handler_start
                })
                && self.blocks.last().map_or(false, |b| b.kind == BlockType::Main)
            {
                self.parse_skipped_nested_chain(pos);
            }
            if self.legacy_handler.is_none()
                && self.legacy_try.as_ref().map_or(false, |l| {
                    l.chain_done
                        && !l.handlers.is_empty()
                        && !l.has_finally
                        && l.else_start.map_or(true, |_| {
                            inst.offset >= l.else_stop
                        })
                })
            {
                // Flush the else region's pending stores BEFORE taking the
                // legacy try, so push_stmt still routes them into lt.orelse
                // (the else_start check needs legacy_try alive). Taking first
                // would strand the else body's last store in the enclosing
                // block, emitting it as a sibling before the Try.
                self.flush_pending_stores();
                // the else region's own branch blocks end AT the flush
                // offset — close them before the emission, else push_stmt
                // routes the Try into the still-open block (compileall
                // 3.7 compile_file: the flush at the merge 650 fired with
                // the else's If[ok==0] open — the whole try/except group
                // rendered INSIDE `if ok == 0:`). ONLY blocks that opened
                // at/after the else start: enclosing wrappers that merely
                // END at the merge must fold after the emission, into
                // their own parents (closing them here redirects whole
                // wrapper Ifs into the orelse)
                if let Some(es) = self.legacy_try.as_ref().and_then(|l| l.else_start) {
                    while self.blocks.len() > 1 {
                        let end = self.blocks.last().map(|b| (b.start, b.end));
                        match end {
                            Some((bs, be)) if bs >= es && be <= pos => {
                                self.force_close_top(pos);
                            }
                            _ => break,
                        }
                    }
                }
                let l = self.legacy_try.take().unwrap();
                if let Some(depth) = self.finish_legacy_nest() {
                    while self.blocks.len() > depth.max(1) {
                        let p = self.blocks.last().map(|b| b.start).unwrap_or(pos);
                        self.force_close_top(p);
                    }
                }
                self.push_stmt(Stmt::Try {
                    body: l.body,
                    handlers: l.handlers,
                    orelse: l.orelse,
                    finalbody: l.finalbody,
                });
            }
            if self.in_handler_prelude
                && !matches!(
                    inst.op,
                    Op::POP_TOP
                        | Op::SETUP_FINALLY
                        | Op::SETUP_EXCEPT
                        | Op::SETUP_CLEANUP
                        | Op::DUP_TOP
                        | Op::ROT_THREE
                        | Op::ROT_FOUR
                        | Op::ROT_TWO
                        | Op::SWAP
                        | Op::STORE_FAST
                        | Op::STORE_NAME
                        | Op::STORE_DEREF
                        | Op::LOAD_CONST
                        | Op::NOP
                        | Op::POP_BLOCK
                        | Op::COPY
                )
            {
                self.in_handler_prelude = false;
            }

            // 3.11+: open try blocks driven by the exception table
            self.open_exception_blocks(pos);

            // a prescanned unconditional `while True` loop starts here
            // (tops are effective offsets: a 3.10 NOP line marker opens
            // the match one instruction early — close the blocks that
            // END at the top FIRST, or a guard If merging exactly here
            // stays open underneath and traps the loop in its arm)
            // match the walk position to a prescanned top: exact, or
            // the position is a NOP line marker immediately before the
            // top (3.10 while-True heads). The NOP-marker early open is
            // suppressed when a try region starts AT the top: opening
            // the loop at the marker beats open_exception_blocks by one
            // instruction and inverts the nesting ([While, Try] instead
            // of [Try, While]) - the try/finally renders INSIDE the loop
            // and its inline copy is walked twice (code 3.14 interact:
            // loop top 620 == the merged finally region's start). The
            // exact-match path at the top runs AFTER
            // open_exception_blocks, giving the source order.
            let wtop = self.while_true_loops.iter().find(|(t, _)| {
                *t == pos
                    || (*t > pos
                        && !self.try_ctxs.contains_key(t)
                        && self.idx_of.get(t).map_or(false, |&i| {
                            i > 0 && self.instrs[i - 1].offset == pos
                                && self.instrs[i - 1].op == Op::NOP
                        }))
            }).map(|(t, e)| (*t, *e));
            if let Some((t_top, _)) = wtop {
              if !self.blocks.iter().any(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (b.start == pos || b.start == t_top)
                })
              {
                let pos_eff = t_top;
                let end = self
                    .while_true_loops
                    .iter()
                    .find(|(t, _)| *t == t_top)
                    .map(|(_, e)| *e)
                    .unwrap_or(usize::MAX);
                // opened via the NOP marker (t_top != pos): a guard
                // merging exactly at the marker must close BEFORE the
                // loop opens or it traps the loop in its arm (binhex
                // 3.10). Exact-match opens keep the historical order
                // (open first; the generic close follows) — reordering
                // there shifted codecs 3.8 read's loop nesting.
                if t_top != pos {
                    self.close_blocks_at(pos);
                } else if self
                    .blocks
                    .last()
                    .map_or(false, |b| !matches!(b.kind, BlockType::Main) && b.end <= pos)
                {
                    // exact-match open with a block merging EXACTLY at
                    // the loop top: close it FIRST — the generic close
                    // below is blocked by the freshly opened loop (its
                    // end > pos) and the guard arm would swallow the
                    // loop (codecs 3.14 read: If[148,154] trapped
                    // While[154,550], `while True` nested under
                    // `if chars < 0`)
                    self.close_blocks_at(pos);
                }
                // statements before the loop top must not flow into it
                if !self.pending_stores.is_empty() {
                    self.flushing = true;
                    self.flush_pending_stores();
                    self.flushing = false;
                }
                // start at the EFFECTIVE top (past the 3.10 NOP line
                // marker): the body's own back edge targets it directly,
                // and matching b.start against the raw NOP offset would
                // read the natural iteration edge as an explicit
                // `continue` (binhex 3.10 HexBin.__init__)
                let mut blk = Block::new(BlockType::While, pos_eff, end);
                blk.cond = Some(self.true_cond_expr());
                blk.cond_set = true;
                self.blocks.push(blk);
              }
            }

            // or-rotated while tail re-eval: skip the whole copy span
            if !self.or_rot_revals.is_empty() {
                if let Some((rs, re)) = self
                    .or_rot_revals
                    .iter()
                    .find(|(rs, _)| *rs == pos)
                    .copied()
                {
                    self.or_rot_revals.retain(|(a, _)| *a != rs);
                    self.skip_until = Some(re);
                }
                if self
                    .or_rot_revals
                    .iter()
                    .any(|(rs, re)| pos >= *rs && pos < *re)
                {
                    pc += 1;
                    continue;
                }
            }
            // Close finished blocks before handling this instruction —
            // except when a backward jump lands exactly at an open If/Else
            // boundary: that jump is either a fused elif-chain exit or a
            // trailing `continue`, and the exec-time folded machinery must
            // see the branch block still open.
            let defer_close = matches!(
                inst.op,
                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT
            ) && inst.target.map_or(false, |t| t < inst.offset)
                && self.blocks.last().map_or(false, |b| {
                    matches!(b.kind, BlockType::If | BlockType::Else) && b.end == pos
                });
            if !defer_close {
                self.close_blocks_at(pos);
                // the close may have run emit_try_tail and armed a skip
                // covering THIS instruction (the try body's tail return
                // at region_end, sunk-pair success copies, chain glue):
                // honor it instead of executing the instruction into the
                // enclosing branch as a stray statement
                if let Some(skip) = self.skip_until {
                    if pos < skip {
                        pc += 1;
                        continue;
                    }
                }
            }

            // 3.10+: a string-expression statement directly after the
            // module docstring is folded to a position NOP (cgi 3.11's
            // exec-magic header: the shebang trick string IS the stored
            // __doc__ and the real docstring that follows is dropped,
            // leaving only a multi-line NOP). The dropped constant is
            // unrecoverable — emit an empty-string Expr placeholder so
            // the recompile reproduces the NOP and the module offsets
            // (a missing NOP shifted every later jump target by 2)
            if matches!(inst.op, Op::NOP) && self.version.at_least(3, 10) {
                let prev_is_doc_store = self.idx_of.get(&pos).map_or(false, |&i| {
                    let mut k = i;
                    while k > 0 {
                        k -= 1;
                        if matches!(
                            self.instrs[k].op,
                            Op::NOP | Op::CACHE | Op::NOT_TAKEN
                        ) {
                            continue;
                        }
                        return matches!(self.instrs[k].op, Op::STORE_NAME)
                            && self.const_name(self.instrs[k].arg as usize)
                                == "__doc__";
                    }
                    false
                });
                // a NOP adjacent to an exception-table region is the
                // 3.12+ try-position ANCHOR, not a dropped string
                // (decimal 3.12 `try: from _decimal import *` — its
                // anchor NOP sits 2 bytes before the region start)
                let try_anchor = self.exc_entries.iter().any(|e| {
                    e.start <= pos + 2 && pos < e.end.saturating_add(2)
                });
                if prev_is_doc_store
                    && !try_anchor
                    && self
                        .blocks
                        .last()
                        .map_or(false, |b| b.kind == BlockType::Main)
                {
                    self.push_stmt(Stmt::Expr(Rc::new(Expr::Const(Rc::new(
                        PyObject::Str(String::new()),
                    )))));
                }
            }
            // comprehension loop-target stores consume no stack value —
            // only while the comprehension is live and its target unset
            // (an unpacked `for k, v in` target arrives via the frame
            // machinery; post-loop restore stores must pop normally)
            if self.comp_target_store
                && self.unpack_frames.is_empty()
                && self
                    .inline_comp
                    .as_ref()
                    .map_or(false, |c| !c.target_seen)
                && matches!(
                    inst.op,
                    Op::STORE_FAST
                        | Op::STORE_NAME
                        | Op::STORE_DEREF
                        | Op::STORE_FAST_LOAD_FAST
                )
            {
                self.comp_target_store = false;
                let name = match inst.op {
                    Op::STORE_NAME => self.const_name(inst.arg as usize),
                    Op::STORE_FAST_LOAD_FAST => {
                        self.local_name(((inst.arg >> 4) & 0xF) as usize)
                    }
                    _ => self.local_name(inst.arg as usize),
                };
                let target_e = self.name_expr(name.clone());
                if let Some(comp) = &mut self.inline_comp {
                    if let Some(cur) = &mut comp.cur {
                        cur.target = Some(target_e);
                    }
                    comp.target_seen = true;
                }
                if inst.op == Op::STORE_FAST_LOAD_FAST {
                    let load = self.local_name((inst.arg & 0xF) as usize);
                    self.push(self.name_expr(load));
                }
                self.prev_op = Some(inst.op);
                pc += 1;
                continue;
            }
            // pre-exec machinery (open_exception_blocks -> emit_try_tail
            // -> handler region sub-walks) leaves cur_offset/cur_next at
            // the sub-walk's last instruction — re-establish THIS loop's
            // position so exec's block bookkeeping (close_blocks_at,
            // loop matching) sees the real dispatch site
            self.cur_offset = pos;
            self.cur_next = inst.end();
            // 3.10 inlines the with-exit protocol
            // (`LOAD None; DUP_TOP; DUP_TOP; CALL_FUNCTION 3; POP_TOP`
            // = __exit__(None, None, None)) into EVERY return path sunk
            // inside the with body — the handler-path copies walk as a
            // bogus `None(None, None, None)` expression statement
            // (codeop 3.10 _maybe_compile). With a With block open the
            // shape is unambiguous machinery: hop it
            if !self.version.at_least(3, 11)
                && inst.op == Op::LOAD_CONST
                && self
                    .code
                    .consts
                    .get(inst.arg as usize)
                    .map_or(false, |o| matches!(&**o, PyObject::None))
                && self.blocks.iter().any(|b| b.kind == BlockType::With)
                && self
                    .idx_of
                    .get(&pos)
                    .map_or(false, |&ci| {
                        matches!(
                            self.instrs.get(ci + 1).map(|x| x.op),
                            Some(Op::DUP_TOP)
                        ) && matches!(
                            self.instrs.get(ci + 2).map(|x| x.op),
                            Some(Op::DUP_TOP)
                        ) && matches!(
                            self.instrs.get(ci + 3).map(|x| (x.op, x.arg)),
                            Some((Op::CALL_FUNCTION, 3))
                        ) && matches!(
                            self.instrs.get(ci + 4).map(|x| x.op),
                            Some(Op::POP_TOP)
                        ) &&
                        // only the SUNK copies (a return follows within a
                        // couple of instructions): the main-path protocol
                        // is consumed by the With block's own close
                        // machinery — skipping it there leaves the exit
                        // function on the simulated stack, which leaks as
                        // a stray `None` statement (_sitebuiltins 3.10)
                        self.instrs[ci + 5..]
                            .iter()
                            .take(3)
                            .any(|x| {
                                matches!(
                                    x.op,
                                    Op::RETURN_VALUE | Op::RETURN_CONST
                                )
                            })
                    })
            {
                if let Some(&ci) = self.idx_of.get(&pos) {
                    if let Some(after) = self.instrs.get(ci + 5) {
                        self.skip_until = Some(after.offset);
                    }
                }
            }
            let prev = self.prev_op;
            self.prev_op_at_exec = prev;
            if !self.exec(&inst) {
                if std::env::var("PYCDC_TRACE").is_ok() {
                    eprintln!("AW BREAK at {} {:?}", pos, inst.op);
                }
                break;
            }
            // batch-103: the while-True loop owning a sunk tail return
            // just closed — lift `return v` to the post-loop level
            if let Some((wtop, _)) = self.sunk_while_lift.as_ref() {
                let gone = !self.blocks.iter().any(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (b.start == *wtop || b.cond_end == *wtop)
                });
                if gone {
                    if let Some((_, e)) = self.sunk_while_lift.take() {
                        self.flush_pending_stores();
                        self.push_stmt(Stmt::Return(Some(e)));
                    }
                }
            }
            // keep prev_op meaningful across transparent ops
            if !matches!(inst.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE) {
                self.prev_op = Some(inst.op);
            }
            pc += 1;
        }
        // teardown lift: the loop never closed during the walk (3.14
        // multi-back-edge while-True) — close it (and any inner blocks)
        // first so the lifted return lands AFTER the loop, not inside it
        if let Some((wtop, e)) = self.sunk_while_lift.take() {
            if let Some(i) = self.blocks.iter().position(|b| {
                matches!(b.kind, BlockType::While | BlockType::For)
                    && (b.start == wtop || b.cond_end == wtop)
            }) {
                let pos = self.instrs.last().map(|x| x.end()).unwrap_or(0);
                while self.blocks.len() > i + 1 {
                    self.force_close_top(pos);
                }
                self.force_close_top(pos);
            }
            self.flush_pending_stores();
            self.push_stmt(Stmt::Return(Some(e)));
        }
    }

    fn open_exception_blocks(&mut self, pos: usize) {
        if !self.version.at_least(3, 11) || self.inline_comp.is_some() {
            return;
        }
        let tail_work = matches!(&self.pending_try_ctx,
            Some(tc) if tc.region_end == pos && tc.region_end > tc.body_end);
        let open_work = self.try_ctxs.contains_key(&pos);
        if !tail_work && !open_work {
            return;
        }
        // stores before a try boundary must land in source order
        if !self.pending_stores.is_empty() {
            self.flushing = true;
            self.flush_pending_stores();
            self.flushing = false;
        }
        // a pending try's protected region ends here: emit else/finally parts
        if tail_work {
            let tc = self.pending_try_ctx.take().unwrap();
            self.emit_try_tail(tc, pos);
        }
        if let Some(tc) = self.try_ctxs.get(&pos).cloned() {
            // close expired blocks BEFORE opening the new Try: an outer
            // try whose region_end lies behind pos must fold first or the
            // new block shields it from close_blocks_at and the inline
            // finally span gets walked as its body (_bootsubprocess 3.11
            // check_output: unlink copy rendered inside the outer body
            // AND again in the finally decompose)
            self.close_blocks_at(pos);
            // the fold may have consumed THIS region as its inline
            // finally span (decompose + skip) — opening it again renders
            // a duplicate empty try
            if self.skip_until.map_or(false, |s| pos < s) {
                return;
            }
            // a protocol-continuation shadow (3.12+ await inside try: the
            // exception table splits the protected range around the
            // YIELD_VALUE suspension point) only extends the previous
            // body — its statements flow into the pending body and the
            // tail already emitted at the first fragment must not repeat.
            // A region with a DIFFERENT handler is a genuinely NESTED try
            // — it must open its own block even under a live active_try
            // (_bootsubprocess 3.11 check_output: the with-try inside the
            // outer try/finally never opened, its FileNotFoundError chain
            // stayed unparsed and the with rendered bare)
            let shadow_of_active = self.active_try.as_ref().map_or(false, |a| {
                a.except_handler == tc.except_handler
                    && a.finally_handler == tc.finally_handler
            });
            if self.active_try.is_none()
                || tc.body_end <= pos
                || !shadow_of_active
            {
                // an enclosing merged same-handler split region whose
                // rebuild will parse THIS region's chain (its head lies
                // in [enclosing body end, enclosing chain head)): defer
                // this region's own tail emit — running it here walks
                // its else-span into the relocated chains (code 3.12
                // interact) and its skip_until strands the enclosing
                // region's tail
                if let Some(h) = tc.except_handler {
                    if self.try_ctxs.values().any(|r| {
                        r.start < tc.start
                            && r.region_end > tc.region_end
                            && r.finally_handler.is_none()
                            && r.body_end == r.region_end
                            && r.except_handler.map_or(false, |ho| {
                                h >= r.body_end && h < ho
                            })
                    }) {
                        self.nested_tail_defer = true;
                    }
                }
                let mut blk = Block::new(BlockType::Try, pos, tc.body_end);
                blk.finally_target = tc.except_handler.or(tc.finally_handler);
                if let Some(prev) = self.active_try.take() {
                    // a genuinely nested region displaced the enclosing
                    // context — keep it so the outer block's close can
                    // still fold its own tail
                    self.active_try_stack.push(prev);
                }
                self.active_try = Some(tc);
                self.blocks.push(blk);
            }
        }
    }

    /// Decompose an inline-finally span [from, to) for handler `fh`.
    /// 3.11+ nests zero-depth finally chains linearly:
    ///   body; [POP] <inline fin copy>; JF next; CHAIN(fh): copy; RERAISE;
    ///   stubs; next: ...
    /// When the span holds a nested try's inline body followed by an
    /// outward jump and `fh`'s chain follows, rebuild the nested Try and
    /// recurse on the remainder.
    /// Canonicalize leaked double negations inside a rebuilt finally
    /// span: a guard cond may arrive as a raw `not <single-op compare>`
    /// when a polarity path wrapped instead of inverting (3.14 interact
    /// rendered `if not exitmsg is not None:`). The fold is scoped to
    /// these spans — a global codegen fold would rewrite FAITHFUL
    /// `not X is None` renderings whose originals compile to
    /// UNARY_NOT + IS_OP (codecs 3.14, cmd 3.7 regressed under the
    /// global form).
    fn canon_not_cmp(&self, stmts: &mut Vec<Stmt>) {
        fn fold(e: &mut ExprRef) {
            let inv;
            let folded = match &**e {
                Expr::Unary { op: UnaryOp::Not, operand } => {
                    match &**operand {
                        Expr::Compare { operands, ops } if ops.len() == 1 => {
                            inv = match ops[0] {
                                CmpOp::Is => Some(CmpOp::IsNot),
                                CmpOp::IsNot => Some(CmpOp::Is),
                                CmpOp::In => Some(CmpOp::NotIn),
                                CmpOp::NotIn => Some(CmpOp::In),
                                CmpOp::Eq => Some(CmpOp::NotEq),
                                CmpOp::NotEq => Some(CmpOp::Eq),
                                _ => None,
                            };
                            match inv {
                                Some(op) => Some(Rc::new(Expr::Compare {
                                    operands: operands.clone(),
                                    ops: vec![op],
                                }) as ExprRef),
                                None => None,
                            }
                        }
                        _ => None,
                    }
                }
                _ => None,
            };
            if let Some(f) = folded {
                *e = f;
            }
        }
        fn walk_expr(e: &mut ExprRef) {
            fold(e);
            match &mut *Rc::make_mut(e) {
                Expr::BoolOp { values, .. } => {
                    for v in values.iter_mut() {
                        walk_expr(v);
                    }
                }
                Expr::Unary { operand, .. } => walk_expr(operand),
                Expr::Binary { left, right, .. } => {
                    walk_expr(left);
                    walk_expr(right);
                }
                Expr::Compare { operands, .. } => {
                    for o in operands.iter_mut() {
                        walk_expr(o);
                    }
                }
                _ => {}
            }
        }
        fn walk(list: &mut Vec<Stmt>) {
            for s in list.iter_mut() {
                match s {
                    Stmt::If { cond, body, orelse } => {
                        fold(cond);
                        walk_expr(cond);
                        walk(body);
                        walk(orelse);
                    }
                    Stmt::While { cond, body, orelse } => {
                        fold(cond);
                        walk_expr(cond);
                        walk(body);
                        walk(orelse);
                    }
                    Stmt::Try { body, handlers, orelse, finalbody } => {
                        walk(body);
                        for h in handlers.iter_mut() {
                            walk(&mut h.body);
                        }
                        walk(orelse);
                        walk(finalbody);
                    }
                    Stmt::For { target, iter, body, orelse, .. } => {
                        walk_expr(target);
                        walk_expr(iter);
                        walk(body);
                        walk(orelse);
                    }
                    _ => {}
                }
            }
        }
        walk(stmts);
    }

    /// Rebuild the if/elif chain of a finally body whose arms end in
    /// sunk `return None` copies (3.12+): the region walk renders each
    /// arm's sunk return as a real Return inside its If arm and the
    /// following arm as a SIBLING if. Neither rendering is correct in a
    /// finally body: the return would SWALLOW the in-flight exception,
    /// and the sibling form loses the arm exclusivity (both tests would
    /// run). The sunk return is the arm terminator replacing the classic
    /// else-jump (the mirrored handler-side arms RERAISE at the same
    /// slots — validated before this runs) — drop the arm's Return and
    /// fold the following sibling statements into its orelse.
    fn rebuild_sunk_elif(&self, list: &mut Vec<Stmt>) {
        fn arm_ends_sunk_return(s: &Stmt) -> bool {
            match s {
                Stmt::If { body, orelse, .. } => {
                    orelse.is_empty()
                        && matches!(body.last(), Some(Stmt::Return(None)))
                }
                _ => false,
            }
        }
        fn rebuild(list: &mut Vec<Stmt>) {
            let mut i = 0;
            while i < list.len() {
                if i + 1 < list.len() && arm_ends_sunk_return(&list[i]) {
                    let mut rest: Vec<Stmt> = list.drain(i + 1..).collect();
                    if let Stmt::If { body, .. } = &mut list[i] {
                        body.pop();
                    }
                    rebuild(&mut rest);
                    if let Stmt::If { orelse, .. } = &mut list[i] {
                        *orelse = rest;
                    }
                    return;
                }
                i += 1;
            }
            // tail of the chain: drop the flat tail-run returns and the
            // LAST arm's own sunk terminator
            while matches!(list.last(), Some(Stmt::Return(None))) {
                list.pop();
            }
            if let Some(Stmt::If { body, orelse, .. }) = list.last_mut() {
                if orelse.is_empty()
                    && matches!(body.last(), Some(Stmt::Return(None)))
                {
                    body.pop();
                }
            }
        }
        rebuild(list);
    }

    fn decompose_finally_span(
        &mut self,
        from: usize,
        to: usize,
        fh: Option<usize>,
    ) -> Vec<Stmt> {
        // locate the outward exit jump of the nested inline body
        let exit = self
            .instrs
            .iter()
            .find(|x| {
                x.offset >= from
                    && x.offset < to
                    && matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                    && x.target.map_or(false, |t| t > to)
            })
            .map(|x| (x.offset, x.target.unwrap()));
        // a nested try exists only when a deeper TryCtx region starts
        // inside this span (the merged finally-levels grouping); a
        // single-level try's span is just [inline copy][exit JF] and the
        // chain at `fh` is its OWN handler copy
        let has_nested_ctx = self
            .try_ctxs
            .keys()
            .any(|s| *s > from && *s < to);
        let nested = match (exit, fh) {
            (Some((xj_off, xj_tgt)), Some(h)) if xj_tgt > h && has_nested_ctx => {
                let hi = self.idx_of.get(&h).copied();
                let head_ok = hi.map_or(false, |i| self.instrs[i].op == Op::PUSH_EXC_INFO);
                if !head_ok {
                    None
                } else {
                    // chain copy ends at its first RERAISE/END_FINALLY
                    let fin_stop = self.instrs[hi.unwrap()..]
                        .iter()
                        .take(200)
                        .find(|y| matches!(y.op, Op::RERAISE | Op::END_FINALLY))
                        .map(|y| y.end());
                    // the nested try is real only when the chain stubs
                    // lead to the exit landing (no further chains between)
                    let extent = self.chain_extent(h);
                    let lands = extent <= xj_tgt && xj_tgt <= xj_off + 64;
                    fin_stop.map(|fs| (xj_off, xj_tgt, h, fs, lands))
                }
            }
            _ => None,
        };
        if let Some((xj_off, xj_tgt, h, fin_stop, lands)) = nested {
            // skip a leading POP_TOP (yield-resume padding)
            let body_from = self
                .instrs
                .iter()
                .find(|x| x.offset >= from)
                .map(|x| {
                    if x.op == Op::POP_TOP {
                        x.end()
                    } else {
                        x.offset
                    }
                })
                .unwrap_or(from);
            let body = self.decompose_finally_span(body_from, xj_off, None);
            let fin = self.decompile_region(h, fin_stop);
            let stmt = Stmt::Try {
                body,
                handlers: Vec::new(),
                orelse: Vec::new(),
                finalbody: fin,
            };
            let resume = xj_tgt;
            let mut out = vec![stmt];
            if lands && resume < to {
                // the remainder of THIS span after the nested chain is
                // unreachable through it — nothing more to add
            } else if resume < to {
                out.extend(self.decompile_region(resume, to));
            }
            return out;
        }
        self.decompile_region(from, to)
    }

    /// True when the chain at instruction index `hi` dispatches except*
    /// clauses (CHECK_EG_MATCH within the clause-head window).
    fn is_star_dispatch(&self, hi: usize) -> bool {
        self.instrs[hi..]
            .iter()
            .take(40)
            .any(|x| x.op == Op::CHECK_EG_MATCH)
    }

    /// Emit the else/finally structure of a completed try region and
    /// decompile the out-of-line handlers.
    /// 3.11+ `with` inside `try`: the exception table splits the
    /// protected body around the with machinery, so the Try folds at an
    /// early fragment boundary while the body's real tail (a `break` /
    /// pass-through jump laid out between the machinery and the chain
    /// head) is still UNWALKED. Detect that tail and record it; the main
    /// walk folds it into the Try's body on arrival. Detection must
    /// reject an else region: when every handler clause re-joins the
    /// mainline at the tail jump's target, the span [jump_target,
    /// chain_head) is the else body, not a body tail (_compression 3.12
    /// read's `else: return ...`).
    fn arm_try_body_tail(&mut self, tc: &TryCtx) {
        self.pending_try_tail = None;
        let dbg = std::env::var("PYCDC_EG_DBG").is_ok();
        if dbg { eprintln!("EG arm ENTER tc=({},{},{}) exc={:?}", tc.start, tc.body_end, tc.region_end, tc.except_handler); }
        if !self.version.at_least(3, 11) || tc.except_handler.is_none() {
            if dbg { eprintln!("EG arm REJECT version/handler"); }
            return;
        }
        let Some(h) = tc.except_handler else { return };
        if h <= tc.body_end {
            if dbg { eprintln!("EG arm REJECT h<=body_end"); }
            return;
        }
        // tail jump: last forward JUMP_FORWARD/JUMP below the chain head
        // not itself inside an exception-table entry (the with success
        // path's own exit jump IS covered — 142 lies in `120 to 142`)
        let (Some(&bi), Some(&hi)) = (self.idx_of.get(&tc.body_end), self.idx_of.get(&h)) else {
            if dbg { eprintln!("EG arm REJECT idx"); }
            return;
        };
        let mut tj = None;
        for j in bi..hi {
            let x = self.instrs[j];
            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                && !x.is_backward
                && x.target.map_or(false, |t| t > x.offset)
                && !self
                    .exc_entries
                    .iter()
                    .any(|e| e.start <= x.offset && x.offset < e.end)
            {
                tj = Some(j);
            }
        }
        let Some(j) = tj else {
            if dbg { eprintln!("EG arm REJECT no tail jump in [{},{})", tc.body_end, h); }
            return;
        };
        let jt = self.instrs[j].target.unwrap();
        if dbg { eprintln!("EG arm tailjump j={} off={} jt={}", j, self.instrs[j].offset, jt); }
        // every clause's re-join jump aiming at jt makes [jt, h) an else
        // region — the tail jump is the else body's exit, not a body tail
        let chain_end = self.chain_extent(h);
        let (clause_joins, joins_at_jt) = self
            .idx_of
            .get(&h)
            .map(|&csi| {
                let cei = self
                    .idx_of
                    .get(&chain_end)
                    .copied()
                    .unwrap_or(self.instrs.len());
                let jumps: Vec<_> = self.instrs[csi..cei.min(self.instrs.len())]
                    .iter()
                    .filter(|x| {
                        matches!(
                            x.op,
                            Op::JUMP_FORWARD
                                | Op::JUMP
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                | Op::JUMP_ABSOLUTE
                        )
                    })
                    .collect();
                (
                    jumps.len(),
                    jumps.iter().filter(|x| x.target == Some(jt)).count(),
                )
            })
            .unwrap_or((0, 0));
        if clause_joins > 0 && joins_at_jt >= clause_joins {
            if dbg { eprintln!("EG arm REJECT else-region ({},{})", clause_joins, joins_at_jt); }
            return;
        }
        // the span between the tail jump and the chain head must be
        // handler-prelude padding (POP_TOPs of a bare except, NOPs) —
        // 3.11 lays the chain adjacent to the body. 3.12+ lays it AFTER
        // the main flow: accept that layout only when the tail jump is a
        // BREAK (targets the enclosing loop's exit) and the span between
        // jump and head is exactly the loop's remaining linear flow (no
        // backward edges — nothing can re-enter the skipped span)
        let jump_is_loop_exit = self
            .instrs
            .get(j)
            .and_then(|x| x.target)
            .map_or(false, |t| self.find_loop_exit(t).is_some());
        let mut span_ok = true;
        for x in &self.instrs[j + 1..hi] {
            if matches!(x.op, Op::POP_TOP | Op::NOP | Op::NOT_TAKEN | Op::CACHE) {
                continue;
            }
            if jump_is_loop_exit
                && (!x.is_backward
                    // backward jumps COVERED by an exception-table entry
                    // are machinery resumes (the with success path's
                    // re-entry into the exit protocol) — dead for the
                    // linear walk; an UNCOVERED backward edge would mean
                    // live flow re-enters the span
                    || self
                        .exc_entries
                        .iter()
                        .any(|e| e.start <= x.offset && x.offset < e.end))
            {
                continue;
            }
            span_ok = false;
            break;
        }
        if !span_ok {
            if dbg { eprintln!("EG arm REJECT span jump_is_loop_exit={}", jump_is_loop_exit); }
            return;
        }
        let tail_start = self.instrs[j].offset;
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            eprintln!("EG armtail tc=({},{}) h={} j={} tail_start={} cur_offset={} jump_is_loop_exit={} span_ok={}", tc.start, tc.body_end, h, self.instrs[j].offset, tail_start, self.cur_offset, jump_is_loop_exit, span_ok);
        }
        if tail_start <= self.cur_offset {
            if std::env::var("PYCDC_EG_DBG").is_ok() { eprintln!("EG armtail REJECT cur_offset"); }
            return;
        }
        // padding-adjacent (3.11): resume at the chain head. Break-over-
        // flow (3.12+): resume at the jump's own target (the loop exit) —
        // skipping to the head would drop the post-loop main flow, which
        // the linear walk must still execute (te = 0 marks "no skip")
        let tail_end = if jump_is_loop_exit && hi > j + 1 && !matches!(
            self.instrs[j + 1].op,
            Op::POP_TOP | Op::NOP | Op::NOT_TAKEN | Op::CACHE
        ) {
            0
        } else {
            h
        };
        self.pending_try_tail = Some((tail_start, tail_end));
    }

    /// Opcode mirror check: does the span [s, fh) hold an INLINE copy of
    /// the finally chain whose out-of-line head sits at fh? The copy
    /// mirrors the chain instruction-for-instruction except for: the
    /// chain's PUSH_EXC_INFO head (the copy lacks it), each branch's
    /// terminator (the copy's sunk `return None` - RETURN_CONST or the
    /// LOAD_CONST None + RETURN_VALUE pair - where the chain RERAISEs),
    /// and the chain's cleanup stub tail (COPY; POP_EXCEPT; RERAISE - no
    /// copy counterpart). The span must be consumed exactly when the
    /// mirror ends (a partial match is a coincidental prefix).
    fn finally_copy_mirror(&self, s: usize, fh: usize) -> bool {
        let (Some(&si), Some(&fhi)) =
            (self.idx_of.get(&s), self.idx_of.get(&fh))
        else {
            return false;
        };
        let Some(&si) = self.idx_of.get(&s) else {
            return false;
        };
        // separate cursors: the chain head carries a
        // PUSH_EXC_INFO the inline copy lacks
        let mut cn = 0usize;
        while matches!(
            self.instrs.get(fhi + cn).map(|x| x.op),
            Some(Op::PUSH_EXC_INFO)
                | Some(Op::NOP)
                | Some(Op::NOT_TAKEN)
                | Some(Op::CACHE)
        ) {
            cn += 1;
        }
        let mut sn = 0usize;
        let mut matched = 0usize;
        // the copy's sunk `return None` at a branch end
        // (RETURN_CONST, or the 3.11/3.14-style
        // LOAD_CONST None; RETURN_VALUE pair) - consumed
        // when it aligns with the chain's RERAISE or when
        // a direct comparison fails
        let sunk_ret = |k: usize| -> usize {
            match self.instrs.get(si + k) {
                Some(sp)
                    if sp.offset < fh
                        && matches!(
                            sp.op,
                            Op::RETURN_CONST
                                | Op::RETURN_VALUE
                        ) =>
                {
                    1
                }
                Some(sp)
                    if sp.offset < fh
                        && sp.op == Op::LOAD_CONST
                        && matches!(
                            self.code
                                .consts
                                .get(sp.arg as usize)
                                .map(|o| &**o),
                            Some(PyObject::None)
                        )
                        && self
                            .instrs
                            .get(si + k + 1)
                            .map_or(false, |n2| {
                                n2.offset < fh
                                    && n2.op
                                        == Op::RETURN_VALUE
                            }) =>
                {
                    2
                }
                _ => 0,
            }
        };
        while let Some(f) = self.instrs.get(fhi + cn) {
            if matches!(f.op, Op::RERAISE | Op::END_FINALLY) {
                // branch terminators correspond: the
                // copy ends each finally-body branch
                // with a sunk `return None` where the
                // chain re-raises - skip the aligned
                // pair(s) and keep mirroring the rest
                // (code 3.13 interact: copy
                // RETURN_CONSTs at 1282/1336/1338 vs
                // chain RERAISEs at 1484/1538/1540)
                let mut paired = false;
                while matches!(
                    self.instrs.get(fhi + cn).map(|x| x.op),
                    Some(Op::RERAISE) | Some(Op::END_FINALLY)
                ) {
                    let k = sunk_ret(sn);
                    if k == 0 {
                        break;
                    }
                    cn += 1;
                    sn += k;
                    paired = true;
                }
                if paired {
                    continue;
                }
                break;
            }
            let Some(sp) = self.instrs.get(si + sn) else {
                return false;
            };
            if sp.offset >= fh {
                // the copy span is fully consumed; the
                // chain's remainder must be its cleanup
                // stub tail (COPY; POP_EXCEPT; RERAISE),
                // which has no copy counterpart - the
                // mirror succeeded
                let hre = self.handler_region_end(fh);
                let rest_ok = self.instrs[fhi + cn..]
                    .iter()
                    .take_while(|x| x.offset < hre)
                    .all(|x| {
                        matches!(
                            x.op,
                            Op::COPY
                                | Op::SWAP
                                | Op::POP_EXCEPT
                                | Op::POP_TOP
                                | Op::RERAISE
                                | Op::END_FINALLY
                                | Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE
                        )
                    });
                if rest_ok {
                    break;
                }
                return false;
            }
            if !op_family_eq(sp.op, f.op)
                || (matches!(
                    f.op,
                    Op::LOAD_CONST | Op::LOAD_GLOBAL
                ) && sp.arg != f.arg)
            {
                // misalignment: the copy carries a sunk
                // return the chain lacks at this slot -
                // hop it and retry the same chain slot
                let k = sunk_ret(sn);
                if k > 0 {
                    sn += k;
                    continue;
                }
                return false;
            }
            cn += 1;
            sn += 1;
            matched += 1;
        }
        // the span must run to the chain head: a
        // partial match is a coincidental prefix
        let tail_ok = matched >= 4
            && self
                .instrs
                .get(si + sn)
                .map_or(true, |x| x.offset >= fh);
        if std::env::var("PYCDC_EG_DBG").is_ok() && !tail_ok {
            eprintln!("EG mirfail [{}] s={} tail matched={} next={:?}", self.code.name, s, matched,
                self.instrs.get(si + sn).map(|x| (x.offset, x.op)));
        }
        tail_ok
    }

    fn emit_try_tail(&mut self, tc: TryCtx, pos: usize) {
        // 3.11 except* + else + finally: the chain is laid out INLINE
        // between the body's terminal JUMP_FORWARD and the else region,
        // and the walk leaked body/else statements into the enclosing
        // block — reconstruct every span by offset instead
        let star_inline = tc.finally_handler.is_some()
            && tc.except_handler.map_or(false, |h| {
                self.idx_of
                    .get(&h)
                    .map_or(false, |&hi| self.is_star_dispatch(hi))
            });
        self.bare_try_parse = tc.finally_handler.is_none()
            && tc.region_end == tc.body_end
            && !tc.except_handler.map_or(false, |h| {
                self.idx_of
                    .get(&h)
                    .map_or(false, |&hi| self.is_star_dispatch(hi))
            });
        let body_jf = if star_inline && tc.region_end > tc.body_end {
            // the body's terminal JF sits at body_end, possibly followed
            // by padding before the chain head (region_end)
            self.idx_of.get(&tc.body_end).and_then(|&bi| {
                let mut jf_i = None;
                for x in &self.instrs[bi..] {
                    if x.offset >= tc.region_end {
                        break;
                    }
                    if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP) {
                        jf_i = Some(x);
                        break;
                    }
                    if !matches!(x.op, Op::NOP | Op::NOT_TAKEN) {
                        break;
                    }
                }
                jf_i.and_then(|jf| {
                    if jf.target.map_or(false, |t| t > jf.offset && t <= pos) {
                        Some((jf.offset, jf.target.unwrap()))
                    } else {
                        None
                    }
                })
            })
        } else {
            None
        };
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            eprintln!(
                "EG tail [{}] tc start={} body_end={} region_end={} exc={:?} fin={:?} pos={} star_inline={} body_jf={:?}",
                self.code.name, tc.start, tc.body_end, tc.region_end, tc.except_handler, tc.finally_handler, pos, star_inline, body_jf
            );
        }
        // deferred nested tail: an enclosing merged same-handler region
        // will rebuild this try from spans (see the nested-split branch
        // below) — emitting here would misparse the relocated chain
        if self.nested_tail_defer {
            self.nested_tail_defer = false;
            return;
        }

        // 3.11+ nested try/except/else inside a try/except body: the
        // outer protected range arrives as same-handler fragments
        // sandwiching the nested region (merged by the builder), and
        // the nested chain's out-of-line dispatch lies BETWEEN the
        // outer body end and the outer chain head. The regular walk
        // emits the nested Try at its own body end — before the else
        // span (the outer's second fragment) has run — so its tail
        // logic misreads the span, and the outer body collects the
        // else statements flat (code 3.11 interact: doubled
        // `except KeyboardInterrupt` + `else: if EOFError:` garbage).
        // Rebuild every span from offsets: outer body = [start, nested)
        // + nested Try{body, chain, orelse=[nested region end, nested
        // chain end)}, outer handlers = the outer chain
        if !star_inline
            && body_jf.is_none()
            && tc.finally_handler.is_none()
            && tc.body_end == tc.region_end
        {
            if let Some(h_outer) = tc.except_handler {
                let nested = self
                    .try_ctxs
                    .values()
                    .find(|r| {
                        r.start > tc.start
                            && r.region_end <= tc.body_end
                            && r.finally_handler.is_none()
                            && r.except_handler
                                .map_or(false, |h| h >= tc.body_end && h < h_outer)
                    })
                    .cloned();
                if let Some(inner) = nested {
                    let h_inner = inner.except_handler.unwrap();
                    // the nested chain ends at its last RERAISE; the
                    // outward hop right after it resumes the outer flow.
                    // 3.12 relocates every chain to the function tail and
                    // the clause's break/exit hop (JF to the loop exit)
                    // comes BEFORE the cleanup RERAISEs — accept the
                    // first outward forward hop and cut at the last
                    // chain material seen (RERAISE end, or the POP_EXCEPT
                    // the hop itself follows)
                    let mut last_reraise_end = None;
                    let mut chain_stop = h_outer;
                    if let Some(&ci) = self.idx_of.get(&h_inner) {
                        for x in &self.instrs[ci..] {
                            if x.offset >= h_outer {
                                break;
                            }
                            if x.op == Op::RERAISE {
                                last_reraise_end = Some(x.end());
                            }
                            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                && !x.is_backward
                                && x.target.map_or(false, |t| t >= h_outer)
                            {
                                chain_stop =
                                    last_reraise_end.unwrap_or(x.offset);
                                break;
                            }
                        }
                    }
                    if chain_stop > inner.region_end && chain_stop <= h_outer {
                        // the span re-walks must not re-open these regions
                        self.try_ctxs.remove(&tc.start);
                        self.try_ctxs.remove(&inner.start);
                        // drop the statements the walk leaked into the
                        // enclosing block (the guard if/else of body1,
                        // the nested Try emitted at its own body end,
                        // the flat else-span stores)
                        let mark = self.pending_orelse_mark.take();
                        if let Some(top) = self.blocks.last_mut() {
                            if let Some(m) = mark {
                                if m <= top.stmts.len() {
                                    top.stmts.truncate(m);
                                }
                            }
                        }
                        let handlers = self.parse_except_dispatch(h_outer);
                        let body1 = self.decompile_region(tc.start, inner.start);
                        // adjacent nested chains: the dispatch parse of
                        // the INNER head splits — it stashes the inner
                        // clauses in nested_inner_handlers and RETURNS
                        // the enclosing chain's clauses (the re-raise
                        // wrapper design). Take the stash as the inner
                        // handlers; the returned vec duplicates the
                        // outer parse when the split fired
                        let stash_depth = self.nested_inner_handlers.len();
                        let parsed_inner =
                            self.parse_except_dispatch(h_inner);
                        let inner_handlers =
                            if self.nested_inner_handlers.len() > stash_depth
                            {
                                self.nested_inner_handlers.pop().unwrap()
                            } else {
                                parsed_inner
                            };
                        let inner_body =
                            self.decompile_region(inner.start, inner.region_end);
                        // the else span ends at the merged body end —
                        // the nested chain head bounds it only when the
                        // chain is inline (3.11); 3.12 relocates chains
                        // to the function tail past the loop back edge,
                        // and the span would swallow the back edge and
                        // the chain material as code
                        let orelse_end = tc.body_end.min(h_inner);
                        let inner_orelse =
                            self.decompile_region(inner.region_end, orelse_end);
                        let mut body = body1;
                        body.push(Stmt::Try {
                            body: inner_body,
                            handlers: inner_handlers,
                            orelse: inner_orelse,
                            finalbody: Vec::new(),
                        });
                        self.push_stmt(Stmt::Try {
                            body,
                            handlers,
                            orelse: Vec::new(),
                            finalbody: Vec::new(),
                        });
                        // resume the walk at the merged body end when
                        // the chains are relocated past it (3.12: the
                        // loop back edge and post-loop flow must run
                        // normally); otherwise hop the inline chain
                        let resume = if chain_stop > tc.body_end {
                            tc.body_end.max(pos)
                        } else {
                            chain_stop
                        };
                        if self.skip_until.map_or(true, |s| s < resume) {
                            self.skip_until = Some(resume);
                        }
                        return;
                    }
                }
            }
        }
        if let Some((jf_off, else_at)) = body_jf {
            // statements collected after the try opened (the body's last
            // POP_TOP past the table range, the else region the walk
            // crossed) belong to the spans we rebuild — drop them
            let mark = self.pending_orelse_mark.take();
            if let Some(top) = self.blocks.last_mut() {
                if let Some(m) = mark {
                    if m <= top.stmts.len() {
                        top.stmts.truncate(m);
                    }
                }
            }
            // the span re-walks must not re-open this region's own Try
            self.try_ctxs.remove(&tc.start);
            // parse the out-of-line clauses FIRST: the span walks set
            // skip_until (which region sub-walks would inherit and skip
            // every instruction with)
            let handlers = match tc.except_handler {
                Some(h) => self.parse_except_dispatch(h),
                None => Vec::new(),
            };
            let body = self.decompile_region(tc.start, jf_off);
            let orelse = self.decompile_region(else_at, pos);
            let mut stop = self
                .instrs
                .iter()
                .skip_while(|i| i.offset < pos)
                .find(|i| matches!(i.op, Op::RETURN_VALUE | Op::RETURN_CONST))
                .map(|i| i.offset)
                .unwrap_or(self.code.code.len());
            // the inline finally ends where its exception-path duplicate
            // (the finally handler chain) begins — 3.11 lays that chain
            // BEFORE the flow's RETURN
            if let Some(fh) = tc.finally_handler {
                if fh > pos && fh < stop {
                    stop = fh;
                }
            }
            let finalbody = if stop > pos {
                self.decompile_region(pos, stop)
            } else {
                Vec::new()
            };
            if self.skip_until.map_or(true, |s| s < stop) {
                                self.skip_until = Some(stop);
            }
            self.pending_nested_finally = None;
            self.push_stmt(Stmt::Try {
                body,
                handlers,
                orelse,
                finalbody,
            });
            let star_tail = std::mem::take(&mut self.star_tail);
            if !star_tail.is_empty() {
                self.push_stmt_all(star_tail);
                if let Some(se) = self.star_tail_end.take() {
                    if self.skip_until.map_or(true, |s| s < se) {
                                                self.skip_until = Some(se);
                    }
                }
            } else {
                self.star_tail_end = None;
            }
            return;
        }
        // 3.12+ zero-block try/finally with an early exit (break) inside
        // a loop: the protected range splits around the exit path's
        // inlined finally copy —
        //   [body1][exit: fin-copy + JF][body2 + fin-copy + back-edge]
        // with both fragments covered by the same finally handler. The
        // regular walk below would fold the whole span as one finally.
        // Rebuild from spans: body1 + break + body2-minus-copy, and the
        // finally from the out-of-line handler chain.
        if tc.split_body2.is_some()
            && tc.finally_handler.is_some()
            && tc.except_handler.is_none()
            && pos <= tc.body_end + (tc.body_end - tc.start)
        {
            let exit_jump = self.idx_of.get(&tc.body_end).and_then(|&gi| {
                self.instrs[gi..]
                    .iter()
                    .take(40)
                    .find(|x| {
                        matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                            && x.target.map_or(false, |t| t > x.offset)
                    })
                    .map(|x| (x.offset, x.target.unwrap()))
            });
            if let Some((jf_off, exit_at)) = exit_jump {
                if let Some((b2_start, b2_end)) = tc.split_body2 {
                    // the span re-walks must not re-open this region
                    self.try_ctxs.remove(&tc.start);
                    self.try_ctxs.remove(&b2_start);
                    let fin_head = tc.finally_handler.unwrap();
                    let fin_stop = self
                        .idx_of
                        .get(&fin_head)
                        .and_then(|&hi| {
                            self.instrs[hi..]
                                .iter()
                                .take(120)
                                .find(|x| x.op == Op::RERAISE)
                                .map(|x| x.offset)
                        })
                        .unwrap_or(fin_head);
                    // tail fin-copy of body2: walk back from the protected
                    // range end while the instruction mirrors the handler
                    // copy's tail (same opcode sequence), then step back
                    // over the copy's statement POP_TOPs
                    let frag = |a: usize, b: usize| -> bool {
                        let (ai, bi) = match (self.idx_of.get(&a), self.idx_of.get(&b)) {
                            (Some(&x), Some(&y)) => (x, y),
                            _ => return false,
                        };
                        let ao = self.instrs[ai].op;
                        let bo = self.instrs[bi].op;
                        if ao != bo {
                            return false;
                        };
                        !matches!(
                            ao,
                            Op::LOAD_CONST | Op::LOAD_GLOBAL | Op::LOAD_NAME
                        ) || self.instrs[ai].arg == self.instrs[bi].arg
                    };
                    let mut back = 0usize;
                    // the tail copy lives PAST the protected range (the
                    // compiler excludes it from the entry); never walk
                    // back into the body itself — a body statement can
                    // opcode-mirror the copy
                    let mut copy_start = b2_end;
                    loop {
                        let cand = fin_stop - 2 * (back + 1);
                        let prev_b2 = self
                            .instrs
                            .iter()
                            .rev()
                            .find(|x| {
                                x.offset < copy_start
                                    && x.offset >= b2_end
                                    && !matches!(x.op, Op::CACHE)
                            })
                            .map(|x| x.offset);
                        match prev_b2 {
                            Some(pb) if cand >= fin_head && frag(pb, cand) => {
                                copy_start = pb;
                                back += 1;
                            }
                            _ => break,
                        }
                    }
                    if back == 0 {
                        // no mirrored tail past the range end — probe the
                        // last instructions INSIDE the range instead (some
                        // versions protect the copy)
                        let mut probe = b2_end;
                        let mut pback = 0usize;
                        loop {
                            let cand = fin_stop - 2 * (pback + 1);
                            let prev_b2 = self
                                .instrs
                                .iter()
                                .rev()
                                .find(|x| {
                                    x.offset < probe
                                        && x.offset >= b2_start
                                        && !matches!(x.op, Op::CACHE)
                                })
                                .map(|x| x.offset);
                            match prev_b2 {
                                Some(pb) if cand >= fin_head && frag(pb, cand) => {
                                    probe = pb;
                                    pback += 1;
                                }
                                _ => break,
                            }
                        }
                        // only accept if the mirror ran to the copy's
                        // first instruction (fin_head+2's mirror): the
                        // handler copy minus PUSH_EXC_INFO has a known
                        // instruction count
                        let n_copy = (fin_stop - fin_head) / 2 - 1;
                        if pback == n_copy && pback > 0 {
                            copy_start = probe;
                        }
                    }
                    let trimmed = copy_start.min(b2_end);
                    let fin_body = self.decompile_region(fin_head, fin_stop);
                    // body1's terminal cond-jump aims at b2_start (the
                    // split's else arm): the exit path (the gap) IS its
                    // then arm — rebuild it as `if cond: break` and
                    // append body2 as the fall-through
                    let pre_cond = self
                        .instrs
                        .iter()
                        .take_while(|x| x.offset < tc.body_end)
                        .filter(|x| {
                            matches!(
                                x.op,
                                Op::POP_JUMP_IF_FALSE
                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                    | Op::POP_JUMP_IF_TRUE
                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                            ) && x.target == Some(b2_start)
                        })
                        .count();
                    let cond_span = pre_cond == 1
                        && self
                            .instrs
                            .iter()
                            .filter(|x| {
                                x.offset >= tc.start
                                    && x.offset < tc.body_end
                                    && matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                    )
                            })
                            .count()
                        == 1;
                    let mut body = Vec::new();
                    if cond_span {
                        let cj = self
                            .instrs
                            .iter()
                            .find(|x| {
                                x.offset >= tc.start
                                    && x.offset < tc.body_end
                                    && matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                    )
                            })
                            .map(|x| (x.offset, x.op))
                            .unwrap();
                        self.region_result_expr = None;
                        let cond_stmts = self.decompile_region(tc.start, cj.0);
                        let jump_if_true = matches!(
                            cj.1,
                            Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                        );
                        let mut cond_expr = self
                            .region_result_expr
                            .take()
                            .or_else(|| {
                                cond_stmts.into_iter().find_map(|s| match s {
                                    Stmt::Expr(e) => Some(e),
                                    _ => None,
                                })
                            })
                            .unwrap_or_else(|| self.name_expr("???"));
                        // PJIF_FALSE → b2_start: the then arm (the exit
                        // path) runs when the cond is TRUE
                        if jump_if_true {
                            cond_expr = Rc::new(Expr::Unary {
                                op: UnaryOp::Not,
                                operand: cond_expr,
                            });
                        }
                        body.push(Stmt::If {
                            cond: cond_expr,
                            body: vec![Stmt::Break],
                            orelse: Vec::new(),
                        });
                    } else {
                        body = self.decompile_region(tc.start, pos.min(tc.body_end));
                        body.push(Stmt::Break);
                    }
                    body.extend(self.decompile_region(b2_start, trimmed.max(b2_start)));
                    if std::env::var("PYCDC_EG_DBG").is_ok() {
                        eprintln!(
                            "EG splitfin [{}] body2=[{},{}) fin=[{},{}) exit={}",
                            self.code.name, b2_start, trimmed, fin_head, fin_stop, exit_at
                        );
                    }
                    self.pending_orelse_mark = None;
                    let handlers = match tc.except_handler {
                        Some(h) => self.parse_except_dispatch(h),
                        None => Vec::new(),
                    };
                    self.push_stmt(Stmt::Try {
                        body,
                        handlers,
                        orelse: Vec::new(),
                        finalbody: fin_body,
                    });
                    // the walk resumes at the exit landing (loop end /
                    // post-loop flow); the handler chain folds at its head
                    if self.skip_until.map_or(true, |s| s < exit_at) {
                                                self.skip_until = Some(exit_at);
                    }
                    return;
                }
            }
        }
        // `else:` clause exists only when the protected region extends past
        // the try body (finally covers body+else). For a FINALLY-only
        // chain the extended region is the inline finally body itself —
        // the walk collected it into the enclosing block; take it as the
        // finalbody instead and skip the inline copy below.
        let mut orelse = Vec::new();
        let mut early_fin: Option<Vec<Stmt>> = None;
        if tc.region_end > tc.body_end {
            if let Some(top) = self.blocks.last_mut() {
                let mark = self.pending_orelse_mark.take().unwrap_or(0);
                let taken = if mark <= top.stmts.len() {
                    top.stmts.split_off(mark)
                } else {
                    std::mem::take(&mut top.stmts)
                };
                if tc.except_handler.is_none() && tc.finally_handler.is_some() {
                    early_fin = Some(taken);
                } else {
                    orelse = taken;
                }
            }
        } else {
            self.pending_orelse_mark = None;
        }
        // inline finally body (main flow): from pos until the flow's RETURN
        let mut stop = self
            .instrs
            .iter()
            .skip_while(|i| i.offset < pos)
            .find(|i| matches!(i.op, Op::RETURN_VALUE | Op::RETURN_CONST))
            .map(|i| i.offset)
            .unwrap_or(self.code.code.len());
        // 3.11 lays the exception-path duplicate (the finally handler
        // chain) BEFORE the RETURN — bound the inline body at its head so
        // the duplicate does not fold twice
        if let Some(fh) = tc.finally_handler {
            if fh > pos && fh < stop {
                stop = fh;
            }
        }
        // a finally body ending in an if/elif chain: 3.12+ sinks a
        // `return None` into EVERY arm (RETURN_CONST arm terminators),
        // so the first return found above is an ARM end, not the flow
        // end — the inline copy actually runs to the LAST sunk return
        // before the chain head. Walk the return chain forward while a
        // test region with real code separates consecutive returns (an
        // elif arm); validate the extended span opcode-mirrors the
        // out-of-line chain (finally_copy_mirror pairs each sunk return
        // with the chain's RERAISE — a GENUINE `return` inside a
        // finally body appears in BOTH copies and fails the mirror,
        // keeping the old truncation). Without this the span cut at the
        // first arm and the remaining elif arms vanished from the
        // finalbody (code 3.13/3.14 interact exitmsg chain: the
        // `elif exitmsg != '':` write dropped — a semantic loss).
        let mut sunk_arm_returns = false;
        let mut sunk_copy_start: Option<usize> = None;
        // the extension's own validated stop: fin_span_stop can be
        // clamped below the copy start by a back edge that belongs to
        // an except clause's `continue` BEFORE the copy (3.14 interact:
        // the KI clause's JUMP_BACKWARD at 1066 clamps the span while
        // the copy runs 1190-1474)
        let mut sunk_ext_stop: Option<usize> = None;
        if let Some(fh) = tc.finally_handler {
            if fh > stop {
                let mut cur = stop;
                loop {
                    let next_ret = self
                        .instrs
                        .iter()
                        .skip_while(|i| i.offset <= cur)
                        .take_while(|i| i.offset < fh)
                        .find(|i| {
                            matches!(i.op, Op::RETURN_VALUE | Op::RETURN_CONST)
                        })
                        .map(|i| i.offset);
                    let Some(nr) = next_ret else { break };
                    // advance across both arm separators (real test
                    // code) and the tail return run; the full-span
                    // finally_copy_mirror below is the validator — a
                    // region that is not pure arm material fails the
                    // pairing and aborts the extension
                    cur = nr;
                }
                if cur > stop {
                    // validate through the copy-start candidates (the
                    // span at `pos` may hold except chains before the
                    // copy proper — code 3.13 interact: pos=752 but
                    // the copy starts at the KI chain's extent 1140 —
                    // so `pos` itself can fail the mirror while a
                    // later candidate succeeds)
                    let mut starts = vec![self
                        .skip_until
                        .filter(|&sk| sk > pos && sk < fh)
                        .unwrap_or(pos)];
                    for x in self.instrs.iter() {
                        if x.offset <= pos || x.offset >= fh {
                            continue;
                        }
                        if x.op == Op::PUSH_EXC_INFO {
                            let ext = self.chain_extent(x.offset);
                            if ext > pos && ext < fh && !starts.contains(&ext) {
                                starts.push(ext);
                            }
                        }
                    }
                    if let Some(&s0) = starts
                        .iter()
                        .find(|&&s| self.finally_copy_mirror(s, fh))
                    {
                        stop = cur;
                        sunk_arm_returns = true;
                        sunk_copy_start = Some(s0);
                        sunk_ext_stop = Some(cur);
                    }
                }
            }
        }
        // nested finally levels are laid out consecutively: when the
        // walk already collected the first level's inline copy (an
        // early_fin is pending), the span for the deeper copy ends at
        // the next chain head — but ONLY then; an except chain inside
        // the span belongs to the handlers parse, not the finally bound
        if early_fin.is_some() {
            if let Some(nh) = self
                .instrs
                .iter()
                .find(|x| x.offset > pos && x.offset < stop && x.op == Op::PUSH_EXC_INFO)
                .map(|x| x.offset)
            {
                stop = nh;
            }
        }
        // a `return` sunk past the inline finally evaluates its value
        // AFTER the finally bodies — the value loads belong to the RETURN
        // the main walk emits, not to the finally region
        if tc.finally_handler.is_some() && stop > pos {
            if let Some(&ri) = self
                .instrs
                .iter()
                .position(|x| x.offset == stop)
                .as_ref()
                .and_then(|_| self.idx_of.get(&stop))
            {
                let mut v = ri;
                while v > 0 {
                    let pv = &self.instrs[v - 1];
                    if pv.offset < pos {
                        break;
                    }
                    if matches!(
                        pv.op,
                        Op::LOAD_CONST
                            | Op::LOAD_FAST
                            | Op::LOAD_NAME
                            | Op::LOAD_GLOBAL
                            | Op::LOAD_DEREF
                            | Op::LOAD_SMALL_INT
                    ) {
                        v -= 1;
                    } else {
                        break;
                    }
                }
                if v < ri && self.instrs[v].offset > pos {
                    stop = self.instrs[v].offset;
                }
            }
        }
        let mut nested_inner_fin: Option<Vec<Stmt>> = None;
        // inline-copy bound: a loop back edge inside the span ends the
        // iteration, and the copy itself opcode-mirrors the out-of-line
        // handler chain — statements AFTER the copy (post-try code inside
        // a loop iteration) belong to the main walk, not the finally
        let mut fin_span_stop = stop;
        // the inline-copy mirror verdict: false means the span at `pos`
        // does NOT opcode-mirror the finally chain's copy — there is no
        // inline copy here (an always-raising try body has no normal
        // exit; contextlib 3.12 __exit__'s `try: raise RuntimeError
        // finally: gen.close()`), and the flow at `pos` is the NEXT
        // source statement, which the decompose below would swallow as
        // the finally body
        let mut mirror_ok = true;
        if early_fin.is_none() && tc.finally_handler.is_some() && stop > pos {
            // NOTE: JUMP_BACKWARD_NO_INTERRUPT is the await-resume
            // protocol / finally-flow jump — not a loop back edge
            if let Some(be) = self
                .instrs
                .iter()
                .find(|x| {
                    x.offset >= pos
                        && x.offset < stop
                        && (x.op == Op::JUMP_BACKWARD
                            || (x.op == Op::JUMP_ABSOLUTE && x.is_backward))
                })
                .map(|x| x.offset)
            {
                fin_span_stop = fin_span_stop.min(be);
            }
            if let Some(fh) = tc.finally_handler {
                if let Some(&fhi) = self.idx_of.get(&fh) {
                    let span_i = self
                        .instrs
                        .iter()
                        .position(|x| x.offset >= pos);
                    // hop the chain scaffolding between the fold pos and
                    // the inline copy's start: 3.11 folds land on the
                    // clause RERAISE with the mismatch stubs (COPY;
                    // POP_EXCEPT; RERAISE) between it and the copy (b22
                    // loop_try_mix) — comparing from the stubs misreads
                    // an existing copy as absent
                    let si0 = span_i.map(|mut s0| {
                        while s0 < self.instrs.len()
                            && self.instrs[s0].offset < stop
                            && matches!(
                                self.instrs[s0].op,
                                Op::RERAISE
                                    | Op::COPY
                                    | Op::POP_EXCEPT
                                    | Op::SWAP
                                    | Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::CACHE
                                    | Op::END_FINALLY
                            )
                        {
                            s0 += 1;
                        }
                        s0
                    });
                    if let Some(si0) = si0 {
                        // separate cursors: the chain has a PUSH_EXC_INFO
                        // head the inline copy lacks
                        let mut cn = 0usize;
                        let mut sn = 0usize;
                        let mut ok = true;
                        let mut trim = None;
                        while let Some(f) = self.instrs.get(fhi + cn) {
                            if matches!(f.op, Op::RERAISE | Op::END_FINALLY) {
                                if let Some(s) = self.instrs.get(si0 + sn) {
                                    if s.offset <= fin_span_stop {
                                        trim = Some(s.offset);
                                    }
                                }
                                break;
                            }
                            if matches!(
                                f.op,
                                Op::PUSH_EXC_INFO
                                    | Op::CACHE
                                    | Op::NOP
                                    | Op::NOT_TAKEN
                            ) {
                                // 3.11 pads the finally copy head with a
                                // NOP (its own source line) — the inline
                                // span lacks it; skipping it here keeps
                                // the mirror from diverging at sn=0 and
                                // misreading an existing inline copy as
                                // absent (_bootsubprocess 3.11
                                // check_output re-walked the unlink copy)
                                cn += 1;
                                continue;
                            }
                            match self.instrs.get(si0 + sn) {
                                Some(s)
                                    if op_family_eq(s.op, f.op)
                                        && (!matches!(
                                            s.op,
                                            Op::LOAD_CONST | Op::LOAD_GLOBAL
                                        ) || s.arg == f.arg) => {}
                                _ => {
                                    ok = false;
                                    break;
                                }
                            }
                            cn += 1;
                            sn += 1;
                        }
                        // gate scope: only an IMMEDIATE head divergence
                        // (or a degenerate empty copy) proves there is no
                        // inline copy at `pos` — a late divergence is the
                        // loop-back-edge trim cutting the span short
                        // (b22 3.11 loop_try_mix decomposes correctly
                        // despite it)
                        if std::env::var("PYCDC_EG_DBG").is_ok() {
                            eprintln!("EG mirror [{}] pos={} fh={} ok={} sn={} si0off={} fin_span_stop={}", self.code.name, pos, tc.finally_handler.unwrap_or(0), ok, sn, self.instrs.get(si0).map(|x| x.offset).unwrap_or(0), fin_span_stop);
                        }
                        mirror_ok = ok || sn > 1;
                        if ok {
                            if let Some(t) = trim {
                                // the trim stops at the chain's FIRST
                                // RERAISE = the span's first sunk
                                // return — correct for a straight-line
                                // finally body, but a BRANCHING body
                                // (if/elif arms each ending in a sunk
                                // return) continues past it; the
                                // extension above already validated
                                // and applied the full span
                                if !sunk_arm_returns {
                                    fin_span_stop = t;
                                }
                            }
                        }
                    }
                }
            }
        }
        let mut finalbody = if let Some(ef) = early_fin {
            // ef is the FIRST nested level's inline copy (already walked).
            // When the walk now stands at a deeper level's inline copy
            // (stop > pos), decompile it as the outer finally and wrap
            // the inner try inside the body.
            if stop > pos {
                let walked = self.decompose_finally_span(pos, stop, None);
                if self.skip_until.map_or(true, |s| s < stop) {
                                        self.skip_until = Some(stop);
                }
                if !walked.is_empty() {
                    nested_inner_fin = Some(ef);
                    walked
                } else {
                    if self.skip_until.map_or(true, |s| s < stop) {
                                                self.skip_until = Some(stop);
                    }
                    ef
                }
            } else {
                if self.skip_until.map_or(true, |s| s < stop) {
                                        self.skip_until = Some(stop);
                }
                ef
            }
        } else if tc.finally_handler.is_some() && stop > pos && mirror_ok {
            // the span may hold a NESTED try whose own finally chain was
            // laid out inside it (nested try/finally around a yield in
            // 3.11+): decompose recursively instead of letting the region
            // walk re-open the nested TryCtx and tangle the chains. The
            // nested chain head is the first PUSH_EXC_INFO after the
            // span's outward exit jump.
            let nested_head = self
                .instrs
                .iter()
                .find(|x| {
                    x.offset >= pos && x.offset < stop && x.op == Op::PUSH_EXC_INFO
                })
                .map(|x| x.offset);
            let head = match nested_head {
                Some(nh) => {
                    // confirm an outward exit jump precedes it in the span
                    let has_exit = self.instrs.iter().any(|x| {
                        x.offset >= pos
                            && x.offset < nh
                            && matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                            && x.target.map_or(false, |t| t > nh)
                    });
                    if has_exit {
                        Some(nh)
                    } else {
                        tc.finally_handler
                    }
                }
                None => tc.finally_handler,
            };
            let mut span = self.decompose_finally_span(pos, fin_span_stop, head);
            if sunk_arm_returns {
                self.canon_not_cmp(&mut span);
                self.rebuild_sunk_elif(&mut span);
            }
            // the nested chain and its stubs are folded — never let the
            // main walk re-enter them
            if let Some(nh) = nested_head {
                if head == Some(nh) {
                    let skip_past = self.chain_extent(nh);
                    if self.skip_until.map_or(true, |s| s < skip_past) {
                                                self.skip_until = Some(skip_past);
                    }
                }
            }
            span
        } else {
            Vec::new()
        };
        if tc.finally_handler.is_some() && fin_span_stop > pos && mirror_ok {
            // main pass must not re-execute the inline finally body —
            // only when the mirror confirmed a copy exists at `pos`;
            // with no inline copy the flow there is the next source
            // statement (the enclosing else arm) and skipping strands it
            if self.skip_until.map_or(true, |s| s < fin_span_stop) {
                                self.skip_until = Some(fin_span_stop);
            }
        }
        // except handlers (out-of-line)
        let mut handlers = match tc.except_handler {
            Some(h) => self.parse_except_dispatch(h),
            None => Vec::new(),
        };
        // finally handler body (exception path duplicate) — only use it when
        // there was no inline finally body
        if finalbody.is_empty() {
            if let Some(fh) = tc.finally_handler {
                let body = self.decompile_region(fh, self.handler_region_end(fh));
                finalbody = body;
                // the chain-side render cannot see the arm terminators
                // (its RERAISEs emit no statement, so the if/elif arms
                // arrive as plain siblings). When the extension walk
                // validated an inline copy with sunk arm returns,
                // re-render the finally body from the INLINE copy and
                // rebuild the elif chain from those returns (code
                // 3.13/3.14 interact exitmsg: sibling ifs ran BOTH
                // writes when exitmsg was None)
                if sunk_arm_returns {
                    if let Some(s0) = sunk_copy_start {
                        let span_to = sunk_ext_stop.unwrap_or(fin_span_stop);
                        if span_to > s0 {
                            let mut span2 =
                                self.decompose_finally_span(s0, span_to, None);
                            self.canon_not_cmp(&mut span2);
                            self.rebuild_sunk_elif(&mut span2);
                            if !span2.is_empty() {
                                finalbody = span2;
                            }
                        }
                    }
                }
                // the finally body's INLINE copy may sit between the
                // (already-consumed) except chain and fh when the region
                // emit folded before the walk got there (a loop-carried
                // try/finally closing at its back edge): the mirror probe
                // at `pos` above saw the chain heads, not the copy, and
                // left no skip - the main walk then re-runs the copy and
                // the whole finally body renders AGAIN at function level
                // (code 3.13 interact: duplicated restore/exitmsg blocks
                // after the try). Probe from the current skip point: when
                // [s, fh) opcode-mirrors the chain at fh it IS the copy -
                // hop over it. Without a mirror the flow ahead is genuine
                // mainline (contextlib 3.12 __exit__'s always-raising body
                // has no copy and the next statement must keep walking).
                if fh > pos {
                    if self.idx_of.contains_key(&fh) {
                        // candidate copy starts: the current skip point
                        // (or pos), and the ends of any except chains
                        // wedged between pos and fh - a loop-carried
                        // try/finally folds its region at the loop's
                        // back edge BEFORE the chain-extent skip is
                        // armed, so the copy start must be discovered
                        // from the inner chain's extent (code 3.13
                        // interact: copy at chain_extent(930)=1140)
                        let mut starts = vec![self
                            .skip_until
                            .filter(|&sk| sk > pos && sk < fh)
                            .unwrap_or(pos)];
                        // the inner regions were already emitted (and
                        // removed from try_ctxs) by the time a loop-
                        // carried finally folds - enumerate the chain
                        // heads lexically instead: every PUSH_EXC_INFO
                        // in (pos, fh) whose extent lands inside the gap
                        for x in self.instrs.iter() {
                            if x.offset <= pos || x.offset >= fh {
                                continue;
                            }
                            if x.op == Op::PUSH_EXC_INFO {
                                let ext = self.chain_extent(x.offset);
                                if ext > pos && ext < fh && !starts.contains(&ext) {
                                    starts.push(ext);
                                }
                            }
                        }
                        if let Some(&s0) = starts
                            .iter()
                            .find(|&&s0| self.finally_copy_mirror(s0, fh))
                        {
                            if self.skip_until.map_or(true, |sk| sk < fh) {
                                self.skip_until = Some(fh);
                                self.fin_copy_guard = Some((s0, fh));
                            }
                        }
                    }
                }
            }
        }
        // 3.11+ `try: return <expr> finally: <cleanup>`: the protected
        // region holds ONLY the value loads (region_end == body_end),
        // the inline finally copy follows, and the RETURN sits right
        // after it (fin_span_stop). The walk leaves the value on the
        // stack and would emit the Return AFTER the Try (cProfile
        // 3.11-3.13 runcall rendered `try: pass finally: disable()` +
        // `return func(...)` — semantically wrong: disable ran before
        // the call). Fold the return into the body and hop the walk
        // past it.
        if self.version.at_least(3, 11)
            && tc.except_handler.is_none()
            && tc.region_end == tc.body_end
            && fin_span_stop > pos
        {
            let ret_end = self.idx_of.get(&fin_span_stop).and_then(|&ri| {
                let r = &self.instrs[ri];
                if r.op == Op::RETURN_VALUE {
                    Some(r.end())
                } else {
                    None
                }
            });
            if let Some(ret_end) = ret_end {
                let body_empty = self
                    .pending_try_body
                    .last()
                    .map_or(true, |b| b.is_empty());
                if body_empty
                    && matches!(self.stack.last(), Some(Sv::E(_)))
                {
                    if let Some(Sv::E(v)) = self.stack.pop() {
                        if let Some(body) = self.pending_try_body.last_mut() {
                            body.push(Stmt::Return(Some(v)));
                        }
                        if self.skip_until.map_or(true, |sk| sk < ret_end) {
                            self.skip_until = Some(ret_end);
                        }
                    }
                }
            }
        }
        let mut body = self.pending_try_body.pop().unwrap_or_default();
        // 3.12+ with-wrapped try: the body's tail `return None` sits in
        // the gap between body_end and the chain head, AFTER the inline
        // with success-exit sequence (POP_EXCEPT; LOAD None ×3; CALL;
        // POP_TOP; RETURN_CONST None — codeop 3.13 _maybe_compile inner
        // try). The region ended before it, so the walk would leak it
        // (or drop it at a sub-walk bound). RETURN_CONST-only: the 3.11
        // LOAD None; RETURN_VALUE form is indistinguishable from a sunk
        // post-try continuation (c4f3cc0 lesson)
        if self.version.at_least(3, 11)
            && self.code.name != "<module>"
            && tc.finally_handler.is_none()
            && tc.region_end == tc.body_end
            && orelse.is_empty()
            && !matches!(body.last(), Some(Stmt::Return(_)))
        {
            if let (Some(h), Some(&bi)) =
                (tc.except_handler, self.idx_of.get(&tc.body_end))
            {
                let mut k = bi;
                let mut ret_at = None;
                let mut ok = true;
                let mut saw_exit = false;
                while k < self.instrs.len() {
                    let x = &self.instrs[k];
                    if x.offset >= h {
                        break;
                    }
                    match x.op {
                        Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::POP_EXCEPT => {
                            k += 1;
                        }
                        Op::RETURN_CONST if matches!(
                            self.code.consts.get(x.arg as usize).map(|o| &**o),
                            Some(PyObject::None)
                        ) => {
                            ret_at = Some(x.end());
                            k += 1;
                            break;
                        }
                        // 3.11 sunk shape: LOAD None; RETURN_VALUE — only
                        // unambiguous right after a consumed inline with
                        // exit (the bare form is the c4f3cc0 sunk-
                        // continuation lookalike)
                        Op::RETURN_VALUE if saw_exit
                            && k > 0
                            && self.instrs[k - 1].op == Op::LOAD_CONST
                            && matches!(
                                self.code
                                    .consts
                                    .get(self.instrs[k - 1].arg as usize)
                                    .map(|o| &**o),
                                Some(PyObject::None)
                            ) => {
                            ret_at = Some(x.end());
                            k += 1;
                            break;
                        }
                        Op::LOAD_CONST if saw_exit
                            && matches!(
                                self.code.consts.get(x.arg as usize).map(|o| &**o),
                                Some(PyObject::None)
                            )
                            && self.instrs.get(k + 1).map(|i2| i2.op)
                                == Some(Op::RETURN_VALUE) =>
                        {
                            // 3.11 sunk `return None`: LOAD None; RETURN
                            // right after the consumed exit
                            ret_at = Some(self.instrs[k + 1].end());
                            k += 2;
                            break;
                        }
                        Op::LOAD_CONST => {
                            // inline with-exit sequence only
                            match self.inline_with_exit_span(x.offset) {
                                Some(after) => {
                                    let ai = self
                                        .idx_of
                                        .get(&after)
                                        .copied()
                                        .unwrap_or(k);
                                    if ai <= k {
                                        ok = false;
                                        break;
                                    }
                                    saw_exit = true;
                                    k = ai;
                                }
                                None => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        _ => {
                            ok = false;
                            break;
                        }
                    }
                }
                // the gap past the return must be only pads
                if ok {
                    if let Some(re) = ret_at {
                        let rest_pad = self
                            .idx_of
                            .get(&re)
                            .map_or(true, |&ri2| {
                                self.instrs[ri2..]
                                    .iter()
                                    .take_while(|x| x.offset < h)
                                    .all(|x| {
                                        matches!(
                                            x.op,
                                            Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                        )
                                    })
                            });
                        if rest_pad {
                            body.push(Stmt::Return(None));
                            if self.skip_until.map_or(true, |s2| s2 < re) {
                                self.skip_until = Some(re);
                            }
                        }
                    }
                }
            }
        }
        // 3.12+ shared fall-through terminator: a post-try `raise X`
        // (function's last statement) is compiled into BOTH exits — the
        // body-side sunk copy at [body_end, handler_head) and the
        // handler-side copy the bare clause falls through to after its
        // POP_EXCEPT (no exit jump). The clause body parse swallows the
        // handler-side copy (`except: raise X`) while the body-side copy
        // walks as a post-Try statement — rendering the raise twice.
        // When the two runs mirror, the clause is `pass`: drop its body;
        // if the body-side copy was already collected into `body` (emit
        // fired late), move it out so it lands AFTER the Try
        // (_sitebuiltins 3.12 Quitter.__call__).
        if let Some(h) = tc.except_handler {
            if h > tc.body_end && self.mirrored_clause_terminator(tc.body_end, h) {
                if let Some(lasth) = handlers.last_mut() {
                    if lasth.type_.is_none()
                        && lasth.name.is_none()
                        && matches!(lasth.body.last(), Some(Stmt::Raise { .. }))
                    {
                        lasth.body.clear();
                    }
                }
                if matches!(body.last(), Some(Stmt::Raise { exc: Some(_), .. })) {
                    let stmt = body.pop().unwrap();
                    self.pending_post_chain_stmt = Some(stmt);
                }
            }
        }
        // nested-chain wrap: this region's body IS the inner try's body —
        // nest it, and adopt the enclosing finally parsed alongside
        if !self.nested_inner_handlers.is_empty() {
            // the recursive parse descends OUTWARD: the first pushed
            // level holds the innermost chain's clauses (they protect the
            // shared body) — wrap in push order so each level becomes the
            // next one's body
            for ih in self.nested_inner_handlers.drain(..) {
                let inner = Stmt::Try {
                    body: std::mem::take(&mut body),
                    handlers: ih,
                    orelse: Vec::new(),
                    finalbody: Vec::new(),
                };
                body = vec![inner];
            }
            if let Some(fin) = self.pending_nested_finally.take() {
                if finalbody.is_empty() {
                    finalbody = fin;
                }
            }
        }
        self.pending_nested_finally = None;
        // try/except/else WITHOUT finally (3.11+): the else body lies inline
        // between the try body (body_end) and the handler, ending in a
        // JUMP_FORWARD to the merge point past the handler. It is NOT covered
        // by the exception table, so region_end == body_end and the else
        // capture above (region_end > body_end) missed it; the body sits
        // AHEAD of pos, un-walked. Detect and decompile it here, then skip to
        // the merge so the walk doesn't re-emit it at top level.
        if orelse.is_empty()
            && tc.finally_handler.is_none()
            && tc.region_end == tc.body_end
        {
            if let Some(handler) = tc.except_handler {
                if let Some(&bi) = self.idx_of.get(&tc.body_end) {
                    // Skip WITH-statement protection regions: a `with` inside
                    // the try splits the protected range around BEFORE_WITH /
                    // the __exit__ call, and those regions also reach here.
                    // The with's own exit jump targets the SAME merge point
                    // as the handler chain (chain_extent), so target matching
                    // can't tell them apart — detect the with protocol ops in
                    // the region instead. A real try/except/else body never
                    // contains the with protocol.
                    let is_with_region = self.instrs.iter().any(|x| {
                        matches!(x.op, Op::BEFORE_WITH | Op::WITH_EXCEPT_START)
                            && x.offset >= tc.start
                            && x.offset < handler
                    });
                    // Recover the MERGE point where the try-success path and
                    // the handler both converge. Two layouts:
                    //  * out-of-line handler (3.12+): the handler is laid out
                    //    AFTER the post-try code and rejoins it with a
                    //    BACKWARD jump whose target lands in (body_end,
                    //    handler); the else body falls through to that merge
                    //    with no delimiting jump.
                    //  * inline handler: the else body ends in a JUMP_FORWARD
                    //    to the merge, which is the handler chain's extent.
                    // The else body is [body_end, merge). Guard: no with-
                    // protocol op in it (a `with` in the try is its own stmt).
                    let chain_end = self.chain_extent(handler);
                    // 3.12 relocated chains: the clause-exit jump (the
                    // backward rejoin that delimits the else span) sits
                    // PAST chain_extent's stop, inside the chain's own
                    // exit/stub tail — bound the merge scan at the next
                    // chain head instead so the exit jump is visible
                    // (code 3.12 showsyntaxerror: JUMP_BACKWARD 218->146
                    // lies after extent 216; without it the inner
                    // try/except ValueError/else flattened and the
                    // re-wrap ran even on the pass path)
                    let mut scan_end = chain_end;
                    if let Some(&hi) = self.idx_of.get(&handler) {
                        for x in &self.instrs[hi..] {
                            if x.offset > chain_end
                                // PUSH_EXC_INFO only: a misclassified
                                // cleanup stub in chain_heads let the
                                // window drift into the next real chain
                                // (cmd 3.12 cmdloop: the EOFError try
                                // matched the KeyboardInterrupt chain's
                                // resume JB 1652->546 as its else merge)
                                && x.op == Op::PUSH_EXC_INFO
                            {
                                scan_end = x.offset;
                                break;
                            }
                        }
                    }
                    // hard cap: never scan past this chain's own
                    // exit/stub tail into a LATER sibling chain — its
                    // resume jump targets the sibling's continuation
                    // and misreads as THIS try's else merge (code 3.12
                    // interact: the ps1 try swallowed the ps2 try as a
                    // phantom else via the ps2 chain's JB 544->70)
                    // stub_tail_end: the vetted end of the chain's own
                    // exit/stub material — the else-end jump may fly
                    // over the trailing cleanup stub to the true merge
                    // right past chain_extent's stop (compileall 3.11
                    // compile_file: else JF 2266->2918, stub COPY;
                    // POP_EXCEPT; RERAISE at 2912-2916)
                    let mut stub_tail_end = chain_end;
                    if let Some(&hi) = self.idx_of.get(&handler) {
                        let mut tail_end = chain_end;
                        for x in &self.instrs[hi..] {
                            if x.offset < chain_end {
                                continue;
                            }
                            if matches!(
                                x.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_FORWARD
                                    | Op::JUMP
                                    | Op::RERAISE
                                    | Op::COPY
                                    | Op::SWAP
                                    | Op::POP_EXCEPT
                                    | Op::POP_TOP
                                    | Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::END_FINALLY
                            ) {
                                tail_end = x.end();
                            } else {
                                break;
                            }
                        }
                        stub_tail_end = tail_end;
                        scan_end = scan_end.min(tail_end);
                    }
                    // the chain's own resume jump can sit exactly AT the
                    // extent boundary (copyreg 3.12 _reduce_ex: POP_EXCEPT
                    // @710; JUMP_BACKWARD 712->510, extent=712) — the
                    // tail-cleanup walk already vetted it as chain
                    // material, so admit the single jump instruction
                    if let Some(&si) = self.idx_of.get(&scan_end) {
                        let x = &self.instrs[si];
                        if x.is_backward
                            && matches!(
                                x.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                            )
                        {
                            scan_end = x.end();
                        }
                    }
                    // The try body may be FRAGMENTED into several exception
                    // -table regions sharing this handler (3.12+ inlines a
                    // comprehension in the try body as its own region). The
                    // handler's backward jump can then target an earlier
                    // fragment (comprehension unwinding), NOT an else merge.
                    // A genuine out-of-line else merge lies AFTER the whole
                    // try body — i.e. after the last fragment targeting this
                    // handler — because the try-success path runs every
                    // fragment, then the else, then merges.
                    let last_frag_end = self
                        .try_ctxs
                        .values()
                        .filter(|t| t.except_handler == Some(handler))
                        .map(|t| t.body_end)
                        .max()
                        .unwrap_or(tc.body_end);
                    // the genuine else rejoin is the chain's LAST
                    // backward jump: every clause's normal exit resumes
                    // the mainline at the SAME merge, and the final
                    // clause's exit is the last one before the mismatch
                    // stubs — a FIRST match picks an earlier clause's
                    // resume or a misclassified sibling stub-tail jump
                    // (cmd 3.12 cmdloop: the EOFError try grew a phantom
                    // else holding the elif chain's else arm)
                    let backward_merge = self
                        .instrs
                        .iter()
                        .filter(|x| x.offset >= handler)
                        // the rejoin jump belongs to THIS handler's own
                        // chain: a LATER sibling try's chain also holds a
                        // backward resume jump (its target lands between
                        // this body_end and this handler when the tries
                        // are sequential at module level) and misreads as
                        // an else merge, swallowing the code between the
                        // tries into a phantom else region
                        .filter(|x| x.offset < scan_end)
                        .filter(|x| {
                            // 3.14 rejoins the mainline with
                            // JUMP_BACKWARD_NO_INTERRUPT; the t < handler
                            // bound excludes await-resume JBNIs (their
                            // targets lie inside the chain region)
                            matches!(
                                x.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                            ) && x.target.map_or(false, |t| {
                                t > last_frag_end
                                    && t < handler
                                    // a 3.12+ handler clause's `break`
                                    // is POP_EXCEPT; JUMP_BACKWARD to
                                    // the LOOP EXIT from inside the
                                    // chain — its target satisfies the
                                    // mainline bounds, and reading it
                                    // as the else rejoin swallows the
                                    // enclosing If's whole else arm
                                    // into a phantom try-else
                                    // (_compression 3.12 read). The
                                    // genuine chain-end mainline rejoin
                                    // (3.14 JBNI, _ios_support/abc
                                    // import guards) targets plain
                                    // mainline flow, never a loop exit.
                                    && self.find_loop_exit(t).is_none()
                                    // the body's own exit jump flying to
                                    // the SAME target means the success
                                    // path skips the span entirely — the
                                    // span is an enclosing branch's arm,
                                    // not this try's else (cmd 3.12
                                    // cmdloop: the EOFError try's body
                                    // ends in JF 546->788 and the clause
                                    // exit JB 1104->788; the span
                                    // [546,788) is the elif chain's else
                                    // arm and rendered as a phantom
                                    // try-else)
                                    && !self
                                        .idx_of
                                        .get(&tc.body_end)
                                        .map_or(false, |&bj| {
                                            let x = &self.instrs[bj];
                                            matches!(
                                                x.op,
                                                Op::JUMP_FORWARD
                                                    | Op::JUMP
                                                    | Op::JUMP_NO_INTERRUPT
                                            ) && !x.is_backward
                                                && x.target == Some(t)
                                        })
                                    // a resume hop off a CLEANUP_THROW
                                    // trampoline re-enters a suspended
                                    // await/yield-from in the MIDDLE of
                                    // an enclosing loop body - it is
                                    // protocol continuation, not an
                                    // else merge (compileall 3.13
                                    // _walk_dir: the generator's
                                    // trampoline JBNI->734 claimed the
                                    // whole for-loop span as a phantom
                                    // try-else and the main walk
                                    // skipped the loop)
                                    && !self.idx_of.get(&x.offset).map_or(
                                        false,
                                        |&xi| {
                                            xi > 0
                                                && self.instrs[xi - 1].op
                                                    == Op::CLEANUP_THROW
                                        },
                                    )
                                    // the try body ends ON a backward
                                    // jump out of the body's own start:
                                    // a loop's fused back edge - the
                                    // success path ITERATES, it cannot
                                    // also run an else arm, and the
                                    // span [body_end, t) is the loop
                                    // tail plus sibling code, not an
                                    // else region (_osx_support 3.12
                                    // compiler_fixup: `except
                                    // ValueError: break` exits to the
                                    // enclosing if/elif merge and the
                                    // whole `elif _supports_arm64_
                                    // builds():` branch was swallowed
                                    // into a phantom try-else inside
                                    // the while loop). Await-resume
                                    // JBNIs land INSIDE the body
                                    // (target >= the try's start), so
                                    // the body-start bound keeps them.
                                    && !self
                                        .idx_of
                                        .get(&tc.body_end)
                                        .map_or(false, |&bj| {
                                            let x = &self.instrs[bj];
                                            x.is_backward
                                                && matches!(
                                                    x.op,
                                                    Op::JUMP_BACKWARD
                                                        | Op::JUMP_ABSOLUTE
                                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                )
                                                && x.target
                                                    .map_or(false, |bt| {
                                                        bt < tc.body_end
                                                            && self.is_loop_top_target(bt)
                                                    })
                                        })
                            })
                        })
                        .filter_map(|x| x.target)
                        .last();
                    let merge = if let Some(m) = backward_merge {
                        Some((m, m))
                    } else {
                        // the handler's own resume hop: chain_end can be
                        // a forward jump whose target is the true
                        // mainline merge (copyreg 3.11 _reduce_ex: the
                        // else arm's JF@486 targets 662 = the resume
                        // JF@652's target, not chain_end itself)
                        let resume_hop = self
                            .idx_of
                            .get(&chain_end)
                            .and_then(|&ci3| self.instrs.get(ci3))
                            .and_then(|x| {
                                (matches!(
                                    x.op,
                                    Op::JUMP_FORWARD | Op::JUMP
                                ) && !x.is_backward)
                                    .then_some(x.target)
                            })
                            .flatten();
                        let mut j = bi;
                        let mut found = None;
                        while !is_with_region && j < self.instrs.len() {
                            let x = self.instrs[j];
                            if x.offset >= handler {
                                break;
                            }
                            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                && !x.is_backward
                                && (x.target == Some(chain_end)
                                    || resume_hop.is_some()
                                        && x.target == resume_hop)
                            {
                                found = Some((x.offset, chain_end));
                                break;
                            }
                            // the else-end jump may fly over the chain's
                            // trailing cleanup stub (COPY; POP_EXCEPT;
                            // RERAISE) to the true merge right past it -
                            // the stub-tail walk already vetted
                            // (chain_end, scan_end] as chain material, so
                            // a forward jump landing there delimits the
                            // else span and its target is the walk's
                            // resume (compileall 3.11 compile_file: the
                            // else JF 2266->2918 missed chain_extent's
                            // stub-head stop 2912, the `else: if ok == 0:`
                            // clause flattened past the try and ran on
                            // the exception paths with ok unbound)
                            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                && x.target.map_or(false, |t| {
                                    t > chain_end && t <= stub_tail_end
                                })
                            {
                                found = Some((x.offset, x.target.unwrap()));
                                break;
                            }
                            j += 1;
                        }
                        found
                            .or_else(|| {
                                // function-tail try with the implicit
                                // `return None` SUNK into both exits
                                // (3.11+): no jump delimits the else —
                                // the success-side return copy itself is
                                // the boundary and the skip target is the
                                // chain end (the copy and the chain are
                                // both machinery)
                                let mut pair = self.try_tail_sunk_pair(
                                    last_frag_end.max(tc.body_end),
                                    handler,
                                    chain_end,
                                );
                                if pair.is_none()
                                    && self.version.at_least(3, 11)
                                    && !self.version.at_least(3, 12)
                                {
                                    // 3.11 ONLY — the try is the loop
                                    // body's LAST statement: the inline
                                    // else arm ends with the loop's
                                    // fused back edge (backward jump
                                    // onto the loop top) instead of a
                                    // merge jump (csv 3.11 has_header:
                                    // else arm `hasHeader -= 1;
                                    // JB->for-top` flattened past the
                                    // try and the except arm grew a
                                    // `continue`). Require a NON-EMPTY
                                    // span: a plain try/except at the
                                    // loop tail has the back edge AT
                                    // body_end and no else. 3.12+
                                    // relocates chains and narrows
                                    // protected ranges differently —
                                    // the span test misfires there
                                    // (_compression/_weakrefset/bz2
                                    // 3.12 grew phantom elses).
                                    let mut j2 = bi;
                                    while j2 < self.instrs.len() {
                                        let x = &self.instrs[j2];
                                        if x.offset >= handler
                                            || x.op == Op::PUSH_EXC_INFO
                                        {
                                            break;
                                        }
                                        if x.is_backward
                                            && matches!(
                                                x.op,
                                                Op::JUMP_BACKWARD
                                                    | Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            )
                                            && x.target.map_or(false, |t| {
                                                self.is_loop_top_target(t)
                                            })
                                            && x.offset > tc.body_end
                                        {
                                            // the span must be a real
                                            // else arm FALLING THROUGH
                                            // to the fused back edge: a
                                            // RETURN inside it means the
                                            // span is a value-return
                                            // tail the protected range
                                            // stopped short of (3.11
                                            // narrows at the RETURN),
                                            // not an else arm (bdb 3.11
                                            // effective: the shared
                                            // `return b, True` tail
                                            // SWAP; POP_TOP; RETURN
                                            // read as a phantom else
                                            // and underflowed the
                                            // value stack)
                                            let has_ret = self
                                                .instrs
                                                .iter()
                                                .skip_while(|y| {
                                                    y.offset < tc.body_end
                                                })
                                                .take_while(|y| {
                                                    y.offset < x.offset
                                                })
                                                .any(|y| {
                                                    matches!(
                                                        y.op,
                                                        Op::RETURN_VALUE
                                                            | Op::RETURN_CONST
                                                    )
                                                });
                                            if has_ret {
                                                break;
                                            }
                                            pair = Some((x.offset, x.end()));
                                            break;
                                        }
                                        j2 += 1;
                                    }
                                }
                                if pair.is_some() {
                                    // the pair is confirmed: the handler-
                                    // side sunk copy (3.11 extends the
                                    // clause body over `LOAD None;
                                    // RETURN_VALUE`) is machinery too —
                                    // drop it from the last clause
                                    if let Some(h) = handlers.last_mut() {
                                        if matches!(h.body.last(), Some(Stmt::Return(None))) {
                                            h.body.pop();
                                        }
                                    }
                                }
                                pair
                            })
                            .or_else(|| {
                                // SUNK VALUE-RETURN MIRROR (3.12+): the
                                // chain's last clause ends
                                // POP_EXCEPT; <value ops>; RETURN_VALUE
                                // with NO resume jump - the handler path
                                // RETURNS through a sunk copy of the
                                // function's tail return - and the
                                // mainline carries the identical
                                // instruction sequence: that sequence is
                                // the tail, and the inline else arm is
                                // the span between the try body and the
                                // tail (contextlib 3.12-3.14
                                // push_async_exit: try/except/else +
                                // tail `return exit`; the sunk copy
                                // rendered as a sibling return BEFORE
                                // the else arm and the arm stranded at
                                // top level)
                                self.sunk_return_mirror_merge(
                                    tc.body_end,
                                    handler,
                                    chain_end,
                                )
                            })
                    };
                    // the mirror detector matched: the handler's sunk
                    // copy of the tail return is redundant - the
                    // mainline walk resumes AT the mirror and emits the
                    // tail once. Drop the split-out sunk statements or
                    // the tail renders twice (contextlib 3.13
                    // push_async_exit: `return exit` emitted after the
                    // try AND after the else arm)
                    if self
                        .sunk_return_mirror_merge(tc.body_end, handler, chain_end)
                        .is_some()
                    {
                        self.handler_sunk_tail.clear();
                    }
                    if let Some((else_end, merge)) = merge {
                        if else_end > tc.body_end && !is_with_region {
                            let has_with = self.instrs.iter().any(|x| {
                                matches!(
                                    x.op,
                                    Op::BEFORE_WITH | Op::WITH_EXCEPT_START
                                ) && x.offset >= tc.body_end
                                    && x.offset < else_end
                            });
                            if !has_with {
                                // the recovered "else" holding ONLY a bare
                                // `return None` is the try body's own tail
                                // return: 3.12 excludes the non-raising
                                // RETURN from the protected range, so it
                                // lands in [body_end, merge) and mimics an
                                // else (chunk.skip). Fold it back into the
                                // body - it recompiles to the identical
                                // narrowed range. A genuine `else: return`
                                // with the same shape also recompiles
                                // identically, so the fold is sig-safe.
                                let bare_tail_return = {
                                    let be = self.idx_of.get(&tc.body_end).copied();
                                    let ee = self.idx_of.get(&else_end).copied();
                                    match (be, ee) {
                                        (Some(b), Some(e)) if e > b => {
                                            let mut rets = 0;
                                            let mut only = true;
                                            for x in &self.instrs[b..e] {
                                                match x.op {
                                                    Op::NOP | Op::NOT_TAKEN
                                                    | Op::CACHE => {}
                                                    Op::RETURN_CONST => {
                                                        rets += 1;
                                                        if !matches!(
                                                            self.code
                                                                .consts
                                                                .get(x.arg as usize)
                                                                .map(|o| &**o),
                                                            Some(PyObject::None)
                                                        ) {
                                                            only = false;
                                                        }
                                                    }
                                                    Op::RETURN_VALUE => {
                                                        rets += 1;
                                                    }
                                                    _ => {
                                                        only = false;
                                                    }
                                                }
                                            }
                                            only && rets == 1
                                        }
                                        _ => false,
                                    }
                                };
                                if bare_tail_return {
                                    body.push(Stmt::Return(None));
                                } else {
                                    // 3.14 narrows protected ranges at
                                    // value-construction boundaries: the
                                    // else region can START on a guard
                                    // jump whose operand loads sit inside
                                    // the protected range (_py_warnings
                                    // warn: `if frame is None: raise`
                                    // split between LOAD_FAST_BORROW and
                                    // POP_JUMP_IF_NONE - the region
                                    // sub-walk popped an empty stack).
                                    // Extend the region start back over a
                                    // bounded pure-value prologue when
                                    // the first instruction consumes a
                                    // value, and drop the main walk's
                                    // duplicate pushes (the sub-walk
                                    // re-materializes them).
                                    let consumes = |off: usize| -> bool {
                                        self.idx_of.get(&off).map_or(false, |&i| {
                                            matches!(
                                                self.instrs[i].op,
                                                Op::POP_JUMP_IF_NONE
                                                    | Op::POP_JUMP_IF_NOT_NONE
                                                    | Op::POP_JUMP_FORWARD_IF_NONE
                                                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                                                    | Op::POP_JUMP_BACKWARD_IF_NONE
                                                    | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                                                    | Op::POP_JUMP_IF_TRUE
                                                    | Op::POP_JUMP_IF_FALSE
                                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                                    | Op::JUMP_IF_TRUE
                                                    | Op::JUMP_IF_FALSE
                                                    | Op::POP_TOP
                                                    | Op::TO_BOOL
                                                    | Op::IS_OP
                                                    | Op::CONTAINS_OP
                                            )
                                        })
                                    };
                                    let mut region_from = tc.body_end;
                                    let mut net_push = 0usize;
                                    if else_end > tc.body_end
                                        && consumes(tc.body_end)
                                    {
                                        if let Some(&bi) =
                                            self.idx_of.get(&tc.body_end)
                                        {
                                            let mut k = bi;
                                            let mut steps = 0;
                                            while k > 0 && steps < 8 {
                                                let p = &self.instrs[k - 1];
                                                if p.offset < tc.start
                                                    || !is_pure_value_op(p.op)
                                                {
                                                    break;
                                                }
                                                k -= 1;
                                                steps += 1;
                                                net_push += matches!(
                                                    p.op,
                                                    Op::LOAD_FAST
                                                        | Op::LOAD_FAST_CHECK
                                                        | Op::LOAD_FAST_BORROW
                                                        | Op::LOAD_FAST_LOAD_FAST
                                                        | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                                                        | Op::LOAD_SMALL_INT
                                                        | Op::LOAD_COMMON_CONSTANT
                                                        | Op::LOAD_NAME
                                                        | Op::LOAD_GLOBAL
                                                        | Op::LOAD_CONST
                                                        | Op::LOAD_DEREF
                                                        | Op::LOAD_CLASSDEREF
                                                        | Op::PUSH_NULL
                                                ) as usize;
                                                net_push = net_push.saturating_sub(
                                                    matches!(p.op, Op::POP_TOP)
                                                        as usize,
                                                );
                                            }
                                            if steps > 0
                                                && self.instrs[k].offset
                                                    < tc.body_end
                                            {
                                                region_from =
                                                    self.instrs[k].offset;
                                            }
                                        }
                                    }
                                    if region_from < tc.body_end {
                                        for _ in 0..net_push {
                                            self.stack.pop();
                                        }
                                    }
                                    orelse = self
                                        .decompile_region(region_from, else_end);
                                }
                                if self.skip_until.map_or(true, |s| s < merge) {
                                                                        self.skip_until = Some(merge);
                                }
                            }
                        }
                    }
                }
            }
        }
        if handlers.is_empty() && finalbody.is_empty() && orelse.is_empty() && body.is_empty()
        {
            return;
        }
        // A bare `return` (Return(None)) trailing a value `return X` in the
        // body is unreachable dead code — the nested-try-return relaxation
        // (RETURN-in-try handler now firing for an if-nested `try: return
        // X except E: ..`) can leave the function's sunk tail return
        // appended after the body's own return. Strip it (safe: nothing
        // after a value return executes).
        if body.len() >= 2
            && matches!(body.last(), Some(Stmt::Return(None)))
            && matches!(
                body.get(body.len() - 2),
                Some(Stmt::Return(Some(_))) | Some(Stmt::Raise { .. })
            )
        {
            body.pop();
        }
        if let Some(inner_fin) = nested_inner_fin.take() {
            // two nested finally levels merged into one region: the body
            // plus the first level's copy form the inner try
            let inner = Stmt::Try {
                body,
                handlers,
                orelse,
                finalbody: inner_fin,
            };
            self.push_stmt(Stmt::Try {
                body: vec![inner],
                handlers: Vec::new(),
                orelse: Vec::new(),
                finalbody,
            });
        } else {
            self.push_stmt(Stmt::Try {
                body,
                handlers,
                orelse,
                finalbody,
            });
        }
        let sunk_tail = std::mem::take(&mut self.handler_sunk_tail);
        if !sunk_tail.is_empty() {
            self.push_stmt_all(sunk_tail);
        }
        let star_tail = std::mem::take(&mut self.star_tail);
        if !star_tail.is_empty() {
            self.push_stmt_all(star_tail);
            // 3.11 lays the resume out AFTER the chain(s): the main walk
            // would re-execute it — skip past the span we just folded
            if let Some(se) = self.star_tail_end.take() {
                if self.skip_until.map_or(true, |s| s < se) {
                                        self.skip_until = Some(se);
                }
            }
        } else {
            self.star_tail_end = None;
        }
    }

    /// Linearly decompile the instruction range [from, to), returning its
    /// statements. Used for out-of-line handler regions (finally bodies).
    fn decompile_region(&mut self, from: usize, to: usize) -> Vec<Stmt> {
        let Some(&fi) = self.idx_of.get(&from) else {
            return Vec::new();
        };
        let saved_blocks = std::mem::replace(
            &mut self.blocks,
            vec![Block::new(BlockType::Main, from, to)],
        );
        let saved_stack = std::mem::take(&mut self.stack);
        let saved_skip = self.skip_until;
        let saved_try_tail = self.pending_try_tail.take();
        let saved_post_chain = self.pending_post_chain_stmt.take();
        let saved_active_try = self.active_try.take();
        let saved_active_stack = std::mem::take(&mut self.active_try_stack);
        let saved_cur = (self.cur_offset, self.cur_next);
        let saved_prev = (self.prev_op, self.prev_op_at_exec);
        // an outer walk's skip range must not swallow this region's
        // instructions — the span walk starts with clean skip state
        self.skip_until = None;
        let saved_line = self.cur_line;
        let saved_collect = self.region_collect_only;
        let saved_stores = std::mem::take(&mut self.pending_stores);
        // whether a legacy chain was already live on entry: only a
        // chain CREATED inside this sub-walk runs the state machine
        // during the walk and folds its open clause at the end
        let chain_on_entry = self.legacy_try.is_some() || self.legacy_handler.is_some();

        let mut pc = fi;
        while pc < self.instrs.len() {
            let inst = self.instrs[pc];
            if inst.offset >= to {
                break;
            }
            let pos = inst.offset;
            if let Some(skip) = self.skip_until {
                if pos < skip {
                    pc += 1;
                    continue;
                }
                self.skip_until = None;
            }
            self.cur_offset = pos;
            self.cur_next = inst.end();
            if let Some(l) = inst.line {
                self.cur_line = Some(l);
            }
            // nested tries inside a handler body open from the same table
            self.open_exception_blocks(pos);
            // a nested out-of-line chain head reached LINEARLY (the
            // nested try's tail emission parsed but did not skip it):
            // executing PUSH_EXC_INFO/CHECK_EXC_MATCH as statements
            // leaks the clause head as garbage (copyreg 3.12
            // _reduce_ex: `if AttributeError: None; dict = None`) —
            // skip the whole chain region like the main walk does
            if self.chain_heads.contains(&pos)
                && inst.op == Op::PUSH_EXC_INFO
                // EXCEPT-dispatch chains only: a finally chain head
                // reached by a region sub-walk is walked/parsed by the
                // finally machinery (b15 break_in_try: the loop-break
                // finally copy lost f1/f2 when skipped)
                && self.try_ctxs.values().any(|tc| {
                    tc.except_handler == Some(pos)
                        && tc.finally_handler != Some(pos)
                })
                && self
                    .pending_try_ctx
                    .as_ref()
                    .map_or(true, |tc| tc.except_handler != Some(pos))
            {
                let mut after = self.chain_extent(pos);
                loop {
                    let tramp = self
                        .idx_of
                        .get(&after)
                        .and_then(|&ti| self.instrs.get(ti))
                        .map(|x| {
                            matches!(
                                x.op,
                                Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::NOT_TAKEN
                            ) && x.target.map_or(false, |t| t > x.offset)
                        })
                        .unwrap_or(false);
                    if !tramp {
                        break;
                    }
                    let ti = self.idx_of[&after];
                    let t = self.instrs[ti].target.unwrap();
                    if t <= after {
                        break;
                    }
                    after = t;
                }
                self.close_blocks_at(pos);
                if after > pos {
                    self.skip_until = Some(after);
                }
                pc += 1;
                continue;
            }
            // pre-3.11: a skipped NESTED handler chain parses with the same
            // state machine as the main walk (finally-body and 3.11+ handler
            // regions must NOT drive it — the outer chain state is live)
            if self.legacy_nest_depth > 0
                || (!chain_on_entry && self.legacy_try.is_some())
            {
                self.legacy_chain_step(&inst);
            }
            // nested tail emission may have moved cur_offset — restore
            self.cur_offset = pos;
            self.cur_next = inst.end();
            self.close_blocks_at(pos);
            // keep prev_op_at_exec meaningful inside the sub-walk —
            // value-merge detection (COPY/TO_BOOL before the guard's
            // cond jump) reads it, and a stale main-walk value loses
            // the boolop (_colorize 3.13 can_colorize `return A and B`
            // in an except clause rendered as a statement If)
            let prev = self.prev_op;
            self.prev_op_at_exec = prev;
            if !self.exec(&inst) {
                if std::env::var("PYCDC_TRACE").is_ok() {
                    eprintln!("AW BREAK at {} {:?}", pos, inst.op);
                }
                break;
            }
            if !matches!(inst.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE) {
                self.prev_op = Some(inst.op);
            }
            pc += 1;
        }
        self.flush_pending_stores();
        // a clause opened inside this sub-walk must collect before the
        // region returns: the walk can skip the END_FINALLY / mismatch
        // point where the main walk would fold it (the handler-exit
        // jump arms skip_until past it, and without this the region's
        // tail statements redirect into the still-open handler body —
        // _collections_abc 3.5-3.7 index: the loop-tail `i += 1`
        // landed inside `except IndexError: break`). A chain that
        // predates the region belongs to the caller's own fold path.
        // legacy_nest_depth > 0: a nested-chain region is managed by
        // parse_skipped_nested_chain's own post-region collection (its
        // begin_legacy_nest stashes the outer chain, so chain_on_entry
        // reads false here) — flushing early reorders the clause fold
        // and breaks the nested else/finally rebuild (b05_exceptions)
        if !chain_on_entry
            && self.legacy_nest_depth == 0
            && self.legacy_handler.is_some()
        {
            self.close_handler_blocks();
            self.flush_pending_stores();
            if let Some(h) = self.legacy_handler.take() {
                if let Some(he) = &h.name {
                    if let Expr::Name(n) = &**he {
                        self.pending_as_cleanup = Some(n.clone());
                    }
                }
                if let Some(lt) = self.legacy_try.as_mut() {
                    lt.handlers.push(ExceptHandler {
                        type_: h.type_,
                        name: h.name,
                        body: h.body,
                        is_star: false,
                    });
                }
            }
            self.legacy_handler_end = None;
        }
        while self.blocks.len() > 1 {
            let p = self.blocks.last().map(|b| b.start).unwrap_or(to);
            self.force_close_top(p);
        }
        // a nested try whose protected region ends at/after the sub-walk
        // limit defers its tail forever — emit it now while the parsed
        // handler bodies still belong to it
        while let Some(tc) = self.pending_try_ctx.take() {
            self.emit_try_tail(tc, to);
        }
        // a shared fall-through terminator moved out of a region-folded
        // Try body belongs to the region's statement stream
        if let Some(stmt) = self.pending_post_chain_stmt.take() {
            self.push_stmt(stmt);
        }
        let mut root = self.blocks.pop().unwrap();
        let stmts = std::mem::take(&mut root.stmts);
        self.region_result_expr = match self.stack.last() {
            Some(Sv::E(e)) => Some(e.clone()),
            _ => None,
        };

        self.blocks = saved_blocks;
        self.stack = saved_stack;
        self.skip_until = saved_skip;
        self.pending_try_tail = saved_try_tail;
        self.pending_post_chain_stmt = saved_post_chain;
        self.active_try = saved_active_try;
        self.active_try_stack = saved_active_stack;
        let (saved_cur_offset, saved_cur_next) = saved_cur;
        self.cur_offset = saved_cur_offset;
        self.cur_next = saved_cur_next;
        let (saved_prev_op, saved_prev_at_exec) = saved_prev;
        self.prev_op = saved_prev_op;
        self.prev_op_at_exec = saved_prev_at_exec;
        self.cur_line = saved_line;
        self.region_collect_only = saved_collect;
        self.pending_stores = saved_stores;
        stmts
    }

    /// Parse an out-of-line except-dispatch handler region (3.11+):
    /// PUSH_EXC_INFO followed by `[pattern; CHECK_EXC_MATCH; PJIF next]*`
    /// clause bodies, ending in RERAISE.
    fn parse_except_dispatch(&mut self, from: usize) -> Vec<ExceptHandler> {
        let mut handlers = Vec::new();
        let mut clause_offsets: Vec<usize> = Vec::new();
        let end = self.dispatch_region_end(from);
        let region_end = self.handler_region_end(from);
        // nesting: this chain's own cleanup region ends exactly where the
        // next chain begins — that chain handles re-raises FROM this one,
        // i.e. it is the ENCLOSING try's dispatch. Adjacency must be exact
        // (a chain followed by its try's sunk post-flow, then a finally
        // handler chain, is NOT nested inside that finally).
        // chain adjacency: the instruction(s) before the next chain head
        // are the previous chain's RERAISE stub — 3.11 inserts an exit
        // trampoline (JUMP_FORWARD over the following chain) between them
        let adj_reraise = self
            .idx_of
            .get(&region_end)
            .map(|&ri| {
                let mut p = ri;
                let mut hops = 0;
                loop {
                    if p == 0 || hops > 8 {
                        return false;
                    }
                    p -= 1;
                    hops += 1;
                    let prev = &self.instrs[p];
                    if prev.op == Op::RERAISE {
                        return true;
                    }
                    let outward_jf = matches!(
                        prev.op,
                        Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::NOT_TAKEN
                    ) && prev.target.map_or(true, |t| t >= region_end);
                    // 3.12: a sunk post-try resume (straight-line loads
                    // ending in RETURN) can sit between the stubs and the
                    // enclosing chain head
                    let resume_load = matches!(
                        prev.op,
                        Op::LOAD_FAST
                            | Op::LOAD_NAME
                            | Op::LOAD_CONST
                            | Op::LOAD_GLOBAL
                            | Op::LOAD_DEREF
                            | Op::RETURN_VALUE
                            | Op::RETURN_CONST
                    );
                    if !outward_jf && !resume_load {
                        return false;
                    }
                }
            })
            .unwrap_or(false);
        let extent = self.chain_extent(from);
        // instructions between the chain extent and the next head must be
        // pure outward exit trampolines for the chains to count as nested
        let tramp_gap = match self.idx_of.get(&extent) {
            Some(&si) => {
                let mut ok = true;
                for x in &self.instrs[si..] {
                    if x.offset >= region_end {
                        break;
                    }
                    if !(matches!(
                        x.op,
                        Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::NOT_TAKEN
                    ) && x.target.map_or(true, |t| t >= region_end))
                    {
                        ok = false;
                        break;
                    }
                }
                ok
            }
            None => false,
        };
        let nested = region_end > from && adj_reraise && (extent == region_end || tramp_gap)
            // the exception table must confirm the enclosure: a chain
            // genuinely nested inside the adjacent one has (part of) its
            // own region protected by an entry targeting the adjacent
            // head. SEQUENTIAL sibling tries also lay out stub-adjacent
            // (chain1 RERAISE/cleanup, then chain2 PUSH_EXC_INFO) but the
            // sibling's protected range is its own try body BEFORE this
            // chain — without this check chain2 reads as the enclosing
            // dispatch and swallows the code between the tries as an else
            // region (duplicating it)
            && self.exc_entries.iter().any(|e| {
                e.target == region_end && e.start < region_end && e.end > from
            })
            && self
                .idx_of
                .get(&region_end)
                .and_then(|&i| {
                    let is_dispatch = self.instrs.get(i).map(|x| x.op == Op::PUSH_EXC_INFO)
                        == Some(true)
                        // a finally/cleanup chain (no CHECK_*_MATCH) is
                        // not an enclosing except dispatch
                        && self.instrs[i..]
                            .iter()
                            .take(40)
                            .any(|x| {
                                x.op == Op::CHECK_EXC_MATCH || x.op == Op::CHECK_EG_MATCH
                            });
                    Some(is_dispatch)
                })
                .unwrap_or(false);
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            eprintln!(
                "EG nested-check [{}] from={} region_end={} prev_reraise={} extent={} nested={}",
                self.code.name, from,
                region_end,
                self.idx_of
                    .get(&region_end)
                    .and_then(|&ri| self.instrs.get(ri.wrapping_sub(1)))
                    .map(|p| p.op == Op::RERAISE)
                    .unwrap_or(false),
                extent,
                nested
            );
        }
        let mut pc = match self.idx_of.get(&from) {
            Some(&i) => i,
            None => return handlers,
        };
        // expect PUSH_EXC_INFO
        if self.instrs.get(pc).map(|i| i.op) != Some(Op::PUSH_EXC_INFO) {
            return handlers;
        }
        pc += 1;
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            eprintln!("EG dispatch from={} end={} region_end={} nested={}", from, end, region_end, nested);
        }
        let mut pattern: Option<ExprRef> = None;
        // except* (3.11+): clauses match with CHECK_EG_MATCH and branch
        // on POP_JUMP_IF_NONE; the star flag is per-clause
        let mut star_clause = false;
        // a clause head is expected right after PUSH_EXC_INFO and at each
        // mismatch-jump target; a POP_TOP there is a BARE `except:` clause
        // (the exception value is discarded without any CHECK_EXC_MATCH)
        let mut at_clause_head = true;
        // except* dispatch parks a POP_TOP at each mismatch-jump target
        // (clause-cleanup, not a bare clause); `except` and `except*`
        // cannot share a try, so once an EG match is seen the bare-clause
        // reading is off the table
        let mut eg_chain = false;
        while pc < self.instrs.len() {
            let inst = self.instrs[pc];
            if inst.offset >= end
                && !handlers.is_empty()
                && !(nested && inst.offset < self.chain_extent(from))
            {
                break;
            }
            match inst.op {
                Op::NOP | Op::NOT_TAKEN | Op::CACHE => {
                    pc += 1;
                    continue;
                }
                Op::POP_TOP
                    if at_clause_head
                        && !eg_chain
                        && self.version.at_least(3, 11) =>
                {
                    at_clause_head = false;
                    clause_offsets.push(inst.offset);
                    pc += 1;
                    let body =
                        self.decompile_handler_body(&mut pc, end, region_end, false);
                    handlers.push(ExceptHandler {
                        type_: None,
                        name: None,
                        body,
                        is_star: false,
                    });
                    continue;
                }
                Op::CHECK_EXC_MATCH => {
                    at_clause_head = false;
                    // stack: [exc, pattern] — pattern expression was built
                    // by preceding loads; simulate them minimally
                    pattern = self.sim_pattern(&mut pc, inst.offset);
                    pc += 1;
                    continue;
                }
                Op::CHECK_EG_MATCH => {
                    at_clause_head = false;
                    eg_chain = true;
                    pattern = self.sim_pattern(&mut pc, inst.offset);
                    star_clause = true;
                    pc += 1;
                    continue;
                }
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_IF_NONE
                | Op::POP_JUMP_FORWARD_IF_NONE => {
                    at_clause_head = false;
                    let next = inst.target.unwrap_or(end);
                    clause_offsets.push(inst.offset);
                    pc += 1;
                    // 3.14 pads the clause head with NOT_TAKEN
                    while matches!(
                        self.instrs.get(pc).map(|i| i.op),
                        Some(Op::NOT_TAKEN) | Some(Op::NOP)
                    ) {
                        pc += 1;
                    }
                    // optional `as name` store
                    let mut name = None;
                    if let Some(ninst) = self.instrs.get(pc) {
                        if matches!(
                            ninst.op,
                            Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF
                        ) {
                            name = Some(match ninst.op {
                                Op::STORE_NAME => self.const_name(ninst.arg as usize),
                                Op::STORE_DEREF => self
                                    .code
                                    .deref_name(ninst.arg as usize)
                                    .unwrap_or("?")
                                    .to_string(),
                                _ => self.local_name(ninst.arg as usize),
                            });
                            pc += 1;
                        }
                    }
                    // arm the `as` cleanup swallow for the body sub-walk:
                    // 3.11+ embeds `e = None; del e` between the body and
                    // its RETURN (and again on the exception path)
                    let saved_pac = self.pending_as_cleanup.take();
                    if let Some(n) = &name {
                        self.pending_as_cleanup = Some(n.clone());
                    }
                    let body =
                        self.decompile_handler_body(&mut pc, next, region_end, star_clause);
                    if std::env::var("PYCDC_EG_DBG").is_ok() {
                        eprintln!("EG clause next={} bodylen={}", next, body.len());
                    }
                    self.pending_as_cleanup = saved_pac;
                    handlers.push(ExceptHandler {
                        type_: pattern.take(),
                        name: name.map(|n| Rc::new(Expr::Name(n)) as ExprRef),
                        body,
                        is_star: star_clause,
                    });
                    star_clause = false;
                    // everything up to the next clause (body + exception-
                    // path cleanup + its RERAISE) is consumed
                    if let Some(&ni) = self.idx_of.get(&next) {
                        pc = ni;
                        at_clause_head = true;
                    }
                    continue;
                }
                Op::RERAISE => {
                    at_clause_head = false;
                    pc += 1;
                    // a clause's exception-path cleanup also ends in
                    // RERAISE — the chain only terminates when no new
                    // CHECK_EXC_MATCH clause follows
                    let mut m = pc;
                    let mut more = false;
                    while m < self.instrs.len() {
                        let nx = &self.instrs[m];
                        if nx.offset >= end {
                            break;
                        }
                        match nx.op {
                            Op::CHECK_EXC_MATCH | Op::CHECK_EG_MATCH => {
                                more = true;
                                break;
                            }
                            Op::LOAD_CONST | Op::LOAD_GLOBAL | Op::LOAD_NAME
                            | Op::STORE_FAST | Op::STORE_NAME
                            | Op::DELETE_FAST | Op::DELETE_NAME
                            | Op::STORE_DEREF | Op::DELETE_DEREF
                            | Op::COPY | Op::SWAP | Op::POP_TOP
                            | Op::POP_EXCEPT | Op::PUSH_EXC_INFO
                            | Op::NOP | Op::NOT_TAKEN
                            | Op::LIST_APPEND | Op::CALL_INTRINSIC_2
                            | Op::PREP_RERAISE_STAR
                            | Op::BUILD_TUPLE => {
                                m += 1;
                            }
                            _ => break,
                        }
                    }
                    if !more && (!handlers.is_empty() || pattern.is_none()) {
                        if nested && inst.end() == region_end {
                            // this cleanup RERAISE separates the two
                            // chains — keep scanning into the outer one
                            continue;
                        }
                        break;
                    }
                    continue;
                }
                Op::POP_EXCEPT => {
                    at_clause_head = false;
                    pc += 1;
                    continue;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST | Op::END_FINALLY => {
                    at_clause_head = false;
                    // a stray terminator between clauses (a body ending
                    // without a closing jump): hop to the next clause
                    if inst.offset >= end
                        && !handlers.is_empty()
                        && !(nested && inst.offset < self.chain_extent(from))
                    {
                        break;
                    }
                    pc += 1;
                }
                _ => {
                    at_clause_head = false;
                    pc += 1;
                }
            }
        }
        if nested && !handlers.is_empty() {
            // clauses parsed past the chain boundary belong to the
            // enclosing try — split them off and wrap this try inside a
            // bare `except:` handler (the enclosing try catches re-raises
            // from this one, and any exception when no clause matched).
            // The enclosing chain's own clauses/finally come from a
            // recursive parse of its dispatch head.
            let outer_idx = clause_offsets
                .iter()
                .position(|o| *o >= region_end)
                .unwrap_or(handlers.len());
            let _ = handlers.split_off(outer_idx);
            // the clauses below the boundary are the INNER try's handlers;
            // emit_try_tail builds `Try { body: [inner try], .. }` from them
            self.nested_inner_handlers.push(handlers);
            let outer = self.parse_except_dispatch(region_end);
            // enclosing finally: entries past the outer chain whose target
            // is a non-except (finally) handler
            let mut finalbody = Vec::new();
            let mut fin_target = None;
            for e in &self.exc_entries {
                if e.start > region_end && e.target > region_end {
                    if self
                        .idx_of
                        .get(&e.target)
                        .and_then(|&i| self.instrs.get(i))
                        .map(|x| x.op == Op::PUSH_EXC_INFO)
                        .unwrap_or(false)
                        && !self.instrs[self.idx_of[&e.target]..]
                            .iter()
                            .take(40)
                            .any(|x| {
                                x.op == Op::CHECK_EXC_MATCH || x.op == Op::CHECK_EG_MATCH
                            })
                    {
                        fin_target = Some(e.target);
                        break;
                    }
                }
            }
            if let Some(fh) = fin_target {
                finalbody =
                    self.decompile_region(fh, self.chain_extent(fh).max(fh + 2));
            }
            self.pending_nested_finally = Some(finalbody);
            return outer;
        }
        if handlers.iter().any(|h| h.is_star) {
            if let Some((excl, lim, span_end)) = self.star_resume_span(from) {
                self.star_tail = self.decompile_region(excl, lim);
                self.star_tail_end = Some(span_end);
            }
        }
        handlers
    }

    /// except* chain epilogue: `PREP_RERAISE_STAR; COPY 1;
    /// POP_JUMP_IF_NOT_NONE stub; POP_TOP; POP_EXCEPT` — main flow
    /// resumes right after that POP_EXCEPT and runs until the chain's
    /// dead zero-depth stubs (`SWAP/COPY; POP_EXCEPT; RERAISE`).
    /// Returns (resume_offset, limit_offset, span_end) where span_end is
    /// the offset just past the limit instruction (for skipping the
    /// resume in the main walk — 3.11 lays it out AFTER the chains).
    fn star_resume_span(&self, head: usize) -> Option<(usize, usize, usize)> {
        let mut i = self.idx_of.get(&head).copied()?;
        let extent = self.chain_extent(head);
        let mut prep = None;
        while i < self.instrs.len() && self.instrs[i].offset < extent {
            let ins = self.instrs[i];
            if ins.op == Op::PREP_RERAISE_STAR
                || (ins.op == Op::CALL_INTRINSIC_2 && ins.arg == 1)
            {
                prep = Some(i);
                break;
            }
            i += 1;
        }
        let mut j = prep? + 1;
        while j < self.instrs.len() && self.instrs[j].offset < extent {
            if self.instrs[j].op == Op::POP_EXCEPT {
                break;
            }
            j += 1;
        }
        if j >= self.instrs.len() || self.instrs[j].op != Op::POP_EXCEPT {
            return None;
        }
        // walk from the epilogue's POP_EXCEPT through exit trampolines
        // (3.11 jumps over the dead stubs and possibly over the enclosing
        // chain to the out-of-line resume); guard against backward jumps
        let mut r = j + 1;
        let mut hops = 0;
        let resume;
        loop {
            if r >= self.instrs.len() || hops > 8 {
                return None;
            }
            let ins = self.instrs[r];
            let is_tramp = matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::NOT_TAKEN)
                && ins.target.map_or(false, |t| t > ins.offset);
            let is_stub = matches!(ins.op, Op::SWAP | Op::COPY)
                && matches!(self.instrs.get(r + 1).map(|x| x.op), Some(Op::POP_EXCEPT))
                && matches!(self.instrs.get(r + 2).map(|x| x.op), Some(Op::RERAISE));
            if is_stub || ins.op == Op::PUSH_EXC_INFO {
                return None;
            }
            // 3.11: the epilogue trampoline can jump straight to the
            // resume PAST a finally chain that covers it — that finally
            // is the try's own (folded as finalbody); stop before it
            if is_tramp {
                let t = ins.target.unwrap();
                let t_is_covered_fin = self
                    .exc_entries
                    .iter()
                    .any(|e| e.target == t && e.start != e.end)
                    && self
                        .idx_of
                        .get(&t)
                        .and_then(|&ti| self.instrs.get(ti))
                        .map(|x| x.op == Op::PUSH_EXC_INFO)
                        .unwrap_or(false);
                if t_is_covered_fin {
                    return None;
                }
            }
            if is_tramp {
                let t = ins.target.unwrap();
                match self.idx_of.get(&t) {
                    Some(&ti) => {
                        r = ti;
                        hops += 1;
                        continue;
                    }
                    None => return None,
                }
            }
            resume = ins.offset;
            break;
        }
        let mut k = r;
        while k < self.instrs.len() {
            let ins = self.instrs[k];
            if matches!(ins.op, Op::SWAP | Op::COPY)
                && matches!(self.instrs.get(k + 1).map(|x| x.op), Some(Op::POP_EXCEPT))
                && matches!(self.instrs.get(k + 2).map(|x| x.op), Some(Op::RERAISE))
            {
                break;
            }
            if ins.op == Op::PUSH_EXC_INFO {
                break;
            }
            if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST | Op::RERAISE) {
                k += 1;
                break;
            }
            k += 1;
        }
        let (lim, span_end) = if k < self.instrs.len() {
            (self.instrs[k].offset, self.instrs[k].offset)
        } else {
            let e = self.instrs.last().map(|x| x.end()).unwrap_or(resume);
            (e, e)
        };
        if lim > resume {
            Some((resume, lim, span_end))
        } else {
            None
        }
    }

    /// Build the pattern expression for an except clause: forward-simulate
    /// the loads between the previous clause boundary and CHECK_EXC_MATCH.
    fn sim_pattern(&self, _pc: &mut usize, check_offset: usize) -> Option<ExprRef> {
        let ci = *self.idx_of.get(&check_offset)?;
        // find clause start: previous boundary instruction
        let mut start = ci;
        while start > 0 {
            let prev = &self.instrs[start - 1];
            if matches!(
                prev.op,
                Op::PUSH_EXC_INFO
                    | Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_FORWARD_IF_NONE
                    | Op::RERAISE
                    | Op::JUMP_FORWARD
                    | Op::JUMP_BACKWARD
                    | Op::JUMP_ABSOLUTE
                    | Op::JUMP
                    | Op::POP_EXCEPT
                    | Op::CHECK_EXC_MATCH
                    | Op::CHECK_EG_MATCH
                    | Op::PREP_RERAISE_STAR
            ) {
                break;
            }
            start -= 1;
        }
        let mut stack: Vec<ExprRef> = Vec::new();
        for ins in &self.instrs[start..ci] {
            match ins.op {
                Op::LOAD_GLOBAL => {
                    let idx = if self.version.at_least(3, 11) {
                        (ins.arg >> 1) as usize
                    } else {
                        ins.arg as usize
                    };
                    stack.push(self.name_expr(self.const_name(idx)));
                }
                Op::LOAD_NAME | Op::LOAD_DEREF | Op::LOAD_FAST => {
                    let n = match ins.op {
                        Op::LOAD_NAME => self.const_name(ins.arg as usize),
                        Op::LOAD_DEREF => self
                            .code
                            .deref_name(ins.arg as usize)
                            .unwrap_or("?")
                            .to_string(),
                        _ => self.local_name(ins.arg as usize),
                    };
                    stack.push(self.name_expr(n));
                }
                Op::LOAD_CONST => {
                    if let Some(o) = self.code.consts.get(ins.arg as usize) {
                        stack.push(Rc::new(Expr::Const(o.clone())));
                    }
                }
                Op::LOAD_ATTR | Op::LOAD_METHOD => {
                    let idx = if ins.op == Op::LOAD_ATTR
                        && self.version.at_least(3, 12)
                    {
                        (ins.arg >> 1) as usize
                    } else {
                        ins.arg as usize
                    };
                    let attr = self.const_name(idx);
                    if let Some(v) = stack.pop() {
                        stack.push(Rc::new(Expr::Attribute { value: v, attr }));
                    }
                }
                Op::BUILD_TUPLE => {
                    let n = ins.arg as usize;
                    if stack.len() >= n {
                        let items: Vec<ExprRef> =
                            stack.split_off(stack.len() - n);
                        stack.push(Rc::new(Expr::Tuple(items)));
                    }
                }
                Op::DUP_TOP | Op::COPY => {
                    if let Some(t) = stack.last().cloned() {
                        stack.push(t);
                    }
                }
                _ => {}
            }
        }
        // CHECK_EXC_MATCH consumes [exc, pattern]; pattern is on top
        stack.pop()
    }

    /// Decompile one except-clause body: instructions from the current pc
    /// until POP_EXCEPT; then skip the implicit `name = None; del name`
    /// cleanup and the closing jump. Advances `pc`.
    /// The referenced name of a LOAD_GLOBAL/LOAD_NAME instruction
    /// (mirrors the exec arm's resolution: 3.11+ LOAD_GLOBAL packs
    /// (namei << 1) | null_flag).
    fn store_like_name(&self, ins: &crate::bytecode::Instruction) -> String {
        let idx = match ins.op {
            Op::LOAD_GLOBAL => {
                if self.version.at_least(3, 11) {
                    (ins.arg >> 1) as usize
                } else {
                    ins.arg as usize
                }
            }
            _ => ins.arg as usize,
        };
        self.const_name(idx)
    }

    fn decompile_handler_body(
        &mut self,
        pc: &mut usize,
        next_clause: usize,
        region_end: usize,
        is_star: bool,
    ) -> Vec<Stmt> {
        // the clause body runs to the next clause start (the mismatch
        // jump target is exactly that boundary in every 3.11+ layout)
        let limit = next_clause;
        let _ = region_end;
        let body_start = match self.instrs.get(*pc) {
            Some(i) => i.offset,
            None => return Vec::new(),
        };
        // locate POP_EXCEPT within this clause
        let mut k = *pc;
        let mut pop_idx = None;
        while k < self.instrs.len() {
            let ins = &self.instrs[k];
            if ins.offset >= limit {
                break;
            }
            if ins.op == Op::POP_EXCEPT {
                pop_idx = Some(k);
                break;
            }
            if ins.op == Op::PUSH_EXC_INFO {
                // a nested handler chain starts inside this clause: the
                // clause's own POP_EXCEPT, if any, follows the nested
                // region — the body sub-walk folds the nested chain
                break;
            }
            k += 1;
        }
        let Some(pi) = pop_idx else {
            // No POP_EXCEPT terminator: either an except* clause (3.11+)
            // or a plain clause body ending in `raise`. The body runs
            // until the eager `as` cleanup (`LOAD None; STORE name;
            // DELETE name`), which precedes the closing JUMP_FORWARD and
            // the out-of-line exception-path cleanup stub. Cut there so
            // neither leaks into the body.
            let mut body_end = limit;
            if is_star && self.pending_as_cleanup.is_none() {
                // `except* E:` without `as`: the body ends at the
                // group-append cleanup that feeds the PREP_RERAISE_STAR
                // accumulator (3.12+: `LIST_APPEND 1` right after the
                // as-cleanup; 3.11: a `LIST_APPEND 3` exception stub past
                // the body's closing jump) — stop at the first one
                let mut m = *pc;
                while m < self.instrs.len() {
                    let a = self.instrs[m].offset;
                    if a >= limit {
                        break;
                    }
                    if self.instrs[m].op == Op::LIST_APPEND {
                        body_end = a;
                        break;
                    }
                    m += 1;
                }
            }
            if let Some(n) = self.pending_as_cleanup.clone() {
                let mut m = *pc;
                while m + 2 < self.instrs.len() {
                    let a = self.instrs[m].offset;
                    if a >= limit {
                        break;
                    }
                    let store_match = matches!(
                        self.instrs[m].op,
                        Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF
                    ) && self.store_del_name(m) == Some(n.clone());
                    let del_match = matches!(
                        self.instrs[m + 1].op,
                        Op::DELETE_FAST | Op::DELETE_NAME | Op::DELETE_DEREF
                    ) && self.store_del_name(m + 1) == Some(n.clone());
                    if store_match && del_match {
                        // cut before the eager `LOAD None` when present
                        body_end = if m > 0 && self.instrs[m - 1].op == Op::LOAD_CONST {
                            self.instrs[m - 1].offset
                        } else {
                            a
                        };
                        break;
                    }
                    m += 1;
                }
            }
            *pc = k;
            if std::env::var("PYCDC_EG_DBG").is_ok() {
                eprintln!(
                    "EG no-pop [{}] body start={} end={} limit={} star={} pac={:?}",
                    self.code.name, body_start, body_end, limit, is_star, self.pending_as_cleanup
                );
            }
            return if body_end > body_start {
                self.decompile_region(body_start, body_end)
            } else {
                Vec::new()
            };
        };
        // 3.9+/3.11+ shape: `[POP_TOP;] POP_EXCEPT; [as-cleanup]; body` —
        // the body FOLLOWS the POP_EXCEPT. The legacy shape keeps the body
        // BEFORE it (`body; POP_EXCEPT; cleanup; jump`).
        let prelude_only = self.instrs[*pc..=pi]
            .iter()
            .all(|i| matches!(i.op, Op::POP_TOP | Op::POP_EXCEPT | Op::NOP | Op::NOT_TAKEN));
        if prelude_only {
            let mut m = pi + 1;
            // skip the eager `as` cleanup: LOAD_CONST None; STORE n; DELETE n
            if matches!(self.instrs.get(m).map(|i| i.op), Some(Op::LOAD_CONST))
                && matches!(
                    self.instrs.get(m + 1).map(|i| i.op),
                    Some(Op::STORE_FAST) | Some(Op::STORE_NAME) | Some(Op::STORE_DEREF)
                )
                && matches!(
                    self.instrs.get(m + 2).map(|i| i.op),
                    Some(Op::DELETE_FAST) | Some(Op::DELETE_NAME) | Some(Op::DELETE_DEREF)
                )
            {
                m += 3;
            }
            let body_from = self.instrs.get(m).map(|i| i.offset).unwrap_or(limit);
            *pc = m;
            // `except E: break` — the body's jump targets an enclosing
            // loop's exit; the region sub-walk swaps the block stack and
            // cannot see the loop, so rebuild the Break here while the
            // live blocks are still on the stack. 3.11: JUMP_FORWARD to
            // the exit; 3.12+: JUMP_BACKWARD to it (the out-of-line
            // handler sits PAST the loop exit, so the break hops
            // backward — _compression read's `except trailing_error:
            // break` rendered `pass` and lost the loop semantics)
            if limit > body_from {
                let mut bj = None;
                if let (Some(&bi), Some(&li)) =
                    (self.idx_of.get(&body_from), self.idx_of.get(&limit))
                {
                    for j in bi..li {
                        let ins = self.instrs[j];
                        let is_exit_jump = if ins.is_backward {
                            matches!(
                                ins.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP
                            )
                        } else {
                            matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                        };
                        if is_exit_jump
                            && ins.target.map_or(false, |t| {
                                self.find_loop_exit(t).is_some()
                            })
                        {
                            bj = Some(j);
                            break;
                        }
                    }
                }
                if let Some(j) = bj {
                    let joff = self.instrs[j].offset;
                    let mut body = if joff > body_from {
                        self.decompile_region(body_from, joff)
                    } else {
                        Vec::new()
                    };
                    body.push(Stmt::Break);
                    // the break hops PAST the loop's own exit when the
                    // loop sits inside an if-branch with a sibling
                    // elif: the span between is that branch's else arm
                    // - register it on the innermost enclosing If whose
                    // end the break flew over, so its close assembles
                    // the elif instead of leaving the arm unclaimed at
                    // top level (_osx_support 3.12 compiler_fixup:
                    // `elif not _supports_arm64_builds():` rendered as
                    // a standalone if, running the arm even after the
                    // while-True branch executed)
                    if let Some(t) = self.instrs[j].target {
                        let cand = self
                            .blocks
                            .iter()
                            .rev()
                            .position(|b| {
                                b.kind == BlockType::If
                                    && b.else_end.is_none()
                                    && b.end < t
                                    && b.start < joff
                            });
                        if let Some(k) = cand {
                            let n = self.blocks.len();
                            let b = &self.blocks[n - 1 - k];
                            let (si, ei) = (
                                self.idx_of.get(&b.end).copied(),
                                self.idx_of.get(&t).copied(),
                            );
                            if let (Some(si), Some(ei)) = (si, ei) {
                                if si < ei {
                                    let mut sees_guard = false;
                                    let ok = self.instrs[si..ei].iter().all(|x| {
                                        if x.is_backward {
                                            return true;
                                        }
                                        match x.target {
                                            Some(tt) if tt > t => false,
                                            Some(tt) if tt == t => {
                                                if matches!(
                                                    x.op,
                                                    Op::POP_JUMP_IF_TRUE
                                                        | Op::POP_JUMP_IF_FALSE
                                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                                        | Op::JUMP_IF_TRUE
                                                        | Op::JUMP_IF_FALSE
                                                ) {
                                                    sees_guard = true;
                                                }
                                                true
                                            }
                                            _ => true,
                                        }
                                    });
                                    if ok && sees_guard {
                                        let n = self.blocks.len();
                                        self.blocks[n - 1 - k].else_end = Some(t);
                                    }
                                }
                            }
                        }
                    }
                    return body;
                }
                // `except E: continue` — a backward body jump onto an
                // enclosing loop's top: the region sub-walk swaps the
                // block stack and cannot see the loop, so rebuild the
                // Continue here while the live blocks are still on the
                // stack (cProfile 3.11-3.13 snapshot_stats
                // `except KeyError: continue` rendered `pass`, losing
                // the loop-skip; the clause exit edge is a JB to the
                // FOR_ITER top, not a loop exit, so the break rebuild
                // above does not claim it)
                let mut cj = None;
                if let (Some(&bi2), Some(&li2)) =
                    (self.idx_of.get(&body_from), self.idx_of.get(&limit))
                {
                    for j in bi2..li2 {
                        let ins = self.instrs[j];
                        if ins.is_backward
                            && matches!(
                                ins.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP
                            )
                            && ins
                                .target
                                .map_or(false, |t| self.is_loop_top_target(t))
                        {
                            cj = Some(j);
                            break;
                        }
                    }
                }
                if let Some(j) = cj {
                    let joff = self.instrs[j].offset;
                    let mut body = if joff > body_from {
                        self.decompile_region(body_from, joff)
                    } else {
                        Vec::new()
                    };
                    body.push(Stmt::Continue);
                    return body;
                }
            }
            // an unconditional FORWARD jump at the body head (past the
            // break rebuild above) is the handler's EXIT jump, not a body
            // statement: the clause is empty (`except: pass`). Walking it
            // swallows the post-chain continuation into the handler
            // (_sitebuiltins 3.11 Quitter.__call__: the bare handler's exit
            // JF targets the sunk `raise SystemExit(code)`, which rendered
            // both inside the handler and after the try)
            if let Some(&bi) = self.idx_of.get(&body_from) {
                let hj = self.instrs[bi];
                if matches!(hj.op, Op::JUMP_FORWARD | Op::JUMP)
                    && !hj.is_backward
                    && hj.target.map_or(false, |t| t > body_from)
                {
                    *pc = bi + 1;
                    return Vec::new();
                }
            }
            // sunk break-raise fusion: `except E: break` where the loop
            // exit flow is a matching `raise X` — the compiler fuses the
            // break's landing into the handler as POP_EXCEPT; LOAD X;
            // RAISE (_collections_abc 3.13 Sequence.index `except
            // IndexError: break` + post-loop `raise ValueError`). The
            // literal handler raise recompiles WITHOUT the POP_EXCEPT;
            // only Break reproduces the fused bytes
            if limit > body_from {
                if let (Some(&bi3), Some(&li3)) =
                    (self.idx_of.get(&body_from), self.idx_of.get(&limit))
                {
                    let mut lj = None;
                    for j in bi3..li3 {
                        if matches!(self.instrs[j].op, Op::LOAD_GLOBAL | Op::LOAD_NAME) {
                            lj = Some(j);
                            break;
                        }
                        if !matches!(
                            self.instrs[j].op,
                            Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::POP_TOP
                        ) {
                            break;
                        }
                    }
                    if let Some(j) = lj {
                        let raise_i = (j + 1..li3).find(|&r| {
                            matches!(
                                self.instrs[r].op,
                                Op::CALL | Op::CALL_FUNCTION | Op::PRECALL
                            ) || self.instrs[r].op == Op::RAISE_VARARGS
                        });
                        if let Some(ri) = raise_i {
                            if self.instrs[ri].op == Op::RAISE_VARARGS
                                && ri + 1 == li3
                            {
                                let hname = self.store_like_name(&self.instrs[j]);
                                // the post-loop raise sits at the
                                // enclosing loop's registered exit (the
                                // out-of-line handler lies PAST it, so a
                                // forward scan from the clause cannot
                                // reach it)
                                let loop_exit = self
                                    .blocks
                                    .iter()
                                    .rev()
                                    .find(|b| {
                                        matches!(
                                            b.kind,
                                            BlockType::While | BlockType::For
                                        )
                                    })
                                    .map(|b| b.end);
                                let post_ok = loop_exit
                                    .and_then(|le| self.idx_of.get(&le).copied())
                                    .map_or(false, |xi| {
                                        let x = &self.instrs[xi];
                                        matches!(
                                            x.op,
                                            Op::LOAD_GLOBAL | Op::LOAD_NAME
                                        ) && self.store_like_name(x) == hname
                                            && self.instrs[xi + 1..]
                                                .iter()
                                                .take(6)
                                                .any(|y| {
                                                    y.op == Op::RAISE_VARARGS
                                                })
                                    });
                                let in_loop = loop_exit.is_some();
                                if post_ok && in_loop {
                                    return vec![Stmt::Break];
                                }
                            }
                        }
                    }
                }
            }
            return if limit > body_from {
                self.decompile_region(body_from, limit)
            } else {
                Vec::new()
            };
        }
        // legacy shape: body before the POP_EXCEPT. A computed return
        // (`except E as e: return <expr with e>`) evaluates the value
        // BEFORE the POP_EXCEPT and returns AFTER the as-cleanup — extend
        // the body region over the cleanup to include that RETURN.
        let mut body_end = self.instrs[pi].offset;
        let mut k2 = pi + 1;
        // a handler ending in `continue` exits through a JUMP_BACKWARD to
        // the enclosing loop top (out-of-line handlers have no other
        // backward exits except finally-flow JBNI, which never targets a
        // loop block)
        let mut trail_continue = false;
        // 3.12+ `break` inside a handler: POP_EXCEPT; JUMP_BACKWARD to
        // the enclosing loop's EXIT (not its top -- the out-of-line
        // handler sits past the exit). tb2/bz2 3.14 decompress shape.
        let mut trail_break: Option<usize> = None;
        // the trail scan consumed a handler exit jump (JF over the
        // mismatch stubs, or JB to the loop top): what follows is
        // exception-path machinery (as-cleanup copy + RERAISE), never a
        // sunk continuation
        let mut trail_exit_jump = false;
        // the clause ends with the sunk implicit tail `return None` copy
        // (3.11+ function-tail try): the region between POP_EXCEPT and
        // the mismatch RERAISE holds ONLY that copy, so the sunk-
        // continuation extension below must not re-swallow it
        let mut sunk_tail_copy = false;
        // skip cleanup: [LOAD_CONST None; STORE; DELETE], closing jump
        while k2 < self.instrs.len() {
            let c = &self.instrs[k2];
            match c.op {
                Op::LOAD_CONST | Op::STORE_FAST | Op::STORE_NAME
                | Op::DELETE_FAST | Op::DELETE_NAME | Op::STORE_DEREF
                | Op::DELETE_DEREF => {
                    k2 += 1;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST => {
                    // a sunk implicit tail `return None` (3.12+
                    // function-tail try: POP_EXCEPT; RETURN_CONST None —
                    // a single instruction, no value load) is the tail
                    // copy, not a computed return value — extending the
                    // body over it makes the clause spuriously
                    // terminating (the try/else flattens and the handler
                    // grows a `return`). emit_try_tail's sunk-pair
                    // recovery uses the success-side copy as the else
                    // boundary. Deliberately RETURN_CONST-only: the
                    // 3.11 `LOAD None; RETURN_VALUE` shape is
                    // indistinguishable from a genuine sunk `return`
                    // continuation here (both follow the as-cleanup skip)
                    // and only costs the handler-side drop there.
                    let sunk_none = match c.op {
                        Op::RETURN_CONST => matches!(
                            self.code.consts.get(c.arg as usize).map(|o| &**o),
                            Some(PyObject::None)
                        ),
                        _ => false,
                    };
                    if !sunk_none {
                        body_end = c.end();
                    }
                    sunk_tail_copy = sunk_none;
                    k2 += 1;
                    break;
                }
                Op::JUMP_FORWARD
                | Op::JUMP_BACKWARD
                | Op::JUMP_ABSOLUTE
                | Op::JUMP
                | Op::JUMP_NO_INTERRUPT
                | Op::RERAISE => {
                    if matches!(c.op, Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP)
                        && c.target.map_or(false, |t| {
                            self.blocks.iter().any(|b| {
                                matches!(b.kind, BlockType::While | BlockType::For)
                                    && (b.start == t || b.cond_end == t)
                            })
                        })
                    {
                        trail_continue = true;
                    } else if c.target.map_or(false, |t| self.find_loop_exit(t).is_some()) {
                        trail_break = Some(k2);
                    }
                    if !matches!(c.op, Op::RERAISE) {
                        trail_exit_jump = true;
                    }
                    k2 += 1;
                    break;
                }
                _ => break,
            }
        }
        // when the clause body ran up to the POP_EXCEPT and what follows
        // (before the mismatch RERAISE) is straight-line flow with no new
        // clause, the compiler sank the post-try continuation into the
        // handler region (`try: raise X / except X: ... / return v` — the
        // body always raises, so the flow is only reachable through the
        // handler). Include it so the function's tail is not lost.
        let mut sunk_resume: Option<(usize, usize)> = None;
        if k2 < self.instrs.len()
            && self.instrs[k2].offset < limit
            && !trail_exit_jump
            && !sunk_tail_copy
            // a normal handler exit (JUMP_FORWARD over the mismatch
            // stubs) is NOT a sunk continuation — extending over it
            // would swallow the exception-path as-cleanup
            && !matches!(
                self.instrs[k2].op,
                Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
            )
        {
            let mut m2 = k2;
            let mut saw_term = false;
            while m2 < self.instrs.len() {
                let nx = &self.instrs[m2];
                match nx.op {
                    // the mismatch RERAISE sits exactly AT the clause
                    // limit — it is the terminator we look for
                    Op::RERAISE if nx.offset <= limit => {
                        saw_term = true;
                        break;
                    }
                    Op::CHECK_EXC_MATCH | Op::PUSH_EXC_INFO => break,
                    // a backward jump inside the span is a continue/back
                    // edge flow (3.13: POP_EXCEPT; finally-copy; JB top),
                    // not a straight-line sunk continuation
                    Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT => break,
                    Op::JUMP_ABSOLUTE if nx.is_backward => break,
                    _ => {}
                }
                if nx.offset >= limit {
                    break;
                }
                m2 += 1;
            }
            if saw_term {
                if self.bare_try_parse {
                    // bare try/except only: split the sunk post-try
                    // resume out of the clause (rendered after the Try;
                    // inside the handler it recompiles to the SWAP-value
                    // POP_EXCEPT exit form — _collections_abc setdefault).
                    // The resume must start IMMEDIATELY after the clause
                    // POP_EXCEPT (pads aside): a clause whose body ends
                    // in `raise` has no normal-exit POP_EXCEPT before the
                    // resume and its pi lies deep in the stubs — cutting
                    // there tore crypt/codeop's handler bodies apart
                    let mut q = pi + 1;
                    while q < self.instrs.len()
                        && matches!(
                            self.instrs[q].op,
                            Op::NOP | Op::NOT_TAKEN | Op::CACHE
                        )
                    {
                        q += 1;
                    }
                    if q < self.instrs.len()
                        && self.instrs[q].offset == self.instrs[k2].offset
                    {
                        // the sunk span must be a PURE straight-line
                        // value run ending in a single RETURN: an inner
                        // POP_EXCEPT (nested try/with inside the clause)
                        // makes pi cut mid-body and the "resume" span
                        // holds real statements (bdb 3.12 bpby clause
                        // rendered `pass` + a bare `return`, losing
                        // `return b, False`)
                        let pure_span = {
                            let mut okp = true;
                            let mut saw_ret = 0usize;
                            for x in &self.instrs[k2..m2] {
                                if matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                                    saw_ret += 1;
                                    continue;
                                }
                                if x.target.is_some()
                                    || !(Self::comp_arm_value_op(x.op)
                                        || matches!(
                                            x.op,
                                            Op::STORE_FAST
                                                | Op::STORE_NAME
                                                | Op::STORE_DEREF
                                        ))
                                {
                                    okp = false;
                                    break;
                                }
                            }
                            okp && saw_ret == 1
                        };
                        if pure_span {
                            sunk_resume = Some((
                                self.instrs[k2].offset,
                                self.instrs[pi].offset,
                            ));
                        }
                    }
                }
                body_end = self.instrs[m2].offset;
                k2 = m2;
            }
        }
        // 3.12+ `continue` inside a handler: POP_EXCEPT; <finally copy>;
        // JUMP_BACKWARD <loop top> — rebuild the body without the copy
        // and append the Continue
        let mut body_has_continue = false;
        {
            let mut j = pi + 1;
            while j < self.instrs.len() {
                let c = &self.instrs[j];
                if c.offset >= limit {
                    break;
                }
                if matches!(c.op, Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT)
                    || (c.op == Op::JUMP_ABSOLUTE && c.is_backward)
                {
                    let is_top = c.target.map_or(false, |t| {
                        self.blocks.iter().any(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && (b.start == t || b.cond_end == t)
                        })
                    });
                    if is_top {
                        body_has_continue = true;
                        // the copy between the clause POP_EXCEPT and this
                        // jump is finally machinery — trim the body there
                        let mut t = pi + 1;
                        while t < j {
                            if self.instrs[t].op == Op::POP_EXCEPT {
                                body_end = self.instrs[t].offset.min(body_end);
                                break;
                            }
                            t += 1;
                        }
                    }
                    break;
                }
                if c.op == Op::RERAISE || c.op == Op::CHECK_EXC_MATCH {
                    break;
                }
                j += 1;
            }
        }
        *pc = k2;
        let mut body = if let Some((resume_off, pop_off)) = sunk_resume {
            let sunk = if body_end > resume_off {
                self.decompile_region(resume_off, body_end)
            } else {
                Vec::new()
            };
            self.handler_sunk_tail.extend(sunk);
            if pop_off > body_start {
                self.decompile_region(body_start, pop_off)
            } else {
                Vec::new()
            }
        } else if body_end > body_start {
            self.decompile_region(body_start, body_end)
        } else {
            Vec::new()
        };
        if trail_continue || body_has_continue {
            body.push(Stmt::Continue);
        }
        if let Some(jidx) = trail_break {
            // the break flow sat on the trail (POP_EXCEPT; JUMP_BACKWARD
            // loop-exit), so the body region's trailing guard If closed
            // EMPTY (`if results: pass`) and the else arm (a bare RAISE
            // at [jump_end, limit)) was orphaned. Rebuild the source
            // shape `if <guard>: break else: raise` (bz2 3.14 decompress,
            // t_trybrk2 3.12/3.14); without a trailing guard the whole
            // clause is `except E: break`.
            let else_off = self
                .instrs
                .get(jidx + 1)
                .map(|x| x.offset)
                .unwrap_or(limit);
            // `if <guard>: <body1>; break else: raise e` — the else arm
            // is a bare `raise <as-name>` (LOAD name; RAISE_VARARGS 1).
            // Detect it up front (immutable) so the guard-If rebuild
            // below can attach it without a reentrant region walk.
            let else_raise_name: Option<String> = if else_off < limit {
                self.idx_of.get(&else_off).and_then(|&ei2| {
                    let load = &self.instrs[ei2];
                    let raised = self.instrs.get(ei2 + 1).map(|x| x.op)
                        == Some(Op::RAISE_VARARGS);
                    if raised {
                        // LOAD_FAST indexes locals (co_varnames), not
                        // co_names — store_like_name's const_name lookup
                        // is wrong there (resolved `raise e` to `raise
                        // str`). Use the op-appropriate table.
                        match load.op {
                            Op::LOAD_FAST => {
                                Some(self.local_name(load.arg as usize))
                            }
                            Op::LOAD_DEREF => Some(
                                self.code
                                    .deref_name(load.arg as usize)
                                    .unwrap_or("?")
                                    .to_string(),
                            ),
                            Op::LOAD_NAME | Op::LOAD_GLOBAL => {
                                Some(self.store_like_name(load))
                            }
                            _ => None,
                        }
                    } else {
                        None
                    }
                })
            } else {
                None
            };
            let mut attached = false;
            if let Some(Stmt::If { body: ib, orelse, .. }) = body.last_mut() {
                if ib.is_empty() || ib.iter().all(|s| matches!(s, Stmt::Pass)) {
                    ib.clear();
                    ib.push(Stmt::Break);
                    if else_off < limit {
                        if let Some(&ei) = self.idx_of.get(&limit) {
                            if self.instrs.get(ei).map(|x| x.op) == Some(Op::RERAISE)
                                && self.instrs[jidx + 1..ei]
                                    .iter()
                                    .all(|x| !matches!(x.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE))
                            {
                                // the span is a real else arm, not a
                                // mismatch stub -- decompile it (region
                                // walks are reentrant; the outer parse
                                // resumes at *pc = k2)
                                *orelse = self.decompile_region(else_off, limit);
                            }
                        }
                    }
                    attached = true;
                } else if orelse.is_empty() && else_raise_name.is_some() {
                    // the guard body holds real statements and the break
                    // sat on the trail. A guard with NO else cannot
                    // legitimately hoist its break to the clause level
                    // (that would run the break even when the guard is
                    // false), so the trailing flow is the break's arm and
                    // the else span is its `raise e`. Push the break INTO
                    // the guard body and attach the else (code 3.13/3.14
                    // interact `except SystemExit as e: if self.local_exit:
                    // self.write('\n'); break else: raise e` — the dropped
                    // else silently swallowed SystemExit instead of
                    // re-raising, and the hoisted break ran unconditionally)
                    ib.push(Stmt::Break);
                    *orelse = vec![Stmt::Raise {
                        exc: Some(self.name_expr(else_raise_name.clone().unwrap())),
                        cause: None,
                        py2_inst: None,
                        py2_tb: None,
                    }];
                    attached = true;
                }
            }
            if !attached {
                body.push(Stmt::Break);
            }
        }
        body
    }

    /// End of a handler region: the next PUSH_EXC_INFO handler start.
    fn handler_region_end(&self, from: usize) -> usize {
        let mut end = self.code.code.len();
        for e in &self.exc_entries {
            if e.target <= from || e.target >= end {
                continue;
            }
            if let Some(&hi) = self.idx_of.get(&e.target) {
                if self.instrs.get(hi).map(|i| i.op) == Some(Op::PUSH_EXC_INFO) {
                    end = e.target;
                }
            }
        }
        end
    }

    /// 3.12+ shared fall-through terminator: [a, h) ends in a
    /// terminator run (expr-build ops ending at the chain head with
    /// RAISE_VARARGS) and the bare handler at `h` (prelude
    /// PUSH_EXC_INFO; POP_TOP*; POP_EXCEPT) falls through to an
    /// IDENTICAL run followed only by chain scaffolding — the post-try
    /// statement was duplicated into both exits with no merge jump.
    fn mirrored_clause_terminator(&self, a: usize, h: usize) -> bool {
        let (Some(&ai), Some(&hi)) = (self.idx_of.get(&a), self.idx_of.get(&h)) else {
            return false;
        };
        if hi <= ai || hi >= self.instrs.len() {
            return false;
        }
        let fam = |o: Op| {
            matches!(
                o,
                Op::LOAD_GLOBAL
                    | Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
                    | Op::LOAD_DEREF
                    | Op::CALL_FUNCTION
                    | Op::CALL_METHOD
                    | Op::CALL_FUNCTION_KW
                    | Op::PRECALL
                    | Op::CALL
                    | Op::KW_NAMES
                    | Op::BINARY_OP
                    | Op::BINARY_SUBSCR
                    | Op::BUILD_TUPLE
                    | Op::BUILD_LIST
                    | Op::BUILD_MAP
                    | Op::BUILD_SET
                    | Op::BUILD_STRING
                    | Op::FORMAT_VALUE
                    | Op::RAISE_VARARGS
            )
        };
        // body-side run: walk back from the chain head over expr ops
        let mut s = hi;
        while s > ai && fam(self.instrs[s - 1].op) {
            s -= 1;
        }
        let n = hi - s;
        if n == 0 || self.instrs[hi - 1].op != Op::RAISE_VARARGS {
            return false;
        }
        // handler side: skip the bare-clause prelude
        let mut k = hi;
        let mut saw_pop_except = false;
        while k < self.instrs.len() {
            match self.instrs[k].op {
                Op::PUSH_EXC_INFO
                | Op::POP_TOP
                | Op::NOP
                | Op::NOT_TAKEN
                | Op::CACHE => {
                    k += 1;
                }
                Op::POP_EXCEPT => {
                    saw_pop_except = true;
                    k += 1;
                    break;
                }
                _ => return false,
            }
        }
        if !saw_pop_except || k + n > self.instrs.len() {
            return false;
        }
        for t in 0..n {
            let x = &self.instrs[s + t];
            let y = &self.instrs[k + t];
            if x.op != y.op || x.arg != y.arg {
                return false;
            }
        }
        // past the handler-side copy: only chain scaffolding or code end
        let mut m = k + n;
        while m < self.instrs.len() {
            if !matches!(
                self.instrs[m].op,
                Op::COPY
                    | Op::SWAP
                    | Op::POP_EXCEPT
                    | Op::RERAISE
                    | Op::NOP
                    | Op::NOT_TAKEN
                    | Op::CACHE
            ) {
                return false;
            }
            m += 1;
        }
        true
    }

    /// Extent of the out-of-line handler chain starting at `from`: runs
    /// through clause bodies and trailing cleanups, ending after the last
    /// RERAISE not followed by more cleanup.
    fn chain_extent(&self, from: usize) -> usize {
        let Some(&i) = self.idx_of.get(&from) else {
            return from;
        };
        // except* chain: clauses match with CHECK_EG_MATCH and the
        // epilogue re-raises via PREP_RERAISE_STAR
        let _is_star_chain = self.instrs[i..]
            .iter()
            .take(80)
            .any(|x| x.op == Op::CHECK_EG_MATCH || x.op == Op::PREP_RERAISE_STAR);
        // a depth-0 entry inside the span whose target is another chain
        // head protects a REAL body laid out after this chain (a whole-
        // function try whose handler precedes its body) — stop before it
        let mut body_stops: Vec<usize> = Vec::new();
        for e in &self.exc_entries {
            if e.depth == 0 && e.start > from && self.chain_heads.contains(&e.target) {
                // chain-internal fragments (clause-closing jumps and
                // cleanup tails redirected onward) consist only of
                // cleanup/jump ops — real bodies contain user code
                let frag = self
                    .idx_of
                    .get(&e.start)
                    .map(|&si| {
                        self.instrs[si..]
                            .iter()
                            .take_while(|x| x.offset < e.end)
                            .all(|x| {
                                matches!(
                                    x.op,
                                    Op::COPY
                                        | Op::SWAP
                                        | Op::POP_TOP
                                        | Op::POP_EXCEPT
                                        | Op::RERAISE
                                        | Op::LOAD_CONST
                                        | Op::STORE_FAST
                                        | Op::STORE_NAME
                                        | Op::STORE_DEREF
                                        | Op::DELETE_FAST
                                        | Op::DELETE_NAME
                                        | Op::DELETE_DEREF
                                        | Op::NOP
                                        | Op::NOT_TAKEN
                                        | Op::CACHE
                                        | Op::EXTENDED_ARG
                                        | Op::JUMP_FORWARD
                                        | Op::JUMP
                                        | Op::JUMP_NO_INTERRUPT
                                        // clause-exit hops: a handler
                                        // clause's `continue`/resume is
                                        // a BACKWARD jump out of the
                                        // chain (compileall 3.12 main:
                                        // the with-handler resume tail
                                        // POP_EXCEPT; POP_TOPs;
                                        // EXTENDED_ARG; JB->mainline
                                        // read as a real body stop and
                                        // truncated chain_extent, so
                                        // the resume jump fell through
                                        // to unclean)
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        | Op::JUMP_ABSOLUTE
                                )
                            })
                    })
                    .unwrap_or(false);
                if !frag {
                    body_stops.push(e.start);
                }
            }
        }
        // table closure: entries targeting this chain, plus entries whose
        // range lies inside the covered span (clause bodies and cleanup
        // redirects), transitively — the chain's code is scattered with
        // inline clause bodies that the canonical op scan cannot cross.
        // The span can never reach a body stop: that is main-flow code
        // following the chain (e.g. the try body after an async-with
        // cleanup handler), even when in-chain entries redirect to
        // far-away dead-end handlers (StopIteration intrinsics).
        let stop_cap = body_stops.iter().filter(|s| **s > from).min().copied();
        let mut table_end = from;
        loop {
            let mut grew = false;
            for e in &self.raw_exc_entries {
                let seed = e.start == from
                    || (e.target == from && e.start < from);
                let inside = e.start >= from
                    && e.start < table_end
                    && !body_stops.contains(&e.start);
                if (seed || inside) && !body_stops.contains(&e.start) {
                    // targets of in-chain redirects stay inside the span;
                    // a target that is ANOTHER chain head (e.g. a finally
                    // handler of the enclosing try) bounds it instead
                    let cands: [usize; 2] =
                        [e.end, if self.chain_heads.contains(&e.target) { from } else { e.target }];
                    for cand in cands {
                        if cand > table_end && cand > from {
                            if stop_cap.map_or(false, |cap| cand >= cap) {
                                continue;
                            }
                            table_end = cand;
                            grew = true;
                        }
                    }
                }
            }
            if !grew {
                break;
            }
        }
        let mut end = from;
        let mut k = i;
        while k < self.instrs.len() {
            let ins = &self.instrs[k];
            if body_stops.contains(&ins.offset) {
                break;
            }
            end = ins.end();
            if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                // the post-try resume can be sunk BEFORE the chain's
                // trailing machinery (mismatch RERAISE + zero-depth
                // stubs) — walk over that dead sequence so the extent
                // reaches the adjacent chain head (nesting adjacency)
                let mut t = k + 1;
                let mut stub_end = end;
                while let Some(nx) = self.instrs.get(t) {
                    if body_stops.contains(&nx.offset) {
                        break;
                    }
                    match nx.op {
                        Op::COPY
                        | Op::SWAP
                        | Op::POP_EXCEPT
                        | Op::POP_TOP
                        | Op::RERAISE
                        | Op::NOP
                        | Op::NOT_TAKEN => {
                            stub_end = nx.end();
                            t += 1;
                        }
                        _ => break,
                    }
                }
                end = stub_end;
                break;
            }
            if ins.op == Op::RERAISE {
                // the chain continues through cleanup tails AND through
                // the pattern loads of a following clause — it only ends
                // when no CHECK_EXC_MATCH is reachable through the
                // cleanup/pattern vocabulary
                let mut m = k + 1;
                let mut cont = false;
                let mut stop_at = None;
                let mut last_cleanup_end = None;
                let mut steps = 0;
                while let Some(nx) = self.instrs.get(m) {
                    if body_stops.contains(&nx.offset) {
                        stop_at = Some(nx.offset);
                        break;
                    }
                    match nx.op {
                        Op::CHECK_EXC_MATCH | Op::CHECK_EG_MATCH => {
                            cont = true;
                            break;
                        }
                        // the adjacent chain head ends this chain's extent
                        // exactly at the head (nesting adjacency)
                        Op::PUSH_EXC_INFO => {
                            stop_at = Some(nx.offset);
                            break;
                        }
                        Op::COPY
                        | Op::SWAP
                        | Op::POP_EXCEPT
                        | Op::POP_TOP
                        | Op::RERAISE
                        | Op::NOP
                        | Op::NOT_TAKEN
                        | Op::LIST_APPEND
                        | Op::CALL_INTRINSIC_2
                        | Op::PREP_RERAISE_STAR
                        | Op::POP_JUMP_IF_NOT_NONE
                        | Op::POP_JUMP_BACKWARD_IF_NOT_NONE => {
                            last_cleanup_end = Some(nx.end());
                            m += 1;
                            steps += 1;
                        }
                        // pattern loads only continue the chain when they
                        // lead to a CHECK_EXC_MATCH (tracked via cont)
                        Op::LOAD_CONST
                        | Op::LOAD_GLOBAL
                        | Op::LOAD_NAME
                        | Op::BUILD_TUPLE
                        | Op::BUILD_LIST
                        | Op::EXTENDED_ARG => {
                            m += 1;
                            steps += 1;
                        }
                        _ => break,
                    }
                    if steps > 16 {
                        break;
                    }
                }
                if let Some(sa) = stop_at {
                    end = sa;
                    break;
                }
                if !cont {
                    // walk the trailing dead cleanup tail (COPY/POP_EXCEPT/
                    // RERAISE zero-depth-finally padding) so the extent
                    // covers it; stop at anything that is not tail padding
                    let mut t = m;
                    let mut tail_end = last_cleanup_end;
                    while let Some(nx) = self.instrs.get(t) {
                        if body_stops.contains(&nx.offset) {
                            break;
                        }
                        match nx.op {
                            Op::COPY
                            | Op::SWAP
                            | Op::POP_EXCEPT
                            | Op::POP_TOP
                            | Op::RERAISE
                            | Op::NOP
                            | Op::NOT_TAKEN
                            | Op::LIST_APPEND
                            | Op::CALL_INTRINSIC_2
                            | Op::PREP_RERAISE_STAR
                            | Op::POP_JUMP_IF_NOT_NONE
                            | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                            | Op::JUMP_BACKWARD_NO_INTERRUPT => {
                                tail_end = Some(nx.end());
                                t += 1;
                            }
                            _ => break,
                        }
                    }
                    // 3.12: the post-try resume (straight-line loads
                    // ending in RETURN) is sunk between this chain's
                    // stubs and the enclosing chain head — span it so
                    // nesting adjacency holds. Stop AT the RETURN; a
                    // following chain head bounds the walk anyway.
                    let mut u = t;
                    let mut span = None;
                    let mut nops = 0;
                    while let Some(nx) = self.instrs.get(u) {
                        if body_stops.contains(&nx.offset) {
                            break;
                        }
                        match nx.op {
                            Op::NOP | Op::NOT_TAKEN => {
                                nops += 1;
                                u += 1;
                            }
                            Op::LOAD_FAST
                            | Op::LOAD_NAME
                            | Op::LOAD_CONST
                            | Op::LOAD_GLOBAL
                            | Op::LOAD_DEREF => {
                                nops += 1;
                                u += 1;
                            }
                            Op::RETURN_VALUE | Op::RETURN_CONST => {
                                // only a resume SUNK BETWEEN chains counts:
                                // an enclosing chain head must follow it
                                // (otherwise this is the function's real
                                // post-finally tail)
                                let next_is_head = self
                                    .instrs
                                    .get(u + 1)
                                    .map_or(false, |nx2| nx2.op == Op::PUSH_EXC_INFO);
                                if nops > 0 && nops <= 4 && next_is_head {
                                    span = Some(nx.end());
                                }
                                u += 1;
                                break;
                            }
                            _ => break,
                        }
                    }
                    if let Some(se) = span {
                        tail_end = Some(se);
                    }
                    if let Some(te) = tail_end {
                        end = te;
                    }
                    break;
                }
            }
            k += 1;
        }
        // the op scan stopping at a body stop already bounds the extent;
        // otherwise a table closure with no body stop (tail-most chain)
        // must not ride depth-0 lasti redirects to far-away dead-end
        // handlers (StopIterationError intrinsics) past the chain's own
        // trailing cleanup. The chain's normal-exit JUMP_FORWARDs target
        // exactly the main-flow resume point — cap the closure there.
        if stop_cap.is_none() {
            let mut exit_cap = usize::MAX;
            let mut k2 = i;
            while k2 < self.instrs.len() {
                let ins = &self.instrs[k2];
                if body_stops.contains(&ins.offset) {
                    break;
                }
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP) {
                    if let Some(t) = ins.target {
                        if t > ins.offset && t > from && t < exit_cap {
                            exit_cap = t;
                        }
                    }
                }
                if ins.op == Op::RERAISE && k2 + 1 < self.instrs.len() {
                    let nx = &self.instrs[k2 + 1];
                    if nx.op == Op::PUSH_EXC_INFO {
                        break;
                    }
                }
                if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                    break;
                }
                k2 += 1;
            }
            if exit_cap < usize::MAX {
                table_end = table_end.min(exit_cap);
            }
        }
        end.max(table_end)
    }

    /// Dispatch-loop end: the region end, additionally capped at the start
    /// of a NESTED try's protected code inside this region — the nested
    /// chain (folded by the body sub-walk) must not be re-parsed here.
    fn dispatch_region_end(&self, from: usize) -> usize {
        let mut end = self.handler_region_end(from);
        for e in &self.exc_entries {
            if e.start > from && e.start < end && e.target > from {
                // only a NESTED chain head bounds the region — an
                // except* clause body's lasti redirect targets in-chain
                // cleanup (LIST_APPEND stubs), not another chain.
                // A WITH cleanup handler also starts with PUSH_EXC_INFO
                // (WITH_EXCEPT_START / 3.14 LOAD_SPECIAL __exit__ in
                // its window): clause fragments protected by the
                // enclosing with must NOT cut the dispatch region
                // (codeop 3.13 _maybe_compile: the [394,396)->476
                // with fragment bounded the inner chain at 394 and
                // `except SyntaxError as e: pass` @422 was dropped)
                let is_chain_head = self
                    .idx_of
                    .get(&e.target)
                    .and_then(|&ti| {
                        let mut window_ok =
                            self.instrs.get(ti).map(|x| x.op) == Some(Op::PUSH_EXC_INFO);
                        if window_ok {
                            // a FINALLY/cleanup chain head also starts
                            // with PUSH_EXC_INFO but holds no exc match
                            // (code 3.13 interact: the KI clause's
                            // POP_EXCEPT+resume fragment is protected by
                            // the enclosing finally 1340; bounding the
                            // KI dispatch there cut the chain at 1020
                            // and dropped the chained SystemExit clause)
                            let mut saw_match = false;
                            for x in self.instrs.iter().skip(ti).take(40) {
                                if matches!(
                                    x.op,
                                    Op::WITH_EXCEPT_START | Op::LOAD_SPECIAL
                                ) {
                                    window_ok = false;
                                    break;
                                }
                                if x.op == Op::CHECK_EXC_MATCH
                                    || x.op == Op::CHECK_EG_MATCH
                                {
                                    saw_match = true;
                                }
                                if x.op == Op::RERAISE {
                                    break;
                                }
                            }
                            if !saw_match {
                                window_ok = false;
                            }
                        }
                        window_ok.then_some(ti)
                    })
                    .is_some();
                if is_chain_head {
                    end = e.start;
                }
            }
        }
        end
    }

    /// Save the outer legacy-chain state so a nested chain (a try inside
    /// an except body) can parse in the single legacy_try/legacy_handler
    /// slots; `finish_legacy_nest` restores it right before the nested
    /// Try is emitted so push_stmt routes it into the outer handler body.
    fn begin_legacy_nest(&mut self) {
        self.legacy_nest.push(LegacyNest {
            outer_try: self.legacy_try.take(),
            outer_handler: self.legacy_handler.take(),
            outer_handler_end: self.legacy_handler_end.take(),
            outer_prelude: self.in_handler_prelude,
            depth: self.blocks.len(),
            skipped_chain: None,
        });
        self.in_handler_prelude = false;
    }

    /// The nested body-end jump flies over the nested handler chain
    /// (py2 emits JUMP_ABSOLUTE here, which the walk follows): parse the
    /// skipped chain [handler_start, target) with a region sub-walk, fold
    /// any handler the sub-walk left open (a terminating `return` body
    /// breaks it before END_FINALLY), and mark the chain done when at
    /// least one clause was parsed — the jump past the chain end IS the
    /// chain completion for a nested try
    fn parse_skipped_nested_chain(&mut self, target: usize) -> bool {
        let Some(lt) = self.legacy_try.clone() else {
            return false;
        };
        if !lt.handlers.is_empty() || target <= lt.handler_start {
            return false;
        }
        // the body-end jump flies over BOTH the nested chain AND the
        // stashed outer chain's else region: clamp the sub-walk at the
        // outer else_start and parse the else span separately into the
        // outer chain (audiodev 2.7 AudioDev: the else body
        // `return Play_Audio_sgi()` executed inside this sub-walk and
        // push_stmt's nest routing sent it to the outer HANDLER body,
        // ahead of the nested Try)
        let mut end = target;
        let mut outer_else: Option<(usize, usize, usize)> = None;
        if let Some(ni) = self.legacy_nest.len().checked_sub(1) {
            if let Some(olt) = &self.legacy_nest[ni].outer_try {
                if let Some(es) = olt.else_start {
                    if es > lt.handler_start && es < end {
                        outer_else = Some((es, end, ni));
                        end = es;
                    }
                }
            }
        }
        self.skipped_chain_landing = Some(target);
        self.legacy_nest_depth += 1;
        self.decompile_region(lt.handler_start, end);
        self.legacy_nest_depth -= 1;
        if let Some(nest) = self.legacy_nest.last_mut() {
            nest.skipped_chain = Some((lt.handler_start, end));
        }
        if let Some(h) = self.legacy_handler.take() {
            if let Some(l) = self.legacy_try.as_mut() {
                l.handlers.push(ExceptHandler {
                    type_: h.type_,
                    name: h.name,
                    body: h.body,
                    is_star: false,
                });
            }
            self.legacy_handler_end = None;
        }
        let has_clauses = self
            .legacy_try
            .as_ref()
            .map_or(false, |l| !l.handlers.is_empty());
        if has_clauses {
            // this chain's OWN else region may also have been flown
            // over: py2 pads a handler's terminating `raise` with a
            // dead JUMP_ABSOLUTE to the chain end (audiodev 2.7:
            // JABS 112->130 after `raise error, ...` flew over the
            // else span [116,126) holding
            // `return Audio_mac.Play_Audio_mac()`) — parse it now,
            // before the redirect is disarmed
            let skipped_else = self.legacy_try.as_ref().and_then(|l| {
                l.else_start.filter(|&es| {
                    l.orelse.is_empty() && es > lt.handler_start && es < end
                })
            });
            if let Some(l) = self.legacy_try.as_mut() {
                l.chain_done = true;
            }
            if let Some(es) = skipped_else {
                let stop = self
                    .idx_of
                    .get(&es)
                    .and_then(|&ei| {
                        self.instrs[ei + 1..]
                            .iter()
                            .take_while(|x| x.offset < end)
                            .find(|x| {
                                x.op == Op::END_FINALLY
                                    || (matches!(
                                        x.op,
                                        Op::JUMP_FORWARD
                                            | Op::JUMP_ABSOLUTE
                                            | Op::JUMP
                                    ) && !x.is_backward)
                            })
                            .map(|x| x.offset)
                    })
                    .unwrap_or(end);
                if stop > es {
                    self.region_collect_only = true;
                    let stmts = self.decompile_region(es, stop);
                    self.region_collect_only = false;
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.orelse.extend(stmts);
                    }
                }
            }
            // the region after the chain belongs to the OUTER flow —
            // never redirect statements into the nested else
            if let Some(l) = self.legacy_try.as_mut() {
                l.else_start = None;
            }
        }
        // the clamped-away outer else span: parse it into the stashed
        // outer chain's orelse — by its recorded nest INDEX: the region
        // sub-walk pushes deeper stashes (the nested chain's own), so
        // last() would drop the else into the WRONG chain (audiodev
        // 2.7: `else: return Play_Audio_sgi()` rendered on the nested
        // sunaudiodev try instead of the outer al try)
        if let Some((es, oe, ni)) = outer_else {
            self.region_collect_only = true;
            let stmts = self.decompile_region(es, oe);
            self.region_collect_only = false;
            if let Some(nest) = self.legacy_nest.get_mut(ni) {
                if let Some(olt) = &mut nest.outer_try {
                    olt.orelse.extend(stmts);
                    olt.chain_done = true;
                    olt.else_start = None;
                }
            }
        }
        matches!(self.legacy_try.as_ref(), Some(l) if !l.handlers.is_empty())
    }

    /// Restore the saved outer chain state, returning the nesting depth
    /// (blocks that opened inside the nested chain and are still open must
    /// be closed before the nested Try is emitted).
    fn finish_legacy_nest(&mut self) -> Option<usize> {
        let nest = self.legacy_nest.pop()?;
        self.legacy_try = nest.outer_try;
        self.legacy_handler = nest.outer_handler;
        self.legacy_handler_end = nest.outer_handler_end;
        self.in_handler_prelude = nest.outer_prelude;
        // the restored outer chain's else region ends at the nested
        // chain's merge: the inner chain's tail END_FINALLY is the last
        // thing before the flow rejoins the outer else region's end —
        // with an unbounded else_stop the outer redirect would swallow
        // every statement past the inner chain into the else arm (3.3
        // fileinput readline: the post-merge savestdout/sys.stdout tail
        // landed inside `else:`)
        if let Some(lt) = self.legacy_try.as_mut() {
            if lt.else_start.is_some() && lt.else_stop == usize::MAX {
                if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                    let stop = self.instrs[ci..]
                        .iter()
                        .take(600)
                        .find(|x| x.op == Op::END_FINALLY)
                        .and_then(|x| {
                            self.idx_of.get(&x.offset).and_then(|&xi| {
                                self.instrs.get(xi + 1).map(|y| y.offset)
                            })
                        });
                    if let Some(sp) = stop {
                        // the handler's normal-exit jump target is the
                        // AUTHORITATIVE else merge: the END_FINALLY-based
                        // stop is only the nested chain's merge, and
                        // trailing statements of the else arm live between
                        // it and the real merge (_osx_support 3.8
                        // _get_system_version: `if m is not None:` after
                        // the nested try/finally was hoisted out of the
                        // else arm, running it on the except path where
                        // `m` is unbound). When no handler-exit jump is
                        // found the nested merge stands (3.3 fileinput
                        // readline).
                        let handler_exit = self
                            .instrs
                            .iter()
                            .find(|x| {
                                x.offset >= lt.handler_start
                                    && x.offset < lt.else_start.unwrap_or(usize::MAX)
                                    && matches!(
                                        x.op,
                                        Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
                                    )
                                    && x.target.map_or(false, |t| t > sp)
                            })
                            .and_then(|x| x.target);
                        lt.else_stop = handler_exit.unwrap_or(sp);
                    }
                }
            }
        }
        // the nested chain's handler-exit jump landing exactly on the
        // outer else_start means the outer handler flow continues into
        // that region: it is a trailing statement zone, not an else
        if let Some(lt) = self.legacy_try.as_mut() {
            if !lt.handlers.is_empty() && self.legacy_handler.is_none() {
                lt.chain_done = true;
            }
        }
        if let (Some((rs, re)), Some(lt)) = (nest.skipped_chain, self.legacy_try.as_mut()) {
            if let Some(es) = lt.else_start {
                let exit_lands_on_else = self
                    .idx_of
                    .get(&rs)
                    .map_or(false, |&ri| {
                        self.instrs[ri..]
                            .iter()
                            .take_while(|x| x.offset < re)
                            .any(|x| {
                                matches!(x.op, Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE)
                                    && x.target == Some(es)
                            })
                    });
                if exit_lands_on_else {
                    lt.else_start = None;
                }
            }
        }
        Some(nest.depth)
    }

    /// Restore without block bookkeeping (the emission sites where the
    /// nested chain's blocks are already closed)
    fn restore_legacy_nest(&mut self) {
        let _ = self.finish_legacy_nest();
    }

    /// Drive the pre-3.11 try/except handler chain state machine.
    fn legacy_chain_step(&mut self, inst: &Instruction) {
        if self.version.at_least(3, 11) {
            return;
        }
        let pos = inst.offset;
        // consecutive SETUP_FINALLY nesting (3.8-3.10): handler regions
        // are laid out in source order, but the chains stash in nesting
        // order — when this position is a STASHED chain's handler start,
        // swap that chain into the active slot so the clause parses into
        // the right try
        if self.legacy_handler.is_none()
            && self
                .legacy_try
                .as_ref()
                .map_or(false, |l| l.handler_start != pos)
        {
            let mut swap_idx = None;
            for (i, nest) in self.legacy_nest.iter().enumerate() {
                if nest
                    .outer_try
                    .as_ref()
                    .map_or(false, |t| t.handler_start == pos)
                {
                    swap_idx = Some(i);
                    break;
                }
            }
            if let Some(i) = swap_idx {
                let mut nest = self.legacy_nest.remove(i);
                let stashed = nest.outer_try.take();
                nest.outer_try = self.legacy_try.take();
                // when the swapped-in chain folds, its Try statement
                // belongs to the swapped-out chain's body
                self.legacy_body_redirect =
                    nest.outer_try.as_ref().map(|l| l.handler_start);
                self.legacy_try = stashed;
                self.legacy_nest.push(nest);
            }
        }
        let Some(mut lt) = self.legacy_try.clone() else {
            return;
        };

        // deferred fold for a handler ended by a bare/plain raise (3.10+:
        // no POP_EXCEPT/RERAISE/END_FINALLY follows to run the historical
        // close). Folding here — one instruction later — lets the dispatch
        // for the RAISE_VARARGS first push Stmt::Raise into the handler
        // body, then the handler is collected into the chain like the
        // RERAISE arm does.
        if self
            .legacy_handler
            .as_ref()
            .map_or(false, |h| h.bare_raise_fold)
        {
            self.close_handler_blocks();
            self.flush_pending_stores();
            if let Some(h) = self.legacy_handler.take() {
                if let Some(he) = &h.name {
                    if let Expr::Name(n) = &**he {
                        self.pending_as_cleanup = Some(n.clone());
                    }
                }
                self.legacy_handler_end = None;
                if let Some(l) = self.legacy_try.as_mut() {
                    l.handlers.push(ExceptHandler {
                        type_: h.type_,
                        name: h.name,
                        body: h.body,
                        is_star: false,
                    });
                }
            }
            // a handler ended by an unconditional raise is the LAST handler
            // (a non-final one would need a mismatch exit). When nothing
            // else can follow the chain (no else region, no POP_EXCEPT /
            // END_FINALLY / RERAISE cleanup path in the rest of the code —
            // the 3.10 branch-duplicated-return layout), flush the chain
            // NOW: the enclosing branch block (e.g. the if-then a bare
            // `except: raise` lives in) is still open, so the Try lands in
            // the right body instead of leaking to the function tail.
            let after = self
                .idx_of
                .get(&pos)
                .map(|&ci| ci + 1)
                .unwrap_or(self.instrs.len());
            let chain_complete = self
                .legacy_try
                .as_ref()
                .map_or(false, |l| !l.handlers.is_empty() && l.else_start.is_none())
                && !self.instrs.iter().skip(after).any(|x| {
                    matches!(x.op, Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE)
                });
            if chain_complete {
                if let Some(l) = self.legacy_try.take() {
                    self.restore_legacy_nest();
                    self.push_legacy_try(l);
                }
            }
        }
        // mark: an unconditional raise inside an open handler (no
        // handler-internal block open, no historical close instruction
        // following) ends the handler flow
        if matches!(inst.op, Op::RAISE_VARARGS)
            && inst.arg <= 1
            && self.version.at_least(3, 9)
            && self.legacy_handler.is_some()
            && self
                .legacy_handler
                .as_ref()
                .map_or(false, |h| self.blocks.len() <= h.block_depth)
        {
            let next_closes = self
                .idx_of
                .get(&pos)
                .and_then(|&ci| self.instrs.get(ci + 1))
                .map_or(false, |nx| {
                    matches!(nx.op, Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE)
                });
            if !next_closes {
                if let Some(h) = self.legacy_handler.as_mut() {
                    h.bare_raise_fold = true;
                }
            }
        }

        // bare `except:` entry: the handler starts with POP_TOPs instead of
        // DUP_TOP + COMPARE_OP + PJIF — open a typeless legacy handler whose
        // end is the first POP_EXCEPT / END_FINALLY / RERAISE
        if self.legacy_handler.is_none()
            && lt.handlers.is_empty()
            && lt.else_start.is_none()
            && pos == lt.handler_start
            && inst.op == Op::POP_TOP
        {
            let mut hend = usize::MAX;
            for ins in self.instrs.iter() {
                if ins.offset <= pos {
                    continue;
                }
                if matches!(ins.op, Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE) {
                    // a terminating handler runs POP_EXCEPT BEFORE its
                    // return/raise completes (3.8/3.9 `except: return
                    // (b, False)`: BUILD_TUPLE; ROT_FOUR; POP_EXCEPT;
                    // ROT_TWO; POP_TOP; RETURN) — this POP_EXCEPT is
                    // mid-body, not the clause end; keep scanning to the
                    // RERAISE/END_FINALLY past the terminator (bdb
                    // 3.8/3.9 effective: collecting at the POP_EXCEPT
                    // rendered `except: pass` and leaked the return into
                    // the enclosing else arm)
                    if ins.op == Op::POP_EXCEPT {
                        let mut k = self
                            .idx_of
                            .get(&ins.offset)
                            .map(|&i| i + 1)
                            .unwrap_or(self.instrs.len());
                        let mut terminator_return = false;
                        while k < self.instrs.len() {
                            match self.instrs[k].op {
                                Op::ROT_TWO
                                | Op::ROT_THREE
                                | Op::ROT_FOUR
                                | Op::POP_TOP
                                | Op::SWAP
                                | Op::COPY
                                | Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE => k += 1,
                                Op::RETURN_VALUE | Op::RETURN_CONST => {
                                    terminator_return = true;
                                    break;
                                }
                                _ => break,
                            }
                        }
                        if terminator_return {
                            continue;
                        }
                    }
                    hend = ins.offset;
                    break;
                }
            }
            if hend == usize::MAX {
                // a handler whose body TERMINATES (return/raise) has no
                // cleanup instruction: the clause runs to the chain's
                // merge point, where the collecting edge folds it
                // (bdb 3.6 effective: bare `except: return (b, False)`
                // with no POP_EXCEPT/END_FINALLY left the clause open
                // and swallowed the function tail)
                if let Some(m) = self.chain_merge_past(pos) {
                    hend = m;
                }
            }
            self.legacy_handler = Some(LegacyHandler {
                type_: None,
                name: None,
                body: Vec::new(),
                block_depth: self.blocks.len(),
                pop_seen: false, bare_raise_fold: false,
            });
            self.legacy_handler_end = Some(hend);
            self.in_handler_prelude = true;
        }

        // current handler body ends at the mismatch jump
        if self.legacy_handler.is_some() {
            let end = self.legacy_handler_end.unwrap_or(usize::MAX);
            // `except E: if c: break else: raise` (bz2 3.8-3.10
            // decompress): the mismatch target IS the inner guard arm's
            // break hop (POP_EXCEPT; JABS/JF -> loop exit). Collecting
            // the clause now leaves the inner If open with no fold
            // routing and leaks the break/raise to loop level (`break;
            // raise` rendered before the try). Defer: the arms rebuild
            // below and the chain end (RERAISE / END_FINALLY / JUMP arm)
            // folds the clause.
            let at_inner_break = self
                .legacy_handler
                .as_ref()
                .map_or(false, |h| self.blocks.len() > h.block_depth)
                && pos >= end
                && self
                    .idx_of
                    .get(&pos)
                    .and_then(|&pi| self.instrs.get(pi + 1))
                    .map_or(false, |nx| {
                        matches!(
                            nx.op,
                            Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP
                        ) && nx
                            .target
                            .map_or(false, |t| t > pos && self.find_loop_exit(t).is_some())
                    });
            if pos >= end && !at_inner_break {
                // inner blocks (a guard If of the handler body) whose end
                // coincides with the handler end must fold into the handler
                // body FIRST: closing them after the take() leaks their
                // statement to the enclosing block — contextlib 3.3 __exit__
                // bare except `if sys.exc_info()[1] is not value: raise`
                // hoisted ahead of the try (If[205,211] was still open when
                // the clause collected at the POP_EXCEPT 211)
                if let Some(d) = self.legacy_handler.as_ref().map(|h| h.block_depth) {
                    if self.blocks.len() > d && self.blocks.iter().skip(d).all(|b| b.end <= pos) {
                        self.close_handler_blocks();
                    } else if self.blocks.len() > d {
                        // a handler-internal guard If whose false-merge
                        // lands PAST the handler end (the mismatch
                        // END_FINALLY / merge sits between the guard's
                        // raise arm and its merge): the block overshoots
                        // `pos`, so the `end <= pos` gate above leaves it
                        // open and the clause would fold with an EMPTY
                        // body while the guard's `raise` stays trapped in
                        // the still-open If — which then escapes to
                        // function level ahead of the try and swallows it
                        // (asyncore 2.7 close: `if why.args[0] not in
                        // (ENOTCONN,EBADF): raise` rendered before the
                        // try, the try nested inside it). Only fold
                        // blocks that opened INSIDE this handler
                        // (start > handler_start) AND strictly before
                        // the fold point (start < pos), so their body
                        // region has already been walked into b.stmts.
                        // A block opening exactly AT pos (the handler
                        // end / mismatch target) has an unwalked body —
                        // force-closing it would emit an empty guard and
                        // strand the real body at function level
                        // (contextlib 3.8 __exit__: the next clause's
                        // guard If[238,244] opens at the handler end).
                        if self.blocks.iter().skip(d).all(|b| {
                            b.start > lt.handler_start && b.start < pos
                        }) {
                            self.close_handler_blocks();
                        }
                    }
                }
                if self.legacy_handler.is_some() {
                    self.flush_pending_stores();
                }
                if let Some(h) = self.legacy_handler.take() {
                    if let Some(he) = &h.name {
                        if let Expr::Name(n) = &**he {
                            self.pending_as_cleanup = Some(n.clone());
                        }
                    }
                    if let Some(lt) = self.legacy_try.as_mut() {
                        lt.handlers.push(ExceptHandler {
                            type_: h.type_,
                            name: h.name,
                            body: h.body,
                            is_star: false,
                        });
                    }
                }
                self.legacy_handler_end = None;
                // refresh the local snapshot: when THIS instruction is
                // also the chain's merge edge (a bare-except clause
                // ending in a terminator collects exactly at the
                // trampoline), the JABS arm below must see the fresh
                // handler count — the stale clone skipped the emit
                // decision and the chain fell to the end-of-walk flush,
                // landing the Try at loop level instead of inside the
                // enclosing else arm (bdb 3.6 effective)
                if let Some(fresh) = self.legacy_try.clone() {
                    lt = fresh;
                }
                // 3.10 fall-through chain end: the clause just folded
                // AT the merge (its POP_EXCEPT falls directly into
                // mainline code - the compiler dropped the exit
                // JUMP_FORWARD + dead RERAISE pair that <=3.9 emit).
                // No later instruction ever runs the chain-end
                // decision: the chain stays open, following statements
                // collect as post-chain content and the Try emission
                // defers to the end-of-walk flush, sinking every try
                // in the function past a phantom tail `return` (cgitb
                // 3.10 handle). Run the decision now - but only when
                // this instruction IS the mainline merge (not chain
                // machinery: <=3.9 folds at the POP_EXCEPT and its
                // JUMP_FORWARD/RERAISE decision sites must keep
                // running; a clause head ahead means more excepts
                // follow; a finally chain emits through its own path).
                if self.version.at_least(3, 10)
                    && !self.version.at_least(3, 11)
                    && !lt.chain_done
                    && !lt.has_finally
                    && !lt.handlers.is_empty()
                    // the fold ran AT the clause's POP_EXCEPT: <=3.9
                    // keeps an exit JUMP_FORWARD + dead RERAISE after
                    // it whose own decision sites must run instead;
                    // 3.10 drops the pair when the merge is the very
                    // next instruction - check that successor is
                    // mainline code, not chain machinery
                    && inst.op == Op::POP_EXCEPT
                    && !lt
                        .pending_mismatch
                        .iter()
                        .any(|&t| t > pos && self.pending_clause_head_at(t))
                    && !self.as_cleanup_wrappers.iter().any(|(_, e)| *e > pos)
                    && self
                        .idx_of
                        .get(&pos)
                        .and_then(|&pi| self.instrs.get(pi + 1))
                        .map_or(false, |nx| {
                            !matches!(
                                nx.op,
                                Op::RERAISE
                                    | Op::END_FINALLY
                                    | Op::JUMP_FORWARD
                                    | Op::JUMP
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::POP_BLOCK
                                    | Op::POP_EXCEPT
                                    | Op::POP_TOP
                                    | Op::DUP_TOP
                            ) && !self.pending_clause_head_at(nx.offset)
                        })
                {
                    let has_else_after =
                        lt.else_start.map_or(true, |es| pos >= es) == false;
                    if has_else_after {
                        // an else region follows the chain: defer
                        // emission until the region is consumed
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.chain_done = true;
                        }
                        self.retract_escaping_else(pos);
                    } else {
                        let l = self.legacy_try.take().unwrap();
                        self.restore_legacy_nest();
                        self.push_legacy_try(l);
                        self.flush_completed_restored_chain();
                        return;
                    }
                }
            }
        }

        // bare `except:` continuation in a MULTI-handler chain: the previous
        // (typed) handler just closed at its mismatch-jump target, which is
        // this bare except's first POP_TOP. The entry check above only fires
        // for a bare except as the FIRST handler (handlers.is_empty() && pos
        // == handler_start); a trailing `except:` after `except E:` starts
        // here instead. Open a typeless handler so its body is collected as a
        // clause rather than hoisted to the enclosing block.
        if self.legacy_handler.is_none()
            && self.legacy_try.is_some()
            && inst.op == Op::POP_TOP
        {
            let try_active = self
                .legacy_try
                .as_ref()
                .map_or(false, |l| !l.handlers.is_empty() && l.else_start.is_none());
            if try_active {
                // confirm a bare-except shape: a run of POP_TOPs (the exc
                // triple, possibly after a pending-as cleanup store) leading
                // to a real body instruction — not a jump/terminal (which
                // would be chain-end glue, not a handler body).
                let mut k = self
                    .idx_of
                    .get(&pos)
                    .map(|&i| i + 1)
                    .unwrap_or(self.instrs.len());
                let mut pops = 0;
                let mut ok = false;
                let mut hend = usize::MAX;
                while k < self.instrs.len() && pops < 4 {
                    let ins = &self.instrs[k];
                    match ins.op {
                        Op::POP_TOP => {
                            pops += 1;
                            k += 1;
                        }
                        Op::STORE_FAST | Op::STORE_NAME | Op::DELETE_FAST
                        | Op::DELETE_NAME | Op::NOP => k += 1,
                        Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE
                        | Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
                        | Op::DUP_TOP => break,
                        _ => {
                            if pops >= 1 {
                                ok = true;
                                // handler body ends at its POP_EXCEPT /
                                // END_FINALLY / RERAISE
                                for e in self.instrs[k..].iter() {
                                    if matches!(
                                        e.op,
                                        Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE
                                    ) {
                                        hend = e.offset;
                                        break;
                                    }
                                }
                            }
                            break;
                        }
                    }
                }
                if ok {
                    self.legacy_handler = Some(LegacyHandler {
                        type_: None,
                        name: None,
                        body: Vec::new(),
                        block_depth: self.blocks.len(),
                        pop_seen: false, bare_raise_fold: false,
                    });
                    self.legacy_handler_end = Some(hend);
                    self.in_handler_prelude = true;
                }
            }
        }

        // swallow the implicit `name = None; del name` handler cleanup
        if self.legacy_handler.is_some() {
            // py3-only: the implicit `e = None; del e` handler cleanup.
            // py2 has NO implicit cleanup - a DELETE matching the handler
            // name there is an explicit source `del err` (_strptime) and
            // must be emitted
            let hname = if self.version.major >= 3 {
                self.legacy_handler
                    .as_ref()
                    .and_then(|h| match &h.name {
                        Some(e) => match &**e {
                            Expr::Name(n) => Some(n.clone()),
                            _ => None,
                        },
                        None => None,
                    })
            } else {
                None
            };
            if let Some(hname) = hname {
                // arm ONLY on the implicit-cleanup STORE (`LOAD_CONST
                // None; STORE name`) - a bare DELETE matching the name
                // is an explicit source `del err` (py3 _strptime has
                // one INSIDE the handler, before the implicit pair) and
                // must be emitted
                let nm = match inst.op {
                    Op::STORE_NAME => Some(self.const_name(inst.arg as usize)),
                    Op::STORE_FAST => Some(self.local_name(inst.arg as usize)),
                    Op::STORE_DEREF => self
                        .code
                        .deref_name(inst.arg as usize)
                        .map(str::to_string),
                    _ => None,
                };
                if nm.as_deref() == Some(hname.as_str()) {
                    let prev_none = self
                        .idx_of
                        .get(&inst.offset)
                        .and_then(|&ii| {
                            let mut p = ii;
                            loop {
                                if p == 0 {
                                    return Some(false);
                                }
                                p -= 1;
                                match self.instrs[p].op {
                                    Op::NOP | Op::CACHE | Op::NOT_TAKEN => {}
                                    Op::LOAD_CONST => {
                                        return Some(matches!(
                                            self.code
                                                .consts
                                                .get(self.instrs[p].arg as usize)
                                                .map(|o| &**o),
                                            Some(PyObject::None)
                                        ));
                                    }
                                    _ => return Some(false),
                                }
                            }
                        })
                        .unwrap_or(false);
                    if prev_none {
                        self.legacy_handler_cleanup = true;
                    }
                }
            }
        }

        match inst.op {
            // `except E as name:` (py3) / `except E, name:` (py2) — both
            // emit an explicit store inside the handler prelude whose value
            // is the phantom exception we never model. A body store instead
            // pops a real pushed value, so an empty simulation stack is the
            // discriminator (LOAD_CONST is prelude-allowed and would
            // otherwise let a first body statement be swallowed as a name).
            Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF => {
                // the `as` store sits inside the handler prelude (right
                // after the POP_TOPs); a store after real body instructions
                // started (prelude cleared) is a body statement
                let wants_name = self.in_handler_prelude
                    && (self.version.major >= 3 || self.legacy_nest_depth == 0)
                    && self.stack.is_empty()
                    && self
                        .legacy_handler
                        .as_ref()
                        .map(|h| h.name.is_none() && h.body.is_empty() && h.type_.is_some())
                        .unwrap_or(false);
                if wants_name {
                    // the `as name` store follows the match jump; let
                    // emit_store capture the target expression
                    self.legacy_handler_name_store = true;
                }
            }
            // end of a handler body
            Op::POP_EXCEPT => {
                self.in_handler_prelude = false;
                // 3.9 terminating handlers run POP_EXCEPT BEFORE the body
                // (`except E: return`): defer the fold to the body's end
                let next_is_body = self
                    .idx_of
                    .get(&pos)
                    .and_then(|&pi| self.instrs.get(pi + 1))
                    .map_or(false, |nx| {
                        !matches!(
                            nx.op,
                            Op::RERAISE
                                | Op::END_FINALLY
                                | Op::JUMP_FORWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP
                        ) && self
                            .legacy_handler_end
                            .map_or(true, |e| nx.offset < e)
                    });
                // the same inner-arm break shape one instruction later:
                // POP_EXCEPT here belongs to the guard arm's escape, the
                // handler stays open for the arm rebuild
                let inner_break_pop = self
                    .legacy_handler
                    .as_ref()
                    .map_or(false, |h| self.blocks.len() > h.block_depth)
                    && self
                        .idx_of
                        .get(&pos)
                        .and_then(|&pi| self.instrs.get(pi + 1))
                        .map_or(false, |nx| {
                            nx.offset > pos
                                && matches!(
                                    nx.op,
                                    Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP
                                )
                                && nx.target.map_or(false, |t| {
                                    t > nx.offset && self.find_loop_exit(t).is_some()
                                })
                        });
                if next_is_body || inner_break_pop {
                    if let Some(h) = self.legacy_handler.as_mut() {
                        h.pop_seen = true;
                    }
                } else {
                    // 3.8-3.10 `except E: break`: the break body IS the
                    // exit jump (POP_EXCEPT; JABS loop-exit) — a forward
                    // JABS to a loop exit after the clause's collected
                    // statements is the clause's break, not the normal-
                    // exit cleanup (_compression read 3.9: the late close
                    // rendered `except: pass` and leaked the Break into
                    // the enclosing then-arm; code 3.8/3.9 interact: the
                    // KI clause's `write(...); break` folded WITHOUT the
                    // break, which then ejected to loop level ahead of
                    // the chain's Try). Push it and skip the jump; the
                    // dead second cleanup pair stays in the linear walk's
                    // path and is consumed by the chain machinery.
                    let handler_break = self
                        .legacy_handler
                        .as_ref()
                        // no block open inside the handler: with an inner
                        // If/loop still open (bz2 3.9 decompress `except
                        // OSError: if results: break else: raise`) the
                        // POP_EXCEPT;JABS is the inner arm's break path —
                        // normal dispatch routes it into the open arm.
                        // a body already ending in a terminator means the
                        // exit jump is dead padding after it, not a
                        // source-level break (mirrors the add_cont guard);
                        // a body ending in an If/else-escape arm whose
                        // region is still AHEAD (the bz2 `else: raise`
                        // lies past this jump) also keeps the historic
                        // path — folding here renders the escape flat and
                        // loses the sig-exact else. The admitted shape is
                        // a run of plain statements (code 3.8/3.9
                        // interact `except EOFError: write('\n'); break`)
                        .map_or(false, |h| {
                            self.blocks.len() <= h.block_depth
                                && !h.body.iter().any(|s| {
                                    ends_scope(s)
                                        || matches!(
                                            s,
                                            Stmt::If { orelse, .. }
                                                if !orelse.is_empty()
                                        )
                                })
                        })
                        && self
                            .instrs
                            .get(
                                self.idx_of
                                    .get(&pos)
                                    .map(|&pi| pi + 1)
                                    .unwrap_or(usize::MAX),
                            )
                            .map_or(false, |nx| {
                                nx.offset > pos
                                    && matches!(
                                        nx.op,
                                        Op::JUMP_ABSOLUTE
                                            | Op::JUMP_FORWARD
                                            | Op::JUMP
                                    )
                                    && nx.target
                                        .map_or(false, |t| {
                                            t > nx.offset
                                                && self.find_loop_exit(t).is_some()
                                        })
                            });
                    if handler_break {
                        self.close_handler_blocks();
                        self.flush_pending_stores();
                        if let Some(h) = self.legacy_handler.as_mut() {
                            h.body.push(Stmt::Break);
                        }
                        if let Some(&pi2) = self.idx_of.get(&pos) {
                            if let Some(t) = self.instrs.get(pi2 + 1)
                                .and_then(|nx| nx.target)
                            {
                                self.mark_guard_else_over_break(t);
                            }
                        }
                        if let Some(&pi) = self.idx_of.get(&pos) {
                            if let Some(nx) = self.instrs.get(pi + 1) {
                                                                self.skip_until = Some(nx.end());
                            }
                        }
                    }
                    if self.legacy_handler.is_some() {
                        self.close_handler_blocks();
                        self.flush_pending_stores();
                    }
                    // 3.8-3.10 `continue` inside an except handler of a
                    // try/except/finally in a loop: the continue path is
                    // POP_EXCEPT; POP_BLOCK; <inline finally copy>;
                    // JABS loop-top. Fold the copy, end the case with a
                    // Continue, and resume at the handler's normal exit.
                    if let Some(&pi) = self.idx_of.get(&self.cur_offset) {
                        let mut q = pi + 1;
                        if self.instrs.get(q).map(|x| x.op) == Some(Op::POP_BLOCK) {
                            q += 1;
                            let fin_from = self.instrs.get(q).map(|x| x.offset);
                            let mut jb = None;
                            while let Some(x) = self.instrs.get(q) {
                                if (x.op == Op::JUMP_ABSOLUTE && x.is_backward)
                                    || matches!(
                                        x.op,
                                        Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    )
                                {
                                    jb = Some((x.end(), x.target));
                                    break;
                                }
                                if x.op == Op::RERAISE || x.op == Op::END_FINALLY {
                                    break;
                                }
                                q += 1;
                            }
                            let jb_is_loop_top = jb.map_or(false, |(_, t)| {
                                t.map_or(false, |t| {
                                    self.blocks.iter().any(|b| {
                                        matches!(
                                            b.kind,
                                            BlockType::While | BlockType::For
                                        ) && (b.start == t || b.cond_end == t)
                                    })
                                })
                            });
                            if jb_is_loop_top {
                                // the enclosing finally chain: either the
                                // active legacy record or the still-open
                                // outer Try block's handler (its close
                                // POP_BLOCK comes later in the layout)
                                let fh = self
                                    .legacy_try
                                    .as_ref()
                                    .and_then(|l| {
                                        if l.has_finally {
                                            Some(l.handler_start)
                                        } else {
                                            None
                                        }
                                    })
                                    .or_else(|| {
                                        self.blocks.iter().rev().find_map(|b| {
                                            if b.kind == BlockType::Try
                                                && b.end > self.cur_offset
                                            {
                                                Some(b.end)
                                            } else {
                                                None
                                            }
                                        })
                                    });
                                if let Some(fh) = fh {
                                    // decompile the inline copy and fold
                                    // the OUTER finally chain with it
                                    let jbe = jb.unwrap().0;
                                    let fin_stmts = match fin_from {
                                        Some(ff) if jbe > ff => {
                                            self.decompile_region(ff, jbe)
                                        }
                                        _ => Vec::new(),
                                    };
                                    if let Some(l) = self.legacy_try.take() {
                                        let inner = Stmt::Try {
                                            body: l.body,
                                            handlers: l.handlers,
                                            orelse: l.orelse,
                                            finalbody: fin_stmts,
                                        };
                                        let outer = Stmt::Try {
                                            body: vec![inner],
                                            handlers: Vec::new(),
                                            orelse: Vec::new(),
                                            finalbody: self
                                                .decompile_region(
                                                    fh,
                                                    self.idx_of
                                                        .get(&fh)
                                                        .and_then(|&hi| {
                                                            self.instrs[hi..]
                                                                .iter()
                                                                .take(200)
                                                                .find(|x| {
                                                                    matches!(
                                                                        x.op,
                                                                        Op::RERAISE
                                                                            | Op::END_FINALLY
                                                                    )
                                                                })
                                                                .map(|x| x.offset)
                                                        })
                                                        .unwrap_or(fh),
                                                ),
                                        };
                                        self.push_stmt(outer);
                                    }
                                    // the open handler's clause becomes
                                    // the continue path; close it and any
                                    // If left open inside it
                                    if let Some(mut h) = self.legacy_handler.take() {
                                        while self.blocks.last().map_or(
                                            false,
                                            |t| t.kind == BlockType::If,
                                        ) {
                                            let e = self
                                                .blocks
                                                .last()
                                                .map(|t| t.end)
                                                .unwrap_or(0);
                                            self.force_close_top(e);
                                        }
                                        h.body.push(Stmt::Continue);
                                        if let Some(lt) = self.legacy_try.as_mut() {
                                            lt.handlers.push(ExceptHandler {
                                                type_: h.type_,
                                                name: h.name,
                                                body: h.body,
                                                is_star: false,
                                            });
                                        }
                                    }
                                    self.legacy_handler_end = None;
                                                                        self.skip_until = Some(jbe);
                                    return;
                                }
                            }
                        }
                    }
                    let add_cont = self
                        .idx_of
                        .get(&self.cur_next)
                        .and_then(|&ni| self.instrs.get(ni))
                        .map_or(false, |x| {
                            matches!(
                                x.op,
                                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP
                            ) && x.target.map_or(false, |t| {
                                let te = self.effective_offset(t);
                                self.blocks.iter().any(|b| {
                                    matches!(
                                        b.kind,
                                        BlockType::While | BlockType::For
                                    ) && self.effective_offset(b.start) == te
                                })
                            })
                        })
                        && !self
                            .legacy_handler
                            .as_ref()
                            // a handler body already ending in a terminator
                            // (break/continue/return/raise) makes the trailing
                            // JABS-to-loop-top dead code, NOT a source-level
                            // continue: `except IndexError: break` compiles to
                            // BREAK_LOOP; POP_EXCEPT; JABS loop_top, and that
                            // JABS is the break's post-terminator padding. The
                            // forward-walk in handler_exit_jabs_is_continue
                            // can't see this (it counts the layout-adjacent
                            // else region as real statements) — guard on the
                            // terminator here (_sitebuiltins _Printer.__call__).
                            .map_or(true, |h| {
                                h.body.last().map_or(false, ends_scope)
                            });
                    if add_cont {
                        // only a continue that SKIPS real body statements
                        // is source-level; the implicit fall-through edge
                        // must not render (code.py 3.5 interact)
                        let jabs_real = self
                            .idx_of
                            .get(&self.cur_next)
                            .map_or(false, |&ni| {
                                self.handler_exit_jabs_is_continue(ni)
                            });
                        if jabs_real {
                            if let Some(h) = self.legacy_handler.as_mut() {
                                h.body.push(Stmt::Continue);
                            }
                        }
                    }
                    if let Some(h) = self.legacy_handler.take() {
                        if let Some(he) = &h.name {
                            if let Expr::Name(n) = &**he {
                                self.pending_as_cleanup = Some(n.clone());
                            }
                        }
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.handlers.push(ExceptHandler {
                                type_: h.type_,
                                name: h.name,
                                body: h.body,
                                is_star: false,
                            });
                        }
                    }
                    self.legacy_handler_end = None;
                }
            }
            // RERAISE ends the current handler; a mismatch-path RERAISE with
            // no open handler ends the whole chain
            Op::RERAISE => {
                self.in_handler_prelude = false;
                if self.legacy_handler.is_some() {
                    self.close_handler_blocks();
                    self.flush_pending_stores();
                }
                let mut folded_last_clause = false;
                if let Some(h) = self.legacy_handler.take() {
                    if let Some(he) = &h.name {
                        if let Expr::Name(n) = &**he {
                            self.pending_as_cleanup = Some(n.clone());
                        }
                    }
                    self.legacy_handler_end = None;
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.handlers.push(ExceptHandler {
                            type_: h.type_,
                            name: h.name,
                            body: h.body,
                            is_star: false,
                        });
                    }
                    // the just-collected clause may BE the last one: a
                    // clause whose arms all escape (bz2 3.10 decompress
                    // `except OSError: if results: break else: raise`)
                    // has NO normal-exit edge jumping to the merge, so
                    // nothing else ever runs the else-region decision —
                    // the presumed else would swallow the whole loop
                    // body. With no pending clause head ahead, this
                    // mismatch RERAISE is the chain end: run the
                    // decision now.
                    folded_last_clause = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            !l.handlers.is_empty()
                                && !l
                                    .pending_mismatch
                                    .iter()
                                    .any(|&m| m > pos && self.pending_clause_head_at(m))
                        });
                } else if self
                    .legacy_try
                    .as_ref()
                    .map(|l| !l.handlers.is_empty())
                    .unwrap_or(false)
                    // an UNPARSED clause head ahead means this RERAISE
                    // is an as-cleanup wrapper's re-raise mid-chain,
                    // not the chain-ending mismatch jump - emitting
                    // here leaks the remaining clauses to the linear
                    // walk (contextlib 3.10 __exit__: clause 1's
                    // cleanup RERAISE folded the chain before the
                    // RuntimeError/BaseException clauses)
                    && !self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            l.pending_mismatch.iter().any(|&t| {
                                t > pos && self.pending_clause_head_at(t)
                            })
                        })
                {
                    let has_else_after = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| l.else_start.map_or(true, |es| pos >= es) == false);
                    // every handler path raises (no POP_EXCEPT anywhere in
                    // the chain): the region at the body-jump target has no
                    // discoverable extent (a real else is delimited by the
                    // handler's exit jump, which does not exist here) and
                    // continuation treatment is semantically identical -
                    // retract the presumed else (crypt's module-level
                    // always-raising import guard)
                    if has_else_after {
                        let chain_start = self.legacy_try.as_ref().map(|l| l.handler_start);
                        if let (Some(hs), Some(&hi)) =
                            (chain_start, self.idx_of.get(&pos))
                        {
                            let always_raises = !self.instrs[..=hi]
                                .iter()
                                .any(|x| x.offset >= hs && x.op == Op::POP_EXCEPT);
                            if always_raises {
                                if let Some(l) = self.legacy_try.as_mut() {
                                    l.else_start = None;
                                }
                            }
                        }
                    }
                    let has_else_after = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| l.else_start.map_or(true, |es| pos >= es) == false);
                    if has_else_after {
                        // an else region follows the chain: defer emission
                        // until the region is consumed
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.chain_done = true;
                        }
                        self.retract_escaping_else(pos);
                    } else {
                        let l = self.legacy_try.take().unwrap();
                        self.restore_legacy_nest();
                        self.push_legacy_try(l);
                        self.flush_completed_restored_chain();
                    }
                }
                // the just-collected clause may BE the last one: a clause
                // whose arms all escape (bz2 3.10 decompress `except
                // OSError: if results: break else: raise`) has NO
                // normal-exit edge jumping to the merge, so no later
                // instruction ever runs the else-region decision — the
                // presumed else would swallow the whole loop body. With
                // no pending clause head ahead AND no live as-cleanup
                // copy (its RERAISE 1/2 re-raises mid-chain: b25
                // patterns clause 1), this RERAISE is the chain end: run
                // the decision now.
                if folded_last_clause
                    && inst.arg == 0
                    && self.legacy_handler.is_none()
                    && self.legacy_try.is_some()
                    && !self.as_cleanup_wrappers.iter().any(|(_, e)| *e > pos)
                    // an UNPARSED clause head ahead (a mismatch target
                    // still holding its DUP_TOP) means the chain
                    // continues past this RERAISE - emitting now leaks
                    // the remaining clauses to the linear walk
                    // (contextlib 3.10 __exit__: the else arm sits
                    // INLINE between POP_BLOCK and the chain, so no
                    // body-exit JF ever set else_start and clause 1's
                    // as-cleanup RERAISE folded the chain before the
                    // RuntimeError/BaseException clauses)
                    && !self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            l.pending_mismatch.iter().any(|&t| {
                                t > pos && self.pending_clause_head_at(t)
                            })
                        })
                {
                    let has_else_after = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            l.else_start.map_or(true, |es| pos >= es) == false
                        });
                    if has_else_after {
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.chain_done = true;
                        }
                        self.retract_escaping_else(pos);
                    } else {
                        let l = self.legacy_try.take().unwrap();
                        self.restore_legacy_nest();
                        self.push_legacy_try(l);
                        self.flush_completed_restored_chain();
                    }
                }
            }
            // END_FINALLY closes a finally handler (and the statement)
            Op::END_FINALLY => {
                // a swallowed as-cleanup wrapper's END_FINALLY is not the
                // chain end
                if self.as_cleanup_wrappers.iter().any(|(_, e)| *e == pos) {
                    return;
                }
                let mut end_at_chain = false;
                if let Some(l) = self.legacy_try.as_mut() {
                    if !l.handlers.is_empty() && !l.has_finally {
                        // last handler mismatch path: chain fully parsed
                        l.chain_done = true;
                        if l.else_start == Some(pos) {
                            // forward jump from the body landed exactly at
                            // the chain end: no else region, emit now
                            end_at_chain = true;
                        }
                    }
                }
                self.retract_escaping_else(pos);
                if end_at_chain {
                    let l = self.legacy_try.take().unwrap();
                    self.flush_pending_stores();
                    self.restore_legacy_nest();
                    self.push_stmt(Stmt::Try {
                        body: l.body,
                        handlers: l.handlers,
                        orelse: l.orelse,
                        finalbody: l.finalbody,
                    });
                    self.flush_completed_restored_chain();
                }
                if let Some(l) = self.legacy_try.as_mut() {
                    if l.has_finally {
                        // the inline finally body's trailing stores are
                        // still pending at the END_FINALLY — flush them
                        // INTO the finalbody (redirect is live while the
                        // chain is up) before taking it, or the Try loses
                        // its finally and renders as `unrecovered`
                        // (codeop _maybe_compile `err1 = err2 = None`)
                        self.flush_pending_stores();
                        let l = self.legacy_try.take().unwrap();
                        self.restore_legacy_nest();
                        self.push_legacy_try(l);
                        self.flush_completed_restored_chain();
                    }
                }
            }
            // a JUMP_FORWARD inside a handler (not part of an open handler
            // body anymore) ends the chain: emit try (+else target region)
            Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE => {
                // py2.7 dead glue (see is_dead_forward_glue): skip the
                // chain logic — the exec-side arms suppress it too
                if self.is_dead_forward_glue() {
                    return;
                }
                // py2 handler normal exits are forward jumps: one
                // landing exactly on the body jump's target retracts the
                // presumed else region (no-else chain). 3.8-3.10 share
                // the shape when the clause exit flows into the post-try
                // continuation (trailing-statement zone); the rare
                // terminating-else case (contextlib 3.9 __exit__) is
                // protected by the pending-clause guards at the chain
                // decision sites instead of skipping the retraction
                if lt.else_start == inst.target
                    && (self.legacy_handler.is_some() || !lt.handlers.is_empty())
                    && inst.target.map_or(false, |t| t > pos)
                {
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.else_start = None;
                    }
                }
                // 3.8-3.10 try/finally: the inline finally body ends with
                // the forward jump over the handler copy — emit and skip.
                // The jump must sit INSIDE the chain's own inline region:
                // a later jump (the with-exit protocol's tail JF past a
                // nested-finally close) must not flush a chain whose
                // region already ended — the emit would land outside the
                // enclosing with/loop block (bz2 3.9 close)
                if lt.has_finally
                    && self.legacy_handler.is_none()
                    && lt
                        .else_start
                        .map_or(false, |es| pos >= es && pos <= lt.else_stop)
                {
                    if let Some(target) = inst.target {
                        if target > pos && target >= lt.handler_start {
                            // crossed pending else arm: an open If/Else
                            // that started BEFORE the handler copy and
                            // ends strictly between the copy head and
                            // this terminal jump's target is overflown
                            // by the jump - skipping to the target
                            // swallows its else region (_bootsubprocess
                            // 3.9 wait: the finally copy's JABS 86->130
                            // flew over the parent-process else arm at
                            // 102 and `waitpid/returncode` vanished).
                            // Mark the If's else region (the generic
                            // forward-jump marking is short-circuited
                            // by this emit) and resume the walk AT the
                            // arm head; the handler copy itself stays
                            // skipped.
                            let mut resume = target;
                            let handler_start = lt.handler_start;
                            for b in self.blocks.iter_mut() {
                                if matches!(
                                    b.kind,
                                    BlockType::If | BlockType::Else
                                ) && b.start < handler_start
                                    && b.end > handler_start
                                    && b.end < target
                                    && b.end > pos
                                {
                                    if b.kind == BlockType::If
                                        && b.else_end.is_none()
                                    {
                                        b.else_end = Some(target);
                                    }
                                    resume = b.end;
                                    break;
                                }
                            }
                            self.flush_pending_stores();
                            let l = self.legacy_try.take().unwrap();
                            self.restore_legacy_nest();
                            self.push_legacy_try(l);
                            self.flush_completed_restored_chain();
                            {
                            // a nested try/finally INSIDE the restored
                            // chain's finally body shares this terminal
                            // jump (bz2 3.9/3.10 close `finally: {try:
                            // ... finally: ...}` — both inline copies
                            // end here): the restored chain's region
                            // also ends at this pos, so emit it too
                            // while the enclosing block is still open
                            while self.legacy_handler.is_none()
                                && self.legacy_try.as_ref().map_or(false, |l2| {
                                    l2.has_finally
                                        && l2.else_start.map_or(false, |es2| {
                                            pos >= es2 && pos <= l2.else_stop
                                        })
                                })
                            {
                                let l2 = self.legacy_try.take().unwrap();
                                self.restore_legacy_nest();
                                self.push_legacy_try(l2);
                            }
                            }
                            self.skip_until = Some(resume);
                            return;
                        }
                    }
                }
                // a handler normal-exit FORWARD jump with a parsed chain
                // and an unbounded else region lands on the chain merge
                // = the else region's end: bound the region so the
                // redirect stops there (3.3 fileinput readline: the
                // outer else ran to MAX and swallowed the post-merge
                // `savestdout` tail into the else arm)
                if !lt.handlers.is_empty()
                    && !lt.has_finally
                    // 3.8+ chains keep the unbounded region: their
                    // clause-exit forward jumps fly to sunk-return
                    // copies PAST the presumed trailing-statement zone,
                    // and bounding there strands the chain emit at the
                    // function tail (asynchat 3.9/3.10 handle_read: the
                    // recv try/except sank below the whole while loop).
                    // The SETUP_LOOP-era layout this fix targets has no
                    // sunk copies — the except-exit JF lands exactly on
                    // the merge (3.3 fileinput readline).
                    && !self.version.at_least(3, 8)
                    && lt.else_start.is_some()
                    && lt.else_stop == usize::MAX
                    && inst.target.map_or(false, |t| {
                        t > pos
                            && lt.else_start.map_or(false, |es| {
                                t > es
                                    // the span between the presumed else
                                    // start and this jump's target must
                                    // hold real code: a genuine else arm
                                    // does (fileinput 3.3 readline: the
                                    // except-exit JF flies over the whole
                                    // else arm to the merge); a presumed
                                    // trailing-statement zone ends at the
                                    // merge itself and the clause-exit JF
                                    // flies further to a sunk-return copy
                                    // — bounding there truncates the zone
                                    // mid-flow (asynchat 3.9/3.10
                                    // handle_read: the recv try sank to
                                    // the function tail)
                                    && self.instrs.iter().any(|x| {
                                        x.offset >= es
                                            && x.offset < t
                                            && !matches!(
                                                x.op,
                                                Op::NOP
                                                    | Op::NOT_TAKEN
                                                    | Op::CACHE
                                                    | Op::POP_TOP
                                                    | Op::POP_EXCEPT
                                                    | Op::POP_BLOCK
                                                    | Op::END_FINALLY
                                                    | Op::RERAISE
                                                    | Op::JUMP_FORWARD
                                                    | Op::JUMP_ABSOLUTE
                                                    | Op::JUMP
                                                    | Op::JUMP_BACKWARD
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            )
                                    })
                            })
                    })
                {
                    let t = inst.target.unwrap();
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.else_stop = t;
                    }
                    lt.else_stop = t;
                }
                // 3.5/3.6 deferred fold: the clause-exit back edge
                // arrives while the handler is STILL open (the as-
                // cleanup wrapper defers the fold past POP_EXCEPT:
                // POP_BLOCK; POP_EXCEPT; LOAD None; cleanup;
                // END_FINALLY; JABS->loop-top). Same structural test
                // as the folded case: a pending clause head ahead +
                // a backward edge onto the enclosing loop top means
                // this is the clause's normal exit fused with the
                // loop back edge — fold the handler WITHOUT the
                // source-level Continue and consume the jump
                // (asyncore 3.5/3.6 close_all clause 1). Scoped to
                // 3.5/3.6: 3.7 folds before the edge (the lh-none
                // consume above), and py2/3.9+ chain states rely on
                // their own fold paths (asyncore 2.7/3.9 close_all
                // tore when this fired there)
                if self.legacy_handler.is_some()
                    && !lt.has_finally
                    && self.version.at_least(3, 3)
                    && !self.version.at_least(3, 11)
                {
                    let clause_exit = inst.is_backward
                        && matches!(
                            inst.op,
                            Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                | Op::JUMP
                        )
                        && inst.target.map_or(false, |t| {
                            t < pos && self.is_loop_top_target(t)
                        })
                        && lt
                            .pending_mismatch
                            .iter()
                            .any(|&m| m > pos && self.pending_clause_head_at(m));
                    if clause_exit {
                        if let Some(mut h) = self.legacy_handler.take() {
                            while self.blocks.len() > h.block_depth {
                                let e = self
                                    .blocks
                                    .last()
                                    .map(|b| b.end.min(pos))
                                    .unwrap_or(pos);
                                self.force_close_top(e);
                            }
                            if let Some(he) = &h.name {
                                if let Expr::Name(n) = &**he {
                                    self.pending_as_cleanup = Some(n.clone());
                                }
                            }
                            if let Some(l) = self.legacy_try.as_mut() {
                                l.handlers.push(ExceptHandler {
                                    type_: h.type_,
                                    name: h.name,
                                    body: std::mem::take(&mut h.body),
                                    is_star: false,
                                });
                            }
                        }
                        self.legacy_handler_end = None;
                        // resume target: the next clause head when one
                        // is pending — an inline as-cleanup's
                        // exception-time copy (LOAD None; STORE; DEL;
                        // RERAISE) trails the exit edge and must not
                        // be walked as flow (3.9 close_all: walking it
                        // with a folded handler tore the remaining
                        // clauses); otherwise just past this jump
                        let mut resume = inst.end();
                        let next_head = lt
                            .pending_mismatch
                            .iter()
                            .copied()
                            .filter(|&m| m > pos)
                            .min();
                        if let Some(nh) = next_head {
                            if nh > resume {
                                resume = nh;
                            }
                        }
                        if self.skip_until.map_or(true, |sk| sk < resume) {
                            self.skip_until = Some(resume);
                        }
                        return;
                    }
                }
                if self.legacy_handler.is_none() && !lt.has_finally {
                    let in_else = lt
                        .else_start
                        .map_or(false, |es| pos >= es && pos < lt.else_stop);
                    let past_chain = lt
                        .else_start
                        .map_or(true, |es| pos >= es && pos >= lt.else_stop);
                    if let Some(target) = inst.target {
                        // handler normal-exit FORWARD jump landing exactly
                        // where the body's forward jump lands == no else
                        // region (a backward jump there is a loop back edge)
                        if !lt.handlers.is_empty()
                            && lt.else_start == Some(target)
                            && target > pos
                        {
                            if let Some(l) = self.legacy_try.as_mut() {
                                l.else_start = None;
                            }
                        }
                        let onto_loop_back_edge = self
                            .idx_of
                            .get(&target)
                            .and_then(|&ti| self.instrs.get(ti))
                            .map_or(false, |x| {
                                x.is_backward
                                    && matches!(
                                        x.op,
                                        Op::JUMP_ABSOLUTE
                                            | Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    )
                                    && x.target.map_or(false, |t| {
                                        self.blocks.iter().any(|b| {
                                            matches!(b.kind, BlockType::While | BlockType::For)
                                                && (b.start == t
                                                    || (b.cond_end != usize::MAX && b.cond_end == t))
                                        })
                                    })
                            })
                            // landing on a conditional back edge is an
                            // if/else MERGE trampoline, not a loop back
                            // edge: presuming an else there swallows the
                            // merge into a phantom else region and leaves
                            // the enclosing If's else arm orphaned
                            // (_compression read 3.5-3.7: the try-in-then
                            // arm's exit JABS landed on the merge's
                            // PJIF-to-loop-top and the whole else arm —
                            // needs_input/EOFError/decompress — vanished)
                            && !self
                                .idx_of
                                .get(&target)
                                .and_then(|&ti| self.instrs.get(ti))
                                .map_or(false, |x| {
                                    matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::JUMP_IF_FALSE_OR_POP
                                            | Op::JUMP_IF_TRUE_OR_POP
                                            | Op::FOR_ITER
                                    )
                                });
                        // a handler chain starting with POP_TOP (no
                        // DUP_TOP+match) is a bare `except:` — the body-end
                        // jump flies over the whole chain, there is no else
                        let bare_chain = self
                            .idx_of
                            .get(&lt.handler_start)
                            .and_then(|&hi2| self.instrs.get(hi2))
                            .map_or(false, |hx| hx.op == Op::POP_TOP);
                        // a forward jump landing exactly on an ENCLOSING
                        // loop's exit is the try-body tail's `break` edge,
                        // not an else-region head: presuming else swallows
                        // every post-loop statement into orelse
                        // (_sitebuiltins 3.8+ __setup: `try: with ...;
                        // break` — the break's JABS targets the FOR_ITER
                        // exit and the post-loop `if not data: ... linecnt`
                        // rendered as a try-else inside a never-closed For)
                        let onto_loop_exit = self.blocks.iter().any(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && b.end == target
                        });
                        // the body-end jump flies over an ENCLOSING
                        // branch's else boundary into the branch merge:
                        // an open If/Else whose end lies strictly
                        // between the handler head and the target owns
                        // the gap — the region past the chain is the
                        // branch's else arm, not a try-else (3.10
                        // _compression.read: `if eof: ... try: ...
                        // except: break / else: <needs_input arm>` —
                        // presuming else at the merge swallowed the
                        // whole else arm into the try's orelse and
                        // hoisted the try out of the then arm)
                        let crosses_branch_else = self.blocks.iter().any(|b| {
                            matches!(b.kind, BlockType::If | BlockType::Else)
                                && b.end > lt.handler_start
                                && b.end < target
                        });
                        if lt.handlers.is_empty() && lt.else_start.is_none()
                            && target > pos && target > lt.handler_start
                            && !onto_loop_back_edge && !bare_chain
                            && !onto_loop_exit
                            && !crosses_branch_else
                        {
                            // end of the try body: forward jump over the
                            // handler chain into the else region. Handlers
                            // are parsed inline as execution continues; else
                            // statements are redirected into orelse by
                            // push_stmt until the region ends.
                            let stop = self.next_boundary(target, usize::MAX);
                            if let Some(l) = self.legacy_try.as_mut() {
                                l.else_start = Some(target);
                                l.else_stop = stop;
                            }
                        } else if !lt.handlers.is_empty()
                            && past_chain
                            && target < pos
                            && self.is_loop_top_target(target)
                            && lt
                                .pending_mismatch
                                .iter()
                                .any(|&m| {
                                    m > pos && self.pending_clause_head_at(m)
                                })
                        {
                            // a clause's normal exit fused with the
                            // enclosing loop's back edge (the try is
                            // the loop body's LAST statement: every
                            // clause's POP_EXCEPT exit is a JABS to
                            // the loop top). A pending clause head
                            // means the chain continues — this edge is
                            // clause-terminator glue, NOT a Continue
                            // statement: an explicit continue in an
                            // as-clause recompiles with CALL_FINALLY-
                            // style cleanup instead of the original's
                            // BEGIN_FINALLY fall-through (asyncore 3.8
                            // close_all clause 1). Consume it
                            let ie = inst.end();
                            if self.skip_until.map_or(true, |s| s < ie) {
                                self.skip_until = Some(ie);
                            }
                        } else if !lt.handlers.is_empty()
                            && (in_else
                                || (past_chain
                                    && target < pos
                                    // a handler body's loop back edge
                                    // arrives while clause heads are
                                    // still pending (its mismatch target
                                    // holds the next DUP_TOP+match head):
                                    // emitting here strands the remaining
                                    // clauses and tears down the enclosing
                                    // loop; the chain's own RERAISE stub
                                    // follows the LAST clause, so a real
                                    // chain end never has a pending head
                                    && !lt
                                    .pending_mismatch
                                    .iter()
                                    .any(|&m| m > pos && self.pending_clause_head_at(m))))
                            // a jump landing INSIDE the else region is not
                            // the region end. Backward: a nested loop's back
                            // edge (the region's own while/for continuing)
                            // (_sitebuiltins _Printer.__call__: the inner
                            // `while key is None` back edge at the else region
                            // fired the emit, scrambling try/else/loop order).
                            // Forward: an if/elif arm's merge jump to a
                            // shared trampoline still inside the region
                            // (asynchat 2.7 handle_read: the `if lb < n:`
                            // arm's JABS to the merge back edge fired the
                            // emit deep in the loop, stranding the Try
                            // inside that arm with the loop hoisted above
                            // it and the else body swallowed whole).
                            // Emitting here strands the rest of the else
                            // body either way. The genuine region end jumps
                            // OUT (target < else_start, e.g. the outer
                            // loop's back edge, or target >= else_stop).
                            && !lt
                                .else_start
                                .map_or(false, |es| {
                                    let lands_inside = target >= es
                                        && target < lt.else_stop
                                        && pos < lt.else_stop;
                                    if target < pos {
                                        // backward: a nested loop's back edge
                                        lands_inside
                                    } else {
                                        // forward: only a jump executed with
                                        // a loop open INSIDE the region is an
                                        // intra-loop merge; at depth 0 it is
                                        // the else arm's own end-of-arm jump
                                        // to the merge point (code 3.3
                                        // showsyntaxerror `JUMP_FORWARD 0`)
                                        lands_inside
                                            && self.blocks.iter().any(|b| {
                                                matches!(
                                                    b.kind,
                                                    BlockType::While | BlockType::For
                                                ) && b.start >= es
                                                    && b.start <= pos
                                            })
                                    }
                                })
                        {
                            // a fused arm-end edge INSIDE the live else
                            // region whose branch structure is still
                            // MID-PARSE (the innermost block is an If/Else
                            // whose region extends past this edge — the
                            // region's own if/else has an arm ending here
                            // and more region follows) must not emit: the
                            // Try would land in the region's inner If and
                            // be hoisted into its arm (ast 3.7 _format:
                            // the else region's then-arm end edge emitted
                            // early and the whole try nested under
                            // `if keywords:`). Defer to the region's own
                            // end edge. Edges under a LOOP top or a guard
                            // ending exactly here are genuine region ends
                            // (_sitebuiltins _Printer.__call__: the
                            // enclosing while-True back edge at 136, and
                            // the trailing `if key=='q': break` guard).
                            //
                            // narrowed: only the region's OWN branch
                            // structure counts — a block opened at or
                            // after the else start whose arm ends exactly
                            // at this edge (the walk continues into its
                            // else arm next). Branches straddling the
                            // region start (enclosing guards) and edges
                            // under loop tops keep the historic emit
                            // (code 3.3 interact, _osx_support 2.7/3.3,
                            // asynchat 3.9 regressed under the wide form)
                            let region_mid_parse = lt.else_start.map_or(
                                false,
                                |es| {
                                    self.blocks.last().map_or(false, |t| {
                                        matches!(
                                            t.kind,
                                            BlockType::If | BlockType::Else
                                        ) && t.start >= es
                                            && t.end > pos
                                            && (t.end == self.cur_next
                                                // the arm-end edge flies
                                                // straight to the region
                                                // If's own merge (py2.7
                                                // pads dead glue between
                                                // the arm end and the
                                                // region end: CGIHTTPServer
                                                // 2.7 run_cgi's else-region
                                                // guard `if len(...)==2:`
                                                // emitted the Try INSIDE
                                                // the guard at its arm-end
                                                // JABS)
                                                || inst.target == Some(t.end))
                                    })
                                },
                            );
                            // ...and the Try must actually LAND in the
                            // mid-parse branch: when an intermediate
                            // region block still separates the jump from
                            // that branch, the emission's container scan
                            // routes the Try correctly on its own —
                            // deferring would strand the chain with no
                            // later emit edge (asynchat 3.9
                            // initiate_send: the tail Try hoisted above
                            // the while loop and swallowed it into the
                            // orelse)
                            if in_else
                                && region_mid_parse
                                && self
                                    .blocks
                                    .last()
                                    .map_or(false, |t| {
                                        matches!(
                                            t.kind,
                                            BlockType::If | BlockType::Else
                                        ) && lt
                                            .else_start
                                            .map_or(false, |es| {
                                                t.start >= es
                                            })
                                    })
                            {
                                return;
                            }
                            // end of the else region (back edge or jump out):
                            // emit the complete try statement; flush first so
                            // else-region stores land in orelse, not after it
                            //
                            // close any else-region block still open at `pos`
                            // FIRST (e.g. a trailing `if key=='q': break`
                            // whose If block ends exactly here): its statement
                            // redirects into orelse and the innermost block
                            // becomes the try's real parent. legacy_chain_step
                            // runs before the main loop's close_blocks_at, so
                            // without this the Try is pushed into the still-open
                            // trailing If (_sitebuiltins _Printer.__call__).
                            //
                            // ...but an open If/Else ARM that ENCLOSES the
                            // whole chain (opened before the handler, its
                            // region covering the else start, ending at or
                            // before this boundary jump — the fused
                            // loop-tail shape) is the try's real parent:
                            // close_blocks_at would seal the arm BEFORE the
                            // Try exists and drop it beside the arm instead
                            // of into its orelse (csv 3.5/3.6 has_header:
                            // `else: try/except/else` flattened to loop
                            // level). Close only the blocks nested above
                            // the container and route the Try into its
                            // stmts; the container itself closes later
                            // with the Try inside.
                            // the container must be reachable from the
                            // stack top WITHOUT crossing a loop: a try
                            // inside a loop body belongs to the loop,
                            // not to some enclosing branch whose region
                            // happens to span the emit point
                            // (_osx_support 3.9 _get_arch_flags: the
                            // `while True: try/except-break` chain's
                            // emit routed the Try into the enclosing
                            // guard If, lifting it out of the loop)
                            let container_idx = {
                                let mut found = None;
                                for (bi, b) in self.blocks.iter().enumerate().rev() {
                                    if matches!(
                                        b.kind,
                                        BlockType::While | BlockType::For
                                    ) {
                                        found = None;
                                        break;
                                    }
                                    if matches!(
                                        b.kind,
                                        BlockType::If | BlockType::Else
                                    ) && b.start < lt.handler_start
                                        && b.end <= pos
                                        && lt.else_start.map_or(true, |es| {
                                            b.end >= es
                                        })
                                    {
                                        found = Some(bi);
                                        break;
                                    }
                                }
                                found
                            };
                            if let Some(ci) = container_idx {
                                while self.blocks.len() - 1 > ci {
                                    let e = self
                                        .blocks
                                        .last()
                                        .map(|b| b.end.min(pos))
                                        .unwrap_or(pos);
                                    self.force_close_top(e);
                                }
                                self.flush_pending_stores();
                                let l = self.legacy_try.take().unwrap();
                                self.restore_legacy_nest();
                                if let Some(lb) = self.blocks.get_mut(ci) {
                                    lb.stmts.push(Stmt::Try {
                                        body: l.body,
                                        handlers: l.handlers,
                                        orelse: l.orelse,
                                        finalbody: l.finalbody,
                                    });
                                }
                            } else {
                                self.close_blocks_at(pos);
                                self.flush_pending_stores();
                                let l = self.legacy_try.take().unwrap();
                                self.restore_legacy_nest();
                                self.push_legacy_try(l);
                            }
                        }
                    }
                }
            }
            _ => {}
        }
        // chain fully parsed and no else region followed: emit on the next
        // instruction so statement order stays correct
        if let Some(l) = &self.legacy_try {
            if l.chain_done
                && l.else_start.is_none()
                && !l.handlers.is_empty()
                && self.legacy_handler.is_none()
            {
                let l = self.legacy_try.take().unwrap();
                self.flush_pending_stores();
                self.restore_legacy_nest();
                // route past blocks whose region already ended: a
                // rotated-while's condition If stays open across the
                // iteration (its back edge folds it into the loop
                // condition) — pushing through it sinks the Try into
                // the cond block, which the back edge then flushes
                // into the last handler body (_collections_abc 3.5-3.7
                // index: the loop-tail `i += 1` landed inside
                // `except IndexError: break`)
                let try_stmt = Stmt::Try {
                    body: l.body,
                    handlers: l.handlers,
                    orelse: l.orelse,
                    finalbody: l.finalbody,
                };
                // push_stmt's handler redirects (an open handler, or
                // the STASHED outer handler of a nested-chain region)
                // own the routing whenever they are live — the nested
                // try belongs in the outer except body, not in the
                // region root (b05_exceptions t7/bare_raise: direct
                // block routing hoisted the inner try out of the
                // handler and left `pass` behind)
                let mut host = None;
                if self.legacy_handler.is_none()
                    && self.legacy_nest.is_empty()
                    && self.legacy_try.is_none()
                {
                    for bi in (0..self.blocks.len()).rev() {
                        if self.blocks[bi].end > self.cur_offset {
                            host = Some(bi);
                            break;
                        }
                    }
                }
                match host {
                    Some(bi) if bi + 1 < self.blocks.len() => {
                        // the stale blocks above the host must go now:
                        // left open they capture the post-chain
                        // statements and flush them into the handler
                        // body at the iteration back edge
                        while self.blocks.len() > bi + 1 {
                            let e = self
                                .blocks
                                .last()
                                .map(|b| b.end.min(self.cur_offset))
                                .unwrap_or(self.cur_offset);
                            self.force_close_top(e);
                        }
                        self.blocks[bi].stmts.push(try_stmt);
                    }
                    Some(bi) => self.blocks[bi].stmts.push(try_stmt),
                    None => self.push_stmt(try_stmt),
                }
            }
        }
        let _ = &lt;
    }

    /// Close every block whose `end == pos` (innermost first).
    /// While blocks created for 3.8+ loops have end == start (the cond jump
    /// offset) and must not auto-close there; they are closed by the back
    /// edge.
    fn close_blocks_at(&mut self, pos: usize) {
        // A zero-size rotated-While on top blocks position-based closing;
        // it is closed by its back edge instead.
        if let Some(top) = self.blocks.last() {
            if matches!(top.kind, BlockType::While) && top.start == top.end {
                return;
            }
            if top.kind == BlockType::Main {
                return;
            }
            if top.end > pos && self.overhang_clamp_end(pos).is_none() {
                return;
            }
        }
        // close every non-Main block whose region has ended (possibly
        // earlier than `pos` when control arrived here via a jump)
        while self.blocks.len() > 1 {
            let end = {
                let top = self.blocks.last().unwrap();
                if top.kind == BlockType::Main {
                    break;
                }
                if matches!(top.kind, BlockType::While) && top.start == top.end {
                    break;
                }
                if top.end > pos {
                    match self.overhang_clamp_end(pos) {
                        Some((e, clear_else)) => {
                            let last = self.blocks.last_mut().unwrap();
                            if clear_else {
                                last.else_end = None;
                            }
                            last.end = e;
                            e
                        }
                        None => break,
                    }
                } else {
                    top.end
                }
            };
            self.force_close_top(end);
        }
    }

    /// Overhang clamp: an inner BRANCH region whose recorded end
    /// OUTLIVES an enclosing branch that ended at/below the walk
    /// position overhangs its parent - its real extent was set from an
    /// arm exit flying to the outer merge (an elif-chain arm's
    /// JUMP_FORWARD past the chain), and it can never legitimately hold
    /// statements past the parent boundary. Returns the parent's end so
    /// the caller can fold the child there (_osx_support 3.12
    /// get_platform_osx: chain Elses ran to the function merge and
    /// trapped the parent's elif arms).
    ///
    /// Restrictions proven by regression:
    /// - LOOPS are never clamped: a loop's end is its own exit bound;
    ///   collapsing it mid-body tears the nest down (configparser 3.12
    ///   _read: the main For closed at an exception-table Try's end).
    /// - only a BRANCH (If/Else) ancestor is a container bound;
    ///   Try/With/Container carry infrastructure spans.
    /// - an ELSE top folds at any reached boundary (end <= pos): it
    ///   never opens an else of its own.
    /// - an IF top only folds for a STRICTLY-crossed ancestor (end <
    ///   pos) AND when its own end is a runaway guard target far past
    ///   the walk (>32 bytes) - the runaway swallowed the following
    ///   chain arms as nested content (_strptime 3.6-3.9: If[812,1364]
    ///   trapped the M arm; clamping at the crossed Else boundary puts
    ///   nd at 1). An If ending just past pos is mid-arm and must close
    ///   at its own end where its else arm opens (_markupbase 3.6
    ///   parse_declaration; equality-form folds skip that open), and
    ///   clamping it at a strictly-crossed ancestor yanks enclosing
    ///   arms down mid-flow (bdb 3.14 effective: `return b, True`
    ///   hoisted out of `if not b.cond:`).
    /// - ELSE-TRANSITION equality form: an If top opened INSIDE an
    ///   ancestor If's then arm folds at the ancestor's end when that
    ///   end == pos AND the ancestor's else region is pending
    ///   (else_end set): the then arm terminated on an unconditional
    ///   jump (which marked BOTH else_ends - it flies over the top's
    ///   end too), so the top's own end is only a fall-through merge
    ///   reachable through the ancestor's else arm. Left open, the top
    ///   blocks the ancestor's else transition and swallows the whole
    ///   else arm as nested then-content (_strptime 3.7-3.9 ampm
    ///   chain: `elif ampm == pm:` rendered inside `if hour == 12:`
    ///   merged as `and hour != 12`). The second tuple element says
    ///   the caller must CLEAR the top's else_end before folding: its
    ///   "else" is phantom (the false path merges into the ancestor's
    ///   else flow), and opening it would stall the cascade at an
    ///   empty Else whose region starts with the arm-tail continue.
    ///
    /// Returns (fold_end, clear_top_else_end).
    fn overhang_clamp_end(&self, pos: usize) -> Option<(usize, bool)> {
        let n = self.blocks.len();
        if n < 2 {
            return None;
        }
        let top = &self.blocks[n - 1];
        if matches!(top.kind, BlockType::Main | BlockType::While | BlockType::For)
        {
            return None;
        }
        if top.end <= pos {
            return None;
        }
        let is_else_top = top.kind == BlockType::Else;
        let top_runaway = top.end > pos + 32;
        let anc = self.blocks[..n - 1]
            .iter()
            .rev()
            .find(|b| {
                !matches!(b.kind, BlockType::Main) && b.end <= pos
            })
            .filter(|b| {
                matches!(b.kind, BlockType::If | BlockType::Else)
                    && (is_else_top
                        || (b.end < pos && top_runaway)
                        || (b.end == pos
                            && b.kind == BlockType::If
                            && b.else_end.is_some()
                            && top.kind == BlockType::If
                            && top.else_end.is_some()))
            })?;
        let e = anc.end;
        let clear_else = !is_else_top && e == pos && anc.else_end.is_some();
        if e > top.start {
            Some((e, clear_else))
        } else {
            None
        }
    }

    /// Close the topmost block, converting it to statement(s).
    /// py2: PRINT_ITEMs executed inside a closing branch arm's span
    /// belong to that arm's body — a running `print a,` chain crossing
    /// an if/else would otherwise flatten into ONE print after the
    /// block, losing the conditional items and rendering empty arms
    /// (2.7 aifc initfp EOFError handler: `if len(...)==1: print
    /// 'marker', else: print 'markers',` rendered both strings
    /// unconditionally with a `pass` guard hoisted above the prints)
    fn split_arm_prints(&mut self, b: &mut Block) {
        if self.version.major != 2 || self.pending_print.is_empty() {
            return;
        }
        let (Some(&si), Some(&ei)) = (self.idx_of.get(&b.start), self.idx_of.get(&b.end)) else {
            return;
        };
        if ei <= si {
            return;
        };
        let first = self.instrs[si].offset;
        let last = self.instrs[ei - 1].offset;
        let mut pre = Vec::new();
        let mut inside = Vec::new();
        let mut outside = Vec::new();
        for it in std::mem::take(&mut self.pending_print) {
            if it.0 < first {
                pre.push(it);
            } else if it.0 <= last {
                inside.push(it);
            } else {
                outside.push(it);
            }
        }
        self.pending_print = outside;
        // items printed BEFORE the arm opened are parent-scope
        // statements that must render ahead of the arm's If/else — flush
        // them while the parent is the top block (the caller pushes the
        // branch statement right after this close)
        if !pre.is_empty() {
            let stmt = Stmt::Print {
                dest: None,
                values: pre.into_iter().map(|(_, v)| v).collect(),
                newline: false,
            };
            self.push_stmt(stmt);
        }
        if !inside.is_empty() {
            b.stmts.push(Stmt::Print {
                dest: None,
                values: inside.into_iter().map(|(_, v)| v).collect(),
                newline: false,
            });
        }
    }

    /// 3.12+ inline with success-exit span: `LOAD None; LOAD None;
    /// LOAD None; CALL; POP_TOP` starting at `off` — returns the offset
    /// just past the POP_TOP. The callable is the VM-managed bound
    /// __exit__ (never modeled); the sequence is pure machinery.
    fn inline_with_exit_span(&self, off: usize) -> Option<usize> {
        let Some(&ci) = self.idx_of.get(&off) else {
            return None;
        };
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)
        };
        let mut k = ci;
        let mut nones = 0;
        while nones < 3 {
            let x = self.instrs.get(k)?;
            if is_pad(x) {
                k += 1;
                continue;
            }
            if x.op == Op::LOAD_CONST
                && matches!(
                    self.code.consts.get(x.arg as usize).map(|o| &**o),
                    Some(PyObject::None)
                )
            {
                nones += 1;
                k += 1;
                continue;
            }
            return None;
        }
        while matches!(self.instrs.get(k).map(|x| x.op), Some(op) if matches!(op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)) {
            k += 1;
        }
        // 3.11 inserts PRECALL before the exit CALL
        if self.instrs.get(k).map(|x| x.op) == Some(Op::PRECALL) {
            k += 1;
        }
        if self.instrs.get(k).map(|x| x.op) != Some(Op::CALL) {
            return None;
        }
        k += 1;
        while matches!(self.instrs.get(k).map(|x| x.op), Some(op) if matches!(op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)) {
            k += 1;
        }
        if self.instrs.get(k).map(|x| x.op) != Some(Op::POP_TOP) {
            return None;
        }
        Some(self.instrs[k].end())
    }

    /// 3.12+ `with` whose body contains a try: the exception table
    /// splits the with-protected range into same-handler fragments
    /// around the out-of-line chain(s) (codeop _maybe_compile:
    /// [180,248) + [346,348) + ... all -> the WITH_EXCEPT_START
    /// handler). The first fragment's end truncates the With block and
    /// ejects the try. When later same-handler fragments exist and the
    /// gap between them is entirely nested-try material (every inner
    /// entry targets the out-of-line handler zone [first chain head,
    /// with handler]), extend the end to the last fragment's end — the
    /// chain-head skipper handles the handler material inside.
    fn extend_with_frag_end(&self, frag_start: usize, end: usize) -> usize {
        let Some(handler) = self
            .exc_entries
            .iter()
            .find(|e| e.start == frag_start && e.end == end)
            .map(|e| e.target)
        else {
            return end;
        };
        let later_ends: Vec<usize> = self
            .exc_entries
            .iter()
            .filter(|e| {
                e.target == handler && e.start > end && e.end <= handler
            })
            .map(|e| e.end)
            .collect();
        let Some(span_end) = later_ends.into_iter().max() else {
            return end;
        };
        // cleanup-stub targets (RERAISE/COPY cascades) are not chain
        // heads: bound the zone by OFFSETS — [first PUSH_EXC_INFO past
        // the fragment end, handler]
        let zone_start = self.idx_of.get(&end).and_then(|&fi| {
            self.instrs[fi..]
                .iter()
                .find(|x| x.offset < handler && x.op == Op::PUSH_EXC_INFO)
                .map(|x| x.offset)
        });
        let chainy = zone_start.map_or(false, |zs| {
            self.exc_entries
                .iter()
                .filter(|e| {
                    e.start >= end && e.end <= span_end && e.target != handler
                })
                .all(|e| e.target >= zs && e.target <= handler)
        });
        if chainy && span_end > end {
            span_end
        } else {
            end
        }
    }

    /// Close the open With block(s) down through the innermost one —
    /// the inline success exit IS the with's end; statements after it
    /// (the post-with function tail) belong outside
    fn close_with_blocks(&mut self, pos: usize) {
        let Some(i) = self
            .blocks
            .iter()
            .rposition(|b| matches!(b.kind, BlockType::With))
        else {
            return;
        };
        while self.blocks.len() > i {
            let p = self
                .blocks
                .last()
                .map(|b| {
                    if b.end == usize::MAX || b.end > pos {
                        pos
                    } else {
                        b.end
                    }
                })
                .unwrap_or(pos);
            self.force_close_top(p);
        }
    }

    /// force_close_top with legacy-region cascade: when the closed
    /// block's statement was ROUTED into a legacy chain's inline-finally
    /// region (push_stmt redirect) instead of landing in the parent, an
    /// if-arm chain over that region would close empty level by level
    /// (`if A: pass` / `if B: pass` shells — cmd 3.10 cmdloop). Keep
    /// closing empty If/Else parents whose region also ended at `pos`.
    fn force_close_top_cascade(&mut self, pos: usize) {
        loop {
            let (parent_stmts, parent_is_arm, parent_end) = match self.blocks.last() {
                Some(b) => (
                    b.stmts.len(),
                    matches!(b.kind, BlockType::If | BlockType::Else),
                    b.end,
                ),
                None => return,
            };
            self.force_close_top(pos);
            let routed_away = self
                .blocks
                .last()
                .map_or(false, |b| b.stmts.len() == parent_stmts);
            if !routed_away || !parent_is_arm || parent_end > pos {
                return;
            }
            if !self.blocks.last().map_or(false, |b| {
                matches!(b.kind, BlockType::If | BlockType::Else) && b.end <= pos
            }) {
                return;
            }
        }
    }

    fn force_close_top(&mut self, pos: usize) {

        // stores that happened inside this block must land in it, not in
        // whatever block is open after closing
        self.flush_pending_stores();
        let mut b = self.blocks.pop().unwrap();
        match b.kind {
            BlockType::Main => {
                self.blocks.push(b);
            }
            BlockType::If => {
                let cond = b.cond.take().unwrap_or_else(|| self.name_expr("???"));
                // JUMP_IF_*_OR_POP short-circuit regions merge here into a
                // BoolOp expression instead of an if statement
                if let Some(or_form) = b.short_circuit {
                    if b.stmts.is_empty() {
                        if let Some(Sv::E(right)) = self.stack.last() {
                            let right = right.clone();
                            self.stack.pop();
                            // chained comparison (`a < b < c` via JFOP)
                            if let Some(merged) = merge_chain_compare(&cond, &right) {
                                self.push(merged);
                                if let Some(skip) = b.else_end {
                                                                        self.skip_until = Some(skip);
                                }
                                return;
                            }
                            let kind = if or_form {
                                BoolOpKind::Or
                            } else {
                                BoolOpKind::And
                            };
                            let mut values = Vec::new();
                            flatten_boolop(cond, kind, &mut values);
                            flatten_boolop(right, kind, &mut values);
                            self.push(Rc::new(Expr::BoolOp { op: kind, values }));
                            return;
                        }
                    }
                }
                self.split_arm_prints(&mut b);
                let body = std::mem::take(&mut b.stmts);
                // an if-arm EMPTIED by the legacy finally-region
                // redirect: its content was routed into the chain's
                // finalbody when it flushed (push_legacy_try) — closing
                // the shell here renders `if cond: pass` beside the
                // flushed Try (cmd 3.10 cmdloop `finally: {if A: if B:
                // try/except}`). A genuine `if cond: pass` has no
                // bytecode branch at all, so an empty arm inside a live
                // copy region is always a routed shell — drop it.
                if body.is_empty() && b.else_end.is_none() {
                    let routed_shell =
                        self.legacy_try.as_ref().map_or(false, |l| {
                            l.has_finally
                                && !l.finalbody.is_empty()
                                && l.else_start.map_or(false, |es| {
                                    b.start >= es && b.end <= l.handler_start
                                })
                        });
                    if routed_shell {
                        return;
                    }
                }
                // 3.14 `if c: break` shape: PJIT over a break block with a
                // continue on the fall-through — normalize back
                if body.len() == 1 && matches!(body[0], Stmt::Continue) {
                    if let Expr::Unary {
                        op: UnaryOp::Not,
                        operand,
                    } = &*cond
                    {
                        if let Some(&ti0) = self.idx_of.get(&pos) {
                            // the break block may start with the POP_TOP
                            // that drops the loop iterator (3.12 `if c:
                            // break` inside a for)
                            let mut ti = ti0;
                            while matches!(
                                self.instrs.get(ti).map(|x| x.op),
                                Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
                            ) {
                                ti += 1;
                            }
                            let ins = self.instrs[ti];
                            if matches!(
                                ins.op,
                                Op::JUMP | Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE
                            ) {
                                if let Some(t) = ins.target {
                                    if self.find_loop_exit(t).is_some() {
                                        let c = operand.clone();
                                        self.push_stmt(Stmt::If {
                                            cond: c,
                                            body: vec![Stmt::Break],
                                            orelse: Vec::new(),
                                        });
                                                                                self.skip_until = Some(ins.end());
                                        return;
                                    }
                                }
                            }
                        }
                    }
                }
                // 3.10 sunk-copy else rebuild: the then arm's else-skip
                // jump was replaced by a sunk `LOAD v; RETURN` (suppressed
                // and recorded) — the region from this If's end to the
                // function's final return run is the else arm
                if b.else_end.is_none()
                    && !body.is_empty()
                    && self
                        .sunk_return_fold_at
                        .map_or(false, |fo| fo > b.start && fo < pos)
                {
                    self.sunk_return_fold_at = None;
                    let n = self.instrs.len();
                    let final_ret = (n >= 2)
                        .then(|| self.instrs[n - 1].offset)
                        .filter(|_| {
                            matches!(
                                self.instrs[n - 1].op,
                                Op::RETURN_VALUE | Op::RETURN_CONST
                            )
                        });
                    if let Some(fr) = final_ret {
                        if fr > pos {
                            // find the start of the final return's value
                            // run — the else arm ends there
                            let is_pad = |x: &crate::bytecode::Instruction| {
                                matches!(
                                    x.op,
                                    Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                        | Op::EXTENDED_ARG
                                )
                            };
                            let mut fb = n - 1;
                            let mut fhops = 0;
                            while fb > 0 && fhops < 8 {
                                let p = &self.instrs[fb - 1];
                                if is_pad(p)
                                    || matches!(
                                        p.op,
                                        Op::LOAD_FAST
                                            | Op::LOAD_NAME
                                            | Op::LOAD_GLOBAL
                                            | Op::LOAD_DEREF
                                            | Op::LOAD_CONST
                                            | Op::LOAD_ATTR
                                            | Op::LOAD_METHOD
                                    )
                                {
                                    fb -= 1;
                                    fhops += 1;
                                    continue;
                                }
                                break;
                            }
                            let else_stop = self.instrs[fb].offset;
                            if else_stop > pos {
                                let mut else_blk =
                                    Block::new(BlockType::Else, pos, else_stop);
                                else_blk.cond = Some(cond.clone());
                                self.pending_then.push(body);
                                self.blocks.push(else_blk);
                                return;
                            }
                        }
                    }
                }
                if b.else_end.is_none()
                    && body.is_empty()
                    && b.value_merge.is_some()
                    && !self.stack.is_empty()
                {
                    let kind = b.value_merge.unwrap();
                    // value-flow merge: `a and b` / `a or b` chains
                    let right = self.pop_expr();
                    // restore the tested value's polarity (the block cond was
                    // negated for jump-if-true fall-through modeling) — the
                    // 3.12+ COPY-idiom merge blocks store the operand
                    // POSITIVE: a simplify_not here would leave a folded
                    // compare flip unrecovered (calendar 3.13 isleap
                    // `year % 100 != 0 or ...` rendered `== 0`)
                    let cond = if b.jump_if_true && !b.merge_pos {
                        simplify_not(cond)
                    } else {
                        cond
                    };
                    if let Some(merged) = merge_chain_compare(&cond, &right) {
                        self.push(merged);
                        return;
                    }
                    let mut values = Vec::new();
                    flatten_boolop(cond, kind, &mut values);
                    flatten_boolop(right, kind, &mut values);
                    self.push(Rc::new(Expr::BoolOp { op: kind, values }));
                    return;
                }
                // function-tail if/else whose arms all return: the
                // compiler omits the else jump when the then arm
                // terminates, so no Else region was built — but the
                // implicit tail `LOAD None; RETURN` pair (tail_pair_at)
                // proves the source nested an else. Without rebuilding
                // it here the else arm flattens to sibling statements
                // whose recompile drops the pair (DCE after the arm's
                // return) and the sig loses its last two lines
                // (_dummy_thread 3.3 acquire). The else arm runs to the
                // pair; a jump targeting INSIDE the span means this if's
                // false path resumes mid-function (a plain guard) — no
                // rebuild then.
                if b.else_end.is_none()
                    && !body.is_empty()
                    // the then arm must TERMINATE (that is why the else
                    // jump was omitted); a non-terminal arm means this is
                    // a plain guard whose flow merges before the pair
                    // (`if timeout > 0: sleep` then `return False`,
                    // _dummy_thread innermost if)
                    && matches!(
                        body.last(),
                        Some(Stmt::Return(_)) | Some(Stmt::Raise { .. })
                    )
                {
                    if let Some(pair_at) = self.tail_pair_at {
                        // an unconditional forward jump inside the
                        // span landing exactly on the tail pair is the
                        // else arm's terminating glue: proof of the
                        // nested if/else shape. With it, an outside
                        // COND jump landing inside the span is just an
                        // enclosing guard's escape into its own else
                        // arm (cgi 3.5 getvalue: outer `if key in
                        // self` PJIF flies over the inner else to
                        // `return default`) — only unconditional hops
                        // still veto (the bz2 merge-point shape).
                        let terminator_to_pair = self.instrs.iter().any(|x| {
                            x.offset >= pos
                                && x.offset < pair_at
                                && !x.is_backward
                                && matches!(
                                    x.op,
                                    Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                                )
                                && x.target == Some(pair_at)
                        });
                        if pos < pair_at
                            && !self.instrs.iter().any(|x| {
                                // an OUTSIDE jump landing inside the span
                                // means the flow resumes mid-function —
                                // internal arm jumps are fine
                                x.offset < pos
                                    && x.target
                                        .map_or(false, |t| t > pos && t < pair_at)
                                    && !(terminator_to_pair
                                        && matches!(
                                            x.op,
                                            Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                                | Op::POP_JUMP_BACKWARD_IF_FALSE
                                                | Op::POP_JUMP_BACKWARD_IF_TRUE
                                                | Op::JUMP_IF_FALSE_OR_POP
                                                | Op::JUMP_IF_TRUE_OR_POP
                                                | Op::JUMP_IF_FALSE
                                                | Op::JUMP_IF_TRUE
                                        ))
                            })
                            // an unconditional forward hop landing EXACTLY
                            // on pos makes pos a merge point of two arms
                            // (an enclosing then arm hops over the else to
                            // the same label this guard's PJIF targets):
                            // [pos, pair_at) is then post-merge mainline
                            // flow, NOT this guard's else arm. Rebuilding
                            // traps the whole function tail inside the
                            // guard's else (bz2 3.5-3.7 open(): bz_mode/
                            // binary_file/returns landed in the newline
                            // guard's else, dead in text mode).
                            && !self.instrs.iter().any(|x| {
                                x.offset < pos
                                    && !x.is_backward
                                    && matches!(
                                        x.op,
                                        Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                                    )
                                    && x.target == Some(pos)
                            })
                            // the span must not cross a try structure: a
                            // function ending in try/except(/else) also
                            // grows the implicit tail pair, but the pair
                            // then belongs to the TRY — rebuilding a flat
                            // guard before it wraps the whole try and
                            // scrambles the emission order (cmd 3.6
                            // onecmd). SETUP_EXCEPT/SETUP_FINALLY mark
                            // legacy (<=3.10) try starts inside the span;
                            // PUSH_EXC_INFO marks 3.11+ chains (always
                            // laid out past the inline flow). A clean
                            // span is pure if/else material.
                            && !self.instrs.iter().any(|x| {
                                x.offset >= pos
                                    && x.offset < pair_at
                                    && matches!(
                                        x.op,
                                        Op::PUSH_EXC_INFO
                                            | Op::SETUP_EXCEPT
                                            | Op::SETUP_FINALLY
                                    )
                            })
                            // the span must also be free of loops and
                            // mid-flow raises: a guard whose then arm
                            // terminates with a RAISE followed by the
                            // function's whole mainline (loop + more
                            // raises + returns) is the flat
                            // `if c: raise X` + continuation shape —
                            // rebuilding the else there renders a
                            // spurious `else:` whose recompile adds an
                            // else-skip JF (cgi 3.5 __getitem__: the
                            // TypeError guard swallowed the item loop).
                            // The genuine all-arms-return tail if/else
                            // this rebuild serves is a small pair of
                            // straight-line return arms (_dummy_thread
                            // 3.3 acquire: if/sleep/return vs return).
                            && !(matches!(body.last(), Some(Stmt::Raise { .. }))
                                && self.instrs.iter().any(|x| {
                                    x.offset >= pos
                                        && x.offset < pair_at
                                        && matches!(
                                            x.op,
                                            Op::SETUP_LOOP
                                                | Op::FOR_ITER
                                                | Op::GET_ITER
                                                | Op::GET_AITER
                                                | Op::GET_ANEXT
                                                | Op::END_FOR
                                                | Op::RAISE_VARARGS
                                        )
                                }))
                            // a Raise-then arm whose guard is a mid-
                            // function check (the span still contains a
                            // conditional jump — more guard structure
                            // follows) is the flat `if bad: raise` +
                            // mainline shape; the rebuild only serves
                            // function-tail guards whose span is the
                            // final straight-line return arm
                            // (_dummy_thread 3.3 acquire's PJIF-to-pair
                            // tail has no cond jump left in the span;
                            // cgi 3.5 __getitem__'s `if not found: raise
                            // KeyError` span holds the len==1 check) —
                            // UNLESS the arm's own terminating jump
                            // lands exactly on the tail pair: the
                            // compiler only emits that glue for a
                            // nested if/ELSE whose arms both terminate
                            // (the flat guard-raise shape has no jump
                            // at all after the raise), so the else is
                            // real and its flattened recompile drops
                            // the arm-end JF (cgi 3.5 getvalue/
                            // getfirst/getlist `else: return
                            // value.value`)
                            && !(matches!(body.last(), Some(Stmt::Raise { .. }))
                                && self.instrs.iter().any(|x| {
                                    x.offset >= pos
                                        && x.offset < pair_at
                                        && matches!(
                                            x.op,
                                            Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                                | Op::POP_JUMP_BACKWARD_IF_FALSE
                                                | Op::POP_JUMP_BACKWARD_IF_TRUE
                                                | Op::JUMP_IF_FALSE_OR_POP
                                                | Op::JUMP_IF_TRUE_OR_POP
                                                | Op::JUMP_IF_FALSE
                                                | Op::JUMP_IF_TRUE
                                        )
                                })
                                && !self.instrs.iter().any(|x| {
                                    x.offset >= pos
                                        && x.offset < pair_at
                                        && !x.is_backward
                                        && matches!(
                                            x.op,
                                            Op::JUMP_FORWARD
                                                | Op::JUMP
                                                | Op::JUMP_ABSOLUTE
                                        )
                                        && x.target == Some(pair_at)
                                }))
                        {
                            // the else arm's real extent: when an
                            // unconditional forward jump inside the
                            // span lands exactly on the tail pair, it
                            // is the arm's terminating glue — the arm
                            // ends there and the code between it and
                            // the pair is an ENCLOSING branch's else
                            // arm (cgi 3.5 getvalue: `else: return
                            // value.value` + JF-to-pair, then the
                            // outer guard's `return default`). Running
                            // the Else to the pair would swallow it.
                            let mut real_end = pair_at;
                            for x in self.instrs.iter() {
                                if x.offset < pos {
                                    continue;
                                }
                                if x.offset >= pair_at {
                                    break;
                                }
                                if !x.is_backward
                                    && matches!(
                                        x.op,
                                        Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                                    )
                                    && x.target == Some(pair_at)
                                {
                                    real_end = x.end();
                                    break;
                                }
                            }
                            let mut else_blk =
                                Block::new(BlockType::Else, pos, real_end);
                            else_blk.cond = Some(cond);
                            self.pending_then.push(body);
                            self.blocks.push(else_blk);
                            return;
                        }
                    }
                }
                // pre-3.11 `try: if c: <terminating arms> else:
                // return v` — the LAST statement of a legacy try body:
                // both arms return, so the compiler omitted the else
                // jump AND the assembler could not DCE the body-exit
                // `POP_BLOCK; JUMP_FORWARD` (the explicit-else CFG keeps
                // the merge block alive via the then arm's exit edge).
                // The flat rendering recompiles WITHOUT that pair
                // (unreachable after the flat return) and the sig loses
                // two instructions (compileall 3.7 main: `else: return
                // compile_path(...)` flattened). Rebuild the Else region
                // [pos, POP_BLOCK) when the continuation is a single
                // straight-line return arm ending exactly at the open
                // Try block's closing POP_BLOCK.
                if !self.version.at_least(3, 11)
                    && b.else_end.is_none()
                    && matches!(body.last(), Some(Stmt::Return(Some(_))))
                {
                    if let Some(try_pos) = self
                        .blocks
                        .iter()
                        .rev()
                        .find(|bl| bl.kind == BlockType::Try)
                        .map(|bl| bl.start)
                    {
                        // the else arm is a straight-line value-run
                        // ending in RETURN, optionally preceded by its
                        // own POP_BLOCK (asyncore 3.8 recv:
                        // `else: return data` compiles LOAD; POP_BLOCK;
                        // RETURN — the FIRST POP_BLOCK from pos is the
                        // arm's own, not the body-exit one; the exit
                        // pair is the POP_BLOCK followed by a forward
                        // JUMP)
                        let pop_at = self
                            .idx_of
                            .get(&pos)
                            .and_then(|&pi| {
                                self.instrs[pi..]
                                    .iter()
                                    // the EXIT pair: a POP_BLOCK
                                    // followed by a forward jump — an
                                    // arm-internal POP_BLOCK (before
                                    // its RETURN) is skipped
                                    .find(|pb| {
                                        if pb.op != Op::POP_BLOCK {
                                            return false;
                                        }
                                        self.idx_of
                                            .get(&pb.offset)
                                            .and_then(|&pj| {
                                                self.instrs.get(pj + 1)
                                            })
                                            .map_or(false, |nx| {
                                                matches!(
                                                    nx.op,
                                                    Op::JUMP_FORWARD
                                                        | Op::JUMP
                                                        | Op::DUP_TOP
                                                ) && nx
                                                    .target
                                                    .map_or(true, |t| {
                                                        t > pb.offset
                                                    })
                                            })
                                    })
                                    .map(|pb| pb.offset)
                            });
                        let ok = pop_at.map_or(false, |p| {
                            p > pos
                                // the arm [pos, p) must be a pure value
                                // run ending in RETURN (its optional
                                // POP_BLOCK precedes p and is the arm's
                                // own block pop)
                                && self
                                    .idx_of
                                    .get(&pos)
                                    .map_or(false, |&si| {
                                        let mut saw_ret = false;
                                        self.instrs[si..]
                                            .iter()
                                            .take_while(|x| x.offset < p)
                                            .all(|x| {
                                                if matches!(
                                                    x.op,
                                                    Op::RETURN_VALUE
                                                        | Op::RETURN_CONST
                                                ) {
                                                    saw_ret = true;
                                                    true
                                                } else if x.op == Op::POP_BLOCK {
                                                    !saw_ret
                                                } else {
                                                    !saw_ret
                                                        && is_pure_value_op(
                                                            x.op,
                                                        )
                                                }
                                            })
                                            && saw_ret
                                    })
                                && self.idx_of.get(&p).map_or(false, |&pj| {
                                    self.instrs.get(pj + 1).map_or(false, |nx| {
                                        matches!(
                                            nx.op,
                                            Op::JUMP_FORWARD | Op::JUMP | Op::DUP_TOP
                                        ) && nx.target.map_or(true, |t| t > p)
                                    })
                                })
                                && self.instrs.iter().all(|x| {
                                    x.offset < pos
                                        || x.offset >= p
                                        || x.target.map_or(true, |t| {
                                            t <= pos || t >= p
                                        })
                                })
                                && self.blocks.iter().any(|bl| {
                                    bl.kind == BlockType::Try
                                        && bl.start == try_pos
                                        && bl.end > p
                                })
                        });
                        if ok {
                            let p = pop_at.unwrap();
                            let mut else_blk =
                                Block::new(BlockType::Else, pos, p);
                            else_blk.cond = Some(cond.clone());
                            self.pending_then.push(body);
                            self.blocks.push(else_blk);
                            return;
                        }
                    }
                }
                if let Some(else_end) = b.else_end {
                    // value-merge block (COPY+cond jump) with a forward jump:
                    // both branches produce values — merge into chain compare
                    // or ternary and skip the false-path instructions
                    if let Some(_kind) = b.value_merge {
                        if !body.is_empty() {
                            // py2 if/else STATEMENT compiled value-preserving:
                            // body holds the then statements; open the Else
                            // region and let execution collect the else body
                            let is_elif = self.starts_with_cond_jump(pos, else_end);
                            let real_end = if is_elif {
                                else_end
                            } else {
                                self.next_boundary(pos, else_end)
                            };
                            let mut else_blk = Block::new(BlockType::Else, pos, real_end);
                            else_blk.cond = Some(cond);
                            else_blk.is_elif = is_elif;
                            self.pending_then.push(body);
                            self.blocks.push(else_blk);
                            return;
                        }
                        if body.is_empty() {
                            if let Some(Sv::E(v)) = self.stack.last() {
                                let v = v.clone();
                                if let Some(merged) = merge_chain_compare(&cond, &v) {
                                    self.stack.pop();
                                    self.push(merged);
                                    self.skip_chain_else_arm(else_end);
                                    return;
                                }
                                // A ternary needs the tested value still on
                                // the stack right under the arm value (the
                                // py2 peek-style JUMP_IF_* if-shape and the
                                // 3.12+ COPY both retain it). When the arm's
                                // POP_TOP already dropped the tested value
                                // (py2 / PJFP-style short circuit), a single
                                // arm value is `a and b` / `a or b`.
                                let tested_retained = self
                                    .stack
                                    .get(self.stack.len().wrapping_sub(2))
                                    .map_or(false, |sv| {
                                        matches!(sv, Sv::E(e) if expr_eq(e, &cond))
                                    });
                                if self.stack.len() >= 2 && tested_retained {
                                    self.stack.pop();
                                    let then_val = self.pop_expr();
                                    self.push(Rc::new(Expr::Ternary {
                                        cond,
                                        then_expr: then_val,
                                        else_expr: v,
                                    }));
                                    self.skip_chain_else_arm(else_end);
                                    return;
                                }
                                // py2 short-circuit `a and b` / `a or b`:
                                // the cond was popped by the branch POP_TOP
                                // and the fall-through produced one value
                                let kind = b.value_merge.unwrap();
                                let cond = if b.jump_if_true && !b.merge_pos {
                                    simplify_not(cond)
                                } else {
                                    cond
                                };
                                self.stack.pop();
                                let mut values = Vec::new();
                                flatten_boolop(cond, kind, &mut values);
                                flatten_boolop(v, kind, &mut values);
                                self.push(Rc::new(Expr::BoolOp { op: kind, values }));
                                self.skip_chain_else_arm(else_end);
                                return;
                            }
                        }
                    }
                    let is_elif = self.starts_with_cond_jump(pos, else_end);
                    let real_end = if is_elif {
                        self.clamp_elif_real_end(pos, else_end)
                    } else {
                        self.next_boundary(pos, else_end)
                    };
                    let real_end = self.cap_else_at_loop(pos, real_end);
                    let mut else_blk = Block::new(BlockType::Else, pos, real_end);
                    else_blk.cond = Some(cond);
                    else_blk.is_elif = is_elif;
                    self.pending_then.push(body);
                    self.blocks.push(else_blk);
                } else if b.folded_exit {
                    // folded chain exit: an elif/else region starts right
                    // here and runs until the next folded exit (or the
                    // enclosing structure closes it)
                    let mut else_blk = Block::new(
                        BlockType::Else,
                        pos,
                        self.cap_else_at_loop(pos, usize::MAX),
                    );
                    else_blk.cond = Some(cond);
                    else_blk.folded_exit = true;
                    self.pending_then.push(body);
                    self.blocks.push(else_blk);
                } else if b.else_end.is_none()
                    && b.end > pos
                    && self.version.at_least(3, 11)
                    && self
                        .idx_of
                        .get(&b.end)
                        .copied()
                        .map_or(false, |ti| {
                            // 3.11+ out-of-line handler: the else arm's
                            // bare `raise` is relocated PAST the
                            // handler's normal-exit resume stub (codecs
                            // 3.13 read: PJIF(firstline) targets a bare
                            // RAISE_VARARGS after the JBNI resume) — the
                            // linear body region cannot include it, so
                            // attach it here when the guard's target is
                            // exactly that raise and only exception-path
                            // cleanup follows it
                            self.instrs[ti].op == Op::RAISE_VARARGS
                                && self.instrs[ti].arg == 0
                                && self.instrs[ti + 1..].iter().all(|x| {
                                    matches!(
                                        x.op,
                                        Op::LOAD_CONST
                                            | Op::STORE_FAST
                                            | Op::STORE_NAME
                                            | Op::STORE_DEREF
                                            | Op::DELETE_FAST
                                            | Op::DELETE_NAME
                                            | Op::DELETE_DEREF
                                            | Op::RERAISE
                                            | Op::COPY
                                            | Op::SWAP
                                            | Op::POP_EXCEPT
                                            | Op::POP_TOP
                                            | Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::CACHE
                                            | Op::RAISE_VARARGS
                                    )
                                })
                        })
                {
                    self.push_stmt(Stmt::If {
                        cond,
                        body,
                        orelse: vec![Stmt::Raise {
                            exc: None,
                            cause: None,
                            py2_inst: None,
                            py2_tb: None,
                        }],
                    });
                } else if self.stmt_escapes_else_region(b.start) {
                    // this block ENCLOSES the active chain's else
                    // region and the chain never flushed (an
                    // unbounded else_stop — the region merges by
                    // fall-through, no bounding jump ever ran):
                    // flush it INTO this block's body now, or the
                    // walk-end teardown lands the Try as a sibling
                    // AFTER the guard (_osx_support 3.10
                    // _get_system_version)
                    let mut body = body;
                    if self.legacy_handler.is_none()
                        && self.legacy_try.as_ref().map_or(false, |l| {
                            l.chain_done
                                && !l.handlers.is_empty()
                                && !l.has_finally
                                && l.else_start.map_or(false, |es| {
                                    es > b.start
                                })
                        })
                    {
                        let l = self.legacy_try.take().unwrap();
                        self.flush_pending_stores();
                        self.restore_legacy_nest();
                        body.push(Stmt::Try {
                            body: l.body,
                            handlers: l.handlers,
                            orelse: l.orelse,
                            finalbody: l.finalbody,
                        });
                    }
                    if let Some(top) = self.blocks.last_mut() {
                        top.stmts.push(Stmt::If {
                            cond,
                            body,
                            orelse: Vec::new(),
                        });
                    } else {
                        self.push_stmt(Stmt::If {
                            cond,
                            body,
                            orelse: Vec::new(),
                        });
                    }
                } else {
                    self.push_stmt(Stmt::If {
                        cond,
                        body,
                        orelse: Vec::new(),
                    });
                }
            }
            BlockType::Else => {
                self.split_arm_prints(&mut b);
                let cond = b.cond.take().unwrap_or_else(|| self.name_expr("???"));
                let mut orelse = std::mem::take(&mut b.stmts);
                // skipped else-arm break: the arm's single instruction is
                // a forward jump onto the enclosing loop's exit and the
                // walk's skip hopped over it (the then arm's try-success
                // JF set else_end past an out-of-line handler chain —
                // configparser 3.11 before_get `if value and '%(' in
                // value: <try> else: break` lost the break, running the
                // loop tail for empty values)
                if orelse.is_empty() {
                    if let Some(&si) = self.idx_of.get(&b.start) {
                        let sins = &self.instrs[si];
                        if !sins.is_backward
                            && matches!(
                                sins.op,
                                Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                            )
                            && sins.target.map_or(false, |t| {
                                t > sins.offset && self.find_loop_exit(t).is_some()
                            })
                            && self
                                .blocks
                                .iter()
                                .any(|bl| {
                                    matches!(
                                        bl.kind,
                                        BlockType::While | BlockType::For
                                    )
                                })
                        {
                            orelse.push(Stmt::Break);
                        }
                    }
                }
                let body = self.pending_then.pop().unwrap_or_default();
                if body.is_empty() && orelse.is_empty() {
                    // chained comparison merge: one value on the stack that
                    // shares an operand with the condition (`a < b < c`)
                    if let Some(Sv::E(v)) = self.stack.last() {
                        let v = v.clone();
                        if let Some(merged) = merge_chain_compare(&cond, &v) {
                            self.stack.pop();
                            self.push(merged);
                            return;
                        }
                    }
                    // conditional expression: both branches are pure values
                    if self.stack.len() >= 2 {
                        let else_val = self.pop_expr();
                        let then_val = self.pop_expr();
                        self.push(Rc::new(Expr::Ternary {
                            cond,
                            then_expr: then_val,
                            else_expr: else_val,
                        }));
                        return;
                    }
                }
                if b.folded_exit && body.is_empty() && orelse.len() == 1 {
                    if let Stmt::If { cond: c2, body: t2, orelse: e2 } = orelse.pop().unwrap() {
                        // folded elif link: the region held the next chain
                        // link — re-arm so a following final-else region
                        // receives the whole accumulated chain
                        self.pending_then.push(t2);
                        let mut next_else = Block::new(
                            BlockType::Else,
                            pos,
                            self.cap_else_at_loop(pos, usize::MAX),
                        );
                        next_else.cond = Some(c2);
                        next_else.folded_exit = true;
                        next_else.is_elif = true;
                        // e2 (any deeper chain) is preserved by pushing it
                        // into the new block when non-empty
                        next_else.stmts = e2;
                        self.blocks.push(next_else);
                        let _ = cond;
                        return;
                    }
                }
                // Nesting the else body preserves full fidelity; the
                // codegen renders `else: <single if>` as `elif` anyway
                // (which also covers folded elif chains).
                self.push_stmt(Stmt::If { cond, body, orelse });
            }
            BlockType::While => {
                let cond = b.cond.take().unwrap_or_else(|| self.true_cond_expr());
                let body = std::mem::take(&mut b.stmts);
                // 3.8+ rotated while-else: the exhaustion exit (b.end)
                // closed the body; the else region runs to loop_else_end
                // the close may come from the back edge (cur_next == the
                // exhaustion point) one instruction before b.end — probe
                // there too so else regions still attach
                let probe_at = if pos == b.end {
                    Some(pos)
                } else if self.cur_next <= b.end && b.end - self.cur_next <= 4 {
                    // the back edge sits right before the exhaustion
                    // point (small padding gap)
                    Some(b.end)
                } else {
                    None
                };
                let probed = if b.loop_else_end.is_none() {
                    probe_at.and_then(|p| self.probe_for_else(p))
                } else {
                    None
                };
                if let Some(else_end) = b.loop_else_end.or(probed) {
                    let start = if pos == b.end { pos } else { b.end };
                    self.pending_loop.push((Some(cond), None, None, body, false));
                    let else_blk = Block::new(BlockType::WhileElse, start, else_end);
                    self.blocks.push(else_blk);
                } else {
                    self.push_stmt(Stmt::While {
                        cond,
                        body,
                        orelse: Vec::new(),
                    });
                }
            }
            BlockType::For => {
                let target = b.target.take().unwrap_or_else(|| self.name_expr("_"));
                let iter = b.iter.take().unwrap_or_else(|| self.name_expr("???"));
                let body = std::mem::take(&mut b.stmts);
                let is_async = b.is_async;
                // a loop kept open for a legacy chain had its end
                // stretched to usize::MAX (pending_loop_close_at_chain):
                // recover the physical exhaustion exit from the FOR_ITER
                // so the SETUP_LOOP-era for-else check still sees the
                // real layout (csv 3.5/3.6 has_header: `for thisType in
                // [int, float, complex]: try/except else: thisType =
                // len(row[col])` — for_setup_end compared against the
                // stretched end found no else region and the arm
                // flattened to the enclosing loop level)
                let raw_eff = if b.end == usize::MAX {
                    self.idx_of
                        .get(&b.start)
                        .and_then(|&i| self.instrs.get(i))
                        .filter(|x| matches!(x.op, Op::FOR_ITER))
                        .and_then(|x| x.target)
                        .unwrap_or(b.end)
                } else {
                    b.end
                };
                // the exhaustion exit is the loop's POP_BLOCK: the else
                // body starts AFTER it — a region including the
                // POP_BLOCK is sealed by the POP_BLOCK handler before
                // any else statement is walked (csv 3.6 has_header:
                // `else: continue` from the dead handler-hop, else body
                // stranded at the enclosing loop level)
                let eff_end = self
                    .idx_of
                    .get(&raw_eff)
                    .and_then(|&pi| self.instrs.get(pi))
                    .filter(|x| matches!(x.op, Op::POP_BLOCK))
                    .map(|x| x.end())
                    .unwrap_or(raw_eff);
                let probe_at = if pos == b.end {
                    Some(pos)
                } else if self.cur_next <= b.end && b.end - self.cur_next <= 4 {
                    // closed via the back edge right before the exhaustion
                    // point — the else region (if any) still follows
                    Some(b.end)
                } else {
                    None
                };
                let probed_else = if b.loop_else_end.is_none()
                    && b.for_setup_end.is_none()
                {
                    probe_at.and_then(|p| self.probe_for_else(p))
                } else {
                    None
                };
                if let Some(else_end) = b.loop_else_end.or(probed_else) {
                    self.pending_loop
                        .push((None, Some(target), Some(iter), body, is_async));
                    let else_blk = Block::new(BlockType::ForElse, pos, else_end);
                    self.blocks.push(else_blk);
                } else if let Some(se) = b
                    .for_setup_end
                    .filter(|se| {
                        *se > eff_end && self.setup_for_else_region(eff_end, *se)
                    })
                {
                    // SETUP_LOOP-era for-else: the exhaustion exit (b.end)
                    // closed the body; the else region runs to the loop pop
                    self.pending_loop
                        .push((None, Some(target), Some(iter), body, is_async));
                    let else_blk = Block::new(BlockType::ForElse, eff_end, se);
                    self.blocks.push(else_blk);
                } else {
                    self.push_stmt(Stmt::For {
                        target,
                        iter,
                        body,
                        orelse: Vec::new(),
                        is_async,
                    });
                }
            }
            BlockType::WhileElse => {
                let orelse = std::mem::take(&mut b.stmts);
                let (cond, _, _, body, _) = self.pending_loop.pop().unwrap_or_default();
                self.push_stmt(Stmt::While {
                    cond: cond.unwrap_or_else(|| self.true_cond_expr()),
                    body,
                    orelse,
                });
            }
            BlockType::ForElse => {
                let orelse = std::mem::take(&mut b.stmts);
                let (_, target, iter, body, is_async) =
                    self.pending_loop.pop().unwrap_or_default();
                self.push_stmt(Stmt::For {
                    target: target.unwrap_or_else(|| self.name_expr("_")),
                    iter: iter.unwrap_or_else(|| self.name_expr("???")),
                    body,
                    orelse,
                    is_async,
                });
            }
            BlockType::Try => {
                let body = std::mem::take(&mut b.stmts);
                // 3.11+ exception-table-driven try: body done, handlers are
                // parsed out-of-line; else/finally emission happens when the
                // protected region ends (or immediately without finally)
                if let Some(tc) = self.active_try.take() {
                    if self.active_try.is_none() {
                        self.active_try = self.active_try_stack.pop();
                    }
                    self.last_try_body_end = Some(tc.body_end);
                    self.pending_try_body.push(body.clone());
                    let cover = tc.region_end;
                    // the region may end exactly at the RETURN that closes
                    // the try body (`try: return v` where only the value
                    // load is protected): defer so emit_return can place
                    // the return INSIDE the body
                    let return_at_edge = cover == pos
                        && body.is_empty()
                        && self
                            .idx_of
                            .get(&pos)
                            .map_or(false, |&pi| {
                                matches!(
                                    self.instrs[pi].op,
                                    Op::RETURN_VALUE | Op::RETURN_CONST
                                )
                            });
                    if tc.split_body2.is_some() {
                        // split finally: the reconstruct rebuilds every
                        // span — emit now, before the walk drifts into
                        // the second protected fragment
                        self.pending_try_body.pop();
                        self.emit_try_tail(tc, pos);
                    } else if cover > pos || return_at_edge {
                        self.pending_try_body.pop();
                        self.pending_try_body.push(body);
                        self.pending_try_ctx = Some(tc);
                        self.pending_orelse_mark =
                            self.blocks.last().map(|b| b.stmts.len());
                    } else {
                        self.arm_try_body_tail(&tc);
                        self.emit_try_tail(tc, pos);
                    }
                    return;
                }
                if let Some(finally_target) = b.finally_target {
                    // Either except handlers follow (pushed by the closing
                    // jump / exception-table flow) or this is try/finally.
                    let handlers = std::mem::take(&mut self.pending_handlers);
                    self.pending_try_body.push(body);
                    self.pending_try_handlers.push(handlers);
                    let mut fin = Block::new(BlockType::Finally, pos, usize::MAX);
                    fin.finally_target = Some(finally_target);
                    self.blocks.push(fin);
                } else if self.version.at_least(3, 11) {
                    let handlers = std::mem::take(&mut self.pending_handlers);
                    self.push_stmt(Stmt::Try {
                        body,
                        handlers,
                        orelse: Vec::new(),
                        finalbody: Vec::new(),
                    });
                } else {
                    // pre-3.11: handlers live out-of-line starting at `pos`;
                    // defer emission until the chain completes
                    // 3.8-3.10 try/finally: the out-of-line region is a
                    // finally COPY (no except dispatch, ends in RERAISE /
                    // END_FINALLY) and the real finally body runs INLINE
                    // right after this POP_BLOCK
                    let mut has_finally = false;
                    let mut inline_end = usize::MAX;
                    if self.version.at_least(3, 8) {
                        // classify from the HANDLER head (the Try block's
                        // end), not from this POP_BLOCK: when the finally
                        // body itself holds a nested try/except, a linear
                        // scan from the body end meets the NESTED chain's
                        // match head first and misreads the outer finally
                        // chain as an except chain (_bootsubprocess 3.10
                        // check_output `finally: {try: os.unlink(...)
                        // except OSError: pass}`)
                        let scan_off = if b.end > pos { b.end } else { pos };
                        if let Some(&hi) = self.idx_of.get(&scan_off) {
                            // a handler region whose HEAD is a SETUP op is
                            // a FINALLY copy whose body starts with a
                            // nested try - the nested chain's except-match
                            // head must NOT end the classification
                            // (_bootsubprocess 3.9 check_output: the scan
                            // broke at the nested OSError JUMP_IF_NOT_EXC_
                            // MATCH, misread the outer finally chain as an
                            // except chain, and the inline copy rendered
                            // as an orphan try/except with the whole outer
                            // body lost). The copy's marker is its own
                            // terminating RERAISE/END_FINALLY at depth 0
                            // (depth counted from the leading SETUP; the
                            // nested chain's mismatch RERAISE at depth 0
                            // also serves - the classification only needs
                            // SOME depth-0 terminator). A plain except
                            // chain (any other head) still ends the scan
                            // at its first match head, exactly as before.
                            let head_setup = matches!(
                                self.instrs[hi].op,
                                Op::SETUP_FINALLY
                                    | Op::SETUP_EXCEPT
                                    | Op::SETUP_CLEANUP
                                    | Op::SETUP_LOOP
                            );
                            let mut setup_depth = 0i32;
                            let mut first_break: Option<usize> = None;
                            for k in hi..(hi + 160).min(self.instrs.len()) {
                                let ins = &self.instrs[k];
                                match ins.op {
                                    Op::SETUP_FINALLY
                                    | Op::SETUP_EXCEPT
                                    | Op::SETUP_CLEANUP
                                    | Op::SETUP_LOOP => {
                                        setup_depth += 1;
                                    }
                                    Op::POP_BLOCK => {
                                        if setup_depth > 0 {
                                            setup_depth -= 1;
                                        } else if !head_setup {
                                            if first_break.is_none() {
                                                first_break =
                                                    Some(ins.offset);
                                            }
                                            break;
                                        }
                                    }
                                    Op::JUMP_IF_NOT_EXC_MATCH
                                    | Op::POP_EXCEPT => {
                                        if !head_setup {
                                            if first_break.is_none() {
                                                first_break =
                                                    Some(ins.offset);
                                            }
                                            break;
                                        }
                                    }
                                    // a DUP_TOP only ends the scan when it
                                    // heads an except match (pattern loads
                                    // then COMPARE_OP(exc)/JUMP_IF_NOT_EXC_
                                    // MATCH follow); the chained-assign dup
                                    // inside a finally copy (`err1 = err2 =
                                    // None` = LOAD None; DUP_TOP; STORE;
                                    // STORE; END_FINALLY, codeop
                                    // _maybe_compile) must scan through to
                                    // the END_FINALLY
                                    Op::DUP_TOP => {
                                        let match_head = self.instrs[k + 1..]
                                            .iter()
                                            .take(8)
                                            .any(|x| {
                                                x.op
                                                    == Op::JUMP_IF_NOT_EXC_MATCH
                                                    || (x.op == Op::COMPARE_OP
                                                        && cmp_from_index(
                                                            compare_op_index(
                                                                x.arg as u32,
                                                                self.version,
                                                            ),
                                                        ) == CmpOp::ExceptionMatch)
                                            });
                                        if match_head && !head_setup {
                                            if first_break.is_none() {
                                                first_break =
                                                    Some(ins.offset);
                                            }
                                            break;
                                        }
                                    }
                                    Op::COMPARE_OP
                                        if cmp_from_index(compare_op_index(
                                            ins.arg as u32,
                                            self.version,
                                        )) == CmpOp::ExceptionMatch =>
                                    {
                                        if !head_setup {
                                            if first_break.is_none() {
                                                first_break =
                                                    Some(ins.offset);
                                            }
                                            break;
                                        }
                                    }
                                    Op::RERAISE | Op::END_FINALLY => {
                                        if setup_depth == 0 {
                                            has_finally = true;
                                            break;
                                        }
                                    }
                                    _ => {}
                                }
                            }
                            if !has_finally {
                                if let Some(fb) = first_break {
                                    // except chain: bound the inline_end
                                    // scan at the first match head (a
                                    // clause's normal-exit JUMP_FORWARD
                                    // before the mismatch RERAISE would
                                    // otherwise misread as an inline-
                                    // finally end and mark the chain
                                    // has_finally by accident)
                                    inline_end = fb;
                                }
                            }
                        }
                        if has_finally {
                            // the inline finally body runs from right after
                            // the POP_BLOCK to its RETURN (function-tail
                            // finally) or the forward jump over the handler
                            // copy — the block end is the handler start,
                            // which lies PAST the inline region. A NESTED
                            // try inside the finally body opens its own
                            // SETUP level: its POP_BLOCK/JF close the
                            // nested level only — track the depth so the
                            // outer region extends to ITS own matching
                            // close (bz2 3.8 close: `finally: {try: ...
                            // finally: ...}` — stopping at the nested
                            // POP_BLOCK stranded the inner finally's
                            // stores outside the outer chain)
                            let mut setup_depth = 0i32;
                            for ins in self.instrs.iter() {
                                if ins.offset < self.cur_next {
                                    continue;
                                }
                                match ins.op {
                                    Op::SETUP_FINALLY
                                    | Op::SETUP_EXCEPT
                                    | Op::SETUP_CLEANUP
                                    | Op::SETUP_LOOP => {
                                        setup_depth += 1;
                                    }
                                    Op::RETURN_VALUE | Op::RETURN_CONST => {
                                        inline_end = ins.offset;
                                        break;
                                    }
                                    // a nested try/finally runs the
                                    // enclosing level's POP_BLOCK right
                                    // after this level's inline body
                                    Op::POP_BLOCK => {
                                        if setup_depth > 0 {
                                            setup_depth -= 1;
                                            continue;
                                        }
                                        inline_end = ins.offset;
                                        break;
                                    }
                                    Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE => {
                                        if setup_depth == 0
                                            && ins.target.unwrap_or(0) > pos
                                        {
                                            inline_end = ins.offset;
                                            break;
                                        }
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                    // a nested inline-finally level completes right here
                    // (its else region ends at this POP_BLOCK): fold the
                    // still-active inner chain into a Try statement first
                    // — the trailing stmts of `body` collected past the
                    // inner else_start are the inner inline finally
                    // an active chain at this POP_BLOCK: structurally
                    // COMPLETE (its protected region ended here) folds on
                    // top of the new chain so its Try statement lands in
                    // the new body; a still-live chain (mid-body) stashes
                    // via legacy_nest and the new level nests inside it
                    let prev_complete = self.legacy_try.as_ref().map_or(false, |prev| {
                        prev.else_start
                            .map_or(false, |es| es < self.cur_offset)
                            && (prev.has_finally || !prev.handlers.is_empty())
                            // the else region must have ENDED, not merely
                            // started: with an unbounded else_stop the
                            // region runs until its own end edge, and a
                            // nested try laid out INSIDE it belongs in
                            // the outer orelse — folding the outer here
                            // emits it before the inner chain parses and
                            // drops the inner try out of the else (3.3
                            // fileinput readline: the chmod try/except
                            // landed after `else: fdopen` instead of
                            // inside it, shortening the except arm's
                            // merge jump). 3.8+ inline-finally layouts
                            // rely on the early fold (folding on top of
                            // the new chain puts the Try in its body):
                            // stashing there scrambles the emission
                            // order (_osx_support 3.9 _get_system_version)
                            && (self.cur_offset >= prev.else_stop
                                // 3.8+ inline-finally layouts rely on the
                                // early fold (folding on top of the new
                                // chain puts the Try in its body -
                                // bz2/cmd), but ONLY while no nested try
                                // level is still open inside the region:
                                // an unmatched SETUP between else_start
                                // and this POP_BLOCK means the POP_BLOCK
                                // closes the NESTED level and the outer
                                // region runs on - folding here emits the
                                // outer chain before the inner chain
                                // parses, dropping the nested try out of
                                // its finalbody (bz2 3.8 close) or out of
                                // the else region (_osx_support 3.8/3.9
                                // _get_system_version: `else: {try:
                                // re.search finally: f.close()}` rendered
                                // as a sibling AFTER the outer try, so
                                // f.read() ran before f=open() and the
                                // inner try ran even when open() raised,
                                // which the else forbids). Stash via
                                // legacy_nest in that case instead.
                                || (self.version.at_least(3, 8) && {
                                    let mut d = 0i32;
                                    for ins in self.instrs.iter() {
                                        if ins.offset
                                            < prev
                                                .else_start
                                                .unwrap_or(usize::MAX)
                                        {
                                            continue;
                                        }
                                        if ins.offset >= self.cur_offset {
                                            break;
                                        }
                                        match ins.op {
                                            Op::SETUP_FINALLY
                                            | Op::SETUP_EXCEPT
                                            | Op::SETUP_CLEANUP => d += 1,
                                            Op::POP_BLOCK => d -= 1,
                                            _ => {}
                                        }
                                    }
                                    d == 0
                                }))
                    });
                    let mut prev_done = if prev_complete {
                        self.legacy_try.take()
                    } else {
                        None
                    };
                    if self.legacy_try.is_some() {
                        self.begin_legacy_nest();
                    }
                    let mark = self.blocks.last().map(|b| b.stmts.len()).unwrap_or(0);
                    if self.legacy_try.is_some() {
                        self.begin_legacy_nest();
                    }
                    if let Some(p) = prev_done.take() {
                        // fold the completed inner chain FIRST so its Try
                        // statement is in place before the enclosing chain
                        // starts collecting
                        //
                        // when the folded chain's protected region lies
                        // INSIDE this closing Try block's span, its Try is
                        // lexically part of the new chain's body (`body`
                        // below): absorb it instead of leaving it as an
                        // enclosing-block sibling that would render ahead
                        // of the outer Try (code 3.10 interact: the outer
                        // try's POP_BLOCK folds the inner EOFError chain
                        // [164,222) inside the outer span [146,224); the
                        // loop-body push ordered the inner Try BEFORE the
                        // outer Try emitted at the back edge — rotated
                        // body). Chains outside the span (inside the
                        // region's else, or already-pushed enclosing
                        // chains) keep the historical sibling push.
                        let absorb = p.handler_start >= b.start
                            && p.handler_start < b.end
                            && self.chain_absorb_body.is_none();
                        let before =
                            self.blocks.last().map(|b| b.stmts.len()).unwrap_or(0);
                        self.push_legacy_try(p);
                        if absorb {
                            let taken = self
                                .blocks
                                .last_mut()
                                .filter(|b| {
                                    b.stmts.len() == before + 1
                                        && matches!(b.stmts.last(), Some(Stmt::Try { .. }))
                                })
                                .and_then(|b| b.stmts.pop());
                            if let Some(st) = taken {
                                self.chain_absorb_body = Some(vec![st]);
                            }
                        }
                    }
                    self.legacy_try = Some(LegacyTry {
                        body,
                        handlers: Vec::new(),
                        orelse: Vec::new(),
                        finalbody: Vec::new(),
                        handler_start: pos,
                        has_finally,
                        else_start: if has_finally {
                            Some(self.cur_next)
                        } else {
                            None
                        },
                        else_stop: inline_end,
                        chain_done: false,
                        pending_mismatch: Vec::new(),
                        else_stmt_mark: mark,
                    });

                }
            }
            BlockType::TryElse => {
                // try body finished; else clause runs until the finally
                let orelse = std::mem::take(&mut b.stmts);
                let body = self.pending_try_body.pop().unwrap_or_default();
                let handlers = self.pending_try_handlers.pop().unwrap_or_default();
                let mut fin = Block::new(BlockType::Finally, pos, usize::MAX);
                fin.finally_target = b.finally_target;
                self.pending_try_body.push(body);
                self.pending_try_handlers.push(handlers);
                self.pending_try_orelse.push(orelse);
                self.blocks.push(fin);
            }
            BlockType::Except => {
                let handler = ExceptHandler {
                    type_: b.handler_type.take(),
                    name: b.handler_name.take(),
                    body: std::mem::take(&mut b.stmts),
                    is_star: false,
                };
                self.pending_handlers.push(handler);
            }
            BlockType::Finally => {
                let finalbody = std::mem::take(&mut b.stmts);
                let body = self.pending_try_body.pop().unwrap_or_default();
                let handlers = self.pending_try_handlers.pop().unwrap_or_default();
                let orelse = self.pending_try_orelse.pop().unwrap_or_default();
                if finalbody.iter().all(|s| matches!(s, Stmt::Pass)) && handlers.is_empty() {
                    // bare container close — emit body directly
                    self.push_stmt_all(body);
                    self.push_stmt_all(orelse);
                } else {
                    self.push_stmt(Stmt::Try {
                        body,
                        handlers,
                        orelse,
                        finalbody,
                    });
                }
            }
            BlockType::With => {
                let items = match b.with_item.take() {
                    Some(item) => vec![item],
                    None => self.pending_with.pop().unwrap_or_else(|| {
                        vec![WithItem {
                            ctx: self.name_expr("???"),
                            target: None,
                        }]
                    }),
                };
                let stmt = Stmt::With {
                    items,
                    body: std::mem::take(&mut b.stmts),
                    is_async: b.is_async,
                };
                self.push_stmt(stmt);
            }
            BlockType::Container => {
                if !b.stmts.is_empty() {
                    let stmts = std::mem::take(&mut b.stmts);
                    // A try/finally Container nested inside an OUTER
                    // try/except's ELSE region: its completed statement is
                    // the else region's content and must route into the
                    // outer try's orelse, NOT the enclosing block. The
                    // Container closes via push_stmt_all (which bypasses
                    // push_stmt's else-region redirect), so without this the
                    // inner try emitted as a SIBLING BEFORE the outer try -
                    // scrambling the order and using values before they are
                    // bound (_osx_support _get_system_version/_read_output:
                    // `try: f=open() except OSError: pass else:
                    // try: x=f.read() finally: f.close()` rendered the inner
                    // read first, so f was read before open). The Container's
                    // start lies inside [else_start, else_stop) of a live
                    // outer try/except that has an else region.
                    let b_start = b.start;
                    let in_outer_else =
                        self.legacy_try.as_ref().map_or(false, |l| {
                            !l.has_finally
                                && l.else_start.map_or(false, |es| {
                                    b_start >= es && b_start < l.else_stop
                                })
                        });
                    if in_outer_else {
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.orelse.extend(stmts);
                        }
                    } else {
                        self.push_stmt_all(stmts);
                    }
                }
            }
        }
    }

    fn flush_stack(&mut self) {
        // Leftover stack values at stream end are simulation artifacts
        // (iterator bookkeeping, saved locals from inline comprehensions);
        // only import markers still carry statement meaning.
        while let Some(sv) = self.stack.pop() {
            if let Sv::ImportModule { module, .. } = sv {
                self.push_stmt(Stmt::Import { names: vec![(module, None)] });
            }
        }
    }

    // ----- stack helpers -----

    fn push(&mut self, e: ExprRef) {
        self.stack.push(Sv::E(e));
    }

    fn pop(&mut self) -> Option<Sv> {
        self.stack.pop()
    }

    fn pop_expr(&mut self) -> ExprRef {
        loop {
            match self.stack.pop() {
                Some(Sv::E(e)) => return e,
                Some(Sv::Null) => continue,
                Some(other) => {
                    // keep import markers on the stack; anything else is
                    // rendered as None so the output stays compilable
                    if matches!(other, Sv::ImportModule { .. } | Sv::ImportFrom { .. }) {
                        self.stack.push(other);
                        self.mark_unclean();
                        return Rc::new(Expr::Const(Rc::new(PyObject::None)));
                    }
                    self.mark_unclean();
                    return Rc::new(Expr::Const(Rc::new(PyObject::None)));
                }
                None => {
                    self.mark_unclean();
                    if std::env::var("PYCDC_TRACE").is_ok() {
                        eprintln!("AW UNDERFLOW pop_expr at {} in {:?}", self.cur_offset, self.code.name);
                    }
                    return Rc::new(Expr::Const(Rc::new(PyObject::None)));
                }
            }
        }
    }

    fn pop_expr_raw(&mut self) -> Option<Sv> {
        self.stack.pop()
    }

    /// Restore PEP 8 private names: inside class C the compiler rewrites
    /// `__x` to `_C__x`. The decompiler walks class bodies with the class
    /// name on `class_scope`, so reverse it here.
    fn unmangle(&self, name: &str) -> String {
        if name.starts_with('_') && !name.ends_with("__") {
            for cls in self.class_scope.iter().rev() {
                let ident = cls.trim_start_matches('_');
                if ident.is_empty() {
                    continue;
                }
                let prefix = format!("_{}__", ident);
                if name.starts_with(&prefix) && name.len() > prefix.len() {
                    return format!("__{}", &name[prefix.len()..]);
                }
            }
        }
        name.to_string()
    }

    /// Like `pop_expr`, but reports whether a NULL marker was skipped on
    /// the way to the expression (3.13 pushes NULL above the callable).
    fn pop_expr_skipped(&mut self) -> (ExprRef, bool) {
        let mut skipped = false;
        loop {
            match self.stack.pop() {
                Some(Sv::E(e)) => return (e, skipped),
                Some(Sv::Null) => {
                    skipped = true;
                    continue;
                }
                Some(other) => {
                    if matches!(other, Sv::ImportModule { .. } | Sv::ImportFrom { .. }) {
                        self.stack.push(other);
                        self.mark_unclean();
                        return (Rc::new(Expr::Const(Rc::new(PyObject::None))), skipped);
                    }
                    self.mark_unclean();
                    return (Rc::new(Expr::Const(Rc::new(PyObject::None))), skipped);
                }
                None => {
                    self.mark_unclean();
                    return (Rc::new(Expr::Const(Rc::new(PyObject::None))), skipped);
                }
            }
        }
    }

    fn const_expr(&mut self, idx: usize) -> ExprRef {
        match self.code.consts.get(idx) {
            Some(o) => Rc::new(Expr::Const(o.clone())),
            None => {
                self.mark_unclean();
                self.name_expr(format!("/*bad-const-{idx}*/"))
            }
        }
    }

    fn name_expr(&self, name: impl Into<String>) -> ExprRef {
        Rc::new(Expr::Name(name.into()))
    }

    /// Synthesized condition of a condition-less while loop. py2 does
    /// NOT constant-fold `while True:` (it compiles to LOAD_NAME True +
    /// a per-iteration PJF), while the source `while 1:` these loops
    /// come from has no condition jump at all — render the synthesized
    /// condition as `1` so the recompile keeps the cond-less shape
    /// (cgi 2.7 parse_multipart's inner readline loop). py3 folds both
    /// forms; keep the idiomatic `True` there.
    fn true_cond_expr(&self) -> ExprRef {
        if self.version.major < 3 {
            Rc::new(Expr::Const(Rc::new(PyObject::Int(1))))
        } else {
            self.name_expr("True")
        }
    }

    fn const_name(&self, idx: usize) -> String {
        let n = self
            .code
            .names
            .get(idx)
            .and_then(|n| match &**n {
                PyObject::Str(s) => Some(s.clone()),
                PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                _ => None,
            })
            .unwrap_or_else(|| format!("/*bad-name-{idx}*/"));
        self.unmangle(&n)
    }

    fn local_name(&self, idx: usize) -> String {
        self.code
            .varnames
            .get(idx)
            .map(|n| sanitize_varname(n))
            .unwrap_or_else(|| format!("/*bad-local-{idx}*/"))
    }

    /// Target name of a STORE_*/DELETE_* instruction at `idx` (the
    /// instruction index, not bytecode offset). None for non-store ops.
    fn store_del_name(&self, idx: usize) -> Option<String> {
        let ins = self.instrs.get(idx)?;
        match ins.op {
            Op::STORE_FAST | Op::DELETE_FAST => Some(self.local_name(ins.arg as usize)),
            Op::STORE_NAME | Op::DELETE_NAME => Some(self.const_name(ins.arg as usize)),
            Op::STORE_DEREF | Op::DELETE_DEREF => Some(
                self.code
                    .deref_name(ins.arg as usize)
                    .unwrap_or("?")
                    .to_string(),
            ),
            _ => None,
        }
    }

    /// 2.6 comprehension accumulator temps (`_[1]` …) are compiler
    /// synthetic names — no source statement ever references them
    fn is_comp_temp_name(&self, n: &str) -> bool {
        self.version.major == 2 && n.starts_with("_[") && n.ends_with(']')
    }

    fn push_stmt(&mut self, stmt: Stmt) {
        // re-fold De Morgan expansions (see refold_demorgan)
        let stmt = match stmt {
            Stmt::If { cond, body, orelse } => Stmt::If {
                cond: refold_demorgan(cond),
                body,
                orelse,
            },
            Stmt::While { cond, body, orelse } => Stmt::While {
                cond: refold_demorgan(cond),
                body,
                orelse,
            },
            Stmt::Assert { test, msg } => Stmt::Assert {
                test: refold_demorgan(test),
                msg,
            },
            other => other,
        };
        // any other statement flushes a pending same-line store group first
        // to preserve source order
        if !self.flushing && !self.pending_stores.is_empty() {
            self.flushing = true;
            self.flush_pending_stores();
            self.flushing = false;
        }
        self.last_flush_offset = self.cur_offset;
        if !self.region_collect_only {
            if let Some(h) = self.legacy_handler.as_mut() {
                if self.blocks.len() <= h.block_depth {
                    h.body.push(stmt);
                    return;
                }
                // a block (If/While/...) opened inside the handler collects the
                // statement; it lands in the handler body when the block closes
            }
        }
        // statements emitted while a NESTED chain is being parsed (the
        // outer handler state is stashed) still belong to the outermost
        // stashed handler's body — e.g. the success-path fall-through
        // after a nested try inside an except body
        if !self.region_collect_only
            && self.legacy_handler.is_none()
            && !self.legacy_nest.is_empty()
        {
            if let Some(h) = self.legacy_nest[0].outer_handler.as_mut() {
                if self.blocks.len() <= h.block_depth {
                    h.body.push(stmt);
                    return;
                }
            }
        }
        // a `break` emitted while the chain is still collecting (after the
        // body's POP_BLOCK closed the Try block, before the handler head)
        // belongs INSIDE lt.body — the edge is lexically within the
        // protected region (_sitebuiltins 3.8+ __setup: `try: with ...;
        // break` rendered the break ahead of the Try at loop level)
        if matches!(stmt, Stmt::Break)
            && self.legacy_handler.is_none()
            && self.legacy_nest.is_empty()
        {
            if let Some(lt) = self.legacy_try.as_mut() {
                if lt.else_start.is_none() && self.cur_offset < lt.handler_start {
                    lt.body.push(stmt);
                    return;
                }
            }
        }
        // a block opened INSIDE the else region (an if/loop of the else
        // body) collects its own statements; only redirect when the
        // innermost structure is the region itself. Without this, arm
        // statements of an if inside the else leak out flat and the if
        // closes empty (crypt _add_method's merge-flow `if result and
        // len(result)==total: append; return True` rendered as
        // `append; return True; if ...: pass`). A block that STRADDLES
        // the region start (opened before it, e.g. the 324ffb5 nested-
        // else shape) still redirects — its close lands past the region.
        let else_region_block_open = self
            .legacy_try
            .as_ref()
            .and_then(|l| l.else_start)
            .map_or(false, |es| {
                self.blocks
                    .last()
                    .map_or(false, |b| b.start >= es && b.kind != BlockType::Main)
            });
        // statements executed inside a collected try-else region belong to
        // the Try's orelse, not to the enclosing block; a 3.8-3.10 inline
        // finally body collects into finalbody. The else_stop bound is
        // INCLUSIVE: the legacy-try flush fires at the first offset >=
        // else_stop and drains the else region's trailing pending stores
        // there (cur_offset == else_stop) before taking the try, so those
        // stores still belong to orelse. (Matches the inclusive checks used
        // by the else-region probes elsewhere.)
        if !else_region_block_open {
            if let Some(lt) = self.legacy_try.as_mut() {
                if let Some(es) = lt.else_start {
                    // has_finally regions extend to the HANDLER start:
                    // a branching finally body has multiple sunk tail
                    // returns and the inline_end scan stops at the
                    // first — if-arm wrappers over the copy close past
                    // else_stop and still belong to the finally body
                    // (cmd 3.10 cmdloop). orelse regions keep the
                    // precise else_stop bound.
                    let stop = if lt.has_finally {
                        lt.else_stop.max(lt.handler_start)
                    } else {
                        lt.else_stop
                    };
                    if self.cur_offset >= es && self.cur_offset <= stop {
                        if lt.has_finally {
                            lt.finalbody.push(stmt);
                        } else {
                            lt.orelse.push(stmt);
                        }
                        return;
                    }
                }
            }
        }
        if let Some(top) = self.blocks.last_mut() {
            top.stmts.push(stmt);
        }
    }

    /// A block that ENCLOSES the active chain's else region (opened
    /// before the region start, closing at/after the current offset
    /// while the redirect is live) is the region's CONTAINER: its
    /// statement belongs to the block's own parent, not inside the
    /// orelse it wraps. Without this the container's close — which
    /// shares the region-end offset with the region's own trailing
    /// blocks — rode the redirect and the whole guard landed inside
    /// the try's else arm (_osx_support 3.10 _get_system_version:
    /// `if _SYSTEM_VERSION is None:` enclosing try/except/else).
    fn stmt_escapes_else_region(&self, b_start: usize) -> bool {
        match self.legacy_try.as_ref().and_then(|l| l.else_start) {
            Some(es) => {
                b_start < es
                    && self.cur_offset >= es
                    && self.legacy_try.as_ref().map_or(false, |l| {
                        self.cur_offset <= l.else_stop
                            // require a genuinely PROCESSED chain: the
                            // flush this branch performs is only valid
                            // for a done try/except/else with handlers
                            // and no finally. A raw un-flushed finally
                            // skeleton (chain_done=false, empty
                            // handlers, unbounded else_stop) must fall
                            // through to the normal If close — routing
                            // it here leaked a duplicated teardown arm
                            // (cmd 3.9 cmdloop's compiler-duplicated
                            // `finally` body)
                            && l.chain_done
                            && !l.handlers.is_empty()
                            && !l.has_finally
                    })
            }
            None => false,
        }
    }

    fn push_stmt_all(&mut self, stmts: Vec<Stmt>) {
        if let Some(top) = self.blocks.last_mut() {
            top.stmts.extend(stmts);
        }
    }

    fn pop_n_exprs(&mut self, n: usize) -> Vec<ExprRef> {
        let mut out = Vec::with_capacity(n);
        for _ in 0..n {
            out.push(self.pop_expr());
        }
        out.reverse();
        out
    }

    fn mark_unclean(&mut self) {
        if std::env::var("PYCDC_UNCLEAN").is_ok() {
            eprintln!("UNCLEAN @{} fn={}", self.cur_offset, self.code.name);
            if std::env::var("PYCDC_UNCLEAN_BT").is_ok() {
                let bt = std::backtrace::Backtrace::force_capture();
                for l in bt.to_string().lines().take(40) {
                    if l.contains("decompiler.rs") {
                        eprintln!("   {}", l.trim());
                    }
                }
            }
        }
        self.clean = false;
    }

    fn unimplemented(&mut self, inst: &Instruction, what: &str) {
        self.mark_unclean();
        let text = format!(
            "/* {what}: {} {} @{} */",
            self.table.name(inst.opcode),
            if inst.has_arg {
                inst.arg.to_string()
            } else {
                String::new()
            },
            inst.offset
        );
        self.push_stmt(Stmt::Unimplemented(text));
    }
}

#[allow(dead_code)]
fn short(sv: &Sv) -> String {
    match sv {
        Sv::Null => "null".into(),
        Sv::ImportModule { module, .. } => format!("import:{module}"),
        Sv::ImportFrom { module, name, .. } => format!("from:{module}:{name}"),
        Sv::E(_) => "expr".into(),
    }
}

// =====================  instruction dispatch  =====================

use crate::opcode::Op;

impl<'a> Ctx<'a> {
    /// Execute one instruction. Returns false when the instruction stream
    /// should stop being processed (unconditional exit).
    fn exec(&mut self, inst: &Instruction) -> bool {
        let arg = inst.arg;
        let cont = match inst.op {
            // ---------- no-ops / housekeeping ----------
            Op::NOP
            | Op::CACHE
            | Op::RESUME
            | Op::RESUME_CHECK
            | Op::PRECALL
            | Op::COPY_FREE_VARS
            | Op::MAKE_CELL
            | Op::SETUP_ANNOTATIONS
            | Op::EXTENDED_ARG
            | Op::GEN_START
            | Op::ASYNC_GEN_WRAP
            | Op::SET_LINENO
            | Op::STOP_CODE
            | Op::PUSH_EXC_INFO
            | Op::ANNOTATIONS_PLACEHOLDER
            | Op::JUMP_BACKWARD_NO_INTERRUPT
            | Op::NOT_TAKEN
            | Op::BEGIN_FINALLY => true,

            // ---------- constants / names ----------
            Op::LOAD_CONST => {
                // 3.12+ inline with success exit: swallow the machinery
                // sequence and close the With here (codeop 3.13
                // _maybe_compile: the leak rendered `None(None, None)`
                // and trapped the post-with tail return inside the with)
                if self.version.at_least(3, 11) && self.with_exits > 0 {
                    if let Some(after) = self.inline_with_exit_span(self.cur_offset) {
                        // close the With ONLY when it is topmost: a sunk
                        // exit inside an open branch arm (`if quitting:
                        // return` — bdb 3.12 trace_dispatch) must keep
                        // the with/if open so the following RETURN
                        // renders inside the arm and the walk stays
                        // alive; the with closes at its own end or at
                        // the next success-path exit
                        if matches!(
                            self.blocks.last().map(|b| b.kind),
                            Some(BlockType::With)
                        ) {
                            self.close_with_blocks(self.cur_offset);
                        }
                        if self.skip_until.map_or(true, |s| s < after) {
                            self.skip_until = Some(after);
                        }
                        return true;
                    }
                }
                if let Some(PyObject::Code(c)) =
                    self.code.consts.get(arg as usize).map(|o| &**o)
                {
                    self.recent_code_const = Some(c.clone());
                }
                let e = self.const_expr(arg as usize);
                self.push(e);
                true
            }
            Op::RETURN_CONST => {
                // see RETURN_VALUE: drop the inline finally copy's
                // statements; the return itself still renders
                self.swallow_inline_finally_return();
                let e = self.const_expr(arg as usize);
                self.emit_return(Some(e));
                !matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main))
                    || self.legacy_try.is_some()
            }
            Op::LOAD_NAME => {
                let n = self.const_name(arg as usize);
                // 2.6 synthetic temp: inside an inline comprehension the
                // accumulator reload is tracked by the comp model; outside
                // (with-as target) the stashed value is reloaded
                if self.is_comp_temp_name(&n) {
                    if self.inline_comp.is_some() {
                        return true;
                    }
                    if let Some(v) = self.py26_temps.get(&n).cloned() {
                        self.stack.push(v);
                    } else {
                        self.push(self.name_expr(n));
                    }
                    return true;
                }
                self.push(self.name_expr(n));
                true
            }
            Op::LOAD_FAST
            | Op::LOAD_FAST_CHECK
            | Op::LOAD_FAST_AND_CLEAR
            | Op::LOAD_FAST_BORROW => {
                let n = self.local_name(arg as usize);
                // 2.6 function-level inline comprehension: the `_[N]`
                // accumulator is a FAST local — same handling as the
                // module-level STORE_NAME variant
                if self.is_comp_temp_name(&n) {
                    if self.inline_comp.is_some() {
                        return true;
                    }
                    if let Some(v) = self.py26_temps.get(&n).cloned() {
                        self.stack.push(v);
                    } else {
                        self.push(self.name_expr(n));
                    }
                    return true;
                }
                self.push(self.name_expr(n));
                true
            }
            Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => {
                // 3.14: loads two locals, (arg >> 4) first then (arg & 0xF)
                let a = self.local_name(((arg >> 4) & 0xF) as usize);
                let b = self.local_name((arg & 0xF) as usize);
                self.push(self.name_expr(a));
                self.push(self.name_expr(b));
                true
            }
            Op::LOAD_FAST_LOAD_FAST => {
                let a = self.local_name((arg >> 4) as usize);
                let b = self.local_name((arg & 0xF) as usize);
                self.push(self.name_expr(a));
                self.push(self.name_expr(b));
                true
            }
            Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL => {
                let n = self.local_name(arg as usize);
                if self.is_comp_temp_name(&n) {
                    let v = self.pop_store_value();
                    self.py26_temps.insert(n.clone(), v);
                    self.last_py26_temp = Some(n);
                    return true;
                }
                if self.walrus_at_name(inst, &n) {
                    let val = self.pop_expr();
                    self.pop(); // the duplicated original
                    self.push(Rc::new(Expr::Named {
                        target: self.name_expr(n),
                        value: val,
                    }));
                    return true;
                }
                let is_pending =
                    self.pending_restore_vars.iter().any(|v| *v == n);
                // a 3.12+ inline comprehension's restore is DUPLICATED:
                // the normal exit (STORE; RETURN) consumes
                // pending_restore_vars, then the exception cleanup (STORE;
                // RERAISE) stores the same names with pending empty and a
                // drained stack. Suppress that duplicate (quiet pop, no
                // statement) — but ONLY on an empty stack, so a genuine
                // later assignment of the same name (which pops a computed
                // value) still renders.
                if !is_pending
                    && self.comp_restore_vars.iter().any(|v| *v == n)
                    && self.stack.iter().all(|s| matches!(s, Sv::Null))
                {
                    let _ = self.pop_store_value_quiet();
                    return true;
                }
                let val = if is_pending {
                    self.pop_store_value_quiet()
                } else {
                    self.pop_store_value()
                };
                self.emit_store_sv(self.name_expr(n), val);
                true
            }
            Op::STORE_FAST_LOAD_FAST => {
                let store_idx = (arg >> 4) as usize;
                let load_idx = (arg & 0xF) as usize;
                let val = self.pop_store_value();
                let n = self.local_name(store_idx);
                self.emit_store_sv(self.name_expr(n.clone()), val);
                let ln = self.local_name(load_idx);
                self.push(self.name_expr(ln));
                true
            }
            Op::STORE_FAST_STORE_FAST => {
                // first store (arg >> 4) consumes the TOP of stack
                let a = ((arg >> 4) & 0xF) as usize;
                let b = (arg & 0xF) as usize;
                let val_a = self.pop_store_value();
                let val_b = self.pop_store_value();
                let na = self.local_name(a);
                self.emit_store_sv(self.name_expr(na), val_a);
                let nb = self.local_name(b);
                self.emit_store_sv(self.name_expr(nb), val_b);
                true
            }
            Op::DELETE_FAST => {
                let n = self.local_name(arg as usize);
                if self.is_comp_temp_name(&n) {
                    self.py26_temps.remove(&n);
                    return true;
                }
                self.emit_delete(self.name_expr(n));
                true
            }
            Op::LOAD_GLOBAL => {
                let idx = if self.version.at_least(3, 11) {
                    (arg >> 1) as usize
                } else {
                    arg as usize
                };
                let n = self.const_name(idx);
                // the low-bit NULL-push encoding exists only in 3.11+;
                // pre-3.11 `arg` is the plain co_names index — an odd
                // index must NOT push a marker (it desyncs CALL_METHOD's
                // raw self-marker pop)
                if arg & 1 != 0 && self.version.at_least(3, 11) {
                    if self.version.at_least(3, 14) {
                        // 3.14 CALL slots: [callable, NULL, args] — value
                        // first, NULL marker on top
                        self.push(self.name_expr(n));
                        self.stack.push(Sv::Null);
                    } else {
                        // 3.11-3.13: NULL below the value
                        self.stack.push(Sv::Null);
                        self.push(self.name_expr(n));
                    }
                } else {
                    self.push(self.name_expr(n));
                }
                true
            }
            Op::STORE_GLOBAL => {
                let n = self.const_name(arg as usize);
                if !self.globals.contains(&n) {
                    self.globals.push(n.clone());
                }
                if self.walrus_at_name(inst, &n) {
                    // a walrus inside a comprehension stores to the
                    // enclosing scope (STORE_GLOBAL at module level)
                    let val = self.pop_expr();
                    self.pop(); // the duplicated original
                    self.push(Rc::new(Expr::Named {
                        target: self.name_expr(n),
                        value: val,
                    }));
                    return true;
                }
                let val = self.pop_store_value();
                self.emit_store_sv(self.name_expr(n), val);
                true
            }
            Op::DELETE_GLOBAL => {
                let n = self.const_name(arg as usize);
                if !self.globals.contains(&n) {
                    self.globals.push(n.clone());
                }
                self.emit_delete(self.name_expr(n));
                true
            }
            Op::STORE_NAME => {
                let n = self.const_name(arg as usize);
                // 2.6 inline comprehension accumulator stash (`_[N]`):
                // synthetic name, no source statement
                if self.is_comp_temp_name(&n) {
                    let v = self.pop_store_value();
                    self.py26_temps.insert(n.clone(), v);
                    self.last_py26_temp = Some(n);
                    return true;
                }
                if self.walrus_at_name(inst, &n) {
                    let val = self.pop_expr();
                    self.pop(); // the duplicated original
                    self.push(Rc::new(Expr::Named {
                        target: self.name_expr(n),
                        value: val,
                    }));
                    return true;
                }
                let val = self.pop_store_value();
                self.emit_store_sv(self.name_expr(n), val);
                true
            }
            Op::DELETE_NAME => {
                let n = self.const_name(arg as usize);
                if self.is_comp_temp_name(&n) {
                    self.py26_temps.remove(&n);
                    return true;
                }
                self.emit_delete(self.name_expr(n));
                true
            }
            Op::LOAD_DEREF | Op::LOAD_CLOSURE | Op::LOAD_CLASSDEREF => {
                let n = self
                    .code
                    .deref_name(arg as usize)
                    .unwrap_or("/*bad-deref*/")
                    .to_string();
                self.push(self.name_expr(n));
                true
            }
            Op::LOAD_FROM_DICT_OR_GLOBALS => {
                // 3.14+ (PEP 649 __annotate__): the class-body dict sits on
                // the stack (LOAD_DEREF __classdict__); look up co_names[arg]
                // in it, falling back to globals. For decompilation the
                // resolved value IS that name, so pop the dict and push the
                // name expression — this lets the annotation-reconstruction
                // path see a clean `{'kwargs': str, 'return': Self}` map.
                self.pop(); // the dict / classdict
                self.push(self.name_expr(self.const_name(arg as usize)));
                true
            }
            Op::STORE_DEREF => {
                let n = self
                    .code
                    .deref_name(arg as usize)
                    .unwrap_or("/*bad-deref*/")
                    .to_string();
                // STORE_DEREF on a freevar (not cellvar) implies `nonlocal`
                let is_free = self.code.freevars.iter().any(|f| *f == n)
                    && self.version.at_least(3, 0)
                    && self.code.name != "<module>";
                if is_free && !self.nonlocals.contains(&n) {
                    self.nonlocals.push(n.clone());
                }
                if self.walrus_at_name(inst, &n) {
                    let val = self.pop_expr();
                    self.pop(); // the duplicated original
                    self.push(Rc::new(Expr::Named {
                        target: self.name_expr(n),
                        value: val,
                    }));
                    return true;
                }
                let val = self.pop_store_value();
                self.emit_store_sv(self.name_expr(n), val);
                true
            }
            Op::DELETE_DEREF => {
                let n = self
                    .code
                    .deref_name(arg as usize)
                    .unwrap_or("/*bad-deref*/")
                    .to_string();
                self.emit_delete(self.name_expr(n));
                true
            }
            Op::LOAD_LOCALS => {
                self.push(self.name_expr("locals()"));
                true
            }
            Op::STORE_LOCALS => {
                // py2 class body: locals() -> class dict
                self.pop();
                true
            }
            Op::LOAD_BUILD_CLASS => {
                self.push(self.name_expr("__build_class__"));
                true
            }
            Op::LOAD_ASSERTION_ERROR => {
                self.push(self.name_expr("AssertionError"));
                true
            }
            Op::LOAD_SMALL_INT => {
                // 3.14+: pushes the small int `arg`
                self.push(Rc::new(Expr::Const(Rc::new(PyObject::Int(arg as i32)))));
                true
            }
            Op::LOAD_COMMON_CONSTANT => {
                // 3.14+: arg indexes dis._common_constants =
                //   [AssertionError, NotImplementedError, tuple, all, any].
                // all/any (3/4) also drive the inline all/any-genexpr
                // optimization guard:
                //   <all>; COPY 1; LOAD_COMMON_CONSTANT all; IS_OP 0;
                //   PJIF Lslow; NOT_TAKEN; POP_TOP; <inline genexpr loop
                //   with early exits>; Lslow: PUSH_NULL; <genexpr>;
                //   CALL 0; CALL 1  — both paths merge with one value.
                // Divert to the slow path: it renders the plain
                // `all(<genexpr>)` call via the existing machinery.
                // arg 2 (tuple): the same guard fronts the inlined
                // list-comp + LIST_TO_TUPLE fast path of `tuple(<genexpr>)`
                // (_osx_support 3.14 _get_system_version_tuple: walking
                // the fast path hit CALL_INTRINSIC_1 LIST_TO_TUPLE
                // unclean; the slow path renders the plain call)
                if (arg == 2 || arg == 3 || arg == 4)
                    && self.version.at_least(3, 14)
                {
                    if let Some(slow) = self.inline_all_any_slow_path(arg == 3) {
                        // drop the COPY 1 duplicate; the slow path expects
                        // just the callable
                        self.pop();
                                                self.skip_until = Some(slow);
                        return true;
                    }
                }
                const COMMON: [&str; 5] =
                    ["AssertionError", "NotImplementedError", "tuple", "all", "any"];
                match COMMON.get(arg as usize) {
                    Some(name) => self.push(self.name_expr(*name)),
                    None => {
                        self.mark_unclean();
                        self.push(Rc::new(Expr::Const(Rc::new(PyObject::None))));
                    }
                }
                true
            }

            // ---------- attributes ----------
            Op::LOAD_ATTR | Op::LOAD_METHOD => {
                let (idx, is_method) = match inst.op {
                    Op::LOAD_METHOD => (arg as usize, true),
                    _ if self.version.at_least(3, 12) => {
                        ((arg >> 1) as usize, arg & 1 != 0)
                    }
                    _ => (arg as usize, false),
                };
                let attr = self.unmangle(&self.const_name(idx));
                let value = self.pop_expr();
                let e: ExprRef = Rc::new(Expr::Attribute {
                    value: value.clone(),
                    attr,
                });
                if is_method {
                    if self.version.at_least(3, 14) {
                        // 3.14: [method, self_or_null] — marker on top
                        self.push(e);
                        self.push(value);
                    } else if self.version.at_least(3, 11) {
                        // 3.11-3.13: [self_or_null, method] — method on top
                        self.push(value);
                        self.push(e);
                    } else {
                        // 3.7-3.10: [method, self_or_null] — marker on top
                        self.push(e);
                        self.push(value);
                    }
                } else {
                    self.push(e);
                }
                true
            }
            Op::LOAD_SUPER_ATTR => {
                let idx = if self.version.at_least(3, 12) {
                    (arg >> 2) as usize
                } else {
                    arg as usize
                };
                let attr = self.unmangle(&self.const_name(idx));
                // stack: [super-global, class, self] — the attribute name
                // lives in co_names (arg), not on the stack
                let self_e = self.pop_expr();
                let cls = self.pop_expr();
                let sup = self.pop_expr();
                // two-arg form `super(C, self).m` vs zero-arg `super().m`
                let sup_call = match &*sup {
                    Expr::Name(n) if n == "super" => {
                        let is_zero_arg = matches!(&*cls, Expr::Name(cn) if cn.starts_with("__class"))
                            || matches!(&*cls, Expr::Const(_));
                        if is_zero_arg {
                            Rc::new(Expr::Call {
                                func: sup,
                                args: Vec::new(),
                                keywords: Vec::new(),
                                star_args: None,
                                star_kwargs: None,
                            }) as ExprRef
                        } else {
                            Rc::new(Expr::Call {
                                func: sup,
                                args: vec![cls, self_e],
                                keywords: Vec::new(),
                                star_args: None,
                                star_kwargs: None,
                            }) as ExprRef
                        }
                    }
                    _ => self.name_expr("super()"),
                };
                let e: ExprRef = Rc::new(Expr::Attribute {
                    value: sup_call,
                    attr,
                });
                if arg & 1 != 0 {
                    // loaded method: mirror the LOAD_ATTR marker order
                    if self.version.at_least(3, 14) {
                        self.push(e);
                        self.stack.push(Sv::Null);
                    } else if self.version.at_least(3, 12) {
                        self.stack.push(Sv::Null);
                        self.push(e);
                    } else {
                        self.push(e);
                    }
                } else {
                    self.push(e);
                }
                true
            }
            Op::LOAD_SPECIAL => {
                // 3.14: the arg indexes a fixed special-method table
                // ['__enter__','__exit__','__aenter__','__aexit__'],
                // NOT co_names
                let attr = ["__enter__", "__exit__", "__aenter__", "__aexit__"]
                    .get(arg as usize)
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| self.const_name(arg as usize));
                // 3.14 with header (BEFORE_WITH/BEFORE_ASYNC_WITH are gone):
                //   ctx; COPY 1; LOAD_SPECIAL __exit__; SWAP 2; SWAP 3;
                //   LOAD_SPECIAL __enter__; CALL 0; [GET_AWAITABLE..END_SEND]
                // Recognize it at the exit special: swallow the whole
                // header, open the With block, and leave the enter-result
                // placeholder for the `as` store / POP_TOP.
                if self.version.at_least(3, 14)
                    && (attr == "__exit__" || attr == "__aexit__")
                    && self
                        .idx_of
                        .get(&inst.offset)
                        .and_then(|&si| self.instrs.get(si - 1))
                        .map_or(false, |p| p.op == Op::COPY && p.arg == 1)
                {
                    let is_async = attr == "__aexit__";
                    let ctx_e = self.pop_expr();
                    let _dup = self.pop_expr(); // the COPY 1 duplicate
                    self.with_exits += 1;
                    // stand-in for the __exit__ pair the VM keeps under the
                    // body: 3.14 CALL pops [callable, NULL] marker-first, so
                    // model both slots — the exit CALL then finds the
                    // None-const callable the swallow recognizer expects
                    self.push(Rc::new(Expr::Const(Rc::new(PyObject::None))));
                    self.stack.push(Sv::Null);
                    let item = WithItem {
                        ctx: ctx_e,
                        target: None,
                    };
                    let start = self.cur_offset;
                    // the protected body starts after the header and (for
                    // async) the await protocol — protocol-fragment entries
                    // (RESUME..STORE of a NESTED with) must not define the
                    // span; find the first non-protocol instruction
                    let body_at = self
                        .idx_of
                        .get(&start)
                        .and_then(|&si| {
                            self.instrs[si..]
                                .iter()
                                .take(26)
                                .find(|x| {
                                    !matches!(
                                        x.op,
                                        Op::SWAP
                                            | Op::COPY
                                            | Op::LOAD_SPECIAL
                                            | Op::CALL
                                            | Op::GET_AWAITABLE
                                            | Op::SEND
                                            | Op::YIELD_VALUE
                                            | Op::RESUME
                                            | Op::RESUME_CHECK
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            | Op::END_SEND
                                            | Op::CLEANUP_THROW
                                            | Op::LOAD_CONST
                                            | Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::END_ASYNC_FOR
                                    )
                                })
                                .map(|x| x.offset)
                        })
                        .unwrap_or(start);
                    let (frag_key, end0) =
                        match self.with_regions.get(&body_at) {
                            Some(&v) => (body_at, v),
                            None => self
                                .with_regions
                                .iter()
                                .filter(|(k, _)| **k >= body_at)
                                .min_by_key(|(k, _)| *k)
                                .map(|(k, v)| (*k, *v))
                                .unwrap_or((body_at, usize::MAX)),
                        };
                    // nested-try fragment extension (codeop 3.14)
                    let end = self.extend_with_frag_end(frag_key, end0);
                    let mut wb = Block::new(BlockType::With, start, end);
                    wb.is_async = is_async;
                    wb.with_item = Some(item);
                    self.blocks.push(wb);
                    self.push(self.name_expr(WITH_RESULT_PLACEHOLDER));
                    // skip the SWAPs, enter special + CALL, and (async) the
                    // await protocol; stop AT the instruction that consumes
                    // the enter result (STORE as-target / POP_TOP) or at the
                    // body's first instruction
                    if let Some(&si) = self.idx_of.get(&inst.offset) {
                        let mut saw_enter_call = false;
                        let mut skip_to = None;
                        for k in si + 1..self.instrs.len().min(si + 26) {
                            match self.instrs[k].op {
                                Op::END_SEND => {
                                    skip_to = Some(self.instrs[k].end());
                                    break;
                                }
                                Op::CALL if saw_enter_call => {}
                                Op::CALL => saw_enter_call = true,
                                Op::STORE_FAST
                                | Op::STORE_NAME
                                | Op::STORE_DEREF
                                | Op::POP_TOP
                                    if saw_enter_call || !is_async =>
                                {
                                    skip_to = Some(self.instrs[k].offset);
                                    break;
                                }
                                Op::RETURN_VALUE | Op::RETURN_CONST => break,
                                _ => {}
                            }
                        }
                        if let Some(st) = skip_to {
                                                        self.skip_until = Some(st);
                        }
                    }
                    return true;
                }
                let value = self.pop_expr();
                self.push(Rc::new(Expr::Attribute { value, attr }));
                true
            }
            Op::STORE_ATTR => {
                // STORE_ATTR uses the plain name index in all versions
                let idx = arg as usize;
                let attr = self.unmangle(&self.const_name(idx));
                // all CPython versions push value first, owner on top
                let obj = self.pop_expr();
                let val = self.pop_expr();
                let target: ExprRef = Rc::new(Expr::Attribute { value: obj, attr });
                self.emit_store(target, val);
                true
            }
            Op::DELETE_ATTR => {
                let attr = self.unmangle(&self.const_name(arg as usize));
                let obj = self.pop_expr();
                let target: ExprRef = Rc::new(Expr::Attribute { value: obj, attr });
                self.emit_delete(target);
                true
            }

            // ---------- subscripts / slices ----------
            Op::BINARY_SUBSCR => {
                let idx = self.pop_expr();
                let val = self.pop_expr();
                // 3.14 builds extended slices via `slice(...)` calls or
                // marshalled slice constants
                let idx = normalize_slice_call(idx);
                self.push(Rc::new(Expr::Subscript { value: val, index: idx }));
                true
            }
            Op::BINARY_SLICE => {
                let stop = self.pop_expr();
                let start = self.pop_expr();
                let val = self.pop_expr();
                let slice = Rc::new(Expr::Slice(Box::new(SliceExpr {
                    start: none_if_const_none(start),
                    stop: none_if_const_none(stop),
                    step: None,
                })));
                self.push(Rc::new(Expr::Subscript {
                    value: val,
                    index: slice,
                }));
                true
            }
            Op::STORE_SUBSCR => {
                // All versions: obj and sub on top, value below.
                // <=3.10: [value, obj, sub] (sub top); 3.11+: [sub, obj, value]
                let (val, obj, idx) = if self.version.at_least(3, 11) {
                    let idx = self.pop_expr();
                    let obj = self.pop_expr();
                    let val = self.pop_expr();
                    (val, obj, idx)
                } else {
                    let idx = self.pop_expr();
                    let obj = self.pop_expr();
                    let val = self.pop_expr();
                    (val, obj, idx)
                };
                // 3.14 constant-folded `x[:] = v`: the index arrives as
                // a marshalled slice const (or a slice() call) — render
                // the canonical Slice so the recompile folds it back
                // (cProfile 3.14 main `sys.argv[:] = args`)
                let idx = normalize_slice_call(idx);
                let target = Rc::new(Expr::Subscript { value: obj, index: idx });
                self.emit_store(target, val);
                true
            }
            Op::DELETE_SUBSCR => {
                let idx = self.pop_expr();
                let obj = self.pop_expr();
                let target = Rc::new(Expr::Subscript { value: obj, index: idx });
                self.emit_delete(target);
                true
            }
            Op::STORE_SLICE
            | Op::STORE_SLICE_0
            | Op::STORE_SLICE_1
            | Op::STORE_SLICE_2
            | Op::STORE_SLICE_3
            | Op::DELETE_SLICE_0
            | Op::DELETE_SLICE_1
            | Op::DELETE_SLICE_2
            | Op::DELETE_SLICE_3
            | Op::SLICE_0
            | Op::SLICE_1
            | Op::SLICE_2
            | Op::SLICE_3 => {
                self.handle_slice_ops(inst);
                true
            }

            // ---------- unary / binary ----------
            Op::UNARY_NEGATIVE | Op::UNARY_POSITIVE | Op::UNARY_INVERT | Op::UNARY_NOT => {
                let op = match inst.op {
                    Op::UNARY_NEGATIVE => UnaryOp::Neg,
                    Op::UNARY_POSITIVE => UnaryOp::Pos,
                    Op::UNARY_INVERT => UnaryOp::Invert,
                    _ => UnaryOp::Not,
                };
                let e = self.pop_expr();
                self.push(Rc::new(Expr::Unary { op, operand: e }));
                true
            }
            Op::UNARY_CONVERT => {
                let e = self.pop_expr();
                self.push(Rc::new(Expr::Backquote(e)));
                true
            }
            Op::BINARY_OP => {
                match binary_op_name(arg, self.version) {
                    Some(name) => {
                        if name.ends_with('=') {
                            self.apply_inplace(name.trim_end_matches('='), arg);
                        } else {
                            self.apply_binary(name);
                        }
                    }
                    None if self.version.at_least(3, 14) => {
                        // 3.14 folded BINARY_SUBSCR into BINARY_OP 26 (`[]`)
                        let idx = self.pop_expr();
                        let val = self.pop_expr();
                        let idx = normalize_slice_call(idx);
                        self.push(Rc::new(Expr::Subscript { value: val, index: idx }));
                    }
                    None => {
                        self.mark_unclean();
                        self.apply_binary("+");
                    }
                }
                true
            }
            Op::BINARY_ADD
            | Op::BINARY_SUBTRACT
            | Op::BINARY_MULTIPLY
            | Op::BINARY_DIVIDE
            | Op::BINARY_FLOOR_DIVIDE
            | Op::BINARY_MODULO
            | Op::BINARY_POWER
            | Op::BINARY_LSHIFT
            | Op::BINARY_RSHIFT
            | Op::BINARY_OR
            | Op::BINARY_XOR
            | Op::BINARY_AND
            | Op::BINARY_MATRIX_MULTIPLY
            | Op::BINARY_TRUE_DIVIDE => {
                let name = match inst.op {
                    Op::BINARY_ADD => "+",
                    Op::BINARY_SUBTRACT => "-",
                    Op::BINARY_MULTIPLY => "*",
                    Op::BINARY_DIVIDE | Op::BINARY_TRUE_DIVIDE => "/",
                    Op::BINARY_FLOOR_DIVIDE => "//",
                    Op::BINARY_MODULO => "%",
                    Op::BINARY_POWER => "**",
                    Op::BINARY_LSHIFT => "<<",
                    Op::BINARY_RSHIFT => ">>",
                    Op::BINARY_OR => "|",
                    Op::BINARY_XOR => "^",
                    Op::BINARY_AND => "&",
                    Op::BINARY_MATRIX_MULTIPLY => "@",
                    _ => unreachable!(),
                };
                self.apply_binary(name);
                true
            }
            Op::INPLACE_ADD
            | Op::INPLACE_SUBTRACT
            | Op::INPLACE_MULTIPLY
            | Op::INPLACE_DIVIDE
            | Op::INPLACE_FLOOR_DIVIDE
            | Op::INPLACE_MODULO
            | Op::INPLACE_POWER
            | Op::INPLACE_LSHIFT
            | Op::INPLACE_RSHIFT
            | Op::INPLACE_OR
            | Op::INPLACE_XOR
            | Op::INPLACE_AND
            | Op::INPLACE_MATRIX_MULTIPLY
            | Op::INPLACE_TRUE_DIVIDE => {
                let name = match inst.op {
                    Op::INPLACE_ADD => "+",
                    Op::INPLACE_SUBTRACT => "-",
                    Op::INPLACE_MULTIPLY => "*",
                    Op::INPLACE_DIVIDE | Op::INPLACE_TRUE_DIVIDE => "/",
                    Op::INPLACE_FLOOR_DIVIDE => "//",
                    Op::INPLACE_MODULO => "%",
                    Op::INPLACE_POWER => "**",
                    Op::INPLACE_LSHIFT => "<<",
                    Op::INPLACE_RSHIFT => ">>",
                    Op::INPLACE_OR => "|",
                    Op::INPLACE_XOR => "^",
                    Op::INPLACE_AND => "&",
                    Op::INPLACE_MATRIX_MULTIPLY => "@",
                    _ => unreachable!(),
                };
                self.apply_inplace(name, u32::MAX);
                true
            }
            Op::COMPARE_OP => {
                let idx = compare_op_index(arg, self.version);
                let op = cmp_from_index(idx);
                let rhs = self.pop_expr();
                let lhs = self.pop_expr();
                self.push(Rc::new(Expr::Compare {
                    operands: vec![lhs, rhs],
                    ops: vec![op],
                }));
                true
            }
            Op::IS_OP => {
                let rhs = self.pop_expr();
                let lhs = self.pop_expr();
                let op = if arg == 1 { CmpOp::IsNot } else { CmpOp::Is };
                self.push(Rc::new(Expr::Compare {
                    operands: vec![lhs, rhs],
                    ops: vec![op],
                }));
                true
            }
            Op::CONTAINS_OP => {
                let rhs = self.pop_expr();
                let lhs = self.pop_expr();
                let op = if arg == 1 { CmpOp::NotIn } else { CmpOp::In };
                self.push(Rc::new(Expr::Compare {
                    operands: vec![lhs, rhs],
                    ops: vec![op],
                }));
                true
            }
            Op::TO_BOOL => true,

            // ---------- container building ----------
            Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => {
                let items = self.pop_n_exprs(arg as usize);
                // <=3.5 decorators: BUILD_TUPLE wrapping the function object
                if inst.op == Op::BUILD_TUPLE && items.len() == 1 {
                    if let Expr::Function(fd) = &*items[0] {
                        let mut fd = (**fd).clone();
                        fd.decorators.push(self.name_expr("__decorator__"));
                        self.pending_decorators.push(self.name_expr("__decorator__"));
                        self.push(Rc::new(Expr::Function(Rc::new(fd))));
                        return true;
                    }
                }
                let e = match inst.op {
                    Op::BUILD_TUPLE => Expr::Tuple(items),
                    Op::BUILD_LIST => Expr::List(items),
                    _ => Expr::Set(items),
                };
                self.push(Rc::new(e));
                true
            }
            Op::BUILD_MAP => {
                if !self.version.at_least(3, 5) {
                    // py2-3.4: oparg is a size hint only; entries are added
                    // by STORE_MAP from values pushed *below* the dict
                    self.push(Rc::new(Expr::Dict(Vec::new())));
                } else {
                    let n = arg as usize;
                    let flat = self.pop_n_exprs(2 * n);
                    let mut entries = Vec::with_capacity(n);
                    for chunk in flat.chunks(2) {
                        if chunk.len() == 2 {
                            entries.push((chunk[0].clone(), chunk[1].clone()));
                        }
                    }
                    self.push(Rc::new(Expr::Dict(entries)));
                }
                true
            }
            Op::BUILD_CONST_KEY_MAP => {
                let keys_e = self.pop_expr();
                let values = self.pop_n_exprs(arg as usize);
                let keys: Vec<ObjectRef> = match &*keys_e {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(t) => t.clone(),
                        _ => vec![],
                    },
                    _ => vec![],
                };
                let mut entries = Vec::with_capacity(values.len());
                for (i, v) in values.into_iter().enumerate() {
                    let k = keys
                        .get(i)
                        .cloned()
                        .map(|o| Rc::new(Expr::Const(o)) as ExprRef)
                        .unwrap_or_else(|| self.name_expr("/*key?*/"));
                    entries.push((k, v));
                }
                self.push(Rc::new(Expr::Dict(entries)));
                true
            }
            Op::STORE_MAP => {
                // py2: [map, value, key] with key on top
                let key = self.pop_expr();
                let value = self.pop_expr();
                let map = self.pop_expr();
                let mut entries = match &*map {
                    Expr::Dict(d) => d.clone(),
                    _ => Vec::new(),
                };
                entries.push((key, value));
                self.push(Rc::new(Expr::Dict(entries)));
                true
            }
            Op::BUILD_STRING => {
                let parts_e = self.pop_n_exprs(arg as usize);
                let mut out_parts = Vec::new();
                for p in parts_e {
                    match &*p {
                        Expr::Const(o) => match &**o {
                            PyObject::Str(s) => {
                                out_parts.push(FStringPart::Literal(s.clone()))
                            }
                            _ => out_parts.push(FStringPart::Value {
                                value: p.clone(),
                                conversion: None,
                                format_spec: None,
                            }),
                        },
                        Expr::FString(fs) => out_parts.extend(fs.parts.iter().cloned()),
                        _ => out_parts.push(FStringPart::Value {
                            value: p.clone(),
                            conversion: None,
                            format_spec: None,
                        }),
                    }
                }
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: out_parts,
                }))));
                true
            }
            Op::BUILD_SLICE => {
                let (start, stop, step) = if arg == 3 {
                    let step = none_if_const_none(self.pop_expr());
                    let stop = none_if_const_none(self.pop_expr());
                    let start = none_if_const_none(self.pop_expr());
                    (start, stop, step)
                } else {
                    let stop = none_if_const_none(self.pop_expr());
                    let start = none_if_const_none(self.pop_expr());
                    (start, stop, None)
                };
                self.push(Rc::new(Expr::Slice(Box::new(SliceExpr {
                    start,
                    stop,
                    step,
                }))));
                true
            }
            Op::LIST_EXTEND | Op::SET_UPDATE | Op::DICT_UPDATE | Op::LIST_APPEND
            | Op::SET_ADD | Op::MAP_ADD | Op::LIST_TO_TUPLE | Op::DICT_MERGE
            | Op::COPY_DICT_WITHOUT_KEYS => {
                if self.inline_comp.is_some()
                    && matches!(inst.op, Op::LIST_APPEND | Op::SET_ADD | Op::MAP_ADD)
                {
                    self.comp_add_element(inst);
                } else {
                    self.handle_collection_op(inst, arg);
                }
                true
            }
            Op::BUILD_LIST_UNPACK
            | Op::BUILD_TUPLE_UNPACK
            | Op::BUILD_SET_UNPACK
            | Op::BUILD_MAP_UNPACK
            | Op::BUILD_MAP_UNPACK_WITH_CALL
            | Op::BUILD_TUPLE_UNPACK_WITH_CALL => {
                // 3.5: BUILD_MAP_UNPACK_WITH_CALL packs a with-call flag
                // into the high byte (258 = 2 dicts | 0x100); the count is
                // always the low byte. When set, the following
                // CALL_FUNCTION_KW 0 consumes the merged dict as **kwargs.
                let count = (arg & 0xFF) as usize;
                if inst.op == Op::BUILD_MAP_UNPACK_WITH_CALL && arg & 0x100 != 0 {
                    self.pending_star_kw_call = true;
                }
                let items = self.pop_n_exprs(count);
                let for_call = matches!(
                    inst.op,
                    Op::BUILD_TUPLE_UNPACK | Op::BUILD_TUPLE_UNPACK_WITH_CALL
                );
                let mut out: Vec<ExprRef> = Vec::new();
                for it in items {
                    if for_call {
                        // call-argument groups: plain tuples contribute their
                        // items positionally, everything else is *starred
                        match &*it {
                            Expr::Tuple(inner) => out.extend(inner.iter().cloned()),
                            other => {
                                out.push(Rc::new(Expr::Starred(Rc::new(other.clone()))))
                            }
                        }
                    } else {
                        out.push(Rc::new(Expr::Starred(it)));
                    }
                }
                let e = match inst.op {
                    Op::BUILD_LIST_UNPACK => Expr::List(out),
                    Op::BUILD_SET_UNPACK => Expr::Set(out),
                    // 3.5-3.8 `{**a, **b}` / call kwargs: a dict display
                    // with starred merge entries
                    Op::BUILD_MAP_UNPACK | Op::BUILD_MAP_UNPACK_WITH_CALL => {
                        Expr::Dict(
                            out.iter()
                                .map(|s| (s.clone(), self.name_expr("")))
                                .collect(),
                        )
                    }
                    _ => Expr::Tuple(out),
                };
                self.push(Rc::new(e));
                true
            }
            Op::UNPACK_SEQUENCE => {
                // pops the iterable and pushes N items (bottom->top order)
                let value = self.pop_expr();
                let n = arg as usize;
                self.unpack_frames.push((n, n, None, value.clone()));
                self.unpack_targets.0.push(Vec::new());
                self.unpack_target_lines.push(Vec::new());
                for _ in 0..n {
                    self.stack.push(Sv::E(value.clone()));
                }
                true
            }
            Op::UNPACK_EX => {
                let before = (arg & 0xFF) as usize;
                let after = ((arg >> 8) & 0xFF) as usize;
                let value = self.pop_expr();
                let n = before + after + 1;
                self.unpack_frames.push((n, n, Some(before), value.clone()));
                self.unpack_targets.0.push(Vec::new());
                self.unpack_target_lines.push(Vec::new());
                for _ in 0..n {
                    self.stack.push(Sv::E(value.clone()));
                }
                true
            }

            // ---------- stack manipulation ----------
            Op::POP_TOP => {
                if self.try_fold_sunk_for_break() {
                    return true;
                }
                self.handle_pop_top();
                true
            }
            Op::ROT_TWO => {
                // 3.11+ `with ...: return expr` whose With block already
                // closed at its region end: the tail lifts the value over
                // the unmodeled exit callable and returns it — fold into
                // the just-emitted With statement (see SWAP arm)
                if self.try_fold_late_with_return(&inst) {
                    return true;
                }
                let n = self.stack.len();
                if n >= 2 {
                    self.stack.swap(n - 1, n - 2);
                }
                true
            }
            Op::ROT_THREE => {
                let n = self.stack.len();
                if n >= 3 {
                    let v = self.stack.remove(n - 1);
                    self.stack.insert(n - 3, v);
                }
                true
            }
            Op::ROT_FOUR => {
                let n = self.stack.len();
                if n >= 4 {
                    let v = self.stack.remove(n - 1);
                    self.stack.insert(n - 4, v);
                }
                true
            }
            Op::ROT_N => {
                let n = arg as usize;
                let len = self.stack.len();
                if len >= n && n > 1 {
                    let v = self.stack.remove(len - 1);
                    self.stack.insert(len - n, v);
                }
                true
            }
            Op::SWAP => {
                // 3.11+ `with ...: return expr`: SWAP 2 lifts the return
                // value over the unmodeled __exit__ callable, then
                // LOAD None x3; CALL; POP_TOP; RETURN_VALUE follow. The
                // With block already closed at its exception-table region
                // end, so fold the return into the just-emitted With
                // statement and skip the protocol + handler (without
                // this, the CALL renders `None(None, None)` garbage and
                // the handler glue an `if not None: pass`).
                if (arg == 2 || arg == 3)
                    && self.try_fold_late_with_return(&inst)
                {
                    return true;
                }
                let i = arg as usize;
                let len = self.stack.len();
                if len >= i && i > 0 {
                    self.stack.swap(len - 1, len - i);
                }
                true
            }
            Op::DUP_TOP => {
                if self.try_parse_match() {
                    return true;
                }
                if let Some(sv) = self.stack.last().cloned() {
                    self.stack.push(sv);
                } else if self
                    .idx_of
                    .get(&inst.offset)
                    .map_or(false, |&ci| {
                        // the match pattern can span several pure value
                        // loads (`except struct.error:` / `except (A, B):`),
                        // so scan forward for the COMPARE_OP instead of
                        // pinning ci+2
                        let mut k = ci + 1;
                        for _ in 0..8 {
                            let Some(x) = self.instrs.get(k) else {
                                return false;
                            };
                            if x.op == Op::CACHE {
                                k += 1;
                                continue;
                            }
                            if x.op == Op::COMPARE_OP {
                                return cmp_from_index(compare_op_index(
                                    x.arg as u32,
                                    self.version,
                                )) == CmpOp::ExceptionMatch;
                            }
                            if !matches!(
                                x.op,
                                Op::LOAD_FAST
                                    | Op::LOAD_GLOBAL
                                    | Op::LOAD_NAME
                                    | Op::LOAD_ATTR
                                    | Op::LOAD_CONST
                                    | Op::LOAD_DEREF
                                    | Op::BUILD_TUPLE
                            ) {
                                return false;
                            }
                            k += 1;
                        }
                        false
                    })
                {
                    // handler-entry DUP_TOP over the exception value, which
                    // we do not model: supply a placeholder so the match
                    // comparison pops two operands
                    let ph = self.name_expr("/*exc*/");
                    // py2 `except E, n`: the implicit-as store right after
                    // the prelude pops binds the exception value — inside a
                    // skipped-chain sub-walk (where the store is rendered as
                    // an assignment, not captured as the clause name) give
                    // it a real binding: sys.exc_info()[1], buried under a
                    // tb placeholder the first prelude POP_TOP consumes.
                    // ONLY when this handler really binds (PJIF followed by
                    // POP_TOP + STORE): a bare `except E:` handler pops all
                    // three slots and the placeholder never renders — the
                    // eager flag injected a phantom `import sys` at the top
                    // of the enclosing function (audiodev 2.7 AudioDev)
                    let binds_exc = self
                        .idx_of
                        .get(&inst.offset)
                        .map_or(false, |&ci| {
                            self.instrs[ci + 1..]
                                .iter()
                                .take(10)
                                .enumerate()
                                .find(|(_, x)| {
                                    matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE | Op::JUMP_IF_FALSE
                                    )
                                })
                                .map_or(false, |(k, _)| {
                                    // k is 0-based over ci+1..: the cond
                                    // jump sits at ci+1+k. The implicit-as
                                    // STORE follows the prelude pops: 2.7
                                    // is POP_TOP; STORE; POP_TOP, 2.6 is
                                    // POP_TOP; POP_TOP; STORE; POP_TOP —
                                    // skip up to three POP_TOPs
                                    self.instrs[ci + 2 + k..]
                                        .iter()
                                        .take(4)
                                        .skip_while(|x| x.op == Op::POP_TOP)
                                        .next()
                                        .map_or(false, |x| {
                                            matches!(
                                                x.op,
                                                Op::STORE_FAST | Op::STORE_NAME
                                            )
                                        })
                                })
                        });
                    if self.version.major == 2
                        && self.legacy_nest_depth > 0
                        && binds_exc
                    {
                        self.used_exc_info = true;
                        self.push(Rc::new(Expr::Subscript {
                            value: Rc::new(Expr::Call {
                                func: Rc::new(Expr::Attribute {
                                    value: self.name_expr("sys"),
                                    attr: "exc_info".to_string(),
                                }),
                                args: vec![],
                                keywords: vec![],
                                star_args: None,
                                star_kwargs: None,
                            }),
                            index: Rc::new(Expr::Const(Rc::new(PyObject::Int(1)))),
                        }));
                        self.push(ph.clone());
                    }
                    self.push(ph);
                }
                true
            }
            Op::DUP_TOP_TWO => {
                let n = self.stack.len();
                if n >= 2 {
                    let a = self.stack[n - 2].clone();
                    let b = self.stack[n - 1].clone();
                    self.stack.push(a);
                    self.stack.push(b);
                }
                true
            }
            Op::DUP_TOPX => {
                let n = arg as usize;
                let len = self.stack.len();
                if len >= n && n > 0 {
                    let dup: Vec<Sv> = self.stack[len - n..].to_vec();
                    self.stack.extend(dup);
                }
                true
            }
            Op::COPY => {
                if arg == 1 && self.try_parse_match() {
                    return true;
                }
                let n = arg as usize;
                let len = self.stack.len();
                if len >= n && n > 0 {
                    let v = self.stack[len - n].clone();
                    self.stack.push(v);
                }
                true
            }
            Op::PUSH_NULL => {
                self.stack.push(Sv::Null);
                true
            }

            // ---------- calls ----------
            Op::CALL_FUNCTION => {
                self.call_function_py(arg as usize, None, false);
                true
            }
            Op::CALL_FUNCTION_VAR => {
                self.call_function_py2_var(arg as usize);
                true
            }
            Op::CALL_FUNCTION_KW => {
                if self.pending_star_kw_call {
                    // 3.5 `f(**a, **b)`: BUILD_MAP_UNPACK_WITH_CALL left
                    // the merged dict on top; this call's arg is 0
                    self.pending_star_kw_call = false;
                    let kw = self.pop_expr();
                    let func = self.pop_expr();
                    let (kws, star_kw) = flatten_ex_kwargs(kw);
                    self.push(Rc::new(Expr::Call {
                        func,
                        args: Vec::new(),
                        keywords: kws,
                        star_args: None,
                        star_kwargs: star_kw,
                    }));
                    return true;
                }
                if self.version.at_least(3, 6) {
                    let names = self.pop_expr();
                    self.call_function_py(arg as usize, Some(names), false);
                } else {
                    // py2/3.0-3.5: the **kwargs dict rides on top
                    self.call_function_py2_kw(arg as usize);
                }
                true
            }
            Op::CALL_FUNCTION_VAR_KW => {
                self.call_function_py2_varkw(arg as usize);
                true
            }
            Op::CALL_METHOD => {
                // 3.7-3.10 method call: [meth, self_or_null, args...]
                self.call_function_py(arg as usize, None, true);
                true
            }
            Op::CALL => {
                self.call_311(arg as usize, false);
                true
            }
            Op::CALL_KW => {
                let names_e = self.pop_expr();
                let names: Vec<Option<String>> = match &*names_e {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(items) => items
                            .iter()
                            .map(|it| match &**it {
                                PyObject::Str(s) => Some(s.clone()),
                                _ => None,
                            })
                            .collect(),
                        _ => Vec::new(),
                    },
                    _ => Vec::new(),
                };
                self.call_311(arg as usize, false);
                // retrofit kw names onto the produced call: the names tuple
                // covers the TRAILING k values (like KW_NAMES), the leading
                // total-k values are positional
                if let Some(Sv::E(e)) = self.stack.last_mut() {
                    if let Expr::Call { args, keywords, .. } = Rc::make_mut(e) {
                        let total = args.len() + keywords.len();
                        let named: Vec<Option<String>> = names.clone();
                        if !named.is_empty() && named.len() <= total {
                            let pos_count = total - named.len();
                            let all_vals: Vec<ExprRef> = args
                                .drain(..)
                                .chain(keywords.drain(..).map(|(_, v)| v))
                                .collect();
                            let new_args: Vec<ExprRef> =
                                all_vals.iter().take(pos_count).cloned().collect();
                            let new_kws: Vec<(Option<String>, ExprRef)> = named
                                .into_iter()
                                .zip(all_vals.into_iter().skip(pos_count))
                                .collect();
                            *args = new_args;
                            *keywords = new_kws;
                        }
                    }
                }
                true
            }
            Op::CALL_FUNCTION_EX => {
                // Stack layouts (bottom..top):
                // * <=3.10: [callable, args(, kwargs)] — oparg bit 0 = kwargs
                // * 3.11/3.12: [NULL_or_self, callable, args(, kwargs)]
                // * 3.13: [callable, NULL_or_self, args(, kwargs)] — oparg
                //   bit 0 still selects the kwargs slot
                // * 3.14: oparg removed; a kwargs slot is ALWAYS present on
                //   top: [callable, NULL_or_self, args, kwargs_dict_or_NULL]
                // pop_expr skips NULL markers, so popping callable after
                // args consumes the 3.13+/3.14 self slot automatically.
                let kwargs_opt: Option<ExprRef> = if self.version.at_least(3, 14) {
                    match self.stack.pop() {
                        Some(Sv::E(e)) => Some(e),
                        Some(Sv::Null) => None,
                        other => {
                            if let Some(o) = other {
                                self.stack.push(o);
                            }
                            self.mark_unclean();
                            None
                        }
                    }
                } else if arg & 1 != 0 {
                    Some(self.pop_expr())
                } else {
                    None
                };
                let args = self.pop_expr();
                let func = self.pop_expr();
                if self.version.at_least(3, 11) && !self.version.at_least(3, 13) {
                    // 3.11/3.12: the self/NULL slot sits BELOW the callable
                    if matches!(self.stack.last(), Some(Sv::Null)) {
                        self.stack.pop();
                    }
                }
                let (pos, star) = flatten_ex_args(args);
                let merge_built = self
                    .idx_of
                    .get(&self.cur_offset)
                    .and_then(|&ci| {
                        (ci > 0).then(|| self.instrs[ci - 1].op)
                    })
                    .map_or(false, |o| o == Op::DICT_MERGE);
                let (ex_kws, star_kw) = if let Some(kw) = kwargs_opt {
                    let (k, s) = flatten_ex_kwargs(kw.clone());
                    // a DICT_MERGE-built kwargs dict with const keys
                    // plus ONE trailing star is the compiler's own
                    // layout for `f(kw=..., **x)` — decompose it back
                    // (the whole-dict rendering recompiles to
                    // BUILD_MAP + DICT_UPDATE and breaks sig-exactness;
                    // configparser 3.12 _get_conv). A DICT_UPDATE-built
                    // literal must stay whole: its recompile reproduces
                    // BUILD_MAP + DICT_UPDATE exactly
                    let decomposed: Option<(
                        Vec<(Option<String>, ExprRef)>,
                        Option<ExprRef>,
                    )> = 'dc: {
                        if !merge_built || !k.is_empty() || s.is_none() {
                            break 'dc None;
                        }
                        if let Expr::Dict(entries) = &*kw {
                            if entries.len() >= 2
                                && matches!(
                                    &*entries[entries.len() - 1].0,
                                    Expr::Starred(_)
                                )
                                && entries[..entries.len() - 1].iter().all(
                                    |(kk, _)| {
                                        matches!(&**kk, Expr::Const(o)
                                            if matches!(&**o, PyObject::Str(_)))
                                    },
                                )
                            {
                                let mut kws = Vec::new();
                                for (kk, v) in &entries[..entries.len() - 1] {
                                    if let Expr::Const(o) = &**kk {
                                        if let PyObject::Str(name) = &**o {
                                            kws.push((
                                                Some(name.clone()),
                                                v.clone(),
                                            ));
                                        }
                                    }
                                }
                                if let Expr::Starred(inner) =
                                    &*entries[entries.len() - 1].0
                                {
                                    break 'dc Some((kws, Some(inner.clone())));
                                }
                            }
                        }
                        None
                    };
                    decomposed.unwrap_or((k, s))
                } else {
                    (Vec::new(), None)
                };
                self.push(Rc::new(Expr::Call {
                    func,
                    args: pos,
                    keywords: ex_kws,
                    star_args: star,
                    star_kwargs: star_kw,
                }));
                true
            }
            Op::KW_NAMES => {
                let keys_e = self.const_expr(arg as usize);
                self.last_kw_names = match &*keys_e {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(items) => items
                            .iter()
                            .map(|it| match &**it {
                                PyObject::Str(s) => Some(s.clone()),
                                _ => None,
                            })
                            .collect(),
                        _ => Vec::new(),
                    },
                    _ => Vec::new(),
                };
                true
            }

            // ---------- functions / classes ----------
            Op::MAKE_FUNCTION | Op::MAKE_CLOSURE => {
                self.make_function(inst, arg);
                true
            }
            Op::SET_FUNCTION_ATTRIBUTE => {
                self.set_function_attribute_313(arg);
                true
            }
            Op::BUILD_CLASS => {
                // py2 stack bottom..top: [name, bases_tuple, namespace_dict]
                // (the namespace is the CALL_FUNCTION result of the class
                // body function); the result is stored by the next STORE_NAME
                let methods = self.pop_expr();
                let bases = self.pop_expr();
                let name = self.pop_expr();
                self.pending_py2_class = Some((name, bases, methods));
                self.push(self.name_expr("/*class-object*/"));
                true
            }

            // ---------- imports ----------
            Op::IMPORT_NAME => {
                let fromlist = self.pop_expr();
                let level_e = self.pop_expr();
                let level = match &*level_e {
                    Expr::Const(o) => o.as_int().unwrap_or(0).max(0) as u32,
                    _ => 0,
                };
                let module = self.const_name(arg as usize);
                let fromlist = match &*fromlist {
                    Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                    other => Some(Rc::new(other.clone()) as ExprRef),
                };
                self.stack.push(Sv::ImportModule {
                    level,
                    module,
                    fromlist,
                });
                true
            }
            Op::IMPORT_FROM => {
                let name = self.const_name(arg as usize);
                // 3.12+: IMPORT_FROM may copy from TOS (the module); the
                // module marker stays below.
                if let Some(Sv::ImportModule { level, module, .. }) = self.stack.last() {
                    let (level, module) = (*level, module.clone());
                    self.stack.push(Sv::ImportFrom {
                        level,
                        module,
                        name: name.clone(),
                    });
                } else {
                    self.mark_unclean();
                    self.push(self.name_expr(name));
                }
                true
            }
            Op::IMPORT_STAR => {
                if let Some(Sv::ImportModule { level, module, .. }) = self.pop() {
                    self.push_stmt(Stmt::ImportFrom {
                        module,
                        level,
                        names: vec![("*".to_string(), None)],
                    });
                } else {
                    self.mark_unclean();
                }
                true
            }

            // ---------- returns / yields ----------
            Op::RETURN_VALUE => {
                // 3.11+ sunk arm-tail copy: an inline `LOAD None;
                // RETURN` whose next real instruction is the arm's own
                // out-of-line handler (PUSH_EXC_INFO), AND whose handler
                // chain ALWAYS re-raises (a bare `except: ...; raise` —
                // its last non-machinery op is RERAISE 0). That shape is
                // the implicit function tail duplicated into an arm that
                // ends in an always-raising try: the source had NO
                // `return` there, and the arm TERMINATES (it never falls
                // through to the code past the handler). Rendering the
                // spurious `return` left the arm flattened, so the
                // recompile relocated the tail past the handler and
                // shifted the arm's exit jump (aifc 3.11 Aifc.__init__).
                //
                // The always-raises gate is what separates this from an
                // EXPLICIT `return` inside a try body whose handler does
                // not always raise (b26_tailtry.skip `try: x+=1; return;
                // except OSError: pass`): that return must be folded back
                // into the try body, which the emit_return narrowed-tail
                // recovery below already does — so we must NOT swallow it
                // here. Both shapes are locally identical (LOAD None;
                // RETURN; PUSH_EXC_INFO); only the chain's terminator
                // differs.
                if self.version.at_least(3, 11)
                    && matches!(
                        self.stack.last(),
                        Some(Sv::E(e))
                            if matches!(&**e, Expr::Const(o)
                                if matches!(&**o, PyObject::None))
                    )
                {
                    let next_real = self
                        .idx_of
                        .get(&self.cur_offset)
                        .and_then(|&ri| {
                            let mut k = ri + 1;
                            while matches!(
                                self.instrs.get(k).map(|x| x.op),
                                Some(Op::NOP)
                                    | Some(Op::NOT_TAKEN)
                                    | Some(Op::CACHE)
                            ) {
                                k += 1;
                            }
                            self.instrs.get(k)
                        });
                    if matches!(
                        next_real.map(|x| x.op),
                        Some(Op::PUSH_EXC_INFO)
                    ) {
                        let h = next_real.map(|x| x.offset).unwrap_or(0);
                        let ext = self.chain_extent(h);
                        let chain_always_raises = self
                            .instrs
                            .iter()
                            .rev()
                            .find(|x| {
                                x.offset >= h
                                    && x.offset < ext
                                    && !matches!(
                                        x.op,
                                        Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::CACHE
                                            | Op::COPY
                                            | Op::SWAP
                                            | Op::POP_EXCEPT
                                            | Op::RERAISE
                                    )
                            })
                            .map_or(false, |x| {
                                x.op == Op::RAISE_VARARGS && x.arg == 0
                            });
                        if chain_always_raises {
                            self.pop();
                            // record the terminated arm so the If close
                            // rebuilds the else arm at the PJFF target
                            // instead of flattening it into a sibling (a
                            // flattened arm recompiles to an arm-end
                            // JUMP_FORWARD over the continuation, not the
                            // original's per-arm sunk tail return).
                            self.sunk_return_fold_at =
                                Some(self.cur_offset);
                            return true;
                        }
                    }
                }
                // 3.9/3.10 exits without CALL_FINALLY: the compiler
                // duplicates the finally body inline right before each
                // `return` inside the try. The copy ran as real statements
                // in the open arm while the genuine finally also renders
                // from the handler region — the output duplicates the
                // cleanup (codeop 3.9 _maybe_compile). When the innermost
                // block's statement tail mirrors the copy region at the
                // open Try's handler exactly, drop the copy AND this
                // return: rendering the bare `return` lets the compiler
                // regenerate the copy, and the post-try tail flow supplies
                // the function's own tail return.
                // drop the inline finally copy's statements; the return
                // itself still renders (its recompile regenerates the copy)
                self.swallow_inline_finally_return();
                // a deferred-fold handler (3.9 POP_EXCEPT-first) ends here:
                // the return belongs to its body, so emit first, fold after
                let defer_fold = self
                    .legacy_handler
                    .as_ref()
                    .map_or(false, |h| h.pop_seen);
                // the return sits inside a block opened WITHIN the handler
                // (`except E as e: if cond: return v` — the POP_BLOCK/
                // POP_EXCEPT/cleanup prefix unwinds the nested wrappers
                // for the escape): it belongs to that block's arm. Folding
                // now force-closes the block with an empty arm (`pass`)
                // and strands the return at handler level (crypt
                // _add_method) — leave the handler open; the chain-end
                // RERAISE folds it after the block closes naturally.
                let inner_open = self
                    .legacy_handler
                    .as_ref()
                    .map_or(false, |h| self.blocks.len() > h.block_depth);
                let defer_fold = defer_fold && !inner_open;
                if defer_fold {
                    self.close_handler_blocks();
                }
                let e = self.pop_expr();
                // 3.8-3.10 `break`-to-final-return sinking: when a
                // loop's break flows straight into the function's
                // terminating return, the compiler duplicates the
                // return run into the break's landing pad (the cond
                // jump skips the copy; the copy is [pads] value-loads
                // RETURN, untargeted). Render Break instead of the
                // Return — the mirror renders from the post-loop flow
                // (_compression 3.10 seek: `if not data: break`
                // rendered as a mid-loop `return self._pos`).
                if self.legacy_handler.is_none() && self.legacy_try.is_none() {
                    if let Some(&ri) = self.idx_of.get(&self.cur_offset) {
                        let mut j = ri;
                        while j > 0 {
                            let p = &self.instrs[j - 1];
                            if matches!(p.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)
                                || is_pure_value_op(p.op)
                            {
                                j -= 1;
                                continue;
                            }
                            break;
                        }
                        // the walk stops with instrs[j-1] as the first
                        // non-pad/non-value instruction before RETURN
                        if j == 0 {
                            j = 1;
                        }
                        // a sunk break copy keeps the NOP line marker of
                        // the elided break jump between the cond jump
                        // and the value loads; a GENUINE mid-loop
                        // `if c: return X` whose value happens to mirror
                        // the tail return has NO NOP there (binhex 3.9
                        // read: `if self.eof: return decdata` + the
                        // function's own `return decdata` tail). Strict
                        // NOP + pre-3.11: the sinking era is 3.8-3.10,
                        // and 3.14 puts NOT_TAKEN after EVERY forward
                        // cond jump, so pads there are not markers
                        // (_markupbase 3.14 six genuine `return -1`s
                        // folded to break)
                        let pad_after_j = self.version.at_least(3, 8)
                            && !self.version.at_least(3, 11)
                            && matches!(
                                self.instrs.get(j).map(|x| x.op),
                                Some(Op::NOP)
                            );
                        let jins = &self.instrs[j - 1];
                        let is_fwd_cj = matches!(
                            jins.op,
                            Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_IF_TRUE
                        ) && !jins.is_backward;
                        if let (true, Some(t)) = (is_fwd_cj, jins.target) {
                            let lb = self.blocks.iter().rev().find(|b| {
                                matches!(b.kind, BlockType::While | BlockType::For)
                            });
                            let if_top_ok = matches!(
                                self.blocks.last().map(|b| (b.kind == BlockType::If, b.end)),
                                Some((true, te)) if te == t
                            );
                            if if_top_ok
                                && t > jins.offset
                                && lb.map_or(false, |b| t < b.end && b.start < jins.offset)
                            {
                                // the copy region must be untargeted
                                // (only the cond jump skips over it)
                                let j_off = jins.offset;
                                let cur_off = self.cur_offset;
                                let untargeted = !self.instrs.iter().any(|x| {
                                    x.target.map_or(false, |tt| {
                                        tt > j_off && tt <= cur_off
                                    })
                                });
                                // the loop exit must run straight into
                                // a tail return whose value-op run
                                // mirrors the copy's (same (op, arg)
                                // sequence with pads stripped)
                                let copy_run: Vec<(Op, Option<usize>)> = self.instrs[j..ri]
                                    .iter()
                                    .filter(|x| {
                                        !matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)
                                    })
                                    .map(|x| (x.op, x.target))
                                    .collect();
                                let exit_off = lb.and_then(|b| self.loop_exit_offset(b));
                                let mirrored = exit_off
                                    .and_then(|ex| self.idx_of.get(&ex).copied())
                                    .map_or(false, |ei| {
                                        let mut tail_run: Vec<(Op, Option<usize>)> =
                                            Vec::new();
                                        let mut k = ei;
                                        while k < self.instrs.len()
                                            && tail_run.len() <= copy_run.len()
                                        {
                                            let x = &self.instrs[k];
                                            if matches!(
                                                x.op,
                                                Op::RETURN_VALUE | Op::RETURN_CONST
                                            ) {
                                                return !tail_run.is_empty()
                                                    && tail_run == copy_run;
                                            }
                                            if matches!(
                                                x.op,
                                                Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                            ) {
                                                k += 1;
                                                continue;
                                            }
                                            if !is_pure_value_op(x.op) {
                                                return false;
                                            }
                                            tail_run.push((x.op, x.target));
                                            k += 1;
                                        }
                                        false
                                    });
                                if untargeted && mirrored && pad_after_j {
                                    if let Some(top) = self.blocks.last_mut() {
                                        top.stmts.push(Stmt::Break);
                                    }
                                    self.skip_until = Some(t);
                                    return true;
                                }
                            }
                        }
                        // while-True fully-sunk tail return (codecs
                        // readline family, 3.8+): every `break` of a
                        // `while True:` carries a `[NOP] LOAD v; RETURN`
                        // copy of the source's post-loop `return v` — no
                        // physical tail return exists past the loop's
                        // back edge. The NOP is the elided break jump's
                        // target pad (a genuine in-loop return has no
                        // NOP and no sibling mirrors). Render Break per
                        // copy; the lifted post-loop return emits when
                        // the loop closes.
                        if std::env::var("PYCDC_SWL_DBG").is_ok() {
                            eprintln!(
                                "SWL ret@{} j={} jop={:?} ver={} lift={}",
                                self.cur_offset,
                                self.instrs.get(j).map(|x| x.offset).unwrap_or(999999),
                                self.instrs.get(j).map(|x| x.op),
                                self.version.at_least(3, 8),
                                self.sunk_while_lift.is_some()
                            );
                        }
                        if self.version.at_least(3, 8)
                            && matches!(
                                self.instrs.get(j).map(|x| x.op),
                                Some(Op::NOP)
                            )
                        {
                            let is_pad2 = |x: &crate::bytecode::Instruction| {
                                matches!(
                                    x.op,
                                    Op::NOP
                                        | Op::NOT_TAKEN
                                        | Op::CACHE
                                        | Op::EXTENDED_ARG
                                )
                            };
                            let norm2 = |x: &crate::bytecode::Instruction| {
                                (x.op as u8, x.arg)
                            };
                            let run: Vec<(u8, u32)> = self.instrs[j..=ri]
                                .iter()
                                .filter(|x| !is_pad2(x))
                                .map(norm2)
                                .collect();
                            let loads_only = !run.is_empty()
                                && self.instrs[j..ri]
                                    .iter()
                                    .filter(|x| !is_pad2(x))
                                    .all(|x| {
                                        matches!(
                                            x.op,
                                            Op::LOAD_FAST
                                                | Op::LOAD_NAME
                                                | Op::LOAD_GLOBAL
                                                | Op::LOAD_DEREF
                                                | Op::LOAD_CONST
                                                | Op::LOAD_ATTR
                                                | Op::LOAD_METHOD
                                                | Op::LOAD_FAST_LOAD_FAST
                                                | Op::LOAD_FAST_BORROW
                                                | Op::LOAD_SMALL_INT
                                        )
                                    });
                            if loads_only {
                                let lb = self
                                    .blocks
                                    .iter()
                                    .rev()
                                    .find(|b| {
                                        matches!(b.kind, BlockType::While)
                                    });
                                let span = lb.and_then(|b| {
                                    self.while_true_loops
                                        .iter()
                                        .find(|(t, _)| *t == b.start)
                                        .copied()
                                });
                                if std::env::var("PYCDC_SWL_DBG").is_ok() {
                                    eprintln!("SWL lb={:?} span={:?}", lb.map(|b| (b.start, b.end)), span);
                                }
                                if let (Some(lb), Some((wtop, wend))) =
                                    (lb, span)
                                {
                                    if lb.start < self.cur_offset
                                        && self.cur_offset < wend
                                    {
                                        // every return in the loop span
                                        // mirrors this run (>=2 copies)
                                        let mut count = 0usize;
                                        let mut all_ok = true;
                                        for x in self.instrs.iter() {
                                            if x.offset < wtop
                                                || x.offset >= wend
                                            {
                                                continue;
                                            }
                                            if !matches!(
                                                x.op,
                                                Op::RETURN_VALUE
                                                    | Op::RETURN_CONST
                                            ) {
                                                continue;
                                            }
                                            count += 1;
                                            let Some(&xi) =
                                                self.idx_of.get(&x.offset)
                                            else {
                                                all_ok = false;
                                                break;
                                            };
                                            let mut b2 = xi;
                                            let mut h2 = 0;
                                            while b2 > 0 && h2 < 8 {
                                                let p = &self.instrs[b2 - 1];
                                                if is_pad2(p)
                                                    || matches!(
                                                        p.op,
                                                        Op::LOAD_FAST
                                                            | Op::LOAD_NAME
                                                            | Op::LOAD_GLOBAL
                                                            | Op::LOAD_DEREF
                                                            | Op::LOAD_CONST
                                                            | Op::LOAD_ATTR
                                                            | Op::LOAD_METHOD
                                                            | Op::LOAD_FAST_LOAD_FAST
                                                            | Op::LOAD_FAST_BORROW
                                                            | Op::LOAD_SMALL_INT
                                                    )
                                                {
                                                    b2 -= 1;
                                                    h2 += 1;
                                                    continue;
                                                }
                                                break;
                                            }
                                            let r2: Vec<(u8, u32)> =
                                                self.instrs[b2..=xi]
                                                    .iter()
                                                    .filter(|x2| !is_pad2(x2))
                                                    .map(norm2)
                                                    .collect();
                                            if r2 != run {
                                                all_ok = false;
                                                break;
                                            }
                                        }
                                        // past the loop: only pads (no
                                        // physical tail return)
                                        let tail_pad = self
                                            .instrs
                                            .iter()
                                            .filter(|x| x.offset >= wend)
                                            .all(is_pad2);
                                        if std::env::var("PYCDC_SWL_DBG").is_ok() {
                                            eprintln!("SWL span wtop={} wend={} count={} all_ok={} tail_pad={}", wtop, wend, count, all_ok, tail_pad);
                                        }
                                        if all_ok
                                            && count >= 2
                                            && tail_pad
                                        {
                                            if let Some(top) =
                                                self.blocks.last_mut()
                                            {
                                                top.stmts.push(Stmt::Break);
                                            }
                                            if self.sunk_while_lift.is_none()
                                            {
                                                self.sunk_while_lift =
                                                    Some((wtop, e.clone()));
                                            }
                                            return true;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                // 3.9/3.10 computed `try: return expr finally:` — no
                // CALL_FINALLY marker; the inline finally copy ran into
                // the open Finally block and this RETURN lands on top of
                // it with the body slot still empty: fold it back as the
                // body's return (cProfile 3.9/3.10 runcall rendered
                // `try: pass finally: ...` + stray return). A real
                // `finally: ...; return v` keeps its body statements, so
                // the empty-body gate makes the read unambiguous.
                let is_val_return =
                    !matches!(&*e, Expr::Const(o) if matches!(&**o, PyObject::None));
                if !self.version.at_least(3, 11)
                    && self.legacy_handler.is_none()
                    && matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Finally))
                    && self.pending_try_body.last().map_or(false, |b| b.is_empty())
                    && is_val_return
                {
                    if let Some(body) = self.pending_try_body.last_mut() {
                        body.push(Stmt::Return(Some(e)));
                    }
                    return !matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::Main)
                    );
                }
                // 3.9/3.10 legacy inline-finally path: the chain carries
                // the finally as its "else" region and the body slot is
                // still empty (the value rode the stack) — fold this
                // return into lt.body and let the chain's flush render
                // `try: return expr finally: ...` (cProfile 3.9/3.10
                // runcall). A real `finally: ...; return v` would have
                // non-empty body statements, so the gate is unambiguous.
                // the copy's trailing stores may still sit in
                // pending_stores (this RETURN is their flush trigger):
                // land them while the else-region routing is live so
                // they collect into finalbody, not Main (a STORE-tail
                // copy `finally: self.q = True` otherwise leaked to
                // top level and the flushed Try lost its finally)
                if !self.version.at_least(3, 11)
                    && is_val_return
                    && !self.pending_stores.is_empty()
                    && self.legacy_try.as_ref().map_or(false, |l| {
                        l.has_finally
                            && l.else_start
                                .map_or(false, |es| self.cur_offset >= es)
                    })
                {
                    self.flushing = true;
                    self.flush_pending_stores();
                    self.flushing = false;
                }
                // stashed inner except chain (3.9/3.10 double
                // SETUP_FINALLY `try: return X / except E: ... /
                // finally: F`): its handler region sits between this
                // return and the outer finally handler and the linear
                // walk never reaches it — parse and wrap it around the
                // folded return (mirror of the 3.8 CALL_FINALLY fold
                // fix; bdb 3.9/3.10 runeval lost `except BdbQuit`)
                let stashed_exc = if self.legacy_nest.is_empty() {
                    None
                } else {
                    let ni = self.legacy_nest.len() - 1;
                    self.legacy_nest[ni]
                        .outer_try
                        .as_ref()
                        .filter(|inner| {
                            inner.handlers.is_empty()
                                && !inner.chain_done
                                && inner.handler_start > self.cur_offset
                                && self
                                    .legacy_try
                                    .as_ref()
                                    .map_or(false, |l| {
                                        inner.handler_start < l.handler_start
                                    })
                                && self.chain_has_exc_dispatch(inner.handler_start)
                        })
                        .map(|_| ni)
                };
                if !self.version.at_least(3, 11)
                    && is_val_return
                    && (self.legacy_nest.is_empty() || stashed_exc.is_some())
                    // the value must have ridden the stack UNDER the
                    // inline finally copies (computed inside the
                    // protected body): the instruction right before this
                    // RETURN is the copy's trailing POP_TOP or a
                    // statement-final STORE (a `self.q = True` copy —
                    // bdb 3.9 runeval, t_tef39 g5). A value LOADed right
                    // before the RETURN is the nested-try shared tail
                    // (3.9 computes it after BOTH copies — b15
                    // ret_both_nested) and belongs to the existing flat
                    // rendering
                    && self
                        .idx_of
                        .get(&self.cur_offset)
                        .and_then(|&ri| {
                            (ri > 0).then(|| self.instrs[ri - 1].op)
                        })
                        .map_or(false, |p| {
                            p == Op::POP_TOP
                                || matches!(
                                    p,
                                    Op::STORE_ATTR
                                        | Op::STORE_FAST
                                        | Op::STORE_NAME
                                        | Op::STORE_DEREF
                                        | Op::STORE_GLOBAL
                                        | Op::STORE_SUBSCR
                                )
                        })
                    // OUTERMOST chain only: an enclosing Try/Finally
                    // block still open means this return belongs to a
                    // NESTED try/finally (b15 ret_both_nested: folding
                    // the inner return and ending the walk dropped the
                    // outer finally order)
                    && matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main))
                    && self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            l.has_finally
                                && l.handlers.is_empty()
                                && l.body.is_empty()
                                && l.orelse.is_empty()
                                && l.else_start
                                    .map_or(false, |es| self.cur_offset >= es)
                                // an except dispatch still unparsed in
                                // the chain means this is a try/except
                                // (/finally) — folding here would end
                                // the walk before its clauses parse
                                // (bdb 3.8 runeval lost `except BdbQuit`)
                                && !self.chain_has_exc_dispatch(l.handler_start)
                        })
                {
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.body.push(Stmt::Return(Some(e)));
                    }
                    if let Some(ni) = stashed_exc {
                        let inner =
                            self.legacy_nest[ni].outer_try.take().unwrap();
                        let hs = inner.handler_start;
                        let mut outer = self.legacy_try.take().unwrap();
                        self.legacy_try = Some(inner);
                        // clamp the sub-walk at the chain's own mismatch
                        // terminator (RERAISE/END_FINALLY) before the
                        // outer finally handler: past it lie the except
                        // path's inline copy and bridge, which the
                        // handler region [hs, outer_hs) covers
                        let outer_hs = outer.handler_start;
                        let chain_end = self
                            .idx_of
                            .get(&hs)
                            .and_then(|&hi| {
                                self.instrs[hi..]
                                    .iter()
                                    .take(200)
                                    .take_while(|x| x.offset < outer_hs)
                                    .find(|x| {
                                        matches!(
                                            x.op,
                                            Op::END_FINALLY | Op::RERAISE
                                        )
                                    })
                                    .map(|x| x.offset)
                            })
                            .unwrap_or(outer_hs);
                        self.parse_skipped_nested_chain(chain_end);
                        if let Some(mut inner) = self.legacy_try.take() {
                            if !inner.handlers.is_empty() {
                                // the folded return belongs to the INNER
                                // body; the collected inline copy is the
                                // OUTER finally; the chain's own else
                                // span is dead (covered by the copy)
                                inner.body.extend(std::mem::take(
                                    &mut outer.body,
                                ));
                                outer.body = vec![Stmt::Try {
                                    body: inner.body,
                                    handlers: std::mem::take(
                                        &mut inner.handlers,
                                    ),
                                    orelse: std::mem::take(
                                        &mut inner.orelse,
                                    ),
                                    finalbody: Vec::new(),
                                }];
                                outer.orelse.clear();
                                outer.else_start = None;
                                self.legacy_try = Some(outer);
                                // drop the consumed husk: the teardown
                                // nest-loop would otherwise TAKE the
                                // wrapped chain and drop it (a
                                // finally-chain has no handlers of its
                                // own to pass the push gate)
                                if self
                                    .legacy_nest
                                    .get(ni)
                                    .map_or(false, |n| n.outer_try.is_none())
                                {
                                    self.legacy_nest.remove(ni);
                                }
                            } else {
                                // nothing parsed: restore both unchanged
                                self.legacy_try = Some(outer);
                                self.legacy_nest[ni].outer_try = Some(inner);
                            }
                        } else {
                            self.legacy_try = Some(outer);
                        }
                        self.legacy_handler = None;
                        self.legacy_handler_end = None;
                    }
                    // flow ends at this return; the run() teardown
                    // flushes the chain into its Try statement
                    return false;
                }
                // handler-side copy of the sunk 3.10 tail terminator:
                // drop the return, fold the handler without it. Pre-3.10
                // (and any shape without the success-side copy) the drop
                // requires the mirror: a `LOAD None; RETURN` pair
                // immediately before the handler head — without it this
                // RETURN is a genuine source-level `return` (3.8/3.9
                // _collections_abc Sequence.__iter__ `except IndexError:
                // return` rendered `pass`, compiling the clause to
                // JF-to-tail instead of the in-handler RETURN)
                let handler_sunk = defer_fold
                    && matches!(&*e, Expr::Const(o) if matches!(&**o, PyObject::None))
                    && (self.version.at_least(3, 10)
                        || self.has_pre_handler_return_mirror())
                    // a handler-side sunk copy of the tail return only
                    // EXISTS when the try is tail-positioned (past the
                    // chain terminus lies nothing but the implicit tail
                    // return) — or when an enclosing loop is open (the
                    // sunk-BREAK landing conversion below, which runs
                    // its own tail_only validation). Otherwise this is
                    // a GENUINE source-level `except: return`: dropping
                    // it emptied asynchat 3.10 handle_read's clauses to
                    // `pass`, which also disabled retract_escaping_else
                    // (no clause ended in a Return anymore) and wrapped
                    // the whole post-try flow into a phantom else arm
                    && {
                        let loop_open = self
                            .blocks
                            .iter()
                            .any(|b| {
                                matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                )
                            });
                        // tail position: past the chain's extent lies
                        // nothing but chain-cleanup vocabulary, pads
                        // and the implicit tail return (complete()'s
                        // extent lands PAST its final RERAISE, at the
                        // code end — idx_of resolves that to the
                        // RERAISE index, so the stub ops must be
                        // admitted here; do_help's chain is followed
                        // by the enclosing body's POP_BLOCK)
                        let tail_pos = match self.legacy_try.as_ref() {
                            Some(l) => {
                                let ext = self.chain_extent(l.handler_start);
                                self.idx_of.get(&ext).map_or(true, |&ei| {
                                    self.instrs[ei..].iter().all(|x| {
                                        matches!(
                                            x.op,
                                            Op::NOP
                                                | Op::NOT_TAKEN
                                                | Op::CACHE
                                                | Op::EXTENDED_ARG
                                                | Op::LOAD_CONST
                                                | Op::RETURN_VALUE
                                                | Op::RETURN_CONST
                                                | Op::RERAISE
                                                | Op::END_FINALLY
                                                | Op::POP_BLOCK
                                                | Op::POP_EXCEPT
                                                | Op::POP_TOP
                                                | Op::COPY
                                                | Op::SWAP
                                        )
                                    })
                                })
                            }
                            None => true,
                        };
                        // the chain sits inside an outer finally's
                        // inline-copy region (a stashed outer
                        // has_finally chain, or the active chain's own
                        // copy region): the "post-chain flow" is the
                        // copy's next branch, not mainline code — the
                        // clause None-return there is the branch's sunk
                        // tail copy (cmd 3.10 cmdloop `finally: {if A:
                        // if B: try/except ImportError: pass}`)
                        let in_finally_copy = self
                            .legacy_nest
                            .iter()
                            .any(|n| {
                                n.outer_try
                                    .as_ref()
                                    .map_or(false, |o| o.has_finally)
                            })
                            || self.legacy_try.as_ref().map_or(false, |l| {
                                l.has_finally
                                    && l.else_start.map_or(false, |es| {
                                        self.cur_offset >= es
                                    })
                            });
                        loop_open || tail_pos || in_finally_copy
                    }
                    && {
                        let mut m = match self.idx_of.get(&self.cur_offset) {
                            Some(&i) => i + 1,
                            None => 0,
                        };
                        while matches!(
                            self.instrs.get(m).map(|x| x.op),
                            Some(Op::NOP) | Some(Op::CACHE) | Some(Op::NOT_TAKEN)
                        ) {
                            m += 1;
                        }
                        matches!(
                            self.instrs.get(m).map(|x| x.op),
                            Some(Op::RERAISE) | Some(Op::END_FINALLY) | None
                        ) || self
                            .legacy_handler_end
                            .map_or(false, |he| {
                                self.instrs.get(m).map_or(false, |x| x.offset >= he)
                            })
                    };
                if !handler_sunk {
                    self.emit_return(Some(e));
                } else {
                    // a return-none sunk into a handler whose enclosing
                    // loop exits at the function tail is a sunk BREAK
                    // landing, not the tail terminator's handler copy:
                    // `while 1: try: ... except E: break` compiles the
                    // break to LOAD None; RETURN_VALUE inside the clause
                    // (3.10 _sitebuiltins _Printer.__call__ rendered
                    // `pass`, losing the loop exit). Convert only when
                    // the loop-exit-to-code-end region holds nothing but
                    // the implicit tail return.
                    if let Some(li) = self
                        .blocks
                        .iter()
                        .rposition(|b| matches!(b.kind, BlockType::While | BlockType::For))
                    {
                        let exit_opt = self
                            .loop_exit_offset(&self.blocks[li])
                            .or_else(|| {
                                (self.blocks[li].end != usize::MAX)
                                    .then(|| self.blocks[li].end)
                            });
                        let tail_only = exit_opt.map_or(false, |ex| {
                            let mut saw_return = false;
                            let mut saw_any = false;
                            let mut only = true;
                            for x in self.instrs.iter() {
                                if x.offset < ex {
                                    continue;
                                }
                                saw_any = true;
                                match x.op {
                                    Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::CACHE
                                    | Op::EXTENDED_ARG => {}
                                    Op::LOAD_CONST => {
                                        if !matches!(
                                            self.code.consts.get(x.arg as usize).map(|o| &**o),
                                            Some(PyObject::None)
                                        ) {
                                            only = false;
                                            break;
                                        }
                                    }
                                    Op::RETURN_VALUE | Op::RETURN_CONST => {
                                        saw_return = true;
                                    }
                                    _ => {
                                        only = false;
                                        break;
                                    }
                                }
                            }
                            // an empty region means the loop exits at the
                            // code end (an infinite `while 1:`) — the sunk
                            // handler return IS the tail landing
                            only && (saw_return || !saw_any)
                        });
                        if tail_only {
                            if let Some(h) = self.legacy_handler.as_mut() {
                                h.body.push(Stmt::Break);
                            }
                        }
                    }
                }
                if defer_fold {
                    self.flush_pending_stores();
                    if let Some(h) = self.legacy_handler.take() {
                        if let Some(he) = &h.name {
                            if let Expr::Name(n) = &**he {
                                self.pending_as_cleanup = Some(n.clone());
                            }
                        }
                        if let Some(l) = self.legacy_try.as_mut() {
                            l.handlers.push(ExceptHandler {
                                type_: h.type_,
                                name: h.name,
                                body: h.body,
                                is_star: false,
                            });
                        }
                    }
                    self.legacy_handler_end = None;
                }
                // at function top level a RETURN ends the meaningful stream;
                // trailing bytes are exception-table cleanup paths — unless
                // a pre-3.11 handler chain still needs to run, an open
                // 3.12 chained-comparison link still needs its else-arm
                // fold, or a pending skip marks a real continuation past
                // the chain (the try-body return flush hopped the chain
                // to the post-try mainline: copy 3.12 _deepcopy_tuple's
                // for loop lives past the handler chain)
                !matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main))
                    || self.legacy_try.is_some()
                    || self.skip_until.is_some()
                    || self.blocks.iter().any(|b| b.chain_link)
            }
            Op::YIELD_VALUE => {
                if self.await_mode {
                    // await expr: stack [coro, sent]; consume both
                    self.await_mode = false;
                    self.skip_end_send = true;
                    self.pop(); // sent value
                    // the with-exit recognizer swallowed the async-with
                    // __aexit__ call, so nothing awaitable is left — the
                    // whole protocol is desugaring residue; drop it
                    // without underflowing the value stack
                    if self.with_exit_await_drop
                        || !self.stack.iter().any(|sv| matches!(sv, Sv::E(_)))
                    {
                        self.with_exit_await_drop = false;
                        return true;
                    }
                    let coro = self.pop_expr();
                    match &*coro {
                        // async with: awaiting __aenter__/__aexit__ results
                        Expr::Name(n)
                            if n == WITH_RESULT_PLACEHOLDER || n.contains("underflow") =>
                        {
                            if n == WITH_RESULT_PLACEHOLDER {
                                self.push(coro);
                            }
                        }
                        // the __aexit__ call of an async with was swallowed
                        // by the with-exit recognizer, so the awaited value
                        // underflows to Const(None) — `await None` is never
                        // real code; drop the whole protocol value
                        Expr::Const(o) if matches!(&**o, PyObject::None) => {}
                        _ => self.push(Rc::new(Expr::Await(coro))),
                    }
                    return true;
                }
                let e = self.pop_expr();
                if self.code.is_coroutine() || self.code.is_async_generator() {
                    // inside async functions a bare yield keeps its form
                    self.push(Rc::new(Expr::Yield(Some(e))));
                } else if arg == 1 && self.version.at_least(3, 14) {
                    self.push_stmt(Stmt::Expr(Rc::new(Expr::Yield(Some(e)))));
                } else {
                    self.push(Rc::new(Expr::Yield(Some(e))));
                }
                true
            }
            Op::YIELD_FROM => {
                // stack: [iterable, sent_value]; the sent value is on top
                self.pop();
                if self.await_mode
                    && (self.with_exit_await_drop
                        || !self.stack.iter().any(|sv| matches!(sv, Sv::E(_))))
                {
                    // swallowed async-with __aexit__ call (or a 3.8
                    // WITH_CLEANUP_START whose awaited result was never
                    // modeled): desugaring residue, drop it cleanly —
                    // a real `await x` always has x on the stack
                    self.await_mode = false;
                    self.with_exit_await_drop = false;
                    self.pop();
                    return true;
                }
                let e = self.pop_expr();
                self.await_mode = false;
                // async with: the awaited value is the __aenter__ result
                // placeholder — keep it bare for the `as` store
                let is_placeholder = matches!(&*e, Expr::Name(n) if n == WITH_RESULT_PLACEHOLDER);
                if !is_placeholder && (self.code.is_coroutine() || self.code.is_async_generator())
                {
                    self.push(Rc::new(Expr::Await(e)));
                } else if is_placeholder {
                    self.push(e);
                } else {
                    self.push(Rc::new(Expr::YieldFrom(e)));
                }
                true
            }
            Op::SEND => true,
            Op::END_SEND => {
                if self.skip_end_send {
                    self.skip_end_send = false;
                } else {
                    self.pop();
                }
                true
            }
            Op::RETURN_GENERATOR => {
                // generator expression: the code object is the last code
                // constant referenced by a preceding LOAD_CONST
                let code_const = self
                    .recent_code_const
                    .clone();
                self.pending_gen_code = code_const;
                self.push(self.name_expr("/*generator*/"));
                true
            }
            Op::GET_AWAITABLE => {
                // value-preserving; materializes as `await` at the next
                // YIELD_VALUE (3.11+) or YIELD_FROM (<=3.10)
                self.await_mode = true;
                true
            }
            Op::GET_YIELD_FROM_ITER if self.version.at_least(3, 11) => {
                // 3.11+ delegation (`yield from`) / await protocol:
                //   GET_YIELD_FROM_ITER; LOAD sent; SEND loop; END_SEND
                // Emit the whole protocol as one YieldFrom/Await value or
                // statement and skip the resume machinery. (<=3.10 uses
                // the YIELD_FROM opcode and stays a plain no-op here.)
                let it = self.pop_expr();
                let is_placeholder =
                    matches!(&*it, Expr::Name(n) if n == WITH_RESULT_PLACEHOLDER);
                let expr = if is_placeholder {
                    it
                } else if self.code.is_coroutine() && !self.code.is_async_generator()
                {
                    Rc::new(Expr::Await(it))
                } else {
                    Rc::new(Expr::YieldFrom(it))
                };
                if let Some(&si) = self.idx_of.get(&inst.offset) {
                    let mut end_send = None;
                    let mut tail_pop = None;
                    let mut send_target = None;
                    let mut prev = inst.op;
                    for k in si + 1..self.instrs.len().min(si + 40) {
                        let nx = &self.instrs[k];
                        if nx.op == Op::SEND && send_target.is_none() {
                            send_target = nx.target;
                        }
                        if nx.op == Op::END_SEND {
                            end_send = Some(k);
                            break;
                        }
                        // 3.11 has no END_SEND: the protocol ends with the
                        // POP_TOP right after the resume loop
                        if nx.op == Op::POP_TOP
                            && matches!(
                                prev,
                                Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::SEND
                                    | Op::RESUME
                                    | Op::YIELD_VALUE
                            )
                        {
                            tail_pop = Some(k);
                            break;
                        }
                        if matches!(nx.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                            break;
                        }
                        prev = nx.op;
                    }
                    if let Some(ei) = end_send {
                        let after_pop = self
                            .instrs
                            .get(ei + 1)
                            .filter(|a| a.op == Op::POP_TOP)
                            .map(|a| a.end());
                        let end_send_end = self.instrs[ei].end();
                        if let Some(pop_end) = after_pop {
                            self.push_stmt(Stmt::Expr(expr));
                                                        self.skip_until = Some(pop_end);
                        } else {
                            self.push(expr);
                                                        self.skip_until = Some(end_send_end);
                        }
                        return true;
                    }
                    if let Some(pi) = tail_pop {
                        let pop_end = self.instrs[pi].end();
                        self.push_stmt(Stmt::Expr(expr));
                                                self.skip_until = Some(pop_end);
                        return true;
                    }
                    // value form without END_SEND (3.11): the SEND's jump
                    // target is where the delegated value lands
                    if let Some(st) = send_target {
                        self.push(expr);
                                                self.skip_until = Some(st);
                        return true;
                    }
                }
                self.push(expr);
                true
            }
            // <=3.10: the YIELD_FROM opcode arm models the delegation
            Op::GET_ANEXT if !self.version.at_least(3, 11) => {
                // <=3.10 async-for:
                //   SETUP_FINALLY(->END_ASYNC_FOR); GET_ANEXT; LOAD None;
                //   YIELD_FROM; POP_BLOCK; STORE target; body;
                //   JUMP_ABSOLUTE -> SETUP_FINALLY; END_ASYNC_FOR
                // The back edge targets the SETUP_FINALLY, so the block
                // starts there; skip the anext-await protocol up to the
                // target store.
                let iter = self.pop_expr();
                let mut skip_to = None;
                if let Some(&ai) = self.idx_of.get(&inst.offset) {
                    for k in ai + 1..self.instrs.len().min(ai + 8) {
                        match self.instrs[k].op {
                            Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF => {
                                skip_to = Some(self.instrs[k].offset);
                                break;
                            }
                            Op::YIELD_FROM | Op::POP_BLOCK | Op::LOAD_CONST => {}
                            _ => break,
                        }
                    }
                }
                // 3.5-3.7: the SETUP_EXCEPT guard recognition already opened
                // the async For block (the back edge targets the setup) —
                // just attach the iterator
                // 3.6: GET_AITER's result arrives awaited (`GET_AITER;
                // LOAD None; YIELD_FROM` before the guard) — unwrap so the
                // header renders the plain iterable
                let iter = match &*iter {
                    Expr::Await(inner) => inner.clone(),
                    _ => iter,
                };
                let joined = matches!(
                    self.blocks.last(),
                    Some(b) if b.is_async
                        && matches!(b.kind, BlockType::For)
                        && b.iter.is_none()
                );
                if joined {
                    if let Some(top) = self.blocks.last_mut() {
                        top.iter = Some(iter.clone());
                        top.cond_end = inst.end();
                    }
                } else {
                    let mut start = inst.offset;
                    if let Some(&ai) = self.idx_of.get(&inst.offset) {
                        if ai > 0 && self.instrs[ai - 1].op == Op::SETUP_FINALLY {
                            start = self.instrs[ai - 1].offset;
                        }
                    }
                    let mut exit = usize::MAX;
                    if let Some(&ai) = self.idx_of.get(&inst.offset) {
                        for ins in self.instrs.iter().skip(ai + 1) {
                            if ins.op == Op::END_ASYNC_FOR {
                                exit = ins.offset;
                                break;
                            }
                        }
                    }
                    let mut fb = Block::new(BlockType::For, start, exit);
                    fb.cond_end = inst.end();
                    fb.iter = Some(iter.clone());
                    fb.is_async = true;
                    fb.cond_set = true;
                    self.blocks.push(fb);
                }
                self.awaiting_for_target = true;
                self.push(iter);
                if let Some(st) = skip_to {
                                        self.skip_until = Some(st);
                }
                true
            }
            Op::GET_ANEXT => {
                // 3.10+ async-for loop top:
                //   GET_ANEXT; LOAD sent; SEND L; YIELD_VALUE; RESUME;
                //   JUMP_BACKWARD_NO_INTERRUPT; L: END_SEND; STORE target
                // Open the async For block and skip the resume protocol;
                // the back edge (JUMP_BACKWARD to this offset) closes the
                // loop and skips the CLEANUP_THROW/END_ASYNC_FOR tail.
                let iter = self.pop_expr();
                let mut proto_end = None;
                if let Some(&ai) = self.idx_of.get(&inst.offset) {
                    for k in ai + 1..self.instrs.len().min(ai + 12) {
                        match self.instrs[k].op {
                            Op::END_SEND => {
                                proto_end = Some(self.instrs[k].end());
                                break;
                            }
                            Op::STORE_FAST
                            | Op::STORE_NAME
                            | Op::STORE_DEREF
                            | Op::YIELD_FROM => break,
                            _ => {}
                        }
                    }
                }
                // like FOR_ITER: keep the iterator on the stack so the
                // loop-target STORE pops it (awaiting_for_target reroutes
                // it into the block header) instead of underflowing. With
                // the protocol skipped the STORE is the very next executed
                // instruction; without a skip (3.11 has no END_SEND) the
                // resume ops run inline and would leak a second value.
                if proto_end.is_some() {
                    self.push(iter.clone());
                }
                let mut exit = usize::MAX;
                if let Some(&ai) = self.idx_of.get(&inst.offset) {
                    for ins in self.instrs.iter().skip(ai + 1) {
                        if ins.op == Op::END_ASYNC_FOR {
                            exit = ins.offset;
                            break;
                        }
                    }
                }
                let mut fb = Block::new(BlockType::For, inst.offset, exit);
                fb.cond_end = inst.end();
                fb.iter = Some(iter);
                fb.is_async = true;
                fb.cond_set = true;
                self.blocks.push(fb);
                self.awaiting_for_target = true;
                if let Some(pe) = proto_end {
                                        self.skip_until = Some(pe);
                }
                true
            }
            Op::GET_ITER | Op::GET_YIELD_FROM_ITER | Op::GET_AITER => true,
            Op::END_ASYNC_FOR => {
                self.pop();
                true
            }
            Op::END_FOR => {
                if let Some(end) = self.inline_comp.as_ref().map(|c| c.end) {
                    // pop the exhausted iterator; on 3.14 a following
                    // POP_ITER does it instead
                    // 3.14 uses POP_ITER, 3.13 uses POP_TOP after END_FOR
                    // to remove the exhausted iterator
                    let popiter_follows = self
                        .instrs
                        .iter()
                        .find(|i| i.start >= inst.end())
                        .map(|i| matches!(i.op, Op::POP_ITER | Op::POP_TOP))
                        .unwrap_or(false);
                    if !popiter_follows {
                        // the VM keeps the iterator under the result list
                        // until END_FOR pops it
                        self.pop();
                    }
                    if inst.offset < end {
                        return true; // inner loop cleanup
                    }
                    self.finish_inline_comp();
                    return true;
                }
                self.pop();
                if self.version.at_most(3, 12) {
                    self.pop();
                }
                true
            }
            Op::POP_ITER => {
                // pops the exhausted iterator left by FOR_ITER (3.14+)
                self.pop();
                true
            }

            // ---------- control flow ----------
            Op::JUMP_FORWARD => {
                let target = inst.target.unwrap_or(inst.end());
                if self.is_dead_forward_glue() {
                    return true;
                }
                if !self.version.at_least(3, 11)
                    && target > self.cur_offset
                    && self.legacy_split_finally_rebuild(target)
                {
                    return true;
                }
                // 3.12+ split finally: this is the exit path's jump out
                // of the inlined finally copy — fold the deferred try
                // here (position-based closing never reaches it under
                // the body's open If). The If's then-region (the copy)
                // is rebuilt from spans — discard it.
                if self
                    .pending_try_ctx
                    .as_ref()
                    .map_or(false, |tc| tc.split_body2.is_some())
                {
                    while matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::If)
                    ) {
                        self.blocks.pop();
                    }
                    let tc = self.pending_try_ctx.take().unwrap();
                    self.emit_try_tail(tc, inst.offset);
                    return true;
                }
                let over_handlers = self
                    .legacy_try
                    .as_ref()
                    .map_or(false, |l| target > l.handler_start);
                // a forward jump flying over an enclosing loop's
                // exhaustion exit to a continuation no other jump
                // targets is a `break` over a while/for-else region —
                // record the else end so find_loop_exit can see it
                // (mirrors the JUMP_ABSOLUTE registration)
                if !over_handlers && target > self.cur_offset {
                    self.register_break_over_else(target);
                }
                // 3.9/3.10 `try: with ...; break except E: pass`: the
                // body-tail break is a JUMP_FORWARD to the loop exit that
                // flies over the (still unparsed) handler chain — the
                // over_handlers guard below would drop it and the chain
                // machinery would misread the flow. Emitting Break here
                // routes it into lt.body (push_stmt's chain-collection
                // redirect); the walk then continues linearly into the
                // chain head (_sitebuiltins 3.10 __setup lost the break
                // and grew a phantom handler `continue`).
                let body_tail_break = over_handlers
                    && self.legacy_handler.is_none()
                    && self.legacy_nest.is_empty()
                    && self.legacy_try.as_ref().map_or(false, |l| {
                        l.handlers.is_empty()
                            && l.else_start.is_none()
                            && self.cur_offset < l.handler_start
                    })
                    && self.find_loop_exit(target).is_some();
                if body_tail_break {
                    self.push_stmt(Stmt::Break);
                    return true;
                }
                if !over_handlers && self.find_loop_exit(target).is_some() {
                    // degenerate `if c: break`: this jump IS the whole
                    // body of the just-opened If — close ONLY that block
                    // (it renders `if c: break`). Enclosing branch
                    // blocks continue past it: their then arms resume at
                    // the next instruction, and closing them here drops
                    // the rest of the arm out of the branch
                    // (3.11 _compression.read's `if eof:` arm).
                    let degenerate = matches!(
                        self.blocks.last().map(|b| (b.kind, b.end)),
                        Some((BlockType::If, end)) if end == self.cur_next
                    );
                    self.push_stmt(Stmt::Break);
                    if degenerate {
                        let pos = self.blocks.last().map(|b| b.start).unwrap_or(0);
                        self.force_close_top(pos);
                    } else {
                        self.close_inner_blocks_to_loop();
                    }
                }
                // 3.10 inner handler-arm break (`except E: if c: break
                // else: raise` — bz2 decompress): the break IS this
                // forward jump to the loop exit, with no dead glue
                // after it. Push the Break into the open guard arm and
                // close the arm blocks only down to the handler depth —
                // a full close_inner_blocks_to_loop would let the
                // handle_jump_forward below mark the else arm's tiny
                // [raise] region as stretching to the loop exit and
                // swallow the whole continuation (while/return sank
                // into a phantom else). Mirrors the JUMP_ABSOLUTE arm's
                // over_handlers-guarded break push.
                if over_handlers
                    && self.legacy_handler.is_some()
                    && self.find_loop_exit(target).is_some()
                    && self.blocks.iter().any(|b| {
                        matches!(b.kind, BlockType::While | BlockType::For)
                    })
                {
                    self.push_stmt(Stmt::Break);
                    let depth = self
                        .legacy_handler
                        .as_ref()
                        .map(|h| h.block_depth)
                        .unwrap_or(1);
                    while self.blocks.len() > depth.max(1) {
                        let p = self.blocks.last().map(|b| b.start).unwrap_or(target);
                        self.force_close_top(p);
                    }
                    return true;
                }
                let r = self.handle_jump_forward(target);
                // <=3.10 with normal exit: the jump flies over the whole
                // exception-time cleanup handler (the SETUP_WITH /
                // SETUP_ASYNC_WITH target) — only reachable through an
                // exception, never walk it
                if target > self.cur_next
                    && self.with_handler_starts.contains(&self.cur_next)
                {
                                        self.skip_until = Some(target);
                    return r;
                }
                // With no branch block open and the jumped-over region a
                // PURE VALUE arm, the region is unreachable dead code
                // (e.g. the vestigial else arm of a constant-folded
                // ternary: `LOAD 3.5; JUMP_FORWARD; LOAD 0`) — skip it so
                // it cannot pollute the value stack. Statement regions
                // (loop-else bodies after a break, if/else arms) are never
                // pure-value and keep the normal walk.
                if !over_handlers
                    && target > self.cur_offset
                    && self.find_loop_exit(target).is_none()
                    && matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main))
                    && self.is_pure_value_region(self.cur_next, target)
                {
                                        self.skip_until = Some(target);
                }
                // 3.5-3.7 async-for: the per-iteration JUMP_FORWARD flies
                // over the StopAsyncIteration guard handler into the loop
                // body — skip exactly that machinery region
                if self.skip_until.is_none()
                    && self.async_for_guard.map_or(false, |(h, _, _)| {
                        h == self.cur_next && target > h
                    })
                {
                                        self.skip_until = Some(target);
                }
                r
            }
            Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::CONTINUE_LOOP => {
                if self.is_dead_forward_glue() {
                    return true;
                }
                // 3.9 break-in-try/finally exits via a FORWARD
                // JUMP_ABSOLUTE past the handler copy
                if !self.version.at_least(3, 11)
                    && inst.target.map_or(false, |t| t > inst.offset)
                {
                    if let Some(t) = inst.target {
                        if self.legacy_split_finally_rebuild(t) {
                            return true;
                        }
                    }
                }
                let target = inst.target.unwrap_or(0);
                if let Some(comp) = &self.inline_comp {
                    if comp.for_iter_offsets.contains(&target) {
                        return true; // comprehension loop back edge
                    }
                }
                // a dead duplicate back edge right after a continue's own
                // back jump (unoptimized 3.x compilers emit the pair;
                // nothing targets the duplicate): the first edge already
                // served the continue, and with no block open above the
                // loop this one would be consumed as the loop's CLOSING
                // back edge — tearing the loop down mid-body and orphaning
                // the rest of the iteration (copyreg 3.8 _slotnames:
                // `if name in (...): continue` + dead JABS, the elif chain
                // fell out of the for). Must run before the
                // lands/is-continue gate: both are false at the duplicate.
                if inst.is_backward
                    && matches!(
                        inst.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                            | Op::JUMP
                    )
                {
                    // a loop-exit trampoline targeted ONLY by its
                    // SETUP_LOOP (no `break` ever flies to it) is dead
                    // too: reachable just by fall-through past the
                    // previous back edge (copyreg 3.3 _slotnames: the
                    // 237/240 JABS 68 pair — 240 is the inner loop's
                    // SETUP_LOOP target; executing it pushed a spurious
                    // Continue into the outer for body)
                    if self
                        .instrs
                        .iter()
                        .filter(|i| i.target == Some(inst.offset))
                        .all(|i| i.op == Op::SETUP_LOOP)
                    {
                    if let Some(&ci) = self.idx_of.get(&inst.offset) {
                        if ci > 0 {
                            let prev = &self.instrs[ci - 1];
                            if prev.is_backward
                                && matches!(
                                    prev.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        | Op::JUMP
                                )
                                && prev.target == inst.target
                            {
                                // 3.8+ `if c1: continue elif c2: ...`:
                                // no dead else-skip JUMP_FORWARD follows
                                // the continue edge (3.6 emitted one),
                                // so the elif chain starts right at the
                                // next instruction. Mirror the
                                // dead_after_continue re-open: pop the
                                // just-closed continue-If back off and
                                // run the chain as its Else region,
                                // bounded by the enclosing loop's end
                                // (every chain arm exits through a back
                                // edge; there is no earlier merge).
                                let reopen = self
                                    .blocks
                                    .last()
                                    .map_or(false, |b| {
                                        matches!(
                                            b.stmts.last(),
                                            Some(Stmt::If { orelse, body, .. })
                                                if orelse.is_empty()
                                                    && matches!(
                                                        body.last(),
                                                        Some(Stmt::Continue)
                                                    )
                                        )
                                    })
                                    && self.instrs[ci + 1..]
                                        .iter()
                                        .take(24)
                                        .try_fold(false, |found, nx| {
                                            if found {
                                                return Some(true);
                                            }
                                            if matches!(
                                                nx.op,
                                                Op::POP_JUMP_IF_FALSE
                                                    | Op::POP_JUMP_IF_TRUE
                                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                                    | Op::JUMP_IF_FALSE_OR_POP
                                                    | Op::JUMP_IF_TRUE_OR_POP
                                            ) {
                                                return Some(true);
                                            }
                                            // an elif chain starts with its
                                            // condition's value loads; a
                                            // backward jump / terminator
                                            // first means no chain follows
                                            if nx.target.is_some()
                                                || matches!(
                                                    nx.op,
                                                    Op::RETURN_VALUE
                                                        | Op::RETURN_CONST
                                                        | Op::RAISE_VARARGS
                                                        | Op::POP_BLOCK
                                                )
                                            {
                                                return None;
                                            }
                                            Some(false)
                                        })
                                        .unwrap_or(false);
                                if reopen {
                                    let loop_end = self
                                        .blocks
                                        .iter()
                                        .rev()
                                        .find(|b| {
                                            matches!(
                                                b.kind,
                                                BlockType::While | BlockType::For
                                            )
                                        })
                                        .map(|b| b.end);
                                    if let Some(top) = self.blocks.last_mut() {
                                        if let Some(Stmt::If { cond, body, .. }) =
                                            top.stmts.pop()
                                        {
                                            let else_start = self.cur_next;
                                            self.pending_then.push(body);
                                            let mut else_blk = Block::new(
                                                BlockType::Else,
                                                else_start,
                                                loop_end.unwrap_or(usize::MAX),
                                            );
                                            else_blk.cond = Some(cond);
                                            else_blk.is_elif = true;
                                            // pre-mark the chain spine so
                                            // arm-end back edges inside
                                            // the region take the jfold
                                            // folded path (line_ok) and
                                            // rebuild the chain's else
                                            // arms instead of the
                                            // is_continue dispatch, which
                                            // pushes a spurious Continue
                                            // and tears the whole spine
                                            // down via
                                            // close_inner_blocks_to_loop
                                            // (copyreg 3.8 _slotnames)
                                            else_blk.folded_exit = true;
                                            self.blocks.push(else_blk);
                                        }
                                    }
                                }
                                return true;
                            }
                        }
                    }
                    }
                }
                // <=3.9: `break` is JUMP_ABSOLUTE to the loop exit — but a
                // folded chain exit (jump inside an open If/Else region at
                // its boundary) must go through the folded machinery first
                if target > self.cur_offset {
                    // a forward jump flying over an enclosing loop's
                    // exhaustion exit to a continuation no other jump
                    // targets is a `break` over a for/while-else region:
                    // record the else end so the loop close can build it
                    self.register_break_over_else(target);
                    if self.find_loop_exit(target).is_some() {
                        // a break inside an OPEN legacy handler (code
                        // 3.8/3.9 interact `except EOFError:
                        // self.write("\n"); break` in a nested try):
                        // the Break routes into the handler clause's
                        // body; a full close_inner_blocks_to_loop would
                        // force-close the enclosing Try blocks AT THEIR
                        // STARTS - the deferred pre-3.11 chain creation
                        // records handler_start = the block START
                        // (garbage: the real handler lies at the block's
                        // END), the keep-open back-edge machinery loses
                        // the chain and the loop closes before its
                        // handler region (the KI clause leaked to
                        // function level, the loop body duplicated).
                        // Close only down to the handler depth; the
                        // chain machinery owns the rest. Mirrors the
                        // JUMP_FORWARD arm's over_handlers guard.
                        // Scoped to a break that IS the handler's own
                        // escape: with an inner If/Else arm still open
                        // above the handler depth (bz2 3.8/3.9
                        // decompress `except OSError: if results:
                        // break else: raise`) the normal dispatch owns
                        // the arm - closing it here strands its
                        // not-yet-walked else region and flattens
                        // `else: raise` to a bare `raise`.
                        if self
                            .legacy_handler
                            .as_ref()
                            .map_or(false, |h| {
                                self.blocks.len() <= h.block_depth
                            })
                        {
                            self.push_stmt(Stmt::Break);
                            let depth = self
                                .legacy_handler
                                .as_ref()
                                .map(|h| h.block_depth)
                                .unwrap_or(1);
                            while self.blocks.len() > depth.max(1) {
                                let p = self
                                    .blocks
                                    .last()
                                    .map(|b| b.start)
                                    .unwrap_or(target);
                                self.force_close_top(p);
                            }
                            return true;
                        }
                        // degenerate `if c: break`: close ONLY the
                        // just-opened break block; enclosing branches
                        // continue past it (mirrors the JUMP_FORWARD arm)
                        let degenerate = matches!(
                            self.blocks.last().map(|b| (b.kind, b.end)),
                            Some((BlockType::If, end)) if end == self.cur_next
                        );
                        self.push_stmt(Stmt::Break);
                        if degenerate {
                            let pos =
                                self.blocks.last().map(|b| b.start).unwrap_or(0);
                            self.force_close_top(pos);
                        } else {
                            // a branch whose else region lies AHEAD (not
                            // yet walked) must keep it: the break's
                            // close-through would drop the If with an
                            // empty orelse and strand the else body at
                            // function level (3.8 asynchat handle_read:
                            // `if index: ... break else: collect-all`
                            // lost the else). Mark the over-jump so the
                            // close arm opens the Else region.
                            let loop_top = self
                                .blocks
                                .iter()
                                .rev()
                                .find(|b| {
                                    matches!(b.kind, BlockType::While | BlockType::For)
                                })
                                .map(|b| b.start);
                            for b in self.blocks.iter_mut() {
                                if matches!(b.kind, BlockType::If)
                                    && b.else_end.is_none()
                                    && b.short_circuit.is_none()
                                    && b.end != usize::MAX
                                    && b.end > self.cur_offset
                                    && target > b.end
                                {
                                    // a genuine else region re-joins the
                                    // iteration flow: it holds a back edge
                                    // to the loop top. A region that only
                                    // terminates (raise/return) is the
                                    // post-if continuation, not an else
                                    // (bz2 3.8 decompress: `if results:
                                    // break; raise` grew a phantom else)
                                    let rejoins = loop_top.map_or(false, |lt| {
                                        let (Some(&si), Some(&ei)) = (
                                            self.idx_of.get(&b.end),
                                            self.idx_of.get(&target),
                                        ) else {
                                            return false;
                                        };
                                        self.instrs[si..ei].iter().any(|x| {
                                            x.is_backward && x.target == Some(lt)
                                        })
                                    });
                                    // OR the region is a genuine else arm
                                    // that MERGES at the break's target:
                                    // its last flow is an unconditional
                                    // forward jump landing exactly on
                                    // `target`, with no terminator in
                                    // between (_osx_support 3.9
                                    // compiler_fixup: `if stripArch:
                                    // while True: try/except-break
                                    // elif not arm64: for...` - the elif
                                    // arm's end jumps to the same merge
                                    // the handler break flies to; it has
                                    // no back edge to the while-True top
                                    // so `rejoins` missed it and the elif
                                    // flattened into a sibling that ALSO
                                    // ran after the break)
                                    let merges_at_target = match (
                                        self.idx_of.get(&b.end),
                                        self.idx_of.get(&target),
                                    ) {
                                        (Some(&si), Some(&ei)) if si < ei => {
                                            let span = &self.instrs[si..ei];
                                            !span.iter().any(|x| {
                                                matches!(
                                                    x.op,
                                                    Op::RETURN_VALUE
                                                        | Op::RETURN_CONST
                                                        | Op::RAISE_VARARGS
                                                        | Op::RERAISE
                                                )
                                            }) && span.iter().rev().any(|x| {
                                                !x.is_backward
                                                    && x.target == Some(target)
                                                    && matches!(
                                                        x.op,
                                                        Op::JUMP_FORWARD
                                                            | Op::JUMP
                                                            | Op::JUMP_ABSOLUTE
                                                            // the else
                                                            // arm's own
                                                            // exit edges:
                                                            // an arm-end
                                                            // cond jump
                                                            // over the
                                                            // rest of the
                                                            // chain, or a
                                                            // nested for's
                                                            // exhaustion
                                                            // exit - both
                                                            // merge the
                                                            // arm at the
                                                            // break target
                                                            | Op::POP_JUMP_IF_FALSE
                                                            | Op::POP_JUMP_IF_TRUE
                                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                                            | Op::FOR_ITER
                                                            | Op::FOR_LOOP
                                                    )
                                            })
                                        }
                                        _ => false,
                                    };
                                    if rejoins || merges_at_target {
                                        b.else_end = Some(target);
                                    }
                                }
                            }
                            self.close_inner_blocks_to_loop();
                        }
                        return true;
                    }
                }
                // a BACKWARD jump onto an enclosing loop's top that is not
                // a continue (no inner block open above it): the compiler
                // threaded a nested loop's `break` onto the enclosing back
                // edge — emit the break
                // a nested loop's `break` that the compiler threaded onto
                // the enclosing loop's back edge (recorded when the nested
                // While was opened): emit the break and close to the
                // enclosing loop
                if self.threaded_break_at.contains(&self.cur_offset) {
                    self.close_blocks_at(self.cur_offset);
                    self.push_stmt(Stmt::Break);
                    self.close_inner_blocks_to_loop();
                    return true;
                }
                // a backward edge to a loop top the chain machinery has
                // ALREADY closed (registered in closed_loop_tops when it
                // emitted the Try and collapsed the loop) is post-emit
                // padding: continuing a closed loop has no target, and
                // letting the jump reach the continue machinery drops a
                // spurious Continue into whatever region block is open
                // (csv 3.6 has_header: the inner try chain's collecting
                // end edge became `else: continue` inside the just-opened
                // for-else region, stranding the else body at the
                // enclosing loop level)
                if target < self.cur_offset
                    && self.closed_loop_tops.iter().any(|t| {
                        self.effective_offset(*t) == self.effective_offset(target)
                    })
                {
                    return true;
                }
                // jump-threaded folded exit: a FORWARD jump landing on the
                // loop's own back-edge instruction (the compiler threads
                // branch exits that flow into the iteration end)
                let lands_on_back_edge = target > self.cur_offset
                    && self
                        .idx_of
                        .get(&target)
                        .and_then(|&ti| self.instrs.get(ti))
                        .map_or(false, |x| {
                            x.is_backward
                                && matches!(
                                    x.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                                && x.target
                                    == self
                                        .blocks
                                        .iter()
                                        .rev()
                                        .find(|b| {
                                            matches!(b.kind, BlockType::While | BlockType::For)
                                        })
                                        .map(|l| l.start)
                        });
                // a jump onto a nested rotated-while's exit trampoline is
                // a `break` of that loop
                if self.threaded_break_at.contains(&target) {
                    self.close_blocks_at(self.cur_offset);
                    self.push_stmt(Stmt::Break);
                    self.close_inner_blocks_to_loop();
                    return true;
                }
                // degenerate `if c: break` fusion (3.12): the back edge is
                // the ENTIRE then-region of a just-opened If — let the
                // fused-continue machinery below record the Continue and
                // the close-time normalizer flip it to `if c: break`
                // 3.14 `if c: break`: the PJIT hops over a break block
                // whose head is a jump to the loop EXIT — a plain continue
                // guard's back edge targets the loop top instead and must
                // keep the fused-continue path.
                let break_hop_target = match self.idx_of.get(&self.cur_offset) {
                    Some(&bi0) => {
                        let mut bj = bi0 + 1;
                        while matches!(
                            self.instrs.get(bj).map(|x| x.op),
                            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
                        ) {
                            bj += 1;
                        }
                        match self.instrs.get(bj) {
                            Some(j)
                                if matches!(
                                    j.op,
                                    Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                                ) && !j.is_backward =>
                            {
                                j.target
                            }
                            _ => None,
                        }
                    }
                    None => None,
                };
                let degenerate_break_fusion = self
                    .blocks
                    .last()
                    .map(|t| {
                        t.kind == BlockType::If
                            && t.stmts.is_empty()
                            && t.short_circuit.is_none()
                            && (t.start == self.cur_offset
                                || (self.padding_only_between(t.start, self.cur_offset)
                                    && break_hop_target
                                        .map_or(false, |bt| self.find_loop_exit(bt).is_some())))
                    })
                    .unwrap_or(false);
                // dead duplicate back edge right after a `break`'s exit
                // jump (compiler fall-through glue, untargeted): not a
                // continue and not a folded chain exit — ignoring it
                // keeps the break-rescued else region ahead open for the
                // walk (3.8/3.9 asynchat handle_read: the glue JABS at
                // 446 between the break and the else arm became
                // `else: continue` and stranded the else body)
                let dead_break_glue = self
                    .idx_of
                    .get(&self.cur_offset)
                    .and_then(|&ci| ci.checked_sub(1).map(|p| &self.instrs[p]))
                    .map_or(false, |prev| {
                        !prev.is_backward
                            && matches!(
                                prev.op,
                                Op::JUMP_ABSOLUTE
                                    | Op::JUMP_FORWARD
                                    | Op::JUMP
                                    | Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                            )
                            && prev.target.map_or(false, |t| {
                                t > prev.offset && self.find_loop_exit(t).is_some()
                            })
                    })
                    && !self.targets.contains(&self.cur_offset);
                if dead_break_glue {
                    return true;
                }
                // dead duplicate trampoline: an untargeted forward jump
                // to the chain-tail trampoline right after an arm-end
                // forward jump onto the chain's LOCAL merge trampoline
                // (pre-3.8 compilers emit the pair at elif-arm ends;
                // nothing targets the duplicate). Running it drives the
                // chain-fold machinery to close the enclosing arm HERE
                // and re-arm a phantom Else that starts past the local
                // merge, flattening the sibling arms under a spurious
                // `continue` (_strptime 3.3/2.7 ampm chain: the 1001
                // dup re-armed Else[1007,1599] and the M..Z arms sank
                // under `else: continue`). Consume it as glue only when
                // the local merge lies between this jump and the tail.
                if !inst.is_backward
                    && !self.targets.contains(&self.cur_offset)
                {
                    if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                        if ci > 0 {
                            let prev = &self.instrs[ci - 1];
                            let prev_fwd = !prev.is_backward
                                && matches!(
                                    prev.op,
                                    Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP
                                );
                            let tramp_at = |o: usize| {
                                self.idx_of
                                    .get(&o)
                                    .and_then(|&ti| self.instrs.get(ti))
                                    .map_or(false, |x| {
                                        x.is_backward
                                            && matches!(
                                                x.op,
                                                Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD
                                                    | Op::JUMP
                                            )
                                            && self.is_loop_top_target(
                                                x.target.unwrap_or(0),
                                            )
                                    })
                            };
                            // prev hops OVER this duplicate onto the
                            // local merge trampoline; this duplicate
                            // hops further, to the chain-tail trampoline
                            let prev_fwd_tramp = prev_fwd
                                && prev.target.map_or(false, |m| {
                                    m > self.cur_offset && tramp_at(m)
                                });
                            let tail_tramp = target > self.cur_offset
                                && tramp_at(target)
                                && prev.target.map_or(true, |m| target > m);
                            if prev_fwd_tramp && tail_tramp {
                                return true;
                            }
                        }
                    }
                }
                if std::env::var("PYCDC_EG_DBG").is_ok() {
                    eprintln!(
                        "EG jbarm [{}] pos={} target={} lands={} iscont={} degen={} fused?",
                        self.code.name, self.cur_offset, target,
                        lands_on_back_edge, self.is_continue_jump(target), degenerate_break_fusion
                    );
                }
                if !degenerate_break_fusion
                    && (lands_on_back_edge || self.is_continue_jump(target))
                {
                    // pre-3.11 handler `if c: A else: B` + shared
                    // `continue`: the compiler threads the continue
                    // into BOTH arms (then-arm JABS→loop-top; else-arm
                    // JABS→loop-top; the handler-exit JF follows). The
                    // flat rendering (`if c: A; continue` + `B;
                    // continue`) recompiles with a dead else-skip JF
                    // after the then arm's JABS — sig drift (asynchat
                    // 2.7 initiate_send `except TypeError: if data:
                    // appendleft else: del; continue`). Rebuild the
                    // if/else with one shared continue.
                    if self.legacy_handler.is_some() {
                        let rebuild = match self.blocks.last() {
                            Some(t)
                                if t.kind == BlockType::If
                                    && t.short_circuit.is_none()
                                    && t.else_end.is_none()
                                    && t.end >= self.cur_next
                                    && !t.stmts.is_empty()
                                    && t.cond_set =>
                            {
                                let else_start = t.end;
                                // the else arm must terminate with a
                                // back edge to the SAME loop top, with
                                // no other backward edge inside, and be
                                // followed by [pads] the handler-exit
                                // forward jump
                                let mut e2 = None;
                                let mut ok = true;
                                for x in self.instrs.iter() {
                                    if x.offset < else_start {
                                        continue;
                                    }
                                    if x.is_backward {
                                        if x.target == Some(target)
                                            && matches!(
                                                x.op,
                                                Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            )
                                        {
                                            e2 = Some(x.offset);
                                        } else {
                                            ok = false;
                                        }
                                        break;
                                    }
                                }
                                let after_ok = e2.map_or(false, |e2o| {
                                    self.idx_of.get(&e2o).map_or(false, |&ei| {
                                        let mut k = ei + 1;
                                        while matches!(
                                            self.instrs.get(k).map(|x| x.op),
                                            Some(Op::NOP)
                                                | Some(Op::NOT_TAKEN)
                                                | Some(Op::CACHE)
                                        ) {
                                            k += 1;
                                        }
                                        matches!(
                                            self.instrs.get(k).map(|x| (x.op, x.is_backward)),
                                            Some((Op::JUMP_FORWARD, false))
                                                | Some((Op::JUMP, false))
                                        )
                                    })
                                });
                                if ok && after_ok {
                                    e2.map(|e2o| (else_start, e2o))
                                } else {
                                    None
                                }
                            }
                            _ => None,
                        };
                        if let Some((else_start, e2)) = rebuild {
                            let mut t = self.blocks.pop().unwrap();
                            let then_stmts = std::mem::take(&mut t.stmts);
                            let cond = t.cond.clone().unwrap();
                            // the live legacy handler would swallow the
                            // region's statements — collect them into
                            // the orelse instead
                            let saved_rc = self.region_collect_only;
                            self.region_collect_only = true;
                            let orelse = self.decompile_region(else_start, e2);
                            self.region_collect_only = saved_rc;
                            self.push_stmt(Stmt::If {
                                cond,
                                body: then_stmts,
                                orelse,
                            });
                            self.push_stmt(Stmt::Continue);
                            let resume = self
                                .idx_of
                                .get(&e2)
                                .map(|&ei| self.instrs[ei].end())
                                .unwrap_or(e2);
                            self.skip_until = Some(resume);
                            return true;
                        }
                    }
                    // folded elif/else boundary: this jump is the LAST
                    // instruction of an If/Else branch region and the target
                    // is (or threads to) the enclosing loop's back edge —
                    // the compiler fused the chain exit with the loop end.
                    // Close the branch and let the chain machinery build
                    // the else/elif at the next instruction.
                    // a backward jump to the loop top from inside an OPEN
                    // legacy handler is the handler's continue path, not a
                    // fused chain exit: the chain machinery below would
                    // consume it as the chain's collecting back edge and
                    // drop the Continue (asynchat 2.7 initiate_send
                    // `except TypeError: ... continue` lost the continue
                    // when the if/else arms each ended in JABS-to-top).
                    // Let it fall through to the is_continue_jump path /
                    // handle_jump_backward's explicit-vs-implicit scan.
                    let folded = match self.blocks.last() {
                        Some(t)
                            if matches!(t.kind, BlockType::If | BlockType::Else)
                                && t.short_circuit.is_none()
                                && self.legacy_handler.is_none() =>
                        {
                            let at_end = t.end == self.cur_next
                                || t.end == self.cur_offset
                                || (t.folded_exit && t.end == usize::MAX);
                            // or the jump hops over trailing else-code that
                            // no other instruction references (the folded
                            // chain exit jumps straight to the loop top)
                            // bounded scan: an open-ended Else[MAX] has no
                            // physical tail to hop over, and ranging to
                            // usize::MAX spins forever (_markupbase 3.8
                            // _parse_doctype_notation hang)
                            let hops_tail = t.end > self.cur_next
                                && t.end != usize::MAX
                                && (self.cur_offset..t.end).any(|o| self.targets.contains(&o))
                                && (self.cur_next..t.end)
                                    .all(|o| !self.targets.contains(&o));
                            // 3.8+: a real `continue` statement carries
                            // its own source line (the compiler attributes
                            // it to the loop header or the continue
                            // itself), while a fused chain exit carries the
                            // preceding statement's line, matching the
                            // branch cond jump's line in the common
                            // single-line-branch case. Empirical heuristic;
                            // <=3.7 has the distinct CONTINUE_LOOP opcode.
                            // line-based disambiguation of a fused chain
                            // exit from a real trailing `continue`:
                            // - 3.8+: a real continue carries its own line
                            //   (or the loop header's), a fused exit carries
                            //   the branch cond's line
                            // - py2/<=3.7: a fused exit shares the line of
                            //   the last statement in the branch; a real
                            //   continue starts a fresh line
                            // a fused chain exit inherits the line of the
                            // arm's LAST statement: the instruction right
                            // before this jump shares its line. A real
                            // trailing `continue` is a statement of its
                            // own and starts a fresh line (3.8+; the
                            // cond-jump comparison alone is unsound for
                            // multi-statement arms — copyreg 3.8
                            // _slotnames: the inner else arm's fused end
                            // edge failed the cond-line check, was taken
                            // as an explicit continue, and the chain's
                            // final else arm flattened into the loop).
                            let prev_same_line = self
                                .idx_of
                                .get(&self.cur_offset)
                                .and_then(|&ci| (ci > 0).then(|| &self.instrs[ci - 1]))
                                .map_or(false, |prev| {
                                    prev.line.is_some()
                                        && inst.line.is_some()
                                        && prev.line == inst.line
                                });
                            let line_ok = t.folded_exit
                                || prev_same_line
                                || if self.version.at_least(3, 8) {
                                    self.instrs
                                        .iter()
                                        .find(|i| i.end() == t.start && i.target.is_some())
                                        .map_or(true, |cj| {
                                            cj.line.is_none()
                                                || inst.line.is_none()
                                                || cj.line == inst.line
                                        })
                                } else {
                                    self.idx_of
                                        .get(&self.cur_offset)
                                        .and_then(|&ci| {
                                            (ci > 0).then(|| &self.instrs[ci - 1])
                                        })
                                        .map_or(true, |prev| {
                                            prev.line.is_none()
                                                || inst.line.is_none()
                                                || prev.line == inst.line
                                        })
                                };
                            // a DEGENERATE guard (`if c: continue` from
                            // an and/break chain transformation) has an
                            // EMPTY then-region - only padding between the
                            // block start and this back jump. A genuine
                            // folded chain exit ends a nonempty branch
                            // body. Misfolding the guard turns the whole
                            // loop tail into an Else[MAX] chain region
                            // (3.14 for-else + `if a and b: break`).
                            let then_empty = (self.cur_offset..t.start.max(self.cur_offset))
                                .next()
                                .is_none()
                                && self.padding_only_between(
                                    t.start.min(self.cur_offset),
                                    self.cur_offset,
                                );
                            (at_end || hops_tail)
                                && !then_empty
                                && line_ok
                                && (lands_on_back_edge
                                    || self
                                        .blocks
                                        .iter()
                                        .rev()
                                        .skip(1)
                                        .find(|b| {
                                            matches!(b.kind, BlockType::While | BlockType::For)
                                        })
                                        .map_or(false, |l| {
                                            l.start == target || l.cond_end == target
                                        }))
                        }
                        _ => false,
                    };
                    if std::env::var("PYCDC_EG_DBG").is_ok() {
                        eprintln!("EG jfold [{}] pos={} folded={}", self.code.name, self.cur_offset, folded);
                    }
                    if folded {
                        let end = self.blocks.last().map(|t| t.end).unwrap_or(target);
                        // mark every enclosing open If/Else whose region
                        // contains this jump: the fused exit serves as the
                        // then-exit for the whole chain spine. Only the
                        // CONTIGUOUS branch-block segment at the top of
                        // the stack belongs to this chain: marking across
                        // an intervening loop leaks folded_exit to the
                        // loop's enclosing guard, whose own arm-end
                        // iteration edge then folds open a dead Else[MAX]
                        // that swallows the function tail (copyreg 3.8
                        // _slotnames: If[60,186) marked from the inner
                        // chain's fold at 160 reopened a phantom
                        // Else[186,MAX] at the mro loop's back edge,
                        // whose re-arm popped the wrong pending_then and
                        // dropped the whole loop)
                        let mut mark_spine: Vec<usize> = Vec::new();
                        for t in self.blocks.iter().rev() {
                            if matches!(t.kind, BlockType::If | BlockType::Else)
                                && t.end > self.cur_offset
                                && !t.no_fold
                            {
                                mark_spine.push(t.start);
                            } else if !matches!(
                                t.kind,
                                BlockType::If | BlockType::Else
                            )
                                || t.no_fold
                            {
                                break;
                            }
                        }
                        for t in self.blocks.iter_mut() {
                            if matches!(t.kind, BlockType::If | BlockType::Else)
                                && t.end > self.cur_offset
                                && mark_spine.contains(&t.start)
                            {
                                t.folded_exit = true;
                            }
                        }
                        // close inner blocks whose region already ended,
                        // then the folded branch block itself
                        self.close_blocks_at(self.cur_offset);
                        let top_matches = self.blocks.last().map_or(false, |t| {
                            (matches!(t.kind, BlockType::If) || matches!(t.kind, BlockType::Else))
                                && t.end == end
                        });
                        // folded chain blocks that were already open
                        // before this jump also end here (the jump is
                        // the chain end); blocks freshly opened by the
                        // close below must stay (their region follows)
                        // only the CONTIGUOUS If/Else segment at the
                        // top of the stack belongs to this chain's
                        // spine — a loop block below separates the
                        // enclosing branches, whose close belongs to
                        // the loop's own exhaustion flow (copyreg 3.8
                        // _slotnames: the enclosing mro For and the
                        // guard If were folded early, dropping the
                        // else branch and function tail into a dead
                        // Else[MAX])
                        let mut spine: Vec<usize> = Vec::new();
                        for t in self.blocks.iter().rev() {
                            if matches!(t.kind, BlockType::If | BlockType::Else)
                                && t.folded_exit
                                && t.end > self.cur_offset
                            {
                                spine.push(t.start);
                            } else if !matches!(
                                t.kind,
                                BlockType::If | BlockType::Else
                            ) {
                                break;
                            }
                        }
                        // the marking must also run when the folded top
                        // does NOT end at the fold point: a spine If one
                        // level down can still have its else arm starting
                        // right after it (csv 3.5 has_header: the inner
                        // else's fused end edge folded with the chain If
                        // ending at the following SETUP_EXCEPT — without
                        // the mark its folded-exit reopen produced an
                        // Else[MAX] that the try body's forward jump
                        // sealed early, flattening the try)
                        let mark_needed = top_matches
                            || self.blocks.iter().any(|b| {
                                matches!(b.kind, BlockType::If)
                                    && b.folded_exit
                                    && spine.contains(&b.start)
                                    && b.else_end.is_none()
                                    && b.end == self.cur_next
                            });
                        if mark_needed {
                            // a spine If whose end is exactly the fold
                            // point may have an UNMARKED else arm lying
                            // right after it: the arm-end forward jump
                            // flew to a merge trampoline (a back edge to
                            // the loop top) instead of marking else_end.
                            // Mark it here so the close transitions into
                            // the Else region and the walk rebuilds the
                            // chain's final else arm (copyreg 3.8
                            // _slotnames: `elif ...: ... else:
                            // names.append(name)` flattened to loop
                            // level, the inner else grew a spurious
                            // continue from the trampoline back edge).
                            // The trampoline probe keeps genuine
                            // no-else guards intact (their arm-end jump
                            // targets the loop top directly, not a
                            // back-edge instruction).
                            for si in (0..self.blocks.len()).rev() {
                                let else_mark = {
                                    let b = &self.blocks[si];
                                    if !(matches!(b.kind, BlockType::If)
                                        && b.folded_exit
                                        && spine.contains(&b.start)
                                        && b.else_end.is_none()
                                        && b.end == self.cur_next)
                                    {
                                        None
                                    } else if self.starts_with_cond_jump(
                                        self.cur_next,
                                        usize::MAX,
                                    ) {
                                        // the region right after the fold
                                        // opens with a conditional jump:
                                        // it is the NEXT elif link of the
                                        // chain (handled by the folded
                                        // re-arm machinery), not this
                                        // block's else arm — marking
                                        // else_end here swallows the link
                                        // into a nested else (filecmp 3.3
                                        // phase2: the S_ISREG link nested
                                        // under S_ISDIR with a spurious
                                        // continue and the final else
                                        // flattened to loop level)
                                        None
                                    } else {
                                        // the else arm (if any) starts at
                                        // the fold point; its extent ends
                                        // at the FIRST structural
                                        // boundary: a backward edge to
                                        // the loop top (the arm's fused
                                        // iteration end), a forward jump
                                        // to such an edge (a merge
                                        // trampoline), or a jump to the
                                        // loop exit (an arm-ending
                                        // break). A pre-3.11 try chain
                                        // laid out inside the arm owns
                                        // collecting back edges of its
                                        // own (the except arm's normal
                                        // exit): the arm's real boundary
                                        // is the chain-END back edge
                                        // after the chain's else/merge
                                        // region — statically skip edges
                                        // below the chain merge (csv 3.5
                                        // has_header: the `else:
                                        // try/except/else` arm cut at
                                        // the except arm's edge was
                                        // sealed by the try body's own
                                        // forward jump before the Try
                                        // emitted, flattening it).
                                        // Anything else: no discoverable
                                        // arm — no mark.
                                        let mut mark: Option<usize> = None;
                                        let mut chain_merge: Option<usize> =
                                            None;
                                        let mut steps = 0usize;
                                        for x in self.instrs.iter().skip_while(
                                            |x| x.offset < self.cur_next,
                                        ) {
                                            steps += 1;
                                            if steps > 400 {
                                                break;
                                            }
                                            if matches!(
                                                x.op,
                                                Op::SETUP_EXCEPT
                                                    | Op::SETUP_FINALLY
                                                    | Op::SETUP_CLEANUP
                                            ) {
                                                // the chain head may sit
                                                // exactly AT the arm
                                                // start (the else arm
                                                // begins with the try) —
                                                // test it before the
                                                // start-instruction skip
                                                // below
                                                // chain head: the body-end
                                                // unconditional forward
                                                // jump flies over the
                                                // handler region — its
                                                // target is the chain's
                                                // else/merge start
                                                if let Some(h) = x.target {
                                                    chain_merge = self
                                                        .instrs
                                                        .iter()
                                                        .skip_while(|y| {
                                                            y.offset
                                                                <= x.offset
                                                        })
                                                        .take(300)
                                                        .find(|y| {
                                                            !y.is_backward
                                                                && matches!(
                                                                    y.op,
                                                                    Op::JUMP_ABSOLUTE
                                                                        | Op::JUMP_FORWARD
                                                                        | Op::JUMP
                                                                )
                                                                && y.target
                                                                    .map_or(
                                                                        false,
                                                                        |t| {
                                                                            t > h
                                                                        },
                                                                    )
                                                        })
                                                        .and_then(|y| y.target)
                                                        .or(chain_merge);
                                                    // a chain whose body
                                                    // and handlers all
                                                    // exit through
                                                    // BACKWARD edges has
                                                    // no forward merge
                                                    // jump: the region's
                                                    // boundary is the
                                                    // chain's merge
                                                    // point — the
                                                    // body-end and
                                                    // handler-exit
                                                    // collecting edges
                                                    // below it are
                                                    // chain-internal
                                                    // (bdb 3.5/3.6
                                                    // effective: the
                                                    // else arm holding
                                                    // the try cut at the
                                                    // body-end edge,
                                                    // closed empty
                                                    // before the chain
                                                    // emitted, and the
                                                    // Try hoisted to
                                                    // loop level)
                                                    if chain_merge.is_none() {
                                                        chain_merge = self
                                                            .chain_merge_past(h)
                                                            .or(chain_merge);
                                                    }
                                                }
                                                continue;
                                            }
                                            if x.offset <= self.cur_next {
                                                continue;
                                            }
                                            let back_to_top = x.is_backward
                                                && x.target.map_or(
                                                    false,
                                                    |t| self.is_loop_top_target(t),
                                                );
                                            let fwd_to_tramp = !x.is_backward
                                                && matches!(
                                                    x.op,
                                                    Op::JUMP_ABSOLUTE
                                                        | Op::JUMP_FORWARD
                                                        | Op::JUMP
                                                )
                                                && x.target.map_or(
                                                    false,
                                                    |t| {
                                                        self.idx_of.get(&t)
                                                            .and_then(|&ti| {
                                                                self.instrs.get(ti)
                                                            })
                                                            .map_or(false, |y| {
                                                                y.is_backward
                                                                    && y.target.map_or(
                                                                        false,
                                                                        |lt| self
                                                                            .is_loop_top_target(
                                                                                lt,
                                                                            ),
                                                                    )
                                                            })
                                                    },
                                                );
                                            let to_loop_exit = x
                                                .target
                                                .map_or(false, |t| {
                                                    t > x.offset
                                                        && self
                                                            .find_loop_exit(t)
                                                            .is_some()
                                                });
                                            if back_to_top
                                                || fwd_to_tramp
                                                || to_loop_exit
                                            {
                                                if chain_merge
                                                    .map_or(false, |m| {
                                                        x.offset < m
                                                    })
                                                {
                                                    // chain-internal
                                                    // collecting edge
                                                    continue;
                                                }
                                                mark = Some(
                                                    if x.is_backward {
                                                        x.offset
                                                    } else {
                                                        x.target.unwrap()
                                                    },
                                                );
                                                break;
                                            }
                                        }
                                        mark
                                    }
                                };
                                if let Some(t) = else_mark {
                                    self.blocks[si].else_end = Some(t);
                                }
                            }
                        }
                        if top_matches {
                            self.force_close_top(end);
                            let mut guard = 0;
                            while self.blocks.last().map_or(false, |t| {
                                matches!(t.kind, BlockType::If | BlockType::Else)
                                    && t.folded_exit
                                    && spine.contains(&t.start)
                            }) && guard < 16
                            {
                                let e = self.blocks.last().map(|t| t.end).unwrap_or(end);
                                self.force_close_top(e);
                                guard += 1;
                            }
                            // spine members separated from the fold point
                            // by an intervening loop block must NOT be
                            // closed here: the loop's own close at its
                            // exhaustion exit emits into them first
                            // (copyreg 3.8 _slotnames: folding the inner
                            // chain's edge closed the enclosing mro For
                            // and the guard If early, dropping the whole
                            // else branch and the function tail into a
                            // dead Else[MAX])
                        }
                        // the fold consumed the loop body's LAST back
                        // edge (the next instruction is the exhaustion
                        // exit of the loop right below the still-open
                        // chain blocks): open-ended folded chain If/Else
                        // (end == MAX) sitting directly above that loop
                        // must close HERE — the exhaustion close cannot
                        // reach them (close_blocks_at unwinds only from
                        // the top), and leaving them open swallows the
                        // loop and the whole function tail into a dead
                        // Else[MAX] (_strptime 3.14 __calc_date_time:
                        // the prev_same_line fold at the chain's final
                        // fused arm end trapped the tail). The close is
                        // chain-safe: a folded Else whose pending body
                        // and single nested If form the next link
                        // re-arms instead of sealing, so only a
                        // genuinely finished chain collapses here.
                        loop {
                            // contiguous open If/Else chain segment at the
                            // top and the first non-branch block below it
                            // NOTE: the segment includes branch blocks
                            // whose end already passed — a stranded chain
                            // head sits below the open Else[MAX] long
                            // after its own end offset (close_blocks_at
                            // unwinds from the top only), and it must
                            // close together with the chain (cmd 3.14
                            // do_help: If[328,430) under Else[434,MAX])
                            let (seg, below_exit) = {
                                let mut seg = 0;
                                let mut below = None;
                                for t in self.blocks.iter().rev() {
                                    if matches!(
                                        t.kind,
                                        BlockType::If | BlockType::Else
                                    ) {
                                        seg += 1;
                                    } else {
                                        below = matches!(
                                            t.kind,
                                            BlockType::While | BlockType::For
                                        )
                                        .then(|| {
                                            self.loop_exit_offset(t)
                                        })
                                        .flatten();
                                        break;
                                    }
                                }
                                (seg, below)
                            };
                            let collapse = seg > 0
                                && matches!(
                                    self.blocks.last(),
                                    Some(t) if matches!(
                                        t.kind,
                                        BlockType::If | BlockType::Else
                                    ) && t.folded_exit
                                        && t.end == usize::MAX
                                )
                                && below_exit == Some(self.cur_next);
                            if !collapse {
                                break;
                            }
                            let before = self.blocks.len();
                            // close the whole segment: the chain head's
                            // region also ends at this fused back edge
                            // (its else arm was the one just folded)
                            for _ in 0..seg {
                                let e = self
                                    .blocks
                                    .last()
                                    .map(|t| {
                                        t.end.min(self.cur_next)
                                    })
                                    .unwrap();
                                self.force_close_top(e);
                            }
                            // a folded Else re-arm replaces the closed
                            // block instead of shrinking the stack: the
                            // chain is not finished here — stop and let
                            // the walk continue (guards against a re-arm
                            // ping-pong spin)
                            if self.blocks.len() >= before {
                                break;
                            }
                        }
                        return true;
                    }
                    // not folded: run the deferred block close, then decide
                    // again — the branch block that ended at this jump may
                    // have been the only thing making this a nested continue.
                    // A jump landing ON the loop's back edge just flows into
                    // the iteration end (compiler fusion), never a continue.
                    self.close_blocks_at(self.cur_offset);
                    // 3.12+ nested-loop break threaded onto the enclosing
                    // back edge: `POP_TOP <inner iterator>; JB outer-top`.
                    // A real outer continue never pops the enclosing
                    // iterator, so the POP_TOP discriminates.
                    // a `continue` right after a nested try's handler
                    // chain also shows POP_TOP + a backward jump to an
                    // enclosing top — require no legacy chain in flight
                    // (3.12+ never keeps one)
                    let inner_break = self.legacy_try.is_none()
                        && (!self.version.at_least(3, 12)
                            || self
                                .match_prev_real(
                                    self.idx_of
                                        .get(&self.cur_offset)
                                        .copied()
                                        .unwrap_or(usize::MAX),
                                )
                                .map_or(false, |pi| self.instrs[pi].op == Op::POP_TOP))
                        && {
                            let mut seen_inner = false;
                            let mut matched_outer = false;
                            for b in self.blocks.iter().rev() {
                                if matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                ) {
                                    if b.start == target || b.cond_end == target {
                                        matched_outer = true;
                                        break;
                                    }
                                    seen_inner = true;
                                }
                            }
                            seen_inner && matched_outer
                        };
                    if std::env::var("PYCDC_EG_DBG").is_ok() {
                        eprintln!(
                            "EG ib [{}] pos={} target={} inner_break={} blocks={:?} skip={:?}",
                            self.code.name, self.cur_offset, target, inner_break,
                            self.blocks.iter().map(|b| format!("{:?}[{},{}]", b.kind, b.start, b.end)).collect::<Vec<_>>(),
                            self.skip_until
                        );
                    }
                    if inner_break {
                        // just the Break: the inner loop closes at its
                        // OWN back edge further down (the linear walk
                        // still renders the rest of its body and the
                        // else region), and this jump re-enters the
                        // outer loop's next iteration naturally
                        self.push_stmt(Stmt::Break);
                        // register the inner loop's else end: a backward
                        // jump to the outer top on the BREAK's own source
                        // line closes an else region (the compiler
                        // threads the else's iteration end onto the outer
                        // back edge); one on the loop header's line is
                        // the outer loop's own back edge (no else)
                        if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                            let mut inner_idx = None;
                            let mut inner_end = None;
                            for i in (0..self.blocks.len()).rev() {
                                if matches!(
                                    self.blocks[i].kind,
                                    BlockType::While | BlockType::For
                                ) {
                                    if self.blocks[i].start == target
                                        || self.blocks[i].cond_end == target
                                    {
                                        break;
                                    }
                                    if inner_idx.is_none() {
                                        inner_idx = Some(i);
                                        inner_end = Some(self.blocks[i].end);
                                    }
                                }
                            }
                            if let (Some(ii), Some(iend)) = (inner_idx, inner_end) {
                                // the else bound: the outer loop's own
                                // back edge after the inner end (while
                                // case), or — for 3.13 nested FOR loops,
                                // whose outer has NO back edge — the
                                // outer loop's exhaustion end (_check_
                                // methods: the break JB threads onto the
                                // outer FOR_ITER and the else arm
                                // [END_FOR+POP_TOP .. outer END_FOR)
                                // diverges with `return NotImplemented`)
                                let outer_end_bound = self
                                    .blocks
                                    .iter()
                                    .rev()
                                    .find(|b| {
                                        matches!(
                                            b.kind,
                                            BlockType::While | BlockType::For
                                        ) && (b.start == target
                                            || b.cond_end == target)
                                    })
                                    .map(|b| b.end)
                                    .filter(|e| {
                                        *e != usize::MAX && *e > iend
                                    });
                                let jb_bound = self.instrs[ci + 1..]
                                    .iter()
                                    .find(|x| {
                                        x.is_backward
                                            && matches!(
                                                x.op,
                                                Op::JUMP_BACKWARD
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                    | Op::JUMP_ABSOLUTE
                                            )
                                            && x.target == Some(target)
                                    })
                                    .map(|x| x.offset)
                                    .or(outer_end_bound);
                                if let Some(jb_off) = jb_bound {
                                    // an else region holds statements
                                    // between the exhaustion point and
                                    // the threaded jump; loop padding
                                    // (END_FOR/POP_TOP) alone means the
                                    // jump is the outer's plain back edge.
                                    // A threaded inner exit (end BEFORE
                                    // this break) has no local else span
                                    let has_stmts = iend > self.cur_offset && self
                                        .instrs
                                        .iter()
                                        .any(|x| {
                                            x.offset >= iend
                                                && x.offset < jb_off
                                                && !matches!(
                                                    x.op,
                                                    Op::END_FOR
                                                        | Op::POP_TOP
                                                        | Op::POP_ITER
                                                        | Op::NOP
                                                        | Op::NOT_TAKEN
                                                        | Op::CACHE
                                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                )
                                        });
                                    if has_stmts
                                        && self.blocks[ii].loop_else_end.is_none()
                                    {
                                        self.blocks[ii].loop_else_end =
                                            Some(jb_off);
                                    }
                                }
                            }
                        }
                        return true;
                    }
                    // unreachable back-edge padding: a jump right after a
                    // RAISE/RETURN ending an arm, with no jump landing on
                    // it, is a dead copy from an unoptimized compiler
                    // (2.6/3.5/3.6). is_continue_jump below would render
                    // it as a spurious `continue` inside the terminating
                    // arm (chunk.skip 2.6). Placement AFTER the folded
                    // machinery is deliberate: an arm-end jump to the
                    // loop top that folds as a chain exit keeps the elif
                    // chain intact (configparser 3.5 _read) — only the
                    // non-folding remainder is dead padding.
                    if !lands_on_back_edge && inst.is_backward {
                        if let Some(&ci) = self.idx_of.get(&inst.offset) {
                            if ci > 0 {
                                let prev = &self.instrs[ci - 1];
                                if matches!(
                                    prev.op,
                                    Op::RAISE_VARARGS
                                        | Op::RETURN_VALUE
                                        | Op::RETURN_CONST
                                ) && !self.targets.contains(&inst.offset)
                                {
                                    // the dead edge may still be the loop's
                                    // LAST physical back edge (configparser
                                    // 3.6 _interpolate_some: raise, dead
                                    // JABS, POP_BLOCK, function-tail
                                    // return) — close the loop like the
                                    // back-edge handler would. When a REAL
                                    // back edge follows (dead jump
                                    // mid-body), keep the loop open —
                                    // closing early triggers the else
                                    // probe and steals the rest of the
                                    // body into a phantom for-else
                                    // (SimpleXMLRPCServer 2.6)
                                    let more_back_edges = self
                                        .instrs
                                        .iter()
                                        .skip(ci + 1)
                                        .any(|x| {
                                            x.is_backward
                                                && matches!(
                                                    x.op,
                                                    Op::JUMP_ABSOLUTE
                                                        | Op::JUMP_BACKWARD
                                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                        | Op::JUMP
                                                )
                                                && x.target == Some(target)
                                        });
                                    if !more_back_edges {
                                        let n = self.blocks.len();
                                        for i in (0..n).rev() {
                                            if matches!(
                                                self.blocks[i].kind,
                                                BlockType::While | BlockType::For
                                            ) && (self.blocks[i].start == target
                                                || self.blocks[i].end == target)
                                            {
                                                while self.blocks.len() > i + 1 {
                                                    let p = self
                                                        .blocks
                                                        .last()
                                                        .map(|x| x.start)
                                                        .unwrap_or(target);
                                                    self.force_close_top(p);
                                                }
                                                self.force_close_top(target);
                                                self.closed_loop_tops.push(target);
                                                break;
                                            }
                                        }
                                    }
                                    return true;
                                }
                            }
                        }
                    }
                    // a legacy chain's body-end hop over the handler
                    // region to the merge point is NOT a continue: the
                    // chain must parse inline and the enclosing If's
                    // else arm (between the chain and the merge) must
                    // stay attached (_compression read 3.5-3.7: the
                    // then-arm's JABS-to-merge classified as continue
                    // tore the If down, orphaned the else arm and sank
                    // the try to the loop tail)
                    let chain_body_hop = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            // body-end hop: the chain is unparsed and the
                            // jump flies over it
                            (l.handlers.is_empty()
                                && l.handler_start > self.cur_offset
                                && l.handler_start < target)
                                // handler-exit hop: this jump leaves the
                                // chain region (which lies between the
                                // enclosing If's start and its else arm)
                                // for the merge — a continue here tears
                                // the If down and flattens the else arm
                                // into the loop. The clause may still be
                                // OPEN (an empty `except: pass` body
                                // collects only at the chain end) or
                                // already collected (_compression 3.7)
                                || (l.handler_start <= self.cur_offset
                                    && (self.legacy_handler.is_some()
                                        || !l.handlers.is_empty())
                                    && self.blocks.iter().any(|b| {
                                        matches!(b.kind, BlockType::If)
                                            && b.start < l.handler_start
                                            && b.end > l.handler_start
                                    }))
                        });
                    // a FORWARD jump into the loop middle right after a
                    // continue's own back edge is the branch arm's dead
                    // end-of-arm trampoline (py2.6 emits it as a forward
                    // JUMP_ABSOLUTE): the continue was already emitted —
                    // a second one duplicates the statement and blocks
                    // the elif chain below from folding (ast 2.6
                    // generic_visit: doubled continues, flattened elif)
                    let dead_after_cont = target > self.cur_offset
                        && self
                            .idx_of
                            .get(&self.cur_offset)
                            .and_then(|&ci| {
                                (ci > 0).then(|| &self.instrs[ci - 1])
                            })
                            .map_or(false, |prev| {
                                prev.is_backward
                                    && matches!(
                                        prev.op,
                                        Op::JUMP_ABSOLUTE
                                            | Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            | Op::JUMP
                                    )
                                    && prev.target
                                        .map_or(false, |t| {
                                            self.is_loop_top_target(t)
                                        })
                            })
                        && !self.targets.contains(&self.cur_offset);
                    // a chain-collecting back edge INSIDE the live
                    // region of a legacy try (the body-end edge before
                    // the handler, or the handler-exit edge after the
                    // clauses) is structural glue, not a source-level
                    // continue: emitting one here lands it in the
                    // enclosing else arm beside the deferred Try
                    // (bdb 3.5/3.6 effective: `else: continue; try:`
                    // and a trailing `continue` after the except arm)
                    let chain_collect_edge = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            target < l.handler_start
                                && (self.cur_offset < l.handler_start
                                    || self.cur_offset
                                        > l.else_stop.max(l.handler_start))
                                && self.blocks.iter().any(|b| {
                                    matches!(
                                        b.kind,
                                        BlockType::If | BlockType::Else
                                    ) && b.start < l.handler_start
                                        && b.end > l.handler_start
                                })
                        });
                    // a FORWARD jump to a mainline merge point (not a
                    // loop top/exit, not itself targeted by a jump from
                    // before this instruction, and not inside a live
                    // legacy chain's region) is an if/else arm end —
                    // py2.7 compiles the arm-end skip as JUMP_ABSOLUTE
                    // instead of JUMP_FORWARD (cgi 2.7 parse_multipart:
                    // `JABS 275` after `data = fp.read(bytes)` rendered
                    // a spurious `continue` and flattened the else arm).
                    // Handle it as a forward jump so the else arm gets
                    // marked. Targets of EARLIER jumps are body/arm
                    // starts, not merges (a continue onto a loop
                    // trampoline stays on the historic path — bdb 3.6's
                    // merge trampoline is targeted by the arm-end hop);
                    // the else arm's own end jump targets the merge
                    // from AFTER this instruction and does not veto.
                    let in_chain_region = self
                        .legacy_try
                        .as_ref()
                        .map_or(false, |l| {
                            target >= l.handler_start
                                && target < l.else_stop.max(l.handler_start)
                        });
                    let arm_merge_ahead = target > self.cur_offset
                        // py2.6's peek-jump (JUMP_IF_FALSE/TRUE +
                        // POP_TOP) branch shapes fold through their own
                        // value-merge machinery; the arm-end JABS there
                        // feeds the folded-chain path and diverting it
                        // hoists the loop body out of the loop (cgitb
                        // 2.6 scanvars). 2.6 stays on the historic path
                        // pending the py2.6 chain redesign.
                        && !(self.version.major == 2 && self.version.minor == 6)
                        && !in_chain_region
                        // the merge is a mainline statement, not a
                        // trampoline: a trampoline (the target itself
                        // hops to a loop top) is the bdb 3.6 chain-merge
                        // shape whose edge keeps the historic path
                        && !self
                            .idx_of
                            .get(&target)
                            .and_then(|&ti| self.instrs.get(ti))
                            .map_or(false, |x| {
                                x.is_backward
                                    && x.target.map_or(false, |t| {
                                        self.is_loop_top_target(t)
                                    })
                            })
                        // veto: the top block's OWN cond jump targets
                        // this merge — its else arm is entered by
                        // fall-through only (no jump labels the else
                        // start), the cgitb scanvars shape where the
                        // historic continue + fold machinery renders
                        // correctly. When the merge is targeted only by
                        // OTHER structures (an enclosing guard's escape,
                        // the else arm's own end jump — cgi 2.7
                        // parse_multipart's 275), the gap after this
                        // arm end IS a jump-labeled else arm and the
                        // forward path must mark it.
                        // the arm-merge reading is only valid when the
                        // region right after this jump is the TOP
                        // block's own jump-labeled else arm (its cond
                        // jump targets cur_next) AND the jump lands
                        // exactly on the block's end (the else arm
                        // starts here and runs to the merge): then the
                        // forward path marks the else and the close
                        // rebuilds the if/else (cgi 2.7 parse_multipart:
                        // PJF-215 labels 266, the arm-end JABS hops it
                        // to the merge 275 == the block's end). Shapes
                        // that must keep the historic path: a
                        // fall-through else (the cond flies to the
                        // merge itself — cgitb 3.5/3.3 scanvars), and a
                        // guardless arm end flying to an ENCLOSING
                        // merge while an outer guard's else arm starts
                        // at cur_next (bz2 3.3 open: the else-arm
                        // marking swallowed the guards into the inner
                        // raise arm)
                        && self
                            .blocks
                            .last()
                            .map_or(false, |t| {
                                matches!(
                                    t.kind,
                                    BlockType::If | BlockType::Else
                                ) && self
                                        .idx_of
                                        .get(&t.start)
                                        .and_then(|&si| {
                                            (si > 0).then(|| &self.instrs[si - 1])
                                        })
                                        .map_or(false, |cj| {
                                            matches!(
                                                cj.op,
                                                Op::POP_JUMP_IF_FALSE
                                                    | Op::POP_JUMP_IF_TRUE
                                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                                    | Op::POP_JUMP_BACKWARD_IF_FALSE
                                                    | Op::POP_JUMP_BACKWARD_IF_TRUE
                                                    | Op::JUMP_IF_FALSE_OR_POP
                                                    | Op::JUMP_IF_TRUE_OR_POP
                                                    | Op::JUMP_IF_FALSE
                                                    | Op::JUMP_IF_TRUE
                                                    | Op::POP_JUMP_IF_NONE
                                                    | Op::POP_JUMP_IF_NOT_NONE
                                                    | Op::POP_JUMP_FORWARD_IF_NONE
                                                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                                            ) && cj.target == Some(self.cur_next)
                                        })
                            })
                        && !self.blocks.iter().any(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && (b.start == target
                                    || b.cond_end == target
                                    || (b.cond_end != usize::MAX
                                        && b.start < target
                                        && target < b.cond_end))
                        });
                    if !lands_on_back_edge
                        && !chain_body_hop
                        && !chain_collect_edge
                        && !dead_after_cont
                        && !arm_merge_ahead
                        && self.is_continue_jump(target)
                    {
                        // continue of an outer loop: emit first, then close
                        // the inner blocks it jumps out of
                        self.push_stmt(Stmt::Continue);
                        // A branch block whose region still lies ahead
                        // (end > cur_next) has an unparsed else arm — the
                        // then arm's terminating jump comes right after
                        // this continue and will mark/close the block
                        // through handle_jump_forward. Closing here
                        // instead strands the else region out of the
                        // branch and the follow-up trampoline skips it
                        // (bdb 3.5 effective(): `if b.ignore > 0: ...
                        // continue` lost `else: return (b, True)` and the
                        // whole conditional-breakpoint try arm).
                        // only with the legacy try machinery fully
                        // quiescent: chain-collecting and dead back
                        // edges inside a parsed chain must keep the
                        // historic close (asyncore 2.7 close_all: the
                        // handler-region edges left the clause blocks
                        // open and the Try sank under the scrambled
                        // handler bodies)
                        let legacy_active = self.legacy_try.is_some()
                            || self.legacy_handler.is_some()
                            || !self.legacy_nest.is_empty();
                        let mut region_ahead = false;
                        if !legacy_active {
                            for b in self.blocks.iter().rev() {
                                if matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                ) {
                                    break;
                                }
                                // an open-ended folded-chain block
                                // (Else[MAX]) has no bounded else arm
                                // awaiting the walk — py2's dead
                                // duplicate back edge after a continue
                                // would emit a SECOND Continue with the
                                // chain left open (ast 2.6
                                // generic_visit)
                                if matches!(b.kind, BlockType::If | BlockType::Else)
                                    && b.end > self.cur_next
                                    && b.end != usize::MAX
                                {
                                    // ...unless sibling mainline code
                                    // sits between the continue and the
                                    // block end: a jump target inside
                                    // [cur_next, end) reached from
                                    // OUTSIDE the block is the next arm
                                    // of an enclosing chain (an elif
                                    // test) — keeping the block open
                                    // would swallow it and trap the
                                    // post-loop tail in a dead else
                                    // (base64 3.5 a85decode). The
                                    // block's own else target IS its
                                    // end, excluded by the range; an
                                    // else arm starting right at
                                    // cur_next is the bdb shape and
                                    // keeps the block open.
                                    let sibling_inside = self
                                        .targets
                                        .iter()
                                        .any(|&t| {
                                            t >= self.cur_next
                                                && t < b.end
                                                && self
                                                    .instrs
                                                    .iter()
                                                    .any(|x| {
                                                        x.target == Some(t)
                                                            && (x.offset
                                                                < b.start
                                                                || x.offset
                                                                    >= b.end)
                                                    })
                                        });
                                    if !sibling_inside {
                                        region_ahead = true;
                                    }
                                }
                            }
                        }
                        if !region_ahead {
                            self.close_inner_blocks_to_loop();
                        }
                        return true;
                    }
                }
                if target > self.cur_offset {
                    // forward absolute jump (<=3.7 else/exit jumps). Inside
                    // an If/Else block it ends a then/else body; otherwise
                    // it skips over cleanup-handler code.
                    let in_branch = matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::If) | Some(BlockType::Else) | Some(BlockType::Try)
                    );
                    if in_branch {
                        return self.handle_jump_forward(target);
                    }
                    self.close_blocks_at(self.cur_offset);
                                        self.skip_until = Some(target);
                    return true;
                }
                self.handle_jump_backward(target);
                true
            }
            Op::JUMP | Op::JUMP_NO_INTERRUPT => {
                if inst.is_backward {
                    let target = inst.target.unwrap_or(0);
                    self.handle_jump_backward(target);
                } else {
                    let target = inst.target.unwrap_or(inst.end());
                    return self.handle_jump_forward(target);
                }
                true
            }
            Op::POP_JUMP_IF_FALSE
            | Op::POP_JUMP_FORWARD_IF_FALSE
            | Op::POP_JUMP_BACKWARD_IF_FALSE => {
                let target = inst.target.unwrap_or(inst.end());
                let cond = self.pop_expr();
                self.handle_cond_jump(cond, false, target);
                true
            }
            Op::POP_JUMP_IF_TRUE
            | Op::POP_JUMP_FORWARD_IF_TRUE
            | Op::POP_JUMP_BACKWARD_IF_TRUE => {
                let target = inst.target.unwrap_or(inst.end());
                let cond = self.pop_expr();
                self.handle_cond_jump(cond, true, target);
                true
            }
            Op::POP_JUMP_IF_NONE | Op::POP_JUMP_FORWARD_IF_NONE | Op::POP_JUMP_BACKWARD_IF_NONE => {
                let target = inst.target.unwrap_or(inst.end());
                let val = self.pop_expr();
                let cond = Rc::new(Expr::Compare {
                    operands: vec![val, Rc::new(Expr::Const(Rc::new(PyObject::None)))],
                    ops: vec![CmpOp::Is],
                });
                // jumps when the comparison is TRUE
                self.handle_cond_jump(cond, true, target);
                true
            }
            Op::POP_JUMP_IF_NOT_NONE
            | Op::POP_JUMP_FORWARD_IF_NOT_NONE
            | Op::POP_JUMP_BACKWARD_IF_NOT_NONE => {
                let target = inst.target.unwrap_or(inst.end());
                let val = self.pop_expr();
                let cond = Rc::new(Expr::Compare {
                    operands: vec![val, Rc::new(Expr::Const(Rc::new(PyObject::None)))],
                    ops: vec![CmpOp::IsNot],
                });
                self.handle_cond_jump(cond, true, target);
                true
            }
            Op::JUMP_IF_TRUE_OR_POP => {
                // `or`: if truthy jump keeping value, else pop and continue
                let target = inst.target.unwrap_or(inst.end());
                self.handle_short_circuit(true, target);
                true
            }
            Op::JUMP_IF_FALSE_OR_POP => {
                // `and`
                let target = inst.target.unwrap_or(inst.end());
                self.handle_short_circuit(false, target);
                true
            }
            Op::JUMP_IF_FALSE | Op::JUMP_IF_TRUE => {
                // py2 value-preserving cond jump. Two shapes:
                //   if-stmt:  JUMP_IF_FALSE L; POP_TOP; then; JUMP_FORWARD E;
                //             L: POP_TOP; else; E:
                //   value:    JUMP_IF_FALSE L; POP_TOP; b; L:   (and/or/ternary)
                let target = inst.target.unwrap_or(inst.end());
                let jump_if_true = inst.op == Op::JUMP_IF_TRUE;
                let ci = self.idx_of.get(&inst.offset).copied();
                let next_pop = ci
                    .and_then(|i| self.instrs.get(i + 1))
                    .map(|x| x.op == Op::POP_TOP)
                    .unwrap_or(false);
                let target_pop = self
                    .idx_of
                    .get(&target)
                    .and_then(|i| self.instrs.get(*i))
                    .map(|x| x.op == Op::POP_TOP)
                    .unwrap_or(false);
                if jump_if_true && next_pop {
                    // py2 `assert cond[, msg]`: JUMP_IF_TRUE L; POP_TOP;
                    // LOAD AssertionError; ...; RAISE 1; L:
                    if let Some(msg) = self.is_assert_fallthrough(target) {
                        let cond = self.pop_expr();
                        self.push_stmt(Stmt::Assert { test: cond, msg });
                                                self.skip_until = Some(target);
                        return true;
                    }
                }
                if next_pop && target_pop {
                    // py2.6 statement boolop chain: `if A and B:` / `elif
                    // C or D:` compile every link as JUMP_IF_* + POP_TOP —
                    // the same shape as the whole-statement jump. A chain
                    // is told apart by its then arm holding ANOTHER cond
                    // jump reachable through pure value ops only (the
                    // next link); statement bodies contain non-value ops.
                    // Fold the whole chain into one BoolOp condition and
                    // open the if from the final link.
                    let first = match (ci, self.stack.last()) {
                        (Some(_), Some(Sv::E(e))) => Some(e.clone()),
                        _ => None,
                    };
                    if let (Some(i0), Some(first)) = (ci, first) {
                        if let Some((cond, then_start, else_body, else_pop)) =
                            self.py26_stmt_boolop_chain(i0, first, jump_if_true, target)
                        {
                            self.pop(); // operand 0 (consumed by the fold)
                            self.py2_else_pop_at = Some(else_pop);
                                                        self.skip_until = Some(then_start);
                            self.handle_cond_jump(cond, false, else_body);
                            return true;
                        }
                    }
                    // py2.6 nested ternary: the then arm ends in a
                    // forward jump to a merge M and the else arm is a
                    // pure value region falling through to M — evaluate
                    // both arms recursively and merge on the stack
                    let tern = self.py2_ternary_at(ci, target);
                    if let Some((then_start, else_start, merge)) = tern {
                        let cond = self.pop_expr();
                        self.region_result_expr = None;
                        let _ = self.decompile_region(then_start, target);
                        let then_val = self
                            .region_result_expr
                            .take()
                            .unwrap_or_else(|| self.name_expr("???"));
                        self.region_result_expr = None;
                        let _ = self.decompile_region(else_start, merge);
                        let else_val = self
                            .region_result_expr
                            .take()
                            .unwrap_or_else(|| self.name_expr("???"));
                        self.push(Rc::new(Expr::Ternary {
                            cond,
                            then_expr: then_val,
                            else_expr: else_val,
                        }));
                                                self.skip_until = Some(merge);
                        return true;
                    }
                    // if-statement shape: both paths discard the value
                    let cond = self.pop_expr();
                    let else_body = self
                        .idx_of
                        .get(&target)
                        .map(|&ti| self.instrs[ti].end())
                        .unwrap_or(target);
                    self.py2_else_pop_at = Some(target);
                    // skip the then-branch POP_TOP (cond already popped)
                    if let Some(i) = ci {
                        if let Some(pop) = self.instrs.get(i + 1) {
                                                        self.skip_until = Some(pop.end());
                        }
                    }
                    self.handle_cond_jump(cond, jump_if_true, else_body);
                    return true;
                }
                // short-circuit / ternary shape: the target region carries a
                // value that merges at `target`
                let cond = match self.stack.last() {
                    Some(Sv::E(e)) => e.clone(),
                    _ => self.name_expr("???"),
                };
                let c = if jump_if_true {
                    simplify_not(cond)
                } else {
                    cond
                };
                let mut blk = Block::new(BlockType::If, self.cur_next, target);
                blk.cond = Some(c);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.value_merge = Some(if jump_if_true {
                    BoolOpKind::Or
                } else {
                    BoolOpKind::And
                });
                blk.else_end = Some(target);
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                true
            }
            Op::FOR_ITER => {
                if self.in_comp_region(inst.offset)
                    && !self.has_build_prologue(inst.offset)
                {
                    // additional generator of the SAME comprehension
                    // (`for x in A for y in B`)
                    self.push_nested_comp_gen();
                    return true;
                }
                if let Some(kind) = self.detect_inline_comp() {
                    self.start_inline_comp(kind, inst);
                    return true;
                }
                let target = inst.target.unwrap_or(inst.end());
                // async for: the iterable expression is an Await, or we are
                // inside an async def using GET_AITER
                let is_async = matches!(
                    self.stack.last(),
                    Some(Sv::E(e)) if matches!(&**e, Expr::Await(_))
                );
                if is_async {
                    if let Some(Sv::E(e)) = self.stack.last_mut() {
                        if let Expr::Await(inner) = &**e {
                            *e = inner.clone();
                        }
                    }
                }
                self.handle_for_iter(target, is_async);
                true
            }
            Op::FOR_LOOP => {
                if self.in_comp_region(inst.offset)
                    && !self.has_build_prologue(inst.offset)
                {
                    self.push_nested_comp_gen();
                    return true;
                }
                if let Some(kind) = self.detect_inline_comp() {
                    self.start_inline_comp(kind, inst);
                    return true;
                }
                // 3.14: FOR_LOOP with kind in low bits of arg
                let target = inst.target.unwrap_or(inst.end());
                self.handle_for_iter(target, false);
                true
            }
            Op::BREAK_LOOP => {
                self.push_stmt(Stmt::Break);
                if self.broken_loop_top.is_none() {
                    self.broken_loop_top = self
                        .blocks
                        .iter()
                        .rev()
                        .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
                        .map(|b| b.start);
                }
                true
            }

            // ---------- block setup (<= 3.10 era) ----------
            Op::SETUP_LOOP => {
                let target = inst.target.unwrap_or(inst.end());
                if !self.pending_stores.is_empty() {
                    self.flushing = true;
                    self.flush_pending_stores();
                    self.flushing = false;
                }
                let mut blk = Block::new(BlockType::While, inst.end(), target);
                blk.cond_set = false;
                self.blocks.push(blk);
                true
            }
            Op::SETUP_EXCEPT => {
                // compiler-internal exception-state finally inside a
                // legacy handler body (e.g. `raise` in except on 3.8-3.10)
                if self.legacy_handler.is_some() {
                    // <=3.7: a REAL nested try inside the handler body —
                    // save the outer chain, let the nested chain parse in
                    // the single slots, restore before its Try is emitted
                    // (push_stmt then routes it into the outer handler body)
                    if !self.version.at_least(3, 8) {
                        self.begin_legacy_nest();
                    } else {
                        return true;
                    }
                }
                // 3.5-3.7 async-for per-iteration guard:
                //   SETUP_LOOP; iter; GET_AITER; SETUP_EXCEPT -> H;
                //   GET_ANEXT; LOAD None; YIELD_FROM; STORE; POP_BLOCK;
                //   JUMP_FORWARD -> body; H: DUP_TOP; LOAD StopAsyncIteration;
                //   COMPARE_OP exc-match; PJIT -> unwind; END_FINALLY;
                //   unwind: POP_TOP x3; POP_EXCEPT; POP_TOP; POP_BLOCK
                // The guard is loop machinery, not a source-level try:
                // open the async For block HERE (the back edge targets this
                // SETUP_EXCEPT) and absorb the handler when reached.
                if !self.version.at_least(3, 8) {
                    if let Some(t) = inst.target {
                        let is_guard = self
                            .idx_of
                            .get(&t)
                            .map_or(false, |&hi| {
                                self.instrs[hi].op == Op::DUP_TOP
                                    && self.instrs[hi + 1..]
                                        .iter()
                                        .take(3)
                                        .any(|x| {
                                            x.op == Op::LOAD_GLOBAL
                                                && self.const_name(x.arg as usize)
                                                    == "StopAsyncIteration"
                                        })
                            })
                            && self
                                .idx_of
                                .get(&inst.offset)
                                .map_or(false, |&si| {
                                    self.instrs[si + 1..]
                                        .iter()
                                        .take(2)
                                        .any(|x| x.op == Op::GET_ANEXT)
                                });
                        if is_guard {
                            // the exhaustion unwind tail starts at the
                            // guard handler's PJIT target; it ends at the
                            // POP_BLOCK whose next instruction is the loop
                            // continuation
                            let mut unwind = usize::MAX;
                            let mut exit = usize::MAX;
                            if let Some(&hi) = self.idx_of.get(&t) {
                                for k in hi..self.instrs.len().min(hi + 8) {
                                    if matches!(
                                        self.instrs[k].op,
                                        Op::POP_JUMP_IF_TRUE | Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE
                                    ) && unwind == usize::MAX
                                        && k > hi
                                    {
                                        unwind = self.instrs[k].target.unwrap_or(usize::MAX);
                                    }
                                }
                                if unwind != usize::MAX {
                                    if let Some(&ui) = self.idx_of.get(&unwind) {
                                        for ins in self.instrs[ui..].iter().take(12) {
                                            if ins.op == Op::POP_BLOCK {
                                                if let Some(&pi) =
                                                    self.idx_of.get(&ins.offset)
                                                {
                                                    exit = self
                                                        .instrs
                                                        .get(pi + 1)
                                                        .map(|x| x.offset)
                                                        .unwrap_or(usize::MAX);
                                                }
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                            self.async_for_guard = Some((t, unwind, exit));
                            let mut fb =
                                Block::new(BlockType::For, inst.offset, usize::MAX);
                            fb.is_async = true;
                            fb.cond_set = true;
                            // a SETUP_LOOP placeholder may be open: absorb it
                            // (it would render as a bogus `while True`)
                            if let Some(top) = self.blocks.last() {
                                if matches!(top.kind, BlockType::While) && !top.cond_set {
                                    fb.for_setup_end = Some(top.end);
                                }
                            }
                            while let Some(top) = self.blocks.last() {
                                if matches!(top.kind, BlockType::While) && !top.cond_set {
                                    self.blocks.pop();
                                } else {
                                    break;
                                }
                            }
                            self.blocks.push(fb);
                            return true;
                        }
                    }
                }
                // stores before the try belong to the enclosing block
                if !self.pending_stores.is_empty() {
                    self.flushing = true;
                    self.flush_pending_stores();
                    self.flushing = false;
                }
                let target = inst.target.unwrap_or(inst.end());
                self.blocks.push(Block::new(BlockType::Try, inst.end(), target));
                true
            }
            Op::SETUP_FINALLY => {
                // 2.6 with statement: the enter result was stashed in a
                // synthetic temp and the setup targets WITH_CLEANUP:
                //   ctx; DUP_TOP; LOAD_ATTR __exit__; ROT_TWO;
                //   LOAD_ATTR __enter__; CALL 0; STORE _[N];
                //   SETUP_FINALLY -> WITH_CLEANUP; LOAD _[N]; DELETE; [STORE as]
                if self.version.major == 2
                    && inst.target.map_or(false, |t| {
                        self.idx_of
                            .get(&t)
                            .map_or(false, |&ti| self.instrs[ti].op == Op::WITH_CLEANUP)
                    })
                {
                    // the bound __exit__ sits on the stack; its receiver is
                    // the context manager. The no-as form POP_TOPs it right
                    // here instead of stashing it.
                    let exit_e = self.pop_expr();
                    let ctx_e = match &*exit_e {
                        Expr::Attribute { value, .. } => value.clone(),
                        _ => exit_e,
                    };
                    self.with_exits += 1;
                    let item = WithItem {
                        ctx: ctx_e,
                        target: None,
                    };
                    let start = inst.end();
                    let end = inst.target.unwrap_or(usize::MAX);
                    let mut wb = Block::new(BlockType::With, start, end);
                    wb.with_item = Some(item);
                    self.blocks.push(wb);
                    // the stashed enter result reloads as the placeholder
                    // so the following store becomes the `as` target
                    let ph = Sv::E(self.name_expr(WITH_RESULT_PLACEHOLDER));
                    for (_, v) in self.py26_temps.iter_mut() {
                        *v = ph.clone();
                    }
                    return true;
                }
                // <=3.10 async-for wrapper: SETUP_FINALLY targeting
                // END_ASYNC_FOR is loop machinery, not a source-level
                // try/finally — swallow it (GET_ANEXT opens the loop)
                if !self.version.at_least(3, 11) {
                    if let Some(t) = inst.target {
                        if self
                            .idx_of
                            .get(&t)
                            .map_or(false, |&ti| self.instrs[ti].op == Op::END_ASYNC_FOR)
                        {
                            return true;
                        }
                    }
                }
                // compiler-internal exception-state finally inside a
                // legacy handler body (e.g. `raise` in except on 3.8-3.10)
                if self.legacy_handler.is_some() {
                    // 3.3-3.7 wrap the implicit `as`-name cleanup in a
                    // SETUP_FINALLY whose handler is exactly
                    // `LOAD None; STORE n; DELETE n; END_FINALLY` (also
                    // around `raise ... from` inside except) — internal,
                    // swallow it; a REAL nested try/finally gets the
                    // nesting treatment
                    let as_cleanup = self
                        .idx_of
                        .get(&inst.target.unwrap_or(usize::MAX))
                        .map_or(false, |&ti| {
                            matches!(self.instrs[ti].op, Op::LOAD_CONST)
                                && self
                                    .code
                                    .consts
                                    .get(self.instrs[ti].arg as usize)
                                    .map_or(false, |c| matches!(&**c, PyObject::None))
                                && matches!(
                                    self.instrs.get(ti + 1).map(|x| x.op),
                                    Some(Op::STORE_FAST) | Some(Op::STORE_NAME) | Some(Op::STORE_DEREF)
                                )
                                && matches!(
                                    self.instrs.get(ti + 2).map(|x| x.op),
                                    Some(Op::DELETE_FAST) | Some(Op::DELETE_NAME) | Some(Op::DELETE_DEREF)
                                )
                                && matches!(
                                    self.instrs.get(ti + 3).map(|x| x.op),
                                    Some(Op::END_FINALLY)
                                )
                        });
                    // 3.8-3.10 `except ... as n:` cleanup wrappers end in
                    // RERAISE 1 instead of END_FINALLY — recognize both so
                    // a genuine nested try is not mistaken for a wrapper
                    let as_cleanup_reraise = self
                        .idx_of
                        .get(&inst.target.unwrap_or(usize::MAX))
                        .map_or(false, |&ti| {
                            matches!(self.instrs[ti].op, Op::LOAD_CONST)
                                && self
                                    .code
                                    .consts
                                    .get(self.instrs[ti].arg as usize)
                                    .map_or(false, |c| matches!(&**c, PyObject::None))
                                && matches!(
                                    self.instrs.get(ti + 1).map(|x| x.op),
                                    Some(Op::STORE_FAST) | Some(Op::STORE_NAME) | Some(Op::STORE_DEREF)
                                )
                                && matches!(
                                    self.instrs.get(ti + 2).map(|x| x.op),
                                    Some(Op::DELETE_FAST) | Some(Op::DELETE_NAME) | Some(Op::DELETE_DEREF)
                                )
                                && matches!(self.instrs.get(ti + 3).map(|x| x.op), Some(Op::RERAISE))
                        });
                    let as_cleanup_reraise = self
                        .idx_of
                        .get(&inst.target.unwrap_or(usize::MAX))
                        .map_or(false, |&ti| {
                            matches!(self.instrs[ti].op, Op::LOAD_CONST)
                                && self
                                    .code
                                    .consts
                                    .get(self.instrs[ti].arg as usize)
                                    .map_or(false, |c| matches!(&**c, PyObject::None))
                                && matches!(
                                    self.instrs.get(ti + 1).map(|x| x.op),
                                    Some(Op::STORE_FAST) | Some(Op::STORE_NAME) | Some(Op::STORE_DEREF)
                                )
                                && matches!(
                                    self.instrs.get(ti + 2).map(|x| x.op),
                                    Some(Op::DELETE_FAST) | Some(Op::DELETE_NAME) | Some(Op::DELETE_DEREF)
                                )
                                && matches!(self.instrs.get(ti + 3).map(|x| x.op), Some(Op::RERAISE))
                        });
                    if !as_cleanup && !as_cleanup_reraise {
                        self.begin_legacy_nest();
                    } else {
                        if as_cleanup {
                            // record the wrapper's own END_FINALLY (inside
                            // the cleanup handler) so the chain machine
                            // does not mistake it for the chain end
                            if let Some(t) = inst.target {
                                if let Some(&ti) = self.idx_of.get(&t) {
                                    for ins in self.instrs[ti..].iter().take(6) {
                                        if ins.op == Op::END_FINALLY {
                                            self.as_cleanup_wrappers
                                                .push((inst.offset, ins.offset));
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        return true;
                    }
                }
                // stores before the try belong to the enclosing block
                if !self.pending_stores.is_empty() {
                    self.flushing = true;
                    self.flush_pending_stores();
                    self.flushing = false;
                }
                let target = inst.target.unwrap_or(inst.end());
                if self.version.at_least(3, 8) {
                    // 3.8+: also used for except handlers; the legacy chain
                    // machinery decides except-vs-finally at close time
                    let mut t = Block::new(BlockType::Try, inst.end(), target);
                    self.blocks.push(t);
                } else {
                    let mut cont = Block::new(BlockType::Container, inst.end(), usize::MAX);
                    cont.finally_target = Some(target);
                    self.blocks.push(cont);
                    let mut t = Block::new(BlockType::Try, inst.end(), target);
                    t.finally_target = Some(target);
                    self.blocks.push(t);
                }
                true
            }
            Op::SETUP_CLEANUP => {
                // compiler-internal exception-state finally inside a
                // legacy handler body (e.g. `raise` in except on 3.8-3.10)
                if self.legacy_handler.is_some() {
                    return true;
                }
                let target = inst.target.unwrap_or(inst.end());
                let mut t = Block::new(BlockType::Try, inst.end(), target);
                self.blocks.push(t);
                true
            }
            Op::SETUP_WITH => {
                self.handle_with_setup(inst.target, false);
                true
            }
            Op::SETUP_ASYNC_WITH => {
                self.handle_with_setup(inst.target, true);
                true
            }
            Op::BEFORE_ASYNC_WITH => {
                if self.version.at_least(3, 11) {
                    // 3.10+/3.11+: like BEFORE_WITH but awaits __aenter__
                    let ctx_e = self.pop_expr();
                    self.with_exits += 1;
                    let item = WithItem {
                        ctx: ctx_e,
                        target: None,
                    };
                    let start = inst.end();
                    let end = self
                        .with_regions
                        .get(&start)
                        .copied()
                        .or_else(|| {
                            // the __aenter__ await protocol (GET_AWAITABLE
                            // ..SEND..END_SEND, possibly a CLEANUP_THROW
                            // trampoline) sits between BEFORE_ASYNC_WITH and
                            // the protected body — protocol-fragment entries
                            // (e.g. RESUME..STORE for a NESTED async with)
                            // must not define the span; find the first
                            // non-protocol instruction and take its region
                            let body_at = self
                                .instrs
                                .iter()
                                .skip_while(|x| x.offset < start)
                                .take(20)
                                .find(|x| {
                                    !matches!(
                                        x.op,
                                        Op::GET_AWAITABLE
                                            | Op::SEND
                                            | Op::YIELD_VALUE
                                            | Op::RESUME
                                            | Op::RESUME_CHECK
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            | Op::END_SEND
                                            | Op::CLEANUP_THROW
                                            | Op::LOAD_CONST
                                            | Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::END_ASYNC_FOR
                                    )
                                })
                                .map(|x| x.offset)?;
                            self.with_regions.get(&body_at).copied().or_else(|| {
                                self.instrs
                                    .iter()
                                    .skip_while(|x| x.offset < body_at)
                                    .take(20)
                                    .find_map(|x| {
                                        self.with_regions.get(&x.offset).copied()
                                    })
                            })
                        })
                        .unwrap_or(usize::MAX);
                    let mut wb = Block::new(BlockType::With, start, end);
                    wb.is_async = true;
                    wb.with_item = Some(item);
                    self.blocks.push(wb);
                    self.push(self.name_expr(WITH_RESULT_PLACEHOLDER));
                } else {
                    // <=3.10: pushes the __aenter__ awaitable; the With block
                    // is opened by the following SETUP_ASYNC_WITH using the
                    // stashed context expression
                    let ctx_e = self.pop_expr();
                    self.pending_async_with_ctx = Some(ctx_e);
                    self.push(self.name_expr(WITH_RESULT_PLACEHOLDER));
                }
                true
            }
            Op::BEFORE_WITH => {
                // 3.11+: pushes __exit__ then result; block boundary comes
                // from the exception table entry that starts right after.
                let ctx_e = self.pop_expr();
                // the VM's BEFORE_WITH consumes ONLY the context manager;
                // the bound __exit__ it pushes is never modeled here. The
                // historical second pop_expr underflowed on every plain
                // with (spurious "Decompyle incomplete" across ALL 3.11+
                // with-modules: b08_with PASS-WARN, _compression
                // readinto, t_singlewith). Consume leftover NULL markers
                // (3.11+ LOAD_ATTR NULL|self) but no real second value.
                while matches!(self.stack.last(), Some(Sv::Null)) {
                    self.stack.pop();
                }
                self.with_exits += 1;
                let item = WithItem {
                    ctx: ctx_e,
                    target: None,
                };
                self.pending_with.push(vec![item]);
                self.push(self.name_expr(WITH_RESULT_PLACEHOLDER));
                // open a With block spanning the PROTECTED BODY: it ends
                // where the body ends (the inline __exit__ call and the
                // out-of-line cleanup handler follow). Using the handler
                // target here swallows sequential following statements
                // into the with body.
                let start = inst.end();
                let mut end = self
                    .with_regions
                    .get(&start)
                    .copied()
                    .or_else(|| {
                        self.exc_entries
                            .iter()
                            .find(|e| e.start == start || e.start == inst.end())
                            .map(|e| e.end)
                    })
                    .unwrap_or(usize::MAX);
                // a nested try chain SPLITS the with body into same-handler
                // fragments (codeop _maybe_compile): extend the block end
                // over the chain material when the shape vets out
                let end = self.extend_with_frag_end(start, end);
                let mut wb = Block::new(BlockType::With, start, end);
                wb.is_async = false;
                self.blocks.push(wb);
                true
            }
            Op::POP_BLOCK => {
                if self.legacy_handler.is_none() {
                    self.handle_pop_block();
                }
                true
            }
            Op::POP_EXCEPT => {
                if let Some(top) = self.blocks.last() {
                    if top.kind == BlockType::Except {
                        let pos = inst.offset;
                        self.force_close_top(pos);
                    }
                }
                // POP_EXCEPT drops the (unmodeled) exception state. When
                // live body values sit on the simulated stack the cleanup
                // slots are already balanced out — popping would eat the
                // body value (3.9+ terminating handlers and 3.11+ computed
                // returns: `expr; SWAP; POP_EXCEPT; as-cleanup; RETURN`)
                let live_values = self.stack.iter().any(|s| matches!(s, Sv::E(_)));
                let next_returns = self
                    .idx_of
                    .get(&inst.offset)
                    .and_then(|&pi| self.instrs.get(pi + 1))
                    .map_or(false, |nx| {
                        matches!(nx.op, Op::RETURN_VALUE | Op::RETURN_CONST)
                    });
                if !next_returns && !live_values {
                    self.pop();
                }
                true
            }
            Op::END_FINALLY => {
                if self.legacy_handler.is_some() {
                    // internal cleanup inside a handler body
                    self.pop();
                    return true;
                }
                self.pop();
                self.close_finally();
                true
            }
            Op::WITH_CLEANUP => {
                // py2 / <=3.4: pops exception state + 3 exits
                self.pop();
                self.with_exits = self.with_exits.saturating_sub(1);
                self.handle_with_body_end();
                true
            }
            Op::WITH_CLEANUP_START => {
                self.with_exits = self.with_exits.saturating_sub(1);
                true
            }
            Op::WITH_CLEANUP_FINISH => {
                self.handle_with_body_end();
                true
            }
            Op::WITH_EXCEPT_START => {
                // pre-3.11: the linear walk FELL THROUGH into a
                // registered exception-time with handler (every normal
                // flow ends in a RETURN or a JF over it) — the region
                // is exception-only; skip it whole (aifc 3.10
                // __main__: the handler's PJIT-swallow rendered
                // `if not None: pass` at module tail)
                if !self.version.at_least(3, 11)
                    && self.with_handler_starts.contains(&self.cur_offset)
                {
                    let end = self.with_handler_skip_end(self.cur_offset);
                    if self.skip_until.map_or(true, |s| s < end) {
                        self.skip_until = Some(end);
                    }
                    self.with_exits = self.with_exits.saturating_sub(1);
                    return true;
                }
                // 3.11+: result of __exit__ call on top; then POP_EXCEPT etc.
                self.pop();
                self.with_exits = self.with_exits.saturating_sub(1);
                true
            }
            Op::CHECK_EXC_MATCH => {
                let pattern = self.pop_expr();
                let exc = self.pop_expr();
                self.push(exc);
                self.push(pattern);
                true
            }
            Op::CHECK_EG_MATCH => {
                self.pop();
                self.pop();
                true
            }
            Op::RERAISE => {
                for _ in 0..=arg.min(2) {
                    self.pop();
                }
                true
            }
            Op::PREP_RERAISE_STAR => {
                self.pop();
                self.pop();
                true
            }
            Op::CLEANUP_THROW => {
                // 3.12+ await/resume protocols embed a CLEANUP_THROW
                // trampoline right before END_SEND (throw path of the
                // suspended YIELD_VALUE); the linear walk falls through
                // it and its pops would eat the protocol's live stack
                // (e.g. the async-with __aenter__ result placeholder).
                // Dead padding in that position — skip it.
                let next_is_end_send = self
                    .idx_of
                    .get(&self.cur_next)
                    .map_or(false, |&ni| self.instrs[ni].op == Op::END_SEND);
                if !(next_is_end_send && self.skip_end_send) {
                    self.pop();
                    self.pop();
                }
                true
            }
            Op::CALL_FINALLY => {
                // 3.8 alpha era: `POP_BLOCK; CALL_FINALLY h; <body ending
                // in RETURN>` — the finally at h runs before the return
                // resumes. Parse the handler as the finalbody and fold
                // the deferred legacy try here.
                let target = inst.target.unwrap_or(inst.end());
                // 3.8 `except E as e: return <expr>` wraps the return in
                // an as-cleanup SETUP_FINALLY whose handler is exactly
                // `None; STORE e; DELETE e` — not a real finally; leave
                // that idiom to the legacy cleanup machinery
                let as_cleanup_wrapper = self
                    .idx_of
                    .get(&target)
                    .map_or(false, |&hi| {
                        matches!(self.instrs.get(hi).map(|x| x.op), Some(Op::LOAD_CONST))
                            && matches!(
                                self.instrs.get(hi + 1).map(|x| x.op),
                                Some(Op::STORE_FAST) | Some(Op::STORE_NAME) | Some(Op::STORE_DEREF)
                            )
                            && matches!(
                                self.instrs.get(hi + 2).map(|x| x.op),
                                Some(Op::DELETE_FAST) | Some(Op::DELETE_NAME) | Some(Op::DELETE_DEREF)
                            )
                    });
                // skip the fold only while THIS finally's own try block
                // is still open (the break-path variant rebuilds below);
                // an enclosing try belonging to a LATER finally must not
                // block the inner fold (nested `return` in try/finally)
                let try_open = self.blocks.iter().any(|b| {
                    b.kind == BlockType::Try
                        && (b.finally_target == Some(target) || b.end == target)
                });
                // inside a nested-chain region sub-walk
                // (parse_skipped_nested_chain), a CALL_FINALLY belongs to
                // the HANDLER body's own return protocol — folding here
                // would consume the chain being parsed (g3 `except E:
                // return 2`)
                if self.legacy_try.is_some()
                    && !as_cleanup_wrapper
                    && !try_open
                    && self.legacy_nest_depth == 0
                {
                    let fin_stop = self
                        .idx_of
                        .get(&target)
                        .and_then(|&hi| {
                            self.instrs[hi..]
                                .iter()
                                .take(200)
                                .find(|x| {
                                    matches!(
                                        x.op,
                                        Op::END_FINALLY | Op::RERAISE | Op::JUMP_ABSOLUTE
                                    )
                                })
                                .map(|x| x.offset)
                        })
                        .unwrap_or(target);
                    let fin = if fin_stop > target {
                        self.decompile_region(target, fin_stop)
                    } else {
                        Vec::new()
                    };
                    let lt = self.legacy_try.take().unwrap();
                    let handlers = lt.handlers;
                    // the legacy try keeps its body on the LegacyTry
                    // record (pending_try_body stays empty pre-3.11)
                    let mut body = if lt.body.is_empty() {
                        std::mem::take(&mut self.pending_try_body).pop().unwrap_or_default()
                    } else {
                        lt.body
                    };
                    // 3.8 computed `try: return expr finally:`: the
                    // value rides UNDER the CALL_FINALLY slot and the
                    // RETURN right after this jump belongs to the try
                    // BODY — fold it in, or it renders after the Try
                    // (cProfile 3.8 runcall: `try: pass finally:
                    // self.disable()` + stray `return func(*args, **kw)`;
                    // the sig lost the CALL_FINALLY; RETURN shape)
                    let mut folded_return = false;
                    if self
                        .idx_of
                        .get(&self.cur_next)
                        .map_or(false, |&ni| {
                            self.instrs[ni].op == Op::RETURN_VALUE
                        })
                        && matches!(self.stack.last(), Some(Sv::E(_)))
                        && !self.chain_has_exc_dispatch(target)
                    {
                        if let Some(Sv::E(v)) = self.stack.pop() {
                            body.push(Stmt::Return(Some(v)));
                            folded_return = true;
                        }
                    }
                    // nested try/except INSIDE try/finally (3.8-3.10):
                    // the second POP_BLOCK stashed the inner chain in
                    // legacy_nest, and its handler region sits BETWEEN
                    // the folded RETURN and this finally copy — the
                    // linear walk never reaches it and the clauses were
                    // silently dropped (bdb 3.8/3.9 runeval `try:
                    // return eval() except BdbQuit: pass finally:` lost
                    // the except). Parse the stashed chain now and wrap
                    // the folded body in its Try.
                    if folded_return && !self.legacy_nest.is_empty() {
                        let ni = self.legacy_nest.len() - 1;
                        let grab = self.legacy_nest[ni]
                            .outer_try
                            .as_ref()
                            .map_or(false, |l| {
                                l.handlers.is_empty()
                                    && !l.chain_done
                                    && l.handler_start > self.cur_offset
                                    && l.handler_start < target
                            });
                        if grab {
                            let inner =
                                self.legacy_nest[ni].outer_try.take().unwrap();
                            let hs = inner.handler_start;
                            self.legacy_try = Some(inner);
                            // clamp the sub-walk at the chain's own
                            // END_FINALLY (the mismatch re-raise) when
                            // it lies before the finally copy: past it
                            // sit the outer chain's POP_BLOCK /
                            // BEGIN_FINALLY bridge instructions
                            let chain_end = self
                                .idx_of
                                .get(&hs)
                                .and_then(|&hi| {
                                    self.instrs[hi..]
                                        .iter()
                                        .take(200)
                                        .take_while(|x| x.offset < target)
                                        .find(|x| x.op == Op::END_FINALLY)
                                        .map(|x| x.offset)
                                })
                                .unwrap_or(target);
                            self.parse_skipped_nested_chain(chain_end);
                            if let Some(mut inner) = self.legacy_try.take() {
                                if !inner.handlers.is_empty() {
                                    inner.body = body;
                                    body = vec![Stmt::Try {
                                        body: inner.body,
                                        handlers: std::mem::take(
                                            &mut inner.handlers,
                                        ),
                                        orelse: std::mem::take(
                                            &mut inner.orelse,
                                        ),
                                        finalbody: Vec::new(),
                                    }];
                                }
                            }
                            self.legacy_handler = None;
                            self.legacy_handler_end = None;
                        }
                    }
                    if !handlers.is_empty() || !fin.is_empty() {
                        self.push_stmt(Stmt::Try {
                            body,
                            handlers,
                            orelse: Vec::new(),
                            finalbody: fin,
                        });
                    } else {
                        self.push_stmt_all(body);
                    }
                    // the handler region is folded; the flow continues
                    // with the return value right after this jump
                    if folded_return {
                        if let Some(&ni) = self.idx_of.get(&self.cur_next) {
                            if let Some(after) = self.instrs.get(ni + 1) {
                                // try/except/finally (3.8): the except
                                // chain sits between the folded return
                                // and the finally copy — its clauses are
                                // already rendered, so hop the walk to
                                // the copy (bdb 3.8 runeval: resuming at
                                // the chain head double-walked it and
                                // marked the module unclean)
                                let resume = if after.op == Op::DUP_TOP
                                    && self.chain_has_exc_dispatch(after.offset)
                                {
                                    target
                                } else {
                                    after.offset
                                };
                                if self
                                    .skip_until
                                    .map_or(true, |s| s < resume)
                                {
                                    self.skip_until = Some(resume);
                                }
                            }
                        }
                    }
                    self.legacy_handler = None;
                    self.legacy_handler_end = None;
                } else if !as_cleanup_wrapper
                    && !self.version.at_least(3, 11)
                    && matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::If)
                    )
                    && self
                        .blocks
                        .iter()
                        .any(|b| matches!(b.kind, BlockType::While | BlockType::For))
                {
                    // 3.8 break-in-try/finally: the break path is
                    //   POP_BLOCK; CALL_FINALLY h; [POP_TOP;] JABS exit
                    // with ONE shared finally copy at h ending in the
                    // loop back edge — rebuild the split try from spans
                    let n = self.blocks.len();
                    let ii = n - 1;
                    let ti = (0..ii)
                        .rev()
                        .find(|&i| self.blocks[i].kind == BlockType::Try);
                    if std::env::var("PYCDC_EG_DBG").is_ok() {
                        eprintln!(
                            "EG cf-split [{}] pos={} target={} ti={:?} ii={} blocks={:?}",
                            self.code.name, self.cur_offset, target, ti, ii,
                            self.blocks.iter().map(|b| format!("{:?}", b.kind)).collect::<Vec<_>>()
                        );
                    }
                    // the break path's exit jump: any jump between here
                    // and the handler that lands PAST the handler (3.8
                    // uses a forward JUMP_ABSOLUTE to the loop exit)
                    let exit_jump = self.instrs.iter().find(|x| {
                        x.offset > self.cur_offset
                            && x.offset < target
                            && matches!(
                                x.op,
                                Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP
                            )
                            && x.target.map_or(false, |t| t > target)
                    });
                    let exit_target = exit_jump.and_then(|x| x.target);
                    if let (Some(ti), Some(exit_at)) = (ti, exit_target) {
                        let b2_start = self.blocks[ii].end;
                        let try_start = self.blocks[ti].start;
                        let pb2 = self
                            .instrs
                            .iter()
                            .find(|x| x.offset >= b2_start && x.op == Op::POP_BLOCK)
                            .map(|x| x.offset);
                        let fin_stop = self
                            .idx_of
                            .get(&target)
                            .and_then(|&hi| {
                                self.instrs[hi..]
                                    .iter()
                                    .take(200)
                                    .find(|x| {
                                        matches!(
                                            x.op,
                                            Op::END_FINALLY
                                                | Op::RERAISE
                                                | Op::JUMP_ABSOLUTE
                                        )
                                    })
                                    .map(|x| x.offset)
                            })
                            .unwrap_or(target);
                        let cond_jump = self
                            .instrs
                            .iter()
                            .find(|x| {
                                x.offset >= try_start
                                    && x.offset < b2_start
                                    && matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                    )
                                    && x.target == Some(b2_start)
                            })
                            .map(|x| (x.offset, x.op));
                        if std::env::var("PYCDC_EG_DBG").is_ok() {
                            eprintln!(
                                "EG cf-split2 b2={} pb2={:?} fin_stop={} cj={:?}",
                                b2_start, pb2, fin_stop, cond_jump
                            );
                        }
                        if let (Some(pb2), Some((cj_off, cj_op))) = (pb2, cond_jump) {
                            if pb2 < target && fin_stop > target {
                                while self.blocks.len() > ti {
                                    self.blocks.pop();
                                }
                                self.legacy_try = None;
                                self.legacy_handler = None;
                                self.legacy_handler_end = None;
                                self.region_result_expr = None;
                                let _ = self.decompile_region(try_start, cj_off);
                                let mut cond_e = self
                                    .region_result_expr
                                    .take()
                                    .unwrap_or_else(|| self.name_expr("???"));
                                if matches!(
                                    cj_op,
                                    Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                                ) {
                                    cond_e = Rc::new(Expr::Unary {
                                        op: UnaryOp::Not,
                                        operand: cond_e,
                                    });
                                }
                                let mut body = vec![Stmt::If {
                                    cond: cond_e,
                                    body: vec![Stmt::Break],
                                    orelse: Vec::new(),
                                }];
                                body.extend(self.decompile_region(b2_start, pb2));
                                let fin = self.decompile_region(target, fin_stop);
                                self.push_stmt(Stmt::Try {
                                    body,
                                    handlers: Vec::new(),
                                    orelse: Vec::new(),
                                    finalbody: fin,
                                });
                                                                self.skip_until = Some(exit_at);
                                return true;
                            }
                        }
                    }
                    if let Some(top) = self.blocks.last_mut() {
                        top.finally_target = Some(target);
                    }
                } else if let Some(top) = self.blocks.last_mut() {
                    top.finally_target = Some(target);
                }
                // 3.8 computed `try: return expr finally:`: the value
                // rides UNDER the CALL_FINALLY slot and the RETURN right
                // after it belongs to the try BODY — fold it into the
                // pending body now, or it renders after the Try (cProfile
                // 3.8 runcall: `try: pass finally: self.disable()` +
                // stray `return func(*args, **kw)`; the sig lost the
                // CALL_FINALLY; RETURN body shape)
                self.stack.push(Sv::Null);
                true
            }
            Op::POP_FINALLY => {
                self.pop();
                self.close_finally();
                true
            }
            Op::JUMP_IF_NOT_EXC_MATCH => {
                let target = inst.target.unwrap_or(inst.end());
                let pattern = self.pop_expr();
                // the exception value comes from VM state we do not model;
                // popping an empty stack here is not an error
                let exc = match self.stack.pop() {
                    Some(Sv::E(e)) => e,
                    Some(_) | None => Rc::new(Expr::Name("__exc__".to_string())),
                };
                let cond = Rc::new(Expr::Compare {
                    operands: vec![exc, pattern],
                    ops: vec![CmpOp::ExceptionMatch],
                });
                self.handle_cond_jump(cond, true, target);
                true
            }
            Op::RAISE_VARARGS => {
                // 3.8-3.10 sunk tail-raise pair (see sunk_raise_pair_side):
                // drop the success-side copy; at the handler-side copy
                // flush the chain first so the raise renders AFTER the Try
                if arg >= 1 && self.version.major == 3 {
                    match self.sunk_raise_pair_side(inst.offset, arg) {
                        Some(true) => {
                            for _ in 0..arg {
                                self.pop();
                            }
                            return true;
                        }
                        Some(false) => {
                            if let Some(l) = self.legacy_try.take() {
                                self.push_legacy_try(l);
                            }
                        }
                        None => {}
                    }
                }
                let r = match arg {
                0 => {
                    self.push_stmt(Stmt::Raise {
                        exc: None,
                        cause: None,
                        py2_inst: None,
                        py2_tb: None,
                    });
                    true
                }
                1 => {
                    let exc = self.pop_expr();
                    self.push_stmt(Stmt::Raise {
                        exc: Some(exc),
                        cause: None,
                        py2_inst: None,
                        py2_tb: None,
                    });
                    true
                }
                _ => {
                    if self.version.major == 2 {
                        // py2 `raise type, inst[, tb]`: render the native
                        // form - it recompiles to identical bytecode (the
                        // old Call-instantiation rewrite could never
                        // sig-match and dropped the traceback)
                        let tb = if arg >= 3 {
                            Some(self.pop_expr())
                        } else {
                            None
                        };
                        let inst = self.pop_expr();
                        let ty = self.pop_expr();
                        self.push_stmt(Stmt::Raise {
                            exc: Some(ty),
                            cause: None,
                            py2_inst: Some(inst),
                            py2_tb: tb,
                        });
                        return true;
                    }
                    let cause = self.pop_expr();
                    let exc = self.pop_expr();
                    self.push_stmt(Stmt::Raise {
                        exc: Some(exc),
                        cause: Some(cause),
                        py2_inst: None,
                        py2_tb: None,
                    });
                    true
                }
                };
                // 3.12+ drops the dead JUMP_FORWARD that <=3.11 emitted
                // after an arm-terminating raise: the next offset can be
                // an else-arm label belonging to an ENCLOSING branch
                // while the raise's own If spans past it — statements
                // there would leak into the raise's then arm
                // (_compression 3.12 read: `rawblock = b''` landed after
                // the EOFError raise). Close the terminated arm(s) now.
                if r {
                    self.close_terminated_branch_arms();
                }
                r
            },

            // ---------- py2 print / exec ----------
            Op::PRINT_ITEM => {
                let v = self.pop_expr();
                let at = self.cur_offset;
                self.pending_print.push((at, v));
                true
            }
            Op::PRINT_ITEM_TO => {
                // `print >> file, value`: bytecode is
                //   [file]; DUP_TOP; [value]; ROT_TWO  ->  [file, value, file]
                // so the stream copy is on TOP and the item is below it.
                // PRINT_ITEM_TO pops the stream first, then the item (the
                // original [file] stays for PRINT_NEWLINE_TO). Popping in the
                // reverse order rendered the file expr as the printed value.
                self.pop(); // the DUPed stream copy (top)
                let v = self.pop_expr(); // the item
                let at = self.cur_offset;
                self.pending_print.push((at, v));
                true
            }
            Op::PRINT_NEWLINE => {
                let values = std::mem::take(&mut self.pending_print)
                    .into_iter()
                    .map(|(_, v)| v)
                    .collect();
                let dest = self.pending_print_dest.take();
                self.push_stmt(Stmt::Print {
                    dest,
                    values,
                    newline: true,
                });
                true
            }
            Op::PRINT_NEWLINE_TO => {
                let values = std::mem::take(&mut self.pending_print)
                    .into_iter()
                    .map(|(_, v)| v)
                    .collect();
                let dest = self.pop_expr();
                self.push_stmt(Stmt::Print {
                    dest: Some(dest),
                    values,
                    newline: true,
                });
                true
            }
            Op::PRINT_EXPR => {
                // interactive-mode only; treat as expression statement
                let e = self.pop_expr();
                self.push_stmt(Stmt::Expr(e));
                true
            }
            Op::EXEC_STMT => {
                let locals = self.pop_expr();
                let globals = self.pop_expr();
                let code = self.pop_expr();
                self.push_stmt(Stmt::Exec {
                    code,
                    globals: none_if_const_none(globals),
                    locals: none_if_const_none(locals),
                });
                true
            }

            // ---------- f-strings ----------
            Op::FORMAT_VALUE => {
                // oparg: bits 0-1 conversion (1=str 2=repr 3=ascii),
                // bit 2 = has format spec
                let conversion = match arg & 0x3 {
                    1 => Some('s'),
                    2 => Some('r'),
                    3 => Some('a'),
                    _ => None,
                };
                let format_spec = if arg & 0x04 != 0 {
                    Some(self.pop_expr())
                } else {
                    None
                };
                let value = self.pop_expr();
                let part = FStringPart::Value {
                    value,
                    conversion,
                    format_spec: format_spec.map(|f| Box::new(expr_to_fstring(f))),
                };
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: vec![part],
                }))));
                true
            }
            Op::FORMAT_SIMPLE => {
                let value = self.pop_expr();
                // 3.13+: CONVERT_VALUE already produced a single-part
                // f-string; reuse it instead of nesting
                if let Expr::FString(f) = &*value {
                    if f.parts.len() == 1 {
                        self.push(value);
                        return true;
                    }
                }
                let part = FStringPart::Value {
                    value,
                    conversion: None,
                    format_spec: None,
                };
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: vec![part],
                }))));
                true
            }
            Op::FORMAT_WITH_SPEC => {
                let spec = self.pop_expr();
                let value = self.pop_expr();
                // unwrap a CONVERT_VALUE single-part f-string, keeping its
                // conversion flag
                let (value, conversion) = match &*value {
                    Expr::FString(f) if f.parts.len() == 1 => {
                        match &f.parts[0] {
                            FStringPart::Value {
                                value: v,
                                conversion: c,
                                format_spec: None,
                            } => (v.clone(), *c),
                            _ => (value, None),
                        }
                    }
                    _ => (value, None),
                };
                let part = FStringPart::Value {
                    value,
                    conversion,
                    format_spec: Some(Box::new(expr_to_fstring(spec))),
                };
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: vec![part],
                }))));
                true
            }
            Op::CONVERT_VALUE => {
                let value = self.pop_expr();
                let conversion = match arg {
                    1 => Some('s'),
                    2 => Some('r'),
                    3 => Some('a'),
                    _ => None,
                };
                let part = FStringPart::Value {
                    value,
                    conversion,
                    format_spec: None,
                };
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: vec![part],
                }))));
                true
            }
            // 3.14+ t-string (PEP 750) interpolation builder: pops
            // [value, expr_str?, format_spec?] per the flag bits
            // (arg = conversion<<2 | has_expr<<1 | has_spec; conversion
            // 0=none 1='s' 2='r' 3='a') and pushes one Interpolation.
            // Model it as a single-part FString Value so BUILD_TEMPLATE
            // can interleave it with the literal strings.
            Op::BUILD_INTERPOLATION => {
                let has_spec = arg & 1 != 0;
                let has_expr = (arg >> 1) & 1 != 0;
                let conv_code = (arg >> 2) & 3;
                let format_spec = if has_spec {
                    Some(self.pop_expr())
                } else {
                    None
                };
                // the expr source text (e.g. 'x' for `{x}`) is dropped:
                // rendering the value expression reproduces it for the
                // common cases
                if has_expr {
                    self.pop_expr();
                }
                let value = self.pop_expr();
                let conversion = match conv_code {
                    1 => Some('s'),
                    2 => Some('r'),
                    3 => Some('a'),
                    _ => None,
                };
                let part = FStringPart::Value {
                    value,
                    conversion,
                    format_spec: format_spec
                        .map(|s| Box::new(expr_to_fstring(s))),
                };
                self.push(Rc::new(Expr::FString(Box::new(FString {
                    parts: vec![part],
                }))));
                true
            }
            // 3.14+ t-string (PEP 750) builder: pops the interpolations
            // tuple (TOS) and the strings tuple (TOS-1), pushes a
            // Template. strings has one more element than interpolations;
            // the literal parts interleave with the `{...}` fields
            // (annotationlib 3.14 `_Template = type(t"")` — the empty
            // template rendered nothing and marked the module INCOMPLETE).
            Op::BUILD_TEMPLATE => {
                let interps = self.pop_expr();
                let strings = self.pop_expr();
                // string literals from the strings tuple const
                let lits: Vec<String> = match &*strings {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(items) => items
                            .iter()
                            .map(|it| match &**it {
                                PyObject::Str(s) => s.clone(),
                                _ => String::new(),
                            })
                            .collect(),
                        PyObject::Str(s) => vec![s.clone()],
                        _ => Vec::new(),
                    },
                    _ => Vec::new(),
                };
                // interpolation Value parts from the interpolations tuple
                let mut vals: Vec<FStringPart> = Vec::new();
                match &*interps {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(items) if items.is_empty() => {}
                        _ => {}
                    },
                    Expr::Tuple(items) => {
                        for it in items {
                            if let Expr::FString(f) = &**it {
                                vals.extend(f.parts.iter().cloned());
                            }
                        }
                    }
                    Expr::FString(f) => vals.extend(f.parts.iter().cloned()),
                    _ => {}
                }
                let mut parts: Vec<FStringPart> = Vec::new();
                for (i, lit) in lits.iter().enumerate() {
                    parts.push(FStringPart::Literal(lit.clone()));
                    if let Some(v) = vals.get(i) {
                        parts.push(v.clone());
                    }
                }
                self.push(Rc::new(Expr::TString(Box::new(FString {
                    parts,
                }))));
                true
            }
            Op::STORE_ANNOTATION => {
                // 3.6.0 only: [value?, annotation] — CPython: TOS=ann, TOS1=name
                let ann = self.pop_expr();
                let target = self.pop_expr();
                self.push_stmt(Stmt::AnnAssign {
                    target,
                    annotation: ann,
                    value: None,
                });
                true
            }

            // ---------- match (3.10+) ----------
            Op::MATCH_MAPPING | Op::MATCH_SEQUENCE | Op::MATCH_CLASS => {
                if self.try_parse_match() {
                    return true;
                }
                self.unimplemented(inst, "match/case");
                true
            }
            Op::GET_LEN | Op::MATCH_KEYS => {
                self.unimplemented(inst, "match/case");
                true
            }
            Op::CALL_INTRINSIC_1 | Op::CALL_INTRINSIC_2 => {
                // 3.11: {1: async_gen_wrap, 2: import_star};
                // 3.12+: {2: import_star} (verified against real bytecode)
                let import_star = arg == 2;
                if import_star && inst.op == Op::CALL_INTRINSIC_1 {
                    if let Some(Sv::ImportModule { level, module, .. }) = self.pop() {
                        self.push_stmt(Stmt::ImportFrom {
                            module,
                            level,
                            names: vec![("*".to_string(), None)],
                        });
                    }
                    // the intrinsic leaves a result that POP_TOP discards
                    self.push(Rc::new(Expr::Const(Rc::new(PyObject::None))));
                    self.import_star_pop_pending = true;
                }
                // 3.12+: INTRINSIC_UNARY_POSITIVE (5) — the unary `+`
                // (replaced the UNARY_POSITIVE opcode). NOT a
                // pass-through: dropping it loses semantically
                // meaningful rounding for Decimal (_pylong 3.14
                // `hi = +n * +recip` rendered `n * recip`, which also
                // let 3.14 fuse the loads into
                // LOAD_FAST_BORROW_LOAD_FAST_BORROW)
                if inst.op == Op::CALL_INTRINSIC_1 && arg == 5 {
                    let e = self.pop_expr();
                    self.push(Rc::new(Expr::Unary {
                        op: UnaryOp::Pos,
                        operand: e,
                    }));
                    return true;
                }
                // 3.12+: INTRINSIC_LIST_TO_TUPLE (6) converts the
                // star-unpack build list into a tuple display
                if inst.op == Op::CALL_INTRINSIC_1 && arg == 6 {
                    let e = self.pop_expr();
                    let t = match &*e {
                        Expr::List(items) => Expr::Tuple(items.clone()),
                        other => Expr::Tuple(vec![Rc::new(other.clone())]),
                    };
                    self.push(Rc::new(t));
                    return true;
                }
                // all other intrinsics are value-preserving pass-throughs
                true
            }

            Op::Unknown => {
                self.unimplemented(inst, "unknown opcode");
                true
            }
            other => {
                self.unimplemented(inst, "unsupported opcode");
                let _ = other;
                true
            }
        };
        // statements flush any pending multi-store group; pure stack
        // manipulation and further stores do not. Container stores
        // (subscript/attr/slice) also join the group, and while one is
        // pending the pure-value ops constructing the NEXT target do
        // not flush either — but only when the scan ahead actually
        // finds that next same-line container store through pure
        // material (the compiler interleaves obj/index loads and
        // subscript arithmetic between the stores of a swap:
        // `self[i], self[n-i-1] = self[n-i-1], self[i]`; flushing
        // there tore it into two sequential assignments, silently
        // breaking the swap, _collections_abc reverse). The narrow
        // lookahead matters: an unconditional deferral stalled
        // single-store flushes past their expression-statement point
        // (b21_strbytes rendered `b'Abc'(...)`, 12 matrix cases red).
        let container_store = matches!(
            inst.op,
            Op::STORE_SUBSCR
                | Op::STORE_ATTR
                | Op::STORE_SLICE
                | Op::STORE_SLICE_0
                | Op::STORE_SLICE_1
                | Op::STORE_SLICE_2
                | Op::STORE_SLICE_3
        );
        let building_container_target = !self.pending_stores.is_empty()
            && self.pending_stores.iter().any(|(t, _)| {
                matches!(&**t, Expr::Subscript { .. } | Expr::Attribute { .. })
            })
            && is_pure_value_op(inst.op)
            && self.same_line_container_store_ahead(inst.offset)
            // separate same-line statements (`self.list = None;
            // self.file = None`, and the 3.12+ coalesced line entries
            // for consecutive attr stores) reload their values or
            // recompute between the stores; a genuine parallel
            // assignment keeps every rhs value live on the stack
            // across the whole window (cgi 3.7 read_lines, Cookie 2.6
            // Morsel.__init__, contextlib 3.12/3.13 __init__ merged
            // into chained/tuple forms without this)
            && self.values_still_live_ahead(inst.offset);
        if !is_stack_plumbing(inst.op)
            && !is_store_op(inst.op)
            && !container_store
            && !building_container_target
        {
            self.flush_pending_stores();
        }
        cont
    }

    /// True while the simulated value stack still holds at least as
    /// many live expressions as pending stores whose value has already
    /// been consumed: a parallel assignment front-loads ALL rhs values
    /// before the first store, so the leftover count never drops below
    /// the number of stores still to come. Any op that consumes values
    /// without storing (a call, an in-place update, a comparison)
    /// breaks the parallel shape - the pending stores are separate
    /// statements and must flush.
    fn values_still_live_ahead(&self, off: usize) -> bool {
        let Some(&ci) = self.idx_of.get(&off) else {
            return false;
        };
        let pending = self.pending_stores.len() as i32;
        let mut live = self
            .stack
            .iter()
            .filter(|s| matches!(s, Sv::E(_)))
            .count() as i32;
        if live < pending {
            return false;
        }
        // push/pop accounting over the window: the leftover rhs values
        // must stay reachable (never popped away) until their store
        // consumes them; anything with an unmodeled delta aborts
        let delta = |x: &Instruction, ver312: bool| -> Option<i32> {
            let d = match x.op {
                Op::STORE_SUBSCR => -3,
                Op::STORE_ATTR => {
                    if ver312 {
                        -1
                    } else {
                        -2
                    }
                }
                Op::STORE_SLICE => -2,
                Op::STORE_SLICE_0 => -1,
                Op::STORE_SLICE_1 | Op::STORE_SLICE_2 => -2,
                Op::STORE_SLICE_3 => -3,
                Op::LOAD_FAST_LOAD_FAST
                | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                | Op::DUP_TOP_TWO => 2,
                Op::DUP_TOP => 1,
                Op::ROT_TWO | Op::ROT_THREE | Op::ROT_FOUR | Op::SWAP | Op::COPY => 0,
                Op::POP_TOP => -1,
                Op::BINARY_SUBSCR => -1,
                Op::BINARY_OP
                | Op::BINARY_ADD
                | Op::BINARY_SUBTRACT
                | Op::BINARY_MULTIPLY
                | Op::BINARY_TRUE_DIVIDE
                | Op::BINARY_FLOOR_DIVIDE
                | Op::BINARY_MODULO
                | Op::BINARY_POWER
                | Op::BINARY_LSHIFT
                | Op::BINARY_RSHIFT
                | Op::BINARY_AND
                | Op::BINARY_OR
                | Op::BINARY_XOR
                | Op::BINARY_MATRIX_MULTIPLY => -1,
                Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => 1 - x.arg as i32,
                Op::UNPACK_SEQUENCE => x.arg as i32 - 1,
                Op::LOAD_FAST
                | Op::LOAD_FAST_CHECK
                | Op::LOAD_FAST_BORROW
                | Op::LOAD_NAME
                | Op::LOAD_GLOBAL
                | Op::LOAD_CONST
                | Op::LOAD_DEREF
                | Op::LOAD_CLOSURE
                | Op::LOAD_CLASSDEREF
                | Op::LOAD_SMALL_INT
                | Op::LOAD_COMMON_CONSTANT
                | Op::PUSH_NULL => 1,
                // anything else (calls, comparisons, exotic loads):
                // unmodeled delta - refuse the deferral and keep the
                // historic per-statement flush
                _ => return None,
            };
            Some(d)
        };
        let ver312 = self.version.at_least(3, 12);
        let mut steps = 0usize;
        for x in self.instrs.iter().skip(ci + 1) {
            steps += 1;
            if steps > 16 {
                return false;
            }
            let Some(d) = delta(x, ver312) else {
                return false;
            };
            live += d;
            if live < 0 {
                return false;
            }
            if matches!(
                x.op,
                Op::STORE_SUBSCR
                    | Op::STORE_ATTR
                    | Op::STORE_SLICE
                    | Op::STORE_SLICE_0
                    | Op::STORE_SLICE_1
                    | Op::STORE_SLICE_2
                    | Op::STORE_SLICE_3
            ) {
                return true;
            }
        }
        false
    }

    /// True when the instructions after `off` are pure value/plumbing
    /// material on the pending store group's line, ending at another
    /// container store — the target-construction window between the
    /// two stores of a simultaneous assignment.
    fn same_line_container_store_ahead(&self, off: usize) -> bool {
        let Some(&ci) = self.idx_of.get(&off) else {
            return false;
        };
        let line = self.last_store_line;
        let mut steps = 0usize;
        for x in self.instrs.iter().skip(ci + 1) {
            steps += 1;
            if steps > 16 {
                return false;
            }
            if matches!(
                x.op,
                Op::STORE_SUBSCR
                    | Op::STORE_ATTR
                    | Op::STORE_SLICE
                    | Op::STORE_SLICE_0
                    | Op::STORE_SLICE_1
                    | Op::STORE_SLICE_2
                    | Op::STORE_SLICE_3
            ) {
                return x.line.is_none() || line.is_none() || x.line == line;
            }
            if !is_pure_value_op(x.op) && !is_stack_plumbing(x.op) {
                return false;
            }
            if x.line.is_some() && line.is_some() && x.line != line {
                return false;
            }
        }
        false
    }

    /// Flush a group of stores that share one source line as a simultaneous
    /// assignment (`a, b = b, a + b`) or a chained assignment (`a = b = e`).
    fn group_has_swap(&self) -> bool {
        self.instrs
            .iter()
            .skip_while(|i| i.offset <= self.last_flush_offset)
            .take_while(|i| i.offset <= self.cur_offset)
            .any(|i| {
                matches!(
                    i.op,
                    Op::SWAP | Op::ROT_TWO | Op::ROT_THREE | Op::ROT_FOUR | Op::ROT_N
                )
            })
    }

    fn flush_pending_stores(&mut self) {
        if self.pending_stores.len() >= 2 {
            let group = std::mem::take(&mut self.pending_stores);
            self.last_store_line = None;
            self.pending_unpack_wrap.clear();
            let all_same = group.windows(2).all(|w| expr_eq(&w[0].1, &w[1].1));
            if all_same {
                let value = group[0].1.clone();
                let targets: Vec<ExprRef> = group.iter().map(|(t, _)| t.clone()).collect();
                self.push_stmt(Stmt::Assign {
                    targets,
                    value,
                    wrap_before: Vec::new(),
                });
            } else {
                // simultaneous assignment from consecutive stores. Store
                // order is reversed relative to source when the compiler
                // used the ROT/SWAP-free overlapping-values trick (3.12+);
                // an explicit SWAP/ROT inside the group means the values
                // were pre-arranged and stores follow source order.
                let has_swap = self.group_has_swap();
                let (targets, values): (Vec<ExprRef>, Vec<ExprRef>) = if has_swap {
                    (
                        group.iter().map(|(t, _)| t.clone()).collect(),
                        group.iter().map(|(_, v)| v.clone()).collect(),
                    )
                } else {
                    (
                        group.iter().rev().map(|(t, _)| t.clone()).collect(),
                        group.iter().rev().map(|(_, v)| v.clone()).collect(),
                    )
                };
                self.push_stmt(Stmt::Assign {
                    targets: vec![Rc::new(Expr::Tuple(targets))],
                    value: Rc::new(Expr::Tuple(values)),
                    wrap_before: Vec::new(),
                });
            }
        } else if self.pending_stores.len() == 1 {
            let (t, v) = self.pending_stores.pop().unwrap();
            self.last_store_line = None;
            let wrap_before = std::mem::take(&mut self.pending_unpack_wrap);
            self.push_stmt(Stmt::Assign {
                targets: vec![t],
                value: v,
                wrap_before,
            });
        } else {
            self.last_store_line = None;
        }
    }
}

/// Store opcodes participate in the pending group without flushing it.
fn is_store_op(op: Op) -> bool {
    matches!(
        op,
        Op::STORE_FAST
            | Op::STORE_FAST_MAYBE_NULL
            | Op::STORE_FAST_LOAD_FAST
            | Op::STORE_FAST_STORE_FAST
            | Op::STORE_NAME
            | Op::STORE_GLOBAL
            | Op::STORE_DEREF
    )
}

/// Opcodes that only move values around and must not flush a pending
/// multi-store group.
fn is_stack_plumbing(op: Op) -> bool {
    matches!(
        op,
        Op::POP_TOP
            | Op::ROT_TWO
            | Op::ROT_THREE
            | Op::ROT_FOUR
            | Op::ROT_N
            | Op::SWAP
            | Op::DUP_TOP
            | Op::DUP_TOP_TWO
            | Op::DUP_TOPX
            | Op::COPY
            | Op::PUSH_NULL
            | Op::NOP
            | Op::CACHE
            | Op::RESUME
            | Op::RESUME_CHECK
            | Op::PRECALL
            | Op::EXTENDED_ARG
            | Op::TO_BOOL
            | Op::UNPACK_SEQUENCE
            | Op::UNPACK_EX
    )
}

// =====================  control-flow handlers  =====================

impl<'a> Ctx<'a> {
    /// Conditional jump. `jump_if_true` = the branch taken when the
    /// condition holds.
    /// py2.7 boolean-op if-conditions. `(a or b) and c` compiles to
    /// `J1: PJIT L; <a-false rhs> J0: PJIF E; L: <rhs c> J2: PJIF E; then; E:`
    /// where J1's target region also ends in a cond jump to the same E.
    /// Returns the merged (cond, then_end) when the pattern matches.
    /// 3.14 inline all/any guard: validate the fast-path shape and return
    /// the slow-path (generic call) offset. `is_all` selects the expected
    /// builtin constant index (3 = all, 4 = any).
    fn inline_all_any_slow_path(&self, is_all: bool) -> Option<usize> {
        let ci = self.idx_of.get(&self.cur_offset).copied()?;
        // guard: COPY 1 before, IS_OP 0 + forward PJIF after
        if self.instrs.get(ci.wrapping_sub(1)).map(|x| (x.op, x.arg))
            != Some((Op::COPY, 1))
        {
            return None;
        }
        let isop = self.instrs.get(ci + 1)?;
        if isop.op != Op::IS_OP || isop.arg != 0 {
            return None;
        }
        let pjif = self.instrs.get(ci + 2)?;
        if pjif.op != Op::POP_JUMP_IF_FALSE {
            return None;
        }
        let slow = pjif.target?;
        if slow <= pjif.offset {
            return None;
        }
        let &si = self.idx_of.get(&slow)?;
        if self.instrs.get(si).map(|x| x.op) != Some(Op::PUSH_NULL) {
            return None;
        }
        // slow path: PUSH_NULL; [closure vars; BUILD_TUPLE n;]
        // LOAD_CONST <genexpr code>; MAKE_FUNCTION;
        // [SET_FUNCTION_ATTRIBUTE closure]; <iterable>; GET_ITER;
        // CALL 0; CALL 1 — the closure prologue exists when the genexpr
        // captures locals (_py_abc 3.14 __instancecheck__'s
        // `any(cls.__subclasscheck__(c) ...)` closes over cls)
        let mut k = si + 1;
        let mut lci = None;
        while let Some(ins) = self.instrs.get(k) {
            if ins.op == Op::LOAD_CONST {
                match self.code.consts.get(ins.arg as usize).map(|o| &**o) {
                    Some(PyObject::Code(c)) if c.name == "<genexpr>" => {
                        lci = Some(k);
                        break;
                    }
                    _ => return None,
                }
            }
            if matches!(
                ins.op,
                Op::LOAD_FAST
                    | Op::LOAD_FAST_BORROW
                    | Op::LOAD_FAST_CHECK
                    | Op::LOAD_DEREF
                    | Op::LOAD_FAST_LOAD_FAST
                    | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                    | Op::BUILD_TUPLE
                    | Op::NOP
                    | Op::NOT_TAKEN
                    | Op::CACHE
            ) {
                k += 1;
                continue;
            }
            return None;
        }
        let lci = lci?;
        if self.instrs.get(lci + 1).map(|x| x.op) != Some(Op::MAKE_FUNCTION) {
            return None;
        }
        let mut k = lci + 2;
        while matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::SET_FUNCTION_ATTRIBUTE)
        ) {
            k += 1;
        }
        let mut saw_get_iter = false;
        let mut call0 = None;
        while let Some(ins) = self.instrs.get(k) {
            match ins.op {
                Op::GET_ITER => saw_get_iter = true,
                Op::CALL if ins.arg == 0 => {
                    call0 = Some(k);
                    break;
                }
                op if is_pure_value_op(op) => {}
                _ => return None,
            }
            k += 1;
        }
        let c0 = call0?;
        if !saw_get_iter {
            return None;
        }
        if self.instrs.get(c0 + 1).map(|x| (x.op, x.arg)) != Some((Op::CALL, 1)) {
            return None;
        }
        // fast path [guard end, slow): must hold the inline generator loop
        let fast_start = ci + 3;
        let mut saw_for_iter = false;
        for ins in self.instrs.iter().skip(fast_start) {
            if ins.offset >= slow {
                break;
            }
            if ins.op == Op::FOR_ITER {
                saw_for_iter = true;
            }
        }
        if !saw_for_iter {
            return None;
        }
        let _ = is_all;
        Some(slow)
    }

    /// Flush a completed legacy (<=3.10) try chain into the enclosing
    /// block. Success-path statements emitted after POP_BLOCK (typically
    /// the function's trailing `return`) chronologically FOLLOW the try
    /// statement in the source, so insert before any trailing returns.
    /// Close blocks opened INSIDE the currently open legacy handler
    /// (If/Else/With/...) before it is collected, so their converted
    /// statements route into the handler body instead of the enclosing
    /// scope (their lexical end can sit past the collection point —
    /// e.g. an else region falling through to POP_EXCEPT).
    fn close_handler_blocks(&mut self) {
        let Some(depth) = self.legacy_handler.as_ref().map(|h| h.block_depth) else {
            return;
        };
        let mut guard = self.blocks.len();
        while self.blocks.len() > depth && guard > 0 {
            guard -= 1;
            let end = self
                .blocks
                .last()
                .map(|b| b.end.min(self.cur_offset.max(b.start)))
                .unwrap_or(self.cur_offset);
            self.force_close_top(end);
        }
    }

    /// When every collected handler's paths all end the scope
    /// (return/raise/break/continue), the continuation at the body-jump
    /// target is unreachable from the handler flow: `try + continuation`
    /// and `try/else + continuation` are bytecode-identical, so retract
    /// the presumed else region and render the continuation flat — the
    /// source form (asynchat 2.7 handle_read, crypt's always-raising
    /// import guard, compileall 3.6 flist guard whose If-merge coincides
    /// with the continuation and would otherwise close empty INSIDE the
    /// swallowed else region). Genuine `else:` sources with escaping
    /// handlers render flat too — semantically identical.
    fn retract_escaping_else(&mut self, pos: usize) {
        // a chain nested inside a still-open handler body is folded by the
        // outer chain's machinery (begin/finish_legacy_nest): retracting
        // its presumed else fires the deferred flush mid-nest and tears
        // the outer handler down (b05 t7/bare_raise lost the nested try).
        // ≤3.7 nesting STASHES the outer chain into legacy_nest (the
        // single legacy_handler slot parses the inner chain), so both
        // slots must be quiescent
        if self.legacy_handler.is_some() || !self.legacy_nest.is_empty() {
            return;
        }
        let retract = self
            .legacy_try
            .as_ref()
            .map_or(false, |l| {
                l.chain_done
                    && !l.has_finally
                    && l.orelse.is_empty()
                    && l.else_start.is_some()
                    // no unparsed clause heads past this chain end
                    && !l
                        .pending_mismatch
                        .iter()
                        .any(|&m| m > pos && self.pending_clause_head_at(m))
                    && l.handlers
                        .iter()
                        .all(|h| {
                            let t = h.body.last();
                            // RETURN/RAISE handlers leave no usable
                            // cleanup edge (py2/3.6+: none at all; 3.5:
                            // dead overfly) — the Stmt-level check plus
                            // the geometric discriminators below decide
                            // those. BREAK/CONTINUE are excluded here
                            // (see the match arm)
                            // BREAK/CONTINUE handlers always carry a
                            // compiler cleanup edge whose target is the
                            // geometric discriminator (flat: lands on
                            // the continuation == else_start, retracted
                            // by the handler-exit-jump rule; else:
                            // lands on the loop top / region end).
                            // Never Stmt-retract those — _sitebuiltins
                            // _Printer.__call__ 3.5-3.7 `except
                            // IndexError: break` + JABS-to-loop-top was
                            // PASS with the else form.
                            matches!(
                                t,
                                Some(Stmt::Return(_)) | Some(Stmt::Raise { .. })
                            )
                        })
                    // 3.3+ dead-code discriminator: a genuine `else:`
                    // makes the compiler emit each handler's dead
                    // normal-exit cleanup (POP_EXCEPT; JF) targeting the
                    // POST-else merge, while a flat continuation gets
                    // cleanup targeting the continuation itself (== the
                    // body jump's target, retracted earlier) or none at
                    // all. A cleanup jump that OVERFLIES the presumed
                    // else region is therefore proof of a real else —
                    // keep it (_collections_abc __contains__ 3.5-3.8,
                    // code 3.3, _sitebuiltins 3.5-3.7 were PASS with
                    // the else form). py2 emits no such cleanup.
                    && !l.else_start.map_or(false, |es| {
                        let hs = l.handler_start;
                        self.instrs.iter().any(|x| {
                            x.offset >= hs
                                && x.offset < es
                                && matches!(
                                    x.op,
                                    Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
                                )
                                // a jump to a loop exit is a break
                                // escape, not the dead else-merge
                                // cleanup (bz2 3.10 decompress `if
                                // results: break` overflew the
                                // continuation and blocked the
                                // legitimate retraction)
                                && x.target.map_or(false, |t| {
                                    t > es && self.find_loop_exit(t).is_none()
                                })
                        })
                    })
                    // dead function-tail epilogue discriminator: when
                    // the presumed else region's flow all-returns, a
                    // genuine `else:` leaves an UNREACHABLE `LOAD None;
                    // RETURN` pair at the code tail (the else clause's
                    // merge point, 3.5-3.10 _collections_abc
                    // __contains__), while a flat all-returning
                    // continuation ends the code object at its own
                    // return — no dead pair. A LIVE epilogue
                    // (jump-targeted or fall-through-reachable, e.g. a
                    // loop-exit POP_BLOCK before it) is the flat
                    // continuation case (asynchat handle_read) and
                    // still retracts. py2 all-return flat forms end at
                    // their own RETURN and never carry a dead pair.
                    && !l.else_start.map_or(false, |_es| {
                        let n = self.instrs.len();
                        if n < 2 {
                            return false;
                        }
                        let last = &self.instrs[n - 1];
                        let prev = &self.instrs[n - 2];
                        let none_const = matches!(prev.op, Op::LOAD_CONST)
                            && self
                                .code
                                .consts
                                .get(prev.arg as usize)
                                .map_or(false, |o| matches!(&**o, PyObject::None));
                        if !(none_const
                            && matches!(
                                last.op,
                                Op::RETURN_VALUE | Op::RETURN_CONST
                            ))
                        {
                            return false;
                        }
                        // nothing jumps to the epilogue, and the
                        // instruction before it terminates (unreachable
                        // fall-through) => dead pair
                        !self.targets.contains(&prev.offset)
                            && self.idx_of.get(&prev.offset).map_or(false, |&pi| {
                                pi > 0
                                    && matches!(
                                        self.instrs[pi - 1].op,
                                        Op::RETURN_VALUE
                                            | Op::RETURN_CONST
                                            | Op::RAISE_VARARGS
                                            | Op::JUMP_FORWARD
                                            | Op::JUMP_ABSOLUTE
                                            | Op::JUMP
                                            | Op::BREAK_LOOP
                                    )
                            })
                    })
            });
        if retract {
            if let Some(l) = self.legacy_try.as_mut() {
                l.else_start = None;
            }
        }
    }

    /// Legacy (3.8-3.10) tail-position try whose post-try `return v` was
    /// SUNK into both exits (copyreg 3.10 _slotnames `try: cls.__slotnames__
    /// = names; except: pass; return names`): the success-path copy sits
    /// between the body's POP_BLOCK and handler_start, and the handler
    /// region opens (after the bare-except prelude POPs) with a mirrored
    /// copy. Detect the pair: [POP_BLOCK] [success run] RETURN
    /// handler_start [POP_TOP*/POP_EXCEPT] [mirror run] RETURN.
    /// True when `a` and `b` are both `LOAD [value-run]; RETURN`
    /// sequences with identical normalized value runs — 3.10 duplicates
    /// the function-tail return at EVERY exit of a finally-copy branch,
    /// so an and-chain's links land on sibling copies of the same
    /// source exit (cmd 3.10 cmdloop). Offsets may point at the run's
    /// first load or at the return itself.
    fn equivalent_sunk_exit(&self, a: usize, b: usize) -> bool {
        if a == b {
            return false;
        }
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let is_load = |o: Op| {
            matches!(
                o,
                Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_DEREF
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
            )
        };
        let run_at = |off: usize| -> Option<Vec<(u8, u32)>> {
            let mut k = self.idx_of.get(&off).copied()?;
            if matches!(self.instrs.get(k).map(|x| x.op), Some(Op::RETURN_VALUE)) {
                // walk back over the value loads
                let mut b0 = k;
                let mut hops = 0;
                while b0 > 0 && hops < 8 {
                    let p = &self.instrs[b0 - 1];
                    if is_pad(p) || is_load(p.op) {
                        b0 -= 1;
                        hops += 1;
                        continue;
                    }
                    break;
                }
                k = b0;
            }
            let mut run = Vec::new();
            let mut i = k;
            while i < self.instrs.len() && run.len() <= 9 {
                let x = &self.instrs[i];
                if is_pad(x) {
                    i += 1;
                    continue;
                }
                if is_load(x.op) {
                    run.push((x.op as u8, x.arg));
                    i += 1;
                    continue;
                }
                if x.op == Op::RETURN_VALUE {
                    run.push((x.op as u8, 0));
                    return Some(run);
                }
                return None;
            }
            None
        };
        match (run_at(a), run_at(b)) {
            (Some(ra), Some(rb)) => ra.len() >= 2 && ra == rb,
            _ => false,
        }
    }

    fn legacy_sunk_pair_return(&self, lt: &LegacyTry, ret_off: usize) -> Option<usize> {
        let hs = lt.handler_start;
        if ret_off >= hs || !self.version.at_least(3, 8) {
            return None;
        }
        let (Some(&si), Some(&hi)) =
            (self.idx_of.get(&hs), self.idx_of.get(&ret_off))
        else {
            return None;
        };
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let is_load = |o: Op| {
            matches!(
                o,
                Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_DEREF
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
            )
        };
        let norm = |x: &crate::bytecode::Instruction| (x.op as u8, x.arg);
        // success run: back-walk from the return over loads/pads
        let mut b = hi;
        let mut hops = 0;
        while b > 0 && hops < 8 {
            let p = &self.instrs[b - 1];
            if is_pad(p) || is_load(p.op) {
                b -= 1;
                hops += 1;
                continue;
            }
            break;
        }
        let run_a: Vec<(u8, u32)> = self.instrs[b..=hi]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        if run_a.len() < 2
            || !matches!(run_a.last().map(|t| t.0), Some(op) if op == Op::RETURN_VALUE as u8)
        {
            return None;
        }
        // the run must start right after the body's POP_BLOCK (+pads)
        let mut after_pop_block = false;
        {
            let mut k = b;
            while k > 0 {
                let p = &self.instrs[k - 1];
                if is_pad(p) {
                    k -= 1;
                    continue;
                }
                after_pop_block = p.op == Op::POP_BLOCK;
                break;
            }
        }
        if !after_pop_block {
            return None;
        }
        // handler region: bare prelude POPs/pads, then the mirrored run
        let mut k = si;
        while k < self.instrs.len() {
            let x = &self.instrs[k];
            if matches!(x.op, Op::POP_TOP | Op::POP_EXCEPT) || is_pad(x) {
                k += 1;
                continue;
            }
            break;
        }
        let hb = k;
        let mut k2 = k;
        let mut hops2 = 0;
        while k2 < self.instrs.len() && hops2 < 10 {
            let x = &self.instrs[k2];
            if is_pad(x) || is_load(x.op) {
                k2 += 1;
                hops2 += 1;
                continue;
            }
            break;
        }
        if k2 >= self.instrs.len() || self.instrs[k2].op != Op::RETURN_VALUE {
            return None;
        }
        let run_h: Vec<(u8, u32)> = self.instrs[hb..=k2]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        (run_h == run_a).then(|| self.instrs[hb].offset)
    }


    /// 3.10 double-sunk-tail try/except/finally: the inner except chain
    /// (fully parsed before this outer finally chain flushes) sits
    /// STASHED in legacy_nest — the end-of-walk nest teardown would emit
    /// it as a SIBLING after the outer Try (bdb 3.10 run rendered
    /// `try: pass finally: ...` + a separate `try: exec() except
    /// BdbQuit: pass`). Fold it into the outer chain's body as a nested
    /// Try. The nest husk stays for the caller's restore_legacy_nest.
    fn fold_stashed_inner_chain(&mut self, l: &mut LegacyTry) {
        if self.legacy_nest.is_empty() {
            return;
        }
        let ni = self.legacy_nest.len() - 1;
        let ok = self.legacy_nest[ni]
            .outer_try
            .as_ref()
            .map_or(false, |inner| {
                !inner.handlers.is_empty()
                    && inner.chain_done
                    && l.else_start
                        .map_or(false, |es| inner.handler_start < es)
                    && inner.finalbody.is_empty()
            });
        if !ok {
            return;
        }
        let mut inner = self.legacy_nest[ni].outer_try.take().unwrap();
        let inner_try = Stmt::Try {
            body: std::mem::take(&mut inner.body),
            handlers: std::mem::take(&mut inner.handlers),
            orelse: std::mem::take(&mut inner.orelse),
            finalbody: Vec::new(),
        };
        l.body.push(inner_try);
    }

    fn push_legacy_try(&mut self, l: LegacyTry) {
        let l_handler_start = l.handler_start;
        let mut try_stmt = Stmt::Try {
            body: l.body,
            handlers: l.handlers,
            orelse: l.orelse,
            finalbody: l.finalbody,
        };
        // a chain Try absorbed for THIS chain's body (armed at the
        // POP_BLOCK that created the chain, see chain_absorb_body):
        // merge it into the body — before any trailing returns — so it
        // renders INSIDE this try, then route the merged statement
        // normally. Only while the loop is still open for the chain
        // (once the loop closed, the holder is stale)
        if self.pending_loop_close_at_chain.is_none() {
            if let Some(stash) = self.chain_absorb_body.take() {
                if let Stmt::Try { body, .. } = &mut try_stmt {
                    let mut at = body.len();
                    while at > 0 && matches!(body[at - 1], Stmt::Return(_)) {
                        at -= 1;
                    }
                    for (k, st) in stash.into_iter().enumerate() {
                        body.insert(at + k, st);
                    }
                }
            }
        }
        // swap-in fold: route into the swapped-out chain's body (it may
        // be active again already — the fold path restores the nest
        // BEFORE pushing) or still stashed
        if let Some(hs) = self.legacy_body_redirect.take() {
            let owner_active = self
                .legacy_try
                .as_ref()
                .map_or(false, |l| l.handler_start == hs);
            // insert before any trailing returns of the owner body (the
            // sunk post-try `return` collected before this fold)
            let insert_before_returns = |body: &mut Vec<Stmt>, s: Stmt| {
                let mut at = body.len();
                while at > 0 && matches!(body[at - 1], Stmt::Return(_)) {
                    at -= 1;
                }
                body.insert(at, s);
            };
            if owner_active {
                if let Some(ot) = self.legacy_try.as_mut() {
                    insert_before_returns(&mut ot.body, try_stmt);
                }
                return;
            }
            let owner_idx = self.legacy_nest.iter().position(|n| {
                n.outer_try
                    .as_ref()
                    .map_or(false, |l| l.handler_start == hs)
            });
            if let Some(idx) = owner_idx {
                if let Some(ot) = self.legacy_nest[idx].outer_try.as_mut() {
                    insert_before_returns(&mut ot.body, try_stmt);
                }
                return;
            }
        }
        // an emitted nested Try landing inside the RESTORED outer
        // chain's inline-finally region belongs to that chain's
        // finalbody, not to the enclosing block (bz2 3.8 close:
        // `finally: {try: ... finally: ...}` — the nested Try flushed
        // at its own END_FINALLY must fold into the outer finally;
        // sibling emission inverted the order and left the outer
        // finalbody empty)
        // a STASHED chain whose inline-finally region still contains
        // this emission point wins over the active chain: a nested try
        // inside a finally body flushes from within an if-arm of that
        // body while the outer chain is stashed — routing into the
        // stash keeps the wrapper cascade intact (cmd 3.10 cmdloop:
        // the active-then-restored routing put the nested Try bare
        // into finalbody and the arm wrappers closed as dropped
        // empty shells, losing the `if use_rawinput:` guards)
        {
            let mut target_idx = None;
            for (i, n) in self.legacy_nest.iter().enumerate().rev() {
                if let Some(o) = &n.outer_try {
                    if o.has_finally && o.handler_start != l_handler_start {
                        if let Some(es) = o.else_start {
                            if self.cur_offset >= es
                                && self.cur_offset <= o.else_stop
                            {
                                target_idx = Some(i);
                                break;
                            }
                        }
                    }
                }
            }
            if let Some(i) = target_idx {
                if let Some(o) = self.legacy_nest[i].outer_try.as_mut() {
                    o.finalbody.push(try_stmt);
                }
                return;
            }
        }
        // a nested chain flushed while the ACTIVE outer chain is a
        // try/except/ELSE whose else REGION contains this emission point:
        // the nested Try is the else region's content and belongs in the
        // outer's orelse - the mirror of push_stmt's else-region redirect,
        // which push_legacy_try bypasses. The 3.8/3.9 inline-finally inner
        // chain flushes at its terminal JF right AFTER legacy_chain_step
        // restored the stashed outer (restore-before-push at the 7227 call
        // site), so the outer is active here, not stashed. Without this the
        // inner try emitted as a Main-level SIBLING before the outer and
        // the outer's orelse wrongly collected the post-else tail
        // (_osx_support 3.8/3.9 _get_system_version: f.read() before
        // f=open(), inner try ran even when open() raised, and
        // `else: return _SYSTEM_VERSION` swallowed the function tail).
        if let Some(lt) = self.legacy_try.as_ref() {
            if !lt.has_finally
                && lt.handler_start != l_handler_start
                && lt.else_start.map_or(false, |es| {
                    self.cur_offset >= es && self.cur_offset <= lt.else_stop
                })
            {
                // the nested chain's terminal jump flies to the else
                // region's true end (the merge the except-exit also
                // targets): bound the region there NOW. 3.8+ leaves
                // else_stop unbounded (the except-exit bounder is gated
                // pre-3.8 for asynchat's sunk copies), and an unbounded
                // region keeps redirecting every later statement - the
                // enclosing guard If's close and the function tail - into
                // the orelse (_osx_support 3.9: the outer
                // `if _SYSTEM_VERSION is None:` wrapper and
                // `return _SYSTEM_VERSION` were swallowed into the else).
                // Gated on the chain being DONE (its terminal jump is the
                // region's last flow) and the target not being a jump
                // target itself (a mid-region merge would cut the region
                // short).
                let chain_done = lt.chain_done;
                let o_hs = lt.handler_start;
                let o_es = lt.else_start.unwrap_or(usize::MAX);
                // the region's true end is the OUTER chain's handler-exit
                // jump target (where the except path merges with the
                // else's fall-through). Validate via this chain's terminal
                // forward jump: it must stay INSIDE the candidate region
                // (the flush site may BE that jump - legacy_chain_step's
                // JUMP_FORWARD arm - or sit right before it, an
                // END_FINALLY / POP_EXCEPT fold). A terminal jump past the
                // candidate means the layout is a sunk-copy variant
                // (asynchat 3.9/3.10) - leave else_stop untouched there.
                let fwd_jump_at = |i: usize| {
                    self.instrs.get(i).and_then(|x| {
                        (matches!(
                            x.op,
                            Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                        ) && !x.is_backward)
                            .then_some(x.target)
                            .flatten()
                    })
                };
                let terminal_jf = self
                    .idx_of
                    .get(&self.cur_offset)
                    .copied()
                    .and_then(|ci| {
                        let mut k = ci + 1;
                        while matches!(
                            self.instrs.get(k).map(|x| x.op),
                            Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
                        ) {
                            k += 1;
                        }
                        fwd_jump_at(ci).or_else(|| fwd_jump_at(k))
                    });
                let bound = if chain_done {
                    self.instrs
                        .iter()
                        .filter(|x| {
                            x.offset >= o_hs
                                && x.offset < o_es
                                && !x.is_backward
                                && matches!(
                                    x.op,
                                    Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                                )
                        })
                        .filter_map(|x| x.target)
                        .filter(|&t| {
                            t > self.cur_offset
                                && self.idx_of.contains_key(&t)
                                && terminal_jf.map_or(false, |jt| jt <= t)
                        })
                        .min()
                } else {
                    None
                };
                if let Some(lt) = self.legacy_try.as_mut() {
                    if let Some(t) = bound {
                        if t < lt.else_stop {
                            lt.else_stop = t;
                        }
                    }
                    lt.orelse.push(try_stmt);
                }
                return;
            }
        }
        if let Some(lt) = self.legacy_try.as_mut() {
            if lt.has_finally && lt.handler_start != l_handler_start {
                if let Some(es) = lt.else_start {
                    // two window shapes: (a) handler BEFORE the inline
                    // copy (3.8 END_FINALLY layout, bz2 3.8 close):
                    // [es, else_stop]; (b) handler AFTER the copy (3.9+
                    // inline layout) and the copy's if-arm wrappers all
                    // closed already (top is Main/Try): the window
                    // extends to the handler start — a nested chain
                    // flushing from past the first sunk tail return
                    // still belongs to the finally body
                    // (_bootsubprocess 3.10 check_output). With arms
                    // still open (cmd 3.10 cmdloop) keep the tight
                    // bound so the Try lands in the arm and the
                    // wrappers cascade into the finalbody.
                    let arms_open = matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::If) | Some(BlockType::Else)
                    );
                    let in_window = if lt.handler_start > lt.else_stop
                        && !arms_open
                    {
                        self.cur_offset >= es
                            && self.cur_offset < lt.handler_start
                    } else {
                        self.cur_offset >= es && self.cur_offset <= lt.else_stop
                    };
                    if in_window {
                        lt.finalbody.push(try_stmt);
                        return;
                    }
                }
            }
        }
        // a nested chain flushed inside a restored outer handler belongs to
        // that handler's body, not to the enclosing block
        if let Some(h) = self.legacy_handler.as_mut() {
            if self.blocks.len() <= h.block_depth {
                let mut at = h.body.len();
                while at > 0 && matches!(h.body[at - 1], Stmt::Return(_)) {
                    at -= 1;
                }
                h.body.insert(at, try_stmt);
                return;
            }
        }
        let top = self.blocks.last_mut().unwrap();
        let mut at = top.stmts.len();
        while at > 0 && matches!(top.stmts[at - 1], Stmt::Return(_)) {
            at -= 1;
        }
        top.stmts.insert(at, try_stmt);
        // a loop kept open for this chain closes now that the Try is in
        // its body
        if let Some(loop_top) = self.pending_loop_close_at_chain.take() {
            if self.legacy_try.is_none() {
                let idx = self.blocks.iter().rposition(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (b.start == loop_top || b.cond_end == loop_top)
                });
                if let Some(li) = idx {
                    let close_at = self.cur_offset;
                    // a block below the loop whose span has NOT been
                    // reached yet (its end lies ahead - an enclosing
                    // if-guard whose else region starts there) must
                    // survive the chain-fold close: force-closing it at
                    // the fold offset opens its Else region inside the
                    // dead handler glue (next_boundary lands on the
                    // RERAISE) and the real else arm - the elif chain
                    // ahead - walks at parent level, flattened into a
                    // sibling that also runs after the break
                    // (_osx_support 3.9 compiler_fixup). The linear walk
                    // closes it at its own end where the Else region
                    // opens correctly.
                    let unreached = self
                        .blocks
                        .get(li)
                        .map(|b| b.start)
                        .and_then(|ls| {
                            (0..li).rev().find(|&i| {
                                matches!(self.blocks[i].kind, BlockType::If)
                                    && self.blocks[i].end > ls
                                    && self.blocks[i].end > close_at
                            })
                        });
                    let stop_len = match unreached {
                        Some(i) => i + 1,
                        None => li,
                    };
                    while self.blocks.len() > stop_len {
                        self.force_close_top(close_at);
                        // the loop's own close may have opened its
                        // for-else region (SETUP_LOOP-era for/else):
                        // that region is walked by the linear flow
                        // ahead — closing it here (empty) drops the
                        // else arm and the trailing unconditional
                        // close then eats the ENCLOSING loop (csv
                        // 3.5/3.6 has_header: for-col died at the
                        // inner chain's emit, stranding the else
                        // body and the if/else tail at row level)
                        if self
                            .blocks
                            .last()
                            .map_or(false, |t| {
                                matches!(
                                    t.kind,
                                    BlockType::ForElse | BlockType::WhileElse
                                )
                            })
                        {
                            self.closed_loop_tops.push(loop_top);
                            return;
                        }
                    }
                    if self.blocks.len() > stop_len {
                        self.force_close_top(close_at);
                    }
                    // the loop closed HERE, not through the back-edge
                    // handler: register its top so the chain-end back
                    // edge that flows into handle_jump_backward next (and
                    // any dead duplicate padding) reads as closed-loop
                    // padding instead of marking the frame incomplete
                    self.closed_loop_tops.push(loop_top);
                }
            }
        }
    }

    /// py2.6 statement boolop chain fold. Every link compiles to
    /// `JUMP_IF_* L; POP_TOP` (the peek-jump keeps the operand for the
    /// escape path, the POP drops it on fall-through):
    ///
    /// ```text
    ///   eval A; JIF Lelse; POP; eval B; JIF Lelse; POP; THEN ...
    ///   Lelse: POP; ELSE
    ///   eval C; JIT Lmerge; POP; eval D; JIF Lelse; Lmerge: POP; THEN
    /// ```
    ///
    /// `first` is operand 0 (on the live stack; the caller pops it on
    /// success). Each link's polarity combines the operand BEFORE it with
    /// the chain that follows: JIF escape = And, JIT escape = Or. The
    /// chain ends when the region after a link's POP_TOP is no longer
    /// pure-value-then-peek-jump (that region is the THEN body). Returns
    /// (merged cond, then_start, else_body_start, else_pop_offset).
    /// py2.6 ternary merge recognition at a value-preserving JUMP_IF_*:
    /// `JIF target; POP; <then>; JF/JABS M; target: POP; <pure value>; M:`
    /// — returns (then_start, else_start, merge).
    fn py2_ternary_at(&self, ci: Option<usize>, target: usize) -> Option<(usize, usize, usize)> {
        let ci = ci?;
        let then_start = self.instrs.get(ci + 2)?.offset; // past the POP
        if then_start >= target {
            return None;
        }
        // then arm: pure ops ending in a forward jump to the merge
        let mut merge = None;
        for ins in self.instrs.iter() {
            if ins.offset < then_start || ins.offset >= target {
                continue;
            }
            if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP)
                && ins.target.map_or(false, |t| t > target)
            {
                merge = ins.target;
            }
        }
        let merge = merge?;
        // else arm: POP at target, then pure value ops up to the merge
        let ti = self.idx_of.get(&target)?;
        if self.instrs.get(*ti)?.op != Op::POP_TOP {
            return None;
        }
        let else_start = self.instrs.get(ti + 1)?.offset;
        if else_start >= merge {
            return None;
        }
        for ins in self.instrs.iter() {
            if ins.offset < else_start || ins.offset >= merge {
                continue;
            }
            if !is_pure_value_op(ins.op) {
                return None;
            }
        }
        Some((then_start, else_start, merge))
    }

    fn py26_stmt_boolop_chain(
        &self,
        i0: usize,
        first: ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<(ExprRef, usize, usize, usize)> {
        // link 0's target must hold the escape-path POP_TOP
        let &t0i = self.idx_of.get(&target)?;
        if self.instrs.get(t0i).map(|x| x.op) != Some(Op::POP_TOP) {
            return None;
        }
        // pending = (operand, link polarity, escape target) triples
        // awaiting the tail
        let mut pending: Vec<(ExprRef, bool, usize)> = vec![(first, jump_if_true, target)];
        let mut last_target = target;
        let mut k = i0 + 1;
        // POP_TOP dropping operand 0 on fall-through
        if self.instrs.get(k).map(|x| x.op) != Some(Op::POP_TOP) {
            return None;
        }
        k += 1;
        let tail;
        loop {
            // scan the next operand region: pure value ops up to a peek-jump
            let region_start = k;
            let mut link = None;
            while let Some(ins) = self.instrs.get(k) {
                if matches!(ins.op, Op::JUMP_IF_FALSE | Op::JUMP_IF_TRUE)
                    && ins.target.map_or(false, |t| t > ins.offset)
                {
                    link = Some(k);
                    break;
                }
                if !is_pure_value_op(ins.op) && ins.op != Op::POP_TOP {
                    return None;
                }
                k += 1;
            }
            let lk = link?;
            if lk == region_start {
                return None;
            }
            let operand = self.sim_value_region(region_start, lk)?;
            let lins = self.instrs[lk];
            let lt = lins.target?;
            // the link target must hold the escape POP_TOP
            let &lti = self.idx_of.get(&lt)?;
            if self.instrs.get(lti).map(|x| x.op) != Some(Op::POP_TOP) {
                return None;
            }
            let ljit = lins.op == Op::JUMP_IF_TRUE;
            // POP_TOP dropping this operand on fall-through
            k = lk + 1;
            if self.instrs.get(k).map(|x| x.op) != Some(Op::POP_TOP) {
                return None;
            }
            k += 1;
            // another link follows, or is [k, ..) the THEN body? Probe:
            // pure value ops then a forward peek-jump whose target holds
            // POP_TOP → another link. Anything else → body.
            let mut p = k;
            let mut more = false;
            while let Some(ins) = self.instrs.get(p) {
                if matches!(ins.op, Op::JUMP_IF_FALSE | Op::JUMP_IF_TRUE)
                    && ins.target.map_or(false, |t| t > ins.offset)
                {
                    if let Some(t) = ins.target {
                        if let Some(&nti) = self.idx_of.get(&t) {
                            if self.instrs.get(nti).map(|x| x.op) == Some(Op::POP_TOP) {
                                more = true;
                            }
                        }
                    }
                    break;
                }
                if !is_pure_value_op(ins.op) {
                    break;
                }
                p += 1;
            }
            if !more {
                // this link was the statement jump: its fall-through POP
                // was just consumed; the operand is the chain tail.
                // Coherence check: in a real boolop chain every JIF link
                // escapes to the SAME else/end pop and every JIT link to
                // the SAME body pop (at most one distinct JIT target, and
                // it is not the tail's escape). A nested `if a: (if b: X
                // else: Y)` mimics a chain locally — its inner JIF escapes
                // to its own else arm instead — and is rejected here.
                let coherent = pending.iter().all(|(_, j, t)| {
                    if *j == ljit {
                        *t == lt
                    } else {
                        true
                    }
                }) && pending
                    .iter()
                    .filter(|(_, j, _)| *j != ljit)
                    .fold(Some(0usize), |acc, (_, _, t)| match acc {
                        Some(x) if x == 0 || x == *t => Some(*t),
                        _ => None,
                    })
                    .map_or(false, |t| t != lt);
                if !coherent {
                    return None;
                }
                tail = operand;
                last_target = lt;
                break;
            }
            pending.push((operand, ljit, lt));
        }
        // fold right-associatively from the tail: cond = tail, then each
        // pending (operand, polarity) wraps it — And for JIF, Or for JIT
        let mut cond = tail;
        for (operand, jit, _) in pending.into_iter().rev() {
            let kind = if jit { BoolOpKind::Or } else { BoolOpKind::And };
            let mut values = Vec::new();
            flatten_boolop(operand, kind, &mut values);
            flatten_boolop(cond, kind, &mut values);
            cond = Rc::new(Expr::BoolOp { op: kind, values });
        }
        // final link: fall-through after its POP_TOP is the THEN body;
        // the escape POP_TOP at last_target leads the ELSE body
        let then_start = self.instrs.get(k).map(|x| x.offset)?;
        let &lti = self.idx_of.get(&last_target)?;
        let else_body = self.instrs.get(lti + 1).map(|x| x.offset)?;
        Some((cond, then_start, else_body, last_target))
    }

    fn try_merge_py2_boolop(
        &self,
        cond: &ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        macro_rules! bail {
            ($why:expr) => {
                return None
            };
        }
        let instrs = &self.instrs;
        let is_value_op = |o: Op| {
            matches!(
                o,
                Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_DEREF
                    | Op::LOAD_METHOD
                    | Op::LOAD_BUILD_CLASS
                    | Op::COMPARE_OP
                    | Op::IS_OP
                    | Op::CONTAINS_OP
                    | Op::BINARY_OP
                    | Op::BINARY_SUBSCR
                    | Op::CALL
                    | Op::CALL_FUNCTION
                    | Op::CALL_METHOD
                    | Op::CALL_FUNCTION_KW
                    | Op::BUILD_TUPLE
                    | Op::BUILD_LIST
                    | Op::BUILD_MAP
                    | Op::BUILD_SET
                    | Op::BUILD_STRING
                    | Op::UNARY_NOT
                    | Op::UNARY_NEGATIVE
                    | Op::UNARY_INVERT
                    | Op::TO_BOOL
                    | Op::FORMAT_VALUE
                    | Op::GET_ITER
                    | Op::LIST_EXTEND
                    | Op::SET_ADD
                    | Op::MAP_ADD
                    | Op::COPY
                    | Op::NOP
            )
        };
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
                    | Op::POP_JUMP_BACKWARD_IF_FALSE
                    | Op::POP_JUMP_BACKWARD_IF_TRUE
            )
        };
        // scan the fall-through region [cur_next, target) for its terminating
        // cond jump; everything before it must be pure value computation
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            bail!("no ci");
        };
        let Some(&ti) = self.idx_of.get(&target) else {
            bail!("no ti");
        };
        if ti <= ci + 1 {
            bail!("ti too close");
        }
        let mut j0 = None;
        for k in ci + 1..ti {
            let ins = &instrs[k];
            if is_cond_jump(ins.op) && ins.target.unwrap_or(0) > target {
                j0 = Some((k, ins.target.unwrap_or(0), ins.op));
                break;
            }
            if !is_value_op(ins.op) {
                bail!(format!("lhs op {:?}", ins.op));
            }
        }
        let (j0k, e0, j0op) = match j0 { Some(x) => x, None => bail!("no j0") };
        let _ = (j0k, j0op);
        // a genuine merged boolop chain is contiguous: the lhs region's
        // terminating cond jump falls THROUGH straight into the rhs operand
        // region. Any bytecode between j0 and `target` is a statement arm
        // (bz2 3.5-3.7 open(): `if 't' in mode: [if 'b' in mode: raise;
        // JUMP_FORWARD end] else: [encoding guard...]` -- the then arm's
        // raise + hop sat in the gap and the whole if/else was folded into
        // a bogus `'t' in mode and 'b' in mode or encoding is not None`
        // condition, dropping the Invalid-mode raise).
        // SAME-POLARITY j0 (both links jump on the same truth value) is
        // NOT a py2-boolop mixed chain: it is either a flat and/or chain
        // (split_cond's job -- `if i==1 and j==1:` in b16) or a folded
        // `not A or B` first operand (3.7 compiles `not dir or dir==curdir`
        // to PJIF(dir->C) with no UNARY_NOT; merging here yielded
        // `(dir and dir==curdir) and skip_curdir` in compileall 3.7,
        // dropping the negation). Genuine mixed chains always flip
        // polarity between J1 and j0 (PJIT+PJIF or PJIF+PJIT). Defer to
        // split_cond, which merges same-target same-polarity pairs with
        // the correct And semantics.
        let j0_polarity_true = matches!(
            j0op,
            Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE | Op::POP_JUMP_BACKWARD_IF_TRUE
        );
        if j0_polarity_true == jump_if_true
            && self.is_split_cond_region(self.cur_next, instrs[j0k].offset, target, jump_if_true)
        {
            bail!("same-polarity lhs: split_cond territory");
        }
        if instrs.get(j0k + 1).map(|x| x.offset) != Some(target) {
            // tolerate inter-instruction padding, nothing else
            let mut g = j0k + 1;
            while matches!(
                instrs.get(g).map(|x| x.op),
                Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE) | Some(Op::EXTENDED_ARG)
            ) {
                g += 1;
            }
            if instrs.get(g).map(|x| x.offset) != Some(target) {
                bail!("gap after j0");
            }
        }
        // scan the target (rhs) region [target, e0): value ops then a cond
        // jump. Shape A: that jump also targets e0 (shared exit E):
        //   (c1 OP c2) AND c3. Shape B: it targets some E != e0 (e0 is the
        //   then-body): (c1 OP c2) OR c3.
        let Some(&ei) = self.idx_of.get(&e0) else {
            bail!("no ei");
        };
        if ei <= ti {
            bail!("ei <= ti");
        }
        let mut j2 = None;
        let mut j2k = 0usize;
        let mut j2_target = 0usize;
        for k in ti..ei {
            let ins = &instrs[k];
            if is_cond_jump(ins.op) {
                if let Some(t) = ins.target {
                    if t > self.cur_offset {
                        j2 = Some(ins.op);
                        j2k = k;
                        j2_target = t;
                        break;
                    }
                }
                bail!("rhs jump backward");
            }
            if !is_value_op(ins.op) {
                bail!(format!("rhs op {:?}", ins.op));
            }
        }
        let j2op = match j2 { Some(x) => x, None => bail!("no j2") };
        let then_start = instrs[j2k].end();
        let e = j2_target;
        // every false-exit of a merged boolop chain lands at or past the
        // chain's shared skip (e0): shape And shares it outright, shape Or
        // exits past the body. A j2 landing BEFORE e0 is an inner statement
        // guard of the enclosing if's BODY (abc 2.7 __instancecheck__: the
        // body opens with `if B and C: return False`, whose B/C PJIFs skip
        // to the body-internal return) -- folding it as a chain operand
        // swallows the nested guard and flattens the bodies.
        if e < e0 {
            bail!("j2 before shared exit");
        }
        // Shape sanity: the captured rhs operand must be the LAST one and
        // [then_start, e) must be the real BODY.
        if j2_target == e0 {
            // shape And (shared skip): the body may open with a nested if
            // guard, but that guard's cond jump must skip to the shared
            // exit e0 (compileall compile_path `if quiet<2: print` guards
            // to the back edge at 54... its PJIF targets 80 which is the
            // loop back edge PAST e0 -- accept targets >= e0). abc 2.7
            // __instancecheck__ misfire: the "body" opened with the nested
            // guard's PJIF targeting 143, strictly BEFORE e0=156 -- the
            // span was an inner if's condition, not this chain's body.
            // the "body" [then_start, e) must not itself be an operand
            // region (pure value ops terminated by a cond jump): that is
            // the `if not A or B: if not C: stmt` inversion, where J1 is
            // the folded-not or-join landing on the BODY and j2 is the
            // nested guard whose skip coincides with the outer skip
            // (configparser 3.7-3.9 _validate_value_types folded into
            // `if (A and B) and C: raise`). Genuine And-shape bodies may
            // OPEN with a nested guard (compileall compile_path), but a
            // statement op always follows it before e.
            let mut k2 = j2k + 1;
            let mut all_value = true;
            while let Some(ins) = instrs.get(k2) {
                if ins.offset >= e {
                    break;
                }
                if is_cond_jump(ins.op) {
                    k2 += 1;
                    continue;
                }
                if !is_value_op(ins.op) {
                    all_value = false;
                    break;
                }
                k2 += 1;
            }
            if all_value {
                bail!("and-shape body is operand material");
            }
        } else {
            // shape Or: j0 jumps straight to the body (e0 == body start)
            // and j2 must be the LAST instruction before it. `(A1 and A2)
            // or (B1 and B2)` (codecs 3.6-3.9 StreamReader.read) leaves
            // the un-captured B2 operand between j2 and e0; folding only
            // B1 produced `((A1 and A2) or B1) and B2`, applying B2 to
            // str data.
            if e0 != then_start {
                bail!("or-shape rhs continues past j2");
            }
        }
        // the rhs operand region must not contain a terminator before j2:
        // an operand is a pure value, it cannot RETURN/RAISE mid-region
        if instrs[ti..j2k]
            .iter()
            .any(|x| matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS))
        {
            bail!("rhs terminator");
        }
        // J1 semantics: c1_jit=true means c1 joins when TRUE (or)
        let c1_true = jump_if_true;
        let c2_true = matches!(
            j0op,
            Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE | Op::POP_JUMP_BACKWARD_IF_TRUE
        );
        let c3_true = matches!(
            j2op,
            Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE | Op::POP_JUMP_BACKWARD_IF_TRUE
        );
        // shape validity is enforced by the region scans and target
        // relations; J0/J2 polarities decide the operators below
        // c1 and c2 combine via c1's jump polarity (both reach the rhs
        // region when "joining"). Outer: shared exit (shape A) -> And with
        // c3; J0 jumping to the then-body (shape B) -> Or with c3.
        let inner_kind = if c1_true { BoolOpKind::Or } else { BoolOpKind::And };
        let outer_kind = if j2_target == e0 {
            BoolOpKind::And
        } else {
            BoolOpKind::Or
        };
        let _ = (c2_true, c3_true);
        // simulate both operand regions on a scratch stack
        let lhs_e = match self.sim_value_region(ci + 1, j0k) { Some(x) => x, None => bail!("lhs sim") };
        let rhs_e = match self.sim_value_region(ti, j2k) { Some(x) => x, None => bail!("rhs sim") };
        let lhs = Rc::new(Expr::BoolOp {
            op: inner_kind,
            values: vec![cond.clone(), lhs_e],
        }) as ExprRef;
        let merged = Rc::new(Expr::BoolOp {
            op: outer_kind,
            values: vec![lhs, rhs_e],
        }) as ExprRef;
        Some((merged, then_start, e))
    }

    /// Detect `if a or b: body` / mixed and-chains: J1 (this jump) targets
    /// the body start; [next, target) is a pure operand region ending in an
    /// opposite-polarity cond jump J0 to the if exit; the merged If covers
    /// [target, J0.target). Returns (cond, body_start, exit).
    fn try_merge_or_cond(
        &self,
        cond: &ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<(ExprRef, usize, usize, usize)> {
        // General same-body boolop condition chains:
        //   `if a or b or c: BODY else: ELSE` compiles to a sequence of
        //   pure operand regions each terminated by a cond jump; jumps to
        //   BODY-start mean "operand joins on jump", the final jump to the
        //   if-exit means "operand joins on fall-through". Two-operand
        //   same-exit chains (`a and b`) are handled by the split-cond
        //   merge instead; require at least one body-targeting jump here.
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
                    | Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_IF_NOT_NONE
                    | Op::POP_JUMP_FORWARD_IF_NONE
                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
            )
        };
        let jump_true =
            |o: Op| matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE);
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return None;
        };
        let Some(&ti) = self.idx_of.get(&target) else {
            return None;
        };
        if ti <= ci + 1 || ti >= self.instrs.len() {
            return None;
        }
        // operand 1 joins via this jump. CHAIN-OR: when this cond jump
        // exits a statement-level chained comparison (`if a==b==c or d:`),
        // the earlier chain links opened nested If blocks whose ends are the
        // trampoline POP_TOP cleanups — fold their conds into the first
        // operand via merge_chain_compare; the caller pops the absorbed
        // blocks when the merge succeeds.
        let mut first: ExprRef = if jump_if_true {
            cond.clone()
        } else {
            Rc::new(Expr::Unary { op: UnaryOp::Not, operand: cond.clone() })
        };
        let mut chain_blocks = 0usize;
        {
            let mut depth = 0;
            while let Some(b) = self.blocks.iter().rev().nth(depth) {
                if !matches!(b.kind, BlockType::If) {
                    break;
                }
                let is_link = b.end < target
                    && self
                        .idx_of
                        .get(&b.end)
                        .and_then(|&ei| self.instrs.get(ei))
                        .map_or(false, |x| x.op == Op::POP_TOP);
                if !is_link {
                    break;
                }
                match b.cond.as_ref() {
                    Some(c) => match merge_chain_compare(c, &first) {
                        Some(m) => {
                            first = m;
                            chain_blocks += 1;
                            depth += 1;
                        }
                        None => break,
                    },
                    None => break,
                }
            }
        }
        let mut parts: Vec<ExprRef> = vec![first];
        // J1 itself targets the body start — it is the first body jump
        let mut body_jumps = 1usize;
        let mut k = ci + 1;
        let mut exit: Option<usize> = None;
        let mut final_was_exit_jump = false;
        loop {
            // scan the next pure operand region up to its cond jump
            let mut region_start = k;
            let mut jidx = None;
            let mut saw_trampoline = false;
            while k < self.instrs.len() {
                let ins = &self.instrs[k];
                if is_cond_jump(ins.op) {
                    jidx = Some(k);
                    break;
                }
                // chain-or trampoline: the chain-false path hops (JF) over
                // the POP_TOP cleanup into the next or operand — resume the
                // operand scan at the continuation (once per region)
                if !saw_trampoline
                    && matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                    && !ins.is_backward
                    && ins.target
                        .map_or(false, |t| t > ins.offset && t < target)
                {
                    if let Some(&tk) = self.idx_of.get(&ins.target.unwrap()) {
                        saw_trampoline = true;
                        k = tk;
                        region_start = tk;
                        continue;
                    }
                    return None;
                }
                if !is_pure_value_op(ins.op)
                    && !matches!(
                        ins.op,
                        // chain-head bookkeeping for a chained-comparison
                        // operand (DUP/ROT <=3.11, SWAP/COPY 3.12+): admit
                        // locally — globally they delimit other scans
                        Op::DUP_TOP | Op::ROT_TWO | Op::ROT_THREE | Op::SWAP
                    )
                    || ins.offset >= target
                {
                    return None;
                }
                k += 1;
            }
            let jk = jidx?;
            // the operand's exit jump must lead DIRECTLY to the merged
            // if's exit on its false path: a real statement (raise /
            // store / return / print ...) between this jump and the
            // body start means the jump is a nested GUARD's skip and
            // its fall-through is an arm body, not operand material —
            // folding it as an or-operand swallows that arm and inverts
            // the flow (py2.7 Queue put/get: `if not block: if
            // _qsize()==maxsize: raise Full` merged as `if block or
            // _qsize()==maxsize:`, losing raise Full, the timeout<0
            // ValueError and the whole timed-wait else arm)
            if self.instrs[jk + 1..]
                .iter()
                .take_while(|x| x.offset < target)
                // stop at the next cond jump: material past it is the
                // NEXT operand link's region (a chain-or-chain's second
                // comparison + shared body live there — b23
                // or_chain_chain), not this operand's fall-through
                .take_while(|x| {
                    !is_cond_jump(x.op)
                })
                .any(|x| {
                    matches!(
                        x.op,
                        Op::RAISE_VARARGS
                            | Op::RETURN_VALUE
                            | Op::RETURN_CONST
                            | Op::STORE_FAST
                            | Op::STORE_NAME
                            | Op::STORE_GLOBAL
                            | Op::STORE_ATTR
                            | Op::STORE_SUBSCR
                            | Op::STORE_DEREF
                            | Op::STORE_MAP
                            | Op::DELETE_FAST
                            | Op::DELETE_NAME
                            | Op::DELETE_GLOBAL
                            | Op::DELETE_ATTR
                            | Op::DELETE_DEREF
                            | Op::PRINT_ITEM
                            | Op::PRINT_NEWLINE
                            | Op::YIELD_VALUE
                            | Op::YIELD_FROM
                            | Op::IMPORT_STAR
                            | Op::EXEC_STMT
                            | Op::BREAK_LOOP
                            | Op::RERAISE
                    )
                })
            {
                return None;
            }
            // chain-head operand regions (DUP/ROT or SWAP/COPY + CMP) leave
            // the retained middle operand under the comparison — tolerate
            // that one residual, prefer the strict single-value sim
            let operand = self
                .sim_value_region(region_start, jk)
                .or_else(|| self.sim_value_region_ex(region_start, jk, true))?;
            let jins = &self.instrs[jk];
            let jt = jump_true(jins.op);
            // the condition under which this operand's jump FIRES (the
            // NONE family tests the operand value directly — `if size
            // is None or ...` joins via PJIF_NONE, codecs 3.12
            // readline `not data or size is not None`)
            let jc: ExprRef = if matches!(
                jins.op,
                Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_FORWARD_IF_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NONE
            ) {
                Rc::new(Expr::Compare {
                    operands: vec![
                        operand.clone(),
                        Rc::new(Expr::Const(Rc::new(PyObject::None))),
                    ],
                    ops: vec![CmpOp::Is],
                })
            } else if matches!(
                jins.op,
                Op::POP_JUMP_IF_NOT_NONE
                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
            ) {
                Rc::new(Expr::Compare {
                    operands: vec![
                        operand.clone(),
                        Rc::new(Expr::Const(Rc::new(PyObject::None))),
                    ],
                    ops: vec![CmpOp::IsNot],
                })
            } else if matches!(
                jins.op,
                Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
            ) {
                operand.clone()
            } else {
                Rc::new(Expr::Unary {
                    op: UnaryOp::Not,
                    operand: operand.clone(),
                })
            };
            match jins.target {
                Some(t) if t == target => {
                    // jumps to the body: operand joins when the jump fires
                    parts.push(jc);
                    body_jumps += 1;
                    k = jk + 1;
                    if k >= ti {
                        return None; // no final operand before the body
                    }
                }
                Some(t) if t > target && self.idx_of.contains_key(&t) => {
                    // final operand: its jump skips the body (if exit) and
                    // must be the last instruction before the body starts
                    // (3.14 pads the body head with NOT_TAKEN)
                    let mut nj = jk + 1;
                    while matches!(
                        self.instrs.get(nj).map(|x| x.op),
                        Some(Op::NOT_TAKEN) | Some(Op::NOP)
                    ) {
                        nj += 1;
                    }
                    if nj != ti {
                        return None;
                    }
                    // operand joins on FALL-THROUGH: the negation of the
                    // jump-fires condition. NONE family folds Is<->IsNot;
                    // the TRUE/FALSE families keep the explicit Not form
                    // (negate_cond would flip `is`->`is not` and recompile
                    // to inverted polarity — bdb 3.7 or-merge regression)
                    parts.push(if matches!(
                        jins.op,
                        Op::POP_JUMP_IF_NONE
                            | Op::POP_JUMP_FORWARD_IF_NONE
                            | Op::POP_JUMP_BACKWARD_IF_NONE
                            | Op::POP_JUMP_IF_NOT_NONE
                            | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                            | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                    ) {
                        negate_cond(jc)
                    } else if jt {
                        Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
                    } else {
                        operand
                    });
                    exit = Some(t);
                    final_was_exit_jump = true;
                    break;
                }
                Some(t)
                    if !jt
                        && t < target
                        && self
                            .idx_of
                            .get(&t)
                            .and_then(|&ci2| self.instrs.get(ci2))
                            .map_or(false, |x| x.op == Op::POP_TOP) =>
                {
                    // chain-or-CHAIN: this operand is itself a chained
                    // comparison whose mid-link PJIFs exit to [POP_TOP;
                    // else-copy] stubs lexically BEFORE the (duplicated)
                    // body — CPython small-block duplication for
                    // `(a==b==c) or (d==e==f)`. Walk the chain's
                    // continuation links, folding each into the operand via
                    // merge_chain_compare, until the final link's exit jump
                    // past the body: its target is the canonical else, and
                    // the fall-through body ends there, so [target, exit)
                    // is exactly the body copy the first chain's body-jump
                    // already targets.
                    let mut acc = operand;
                    let mut k2 = jk + 1;
                    let mut chain_exit: Option<usize> = None;
                    loop {
                        let rs = k2;
                        let mut j2 = None;
                        let mut steps = 0;
                        while let Some(ins) = self.instrs.get(k2) {
                            if is_cond_jump(ins.op) {
                                j2 = Some(k2);
                                break;
                            }
                            if !is_pure_value_op(ins.op) {
                                break;
                            }
                            k2 += 1;
                            steps += 1;
                            if steps > 32 {
                                break;
                            }
                        }
                        let Some(j2i) = j2 else { return None };
                        let j2ins = &self.instrs[j2i];
                        let Some(t2) = j2ins.target else {
                            return None;
                        };
                        // the continuation link's comparison sits right
                        // before its jump; the region before the comparison
                        // is the rhs — the lhs is the chain's retained
                        // middle operand (= acc's last operand, not lexical)
                        let cmp_i = match self.match_prev_real(j2i) {
                            Some(x) if x >= rs => x,
                            _ => return None,
                        };
                        if self.instrs[cmp_i].op != Op::COMPARE_OP {
                            return None;
                        }
                        let rhs = self.sim_value_region(rs, cmp_i)?;
                        let last = match &*acc {
                            Expr::Compare { operands, .. } => {
                                operands.last()?.clone()
                            }
                            _ => return None,
                        };
                        let link: ExprRef = Rc::new(Expr::Compare {
                            operands: vec![last, rhs],
                            ops: vec![cmp_from_index(compare_op_index(
                                self.instrs[cmp_i].arg as u32,
                                self.version,
                            ))],
                        });
                        if t2 > target {
                            // final link: false exits to the canonical else;
                            // the fall-through body ends at that offset
                            if jump_true(j2ins.op) {
                                return None;
                            }
                            acc = merge_chain_compare(&acc, &link)?;
                            chain_exit = Some(t2);
                            break;
                        }
                        // mid link: fold and continue past it
                        acc = merge_chain_compare(&acc, &link)?;
                        k2 = j2i + 1;
                    }
                    let Some(ex) = chain_exit else {
                        return None;
                    };
                    parts.push(acc);
                    exit = Some(ex);
                    final_was_exit_jump = true;
                    break;
                }
                _ => return None,
            }
        }
        let exit = match exit {
            Some(e) => e,
            None => {
                // every operand jumped to the body (`not a or not b`): the
                // fall-through region between the chain and the body is the
                // ELSE; find its terminating forward jump
                if body_jumps < 2 {
                    return None;
                }
                let mut e2 = None;
                for m in k..ti {
                    let ins = &self.instrs[m];
                    if !is_pure_value_op(ins.op) {
                        if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                            && ins.target.map_or(false, |t| t > target)
                            && m + 1 == ti
                        {
                            e2 = ins.target;
                        }
                        break;
                    }
                }
                e2?
            }
        };
        if body_jumps == 0 || parts.len() < 2 {
            return None;
        }
        // mixed chains combine as Or; all-body-jump chains are the De Morgan
        // dual: And of the (negated) join forms
        let op = if final_was_exit_jump {
            BoolOpKind::Or
        } else {
            BoolOpKind::And
        };
        // don't fire inside loops whose exit this might be (break shape)
        if self.find_loop_exit(exit).is_some() || self.find_loop_exit(target).is_some() {
            return None;
        }
        // rotated `while a or b:` — the body region loops back to this
        // condition; leave it to the while machinery
        if let (Some(&bi), Some(&ei)) = (self.idx_of.get(&target), self.idx_of.get(&exit)) {
            if self.instrs[bi..ei]
                .iter()
                .any(|x| x.is_backward && x.target.map_or(false, |t| t <= self.cur_offset))
            {
                return None;
            }
        }
        let merged = Rc::new(Expr::BoolOp { op, values: parts }) as ExprRef;
        Some((merged, target, exit, chain_blocks))
    }

    /// Fused `if a or b [or c]: continue` chain (common on py2): the first
    /// operand's cond jump targets the LOOP TOP; further operands jump to
    /// the loop top as well, and the last one jumps forward over a body
    /// that is exactly a back-edge jump. Returns (cond, body_start,
    /// body_end).
    /// Polarity of the conditional jump at instruction index `ci`.
    fn jump_if_true_at_ci(&self, ci: usize) -> bool {
        matches!(
            self.instrs.get(ci).map(|i| i.op),
            Some(Op::POP_JUMP_IF_TRUE) | Some(Op::POP_JUMP_FORWARD_IF_TRUE)
        )
    }

    /// Forward or-continue chain probe: see handle_cond_jump. Returns
    /// (merged Or condition, offset just past the back edge = skip
    /// target). The current jump is the FIRST operand (PJIT to the loop
    /// top); the second operand's PJIF skips the back edge into the body.
    fn is_loop_top_target(&self, t: usize) -> bool {
        self.blocks.iter().any(|b| {
            matches!(b.kind, BlockType::While | BlockType::For)
                && (b.start == t
                    || (b.cond_end != usize::MAX && b.start <= t && t < b.cond_end))
        })
    }

    fn try_fwd_or_continue(&self, target: usize, first: &ExprRef) -> Option<(ExprRef, usize)> {
        let dbg = std::env::var("PYCDC_FOC_DBG").is_ok();
        // pre-3.8 has no back-edge redirect: the target may be the back
        // edge instruction itself - normalize to the loop top
        let top_target = self
            .idx_of
            .get(&target)
            .and_then(|&ti| {
                let ins = self.instrs.get(ti)?;
                if ins.is_backward
                    && matches!(
                        ins.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                    )
                {
                    ins.target
                } else {
                    None
                }
            })
            .unwrap_or(target);
        macro_rules! bail {
            ($why:expr) => {{
                if dbg { eprintln!("FOC[{}] off={}: bail {}", self.code.name, self.cur_offset, $why); }
                return None;
            }};
        }
        // enclosing loop whose top is the redirect target
        let loop_blk = self.blocks.iter().rev().find(|b| {
            matches!(b.kind, BlockType::While | BlockType::For)
                && (b.start == top_target
                    || (b.cond_end != usize::MAX && b.cond_end == top_target))
        }) else { bail!("no-loop") };
        let _ = loop_blk;
        let ci = *self.idx_of.get(&self.cur_offset)?;
        // second operand region: pure value ops up to its cond jump
        let mut k = ci + 1;
        let mut steps = 0;
        while let Some(ins) = self.instrs.get(k) {
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                break;
            }
            if !is_pure_value_op(ins.op)
                && !matches!(
                    ins.op,
                    Op::NOP
                        | Op::NOT_TAKEN
                        | Op::CACHE
                        | Op::TO_BOOL
                        | Op::COMPARE_OP
                        | Op::IS_OP
                        | Op::CONTAINS_OP
                        | Op::UNARY_NOT
                        | Op::UNARY_NEGATIVE
                        | Op::UNARY_POSITIVE
                        | Op::UNARY_INVERT
                        | Op::BINARY_ADD
                        | Op::BINARY_SUBTRACT
                        | Op::BINARY_MULTIPLY
                        | Op::BINARY_TRUE_DIVIDE
                        | Op::BINARY_FLOOR_DIVIDE
                        | Op::BINARY_MODULO
                        | Op::BINARY_POWER
                        | Op::BINARY_LSHIFT
                        | Op::BINARY_RSHIFT
                        | Op::BINARY_AND
                        | Op::BINARY_OR
                        | Op::BINARY_XOR
                )
            {
                bail!(format!("scan-op {:?}", ins.op));
            }
            k += 1;
            steps += 1;
            if steps > 64 {
                bail!("scan-len");
            }
        }
        let Some(j2) = self.instrs.get(k) else { bail!("scan-end") };
        if !matches!(
            j2.op,
            Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
        ) {
            bail!("no-j2");
        }
        let Some(body_at) = j2.target else { bail!("j2-no-target") };
        if body_at <= j2.offset {
            bail!("j2-back");
        }
        // operand 2 = the value region before j2's comparison
        // operand 2 = the whole region up to j2, simulated through its
        // comparison (the region yields exactly one value: the test)
        if k <= ci + 1 {
            bail!("empty-region");
        }
        let Some(second) = self.sim_value_region_ex(ci + 1, k, false) else {
            bail!("sim");
        };
        // between j2 and the body: exactly the loop's back edge
        let mut m = k + 1;
        while matches!(
            self.instrs.get(m).map(|x| x.op),
            Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
        ) {
            m += 1;
        }
        let e = self.instrs.get(m)?;
        if !(e.is_backward
            && e.target == Some(top_target)
            && matches!(
                e.op,
                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT
            ))
        {
            bail!(format!("no-backedge at {:?} tgt={:?} want={}", e.op, e.target, top_target));
        }
        let mut m2 = m + 1;
        loop {
            while matches!(
                self.instrs.get(m2).map(|x| x.op),
                Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
            ) {
                m2 += 1;
            }
            // py2 pads the continue landing with a zero-hop JUMP_FORWARD
            // onto the body start
            let pad_hop = self
                .instrs
                .get(m2)
                .map(|x| {
                    matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                        && !x.is_backward
                        && x.target == Some(body_at)
                        && x.offset != body_at
                })
                .unwrap_or(false);
            if pad_hop {
                m2 += 1;
                continue;
            }
            break;
        }
        if self.instrs.get(m2).map(|x| x.offset) != Some(body_at) {
            bail!("body-mismatch");
        }
        let mut values = Vec::new();
        flatten_boolop(first.clone(), BoolOpKind::Or, &mut values);
        flatten_boolop(second, BoolOpKind::Or, &mut values);
        Some((
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::Or,
                values,
            }),
            self.instrs.get(m2).map(|x| x.offset).unwrap_or(body_at),
        ))
    }


    /// 3.8-3.11 loop-tail `if A or B: break` guard: A's PJIT flies
    /// straight to the loop exit (the break landing); B's operand run
    /// ends in PJFF links that land on the loop top (continue) — either
    /// directly or through a POP_TOP cleanup trampoline dropping a
    /// chained comparison's retained middle operand — and the
    /// fall-through after the last link is the break jump (a JF/JABS to
    /// the loop exit or to a stub jumping there). Per-jump rendering
    /// split this into `if A: break` + `if B: pass` + an UNCONDITIONAL
    /// break (cgi 3.8/3.9 read_multi `if part.done or self.bytes_read
    /// >= self.length > 0: break`). Returns (merged Or cond, resume
    /// offset = the loop's natural back edge after the break stub).
    fn try_or_break_chain(&self, cond: &ExprRef, target: usize) -> Option<(ExprRef, usize)> {
        let dbg = std::env::var("PYCDC_OBC_DBG").is_ok();
        macro_rules! bail {
            ($why:expr) => {{
                if dbg {
                    eprintln!(
                        "OBC[{}] off={}: bail {}",
                        self.code.name, self.cur_offset, $why
                    );
                }
                return None;
            }};
        }
        let ci = *self.idx_of.get(&self.cur_offset)?;
        // A must break the innermost open loop on TRUE
        let loop_blk = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))?;
        let exit = self.loop_exit_offset(loop_blk)?;
        if self.effective_offset(exit) != self.effective_offset(target) {
            bail!("target-not-exit");
        }
        let loop_top = loop_blk.start;
        // resolve a jump-target offset to its logical instruction index:
        // the target may land on an EXTENDED_ARG prefix byte, which
        // idx_of maps to the PREVIOUS instruction's end() (3.8 cgi
        // read_multi's continue stub `572: EXTARG; 574: JABS` resolved
        // to the break stub JABS@570 whose end is 572)
        let idx_at = |off: usize| -> Option<usize> {
            if let Some(&i) = self.idx_of.get(&off) {
                if self.instrs[i].offset == off {
                    return Some(i);
                }
            }
            self.instrs.iter().position(|x| x.start == off)
        };
        // does `t` land on the loop top (a continue)? — directly, or via
        // a chained-comparison cleanup trampoline ([POP_TOP;] JF -> stub)
        // whose stub is [pads;] JABS -> loop top
        let lands_on_top = |t: usize| -> bool {
            if t == loop_top {
                return true;
            }
            let Some(tk) = idx_at(t) else {
                return false;
            };
            let is_pad = |k: usize| {
                matches!(
                    self.instrs.get(k).map(|x| x.op),
                    Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
                )
            };
            let mut k = tk;
            let mut pops = 0;
            while matches!(self.instrs.get(k).map(|x| x.op), Some(Op::POP_TOP)) {
                k += 1;
                pops += 1;
            }
            if pops == 0 || pops > 2 {
                return false;
            }
            while is_pad(k) {
                k += 1;
            }
            let Some(jf) = self.instrs.get(k) else {
                return false;
            };
            if !matches!(jf.op, Op::JUMP_FORWARD | Op::JUMP) || jf.is_backward {
                return false;
            }
            let Some(t2) = jf.target else {
                return false;
            };
            let Some(t2k) = idx_at(t2) else {
                return false;
            };
            let mut k2 = t2k;
            while matches!(
                self.instrs.get(k2).map(|x| x.op),
                Some(Op::NOP)
                    | Some(Op::NOT_TAKEN)
                    | Some(Op::CACHE)
                    | Some(Op::EXTENDED_ARG)
            ) {
                k2 += 1;
            }
            let Some(jb) = self.instrs.get(k2) else {
                return false;
            };
            jb.is_backward
                && jb.target == Some(loop_top)
                && matches!(
                    jb.op,
                    Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
        };
        // walk B's links
        let mut acc: Option<ExprRef> = None;
        let mut k = ci + 1;
        let mut region_start = ci + 1;
        let mut resume: Option<usize> = None;
        loop {
            // next PJFF link (or the break fall-through)
            let mut jk = None;
            while let Some(ins) = self.instrs.get(k) {
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                ) {
                    jk = Some(k);
                    break;
                }
                if matches!(
                    ins.op,
                    Op::JUMP_FORWARD
                        | Op::JUMP
                        | Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                ) {
                    // the chain's true fall-through: the break jump —
                    // handled by the no-more-links arm below
                    break;
                }
                if ins.offset >= target {
                    bail!("ran-past-exit");
                }
                if !is_pure_value_op(ins.op)
                    && !matches!(
                        ins.op,
                        Op::NOP
                            | Op::NOT_TAKEN
                            | Op::CACHE
                            | Op::TO_BOOL
                            | Op::EXTENDED_ARG
                            | Op::COMPARE_OP
                            | Op::IS_OP
                            | Op::CONTAINS_OP
                            | Op::DUP_TOP
                            | Op::ROT_TWO
                            | Op::ROT_THREE
                            | Op::ROT_FOUR
                            | Op::SWAP
                            | Op::COPY
                    )
                {
                    bail!(format!("scan-op {:?}", ins.op));
                }
                k += 1;
            }
            let Some(jk) = jk else {
                // no more links: the fall-through must be the break jump
                let ins = self.instrs.get(k)?;
                let Some(bt) = ins.target else {
                    bail!("fallthrough-no-target");
                };
                if !matches!(
                    ins.op,
                    Op::JUMP_FORWARD
                        | Op::JUMP
                        | Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                ) {
                    bail!(format!("fallthrough-op {:?}", ins.op));
                }
                // break landing: the exit itself, or a stub [pads;] JABS -> exit
                let lands_on_exit = |t: usize| -> Option<usize> {
                    if self.effective_offset(t) == self.effective_offset(target) {
                        return Some(t);
                    }
                    let Some(tk) = idx_at(t) else {
                        return None;
                    };
                    let mut k2 = tk;
                    while matches!(
                        self.instrs.get(k2).map(|x| x.op),
                        Some(Op::NOP)
                            | Some(Op::NOT_TAKEN)
                            | Some(Op::CACHE)
                            | Some(Op::EXTENDED_ARG)
                    ) {
                        k2 += 1;
                    }
                    let jb = self.instrs.get(k2)?;
                    if matches!(
                        jb.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                            | Op::JUMP_FORWARD
                            | Op::JUMP
                    ) && jb
                        .target
                        .map_or(false, |t2| self.effective_offset(t2) == self.effective_offset(target))
                    {
                        // resume past the stub's jump
                        let mut k3 = k2 + 1;
                        while matches!(
                            self.instrs.get(k3).map(|x| x.op),
                            Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
                        ) {
                            k3 += 1;
                        }
                        return Some(self.instrs.get(k3).map(|x| x.offset).unwrap_or(jb.end()));
                    }
                    None
                };
                let Some(r) = lands_on_exit(bt) else {
                    bail!("fallthrough-not-break")
                };
                resume = Some(r.max(ins.end()));
                break;
            };
            let jins = &self.instrs[jk];
            let Some(t) = jins.target else {
                bail!("link-no-target");
            };
            if !lands_on_top(t) {
                bail!(format!("link-target {} not-continue", t));
            }
            // reconstruct the comparison link ending at jk
            let cmp_i = match self.match_prev_real(jk) {
                Some(x) if x >= region_start => x,
                _ => bail!("no-prev-cmp"),
            };
            match self.instrs[cmp_i].op {
                Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP => {}
                other => bail!(format!("link-cmp {:?}", other)),
            }
            let link_expr = if acc.is_none() {
                // first link: the region INCLUDES the comparison (chain
                // head setup DUP/ROT leaves the middle operand residual)
                let e = self.sim_value_region_ex(region_start, jk, true);
                let Some(e) = e else { bail!("head-sim") };
                e
            } else {
                let rhs = self.sim_value_region(region_start, cmp_i);
                let Some(rhs) = rhs else { bail!("rhs-sim") };
                let op = if self.instrs[cmp_i].op == Op::COMPARE_OP {
                    cmp_from_index(compare_op_index(
                        self.instrs[cmp_i].arg as u32,
                        self.version,
                    ))
                } else {
                    bail!("non-cmp-link");
                };
                let prev = acc.clone().unwrap();
                let last = match &*prev {
                    Expr::Compare { operands, .. } => operands.last().cloned(),
                    _ => None,
                };
                let Some(last) = last else { bail!("acc-not-compare") };
                let link: ExprRef = Rc::new(Expr::Compare {
                    operands: vec![last, rhs],
                    ops: vec![op],
                });
                let m = merge_chain_compare(&prev, &link);
                let Some(m) = m else { bail!("chain-merge") };
                m
            };
            acc = Some(link_expr);
            region_start = jk + 1;
            k = jk + 1;
        }
        let Some(b_expr) = acc else { bail!("no-links") };
        let resume = resume?;
        let mut values = Vec::new();
        flatten_boolop(cond.clone(), BoolOpKind::Or, &mut values);
        flatten_boolop(b_expr, BoolOpKind::Or, &mut values);
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values,
        });
        if dbg {
            eprintln!(
                "OBC[{}] off={}: MERGED resume={}",
                self.code.name, self.cur_offset, resume
            );
        }
        Some((merged, resume))
    }


    /// 3.8-3.11 `if A and (b<c<d): break` guard: the first operand's
    /// PJIF skips to the body; a statement-level chained comparison
    /// follows whose mid links escape through a POP_TOP cleanup
    /// trampoline dropping the retained middle operand (or straight to
    /// the same skip) and whose true fall-through is a jump onto the
    /// guard body — a break stub flying to the loop exit. Per-jump
    /// rendering split this into `if A:` + nested `if chain: pass` + an
    /// UNCONDITIONAL break (cgi 3.8/3.9 read_lines_to_outerboundary
    /// `if self.limit is not None and 0 <= self.limit <= _read: break`
    /// broke out whenever limit was set). Returns (merged And cond,
    /// guard-body start, guard-body end = the shared skip).
    fn try_and_chain_break_guard(
        &self,
        cond: &ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        let dbg = std::env::var("PYCDC_ACB_DBG").is_ok();
        macro_rules! bail {
            ($why:expr) => {{
                if dbg {
                    eprintln!(
                        "ACB[{}] off={}: bail {}",
                        self.code.name, self.cur_offset, $why
                    );
                }
                return None;
            }};
        }
        let ci = *self.idx_of.get(&self.cur_offset)?;
        let skip = target;
        // resolve a jump-target offset to its logical instruction index
        // (the target may land on an EXTENDED_ARG prefix byte that idx_of
        // maps to the PREVIOUS instruction's end())
        let idx_at = |off: usize| -> Option<usize> {
            if let Some(&i) = self.idx_of.get(&off) {
                if self.instrs[i].offset == off {
                    return Some(i);
                }
            }
            self.instrs.iter().position(|x| x.start == off)
        };
        let is_pad = |k: usize| {
            matches!(
                self.instrs.get(k).map(|x| x.op),
                Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
            )
        };
        // does the link target `t` reach the shared skip — directly or
        // through the chain's POP_TOP cleanup trampoline?
        let skip_or_tramp = |t: usize| -> bool {
            if self.effective_offset(t) == self.effective_offset(skip) {
                return true;
            }
            let Some(tk) = idx_at(t) else {
                return false;
            };
            let mut k = tk;
            let mut pops = 0;
            while matches!(self.instrs.get(k).map(|x| x.op), Some(Op::POP_TOP)) {
                k += 1;
                pops += 1;
            }
            if pops == 0 || pops > 2 {
                return false;
            }
            while is_pad(k) {
                k += 1;
            }
            let Some(jf) = self.instrs.get(k) else {
                return false;
            };
            if !matches!(jf.op, Op::JUMP_FORWARD | Op::JUMP) || jf.is_backward {
                return false;
            }
            jf.target
                .map_or(false, |t2| self.effective_offset(t2) == self.effective_offset(skip))
        };
        // walk the chain links
        let mut acc: Option<ExprRef> = None;
        let mut k = ci + 1;
        let mut region_start = ci + 1;
        let mut true_jump: Option<usize> = None;
        loop {
            let mut jk = None;
            while let Some(ins) = self.instrs.get(k) {
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                ) {
                    jk = Some(k);
                    break;
                }
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP) && !ins.is_backward {
                    // the chain's true fall-through: the guard-body jump
                    true_jump = Some(k);
                    break;
                }
                if ins.offset >= skip {
                    bail!("ran-past-skip");
                }
                if !is_pure_value_op(ins.op)
                    && !matches!(
                        ins.op,
                        Op::NOP
                            | Op::NOT_TAKEN
                            | Op::CACHE
                            | Op::TO_BOOL
                            | Op::EXTENDED_ARG
                            | Op::COMPARE_OP
                            | Op::IS_OP
                            | Op::CONTAINS_OP
                            | Op::DUP_TOP
                            | Op::ROT_TWO
                            | Op::ROT_THREE
                            | Op::ROT_FOUR
                            | Op::SWAP
                            | Op::COPY
                    )
                {
                    bail!(format!("scan-op {:?}", ins.op));
                }
                k += 1;
            }
            let Some(jk) = jk else {
                break;
            };
            let jins = &self.instrs[jk];
            let Some(t) = jins.target else {
                bail!("link-no-target");
            };
            if !skip_or_tramp(t) {
                bail!(format!("link-target {} not-skip", t));
            }
            let cmp_i = match self.match_prev_real(jk) {
                Some(x) if x >= region_start => x,
                _ => bail!("no-prev-cmp"),
            };
            match self.instrs[cmp_i].op {
                Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP => {}
                other => bail!(format!("link-cmp {:?}", other)),
            }
            let link_expr = if acc.is_none() {
                let e = self.sim_value_region_ex(region_start, jk, true);
                let Some(e) = e else { bail!("head-sim") };
                e
            } else {
                let rhs = self.sim_value_region(region_start, cmp_i);
                let Some(rhs) = rhs else { bail!("rhs-sim") };
                let op = if self.instrs[cmp_i].op == Op::COMPARE_OP {
                    cmp_from_index(compare_op_index(
                        self.instrs[cmp_i].arg as u32,
                        self.version,
                    ))
                } else {
                    bail!("non-cmp-link");
                };
                let prev = acc.clone().unwrap();
                let last = match &*prev {
                    Expr::Compare { operands, .. } => operands.last().cloned(),
                    _ => None,
                };
                let Some(last) = last else { bail!("acc-not-compare") };
                let link: ExprRef = Rc::new(Expr::Compare {
                    operands: vec![last, rhs],
                    ops: vec![op],
                });
                let m = merge_chain_compare(&prev, &link);
                let Some(m) = m else { bail!("chain-merge") };
                m
            };
            acc = Some(link_expr);
            region_start = jk + 1;
            k = jk + 1;
        }
        let Some(b_expr) = acc else { bail!("no-links") };
        let Some(tj) = true_jump else {
            bail!("no-true-jump");
        };
        let tj_ins = &self.instrs[tj];
        let Some(g) = tj_ins.target else {
            bail!("true-jump-no-target");
        };
        let Some(gk) = idx_at(g) else {
            bail!("no-idx-body");
        };
        if self.effective_offset(g) == self.effective_offset(skip) {
            bail!("body-is-skip");
        }
        // the guard body [g, skip) must be a break stub: pads then a
        // single jump onto the enclosing loop's exit
        {
            let mut k2 = gk;
            while matches!(
                self.instrs.get(k2).map(|x| x.op),
                Some(Op::NOP)
                    | Some(Op::NOT_TAKEN)
                    | Some(Op::CACHE)
                    | Some(Op::EXTENDED_ARG)
            ) {
                k2 += 1;
            }
            let Some(jb) = self.instrs.get(k2) else {
                bail!("no-body-jump");
            };
            if !matches!(
                jb.op,
                Op::JUMP_ABSOLUTE
                    | Op::JUMP_BACKWARD
                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                    | Op::JUMP_FORWARD
                    | Op::JUMP
            ) {
                bail!(format!("body-op {:?}", jb.op));
            }
            let Some(bt) = jb.target else {
                bail!("body-jump-no-target");
            };
            let is_exit = self.find_loop_exit(bt).is_some();
            if !is_exit {
                bail!("body-not-break");
            }
            // nothing but the jump between g and skip
            let Some(&si) = self.idx_of.get(&skip) else {
                bail!("no-skip-idx");
            };
            if k2 + 1 != si {
                // padding between the break jump and the skip is fine
                let mut k3 = k2 + 1;
                while is_pad(k3) || matches!(self.instrs.get(k3).map(|x| x.op), Some(Op::EXTENDED_ARG))
                {
                    k3 += 1;
                }
                if k3 != si {
                    bail!("body-extra");
                }
            }
        }
        let mut values = Vec::new();
        flatten_boolop(cond.clone(), BoolOpKind::And, &mut values);
        flatten_boolop(b_expr, BoolOpKind::And, &mut values);
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values,
        });
        if dbg {
            eprintln!(
                "ACB[{}] off={}: MERGED body=[{},{})",
                self.code.name, self.cur_offset, g, skip
            );
        }
        Some((merged, g, skip))
    }

    fn try_or_continue_chain(
        &self,
        loop_top: usize,
        first_cond: &ExprRef,
    ) -> Option<(ExprRef, usize, usize)> {

        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
            )
        };
        let jump_true =
            |o: Op| matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE);
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return None;
        };
        // the Or-chain contribution of the FIRST operand follows its own
        // jump polarity: a PJIF-to-top jumps to the continue when the
        // operand is FALSE, so it contributes Not(operand) (configparser
        // 3.12 RawConfigParser.__init__ `if not m or not callable(...)`
        // rendered `if m or ...` — polarity-inverted). The And forms
        // (top_parts) keep the raw operand and normalize separately.
        let first_part: ExprRef = if self.jump_if_true_at_ci(ci) {
            first_cond.clone()
        } else {
            Rc::new(Expr::Unary {
                op: UnaryOp::Not,
                operand: first_cond.clone(),
            })
        };
        let mut parts: Vec<ExprRef> = vec![first_part];
        // operands collected via jumps to the loop top, with their polarity
        let mut top_parts: Vec<ExprRef> = vec![first_cond.clone()];
        let mut top_jumps_true = true;
        let mut top_jumps_false = true;
        let mut k = ci + 1;
        let mut exit: Option<usize> = None;
        let mut body_start = 0usize;
        loop {
            let region_start = k;
            let mut jidx = None;
            while k < self.instrs.len() {
                let ins = &self.instrs[k];
                if is_cond_jump(ins.op) {
                    jidx = Some(k);
                    break;
                }
                if !is_pure_value_op(ins.op) {
                    // not an operand region any more — the body starts here
                    break;
                }
                k += 1;
            }
            let jk = match jidx {
                Some(x) => x,
                None => {
                    // 3.12+ guard chain landing: the region holds only the
                    // NOT_TAKEN pad before the loop's back edge — this is
                    // the continue trampoline of a folded guard chain
                    // (`if g1 and g2: continue`); the real body resumes
                    // after the trampoline
                    if self.version.at_least(3, 12) && body_start == 0 {
                        let mut pad = region_start;
                        while matches!(
                            self.instrs.get(pad).map(|x| x.op),
                            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
                        ) {
                            pad += 1;
                        }
                        if let Some(ins) = self.instrs.get(pad) {
                            if ins.is_backward
                                && ins.target == Some(loop_top)
                                && matches!(
                                    ins.op,
                                    Op::JUMP_BACKWARD
                                        | Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                            {
                                let mut k2 = pad + 1;
                                while matches!(
                                    self.instrs.get(k2).map(|x| x.op),
                                    Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
                                ) {
                                    k2 += 1;
                                }
                                if let Some(bins) = self.instrs.get(k2) {
                                    return Some((
                                        self.merge_guard_values(top_parts),
                                        bins.offset,
                                        ins.offset,
                                    ));
                                }
                            }
                        }
                    }
                    // no further operand jump: the body starts right here
                    // (all operands short-circuit to the loop top and the
                    // body is a bare continue/break jump)
                    let mut m = region_start;
                    let mut body_jump: Option<(usize, usize)> = None;
                    while m < self.instrs.len() {
                        let ins = &self.instrs[m];
                        if ins.op == Op::POP_TOP || ins.op == Op::NOP {
                            m += 1;
                            continue;
                        }
                        if let Some(t) = ins.target {
                            let back = ins.is_backward
                                && t == loop_top
                                && matches!(
                                    ins.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                );
                            // a forward UNCONDITIONAL jump leaving the loop
                            // block is the `break` (it may fly over a
                            // for-else region); a conditional jump here is
                            // the rotated-while's duplicated exit test
                            let fwd_exit = !ins.is_backward
                                && matches!(
                                    ins.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_FORWARD
                                        | Op::JUMP
                                        | Op::JUMP_NO_INTERRUPT
                                )
                                && self
                                    .blocks
                                    .iter()
                                    .rev()
                                    .find(|b| {
                                        matches!(b.kind, BlockType::While | BlockType::For)
                                            && b.start == loop_top
                                    })
                                    .map_or(false, |b| t >= b.end);
                            if back || fwd_exit {
                                body_jump = Some((ins.end(), t));
                                break;
                            }
                        }
                        // mixed/plain continue-guard chain: every operand
                        // jumps to the loop top and a REAL body follows,
                        // ending at the loop's back edge. The body runs
                        // only when no jump fired: And-merge with each
                        // operand normalized by its jump polarity (PJIF
                        // guard = operand, PJIT guard = Not operand).
                        // Uniform-polarity chains keep the historical Or/And
                        // forms (corpus-verified); the And-normalization is
                        // for MIXED chains only, where no historical merge
                        // applied.
                        let first_jt = self.jump_if_true_at_ci(ci);
                        let uniform = (top_jumps_true && first_jt)
                            || (top_jumps_false && !first_jt);
                        if uniform {
                            return None;
                        }
                        let mut m = region_start;
                        let mut back_edge: Option<usize> = None;
                        let mut failed = false;
                        while m < self.instrs.len() {
                            let ins = &self.instrs[m];
                            if ins.is_backward
                                && ins.target == Some(loop_top)
                                && matches!(
                                    ins.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                            {
                                back_edge = Some(ins.offset);
                                break;
                            }
                            if let Some(t) = ins.target {
                                // a break jump out of the loop ends the
                                // body region as well
                                let leaves = self
                                    .blocks
                                    .iter()
                                    .rev()
                                    .find(|b| {
                                        matches!(b.kind, BlockType::While | BlockType::For)
                                            && b.start == loop_top
                                    })
                                    .map_or(false, |b| {
                                        !ins.is_backward
                                            && self
                                                .loop_exit_offset(b)
                                                .map_or(false, |le| {
                                                    self.effective_offset(t)
                                                        == self.effective_offset(le)
                                                })
                                    });
                                if leaves {
                                    back_edge = Some(t);
                                    break;
                                }
                                failed = true;
                                break;
                            }
                            m += 1;
                        }
                        if failed {
                            return None;
                        }
                        let body_end_off = match back_edge {
                            Some(b) => b,
                            None => return None,
                        };
                        if body_end_off <= region_start {
                            return None;
                        }
                        // operand polarities: replay the chain jumps with
                        // their operand regions (a PJIF guard keeps its
                        // operand, a PJIT guard negates it)
                        let mut guard_parts: Vec<ExprRef> = Vec::new();
                        {
                            let mut region = ci + 1;
                            let mut kk = ci + 1;
                            while kk < self.instrs.len() {
                                let ins = &self.instrs[kk];
                                if is_cond_jump(ins.op) {
                                    if ins.target != Some(loop_top) {
                                        break;
                                    }
                                    match self.sim_value_region(region, kk) {
                                        Some(op) => {
                                            guard_parts.push(if jump_true(ins.op) {
                                                Rc::new(Expr::Unary {
                                                    op: UnaryOp::Not,
                                                    operand: op,
                                                })
                                            } else {
                                                op
                                            });
                                        }
                                        None => return None,
                                    }
                                    kk += 1;
                                    region = kk;
                                } else if !is_pure_value_op(ins.op) {
                                    break;
                                } else {
                                    kk += 1;
                                }
                            }
                        }
                        if guard_parts.is_empty() {
                            return None;
                        }
                        let mut values = Vec::new();
                        let first_norm = if self.jump_if_true_at_ci(ci) {
                            Rc::new(Expr::Unary {
                                op: UnaryOp::Not,
                                operand: first_cond.clone(),
                            })
                        } else {
                            first_cond.clone()
                        };
                        flatten_boolop(first_norm, BoolOpKind::And, &mut values);
                        for gp in guard_parts {
                            flatten_boolop(gp, BoolOpKind::And, &mut values);
                        }
                        if values.len() < 2 {
                            return None;
                        }
                        let merged: ExprRef = Rc::new(Expr::BoolOp {
                            op: BoolOpKind::And,
                            values,
                        });
                        let body_off = self.instrs.get(region_start).map(|i| i.offset)?;
                        return Some((merged, body_off, body_end_off));
                    }
                    let (body_end, body_t) = body_jump?;
                    // the historical Or/And merges assume a UNIFORM chain
                    // whose polarity matches the first jump (Or = every
                    // top-jump PJIT like the first; And = every PJIF).
                    // top_jumps_true/false only fold the FOLLOWING links,
                    // so a MIXED chain (PJIF first + PJIT link — `if A and
                    // not B: break`, copyreg._reduce_ex) took the Or branch
                    // and rendered `if A or B: break` — polarity-broken.
                    // Mixed chains belong to the And-normalized guard
                    // branch above (which requires a real body, so it
                    // declined this bare jump body); decline here too and
                    // let the generic per-jump If rendering nest the
                    // conditions correctly.
                    let first_jt = self.jump_if_true_at_ci(ci);
                    let uniform = (top_jumps_true && first_jt)
                        || (top_jumps_false && !first_jt);
                    if !uniform {
                        return None;
                    }
                    let op = if top_jumps_true {
                        BoolOpKind::Or
                    } else {
                        BoolOpKind::And
                    };
                    let vals = if top_jumps_true { parts } else { top_parts };
                    let merged: ExprRef = if vals.len() >= 2 {
                        Rc::new(Expr::BoolOp { op, values: vals })
                    } else if !self.jump_if_true_at_ci(ci)
                        && body_t != loop_top
                        && !matches!(
                            self.instrs.get(ci).map(|i| i.op),
                            Some(Op::POP_JUMP_BACKWARD_IF_TRUE)
                                | Some(Op::POP_JUMP_BACKWARD_IF_FALSE)
                        )
                    {
                        // single operand `if c: break`: the PJIF jumps to
                        // the loop top (continue) and the fall-through body
                        // is the break jump. BACKWARD cond-jump variants are
                        // rotated-while re-entries, never this shape.
                        first_cond.clone()
                    } else {
                        return None;
                    };
                    let body_off = self.instrs.get(region_start).map(|i| i.offset)?;
                    return Some((merged, body_off, body_end));
                }
            };
            let operand = self.sim_value_region(region_start, jk)?;
            let jins = &self.instrs[jk];
            let jt = jump_true(jins.op);
            if jins.target == Some(loop_top) {
                // another operand short-circuiting to the loop top
                if jt {
                    // jumps to top when TRUE: `if a or ...: continue`
                    parts.push(operand.clone());
                }
                // jumps to top when FALSE: the body needs every operand
                // true (`if a and ...: break`) — raw participation
                top_parts.push(operand);
                top_jumps_true = top_jumps_true && jt;
                top_jumps_false = top_jumps_false && !jt;
                k = jk + 1;
                continue;
            }
            if let Some(t) = jins.target {
                if t > self.cur_offset && self.idx_of.contains_key(&t) {
                    parts.push(if jt {
                        Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
                    } else {
                        operand
                    });
                    exit = Some(t);
                    body_start = self.instrs[jk].end();
                    break;
                }
            }
            return None;
        }
        let exit = match exit {
            Some(x) => x,
            None => return None,
        };
        if parts.len() < 2 {
            return None;
        }
        // the body between the chain and the exit must be exactly the
        // continue back edge (plus optional dead padding jumps)
        let Some(&bsi) = self.idx_of.get(&body_start) else {
            return None;
        };
        let Some(&ei) = self.idx_of.get(&exit) else {
            return None;
        };
        if ei <= bsi {
            return None;
        }
        // the body must leave the loop immediately: a back edge to the top
        // (`continue`) or a forward jump to the loop exit (`break`, which
        // 3.8 prefixes with POP_TOP), plus dead padding
        let loop_exit = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For) && b.start == loop_top)
            .and_then(|b| self.loop_exit_offset(b));
        let mut saw_exit_jump = false;
        for m in bsi..ei {
            let ins = &self.instrs[m];
            if let Some(t) = ins.target {
                let back_to_top = ins.is_backward
                    && t == loop_top
                    && matches!(
                        ins.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                    );
                let fwd_to_exit = !ins.is_backward
                    && loop_exit.map_or(false, |le| {
                        self.effective_offset(t) == self.effective_offset(le)
                    });
                if back_to_top || fwd_to_exit {
                    saw_exit_jump = true;
                    continue;
                }
            }
            if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP | Op::NOP | Op::POP_TOP) {
                continue;
            }
            return None;
        }
        if !saw_exit_jump {
            return None;
        }
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values: parts,
        }) as ExprRef;
        Some((merged, body_start, exit))
    }

    /// Evaluate a straight-line value-expression instruction region on a
    /// scratch stack (py2 boolop condition merging). Returns None when any
    /// instruction is not pure value computation.
    fn sim_value_region(&self, from_idx: usize, to_idx: usize) -> Option<ExprRef> {
        self.sim_value_region_ex(from_idx, to_idx, false)
    }

    /// Simulate a pure value region. `allow_chain_residual` tolerates ONE
    /// leftover value under the result — the retained middle operand of a
    /// chained-comparison head (`LOAD d; LOAD a; DUP; ROT_THREE; CMP` leaves
    /// [a, cmp(d==a)]), which the chain-or operand scan needs.
    fn sim_value_region_ex(
        &self,
        from_idx: usize,
        to_idx: usize,
        allow_chain_residual: bool,
    ) -> Option<ExprRef> {
        let mut st: Vec<ExprRef> = Vec::new();
        let pop1 = |st: &mut Vec<ExprRef>| st.pop().unwrap_or_else(|| self.name_expr("???"));
        for k in from_idx..to_idx {
            let ins = &self.instrs[k];
            let arg = ins.arg as usize;
            match ins.op {
                Op::LOAD_FAST | Op::LOAD_FAST_CHECK | Op::LOAD_FAST_BORROW => {
                    st.push(self.name_expr(self.local_name(arg)));
                }
                Op::LOAD_FAST_LOAD_FAST | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => {
                    st.push(self.name_expr(self.local_name(((arg >> 4) & 0xF) as usize)));
                    st.push(self.name_expr(self.local_name((arg & 0xF) as usize)));
                }
                Op::STORE_FAST_LOAD_FAST => {
                    // capture store that re-pushes the loaded name (the
                    // value stored is the region's incoming TOS)
                    pop1(&mut st);
                    st.push(self.name_expr(self.local_name((arg & 0xF) as usize)));
                }
                Op::LOAD_NAME | Op::LOAD_GLOBAL | Op::STORE_FAST => {
                    if ins.op == Op::STORE_FAST {
                        return None;
                    }
                    let n = if ins.op == Op::LOAD_GLOBAL && self.version.at_least(3, 11) {
                        self.const_name(arg >> 1)
                    } else {
                        self.const_name(arg)
                    };
                    st.push(self.name_expr(n));
                }
                Op::LOAD_DEREF => {
                    let n = self
                        .code
                        .deref_name(arg)
                        .unwrap_or("???")
                        .to_string();
                    st.push(self.name_expr(n));
                }
                Op::LOAD_SMALL_INT => {
                    st.push(Rc::new(Expr::Const(Rc::new(PyObject::Int(
                        ins.arg as i32,
                    )))));
                }
                Op::LOAD_CONST => {
                    st.push(Rc::new(Expr::Const(
                        self.code.consts.get(arg).cloned().unwrap_or_else(|| {
                            Rc::new(PyObject::None)
                        }),
                    )));
                }
                Op::LOAD_ATTR | Op::LOAD_METHOD => {
                    let v = pop1(&mut st);
                    let idx = if ins.op == Op::LOAD_ATTR && self.version.at_least(3, 12) {
                        arg >> 1
                    } else {
                        arg
                    };
                    let a = self.const_name(idx);
                    st.push(Rc::new(Expr::Attribute { value: v, attr: a }));
                }
                Op::COMPARE_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = cmp_from_index(compare_op_index(arg as u32, self.version));
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::IS_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = if arg == 1 { CmpOp::IsNot } else { CmpOp::Is };
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::CONTAINS_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = if arg == 1 { CmpOp::NotIn } else { CmpOp::In };
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::UNARY_NOT => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Not, operand: v }));
                }
                Op::UNARY_NEGATIVE => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Neg, operand: v }));
                }
                Op::UNARY_INVERT => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Invert, operand: v }));
                }
                Op::BINARY_SUBSCR => {
                    let i = pop1(&mut st);
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Subscript { value: v, index: i }));
                }
                Op::BINARY_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    match binary_op_name(arg as u32, self.version) {
                        Some(name) => {
                            if name.ends_with('=') {
                                return None;
                            }
                            let op = binop_from_text(name);
                            st.push(Rc::new(Expr::Binary { op, left: l, right: r }));
                        }
                        // 3.14 folded BINARY_SUBSCR into BINARY_OP `[]`,
                        // with constant slices as LOAD_CONST slice(...) —
                        // mirror the main handler's subscript conversion
                        None if self.version.at_least(3, 14) => {
                            let idx = normalize_slice_call(r);
                            st.push(Rc::new(Expr::Subscript {
                                value: l,
                                index: idx,
                            }));
                        }
                        None => return None,
                    }
                }
                Op::BINARY_ADD | Op::BINARY_SUBTRACT | Op::BINARY_MULTIPLY
                | Op::BINARY_DIVIDE | Op::BINARY_TRUE_DIVIDE | Op::BINARY_FLOOR_DIVIDE
                | Op::BINARY_MODULO | Op::BINARY_POWER | Op::BINARY_LSHIFT
                | Op::BINARY_RSHIFT | Op::BINARY_OR | Op::BINARY_XOR | Op::BINARY_AND
                | Op::BINARY_MATRIX_MULTIPLY => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = match ins.op {
                        Op::BINARY_ADD => BinaryOp::Add,
                        Op::BINARY_SUBTRACT => BinaryOp::Sub,
                        Op::BINARY_MULTIPLY => BinaryOp::Mult,
                        Op::BINARY_DIVIDE | Op::BINARY_TRUE_DIVIDE => BinaryOp::Div,
                        Op::BINARY_FLOOR_DIVIDE => BinaryOp::FloorDiv,
                        Op::BINARY_MODULO => BinaryOp::Mod,
                        Op::BINARY_POWER => BinaryOp::Pow,
                        Op::BINARY_LSHIFT => BinaryOp::LShift,
                        Op::BINARY_RSHIFT => BinaryOp::RShift,
                        Op::BINARY_OR => BinaryOp::BitOr,
                        Op::BINARY_XOR => BinaryOp::BitXor,
                        Op::BINARY_AND => BinaryOp::BitAnd,
                        _ => BinaryOp::MatMult,
                    };
                    st.push(Rc::new(Expr::Binary { op, left: l, right: r }));
                }
                Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => {
                    let n = arg.min(st.len());
                    let items: Vec<ExprRef> = st.split_off(st.len() - n);
                    let e = match ins.op {
                        Op::BUILD_TUPLE => Expr::Tuple(items),
                        Op::BUILD_LIST => Expr::List(items),
                        _ => Expr::Set(items),
                    };
                    st.push(Rc::new(e));
                }
                Op::CALL_FUNCTION | Op::CALL | Op::CALL_METHOD => {
                    let n = if ins.op == Op::CALL_FUNCTION && !self.version.at_least(3, 6) {
                        arg & 0xFF
                    } else {
                        arg
                    };
                    let n = n.min(st.len());
                    let args: Vec<ExprRef> = st.split_off(st.len() - n);
                    let func = pop1(&mut st);
                    st.push(Rc::new(Expr::Call {
                        func,
                        args,
                        keywords: Vec::new(),
                        star_args: None,
                        star_kwargs: None,
                    }));
                }
                // 3.13+/3.14 keyword call: [callable, args..., kwnames]
                // with oparg = positional + keyword count
                Op::CALL_KW => {
                    let kw_names_e = pop1(&mut st);
                    let names: Vec<String> = match &*kw_names_e {
                        Expr::Const(o) => match &**o {
                            PyObject::Tuple(items) => items
                                .iter()
                                .filter_map(|it| match &**it {
                                    PyObject::Str(t) => Some(t.clone()),
                                    _ => None,
                                })
                                .collect(),
                            _ => Vec::new(),
                        },
                        _ => Vec::new(),
                    };
                    let n = arg.min(st.len());
                    let all: Vec<ExprRef> = st.split_off(st.len() - n);
                    let npos = n.saturating_sub(names.len());
                    let args = all[..npos.min(all.len())].to_vec();
                    let mut keywords = Vec::new();
                    for (ki, nm) in names.iter().enumerate() {
                        if let Some(v) = all.get(npos + ki) {
                            keywords.push((Some(nm.clone()), v.clone()));
                        }
                    }
                    let func = pop1(&mut st);
                    st.push(Rc::new(Expr::Call {
                        func,
                        args,
                        keywords,
                        star_args: None,
                        star_kwargs: None,
                    }));
                }
                // stack shuffles: chain heads (DUP_TOP+ROT_THREE <=3.11,
                // SWAP+COPY 3.12+) and or-arm setups move values without
                // consuming them
                Op::DUP_TOP => {
                    let t = pop1(&mut st);
                    st.push(t.clone());
                    st.push(t);
                }
                Op::ROT_TWO | Op::SWAP if arg == 2 || ins.op == Op::ROT_TWO => {
                    let n = st.len();
                    if n >= 2 {
                        st.swap(n - 1, n - 2);
                    }
                }
                Op::ROT_THREE => {
                    // (x, y, z=TOS) -> (z, x, y): TOS lands at the bottom
                    // of the top three
                    let n = st.len();
                    if n >= 3 {
                        let t = st.pop().unwrap();
                        st.insert(n - 3, t);
                    }
                }
                Op::BUILD_SLICE => {
                    let none_if = |e: ExprRef| -> Option<ExprRef> {
                        match &*e {
                            Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                            _ => Some(e),
                        }
                    };
                    let (start, stop, step) = if arg == 3 {
                        let step = none_if(pop1(&mut st));
                        let stop = none_if(pop1(&mut st));
                        let start = none_if(pop1(&mut st));
                        (start, stop, step)
                    } else {
                        let stop = none_if(pop1(&mut st));
                        let start = none_if(pop1(&mut st));
                        (start, stop, None)
                    };
                    st.push(Rc::new(Expr::Slice(Box::new(SliceExpr {
                        start,
                        stop,
                        step,
                    }))));
                }
                // 3.12+ fused slice-subscript: TOS2[TOS1:TOS]
                Op::BINARY_SLICE => {
                    let none_if = |e: ExprRef| -> Option<ExprRef> {
                        match &*e {
                            Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                            _ => Some(e),
                        }
                    };
                    let stop = none_if(pop1(&mut st));
                    let start = none_if(pop1(&mut st));
                    let val = pop1(&mut st);
                    st.push(Rc::new(Expr::Subscript {
                        value: val,
                        index: Rc::new(Expr::Slice(Box::new(SliceExpr {
                            start,
                            stop,
                            step: None,
                        }))),
                    }));
                }
                // py2 slice ops: SLICE_0 TOS[:], SLICE_1 TOS1[TOS:],
                // SLICE_2 TOS1[:TOS], SLICE_3 TOS2[TOS1:TOS]
                Op::SLICE_0 | Op::SLICE_1 | Op::SLICE_2 | Op::SLICE_3 => {
                    let slice = |start: Option<ExprRef>,
                                 stop: Option<ExprRef>| {
                        Rc::new(Expr::Slice(Box::new(SliceExpr {
                            start,
                            stop,
                            step: None,
                        })))
                    };
                    let sub = match ins.op {
                        Op::SLICE_0 => {
                            let seq = pop1(&mut st);
                            Expr::Subscript { value: seq, index: slice(None, None) }
                        }
                        Op::SLICE_1 => {
                            let start = pop1(&mut st);
                            let seq = pop1(&mut st);
                            Expr::Subscript {
                                value: seq,
                                index: slice(Some(start), None),
                            }
                        }
                        Op::SLICE_2 => {
                            let stop = pop1(&mut st);
                            let seq = pop1(&mut st);
                            Expr::Subscript {
                                value: seq,
                                index: slice(None, Some(stop)),
                            }
                        }
                        _ => {
                            let stop = pop1(&mut st);
                            let start = pop1(&mut st);
                            let seq = pop1(&mut st);
                            Expr::Subscript {
                                value: seq,
                                index: slice(Some(start), Some(stop)),
                            }
                        }
                    };
                    st.push(Rc::new(sub));
                }
                Op::SWAP => {
                    let n = st.len();
                    if arg >= 2 && n >= arg {
                        st.swap(n - 1, n - arg);
                    }
                }
                Op::COPY => {
                    let n = st.len();
                    if arg >= 1 && n >= arg {
                        let v = st[n - arg].clone();
                        st.push(v);
                    }
                }
                Op::TO_BOOL
                | Op::NOP
                | Op::NOT_TAKEN
                | Op::CACHE
                | Op::EXTENDED_ARG
                | Op::PUSH_NULL
                | Op::PRECALL
                | Op::RESUME => {}
                _ => return None,
            }
        }
        if st.len() == 1 || (allow_chain_residual && st.len() == 2) {
            st.pop()
        } else {
            None
        }
    }

    /// 3.14+ continue-guard chain inside a loop: each test jumps FORWARD
    /// to the next test (or the body) when it passes, and falls through
    /// to `NOT_TAKEN; JUMP_BACKWARD loop_top` (an inline continue) when
    /// it fails. Merge the guards into one And condition over the body.
    /// All instructions between the current cond jump and the exit are
    /// pure value ops or forward cond jumps (a multi-jump `and` condition),
    /// followed by the loop body and the duplicated rotated condition.
    fn is_rotated_multijump_while(&self, ci: usize, ti: usize, body_top: usize) -> bool {
        let mut k = ci + 1;
        // remaining initial condition tests
        loop {
            let Some(ins) = self.instrs.get(k) else {
                return false;
            };
            if ins.offset >= body_top {
                break;
            }
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                // every remaining initial test must exit the loop: either
                // to the same label, or (module-level 3.10 duplicates the
                // epilogue per exit) to its own `LOAD None; RETURN` stub
                let ok = match ins.target {
                    Some(t2) if t2 == self.instrs[ti].offset => true,
                    Some(t2) => self
                        .idx_of
                        .get(&t2)
                        .map_or(false, |&xi| {
                            matches!(
                                self.instrs[xi].op,
                                Op::LOAD_CONST | Op::RETURN_CONST
                            ) && (matches!(
                                self.instrs.get(xi + 1).map(|x| x.op),
                                Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
                            ) || matches!(self.instrs[xi].op, Op::RETURN_CONST))
                        }),
                    None => false,
                };
                if !ok {
                    return false;
                }
            } else if !is_pure_value_op(ins.op) {
                return false;
            }
            k += 1;
        }
        // body: no backward jumps other than the rotated back edge itself;
        // stop AT the back edge (the fall-through past it is the loop
        // exit epilogue, which may legitimately hold a RETURN).
        // A genuine MULTI-jump condition re-evaluates every operand at
        // the loop top, so the re-eval span holds at least one forward
        // exit jump before the backward one. Zero forward jumps means a
        // single-condition rotated while — and this cond jump is a GUARD
        // statement preceding it (`if size<0: while read(): pass` must
        // not merge into `while size<0 and read():`, which re-tests the
        // guard every iteration and calls read() when it is false —
        // 3.11 _compression.seek).
        let mut fwd_jumps_in_body = 0;
        while k < ti {
            let Some(ins) = self.instrs.get(k) else {
                return false;
            };
            if ins.is_backward {
                if ins.target == Some(body_top)
                    && matches!(
                        ins.op,
                        Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_BACKWARD_IF_TRUE
                    )
                {
                    return fwd_jumps_in_body >= 1;
                }
                // a nested loop's own back edge / an in-body `continue`
                // lands INSIDE the body — keep scanning toward the
                // rotated re-entry (csv 3.11 _guess_delimiter
                // `while len(delims)==0 and consistency>=threshold:`
                // holds an inner `for k, v in modeList:` whose back
                // edge aborted the scan, and the while rendered as an
                // if + tail guards)
                if ins
                    .target
                    .map_or(false, |t| t >= body_top && t < ins.offset)
                {
                    k += 1;
                    continue;
                }
                return false;
            }
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
            ) {
                fwd_jumps_in_body += 1;
            }
            k += 1;
        }
        false
    }

    /// Merge the remaining forward cond-jump tests between `ci` and the
    /// body top into one And condition (all operands evaluated left to
    /// right, each false-exiting to the same label).
    fn merge_forward_cond_chain(&self, ci: usize, target: usize) -> Option<ExprRef> {
        self.merge_forward_cond_chain_bt(ci, target).map(|(c, _)| c)
    }

    /// Like merge_forward_cond_chain, also returning the offset just past
    /// the chain's last collected cond jump (the loop body top).
    fn merge_forward_cond_chain_bt(
        &self,
        ci: usize,
        target: usize,
    ) -> Option<(ExprRef, usize)> {
        let &xi0 = self.idx_of.get(&target)?;
        let exit_off = self.instrs[xi0].offset;
        let mut values: Vec<ExprRef> = Vec::new();
        let mut k = ci + 1;
        let mut region_start = k;
        let mut body_top = self.instrs.get(ci + 1).map(|x| x.offset)?;
        while let Some(ins) = self.instrs.get(k) {
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                // the test must exit the loop (shared label or its own
                // `LOAD None; RETURN` epilogue stub)
                let ok = match ins.target {
                    Some(t2) if t2 == exit_off => true,
                    Some(t2) => self
                        .idx_of
                        .get(&t2)
                        .map_or(false, |&xi| {
                            matches!(
                                self.instrs[xi].op,
                                Op::LOAD_CONST | Op::RETURN_CONST
                            ) && (matches!(
                                self.instrs.get(xi + 1).map(|x| x.op),
                                Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
                            ) || matches!(self.instrs[xi].op, Op::RETURN_CONST))
                        }),
                    None => false,
                };
                if !ok {
                    return None;
                }
                let operand = match self.sim_value_region(region_start, k) {
                    Some(o) => o,
                    None => {
                        return None;
                    }
                };
                values.push(operand);
                k += 1;
                // skip NOT_TAKEN padding
                while matches!(
                    self.instrs.get(k).map(|x| x.op),
                    Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
                ) {
                    k += 1;
                }
                body_top = self.instrs.get(k).map(|x| x.offset).unwrap_or(body_top);
                region_start = k;
                continue;
            }
            if !is_pure_value_op(ins.op) {
                break;
            }
            k += 1;
        }
        if values.is_empty() {
            return None;
        }
        let mut flat = Vec::new();
        for v in values {
            flatten_boolop(v, BoolOpKind::And, &mut flat);
        }
        Some((
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::And,
                values: flat,
            }),
            body_top,
        ))
    }

    /// Shape-B admission: the fall-through of `ci` must reach another
    /// cond jump through pure value ops (a second chain link), and that
    /// link must terminate the chain (pass-exit hop over a back
    /// trampoline, jump onto the trampoline, or another advance link).
    fn shape_b_admit(&self, ci: usize, target: usize) -> bool {
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
            )
        };
        let is_back_tramp = |ins: &Instruction| {
            ins.is_backward
                && matches!(
                    ins.op,
                    Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
        };
        // fail trampoline at target?
        let mut fi = match self.idx_of.get(&target) {
            Some(&x) => x,
            None => return false,
        };
        while matches!(
            self.instrs.get(fi).map(|x| x.op),
            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
        ) {
            fi += 1;
        }
        let Some(ftramp) = self.instrs.get(fi) else {
            return false;
        };
        if !is_back_tramp(ftramp) {
            return false;
        }
        let loop_top = match ftramp.target {
            Some(t) => t,
            None => return false,
        };
        // fall-through: second link region
        let mut k = ci + 1;
        while matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
        ) {
            k += 1;
        }
        let mut steps = 0;
        loop {
            let Some(ins) = self.instrs.get(k) else {
                return false;
            };
            if is_cond_jump(ins.op) {
                break;
            }
            if !is_pure_value_op(ins.op) || steps > 40 {
                return false;
            }
            k += 1;
            steps += 1;
        }
        // the second link must terminate the chain
        let j2 = &self.instrs[k];
        let t2 = match j2.target {
            Some(t) => t,
            None => return false,
        };
        let mut ti = match self.idx_of.get(&t2) {
            Some(&x) => x,
            None => return false,
        };
        while matches!(
            self.instrs.get(ti).map(|x| x.op),
            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
        ) {
            ti += 1;
        }
        let Some(tins) = self.instrs.get(ti) else {
            return false;
        };
        // (a) jump lands on the trampoline (A and B: continue) — the
        // second link's fall-through must ALSO be the trampoline, i.e.
        // the chain truly terminates here; a guarded body on the
        // fall-through (b10-style `if A or B: skip`) is not shape B
        if is_back_tramp(tins) && tins.target == Some(loop_top) {
            let mut ft2 = k + 1;
            while matches!(
                self.instrs.get(ft2).map(|x| x.op),
                Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
            ) {
                ft2 += 1;
            }
            return self.instrs.get(ft2).map_or(false, |x| {
                (is_back_tramp(x) && x.target == Some(loop_top))
                    || (matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                        && !x.is_backward
                        && x.target.map_or(false, |t| t > x.offset))
            });
        }
        // (b) jump lands on a pass-exit hop into the body
        if matches!(tins.op, Op::JUMP_FORWARD | Op::JUMP)
            && !tins.is_backward
            && tins.target.map_or(false, |t| t > tins.offset)
        {
            return true;
        }
        // (c) jump lands on a further advance link (pure region + cond
        //     jump), with THIS link's fall-through being the trampoline
        let mut ft = k + 1;
        while matches!(
            self.instrs.get(ft).map(|x| x.op),
            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
        ) {
            ft += 1;
        }
        if !self
            .instrs
            .get(ft)
            .map_or(false, |x| is_back_tramp(x) && x.target == Some(loop_top))
        {
            return false;
        }
        let mut s = ti;
        let mut st = 0;
        loop {
            let Some(ins) = self.instrs.get(s) else {
                return false;
            };
            if is_cond_jump(ins.op) {
                return ins.target.map_or(false, |t| {
                    self.idx_of.get(&t).map_or(false, |&nx| {
                        let mut m = nx;
                        while matches!(
                            self.instrs.get(m).map(|x| x.op),
                            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
                        ) {
                            m += 1;
                        }
                        self.instrs.get(m).map_or(false, |y| {
                            (is_back_tramp(y) && y.target == Some(loop_top))
                                || (matches!(y.op, Op::JUMP_FORWARD | Op::JUMP)
                                    && !y.is_backward)
                        })
                    })
                });
            }
            if !is_pure_value_op(ins.op) || st > 40 {
                return false;
            }
            s += 1;
            st += 1;
        }
    }

    /// Shape-B guard chain (3.14 statement chain-compare ifs and mixed
    /// guard chains): the fail trampoline ([POP_TOP;] JUMP_BACKWARD
    /// loop_top) sits at the guard jumps' TARGET and the chain advances on
    /// fall-through; the final guard's pass-jump exits (optionally via a
    /// JUMP_FORWARD hop) into the body. Each link contributes its operand
    /// positively when the chain advances on TRUE, negated otherwise.
    /// Fold collected guard-chain operands into one And condition,
    /// flattening nested BoolOps of the same kind.
    fn merge_guard_values(&self, parts: Vec<ExprRef>) -> ExprRef {
        let mut flat = Vec::new();
        for v in parts {
            flatten_boolop(v, BoolOpKind::And, &mut flat);
        }
        if flat.len() == 1 {
            flat.pop().unwrap()
        } else {
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::And,
                values: flat,
            })
        }
    }

    fn try_guard_chain_fallthrough(
        &self,
        cond: &ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
            )
        };
        let jump_true =
            |o: Op| matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE);
        let is_back_tramp = |ins: &Instruction| {
            ins.is_backward
                && matches!(
                    ins.op,
                    Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
        };
        let ci = *self.idx_of.get(&self.cur_offset)?;
        // the jump target must hold the fail trampoline:
        // [POP_TOP...] [pad] JUMP_BACKWARD loop_top
        let mut fi = self.idx_of.get(&target).copied()?;
        while matches!(
            self.instrs.get(fi).map(|x| x.op),
            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
        ) {
            fi += 1;
        }
        let ftramp = self.instrs.get(fi)?;
        if !is_back_tramp(ftramp) {
            return None;
        }
        let loop_top = ftramp.target?;
        if !self.blocks.iter().any(|b| {
            matches!(b.kind, BlockType::While | BlockType::For)
                && (b.start == loop_top
                    || (b.cond_end != usize::MAX && b.cond_end == loop_top))
        }) {
            return None;
        }
        // walk the links on the fall-through side
        let mut values: Vec<ExprRef> = Vec::new();
        // first link: the operand was already evaluated (cond); its jump
        // goes to the fail trampoline, so the chain advances on
        // fall-through: PJIF advances on TRUE (positive), PJIT on FALSE.
        // A SINGLE-guard chain (`if c: continue`) instead tests the
        // condition as-is regardless of jump polarity.
        let mut q = ci + 1;
        while matches!(
            self.instrs.get(q).map(|x| x.op),
            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
        ) {
            q += 1;
        }
        let another_link = matches!(
            self.instrs.get(q).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE)
                | Some(Op::POP_JUMP_IF_TRUE)
                | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
                | Some(Op::POP_JUMP_FORWARD_IF_TRUE)
        );
        values.push(if !another_link {
            cond.clone()
        } else if jump_if_true {
            Rc::new(Expr::Unary { op: UnaryOp::Not, operand: cond.clone() })
        } else {
            cond.clone()
        });
        let mut next = ci + 1;
        let mut body_start = None;
        loop {
            while matches!(
                self.instrs.get(next).map(|x| x.op),
                Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
            ) {
                next += 1;
            }
            // this link's JUMP may lead straight to the trampoline
            // (`A and B: continue` — both guards pass-jump into the same
            // continue): the chain is complete, its body IS the continue
            if let Some(ins) = self.instrs.get(next) {
                if is_back_tramp(ins) && ins.target == Some(loop_top) {
                    if !values.is_empty() {
                        let mut k = next + 1;
                        while matches!(
                            self.instrs.get(k).map(|x| x.op),
                            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
                        ) {
                            k += 1;
                        }
                        let bstart = self.instrs.get(k).map(|x| x.offset)?;
                        let mut merged_values = Vec::new();
                        for v in values.drain(..) {
                            flatten_boolop(v, BoolOpKind::And, &mut merged_values);
                        }
                        let merged = Rc::new(Expr::BoolOp {
                            op: BoolOpKind::And,
                            values: merged_values,
                        });
                        return Some((
                            merged as ExprRef,
                            bstart,
                            ins.offset,
                        ));
                    }
                    break;
                }
                // pass-exit hop: a forward jump into the body (3.11 final
                // link advances on fall-through straight into this hop)
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                    && !ins.is_backward
                    && ins.target.map_or(false, |t| t > ins.offset)
                {
                    body_start = Some(ins.target.unwrap());
                    break;
                }
            }
            // scan the operand region up to its cond jump
            let region_start = next;
            let mut jk = next;
            while jk < self.instrs.len() {
                let ins = &self.instrs[jk];
                if is_cond_jump(ins.op) {
                    break;
                }
                if !is_pure_value_op(ins.op) {
                    return None;
                }
                jk += 1;
            }
            if jk >= self.instrs.len() || !is_cond_jump(self.instrs[jk].op) {
                return None;
            }
            let mut jt = jk + 1;
            while matches!(
                self.instrs.get(jt).map(|x| x.op),
                Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
            ) {
                jt += 1;
            }
            let jins = &self.instrs[jk];
            let jt_target = jins.target?;
            let jtrue = jump_true(jins.op);
            // simulate this link's operand region; a chained comparison
            // reuses the shared middle operand left on the LIVE stack by
            // the SWAP/COPY setup — the scratch sim underruns to `???`,
            // repair it from the previous link's last operand
            let sim_region = |slf: &Self, a: usize, b: usize| slf.sim_value_region(a, b);
            let mut operand = sim_region(self, region_start, jk)?;
            if let Some(prev) = values.last() {
                operand = repair_chain_operand(prev, operand);
            }
            // classify the jump target: fail trampoline, pass exit, or
            // another test region
            let mut ti = self.idx_of.get(&jt_target).copied()?;
            let mut pops = 0;
            while matches!(
                self.instrs.get(ti).map(|x| x.op),
                Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
            ) {
                ti += 1;
                pops += 1;
            }
            let tins = self.instrs.get(ti)?;
            if is_back_tramp(tins) && tins.target == Some(loop_top) {
                // jump -> fail: chain advances on fall-through
                values.push(if jtrue {
                    Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
                } else {
                    operand
                });
                next = jt;
                continue;
            }
            if matches!(tins.op, Op::JUMP_FORWARD | Op::JUMP) && !tins.is_backward {
                // jump -> pass exit (trampoline hop into the body)
                values.push(if jtrue {
                    operand
                } else {
                    Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
                });
                let _ = pops;
                body_start = Some(tins.target?);
                break;
            }
            // jump -> next test region: advance through the jump; the
            // fall-through of THIS link must then be the fail trampoline
            let mut ft = jt;
            while matches!(
                self.instrs.get(ft).map(|x| x.op),
                Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
            ) {
                ft += 1;
            }
            let fins = self.instrs.get(ft)?;
            if !(is_back_tramp(fins) && fins.target == Some(loop_top)) {
                return None;
            }
            values.push(if jtrue {
                operand
            } else {
                Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
            });
            next = ti;
        }
        let bs = match body_start {
            Some(x) => x,
            None => return None,
        };
        // the fall-through after the LAST test is the continue trampoline;
        // when the loop ends the walk the body may also be entered by
        // fall-through — verify a back edge bounds the body
        let Some(&bi) = self.idx_of.get(&bs) else {
            return None;
        };
        let mut body_end = None;
        for ins in self.instrs[bi..].iter() {
            if ins.offset < bs {
                continue;
            }
            if let Some(t) = ins.target {
                if ins.is_backward && t == loop_top && is_back_tramp(ins) {
                    body_end = Some(ins.offset);
                    break;
                }
                if !ins.is_backward && self.find_loop_exit(t).is_some() {
                    continue;
                }
                if !ins.is_backward {
                    let inside = self
                        .blocks
                        .iter()
                        .rev()
                        .find(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && (b.start == loop_top
                                    || (b.cond_end != usize::MAX && b.cond_end == loop_top))
                        })
                        .map_or(false, |b| t < b.end);
                    if !inside {
                        return None;
                    }
                }
            }
            if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                body_end = Some(ins.end());
                break;
            }
        }
        let body_end = body_end?;
        if body_end <= bs {
            return None;
        }
        if values.is_empty() {
            return None;
        }
        // fold adjacent Compare links sharing an operand into a single
        // chained comparison (`i == j` + `j == 1` -> `i == j == 1`) so
        // side-effecting middle operands are not re-evaluated
        let mut folded: Vec<ExprRef> = Vec::new();
        for v in values {
            let mut done = false;
            if let Some(last) = folded.last() {
                if !matches!(&**last, Expr::Unary { .. })
                    && !matches!(&*v, Expr::Unary { .. })
                {
                    if let Some(m) = merge_chain_compare(last, &v) {
                        let n = folded.len();
                        folded[n - 1] = m;
                        done = true;
                    }
                }
            }
            if !done {
                folded.push(v);
            }
        }
        let merged: ExprRef = if folded.len() == 1 {
            folded.pop().unwrap()
        } else {
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::And,
                values: folded,
            })
        };
        Some((merged, bs, body_end))
    }

    /// 3.8-3.11 statement-level chained comparison as an if condition:
    /// `<l>; <m>; DUP; ROT_THREE; CMP; PJIF Lelse; <r>; CMP; PJIF Lelse;
    /// JF Lbody; Lelse: POP_TOP; ...` — every link exits to the same else
    /// label; success hops into the body. Returns (merged Compare,
    /// body_start).
    fn try_stmt_chain_compare(
        &self,
        cond: &ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        let scc_dbg = std::env::var("PYCDC_SCC_DBG").is_ok();
        let Expr::Compare { operands, ops } = &**cond else {
            if scc_dbg { eprintln!("SCC: bail not-compare"); }
            return None;
        };
        if operands.len() != 2 || ops.len() != 1 {
            if scc_dbg { eprintln!("SCC: bail operands {}", operands.len()); }
            return None;
        }
        let is_link_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            )
        };
        let ci = *self.idx_of.get(&self.cur_offset)?;
        // negated chain over a tail-duplicated terminating body (3.8+):
        // `if not (a<b<=c): BODY` — every link PJIF escapes into a
        // verbatim copy of BODY (prescan redirected `target` to the
        // shared body start) and the FINAL link is a PJIT hopping over
        // it. Merge the links and emit the negated chain directly.
        if let Some(orig_t) = self
            .dup_copy_redirect
            .iter()
            .find(|(_, &b)| b == target)
            .map(|(&t, _)| t)
        {
            let Some(&bi) = self.idx_of.get(&target) else {
                return None;
            };
            // shared body end: first terminator (RETURN/RAISE outright,
            // forward JF without internal target); a cond jump inside
            // the body means this is not a plain terminator block
            let mut body_end = None;
            let mut k2 = bi;
            while let Some(ins) = self.instrs.get(k2) {
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_TRUE
                        | Op::POP_JUMP_BACKWARD_IF_FALSE
                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                        | Op::JUMP_IF_FALSE_OR_POP
                        | Op::JUMP_IF_TRUE_OR_POP
                        | Op::JUMP_IF_FALSE
                        | Op::JUMP_IF_TRUE
                ) {
                    break;
                }
                if matches!(
                    ins.op,
                    Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS
                ) {
                    body_end = Some(ins.end());
                    break;
                }
                if let Some(t) = ins.target {
                    if !ins.is_backward
                        && t > ins.offset
                        && matches!(
                            ins.op,
                            Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                        )
                    {
                        let internal = self.instrs[bi..k2]
                            .iter()
                            .any(|x| x.target == Some(t));
                        if !internal {
                            body_end = Some(ins.end());
                            break;
                        }
                    }
                }
                k2 += 1;
                if k2 - bi > 400 {
                    break;
                }
            }
            let Some(be) = body_end else {
                if scc_dbg { eprintln!("SCC-neg: bail body_end"); }
                return None;
            };
            // walk the links in [ci+1, bi): pure-value regions ending in
            // COMPARE + cond jump (PJIF -> the copy, final PJIT -> merge)
            let mut acc_ops2 = ops.clone();
            let mut acc_operands2 = operands.clone();
            let mut k = ci + 1;
            let mut prev_link_end = ci + 1;
            let mut final_ok = false;
            let mut m_off1 = None;
            while k < bi {
                let ins = self.instrs[k];
                let is_link = matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_TRUE
                );
                if !is_link {
                    if !is_pure_value_op(ins.op)
                        && !matches!(
                            ins.op,
                            Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL
                        )
                    {
                        if scc_dbg {
                            eprintln!("SCC-neg: bail impure {:?} off={}", ins.op, ins.offset);
                        }
                        return None;
                    }
                    k += 1;
                    continue;
                }
                // link jump: its lhs operand region must end at a COMPARE
                let cmp_idx = match self.match_prev_real(k) {
                    Some(x) if x > ci => x,
                    _ => {
                        if scc_dbg { eprintln!("SCC-neg: bail prev_real"); }
                        return None;
                    }
                };
                if self.instrs[cmp_idx].op != Op::COMPARE_OP {
                    if scc_dbg { eprintln!("SCC-neg: bail not-cmp"); }
                    return None;
                }
                // region between the previous link and this COMPARE
                let region_start = if acc_ops2.len() == ops.len() {
                    ci + 1
                } else {
                    prev_link_end
                };
                let rhs = self.sim_value_region(region_start, cmp_idx)?;
                acc_ops2.push(cmp_from_index(compare_op_index(
                    self.instrs[cmp_idx].arg as u32,
                    self.version,
                )));
                acc_operands2.push(rhs);
                let jt = ins.target?;
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                ) {
                    if jt != orig_t {
                        if scc_dbg { eprintln!("SCC-neg: bail link target {} != {}", jt, orig_t); }
                        return None;
                    }
                    prev_link_end = k + 1;
                    k += 1;
                    continue;
                }
                // final PJIT: fall-through must be the shared body and
                // the hop must clear the duplicated copy
                let mut nx = k + 1;
                while matches!(
                    self.instrs.get(nx).map(|x| x.op),
                    Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
                ) {
                    nx += 1;
                }
                if self.instrs.get(nx).map(|x| x.offset) != Some(target) {
                    if scc_dbg { eprintln!("SCC-neg: bail final fallthrough"); }
                    return None;
                }
                if jt < orig_t {
                    if scc_dbg { eprintln!("SCC-neg: bail final hop into copy"); }
                    return None;
                }
                m_off1 = Some(jt);
                final_ok = true;
                break;
            }
            if !final_ok || acc_ops2.len() < 2 {
                if scc_dbg { eprintln!("SCC-neg: bail final_ok={} ops={}", final_ok, acc_ops2.len()); }
                return None;
            }
            let merged: ExprRef = Rc::new(Expr::Compare {
                operands: acc_operands2,
                ops: acc_ops2,
            });
            // the shared body may flow into the merge instead of
            // terminating: clamp its end at M
            let be = match m_off1 {
                Some(mo) if mo > target => be.min(mo),
                _ => be,
            };
            return Some((negate_cond(merged), target, be));
        }
        // negated chain over a shared body reached through a cleanup
        // trampoline (3.8/3.9/3.11/3.13/3.14): link PJIFs escape to
        // `POP_TOP; BODY`, the final PJIT hops to the merge past BODY,
        // and a JUMP_FORWARD skips the cleanup into BODY:
        //   <link1 CMP> PJIF P; <linkN CMP> PJIT M; JF B; P: POP_TOP;
        //   B: BODY(terminating); M:
        // yields `if not (chain): BODY`.
        {
            let is_pjif = |o: Op| {
                matches!(
                    o,
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                )
            };
            let is_pjit = |o: Op| {
                matches!(
                    o,
                    Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                )
            };
            let is_jf = |o: Op| matches!(o, Op::JUMP_FORWARD | Op::JUMP);
            if let Some(&pi) = self.idx_of.get(&target) {
                if self.instrs.get(pi).map(|x| x.op) == Some(Op::POP_TOP) {
                    // B: first non-padding after the cleanup POP
                    let mut bx = pi + 1;
                    while matches!(
                        self.instrs.get(bx).map(|x| x.op),
                        Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
                    ) {
                        bx += 1;
                    }
                    if let Some(bin) = self.instrs.get(bx) {
                        let b_off = bin.offset;
                        // walk the link span (ci+1 .. pi): pure values,
                        // COMPAREs, PJIFs to `target`, exactly one final
                        // PJIT (merge M) and one JF hopping to B
                        let mut acc_ops_t = ops.clone();
                        let mut acc_operands_t = operands.clone();
                        let mut k = ci + 1;
                        let mut prev_link_end = ci + 1;
                        let mut pjit_seen = false;
                        let mut jf_seen = false;
                        let mut m_off = None;
                        let mut ok = true;
                        while k < pi {
                            let ins = self.instrs[k];
                            if matches!(
                                ins.op,
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL
                            ) || is_pure_value_op(ins.op)
                            {
                                k += 1;
                                continue;
                            }
                            if matches!(
                                ins.op,
                                Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP
                            ) {
                                k += 1;
                                continue;
                            }
                            if is_pjif(ins.op) {
                                // intermediate link: must escape to the
                                // trampoline POP
                                if ins.target != Some(target) {
                                    ok = false;
                                    break;
                                }
                                let cmp_idx = match self.match_prev_real(k) {
                                    Some(x) if x > ci => x,
                                    _ => {
                                        ok = false;
                                        break;
                                    }
                                };
                                if self.instrs[cmp_idx].op != Op::COMPARE_OP {
                                    ok = false;
                                    break;
                                }
                                let rhs =
                                    match self.sim_value_region(prev_link_end, cmp_idx) {
                                        Some(r) => r,
                                        None => {
                                            ok = false;
                                            break;
                                        }
                                    };
                                acc_ops_t.push(cmp_from_index(compare_op_index(
                                    self.instrs[cmp_idx].arg as u32,
                                    self.version,
                                )));
                                acc_operands_t.push(rhs);
                                prev_link_end = k + 1;
                                k += 1;
                                continue;
                            }
                            if is_pjit(ins.op) && !pjit_seen {
                                // final link: its COMPARE feeds the merge
                                let cmp_idx = match self.match_prev_real(k) {
                                    Some(x) if x > ci => x,
                                    _ => {
                                        ok = false;
                                        break;
                                    }
                                };
                                if self.instrs[cmp_idx].op != Op::COMPARE_OP {
                                    ok = false;
                                    break;
                                }
                                let rhs =
                                    match self.sim_value_region(prev_link_end, cmp_idx) {
                                        Some(r) => r,
                                        None => {
                                            ok = false;
                                            break;
                                        }
                                    };
                                acc_ops_t.push(cmp_from_index(compare_op_index(
                                    self.instrs[cmp_idx].arg as u32,
                                    self.version,
                                )));
                                acc_operands_t.push(rhs);
                                // merge M must sit at/after the body end
                                if ins.target.map_or(true, |m| m <= target) {
                                    ok = false;
                                    break;
                                }
                                m_off = ins.target;
                                pjit_seen = true;
                                prev_link_end = k + 1;
                                k += 1;
                                continue;
                            }
                            if is_jf(ins.op) && !jf_seen {
                                // success hop over the cleanup into B
                                if ins.target != Some(b_off) {
                                    ok = false;
                                    break;
                                }
                                jf_seen = true;
                                k += 1;
                                continue;
                            }
                            ok = false;
                            break;
                        }
                        if ok && pjit_seen && acc_ops_t.len() >= 2 {
                            // body end: first terminator from B, OR the
                            // merge M when the body flows into it (the
                            // success path resumes at M — a non-
                            // terminating body ends there, not at the
                            // function's own tail return; calendar 3.13
                            // weekday swallowed `return Day(...)`); a
                            // cond jump inside means this is an
                            // or-operand region, not a terminator body
                            let mut body_end = None;
                            let mut k2 = bx;
                            while let Some(ins) = self.instrs.get(k2) {
                                if let Some(mo) = m_off {
                                    if mo > b_off && ins.offset >= mo {
                                        body_end = Some(mo);
                                        break;
                                    }
                                }
                                if matches!(
                                    ins.op,
                                    Op::POP_JUMP_IF_FALSE
                                        | Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                        | Op::POP_JUMP_BACKWARD_IF_FALSE
                                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                                        | Op::JUMP_IF_FALSE_OR_POP
                                        | Op::JUMP_IF_TRUE_OR_POP
                                        | Op::JUMP_IF_FALSE
                                        | Op::JUMP_IF_TRUE
                                ) {
                                    break;
                                }
                                if matches!(
                                    ins.op,
                                    Op::RETURN_VALUE
                                        | Op::RETURN_CONST
                                        | Op::RAISE_VARARGS
                                        | Op::RERAISE
                                ) {
                                    body_end = Some(ins.end());
                                    break;
                                }
                                if let Some(t) = ins.target {
                                    if !ins.is_backward
                                        && t > ins.offset
                                        && is_jf(ins.op)
                                    {
                                        let internal = self.instrs[bx..k2]
                                            .iter()
                                            .any(|x| x.target == Some(t));
                                        if !internal {
                                            body_end = Some(ins.end());
                                            break;
                                        }
                                    }
                                }
                                k2 += 1;
                                if k2 - bx > 400 {
                                    break;
                                }
                            }
                            if let Some(be) = body_end {
                                let merged: ExprRef = Rc::new(Expr::Compare {
                                    operands: acc_operands_t,
                                    ops: acc_ops_t,
                                });
                                if scc_dbg {
                                    eprintln!("SCC-tramp: merged body [{},{})", b_off, be);
                                }
                                return Some((negate_cond(merged), b_off, be));
                            }
                        }
                    }
                }
            }
        }
        // walk the remaining links: pure value region ending in a PJIF to
        // the SAME else label
        let mut acc_ops = ops.clone();
        let mut acc_operands = operands.clone();
        let mut k = ci + 1;
        let mut body_start = None;
        let mut links = 0usize;
        let mut link_targets: Vec<usize> = vec![target];
        loop {
            let mut region_start = k;
            let mut jk = None;
            let mut steps = 0;
            while let Some(ins) = self.instrs.get(k) {
                if is_link_jump(ins.op) {
                    jk = Some(k);
                    break;
                }
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                    && !ins.is_backward
                {
                    // chain fully matched: success hop into the body —
                    // only after at least one additional link (a bare JF
                    // here is a break/exit hop, not a chain)
                    if links >= 1 {
                        body_start = ins.target;
                    }
                    break;
                }
                if !is_pure_value_op(ins.op)
                    // <=3.11 chained comparisons keep the rhs value
                    // alive across links with DUP_TOP + ROT_* right
                    // before the link's COMPARE — chain bookkeeping,
                    // not a statement (asyncore 3.8 poll
                    // `if [] == r == w == e:` — link 1's region bailed
                    // on DUP_TOP and the head link split off as an
                    // outer if). 3.11+ uses SWAP/COPY for the same
                    // bookkeeping (aifc 3.11 _read_float
                    // `if expon == himant == lomant == 0:` split at
                    // the head link, dropping the elif chain out of
                    // the guard and breaking semantics)
                    && !matches!(
                        ins.op,
                        Op::DUP_TOP
                            | Op::ROT_TWO
                            | Op::ROT_THREE
                            | Op::ROT_FOUR
                            | Op::SWAP
                            | Op::COPY
                    )
                {
                    if scc_dbg { eprintln!("SCC: bail impure {:?} off={}", ins.op, ins.offset); }
                    return None;
                }
                k += 1;
                steps += 1;
                if steps > 32 {
                    return None;
                }
            }
            if let Some(bs) = body_start {
                let _ = region_start;
                // scan the body for its terminator: a RETURN/RAISE ends it
                // outright; a forward jump that nothing inside the body
                // targets internally is the else-skip hop
                let Some(&bi) = self.idx_of.get(&bs) else {
                    if scc_dbg { eprintln!("SCC: bail body idx"); }
                    return None;
                };
                let mut body_end = None;
                let mut k2 = bi;
                while let Some(ins) = self.instrs.get(k2) {
                    // a body that FALLS THROUGH to the chain's skip label
                    // ends there: link targets at/after the body start
                    // bound the span. Without this the scan runs past the
                    // skip into the FOLLOWING statement and adopts its
                    // first forward hop as the "else-skip" (t_chain 3.10:
                    // body_end overshot 46 into the next if's JF at 64,
                    // then the link-into-body veto rejected the whole
                    // chain and both bodies were ejected from their
                    // guards).
                    if ins.offset > bs && link_targets.iter().any(|&t| t == ins.offset) {
                        body_end = Some(ins.offset);
                        break;
                    }
                    if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS) {
                        body_end = Some(ins.end());
                        break;
                    }
                    if let Some(t) = ins.target {
                        if !ins.is_backward
                            && t > ins.offset
                            && matches!(
                                ins.op,
                                Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                            )
                        {
                            let internal = self.instrs[bi..k2]
                                .iter()
                                .any(|x| x.target == Some(t));
                            if !internal {
                                body_end = Some(ins.end());
                                break;
                            }
                        }
                    }
                    k2 += 1;
                    if k2 - bi > 400 {
                        return None;
                    }
                }
                let Some(be) = body_end else {
                    if scc_dbg { eprintln!("SCC: bail body_end"); }
                    return None;
                };
                // no link may exit INTO the body
                if link_targets.iter().any(|&t| t >= bs && t < be) {
                    if scc_dbg { eprintln!("SCC: bail link-into-body"); }
                    return None;
                }
                return Some((
                    Rc::new(Expr::Compare {
                        operands: acc_operands,
                        ops: acc_ops,
                    }),
                    bs,
                    be,
                ));
            }
            let jk = match jk {
                Some(x) => x,
                None => {
                    if scc_dbg { eprintln!("SCC: bail no jk"); }
                    return None;
                }
            };
            // each link exits to its own cleanup/continue label (the last
            // link often jumps straight to the loop top) — record and
            // validate against the body span afterwards
            let Some(lt) = self.instrs[jk].target else {
                return None;
            };
            link_targets.push(lt);
            // the region must end with the link's COMPARE_OP; the link's
            // rhs operand is the region BEFORE it (stack order)
            let cmp_idx = match self.match_prev_real(jk) {
                Some(x) if x >= region_start => x,
                _ => {
                    if scc_dbg { eprintln!("SCC: bail prev_real"); }
                    return None;
                }
            };
            if self.instrs[cmp_idx].op != Op::COMPARE_OP {
                if scc_dbg { eprintln!("SCC: bail not-cmp {:?}", self.instrs[cmp_idx].op); }
                return None;
            }
            // trim the trailing chain bookkeeping (DUP/ROT run feeding
            // the COMPARE's retained operand) — the region sim starts
            // from an empty stack and would duplicate placeholders
            let mut sim_end = cmp_idx;
            while sim_end > region_start
                && matches!(
                    self.instrs[sim_end - 1].op,
                    Op::DUP_TOP
                        | Op::ROT_TWO
                        | Op::ROT_THREE
                        | Op::ROT_FOUR
                        | Op::SWAP
                        | Op::COPY
                )
            {
                sim_end -= 1;
            }
            let rhs = match self.sim_value_region(region_start, sim_end) {
                Some(r) => r,
                None => {
                    if scc_dbg { eprintln!("SCC: bail sim"); }
                    return None;
                }
            };
            acc_ops.push(cmp_from_index(compare_op_index(
                self.instrs[cmp_idx].arg as u32,
                self.version,
            )));
            acc_operands.push(rhs);
            links += 1;
            k = jk + 1;
        }
    }

    /// 3.12+ statement `A or (B and C ...)` where the and-group uses the
    /// guard-chain idiom: each link passes FORWARD via PJIT and fails via
    /// a JUMP_BACKWARD trampoline to the shared skip:
    ///   <A>; PJIT BODY; <B>; PJIT next; JB SKIP; <C>; PJIT BODY; JB SKIP;
    ///   BODY: ...; back edge; [SKIP]
    /// (t_orac 3.12+: `if flag is None or (x>0 and x<lim): append` --
    /// without this the guard-chain machinery inverts to
    /// `if not A: if not B: continue; if not C: continue` and ejects the
    /// body). Returns (merged cond, body_start, body_end).
    fn try_or_group_chain_312(
        &self,
        cond: &ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        if !self.version.at_least(3, 12) {
            return None;
        }
        let is_pjit = |o: Op| {
            matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE)
        };
        let is_jb = |o: Op| {
            matches!(
                o,
                Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD_NO_INTERRUPT
            )
        };
        let pad = |o: Op| matches!(o, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL);
        let ci = *self.idx_of.get(&self.cur_offset)?;
        let ti = *self.idx_of.get(&target)?;
        if ti <= ci + 1 {
            return None;
        }
        let mut g2: Vec<ExprRef> = Vec::new();
        let mut skip: Option<usize> = None;
        let mut region_start = ci + 1;
        let mut k = ci + 1;
        while k < ti {
            let ins = self.instrs[k];
            if pad(ins.op) || (is_pure_value_op(ins.op) && ins.target.is_none()) {
                k += 1;
                continue;
            }
            if is_pjit(ins.op) {
                let t = ins.target?;
                let operand = self.sim_value_region(region_start, k)?;
                if t == target {
                    // last link passes into the body; its trampoline must
                    // be immediately after (padding tolerated)
                    let mut m = k + 1;
                    while m < self.instrs.len() && pad(self.instrs[m].op) {
                        m += 1;
                    }
                    let jb = self.instrs.get(m)?;
                    if !(jb.is_backward && is_jb(jb.op)) {
                        return None;
                    }
                    let s = jb.target?;
                    match skip {
                        None => skip = Some(s),
                        Some(x) if x == s => {}
                        _ => return None,
                    }
                    g2.push(operand);
                    break;
                }
                if t <= ins.offset || t >= target {
                    return None;
                }
                // intermediate link: PJIT to the next test, then the
                // fail trampoline JUMP_BACKWARD to the shared skip
                let mut m = k + 1;
                while m < self.instrs.len() && pad(self.instrs[m].op) {
                    m += 1;
                }
                let jb = self.instrs.get(m)?;
                if !(jb.is_backward && is_jb(jb.op)) {
                    return None;
                }
                let s = jb.target?;
                match skip {
                    None => skip = Some(s),
                    Some(x) if x == s => {}
                    _ => return None,
                }
                g2.push(operand);
                region_start = m + 1;
                k = m + 1;
                continue;
            }
            return None;
        }
        let skip = skip?;
        if g2.is_empty() {
            return None;
        }
        let loop_top = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map(|b| b.start);
        let body_end = if skip > target {
            skip
        } else if Some(skip) == loop_top {
            self.instrs[ti..]
                .iter()
                .find(|x| {
                    x.is_backward
                        && x.target == Some(skip)
                        && matches!(
                            x.op,
                            Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                })
                .map(|x| x.offset)?
        } else {
            return None;
        };
        if body_end <= target {
            return None;
        }
        let a2: ExprRef = if g2.len() == 1 {
            g2.pop().unwrap()
        } else {
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::And,
                values: g2,
            })
        };
        let mut or_vals = Vec::new();
        flatten_boolop(cond.clone(), BoolOpKind::Or, &mut or_vals);
        flatten_boolop(a2, BoolOpKind::Or, &mut or_vals);
        Some((
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::Or,
                values: or_vals,
            }),
            target,
            body_end,
        ))
    }

    /// 3.14 value-position `A1 and ... An or C`: every operand carries its
    /// own COPY/TO_BOOL value-preserving idiom; the and-links PJIF to the
    /// or-continuation (this jump's target) and the LAST and-operand PJITs
    /// to the merge M; [target, M) evaluates C (t_pb f1/g_val 3.14: the
    /// per-jump value_merge blocks mis-nest the chain into
    /// `a and (b or c)`). Read-only; returns (merged value, merge offset).
    fn try_value_and_or_314(
        &self,
        cond: &ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize)> {
        if !self.version.at_least(3, 14) {
            return None;
        }
        let is_pjif = |o: Op| {
            matches!(o, Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE)
        };
        let is_pjit = |o: Op| {
            matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE)
        };
        let pad = |o: Op| matches!(o, Op::NOP | Op::NOT_TAKEN | Op::CACHE);
        // this jump must carry the value idiom (COPY; TO_BOOL; PJIF)
        let ci = *self.idx_of.get(&self.cur_offset)?;
        if !(ci >= 2
            && self.instrs[ci - 1].op == Op::TO_BOOL
            && self.instrs[ci - 2].op == Op::COPY)
        {
            return None;
        }
        let ti = *self.idx_of.get(&target)?;
        if ti <= ci + 1 {
            return None;
        }
        // a value-idiom cond jump at index j: COPY; TO_BOOL; jump
        let idiom_link = |j: usize| -> bool {
            j >= 2 && self.instrs[j - 1].op == Op::TO_BOOL && self.instrs[j - 2].op == Op::COPY
        };
        let mut ands: Vec<ExprRef> = vec![cond.clone()];
        let mut region_start = ci + 1;
        let mut k = ci + 1;
        let mut merge = None;
        while k < ti {
            let ins = self.instrs[k];
            if pad(ins.op) {
                k += 1;
                continue;
            }
            if ins.op == Op::POP_TOP {
                // the dropped previous-operand copy: the next operand
                // region starts after it
                if k >= region_start {
                    region_start = k + 1;
                }
                k += 1;
                continue;
            }
            if (is_pjif(ins.op) || is_pjit(ins.op)) && idiom_link(k) {
                if k < region_start {
                    return None;
                }
                let operand = self.sim_value_region(region_start, k - 2)?;
                if is_pjif(ins.op) {
                    if ins.target != Some(target) {
                        return None;
                    }
                    ands.push(operand);
                    region_start = k + 1;
                    k += 1;
                    continue;
                }
                let m = ins.target?;
                if m <= target {
                    return None;
                }
                ands.push(operand);
                merge = Some(m);
                break;
            }
            if matches!(ins.op, Op::COPY | Op::TO_BOOL) && ins.target.is_none() {
                // the link idiom's own bookkeeping ops
                k += 1;
                continue;
            }
            if ins.target.is_some() || !is_pure_value_op(ins.op) {
                return None;
            }
            k += 1;
        }
        let m = merge?;
        if ands.len() < 2 {
            return None;
        }
        // [target, m) is the or's second operand: a pure value region
        // (its leading POP_TOP discards the arriving operand copy)
        let mi = *self.idx_of.get(&m)?;
        if mi <= ti {
            return None;
        }
        let mut cstart = ti;
        while matches!(
            self.instrs.get(cstart).map(|x| x.op),
            Some(Op::POP_TOP) | Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
        ) {
            cstart += 1;
        }
        if cstart >= mi {
            return None;
        }
        if !self.instrs[cstart..mi].iter().all(|x| {
            x.target.is_none()
                && (is_pure_value_op(x.op)
                    || matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::POP_TOP))
        }) {
            return None;
        }
        let c = self.sim_value_region(cstart, mi)?;
        let mut and_flat = Vec::new();
        for v in ands {
            flatten_boolop(v, BoolOpKind::And, &mut and_flat);
        }
        let and = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values: and_flat,
        }) as ExprRef;
        let mut or_flat = Vec::new();
        flatten_boolop(and, BoolOpKind::Or, &mut or_flat);
        flatten_boolop(c, BoolOpKind::Or, &mut or_flat);
        Some((
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::Or,
                values: or_flat,
            }),
            m,
        ))
    }

    /// 3.12+ `if A or B: body` or-join: both operand tests share polarity
    /// and jump to the BODY start; the false path is an unconditional
    /// backward jump (continue trampoline) immediately before the body
    /// (NOT_TAKEN-padded on 3.14), and the body ends at the loop's back
    /// edge. The split_cond AND merge would DeMorgan-invert the pair
    /// (`not A and not B`) and eject the body to run unconditionally
    /// (t_or38 g1 3.12-3.14). Returns (merged cond, body_end); the caller
    /// pops the absorbed first-operand block.
    /// Statement-level DNF `if (A1 and A2 ...) or (B1 and B2 ...): body`
    /// (codecs StreamReader.read, all versions with POP_JUMP opcodes):
    ///   <A1>; PJIF T_B; <A2>; PJIT BODY; T_B: <B1>; PJIF SKIP; <B2>;
    ///   PJIF SKIP; BODY: ...; SKIP:
    /// Group 1's and-links false-exit to the SECOND OR-GROUP (T_B, the
    /// first jump's target) and its last operand joins the body on TRUE
    /// (PJIT); group 2's links false-exit to the shared SKIP and fall
    /// through into the body. try_merge_or_cond misreads this shape (it
    /// takes T_B as the body start, folds `not A1 or not A2` and nests
    /// group 2 as the body -- inverting the semantics). All read-only
    /// sims; returns (merged cond, body_start, body_end).
    fn try_or_group_chain(
        &self,
        cond: &ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        let is_pjif = |o: Op| {
            matches!(o, Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE)
        };
        let is_pjit = |o: Op| {
            matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE)
        };
        let pad = |o: Op| matches!(o, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL);
        let ci = *self.idx_of.get(&self.cur_offset)?;
        let tbi = *self.idx_of.get(&target)?;
        if tbi <= ci + 1 || target <= self.cur_next {
            return None;
        }
        // group 1: and-links (PJIF -> target) then a final PJIT -> body
        let mut g1: Vec<ExprRef> = vec![cond.clone()];
        let mut region_start = ci + 1;
        let mut k = ci + 1;
        let mut body = None;
        while k < tbi {
            let ins = self.instrs[k];
            if is_pjif(ins.op) {
                if ins.target != Some(target) {
                    return None;
                }
                g1.push(self.sim_value_region(region_start, k)?);
                region_start = k + 1;
            } else if is_pjit(ins.op) {
                let b = ins.target?;
                if b <= target {
                    return None;
                }
                g1.push(self.sim_value_region(region_start, k)?);
                body = Some(b);
                break;
            } else if !is_pure_value_op(ins.op) && !pad(ins.op) {
                return None;
            }
            k += 1;
        }
        let body = body?;
        if g1.len() < 2 {
            return None; // single-operand first group: the simple `A or B`
        }
        // group 2 at [target, body): and-links PJIF -> shared SKIP, then
        // fall-through (padding only) into the body
        let mut g2: Vec<ExprRef> = Vec::new();
        let mut skip = None;
        let mut region_start = tbi;
        let mut k = tbi;
        let bodyi = *self.idx_of.get(&body)?;
        while k < bodyi {
            let ins = self.instrs[k];
            if is_pjif(ins.op) {
                let t = ins.target?;
                match skip {
                    None => skip = Some(t),
                    Some(s) if s == t => {}
                    _ => return None,
                }
                g2.push(self.sim_value_region(region_start, k)?);
                region_start = k + 1;
            } else if is_pjit(ins.op) || ins.is_backward {
                return None;
            } else if !is_pure_value_op(ins.op) && !pad(ins.op) {
                return None;
            }
            k += 1;
        }
        let skip = skip?;
        if g2.is_empty() {
            return None;
        }
        // the tail of group 2 must fall through into the body (padding only)
        if !self.instrs[region_start..bodyi]
            .iter()
            .all(|x| x.target.is_none() && pad(x.op))
        {
            return None;
        }
        // body end: clean (skip past the body) or fused (skip == loop top)
        let loop_top = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map(|b| b.start);
        let body_end = if skip > body {
            skip
        } else if Some(skip) == loop_top {
            self.instrs[bodyi..]
                .iter()
                .find(|x| {
                    x.is_backward
                        && x.target == Some(skip)
                        && matches!(
                            x.op,
                            Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                })
                .map(|x| x.offset)?
        } else {
            return None;
        };
        if body_end <= body {
            return None;
        }
        let a1 = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values: g1,
        }) as ExprRef;
        let a2: ExprRef = if g2.len() == 1 {
            g2.pop().unwrap()
        } else {
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::And,
                values: g2,
            })
        };
        let mut or_vals = Vec::new();
        flatten_boolop(a1, BoolOpKind::Or, &mut or_vals);
        flatten_boolop(a2, BoolOpKind::Or, &mut or_vals);
        Some((
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::Or,
                values: or_vals,
            }),
            body,
            body_end,
        ))
    }

    fn try_or_join(
        &self,
        cond: &ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<(ExprRef, usize, usize)> {
        // PJIT pairs only: a same-polarity PJIF pair with a continue
        // trampoline before the target is the classic `if A and B: stmt;
        // continue` -- indistinguishable locally from the or-join, and
        // split_cond below already merges it correctly (b16_loopflow
        // regressed 10/13 when the PJIF pair was admitted here).
        if !jump_if_true {
            return None;
        }
        let top = self.blocks.last()?;
        if !(matches!(top.kind, BlockType::If)
            && top.cond_set
            && top.short_circuit.is_none()
            && top.end == target
            && target > self.cur_next
            && top.jump_if_true == jump_if_true
            && top.stmts.is_empty())
        {
            return None;
        }
        let prev = top.cond.clone()?;
        let s0 = *self.idx_of.get(&top.start)?;
        let e_cur = *self.idx_of.get(&self.cur_offset)?;
        let e0 = *self.idx_of.get(&target)?;
        if e0 < 2 || e_cur + 1 > e0 - 1 {
            return None;
        }
        // the false exit: unconditional backward jump to the enclosing
        // loop top right before the body
        let fx = &self.instrs[e0 - 1];
        if !(fx.is_backward
            && matches!(
                fx.op,
                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT
            )
            && fx.target.map_or(false, |t| {
                self.blocks.iter().any(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (b.start == t || b.cond_end == t)
                })
            }))
        {
            return None;
        }
        // NOTHING but padding between this jump and the trampoline: any
        // statement op or jump in between is an explicit guard-continue
        // (ast 3.14 dump _format `if A and B: continue` -- absorbing it
        // DeMorgans the guard and wraps the fall-through body; the 3.14
        // continue-guard machinery renders the source form).
        if !self.instrs[e_cur + 1..e0 - 1].iter().all(|x| {
            x.target.is_none()
                && matches!(x.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE)
        }) {
            return None;
        }
        let tramp_end = fx.end();
        // pure value region between the two operand jumps
        if !self.instrs[s0..e_cur].iter().all(|x| {
            x.target.is_none()
                && (is_pure_value_op(x.op)
                    || matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL))
        }) {
            return None;
        }
        // the body ends at the loop's back edge (first backward
        // unconditional jump to a loop top at/after the body start)
        let back_edge = self.instrs[e0..].iter().find(|x| {
            x.is_backward
                && matches!(
                    x.op,
                    Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
                && x.target.map_or(false, |t| {
                    self.blocks.iter().any(|b| {
                        matches!(b.kind, BlockType::While | BlockType::For)
                            && (b.start == t || b.cond_end == t)
                    })
                })
        });
        let body_end = match back_edge {
            Some(x) => x.offset,
            None => {
                // no back edge before the loop ends: the shared success
                // block may be a sunk return stub ([POP_TOP/pads/loads]
                // RETURN) — `if A or B: return K` at the loop tail
                // (_collections_abc 3.13 ItemsView.__contains__). Only
                // the stub shape qualifies; a statement body keeps
                // requiring the back edge.
                let mut rend = None;
                for x in self.instrs[e0..].iter() {
                    if matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                        rend = Some(x.end());
                        break;
                    }
                    if is_pure_value_op(x.op)
                        || matches!(
                            x.op,
                            Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE
                                | Op::EXTENDED_ARG
                                | Op::POP_TOP
                                | Op::POP_ITER
                                | Op::SWAP
                                | Op::COPY
                                | Op::TO_BOOL
                        )
                    {
                        continue;
                    }
                    if x.target.is_some() {
                        break;
                    }
                }
                rend?
            }
        };
        if body_end <= target {
            return None;
        }
        // branch-TAKEN (PJIT) reaches the body: both operands contribute
        // positively to the Or; prev was stored negated for the
        // fall-through modeling, negate_cond restores it (involution)
        let a = negate_cond(prev);
        let mut values = Vec::new();
        flatten_boolop(a, BoolOpKind::Or, &mut values);
        flatten_boolop(cond.clone(), BoolOpKind::Or, &mut values);
        Some((
            Rc::new(Expr::BoolOp { op: BoolOpKind::Or, values }),
            body_end,
            tramp_end,
        ))
    }

    fn try_guard_chain(&self, cond: &ExprRef, jump_if_true: bool, target: usize)
        -> Option<(ExprRef, usize, usize, usize)>
    {
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
            )
        };
        // the enclosing loop top: the trampoline's back-jump target
        let ci = *self.idx_of.get(&self.cur_offset)?;
        // shape A's trampoline must be separated from the jump by real
        // NOT_TAKEN padding (3.12+); a bare adjacent back jump is py2/3.11
        // `if c: continue` and belongs to the historical machinery.
        // 3.13+ dropped NOT_TAKEN from this position entirely: the
        // continue trampoline sits DIRECTLY after the cond jump (copyreg
        // 3.13 _reduce_ex `if isinstance(...) and new.__self__ is base:
        // break` — PJIT→next cond; JUMP_BACKWARD loop_top) — admit the
        // bare-adjacent shape only there; the degenerate single-guard
        // path still renders `if c: continue` correctly
        let pad_present = matches!(
            self.instrs.get(ci + 1).map(|x| x.op),
            Some(Op::NOT_TAKEN)
        ) || self.version.at_least(3, 12);
        let mut t = ci + 1;
        while matches!(self.instrs.get(t).map(|x| x.op), Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)) {
            t += 1;
        }
        let tramp = self.instrs.get(t)?;
        if !tramp.is_backward
            || !matches!(
                tramp.op,
                Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD_NO_INTERRUPT
            )
            || !pad_present
        {
            // shape B (3.11+ statement chain-compare ifs): the FAIL
            // trampoline lives at this jump's TARGET ([POP_TOP;]
            // JUMP_BACKWARD loop_top) and the chain advances on
            // fall-through into ANOTHER test ending at a pass-exit hop.
            // Strict admission: mid-chain guards (whose fall-through is a
            // plain body) must fall back to the generic If nesting.
            if self.shape_b_admit(ci, target) {
return self
                        .try_guard_chain_fallthrough(cond, jump_if_true, target)
                        .map(|(m, bs, be)| (m, bs, be, usize::MAX));
            }
return None;
        }
        let loop_top = tramp.target?;
        let tramp_off = tramp.offset;
        if !self.blocks.iter().any(|b| {
            matches!(b.kind, BlockType::While | BlockType::For)
                && (b.start == loop_top
                    || (b.cond_end != usize::MAX && b.cond_end == loop_top))
        }) {
            return None;
        }
        // sequential shape check: when the pass-jump target IS the very
        // next real instruction after this guard's own continue
        // trampoline, the guard is locally ambiguous between a
        // standalone `if not X: continue` and a fused and-chain link.
        // Decide by the chain TAIL: walk the guarded links; a chain
        // ending at a break chunk is the real fused `if A and B: break`
        // (copyreg 3.13 _reduce_ex — the links are separated by their
        // own trampolines so its target is NOT next-after-tramp, but
        // _slotnames-style single guards are). A chain that stops at
        // plain statements after advancing means sibling `if not X:
        // continue` guards — fusing them nests the loop's tail
        // statements under the last guard and drops their continue
        // semantics (bdb 3.13 effective: the fused form ran the try
        // tail for disabled breakpoints). Bail to the historical
        // per-guard machinery in that case.
        let after_tramp = {
            let mut k = self.idx_of.get(&tramp_off).map(|&i2| i2 + 1);
            while let Some(kk) = k {
                match self.instrs.get(kk).map(|x| x.op) {
                    Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE) => {
                        k = Some(kk + 1);
                    }
                    _ => break,
                }
            }
            k.and_then(|kk| self.instrs.get(kk)).map(|x| x.offset)
        };
        if after_tramp == Some(target)
            && self.version.at_least(3, 13)
            && !self.version.at_least(3, 14)
        {
            // veto applies to 3.13 ONLY: with NOT_TAKEN padding present
            // (3.14+) the historical multi-link fusion renders these
            // chains better (compileall 3.14 _walk_dir 5-operand elif
            // chain, bdb 3.14 effective — the veto there split them
            // into per-link continues and raised nd)
            let is_cj = |o: Op| {
                matches!(
                    o,
                    Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_TRUE
                )
            };
            let mut cur = target;
            let mut advanced = false;
            let tail = loop {
                let Some(&ri) = self.idx_of.get(&cur) else {
                    break None;
                };
                let mut jk = ri;
                let mut cond_at = None;
                while jk < self.instrs.len() {
                    let ins = &self.instrs[jk];
                    if is_cj(ins.op) {
                        cond_at = Some(jk);
                        break;
                    }
                    if !is_pure_value_op(ins.op)
                        && !matches!(
                            ins.op,
                            Op::NOT_TAKEN | Op::NOP | Op::CACHE | Op::TO_BOOL
                        )
                    {
                        break;
                    }
                    jk += 1;
                }
                let Some(cj) = cond_at else {
                    break Some(cur);
                };
                let mut ft = cj + 1;
                while matches!(
                    self.instrs.get(ft).map(|x| x.op),
                    Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
                ) {
                    ft += 1;
                }
                let ok_tramp = self.instrs.get(ft).map_or(false, |x| {
                    x.is_backward
                        && x.target == Some(loop_top)
                        && matches!(
                            x.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                });
                if !ok_tramp {
                    break Some(cur);
                }
                let Some(nt) = self.instrs[cj].target else {
                    break Some(cur);
                };
                advanced = true;
                cur = nt;
            };
            if let Some(stop) = tail {
                if advanced {
                    // stop must be a break chunk ([POP_TOP/pads] + a
                    // forward jump to a loop exit) or the "chain" is a
                    // run of sibling continue guards
                    let is_break_chunk = self
                        .idx_of
                        .get(&stop)
                        .map_or(false, |&si| {
                            let mut k = si;
                            while matches!(
                                self.instrs.get(k).map(|x| x.op),
                                Some(Op::POP_TOP)
                                    | Some(Op::NOT_TAKEN)
                                    | Some(Op::NOP)
                                    | Some(Op::CACHE)
                            ) {
                                k += 1;
                            }
                            self.instrs.get(k).map_or(false, |x| {
                                !x.is_backward
                                    && matches!(
                                        x.op,
                                        Op::JUMP_FORWARD
                                            | Op::JUMP
                                            | Op::JUMP_ABSOLUTE
                                    )
                                    && x.target
                                        .map_or(false, |t| {
                                            self.jump_is_loop_exit_or_merge(t)
                                        })
                            })
                        });
                    if !is_break_chunk {
                        return None;
                    }
                }
                // !advanced: sequential SINGLE guard — the consumer
                // decides between the threaded nested-if form and the
                // historical inverted continue
            }
        }
        // walk the guard chain. Shape A: the chain advances through the
        // JUMP and the fall-through is the continue trampoline, so an
        // operand contributes positively when its jump is PJIT (advances
        // on true) and negated for PJIF — first link included.
        let mut values: Vec<ExprRef> = Vec::new();
        // does the chain continue past this jump (another test region) or
        // does the jump exit into the body/break block? Continuing chains
        // advance THROUGH the jump (PJIT = positive); an exiting single
        // guard renders `if Not(cond): continue`-style with the jump side
        // as the body (PJIT = negated).
        let chain_continues = self
            .idx_of
            .get(&target)
            .map_or(false, |&ti| {
                let mut s = ti;
                let mut steps = 0;
                loop {
                    let Some(ins) = self.instrs.get(s) else {
                        return false;
                    };
                    if matches!(
                        ins.op,
                        Op::POP_JUMP_IF_FALSE
                            | Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_FALSE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                    ) {
                        return true;
                    }
                    // a trampoline INSIDE the lookahead span means the
                    // target begins a NEW statement, not another link of
                    // this and-chain: the sequential per-link trampoline
                    // walk below would have consumed it as an operand
                    // guard had the chain been real. 3.13 bare adjacency
                    // made the `if not A: continue; if not B: continue`
                    // guard pair look like one fused `if A and B:` chain
                    // (bdb 3.13 effective: the loop-level try tail was
                    // swallowed into a nested body, dropping the
                    // guards' continue semantics)
                    if ins.is_backward
                        && matches!(
                            ins.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                        && ins.target == Some(loop_top)
                    {
                        return false;
                    }
                    if !is_pure_value_op(ins.op) || steps > 40 {
                        return false;
                    }
                    s += 1;
                    steps += 1;
                }
            });
        // a backward jump landing on the pass-jump's target — or the
        // fall-through trampoline serving as a LOOP BACK EDGE (its target
        // is a pure cond-expr top strictly before this jump) — means this
        // is a rotated-while cond whose exit was threaded onto an
        // enclosing loop, not a guard chain
        let target_is_loop_top = self
            .instrs
            .iter()
            .any(|ins| ins.is_backward && ins.target == Some(target));
        // rotated-while signature: a backward jump in the chain span
        // loops onto a pure cond-expr top strictly before this jump —
        // these jumps belong to a loop structure, not a guard chain.
        // The scan stays INSIDE the guard's own loop span: 3.11+
        // out-of-line exception handlers sit at the function tail and
        // their JBNI resumes can point back at a cond-looking region
        // (csv 3.13 has_header: the try handler's JBNI->330 inside a
        // 300-instr window vetoed the `if thisType != ...` guard)
        let rbe_bound = self
            .blocks
            .iter()
            .rev()
            .find(|b| {
                matches!(b.kind, BlockType::While | BlockType::For)
                    && (b.start == loop_top
                        || (b.cond_end != usize::MAX && b.cond_end == loop_top))
            })
            .map(|b| b.end)
            .filter(|e| *e != usize::MAX);
        let rotated_back_edge = self
            .instrs
            .iter()
            .skip(ci)
            .take(300)
            .take_while(|ins| rbe_bound.map_or(true, |bnd| ins.offset < bnd))
            .any(|ins| {
                ins.is_backward
                    && ins.target.map_or(false, |bt| {
                        bt < self.cur_offset
                            && self.is_cond_expr_top(bt, self.cur_offset)
                    })
            });
        if target_is_loop_top || rotated_back_edge {
            return None;
        }
        // the pass side lands on an enclosing loop's exit: a rotated
        // while's re-eval link (3.13 `while A and B:` — POP_JUMP_IF_NONE
        // followed directly by the body back edge) belongs to the
        // dup_while machinery; shape A would read it as a degenerate
        // guard and emit a phantom `if <cond>: break` (b16 while_and,
        // v38_walrus 3.13). Genuine guard-chain bodies live INSIDE the
        // loop span — a pass exit into a chain body still lands before
        // the loop's end (copyreg 3.13 _reduce_ex)
        if self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map_or(false, |b| {
                self.loop_exit_offset(b).map_or(false, |le| {
                    self.effective_offset(le) == self.effective_offset(target)
                        // the re-eval's false exit may land on the
                        // loop's own sunk tail-return stub right
                        // before the registered exit (configparser
                        // 3.13 `while rest:` — the re-eval PJIF
                        // targets a duplicated RETURN_CONST one
                        // stub before the exit)
                        || self.is_term_pad_before(target, le, false)
                })
            })
        {
            return None;
        }
        // single guard exiting DIRECTLY into a break chunk (copyreg
        // 3.12 _reduce_ex `if new.__self__ is base: break`): PJIT
        // jumps into [POP_TOP; JF loop-exit], the fall-through is the
        // continue trampoline. The historical inverted rendering
        // (`if is not base: continue` + loop-level break) recompiles
        // the operand (is -> is-not + PJIF) and breaks sig-exactness;
        // the degenerate direct form keeps the single computation.
        // 3.13 already routes this through the consumer's tailwalk
        // case (b); 3.14 keeps the historical form (untested there).
        // Sunk-return breaks (POP_TOP + loads + RETURN, no hop) are
        // left to the existing direct-form branch below.
        if values.is_empty()
            && !chain_continues
            && jump_if_true
            && self.version.at_least(3, 12)
            && !self.version.at_least(3, 14)
        {
            if let Some(&ti) = self.idx_of.get(&target) {
                let mut k = ti;
                while matches!(
                    self.instrs.get(k).map(|x| x.op),
                    Some(Op::POP_TOP)
                        | Some(Op::POP_ITER)
                        | Some(Op::NOT_TAKEN)
                        | Some(Op::NOP)
                        | Some(Op::CACHE)
                ) {
                    k += 1;
                }
                if self.instrs.get(k).map_or(false, |x| {
                    !x.is_backward
                        && matches!(
                            x.op,
                            Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                        )
                        && x.target
                            .map_or(false, |t| self.jump_is_loop_exit_or_merge(t))
                }) {
                    let hop_end = self.instrs[k].end();
                    return Some((
                        cond.clone(),
                        target,
                        hop_end,
                        loop_top,
                    ));
                }
            }
        }
        let first = if chain_continues {
            if jump_if_true {
                cond.clone()
            } else {
                negate_cond(cond.clone())
            }
        } else if jump_if_true {
            // 3.13+ keeps the operand's comparison op and flips the
            // JUMP for a negated guard (`if not X == Y:` -> ==; PJIT) —
            // rendering the folded compare flips the recompiled polarity
            // (_strptime 3.13/3.14 loop guards); the explicit Not form
            // recompiles back to op + inverted jump
            if self.version.at_least(3, 13) {
                simplify_not_or_wrap(cond.clone())
            } else {
                negate_cond(cond.clone())
            }
        } else {
            cond.clone()
        };
        flatten_boolop(first, BoolOpKind::And, &mut values);
        let mut next = target;
        let mut body_start;
        loop {
            let Some(&ni) = self.idx_of.get(&next) else {
return None;
            };
            // scan the operand region up to its cond jump
            let region_start = ni;
            let mut jk = ni;
            while jk < self.instrs.len() {
                let ins = &self.instrs[jk];
                if is_cond_jump(ins.op) {
                    break;
                }
                if !is_pure_value_op(ins.op) {
                    // not another guard: `next` is the body start
                    break;
                }
                jk += 1;
            }
            if jk >= self.instrs.len() || !is_cond_jump(self.instrs[jk].op) {
                if next == target {
                    // the chain never advanced: every guard's pass side
                    // exits through the fall-through continue trampoline
                    // and the jump target is the LOOP-LEVEL body —
                    // `if <guards>: continue` with the body outside
                    //
                    // 3.12 direct-form exception (copy _deepcopy_tuple):
                    // a single PJIT guard whose target body carries a
                    // sunk copy of the function's tail return
                    // (POP_TOP + value loads + RETURN = `break` with a
                    // sunk value return) is the compiler's own layout
                    // for `if cond: <body>; break` at the loop tail —
                    // the inverted continue form recompiles to PJIF and
                    // breaks sig-exactness. Render the direct If over
                    // the body; try_fold_sunk_for_break supplies the
                    // Break and the for-else registration on the walk.
                    if values.len() == 1
                        && jump_if_true
                        && self.version.at_least(3, 12)
                        && target > tramp_off
                    {
                        if let Some(lb) = self.blocks.iter().rev().find(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && (b.start == loop_top
                                    || (b.cond_end != usize::MAX
                                        && b.cond_end == loop_top))
                        }) {
                            let lb_end = lb.end;
                            if let (Some(&ti), Some(&bi)) =
                                (self.idx_of.get(&target), self.idx_of.get(&lb_end))
                            {
                                let is_pad = |x: &crate::bytecode::Instruction| {
                                    matches!(
                                        x.op,
                                        Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::CACHE
                                            | Op::EXTENDED_ARG
                                    )
                                };
                                let mut ok = true;
                                let mut ret_idx = None;
                                for ins in self.instrs[ti..bi].iter() {
                                    if matches!(
                                        ins.op,
                                        Op::RETURN_VALUE | Op::RETURN_CONST
                                    ) {
                                        ret_idx = Some(ins);
                                        continue;
                                    }
                                    if let Some(t) = ins.target {
                                        if ins.is_backward {
                                            if t == loop_top {
                                                ok = false;
                                                break;
                                            }
                                        } else if !(t > ins.offset
                                            && self
                                                .jump_is_loop_exit_or_merge(t))
                                        {
                                            ok = false;
                                            break;
                                        }
                                    }
                                }
                                // break-bearing body only: either a
                                // sunk copy of the tail return (3.10-
                                // 3.12 layout) or a break chunk
                                // ([POP_TOP/pads] + forward jump to a
                                // loop exit/merge). A plain fall-
                                // through body stays with the
                                // historical inverted continue
                                let break_bears = ret_idx.is_some()
                                    || self
                                        .idx_of
                                        .get(&target)
                                        .map_or(false, |&si| {
                                            let mut k = si;
                                            while matches!(
                                                self.instrs.get(k).map(|x| x.op),
                                                Some(Op::POP_TOP)
                                                    | Some(Op::NOT_TAKEN)
                                                    | Some(Op::NOP)
                                                    | Some(Op::CACHE)
                                            ) {
                                                k += 1;
                                            }
                                            self.instrs.get(k).map_or(false, |x| {
                                                !x.is_backward
                                                    && matches!(
                                                        x.op,
                                                        Op::JUMP_FORWARD
                                                            | Op::JUMP
                                                            | Op::JUMP_ABSOLUTE
                                                    )
                                                    && x.target.map_or(false, |t| {
                                                        self.jump_is_loop_exit_or_merge(t)
                                                    })
                                            })
                                        });
                                if !break_bears {
                                    ok = false;
                                }
                                // 3.12/3.13 direct-form guard whose body
                                // is the loop's tail: `if X: <body-to-
                                // loop-end>` compiles to PJIT-over-
                                // trampoline with the body running to
                                // the loop's own back edge. Two body
                                // shapes: (A) plain threaded (csv 3.13
                                // has_header `if thisType !=
                                // columnTypes[col]:` — case (c) misses
                                // it when the body leads with a non-PJ*
                                // conditional jump like
                                // POP_JUMP_IF_NOT_NONE); (B) genuine
                                // body-ending return preceded by for-
                                // loop iterator cleanup SWAP 2; POP_TOP
                                // (csv 3.12/3.13 _guess_delimiter `if d
                                // in delims.keys(): ... return`) — a
                                // sunk tail-return COPY lacks that
                                // cleanup and lacks computed ops in its
                                // value run. The stricter (A) scan here
                                // runs before the lenient 3.12 plain-
                                // thread branch below and falls through
                                // to it on rejection
                                // 3.14 keeps the historical inverted
                                // form — direct nesting there swallowed
                                // sibling elif guards and the post-loop
                                // tail (_osx_support 3.14
                                // _default_sysroot: the post-for `if
                                // _cache_default_sysroot is None` landed
                                // inside the elif's else)
                                if self.version.at_least(3, 12)
                                    && !self.version.at_least(3, 14)
                                    && jump_if_true
                                {
                                    let mut back_off = None;
                                    let mut last_real = None;
                                    let mut ok3 = true;
                                    let mut first_ret = None;
                                    for ins in self.instrs[ti..bi].iter() {
                                        if !is_pad(ins) {
                                            last_real = Some(ins.offset);
                                        }
                                        if matches!(
                                            ins.op,
                                            Op::RETURN_VALUE
                                                | Op::RETURN_CONST
                                        ) && first_ret.is_none()
                                        {
                                            first_ret = Some(ins.offset);
                                        }
                                        if let Some(t) = ins.target {
                                            if ins.is_backward {
                                                if t == loop_top {
                                                    if matches!(
                                                        ins.op,
                                                        Op::JUMP_BACKWARD
                                                            | Op::JUMP_ABSOLUTE
                                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                    ) {
                                                        back_off =
                                                            Some(ins.offset);
                                                    } else {
                                                        ok3 = false;
                                                        break;
                                                    }
                                                }
                                            } else if t >= lb_end {
                                                ok3 = false;
                                                break;
                                            }
                                        }
                                    }
                                    if ok3 {
                                        let mut accept = false;
                                        if let Some(ro) = first_ret {
                                            // (B): body ENDS at the
                                            // return, with iterator
                                            // cleanup before it and a
                                            // computed value in the run
                                            if last_real == Some(ro) {
                                                let rj = self.instrs[ti..bi]
                                                    .iter()
                                                    .position(|x| {
                                                        x.offset == ro
                                                    })
                                                    .map(|p| ti + p);
                                                if let Some(rj) = rj {
                                                    let mut p1 = None;
                                                    let mut p2 = None;
                                                    let mut k = rj;
                                                    while k > ti && p2.is_none()
                                                    {
                                                        k -= 1;
                                                        if is_pad(
                                                            &self.instrs[k],
                                                        ) {
                                                            continue;
                                                        }
                                                        if p1.is_none() {
                                                            p1 = Some(k);
                                                        } else {
                                                            p2 = Some(k);
                                                        }
                                                    }
                                                    let cleanup = p1
                                                        .zip(p2)
                                                        .map_or(false, |(a, b)| {
                                                            matches!(
                                                                self.instrs[a].op,
                                                                Op::POP_TOP
                                                            ) && matches!(
                                                                self.instrs[b].op,
                                                                Op::SWAP
                                                                    | Op::COPY
                                                            )
                                                        });
                                                    if cleanup {
                                                        accept = self.instrs
                                                            [ti..bi]
                                                            .iter()
                                                            .any(|ins| {
                                                                !is_pad(ins)
                                                                    && ins.offset
                                                                        < ro
                                                                    && !matches!(
                                                                        ins.op,
                                                                        Op::SWAP
                                                                            | Op::COPY
                                                                            | Op::POP_TOP
                                                                            | Op::LOAD_FAST
                                                                            | Op::LOAD_NAME
                                                                            | Op::LOAD_GLOBAL
                                                                            | Op::LOAD_DEREF
                                                                            | Op::LOAD_CONST
                                                                            | Op::LOAD_ATTR
                                                                            | Op::LOAD_METHOD
                                                                            | Op::LOAD_FAST_LOAD_FAST
                                                                            | Op::LOAD_FAST_AND_CLEAR
                                                                            | Op::PUSH_NULL
                                                                            | Op::RESUME
                                                                    )
                                                            });
                                                    }
                                                }
                                            }
                                        } else {
                                            // (A): plain threaded body —
                                            // the back edge is the body's
                                            // last real instruction
                                            accept = back_off.is_some()
                                                && back_off == last_real;
                                        }
                                            if !accept {
                                                // (C): body contains a
                                                // RETURN before its last
                                                // instruction and every
                                                // forward exit targets a
                                                // registered loop
                                                // exit/merge (`if method
                                                // in B.__dict__:` over a
                                                // body with `return
                                                // NotImplemented` + break
                                                // — _collections_abc 3.13
                                                // _check_methods). The
                                                // first scan's partial
                                                // state is discarded;
                                                // rescan fully.
                                                let mut ok4 = true;
                                                let mut lreal4 = None;
                                                let mut fret4 = None;
                                                for ins2 in
                                                    self.instrs[ti..bi].iter()
                                                {
                                                    if !is_pad(ins2) {
                                                        lreal4 =
                                                            Some(ins2.offset);
                                                    }
                                                    if matches!(
                                                        ins2.op,
                                                        Op::RETURN_VALUE
                                                            | Op::RETURN_CONST
                                                    ) && fret4.is_none()
                                                    {
                                                        fret4 =
                                                            Some(ins2.offset);
                                                    }
                                                    if let Some(t2) =
                                                        ins2.target
                                                    {
                                                        if ins2.is_backward {
                                                            if t2 == loop_top
                                                                && !matches!(
                                                                    ins2.op,
                                                                    Op::JUMP_BACKWARD
                                                                        | Op::JUMP_ABSOLUTE
                                                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                                )
                                                            {
                                                                ok4 = false;
                                                                break;
                                                            }
                                                        } else if t2 >= lb_end
                                                            && !self
                                                                .jump_is_loop_exit_or_merge(
                                                                    t2,
                                                                )
                                                        {
                                                            ok4 = false;
                                                            break;
                                                        }
                                                    }
                                                }
                                                accept = ok4
                                                    && fret4.is_some()
                                                    && lreal4.is_some()
                                                    && fret4 < lreal4;
                                            }
                                            if !accept {
                                                // (D): the body is a
                                                // bare sunk return stub
                                                // [POP_TOP/pads]
                                                // RETURN_CONST whose
                                                // constant does NOT
                                                // mirror the function's
                                                // tail return — a
                                                // genuine in-loop
                                                // `if cond: return K`
                                                // (_collections_abc
                                                // 3.13 Set.__le__ `if
                                                // elem not in other:
                                                // return False` before
                                                // a tail `return
                                                // True`). A mirroring
                                                // stub stays with the
                                                // sunk for-break fold.
                                                let mut ok5 = true;
                                                let mut k5 = ti;
                                                while k5 < bi
                                                    && (is_pad(
                                                        &self.instrs[k5],
                                                    ) || matches!(
                                                        self.instrs[k5].op,
                                                        Op::POP_TOP
                                                            | Op::POP_ITER
                                                    ))
                                                {
                                                    k5 += 1;
                                                }
                                                if self
                                                    .instrs
                                                    .get(k5)
                                                    .map_or(false, |x| {
                                                        x.op == Op::RETURN_CONST
                                                    })
                                                {
                                                    let n = self.instrs.len();
                                                    let tail_c = (n >= 1)
                                                        .then(|| {
                                                            &self.instrs[n - 1]
                                                        })
                                                        .filter(|x| {
                                                            x.op
                                                                == Op::RETURN_CONST
                                                        })
                                                        .map(|x| x.arg);
                                                    ok5 = tail_c
                                                        .map_or(true, |tc| {
                                                            tc != self.instrs[k5].arg
                                                        });
                                                    // an or-chain success
                                                    // block is targeted
                                                    // by several cond
                                                    // jumps — folding the
                                                    // first link alone
                                                    // tears the chain
                                                    // (ItemsView
                                                    // __contains__ `if v
                                                    // is value or
                                                    // v == value:`)
                                                    if ok5 {
                                                        let ntarget = self
                                                            .instrs
                                                            .iter()
                                                            .filter(|x| {
                                                                x.target
                                                                    == Some(
                                                                        target,
                                                                    )
                                                            })
                                                            .count();
                                                        ok5 = ntarget <= 1;
                                                    }
                                                    if ok5 {
                                                        accept = true;
                                                    }
                                                }
                                        }
                                        if accept {
                                            let direct =
                                                negate_cond(values[0].clone());
                                            return Some((
                                                direct,
                                                target,
                                                lb_end,
                                                loop_top,
                                            ));
                                        }
                                    }
                                }

                                // 3.12 plain threaded body (copyreg
                                // _slotnames `if "__slots__" in
                                // c.__dict__:` — the guard is the
                                // loop's last statement and the body
                                // runs to the loop's OWN back edge):
                                // direct nested If, mirroring the 3.13
                                // case (c) consumer. Tolerate the
                                // final back edge (the break_bears ok
                                // scan rejected it); require it to be
                                // the body's last meaningful
                                // instruction (a mid-body continue
                                // would be swallowed into the If)
                                if ret_idx.is_none()
                                    && self.version.at_least(3, 12)
                                    && !self.version.at_least(3, 13)
                                {
                                    let mut back_off = None;
                                    let mut last_real = None;
                                    let mut ok2 = true;
                                    for ins in self.instrs[ti..bi].iter() {
                                        if !is_pad(ins) {
                                            last_real = Some(ins.offset);
                                        }
                                        if let Some(t) = ins.target {
                                            if ins.is_backward {
                                                if t == loop_top
                                                    && matches!(
                                                        ins.op,
                                                        Op::JUMP_BACKWARD
                                                            | Op::JUMP_ABSOLUTE
                                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                    )
                                                {
                                                    back_off =
                                                        Some(ins.offset);
                                                }
                                            } else if t >= lb_end
                                                && !self
                                                    .jump_is_loop_exit_or_merge(
                                                        t,
                                                    )
                                            {
                                                ok2 = false;
                                                break;
                                            }
                                        }
                                    }
                                    if ok2
                                        && back_off.is_some()
                                        && back_off == last_real
                                    {
                                        let direct =
                                            negate_cond(values[0].clone());
                                        return Some((
                                            direct,
                                            target,
                                            lb_end,
                                            loop_top,
                                        ));
                                    }
                                }
                                // the return's value run must mirror the
                                // function's tail return run
                                if let (true, Some(ri)) = (ok, ret_idx) {
                                    let norm = |x: &crate::bytecode::Instruction| {
                                        (x.op as u8, x.arg)
                                    };
                                    let is_load = |o: Op| {
                                        matches!(
                                            o,
                                            Op::LOAD_FAST
                                                | Op::LOAD_NAME
                                                | Op::LOAD_GLOBAL
                                                | Op::LOAD_DEREF
                                                | Op::LOAD_CONST
                                                | Op::LOAD_ATTR
                                                | Op::LOAD_METHOD
                                        )
                                    };
                                    let ri_i = self
                                        .instrs
                                        .iter()
                                        .position(|x| std::ptr::eq(x, ri))
                                        .unwrap_or(0);
                                    let mut b2 = ri_i;
                                    let mut h2 = 0;
                                    while b2 > 0 && h2 < 8 {
                                        let p = &self.instrs[b2 - 1];
                                        if is_pad(p) || is_load(p.op) {
                                            b2 -= 1;
                                            h2 += 1;
                                            continue;
                                        }
                                        break;
                                    }
                                    let run_a: Vec<(u8, u32)> =
                                        self.instrs[b2..=ri_i]
                                            .iter()
                                            .filter(|x| !is_pad(x))
                                            .map(norm)
                                            .collect();
                                    let n = self.instrs.len();
                                    let mut run_f: Vec<(u8, u32)> =
                                        Vec::new();
                                    if n >= 2
                                        && matches!(
                                            self.instrs[n - 1].op,
                                            Op::RETURN_VALUE | Op::RETURN_CONST
                                        )
                                    {
                                        let mut fb = n - 1;
                                        let mut fh = 0;
                                        while fb > 0 && fh < 8 {
                                            let p = &self.instrs[fb - 1];
                                            if is_pad(p) || is_load(p.op) {
                                                fb -= 1;
                                                fh += 1;
                                                continue;
                                            }
                                            break;
                                        }
                                        run_f = self.instrs[fb..]
                                            .iter()
                                            .filter(|x| !is_pad(x))
                                            .map(norm)
                                            .collect();
                                    }
                                    if !run_a.is_empty() && run_f == run_a {
                                        let direct = negate_cond(
                                            values[0].clone(),
                                        );
                                        return Some((
                                            direct,
                                            target,
                                            lb_end,
                                            loop_top,
                                        ));
                                    }
                                }
                            }
                        }
                    }
                    let merged = self.merge_guard_values(std::mem::take(&mut values));
                    return Some((merged, next, tramp_off, loop_top));
                }
                body_start = next;
                break;
            }
            // the guard's fall-through must be the continue trampoline
            // (NOT_TAKEN padding then the back jump; 3.13+ dropped the
            // padding — the back jump is directly adjacent)
            if !matches!(self.instrs.get(jk + 1).map(|x| x.op), Some(Op::NOT_TAKEN))
                && !self.version.at_least(3, 13)
            {
return None;
            }
            let mut ft = jk + 1;
            while matches!(self.instrs.get(ft).map(|x| x.op), Some(Op::NOT_TAKEN) | Some(Op::NOP)) {
                ft += 1;
            }
            let ftramp = self.instrs.get(ft)?;
            if !ftramp.is_backward
                || ftramp.target != Some(loop_top)
                || !matches!(
                    ftramp.op,
                    Op::JUMP_BACKWARD | Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
            {
                // no trampoline: this jump heads to the body
                body_start = self.instrs[jk].target?;
                // the operand region belongs to the body, not a guard —
                // only accept when nothing was consumed as an operand
                if jk != region_start {
return None;
                }
                break;
            }
            let operand = match self.sim_value_region(region_start, jk) {
                            Some(o) => o,
                            None => {
return None;
                            }
                        };
            let jins = &self.instrs[jk];
            let jt = matches!(
                jins.op,
                Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
            );
            // the chain advances through this jump: PJIT -> operand true
            // continues the chain (positive); PJIF -> negated
            values.push(if jt {
                operand
            } else {
                Rc::new(Expr::Unary { op: UnaryOp::Not, operand })
            });
            next = jins.target?;
        }
        if values.is_empty() {
return None;
        }
        // the body ends at its back edge to the loop top (or a break)
        let Some(&bi) = self.idx_of.get(&body_start) else {
return None;
        };
        let mut body_end = None;
        for ins in self.instrs[bi..].iter() {
            if ins.offset >= body_start {
                if let Some(t) = ins.target {
                    if ins.is_backward
                        && t == loop_top
                        && matches!(
                            ins.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                    {
                        body_end = Some(ins.offset);
                        break;
                    }
                    // terminal break chunk: the body IS [POP_TOP...] +
                    // a forward jump past the loop exit — scanning past
                    // it never finds the loop's back edge (copyreg 3.13
                    // _reduce_ex: `if A and B: break` over a for-else,
                    // the break chunk is followed by END_FOR + the else
                    // region). Bound the body at the break jump
                    if !ins.is_backward
                        && matches!(
                            ins.op,
                            Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                        )
                        && self.jump_is_loop_exit_or_merge(t)
                        && self.instrs[bi..]
                            .iter()
                            .take_while(|x| x.offset < ins.offset)
                            .all(|x| {
                                matches!(
                                    x.op,
                                    Op::POP_TOP
                                        | Op::NOP
                                        | Op::NOT_TAKEN
                                        | Op::CACHE
                                )
                            })
                    {
                        body_end = Some(ins.end());
                        break;
                    }
                    // a break jump out of the loop lives inside the body;
                    // the body ends at the following back edge
                    let leaves = self
                        .blocks
                        .iter()
                        .rev()
                        .find(|b| {
                            matches!(b.kind, BlockType::While | BlockType::For)
                                && (b.start == loop_top
                                    || (b.cond_end != usize::MAX && b.cond_end == loop_top))
                        })
                        .map_or(false, |b| {
                            !ins.is_backward
                                && self
                                    .loop_exit_offset(b)
                                    .map_or(false, |le| {
                                        self.effective_offset(t) == self.effective_offset(le)
                                    })
                        });
                    if leaves {
                        continue;
                    }
                    // any other jump target inside the body is fine, but a
                    // forward jump past the loop means a break to a merged
                    // exit we cannot bound — bail
                    if !ins.is_backward {
                        let inside = self
                            .blocks
                            .iter()
                            .rev()
                            .find(|b| {
                                matches!(b.kind, BlockType::While | BlockType::For)
                                    && (b.start == loop_top
                                        || (b.cond_end != usize::MAX
                                            && b.cond_end == loop_top))
                            })
                            .map_or(false, |b| t < b.end);
                        if !inside {
return None;
                        }
                    }
                }
            }
        }
        let body_end = match body_end {
            Some(b) => b,
            None => {
return None;
            }
        };
        if body_end <= body_start {
return None;
        }
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values,
        });
        Some((merged as ExprRef, body_start, body_end, loop_top))
    }

    /// Recognize a value-position `A and B or C` chain. CPython (3.x)
    /// compiles the merged boolop — whose first operand is an `and` — to:
    ///   LOAD A; POP_JUMP_IF_FALSE T; <B region>; JUMP_IF_TRUE_OR_POP M;
    ///   T: <C region>; M: <consumer>
    /// The `and`'s PJIF target T is exactly the `or`'s second-operand start,
    /// so the whole thing is one value `Or(And(A, B), C)`. The plain PJIF
    /// path instead opens a control-flow `if A: pass` and drops A from the
    /// value (ast 3.6 _format `rv += fields and ', ' or ' '` rendered as
    /// `if fields: pass` + `rv += ', ' or ' '`). Returns the merged value and
    /// the merge offset M to skip to; None when the shape doesn't hold or a
    /// region carries statements (the caller restores and falls through).
    /// 3.12+ value-position ternary whose arms TERMINATE with duplicated
    /// tails (no merge point): each arm runs [slot value; identical tail
    /// ops; RETURN]. Simulate both arms over the shared preloaded base
    /// stack; when the op traces share a prefix and suffix around exactly
    /// one differing stack slot, rebuild the single expression with the
    /// ternary folded into that slot. Returns the merged expression and
    /// arms `dup_tail_ternary_skip` (walk resumes past the else arm).
        /// 3.12+ value-position ternary whose arms TERMINATE with duplicated
    /// tails (no merge point): each arm runs [slot value ops; identical
    /// tail ops; RETURN]. Simulate both arms over the shared preloaded
    /// base stack; when the op traces share a common prefix and suffix
    /// around one differing middle (the slot), rebuild the single
    /// expression with the ternary folded into that slot. Returns the
    /// merged expression and arms `dup_tail_ternary_skip` (the walk
    /// resumes past the else arm's RETURN).
    fn try_dup_tail_ternary(
        &mut self,
        cond: ExprRef,
        jump_if_true: bool,
        target: usize,
    ) -> Option<ExprRef> {
        self.dup_tail_ternary_skip = None;
        // the live stack at entry is the full preload the arms consume
        // (cond already popped by the PJIF handler) — record its length so
        // the cleanup below drains ALL of it (base_depth counts ExprRefs
        // and drops the Null callable markers, under-popping the live
        // stack and stranding the callable as a stray statement)
        let stack_len_at_entry = self.stack.len();
        let ci = *self.idx_of.get(&self.cur_offset)?;
        let ti = *self.idx_of.get(&target)?;
        if ti <= ci + 1 {
            return None;
        }
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(
                x.op,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG
            )
        };
        // then arm: [ci+1, ti) ending in its own RETURN, no inner jumps
        let mut ret_t = None;
        for k in ci + 1..ti {
            let x = &self.instrs[k];
            if x.target.is_some() {
                return None;
            }
            if matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                ret_t = Some(k);
                break;
            }
        }
        let rt = ret_t?;
        if self.instrs[rt].offset >= target {
            return None;
        }
        // else arm: [ti, ret_e], no inner jumps, ends at the first RETURN
        let mut ret_e = None;
        let mut k = ti;
        while k < self.instrs.len() {
            let x = &self.instrs[k];
            if x.target.is_some() {
                return None;
            }
            if matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                ret_e = Some(k);
                break;
            }
            k += 1;
        }
        let re = ret_e?;
        // common preload region before the cond jump (the 3.13 value
        // boolop idiom interposes TO_BOOL between the operand and the
        // jump — walk through it)
        let mut rs = ci;
        while rs > 0 {
            let p = &self.instrs[rs - 1];
            if is_pad(p) || is_pure_value_op(p.op) || p.op == Op::TO_BOOL {
                rs -= 1;
            } else {
                break;
            }
        }
        // a non-empty preload is REQUIRED: an `if C: return A` + `return
        // B` pair has the identical two-terminated-arms shape, and
        // folding it to a ternary recompiles differently (cabc 3.12/3.13
        // __subclasshook__ flipped from PASS). The dup-tail ternary is
        // only forced when arms consume values preloaded BEFORE the cond
        if rs == ci {
            return None;
        }
        // op traces (pads filtered; RETURN excluded)
        let trace = |a: usize, b: usize| -> Vec<(u8, u32)> {
            self.instrs[a..b]
                .iter()
                .filter(|x| !is_pad(x))
                .map(|x| (x.op as u8, x.arg))
                .collect()
        };
        let tt = trace(ci + 1, rt);
        let et = trace(ti, re);
        if tt.is_empty() || et.is_empty() {
            return None;
        }
        // common prefix
        let minlen = tt.len().min(et.len());
        let mut d = 0;
        while d < minlen && tt[d] == et[d] {
            d += 1;
        }
        // common suffix (not overlapping the prefix)
        let mut sfx = 0;
        while sfx < minlen - d
            && tt[tt.len() - 1 - sfx] == et[et.len() - 1 - sfx]
        {
            sfx += 1;
        }
        let t_mid_end = tt.len() - sfx;
        let e_mid_end = et.len() - sfx;
        if d >= t_mid_end || d >= e_mid_end {
            return None;
        }
        // physical index just PAST the middle's last op in each arm
        let phys_past = |a: usize, b: usize, last_tpos: usize| -> Option<usize> {
            let mut c = 0usize;
            for k2 in a..b {
                if !is_pad(&self.instrs[k2]) {
                    if c == last_tpos {
                        return Some(k2 + 1);
                    }
                    c += 1;
                }
            }
            None
        };
        let mt = phys_past(ci + 1, rt, t_mid_end - 1)?;
        let me = phys_past(ti, re, e_mid_end - 1)?;
        // the middles must leave the same net stack depth
        let depth = |a: usize, b: usize| -> Option<i32> {
            let mut acc = self.sim_stack_region(a, b, Vec::new())?;
            Some(acc.len() as i32)
        };
        let dt_d = depth(ci + 1, mt)?;
        let de_d = depth(ti, me)?;
        if dt_d != de_d || dt_d < 1 {
            return None;
        }
        // Use the LIVE simulation stack as the base, not a re-simulation of
        // the preload region. The preload walk above stops at any non-pure
        // op, so for a NESTED dup-tail ternary (annotationlib 3.14
        // __hash__ `hash((a, b, id(c), d, <ternary4>, e, <ternary6>))`) it
        // halts at the inner ternary's arm jump/call and the re-simulated
        // base loses the outer operands (hash/a/inner-value) that the real
        // walk already stacked. The PJIF handler popped the cond before
        // calling, so the live stack IS exactly the base the arms consume
        // (Null callable markers are dropped — sim_stack_region models
        // values only).
        let base: Vec<ExprRef> = self
            .stack
            .iter()
            .filter_map(|sv| match sv {
                Sv::E(e) => Some(e.clone()),
                _ => None,
            })
            .collect();
        // the preload (values under the cond) must be NON-EMPTY: with an
        // empty base this is the plain `if C: return A` + `return B`
        // shape, whose ternary rendering recompiles differently (cabc
        // 3.12/3.13 __subclasshook__ flipped from PASS). The dup-tail
        // ternary is only forced when the arms consume preloaded values
        if base.is_empty() {
            return None;
        }
        let st_t = self.sim_stack_region(ci + 1, mt, base.clone())?;
        let st_e = self.sim_stack_region(ti, me, base.clone())?;
        if st_t.len() != st_e.len() || st_t.is_empty() {
            return None;
        }
        let slot_t = st_t.last()?.clone();
        let slot_e = st_e.last()?.clone();
        // compare the UNDER-stack only — the tops are the slot values
        for (a2, b2) in st_t[..st_t.len() - 1]
            .iter()
            .zip(st_e[..st_e.len() - 1].iter())
        {
            if !expr_eq(a2, b2) {
                return None;
            }
        }
        // full-arm return expressions (continue the sim through the tails)
        let full_t = self.sim_stack_region(mt, rt + 1, st_t)?;
        let full_e = self.sim_stack_region(me, re + 1, st_e)?;
        if full_t.len() != 1 || full_e.len() != 1 {
            return None;
        }
        let expr_t = full_t[0].clone();
        let expr_e = full_e[0].clone();
        let tern: ExprRef = Rc::new(Expr::Ternary {
            cond,
            then_expr: slot_t,
            else_expr: slot_e,
        });
        let merged = Self::ternary_merge_slot(&expr_t, &expr_e, &tern)?;
        let _ = jump_if_true;
        // the preloaded base operands were executed by the real walk and
        // sit under the popped cond — the simulated arms consumed them.
        // Drain the FULL live preload (stack_len_at_entry), not base_depth:
        // base_depth counts ExprRefs and drops the Null callable markers,
        // so popping only base_depth strands the callable (`hash`) as a
        // stray post-return statement (annotationlib 3.14 __hash__).
        for _ in 0..stack_len_at_entry {
            self.stack.pop();
        }
        self.dup_tail_ternary_skip = Some(self.instrs[re].end());
        Some(merged)
    }

/// Structural single-slot merge: a and b must be identical except for
    /// exactly one leaf position, which becomes the ternary `t`.
    fn ternary_merge_slot(a: &ExprRef, b: &ExprRef, t: &ExprRef) -> Option<ExprRef> {
        if expr_eq(a, b) {
            return None;
        }
        macro_rules! try_children {
            ($mk:expr, $($child:expr),+ $(,)?) => {{
                let children: Vec<(&ExprRef, &ExprRef)> = vec![$(($child.0, $child.1)),+];
                let mut merged_idx: Option<usize> = None;
                let mut merged_val: Option<ExprRef> = None;
                for (i, (ca, cb)) in children.iter().enumerate() {
                    if expr_eq(ca, cb) {
                        continue;
                    }
                    if merged_idx.is_some() {
                        return None;
                    }
                    match Self::ternary_merge_slot(ca, cb, t) {
                        Some(m) => {
                            merged_idx = Some(i);
                            merged_val = Some(m);
                        }
                        None => {
                            merged_idx = Some(i);
                            merged_val = Some(t.clone());
                        }
                    }
                }
                if merged_idx.is_none() {
                    return None;
                }
                let idx = merged_idx.unwrap();
                let val = merged_val.unwrap();
                let mut reps: Vec<ExprRef> = children.iter().map(|(ca, _)| (*ca).clone()).collect();
                reps[idx] = val;
                Some($mk(reps))
            }};
        }
        match (&**a, &**b) {
            (Expr::Attribute { value: va, attr: aa }, Expr::Attribute { value: vb, attr: ab }) if aa == ab => {
                try_children!(|r: Vec<ExprRef>| Rc::new(Expr::Attribute { value: r[0].clone(), attr: aa.clone() }), (va, vb),)
            }
            (
                Expr::Subscript { value: va, index: ia },
                Expr::Subscript { value: vb, index: ib },
            ) => {
                try_children!(|r: Vec<ExprRef>| Rc::new(Expr::Subscript { value: r[0].clone(), index: r[1].clone() }), (va, vb), (ia, ib),)
            }
            (Expr::Slice(sa), Expr::Slice(sb)) => {
                {
                    {
                        let kids_a: Vec<Option<ExprRef>> = vec![sa.start.clone(), sa.stop.clone(), sa.step.clone()];
                        let kids_b: Vec<Option<ExprRef>> = vec![sb.start.clone(), sb.stop.clone(), sb.step.clone()];
                        let mut merged_idx: Option<usize> = None;
                        let mut merged_val: Option<ExprRef> = None;
                        for i in 0..3 {
                            match (&kids_a[i], &kids_b[i]) {
                                (None, None) => continue,
                                (Some(x), Some(y)) if expr_eq(x, y) => continue,
                                (Some(x), Some(y)) => {
                                    if merged_idx.is_some() { return None; }
                                    merged_val = Self::ternary_merge_slot(x, y, t).or_else(|| Some(t.clone()));
                                    merged_idx = Some(i);
                                }
                                (None, Some(_)) | (Some(_), None) => {
                                    if merged_idx.is_some() { return None; }
                                    merged_val = Some(t.clone());
                                    merged_idx = Some(i);
                                }
                            }
                        }
                        let idx = merged_idx?;
                        let val = merged_val?;
                        let mut ka = kids_a.clone();
                        ka[idx] = Some(val);
                        Some(Rc::new(Expr::Slice(Box::new(SliceExpr {
                            start: ka[0].clone(),
                            stop: ka[1].clone(),
                            step: ka[2].clone(),
                        }))))
                    }
                }
            }
            (
                Expr::Call { func: fa, args: aa, keywords: ka, star_args: sa, star_kwargs: ska },
                Expr::Call { func: fb, args: ab, keywords: kb, star_args: sb, star_kwargs: skb },
            ) if ka.is_empty() && kb.is_empty() && sa.is_none() && sb.is_none() && ska.is_none() && skb.is_none() && aa.len() == ab.len() => {
                let mut slots: Vec<(&ExprRef, &ExprRef)> = vec![(fa, fb)];
                for (x, y) in aa.iter().zip(ab.iter()) {
                    slots.push((x, y));
                }
                let mut merged_idx: Option<usize> = None;
                let mut merged_val: Option<ExprRef> = None;
                for (i, (x, y)) in slots.iter().enumerate() {
                    if expr_eq(x, y) {
                        continue;
                    }
                    if merged_idx.is_some() {
                        return None;
                    }
                    merged_val = Self::ternary_merge_slot(x, y, t).or_else(|| Some(t.clone()));
                    merged_idx = Some(i);
                }
                let idx = merged_idx?;
                let val = merged_val?;
                let mut reps: Vec<ExprRef> = slots.iter().map(|(x, _)| (*x).clone()).collect();
                reps[idx] = val;
                Some(Rc::new(Expr::Call {
                    func: reps[0].clone(),
                    args: reps[1..].to_vec(),
                    keywords: Vec::new(),
                    star_args: None,
                    star_kwargs: None,
                }))
            }
            (Expr::Binary { op: o1, left: l1, right: r1 }, Expr::Binary { op: o2, left: l2, right: r2 }) if o1 == o2 => {
                try_children!(|r: Vec<ExprRef>| Rc::new(Expr::Binary { op: *o1, left: r[0].clone(), right: r[1].clone() }), (l1, l2), (r1, r2),)
            }
            (Expr::Unary { op: o1, operand: x1 }, Expr::Unary { op: o2, operand: x2 }) if o1 == o2 => {
                try_children!(|r: Vec<ExprRef>| Rc::new(Expr::Unary { op: *o1, operand: r[0].clone() }), (x1, x2),)
            }
            // Tuple/List/Set: the differing slot may be ONE element of a
            // container (annotationlib 3.14 __hash__ `return hash((a, b,
            // id(c), tuple(sorted(..)) if .. else None))` — the ternary is
            // the LAST tuple element; without this arm the catch-all
            // replaced the WHOLE tuple with the ternary, dropping a/b/c).
            // Recurse per element and merge at the single differing one.
            (Expr::Tuple(ea), Expr::Tuple(eb)) if ea.len() == eb.len() => {
                Self::merge_vec_slot(ea, eb, t).map(|v| Rc::new(Expr::Tuple(v)))
            }
            (Expr::List(ea), Expr::List(eb)) if ea.len() == eb.len() => {
                Self::merge_vec_slot(ea, eb, t).map(|v| Rc::new(Expr::List(v)))
            }
            (Expr::Set(ea), Expr::Set(eb)) if ea.len() == eb.len() => {
                Self::merge_vec_slot(ea, eb, t).map(|v| Rc::new(Expr::Set(v)))
            }
            _ => Some(t.clone()),
        }
    }

    /// Merge two equal-length element vectors that differ in exactly ONE
    /// position: recurse at that position (falling back to the bare
    /// ternary `t` for a leaf difference) and return the rebuilt vector.
    fn merge_vec_slot(
        ea: &[ExprRef],
        eb: &[ExprRef],
        t: &ExprRef,
    ) -> Option<Vec<ExprRef>> {
        let mut merged_idx: Option<usize> = None;
        let mut merged_val: Option<ExprRef> = None;
        for (i, (x, y)) in ea.iter().zip(eb.iter()).enumerate() {
            if expr_eq(x, y) {
                continue;
            }
            if merged_idx.is_some() {
                return None;
            }
            merged_val = Self::ternary_merge_slot(x, y, t).or_else(|| Some(t.clone()));
            merged_idx = Some(i);
        }
        let idx = merged_idx?;
        let val = merged_val?;
        let mut reps: Vec<ExprRef> = ea.to_vec();
        reps[idx] = val;
        Some(reps)
    }

    /// Simulate [a, b) over an initial stack, returning the full final
    /// stack. Restricted value-op set; bails (None) on anything else.
    fn sim_stack_region(
        &self,
        a: usize,
        b: usize,
        init: Vec<ExprRef>,
    ) -> Option<Vec<ExprRef>> {
        let mut st: Vec<ExprRef> = init;
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(
                x.op,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG
            )
        };
        let pop1 = |st: &mut Vec<ExprRef>| st.pop().unwrap_or_else(|| self.name_expr("???"));
        for k in a..b.min(self.instrs.len()) {
            let ins = &self.instrs[k];
            if is_pad(ins) {
                continue;
            }
            let arg = ins.arg as usize;
            match ins.op {
                Op::LOAD_FAST | Op::LOAD_FAST_CHECK | Op::LOAD_FAST_BORROW => {
                    st.push(self.name_expr(self.local_name(arg)));
                }
                Op::LOAD_FAST_LOAD_FAST | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => {
                    st.push(self.name_expr(self.local_name((arg >> 4) & 0xF)));
                    st.push(self.name_expr(self.local_name(arg & 0xF)));
                }
                Op::LOAD_NAME => {
                    st.push(self.name_expr(self.const_name(arg)));
                }
                Op::LOAD_GLOBAL => {
                    let idx = if self.version.at_least(3, 11) { arg >> 1 } else { arg };
                    st.push(self.name_expr(self.const_name(idx)));
                }
                Op::LOAD_DEREF => {
                    st.push(self.name_expr(
                        self.code.deref_name(arg).unwrap_or("???").to_string(),
                    ));
                }
                Op::LOAD_SMALL_INT => {
                    st.push(Rc::new(Expr::Const(Rc::new(PyObject::Int(ins.arg as i32)))));
                }
                Op::LOAD_CONST => {
                    st.push(Rc::new(Expr::Const(
                        self.code.consts.get(arg).cloned().unwrap_or_else(|| Rc::new(PyObject::None)),
                    )));
                }
                Op::LOAD_COMMON_CONSTANT => {
                    st.push(self.name_expr(format!("<const{}>", ins.arg)));
                }
                Op::PUSH_NULL => {
                    st.push(self.name_expr("\u{0}null"));
                }
                Op::LOAD_ATTR | Op::LOAD_METHOD => {
                    let v = pop1(&mut st);
                    let idx = if ins.op == Op::LOAD_ATTR && self.version.at_least(3, 12) {
                        (arg >> 1) & 0x3FFFFFFF
                    } else {
                        arg
                    };
                    let a2 = self.const_name(idx);
                    st.push(Rc::new(Expr::Attribute { value: v, attr: a2 }));
                    if ins.op == Op::LOAD_ATTR
                        && self.version.at_least(3, 12)
                        && arg & 1 != 0
                    {
                        st.push(self.name_expr("\u{0}null"));
                    }
                    if ins.op == Op::LOAD_METHOD {
                        st.push(self.name_expr("\u{0}null"));
                    }
                }
                Op::PRECALL | Op::TO_BOOL => {}
                Op::KW_NAMES => {
                    return None;
                }
                Op::CALL | Op::CALL_FUNCTION | Op::CALL_METHOD => {
                    let n = if ins.op == Op::CALL_FUNCTION && !self.version.at_least(3, 6) {
                        arg & 0xFF
                    } else {
                        arg
                    };
                    let mut args = Vec::new();
                    for _ in 0..n {
                        args.push(pop1(&mut st));
                    }
                    args.reverse();
                    let mut callable = pop1(&mut st);
                    let is_null = |e: &ExprRef| {
                        matches!(&**e, Expr::Name(s) if s == "\u{0}null")
                    };
                    if st.last().map_or(false, is_null) {
                        st.pop();
                    }
                    if is_null(&callable) {
                        callable = pop1(&mut st);
                    }
                    // LOAD_METHOD-style: the null marker sits BELOW the
                    // callable in 3.11-3.13 and above in 3.14
                    if st.last().map_or(false, is_null) {
                        st.pop();
                    }
                    st.push(Rc::new(Expr::Call {
                        func: callable,
                        args,
                        keywords: Vec::new(),
                        star_args: None,
                        star_kwargs: None,
                    }));
                }
                Op::BINARY_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    match binary_op_name(arg as u32, self.version) {
                        Some(name) => {
                            if name.ends_with('=') {
                                return None;
                            }
                            let op = binop_from_text(name);
                            st.push(Rc::new(Expr::Binary { op, left: l, right: r }));
                        }
                        None if self.version.at_least(3, 14) => {
                            let idx = normalize_slice_call(r);
                            st.push(Rc::new(Expr::Subscript { value: l, index: idx }));
                        }
                        None => return None,
                    }
                }
                Op::BINARY_SUBSCR => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    st.push(Rc::new(Expr::Subscript { value: l, index: r }));
                }
                Op::BINARY_SLICE => {
                    let stop = pop1(&mut st);
                    let start = pop1(&mut st);
                    let obj = pop1(&mut st);
                    st.push(Rc::new(Expr::Subscript {
                        value: obj,
                        index: Rc::new(Expr::Slice(Box::new(SliceExpr {
                            start: none_if_const_none(start),
                            stop: none_if_const_none(stop),
                            step: None,
                        }))),
                    }));
                }
                Op::COMPARE_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = cmp_from_index(compare_op_index(arg as u32, self.version));
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::IS_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = if ins.arg == 1 { CmpOp::IsNot } else { CmpOp::Is };
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::CONTAINS_OP => {
                    let r = pop1(&mut st);
                    let l = pop1(&mut st);
                    let op = if ins.arg == 1 { CmpOp::NotIn } else { CmpOp::In };
                    st.push(Rc::new(Expr::Compare {
                        operands: vec![l, r],
                        ops: vec![op],
                    }));
                }
                Op::UNARY_NOT => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Not, operand: v }));
                }
                Op::UNARY_NEGATIVE => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Neg, operand: v }));
                }
                Op::UNARY_INVERT => {
                    let v = pop1(&mut st);
                    st.push(Rc::new(Expr::Unary { op: UnaryOp::Invert, operand: v }));
                }
                Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => {
                    let n = arg;
                    if st.len() < n {
                        return None;
                    }
                    let split = st.len() - n;
                    let items: Vec<ExprRef> = st.split_off(split);
                    let e = match ins.op {
                        Op::BUILD_TUPLE => Expr::Tuple(items),
                        Op::BUILD_LIST => Expr::List(items),
                        _ => Expr::Set(items),
                    };
                    st.push(Rc::new(e));
                }
                Op::RETURN_CONST => {
                    st.push(Rc::new(Expr::Const(
                        self.code.consts.get(arg).cloned().unwrap_or_else(|| Rc::new(PyObject::None)),
                    )));
                }
                Op::RETURN_VALUE => {}
                _ => return None,
            }
        }
        Some(st)
    }

    /// Rough stack effect of a value op (None when unknown).
    fn stack_effect_est(&self, op: Op, arg: u32) -> Option<i32> {
        let a = arg as usize;
        let e = match op {
            Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG | Op::PRECALL
            | Op::TO_BOOL => 0,
            Op::LOAD_FAST
            | Op::LOAD_FAST_CHECK
            | Op::LOAD_FAST_BORROW
            | Op::LOAD_NAME
            | Op::LOAD_GLOBAL
            | Op::LOAD_DEREF
            | Op::LOAD_CONST
            | Op::LOAD_SMALL_INT
            | Op::LOAD_COMMON_CONSTANT
            | Op::PUSH_NULL
            | Op::LOAD_ASSERTION_ERROR => 1,
            Op::LOAD_FAST_LOAD_FAST | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => 2,
            Op::LOAD_ATTR => {
                if self.version.at_least(3, 12) && arg & 1 != 0 {
                    1
                } else {
                    0
                }
            }
            Op::LOAD_METHOD => 1,
            Op::CALL | Op::CALL_METHOD => -(a as i32),
            Op::CALL_FUNCTION => {
                if self.version.at_least(3, 6) {
                    -(a as i32)
                } else {
                    -((a & 0xFF) as i32)
                }
            }
            Op::BINARY_OP
            | Op::BINARY_SUBSCR
            | Op::COMPARE_OP
            | Op::IS_OP
            | Op::CONTAINS_OP => -1,
            Op::BINARY_SLICE => -2,
            Op::UNARY_NOT | Op::UNARY_NEGATIVE | Op::UNARY_INVERT | Op::RETURN_CONST => 0,
            Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => 1 - a as i32,
            Op::RETURN_VALUE => 0,
            _ => return None,
        };
        Some(e)
    }

    fn try_and_or_value_chain(
        &mut self,
        cond: ExprRef,
        target: usize,
    ) -> Option<(ExprRef, usize)> {
        let b_start = self.cur_next;
        if target <= b_start {
            return None;
        }
        let bi = *self.idx_of.get(&b_start)?;
        let ti = *self.idx_of.get(&target)?;
        if ti <= bi {
            return None;
        }
        // Walk the and-chain in [b_start, target). CPython compiles
        // `A1 and A2 and ... and An or C` so that every and-operand's
        // short-circuit PJIF lands on the or's second operand (target T),
        // and the LAST and-operand feeds the or's JTPOP -> merge M:
        //   <A1>; PJIF T; <A2>; PJIF T; ...; <An>; JTPOP M; T: <C>; M:
        // Collect each operand's value span; bail if the shape deviates
        // (a cond jump not targeting T, or no terminating JTPOP).
        let mut spans: Vec<(usize, usize)> = Vec::new();
        let mut j = None;
        let mut k = bi;
        let mut seg = b_start;
        while k < ti {
            let off = self.instrs[k].offset;
            match self.instrs[k].op {
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_BACKWARD_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_TRUE => {
                    // intermediate and-operand short-circuit: must target T
                    if self.instrs[k].target != Some(target) {
                        return None;
                    }
                    spans.push((seg, off));
                    seg = self.instrs[k].end();
                }
                Op::JUMP_IF_TRUE_OR_POP => {
                    // last and-operand feeds the or
                    spans.push((seg, off));
                    j = Some(k);
                    break;
                }
                _ => {}
            }
            k += 1;
        }
        let j = j?;
        if spans.is_empty() {
            return None;
        }
        let m = self.instrs[j].target?;
        let mi = *self.idx_of.get(&m)?;
        // the or's second-operand region [T, M) must be non-empty
        if mi <= ti {
            return None;
        }
        // no jump inside [T, M) may land back in the and-chain region, and
        // no instruction strictly inside the C region may be a jump target
        // (the entry T and the merge M are legitimately targeted by the
        // boolop's own PJIF/JTPOP; a label inside means shared control flow)
        for kk in ti..mi {
            if let Some(t) = self.instrs[kk].target {
                if t >= b_start && t < target {
                    return None;
                }
            }
            if kk > ti && self.targets.contains(&self.instrs[kk].offset) {
                return None;
            }
        }
        // speculative: snapshot mutable walk state so an abandoned match
        // (a region carrying statements) restores cleanly
        let blocks = self.blocks.clone();
        let stack = self.stack.clone();
        let skip = self.skip_until;
        let pend = self.pending_stores.clone();
        // evaluate each and-operand value span; all must be statement-free
        let mut and_vals: Vec<ExprRef> = Vec::new();
        let mut ok = true;
        for &(s, e) in &spans {
            if s >= e {
                ok = false;
                break;
            }
            self.region_result_expr = None;
            let stmts = self.decompile_region(s, e);
            let val = self.region_result_expr.take();
            if !stmts.is_empty() {
                ok = false;
                break;
            }
            match val {
                Some(v) => and_vals.push(v),
                None => {
                    ok = false;
                    break;
                }
            }
        }
        if !ok {
            self.blocks = blocks;
            self.stack = stack;
            self.skip_until = skip;
            self.pending_stores = pend;
            return None;
        }
        // C region [target, m) -> value C (statement-free)
        self.region_result_expr = None;
        let c_stmts = self.decompile_region(target, m);
        let c_val = self.region_result_expr.take();
        if !c_stmts.is_empty() || c_val.is_none() {
            self.blocks = blocks;
            self.stack = stack;
            self.skip_until = skip;
            self.pending_stores = pend;
            return None;
        }
        let c = c_val.unwrap();
        // build And(cond, operand-spans...) then Or(and, C), flattening
        // same-kind nested boolops so `A and B and C or D` stays flat
        let mut and_flat: Vec<ExprRef> = Vec::new();
        flatten_boolop(cond, BoolOpKind::And, &mut and_flat);
        for v in and_vals {
            flatten_boolop(v, BoolOpKind::And, &mut and_flat);
        }
        let and = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values: and_flat,
        });
        let mut or_vals = Vec::new();
        flatten_boolop(and as ExprRef, BoolOpKind::Or, &mut or_vals);
        flatten_boolop(c, BoolOpKind::Or, &mut or_vals);
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values: or_vals,
        });
        Some((merged, m))
    }

    /// Statement-level `A or (B and C ...)` if-condition (<=3.7). Compiles:
    ///   <A>; PJIT body; <B>; PJIF skip; <C>; PJIF skip; ...; body; skip:
    /// The first operand's PJIT jumps straight to the body; the remaining
    /// operands form an and-chain whose false-jumps all land on `skip`. The
    /// plain PJIT path opens `if not A:` and nests the and-chain, inverting
    /// the or (`if not a: if b and c:` == `not a and b and c`, which skips
    /// the body when A is true). Detect the shape, extract the and-chain via
    /// merge_forward_cond_chain, and open the if at the body with the merged
    /// `A or (and-chain)` condition. Returns body_start (the skip target).
    fn try_or_and_chain(&mut self, cond: ExprRef, body_start: usize) -> Option<usize> {
        if body_start <= self.cur_next {
            return None;
        }
        let bi = *self.idx_of.get(&self.cur_next)?;
        let body_i = *self.idx_of.get(&body_start)?;
        if body_i <= bi {
            return None;
        }
        // enclosing loop top: the and-chain's false jumps may fuse the
        // body-skip and the loop continue into ONE backward jump to it
        // (`if A or (B and C): <last stmt of loop>`, configparser 3.6
        // _read comment scan). skip is then the loop top (< body_start).
        let loop_top = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map(|b| b.start);
        // the gap [cur_next, body_start) must be a pure and-chain: at least
        // one PJIF, every cond jump targeting the SAME `skip` label -- either
        // a forward label past body_start (clean if-end) or the loop top
        // (fused continue). A PJIT in the gap means a nested or - bail.
        let mut skip = None;
        let mut saw_pjif = false;
        for k in bi..body_i {
            let ins = self.instrs[k];
            match ins.op {
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE => {
                    let t = ins.target?;
                    if t != body_start && t < body_start && loop_top != Some(t) {
                        return None;
                    }
                    if t == body_start {
                        return None;
                    }
                    match skip {
                        None => {
                            skip = Some(t);
                            saw_pjif = true;
                        }
                        Some(s) if s == t => {}
                        _ => return None,
                    }
                }
                Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_FALSE => return None,
                _ => {}
            }
        }
        if !saw_pjif {
            return None;
        }
        let skip = skip?;
        let fused = skip < body_start; // skip == loop_top
        if fused && loop_top != Some(skip) {
            return None;
        }
        // 3.12+ idiom guard: genuine links are PJIFs to the shared skip.
        // The 3.12+ compiler instead emits pass-forward PJIT links each
        // followed by a JUMP_BACKWARD trampoline; when that idiom shows
        // up here this is the `A or (B and C)` guard-chain shape that
        // try_or_group_chain_312 handles -- do not fold it with the
        // PJIF-era assumptions (t_orac 3.12: the fold ejected the body).
        if self.version.at_least(3, 12) {
            let mut k = bi;
            while k < body_i {
                let ins = self.instrs[k];
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                ) && ins.target.map_or(false, |t| t > ins.offset)
                {
                    return None;
                }
                k += 1;
            }
        }
        // extract the and-chain operands (each PJIF targets skip);
        // merge_forward_cond_chain / sim_value_region are read-only sims
        let ci = *self.idx_of.get(&self.cur_offset)?;
        let chain = self.merge_forward_cond_chain(ci, skip)?;
        // require a GENUINE multi-operand and-chain (`B and C`). A single
        // operand means plain `A or B`, which the or-merge later in
        // handle_cond_jump already handles correctly -- and crucially its
        // fused path decompiles the body as a region and SKIPS the loop back
        // edge, whereas opening an If block here would let that back edge
        // emit a spurious trailing `continue` (asyncore 2.7/3.3 poll).
        let chain_is_and = matches!(
            &*chain,
            Expr::BoolOp { op: BoolOpKind::And, values } if values.len() >= 2
        );
        // 3.12+ admits the PLAIN `A or B` single-operand chain too when
        // the skip is a clean forward label INSIDE the enclosing loop:
        // the historical or-merge for this shape is py2/<=3.7-gated, and
        // on 3.13 the nested fallback renders polarity-inverted guards
        // (`if v is not value: if not v == value: continue` for
        // Sequence.index's `if v is value or v == value: return i`).
        // The skip must NOT be the loop's own exit: a top-level while
        // cond `while X and (A or B):` lays its or-links out with the
        // false exit AT the loop exit (_py_warnings 3.14
        // _next_external_frame — folding it there dropped the loop
        // exit into a phantom if-skip and the body lost its back-edge
        // semantics). The fused form (skip == loop top) keeps requiring
        // a genuine and-chain (asyncore poll lesson).
        let chain_ok = chain_is_and
            || (!fused
                && self.version.at_least(3, 12)
                && self.find_loop_exit(skip).is_none()
                && matches!(&*chain, Expr::BoolOp { op: BoolOpKind::And, values } if values.len() == 1));
        if !chain_ok {
            return None;
        }
        let mut or_vals = Vec::new();
        flatten_boolop(cond, BoolOpKind::Or, &mut or_vals);
        if let Expr::BoolOp { op: BoolOpKind::And, values } = &*chain {
            if values.len() == 1 {
                flatten_boolop(values[0].clone(), BoolOpKind::Or, &mut or_vals);
            } else {
                flatten_boolop(chain, BoolOpKind::Or, &mut or_vals);
            }
        } else {
            flatten_boolop(chain, BoolOpKind::Or, &mut or_vals);
        }
        let merged = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values: or_vals,
        });
        // body end: the skip label (clean) or the loop's back edge (fused)
        let body_end = if fused {
            self.idx_of
                .get(&body_start)
                .and_then(|&bk| {
                    self.instrs[bk..]
                        .iter()
                        .find(|x| {
                            x.is_backward
                                && x.target == Some(skip)
                                && matches!(
                                    x.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                        })
                        .map(|x| x.offset)
                })
                .unwrap_or(body_start)
        } else {
            skip
        };
        // the PJIT target must be the real BODY: in `A or (B and C)` the body
        // region [body_start, body_end) holds no cond jump (only the body
        // statements and, when fused, the loop back edge). A cond jump there
        // means the PJIT target is an and-CONTINUATION rather than the body
        // -- e.g. `(args or kw) and D` where PJIT(args) lands on D's eval and
        // D's own PJIF->skip follows. Merging there double-counts D and
        // scrambles the grouping (_threading_local 2.7-3.7 PASS regression).
        if let (Some(&bsi), Some(&bei)) =
            (self.idx_of.get(&body_start), self.idx_of.get(&body_end))
        {
            if bei > bsi
                && self.instrs[bsi..bei].iter().any(|x| {
                    matches!(
                        x.op,
                        Op::POP_JUMP_IF_FALSE
                            | Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_FALSE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                            | Op::POP_JUMP_BACKWARD_IF_FALSE
                            | Op::POP_JUMP_BACKWARD_IF_TRUE
                            | Op::JUMP_IF_FALSE_OR_POP
                            | Op::JUMP_IF_TRUE_OR_POP
                            | Op::JUMP_IF_FALSE
                            | Op::JUMP_IF_TRUE
                    )
                })
            {
                return None;
            }
        }
        // open the if at the body; A's PJIT and the and-chain are skipped
        let mut blk = Block::new(BlockType::If, body_start, body_end);
        blk.cond = Some(merged);
        blk.cond_set = true;
        blk.jump_if_true = false;
        blk.stack_depth = self.stack.len();
        self.blocks.push(blk);
        Some(body_start)
    }

    /// PJFF-headed `(P or Q...) and R` statement chain (3.11-era layout):
    /// the negative first or-operand compiles to a PJFF whose target is
    /// the AND continuation (R's operand run), NOT the else arm - the
    /// or-group's last operand and R share the else label E. Read
    /// naively, the head link opens an `if P:` guard over the rest and
    /// the else arm attaches to the INNER if - the P-true path loses the
    /// else entirely (compileall 3.11 compile_path `if (not dir or
    /// dir == os.curdir) and skip_curdir:` rendered `if dir: if ...
    /// else: ...`; a falsy dir silently skipped what the source sends
    /// to the else arm). Merge into ONE If spanning R's fall-through
    /// and ending at E; the linear walk re-runs R's own PJFF harmlessly
    /// (top.end == E → dead-skip close), exactly like the `A or (B and
    /// C)` fold. Returns the merged If's body start.
    fn try_or_group_and_chain(&mut self, cond: &ExprRef, target: usize) -> Option<usize> {
        if target <= self.cur_next {
            return None;
        }
        let bi = *self.idx_of.get(&self.cur_next)?;
        let ti = *self.idx_of.get(&target)?;
        if ti <= bi {
            return None;
        }
        // the and continuation at `target`: a pure-value run ending in a
        // PJFF-family link (R's false exit) jumping forward to the
        // shared else label E
        let mut k = ti;
        while matches!(self.instrs.get(k).map(|x| x.op), Some(op) if is_pure_value_op(op)
            || matches!(op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL))
        {
            k += 1;
        }
        if k == ti {
            // no operand run at the landing - not R's eval site
            return None;
        }
        let jr = self.instrs.get(k)?;
        if !matches!(
            jr.op,
            Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
        ) {
            return None;
        }
        let e = jr.target?;
        if e <= jr.offset {
            return None;
        }
        let r_val = self.sim_value_region(ti, k)?;
        // the or-group's remaining operands: the gap [cur_next, target)
        // is pure-value runs separated by PJFF-family links ALL exiting
        // to E, with at least one link (a plain `P and R` head would
        // jump straight to E, never landing mid-chain)
        let mut q_vals: Vec<ExprRef> = Vec::new();
        let mut region_start = bi;
        let mut m = bi;
        while m < ti {
            let x = self.instrs[m];
            if matches!(
                x.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                if x.target != Some(e) {
                    return None;
                }
                q_vals.push(self.sim_value_region(region_start, m)?);
                m += 1;
                region_start = m;
                continue;
            }
            if !(is_pure_value_op(x.op)
                || matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::TO_BOOL))
            {
                return None;
            }
            m += 1;
        }
        if q_vals.is_empty() || region_start != ti {
            return None;
        }
        // merge: Or(!P, Q...) And R
        let mut or_vals = Vec::new();
        flatten_boolop(negate_cond(cond.clone()), BoolOpKind::Or, &mut or_vals);
        for q in q_vals {
            flatten_boolop(q, BoolOpKind::Or, &mut or_vals);
        }
        let or_expr: ExprRef = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values: or_vals,
        });
        let mut and_vals = Vec::new();
        flatten_boolop(or_expr, BoolOpKind::And, &mut and_vals);
        flatten_boolop(r_val, BoolOpKind::And, &mut and_vals);
        let merged: ExprRef = Rc::new(Expr::BoolOp {
            op: BoolOpKind::And,
            values: and_vals,
        });
        // open the merged If at R's fall-through (the body head); E is
        // the else start - the walk's normal else machinery takes over
        let body_start = self.instrs.get(k + 1).map(|x| x.offset)?;
        if body_start >= e {
            return None;
        }
        let mut blk = Block::new(BlockType::If, body_start, e);
        blk.cond = Some(merged);
        blk.cond_set = true;
        blk.jump_if_true = false;
        blk.stack_depth = self.stack.len();
        self.blocks.push(blk);
        Some(body_start)
    }

    fn handle_cond_jump(&mut self, cond: ExprRef, jump_if_true: bool, target: usize) {
        // tail-duplicated body copy: aim the jump at the original body
        let target = self.dup_copy_redirect.get(&target).copied().unwrap_or(target);
        let raw_target = target;
        // 3.8+ `continue` threading: the jump may land ON the loop's back
        // edge instruction instead of the loop top (3.10 `if a or b:
        // continue`); executing the back edge IS the continue - normalize
        // to the top so the jump reads identically to the direct form
        // (3.8 targets FOR_ITER/the top outright)
        let target = self
            .idx_of
            .get(&target)
            .and_then(|&ti| {
                let ins = self.instrs.get(ti)?;
                if self.version.at_least(3, 8)
                    && ins.is_backward
                    && matches!(
                        ins.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                    )
                {
                    // only thread when nothing but pads/operand value
                    // ops lies between this cond jump and the back
                    // edge: a real statement there means the back edge
                    // is a fused ARM-END trampoline and this jump is a
                    // nested guard whose merge is the trampoline itself
                    // (_strptime 3.10 _strptime: `if ampm in (...):
                    // if hour == 12: hour = 0` — the guard's PJIF
                    // landed on the elif arm's end JABS, threading to
                    // the loop top opened If[..,454], the body ejected
                    // and the arm grew a phantom continue)
                    // scope: the 3.8-3.10 JUMP_ABSOLUTE back-edge idiom
                    // only — 3.11+ JUMP_BACKWARD chains (elif spines
                    // ending on the fused edge) rely on the threading
                    // to keep their skip jumps aligned (_strptime
                    // 3.13/3.14 LC_alt_digits elif broke when the
                    // guard applied there)
                    // and only when the back edge's target is NOT a
                    // recognizable loop top: the ampm guard's landing
                    // edge targets the for's GET_ITER (one instruction
                    // before the For block's recorded start) — an
                    // arm-end trampoline, not a continue edge
                    // veto the threading only for the 3.8-3.10
                    // JUMP_ABSOLUTE idiom, only when the edge is not a
                    // recognizable loop top, and only when the span
                    // holds real statements: or/and-chain operand runs
                    // (pure values + cond jumps) still thread so
                    // `if a or b: continue` reads right (_pylong), and
                    // 3.11+ JUMP_BACKWARD chains keep their threading
                    // (_strptime 3.13/3.14 LC_alt_digits elif). A
                    // statement-only span means the back edge is a
                    // fused ARM-END trampoline and this jump is a
                    // nested guard whose merge is the trampoline itself
                    // (_strptime 3.10 ampm: `if hour == 12: hour = 0`
                    // threaded to the loop top ejected the body and
                    // grew a phantom continue)
                    let cj_end = self.cur_next;
                    // the back edge is a dedicated continue landing (NOT
                    // a fused arm end) when the instruction before it is
                    // an unconditional forward hop or a return — the span
                    // never falls through into the edge. Threading such a
                    // guard to the loop top opens a degenerate If[end<
                    // start] and silently drops the guard (copy 3.11
                    // _deepcopy_tuple: PJFF->trampoline, body ends in a
                    // break hop). Fused arm ends (elif spines, statement
                    // fall-through) keep their threading.
                    // scope: only when the span between this guard and
                    // the edge holds real statements — pure operand runs
                    // (or/and chains, elif spines) still thread (csv
                    // 3.11 regressed when the veto applied to them)
                    let span_stmts = self
                        .idx_of
                        .get(&cj_end)
                        .copied()
                        .map_or(false, |si| {
                            self.instrs[si..ti].iter().any(|x| {
                                !matches!(
                                    x.op,
                                    Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                ) && !is_pure_value_op(x.op)
                                    && !matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                            | Op::TO_BOOL
                                    )
                            })
                        });
                    // RETURN-before-edge is the standard 3.11+ in-loop
                    // return cleanup (SWAP; POP_TOP; RETURN; back edge)
                    // and must keep threading (csv 3.11 _guess_delimiter
                    // regressed when vetoed); only an unconditional
                    // FORWARD hop over the edge marks a dedicated
                    // continue landing (copy 3.11 _deepcopy_tuple break)
                    let dedicated_tramp = span_stmts
                        && ti > 0
                        && matches!(
                            self.instrs[ti - 1].op,
                            Op::JUMP_FORWARD | Op::JUMP
                        )
                        && !self.instrs[ti - 1].is_backward
                        && self
                            .instrs[ti - 1]
                            .target
                            .map_or(false, |t| {
                                t > self.instrs[ti].offset
                                    && self.jump_is_loop_exit_or_merge(t)
                            });
                    // nested-guard arm end: the span holds real
                    // statements AND the edge is the loop's tail back
                    // edge (nothing but exit machinery between it and
                    // the loop end) — this jump is the arm's skip to
                    // the loop tail, not a continue threading (cmd
                    // 3.10 do_help `if name[:3]=='do_': if
                    // name==prevname: continue; <rest>` — threading
                    // opened a degenerate If and the or-continue fuse
                    // rendered the DeMorgan flat form whose recompile
                    // moved the first PJIF off the tail)
                    let nested_guard_tail = span_stmts
                        // scope: the 3.8-3.10 JUMP_ABSOLUTE back-edge
                        // idiom only — 3.11+ JUMP_BACKWARD chains
                        // (elif spines, continue-guard chains ending on
                        // the fused edge) rely on the threading to keep
                        // their skip jumps aligned (contextlib 3.14
                        // __exit__ and bdb 3.13/3.14 tore when the veto
                        // applied there)
                        && ins.op == Op::JUMP_ABSOLUTE
                        // the span must hold the inner guard's CONTINUE
                        // (a backward jump onto the loop top): a chain's
                        // tail link whose shared exit IS the loop tail
                        // (compileall 3.11 _walk_dir `... and not
                        // islink: yield from`, elif spines ending on the
                        // fused edge) has an arm-only span and must keep
                        // threading
                        && self
                            .blocks
                            .iter()
                            .rev()
                            .find(|b| {
                                matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                )
                            })
                            .map_or(false, |lb| {
                                let lt = lb.start;
                                let lc = lb.cond_end;
                                let edge_off = self.instrs[ti].offset;
                                self.idx_of
                                    .get(&cj_end)
                                    .map_or(false, |&si| {
                                        self.instrs[si..]
                                            .iter()
                                            .take_while(|x| {
                                                x.offset < edge_off
                                            })
                                            .any(
                                            |x| {
                                                x.is_backward
                                                    && matches!(
                                                        x.op,
                                                        Op::JUMP_ABSOLUTE
                                                            | Op::JUMP_BACKWARD
                                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                    )
                                                    && x.target
                                                        .map_or(
                                                            false,
                                                            |t| {
                                                                t == lt
                                                                    || (lc
                                                                        != usize::MAX
                                                                        && lc
                                                                            == t)
                                                            },
                                                        )
                                            },
                                        )
                                    })
                            })
                        && self
                            .blocks
                            .iter()
                            .rev()
                            .find(|b| {
                                matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                )
                            })
                            .map_or(false, |lb| {
                                let le = lb.end;
                                self.instrs.get(ti).map_or(false, |edge| {
                                    le > edge.offset
                                        && !self.instrs[ti + 1..]
                                            .iter()
                                            .take_while(|x| x.offset < le)
                                            .any(|x| {
                                                !matches!(
                                                    x.op,
                                                    Op::NOP
                                                        | Op::NOT_TAKEN
                                                        | Op::CACHE
                                                        | Op::EXTENDED_ARG
                                                        | Op::JUMP_ABSOLUTE
                                                        | Op::JUMP_BACKWARD
                                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                        | Op::JUMP_FORWARD
                                                        | Op::JUMP
                                                        | Op::POP_BLOCK
                                                        | Op::POP_TOP
                                                        | Op::FOR_ITER
                                                        | Op::END_FOR
                                                        | Op::END_SEND
                                                ) && !x.is_backward
                                            })
                                })
                            });
                    let span_pure = !dedicated_tramp
                        && !nested_guard_tail
                        && (ins.op != Op::JUMP_ABSOLUTE
                        || ins.target
                            .map_or(false, |bt| self.is_loop_top_target(bt))
                        || self
                            .idx_of
                            .get(&cj_end)
                            .map_or(false, |&si| {
                                self.instrs[si..ti].iter().all(|x| {
                                    matches!(
                                        x.op,
                                        Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                    ) || is_pure_value_op(x.op)
                                        || matches!(
                                            x.op,
                                            Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                                | Op::TO_BOOL
                                        )
                                })
                            }));
                    if span_pure {
                        ins.target
                    } else {
                        None
                    }
                } else {
                    None
                }
            })
            .unwrap_or(target);
        if target != raw_target {
            self.cond_jump_redirect.insert(self.cur_offset, target);
        }
        // 3.12+ OR-shaped pre-checked rotated while (`while A or B:`):
        // the A link jumps TRUE straight to the body top and only the
        // LAST operand (B) exits to the loop end; the tail re-eval
        // inverts each non-final link (pjFALSE->next region, fall-
        // through JB->body) and repeats the final link + back edge
        // (_collections_abc 3.13 Sequence.index `while stop is None
        // or i < stop:` rendered `if stop is not None: while i <
        // stop:` — semantically wrong for stop=None)
        if self.version.at_least(3, 12)
            && jump_if_true
            && self.try_pre_rot_or(&cond, target)
        {
            return;
        }
        // 3.12+ value-position ternary whose arms TERMINATE with
        // duplicated tails: `return self[:A if C else B].strip()` — the
        // compiler preloads the common slice operands, then each arm
        // runs its own copy of [tail ops; RETURN] with no merge point
        // (configparser 3.13 _strip_inline rendered a statement if/else
        // whose arms lost/misassigned the preloaded stack operands:
        // `return None[:].strip()`). Sim both arms; when they differ in
        // exactly ONE value slot and the op sequences after it match,
        // rebuild the single expression with a ternary at that slot.
        if self.version.at_least(3, 12) {
            if let Some(e) = self.try_dup_tail_ternary(cond.clone(), jump_if_true, target) {
                self.push_stmt(Stmt::Return(Some(e)));
                if let Some(sk) = self.dup_tail_ternary_skip.take() {
                    self.skip_until = Some(sk);
                }
                return;
            }
        }
        // value-form `A and B or C`: the `and`'s PJIF target is the `or`'s
        // second operand, so the chain merges into one BoolOp value instead
        // of an `if A: pass` + a truncated `B or C` (ast 3.6 _format).
        if !jump_if_true {
            if let Some((merged, m)) = self.try_and_or_value_chain(cond.clone(), target) {
                if std::env::var("PYCDC_AOR_DBG").is_ok() {
                    eprintln!("AOR: off={} target={} merge={} -> {:?}", self.cur_offset, target, m, merged);
                }
                self.push(merged);
                                self.skip_until = Some(m);
                return;
            }
        }
        // PJFF-headed `(P or Q...) and R`: the head's false-jump lands on
        // the AND continuation's operand run instead of the else arm —
        // the or-group's last link and R's link share the else label
        // (3.11-era layout, compileall 3.11 compile_path `if (not dir or
        // dir == os.curdir) and skip_curdir:`). Must run before the
        // generic block-open treats the head as an `if P:` guard, which
        // attaches the else arm to the inner if and loses it on the
        // P-true path.
        if !jump_if_true
            && target > self.cur_next
            && self.find_loop_exit(target).is_none()
            && !self.is_loop_top_target(target)
        {
            if let Some(body_start) = self.try_or_group_and_chain(&cond, target) {
                self.skip_until = Some(body_start);
                return;
            }
        }
        // statement-level `A or (B and C ...)`: the first operand's PJIT
        // jumps straight to the body; the rest form an and-chain whose
        // false-jumps share a `skip` label. Merge into one if-condition
        // instead of `if not A: if B and C:` (configparser/asyncore/crypt).
        // The in-loop fused variant (and-chain PJIFs landing on the loop
        // top) is byte-identical on 3.8-3.13 (t_orac/b27), so this runs on
        // ALL versions; the recognizer's guards (pure-value operand sim,
        // shared skip, loop-top admission, e>=e0, statement-headed body)
        // are version-independent and bail to the paths below otherwise.
        if jump_if_true {
            if let Some(body_start) = self.try_or_and_chain(cond.clone(), target) {
                                self.skip_until = Some(body_start);
                return;
            }
        }
        // 3.8+ forward or-continue chain: `if A or B: continue` compiles
        // to  PJIT(A) -> top; <B ops>; PJIF(B) -> body; BACK_EDGE -> top;
        // body:  (3.10+ threads the continue onto the back edge; 3.13
        // _pylong / b16 orcont family). Recognize the two-operand shape
        // and emit `if A or B: continue` directly; anything else falls
        // through to the historical per-version machinery.
        if jump_if_true
            && (self.version.major >= 3 || self.version.at_least(2, 7))
        {
            if let Some((merged, body_end)) = self.try_fwd_or_continue(target, &cond) {
                self.push_stmt(Stmt::If {
                    cond: merged,
                    body: vec![Stmt::Continue],
                    orelse: Vec::new(),
                });
                if self.skip_until.map_or(true, |s| s < body_end) {
                                        self.skip_until = Some(body_end);
                }
                return;
            }
        }
        // loop-tail `if A or B: break` with B a (chained) comparison whose
        // false exits continue the loop: merge into ONE guard with a Break
        // body (cgi 3.8/3.9 read_multi)
        if jump_if_true {
            if let Some((merged, resume)) = self.try_or_break_chain(&cond, target) {
                self.push_stmt(Stmt::If {
                    cond: merged,
                    body: vec![Stmt::Break],
                    orelse: Vec::new(),
                });
                self.skip_until = Some(resume);
                return;
            }
        }
        // py2 value-form boolop consumed by an if: `if X or Y:` where the
        // operands are value-building chains (chained comparisons via
        // JUMP_IF_*_OR_POP) — the FINAL operand's cond jump arrives while
        // the first operand's statement If is still open (its end is the
        // body start, past this jump), and this jump pops the last operand
        // as its own cond. Emit the merged `if X or Y:` statement directly
        // over the body region [blk.end, target); falling through to the
        // generic block-open instead would let this jump (targeting the
        // enclosing else label) trip the else-region arm and orphan any
        // open elif Else block.
        //
        // Version scope: the NON-fused form (second operand's false jump
        // lands past the body) is py2/<=3.7 machinery -- 3.8+ handles that
        // shape elsewhere and must not be disturbed. The FUSED form (false
        // jump == enclosing loop top, `if A or B: <last stmt of loop>`) is
        // identical bytecode on 3.8/3.9 and currently mis-degrades to
        // `if not A: if B:` (semantics inverted) there, so it is admitted
        // on ALL versions via the inner condition.
        {
            let top_info = self.blocks.last().map(|t| {
                (
                    t.kind == BlockType::If,
                    t.short_circuit.is_none(),
                    t.cond.clone(),
                    t.end,
                    t.stack_depth,
                    t.stmts.is_empty(),
                    t.jump_if_true,
                )
            });
            if let Some((true, true, Some(blk_cond), body_start, depth, true, true)) = top_info {
                // The C-operand's false jump normally lands PAST the body
                // (target > body_start). For `if B or C: <last stmt of a
                // loop>` the compiler fuses the body-skip and the loop
                // continue into ONE backward jump to the loop top, so the
                // C target is the enclosing loop's top (< body_start). The
                // body then runs [body_start, back_edge) with an implicit
                // trailing continue (csv 3.5/3.6 _guess_delimiter, where
                // missing this inverted the or into `if not B: if C:`).
                let loop_top = self
                    .blocks
                    .iter()
                    .rev()
                    .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
                    .map(|b| b.start);
                let fused_continue = loop_top == Some(target) && target < body_start;
                // The merge treats the CURRENT cond jump as the LAST operand
                // test before the body, skipping everything in
                // (cur_offset, body_start). If another cond jump lives there
                // it is an extra and-operand of a nested `A or (B and C)`
                // that would be silently DROPPED (configparser 3.6
                // `index==0 or (index>0 and line[index-1].isspace())` lost
                // the isspace() test). Require that span to be cond-jump
                // free; the back edge / body statements still decompile via
                // the body region below.
                let gap_has_cond_jump = self
                    .idx_of
                    .get(&self.cur_offset)
                    .map_or(false, |&ci| {
                        self.instrs[ci + 1..]
                            .iter()
                            .take_while(|x| x.offset < body_start)
                            .any(|x| {
                                matches!(
                                    x.op,
                                    Op::POP_JUMP_IF_FALSE
                                        | Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                        | Op::POP_JUMP_BACKWARD_IF_FALSE
                                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                                        | Op::JUMP_IF_FALSE_OR_POP
                                        | Op::JUMP_IF_TRUE_OR_POP
                                        | Op::JUMP_IF_FALSE
                                        | Op::JUMP_IF_TRUE
                                )
                            })
                    });
                // the skipped span must also hold no STATEMENT material:
                // a raise/store/return there is a nested guard's ARM BODY
                // (`if not block: if qsize==maxsize: raise Full` — the
                // raise sits between this jump and the presumed body
                // start); merging would swallow the arm and invert the
                // flow (py2.7 Queue put/get lost `raise Full`, the
                // timeout<0 ValueError arm and the timed-wait else arm
                // to exactly this)
                let gap_has_stmt = self
                    .idx_of
                    .get(&self.cur_offset)
                    .map_or(false, |&ci| {
                        self.instrs[ci + 1..]
                            .iter()
                            .take_while(|x| x.offset < body_start)
                            .any(|x| {
                                matches!(
                                    x.op,
                                    Op::RAISE_VARARGS
                                        | Op::RETURN_VALUE
                                        | Op::RETURN_CONST
                                        | Op::STORE_FAST
                                        | Op::STORE_NAME
                                        | Op::STORE_GLOBAL
                                        | Op::STORE_ATTR
                                        | Op::STORE_SUBSCR
                                        | Op::STORE_DEREF
                                        | Op::STORE_MAP
                                        | Op::DELETE_FAST
                                        | Op::DELETE_NAME
                                        | Op::DELETE_GLOBAL
                                        | Op::DELETE_ATTR
                                        | Op::DELETE_DEREF
                                        | Op::PRINT_ITEM
                                        | Op::PRINT_NEWLINE
                                        | Op::YIELD_VALUE
                                        | Op::YIELD_FROM
                                        | Op::IMPORT_STAR
                                        | Op::EXEC_STMT
                                        | Op::BREAK_LOOP
                                        | Op::RERAISE
                                )
                            })
                    });
                if !jump_if_true
                    && ((target > body_start && !self.version.at_least(3, 8))
                        || fused_continue)
                    && !gap_has_cond_jump
                    && !gap_has_stmt
                    && body_start > self.cur_offset
                    && self.stack.len() == depth
                {
                    self.blocks.pop();
                    // the block cond was stored NEGATED for the
                    // jump_if_true polarity (`if not A: <region>`) — the
                    // or-operand is the positive form. negate_cond is an
                    // involution on every form it produces (Not(x) and
                    // inverted single-op compares), so it restores the
                    // operand regardless of whether the negation folded
                    let a = negate_cond(blk_cond);
                    let mut values = Vec::new();
                    flatten_boolop(a, BoolOpKind::Or, &mut values);
                    flatten_boolop(cond, BoolOpKind::Or, &mut values);
                    let merged: ExprRef =
                        Rc::new(Expr::BoolOp { op: BoolOpKind::Or, values });
                    // else region [target, else_end): only when a forward
                    // jump from inside the body already marked one on the
                    // enclosing block (the body-end hop over the else)
                    let mut orelse = Vec::new();
                    let mut else_stop = target;
                    if !fused_continue {
                        if let Some(top) = self.blocks.last_mut() {
                            if let Some(ee) = top.else_end.take() {
                                if ee > target {
                                    else_stop = ee;
                                }
                            }
                        }
                        if else_stop > target {
                            orelse = self.decompile_region(target, else_stop);
                        }
                    }
                    // py2 or-continue: the "body" region is the loop's
                    // continue landing (POP_TOP cleanup; back edge to the
                    // loop top; padding hop) - emit Continue instead of
                    // walking it (the region walk has no loop context)
                    // fused shape: the body runs to the loop's
                    // unconditional back edge (JABS/JUMP_BACKWARD to the
                    // loop top == this jump's target)
                    let fused_back_edge = if fused_continue {
                        self.idx_of.get(&body_start).and_then(|&bi| {
                            self.instrs[bi..]
                                .iter()
                                .find(|x| {
                                    x.is_backward
                                        && x.target == Some(target)
                                        && matches!(
                                            x.op,
                                            Op::JUMP_ABSOLUTE
                                                | Op::JUMP_BACKWARD
                                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        )
                                })
                                .map(|x| x.offset)
                        })
                    } else {
                        None
                    };
                    let body_stmts = {
                        let mut is_cont = false;
                        if orelse.is_empty() && !fused_continue {
                            if let (Some(&bi), Some(&ti2)) =
                                (self.idx_of.get(&body_start), self.idx_of.get(&target))
                            {
                                let mut saw_back = false;
                                is_cont = self.instrs[bi..ti2].iter().all(|x| {
                                    if matches!(x.op, Op::POP_TOP | Op::NOP) {
                                        return true;
                                    }
                                    if x.is_backward
                                        && matches!(
                                            x.op,
                                            Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD
                                        )
                                        && self.is_loop_top_target(x.target.unwrap_or(0))
                                    {
                                        saw_back = true;
                                        return true;
                                    }
                                    if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
                                        && !x.is_backward
                                        && x.target == Some(target)
                                    {
                                        return true;
                                    }
                                    false
                                }) && saw_back;
                            }
                        }
                        if is_cont {
                            vec![Stmt::Continue]
                        } else if fused_continue {
                            // body runs to the loop's unconditional back edge;
                            // the fused jump-to-top stands in for the body-end
                            // skip. Do NOT emit an explicit continue: the body
                            // is the loop's last statement, so it falls through
                            // to the back edge naturally (an explicit continue
                            // would recompile to CONTINUE_LOOP and shift the
                            // sig off the original fused PJIF->loop_top).
                            let back_edge = fused_back_edge.unwrap_or(body_start);
                            self.decompile_region(body_start, back_edge)
                        } else {
                            self.decompile_region(body_start, target)
                        }
                    };
                    self.push_stmt(Stmt::If {
                        cond: merged,
                        body: body_stmts,
                        orelse,
                    });
                    if fused_continue {
                        // skip the decompiled-as-region body. Resume point:
                        // <=3.7 the loop's own exit marker (POP_BLOCK /
                        // FOR_ITER target) sits right past the back edge --
                        // skip the back edge too (5550c41 behavior; letting
                        // it re-process regressed asyncore 2.7/3.3 by ~300
                        // sig lines). 3.8+ rotated loops have NEITHER marker
                        // after the body, and an unbounded scan runs away to
                        // an unrelated later POP_BLOCK (asyncore 3.8/3.9
                        // poll() lost the post-loop select chain) -- resume
                        // AT the back edge and let the loop machinery see
                        // it naturally.
                        let exit = if !self.version.at_least(3, 8) {
                            self.idx_of.get(&body_start).and_then(|&bi| {
                                self.instrs[bi..]
                                    .iter()
                                    .find(|x| {
                                        matches!(x.op, Op::FOR_ITER | Op::POP_BLOCK)
                                            && x.offset > body_start
                                    })
                                    .map(|x| {
                                        if x.op == Op::FOR_ITER {
                                            x.target.unwrap_or(x.end())
                                        } else {
                                            x.offset
                                        }
                                    })
                            })
                        } else {
                            None
                        };
                        if let Some(e2) = exit.or(fused_back_edge) {
                                                        self.skip_until = Some(e2);
                        }
                    } else if self.skip_until.map_or(true, |s| s < else_stop) {
                                                self.skip_until = Some(else_stop);
                    }
                    return;
                }
            }
        }
        // 3.14+ continue-guard chain: pass-jumps forward, fail falls into
        // a NOT_TAKEN; JUMP_BACKWARD loop-top trampoline. The NOT_TAKEN
        // padding is mandatory: pre-3.14 `if c: continue` shapes have a
        // bare back jump after the operand jump and belong to the
        // historical machinery.
        // 3.8-3.11: `if A and (chained cmp): break` guard — the chain's
        // mid links hop through a POP_TOP cleanup trampoline, so neither
        // the split-cond merge nor the SCC scan admits the shape
        if !jump_if_true && self.version.major >= 3 && !self.version.at_least(3, 12) {
            if let Some((merged, body_start, body_end)) =
                self.try_and_chain_break_guard(&cond, target)
            {
                let mut blk = Block::new(BlockType::If, body_start, body_end);
                blk.cond = Some(merged);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                self.skip_until = Some(body_start);
                return;
            }
        }
        // 3.8-3.11: statement-level chained-comparison if condition
        if !jump_if_true && self.version.major >= 3 && !self.version.at_least(3, 12) {
            let scc = self.try_stmt_chain_compare(&cond, target);
            if std::env::var("PYCDC_SCC_DBG").is_ok() {
                eprintln!("SCCDBG: off={} target={} -> {:?}", self.cur_offset, target,
                    scc.as_ref().map(|(m, bs, be)| (format!("{m:?}").chars().take(60).collect::<String>(), *bs, *be)));
            }
            if let Some((merged, body_start, body_end)) = scc {
                // open the if directly over the body; the links and the
                // success hop are skipped. The else arm (at `target`)
                // sits BEFORE the body in layout and is only ever
                // reached by the link jumps — no Else region is walked.
                let mut blk = Block::new(BlockType::If, body_start, body_end);
                blk.cond = Some(merged);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                                self.skip_until = Some(body_start);
                return;
            }
        }
        // 3.12+ or-join takes precedence over the guard-chain machinery:
        // `if A or B: body` would otherwise be split into inverted
        // `if not A: if not B: continue` with the body ejected. Gated to
        // 3.12+: pre-3.12 shapes (fused PJIF->loop-top) belong to the
        // or-merge/try_or_and_chain machinery, and running this there
        // scrambled csv _sniffer 3.5/3.6 (+350 sig lines).
        if self.version.at_least(3, 12) {
            if let Some((merged, body_end, tramp_end)) =
                self.try_or_join(&cond, jump_if_true, target)
            {
            self.blocks.pop();
            let mut blk = Block::new(BlockType::If, target, body_end);
            blk.cond = Some(merged);
            blk.cond_set = true;
            blk.jump_if_true = false;
            blk.stack_depth = self.stack.len();
            self.blocks.push(blk);
            // skip the absorbed operand spans AND the false-exit
            // trampoline; resume at the body
                        self.skip_until = Some(tramp_end.max(target));
            return;
            }
        }
        if self.version.at_least(3, 11) {
            if let Some((merged, body_start, body_end, chain_loop_top)) =
                self.try_guard_chain(&cond, jump_if_true, target)
            {
                if body_end <= body_start {
                    // degenerate guard: the whole fall-through IS the
                    // continue trampoline. When the pass-jump target is a
                    // BREAK block (an exit jump, not the loop-level body),
                    // keep the historical rendering: `if <pass cond>:
                    // break` over the trampoline — the inverted-continue
                    // form would drop the break entirely.
                    let pass_is_break = jump_if_true
                        && (self.find_loop_exit(target).is_some()
                            || self
                                .idx_of
                                .get(&target)
                                .and_then(|&ti| self.instrs.get(ti))
                                .map_or(false, |ins| {
                                    matches!(
                                        ins.op,
                                        Op::JUMP_FORWARD
                                            | Op::JUMP
                                            | Op::JUMP_ABSOLUTE
                                            | Op::JUMP_BACKWARD
                                    ) && ins
                                        .target
                                        .map_or(false, |t| {
                                            t > ins.offset
                                                && self.find_loop_exit(t).is_some()
                                        })
                                }));
                    if pass_is_break {
                        let c = simplify_not(merged.clone());
                        self.push_stmt(Stmt::If {
                            cond: c,
                            body: vec![Stmt::Break],
                            orelse: Vec::new(),
                        });
                        // resume past the break block's exit jump
                        let after = self
                            .idx_of
                            .get(&target)
                            .and_then(|&ti| self.instrs.get(ti))
                            .and_then(|ins| ins.target)
                            .unwrap_or(body_start);
                                                self.skip_until = Some(after);
                        return;
                    }
                    // sequential shape-A guard (3.13+ bare adjacency):
                    // the pass target IS the next real instruction after
                    // this guard's own continue trampoline. Locally
                    // ambiguous between (a) a standalone `if not X:
                    // continue` statement with sibling statements
                    // after it, (b) the first link of a fused and-chain
                    // ending in break (copyreg 3.13 _reduce_ex `if A
                    // and B: break`), and (c) a threaded `if X: <body
                    // to loop end>` (copyreg 3.13 _slotnames outer if).
                    // Walk the chain tail to decide: (b) ends at a
                    // break chunk -> emit the fused break; (c) the
                    // chain never advances and the body runs to the
                    // loop's own back edge -> nested If (3.13 only —
                    // 3.14 keeps the historical inverted continue,
                    // nesting there swallowed sibling guards and
                    // dropped tail breaks: _py_warnings, bdb,
                    // configparser 3.14); anything else falls to the
                    // historical inverted continue — fusing sibling
                    // guards nests the loop's tail statements under
                    // the last guard and loses their continue
                    // semantics (bdb 3.13 effective: the fused form
                    // ran the try tail for disabled breakpoints).
                    if chain_loop_top != usize::MAX {
                        let after_tramp = {
                            let mut k = self
                                .idx_of
                                .get(&body_end)
                                .map(|&i2| i2 + 1);
                            while let Some(kk) = k {
                                match self.instrs.get(kk).map(|x| x.op) {
                                    Some(Op::NOT_TAKEN)
                                    | Some(Op::NOP)
                                    | Some(Op::CACHE) => k = Some(kk + 1),
                                    _ => break,
                                }
                            }
                            k.and_then(|kk| self.instrs.get(kk))
                                .map(|x| x.offset)
                        };
                        if after_tramp == Some(body_start) {
                            let is_cj = |o: Op| {
                                matches!(
                                    o,
                                    Op::POP_JUMP_IF_FALSE
                                        | Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                )
                            };
                            // walk successive guarded links: pure-value
                            // region + cond jump whose fall-through is
                            // [pads] JUMP_BACKWARD chain_loop_top
                            let mut cur = body_start;
                            let mut advanced = false;
                            let tail = loop {
                                let Some(&ri) = self.idx_of.get(&cur) else {
                                    break None;
                                };
                                let mut jk = ri;
                                let mut cond_at = None;
                                while jk < self.instrs.len() {
                                    let ins = &self.instrs[jk];
                                    if is_cj(ins.op) {
                                        cond_at = Some(jk);
                                        break;
                                    }
                                    if !is_pure_value_op(ins.op)
                                        && !matches!(
                                            ins.op,
                                            Op::NOT_TAKEN
                                                | Op::NOP
                                                | Op::CACHE
                                                | Op::TO_BOOL
                                        )
                                    {
                                        break;
                                    }
                                    jk += 1;
                                }
                                let Some(cj) = cond_at else {
                                    break Some(cur);
                                };
                                let mut ft = cj + 1;
                                while matches!(
                                    self.instrs.get(ft).map(|x| x.op),
                                    Some(Op::NOT_TAKEN)
                                        | Some(Op::NOP)
                                        | Some(Op::CACHE)
                                ) {
                                    ft += 1;
                                }
                                let ok_tramp = self
                                    .instrs
                                    .get(ft)
                                    .map_or(false, |x| {
                                        x.is_backward
                                            && x.target
                                                == Some(chain_loop_top)
                                            && matches!(
                                                x.op,
                                                Op::JUMP_BACKWARD
                                                    | Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            )
                                    });
                                if !ok_tramp {
                                    break Some(cur);
                                }
                                let Some(nt) = self.instrs[cj].target else {
                                    break Some(cur);
                                };
                                advanced = true;
                                cur = nt;
                            };
                            // (b) the chain stopped at a break chunk:
                            // [POP_TOP/pads] forward jump to a loop exit
                            if let Some(stop) = tail {
                                if advanced {
                                    if let Some(&si) = self.idx_of.get(&stop) {
                                        let mut k = si;
                                        while matches!(
                                            self.instrs.get(k).map(|x| x.op),
                                            Some(Op::POP_TOP)
                                                | Some(Op::NOT_TAKEN)
                                                | Some(Op::NOP)
                                                | Some(Op::CACHE)
                                        ) {
                                            k += 1;
                                        }
                                        let break_hop = self
                                            .instrs
                                            .get(k)
                                            .filter(|jins| {
                                                !jins.is_backward
                                                    && matches!(
                                                        jins.op,
                                                        Op::JUMP_FORWARD
                                                            | Op::JUMP
                                                            | Op::JUMP_ABSOLUTE
                                                    )
                                                    && jins
                                                        .target
                                                        .map_or(false, |t| {
                                                            self.jump_is_loop_exit_or_merge(t)
                                                        })
                                            })
                                            .map(|jins| jins.end());
                                        if let Some(hop_end) = break_hop {
                                            self.push_stmt(Stmt::If {
                                                cond: merged.clone(),
                                                body: vec![Stmt::Break],
                                                orelse: Vec::new(),
                                            });
                                            self.skip_until = Some(hop_end);
                                            return;
                                        }
                                    }
                                } else if jump_if_true
                                    && self.version.at_least(3, 13)
                                {
                                    // (c) threaded if: no chain link at
                                    // the target — it is a plain body
                                    // that must run to the loop's OWN
                                    // back edge (the LAST one before
                                    // the loop end; an inner guard's
                                    // trampoline would cut the body
                                    // short and swallow siblings)
                                    let lb = self
                                        .blocks
                                        .iter()
                                        .rev()
                                        .find(|b| {
                                            matches!(
                                                b.kind,
                                                BlockType::While
                                                    | BlockType::For
                                            ) && (b.start == chain_loop_top
                                                || (b.cond_end != usize::MAX
                                                    && b.cond_end
                                                        == chain_loop_top))
                                        });
                                    if let Some(lb) = lb {
                                        let lb_end = lb.end;
                                        let mut back_off = None;
                                        let mut ok = self
                                            .idx_of
                                            .get(&body_start)
                                            .is_some();
                                        if ok {
                                            let bi = self.idx_of[&body_start];
                                            for ins in self.instrs[bi..].iter()
                                            {
                                                if ins.offset >= lb_end {
                                                    break;
                                                }
                                                if let Some(t) = ins.target {
                                                    if ins.is_backward
                                                        && t == chain_loop_top
                                                        && matches!(
                                                            ins.op,
                                                            Op::JUMP_BACKWARD
                                                                | Op::JUMP_ABSOLUTE
                                                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                        )
                                                    {
                                                        back_off =
                                                            Some(ins.offset);
                                                    }
                                                    if !ins.is_backward
                                                        && t >= lb_end
                                                    {
                                                        ok = false;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                        if let (true, Some(be)) = (ok, back_off) {
                                            if be > body_start {
                                                // merged is the NEGATED
                                                // guard (shape A PJIT
                                                // degenerate folds `in`
                                                // to `not in` via
                                                // negate_cond) — restore
                                                // the source polarity
                                                let c = negate_cond(
                                                    merged.clone(),
                                                );
                                                let mut blk = Block::new(
                                                    BlockType::If,
                                                    body_start,
                                                    be,
                                                );
                                                blk.cond = Some(c);
                                                blk.cond_set = true;
                                                blk.jump_if_true = false;
                                                blk.stack_depth =
                                                    self.stack.len();
                                                self.blocks.push(blk);
                                                self.skip_until =
                                                    Some(body_start);
                                                return;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // emit `if <merged>: continue` and resume at the
                    // loop-level body that follows the trampoline
                    self.push_stmt(Stmt::If {
                        cond: merged,
                        body: vec![Stmt::Continue],
                        orelse: Vec::new(),
                    });
                                        self.skip_until = Some(body_start);
                    return;
                }
                let mut blk = Block::new(BlockType::If, body_start, body_end);
                blk.cond = Some(merged);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                // direct-form body running to the loop's own end: its
                // tail iteration edge must not fold the spine
                blk.no_fold = self
                    .blocks
                    .iter()
                    .rev()
                    .find(|b| {
                        matches!(b.kind, BlockType::While | BlockType::For)
                    })
                    .map_or(false, |lb| lb.end == body_end);
                self.blocks.push(blk);
                                self.skip_until = Some(body_start);
                return;
            }
        }
        // 3.12+: statement-level chained-comparison if condition, as a
        // FALLBACK after the loop-guard chain path above. 3.12 replaced the
        // DUP/ROT chain bookkeeping with SWAP/COPY and lets each link exit
        // to its own else-copy/cleanup label, but the layout (pure-value
        // link regions ending in PJIF, success hop JUMP_FORWARD into the
        // body) still fits the SCC scan — e.g. `if a==b==c and a==d:` whose
        // first link exits to a duplicated else stub ahead of the body.
        if !jump_if_true && self.version.at_least(3, 12) {
            if let Some((merged, body_start, body_end)) =
                self.try_stmt_chain_compare(&cond, target)
            {
                let mut blk = Block::new(BlockType::If, body_start, body_end);
                blk.cond = Some(merged);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                                self.skip_until = Some(body_start);
                return;
            }
        }
        // py2-style boolop if-conditions: `(a or b) and c` merges into one
        // BoolOp cond + a single If block. Skipped when this jump is an
        // uninitialized loop's condition (SETUP_LOOP era) or a rotated-while
        // back-edge candidate.
        let while_top = self.blocks.last().map_or(false, |b| {
            matches!(b.kind, BlockType::While)
                && (!b.cond_set || b.cond_end != usize::MAX)
        });
        if !while_top {
            // `(a and b) or c`: when THIS jump is a PJIF (jump_if_true
            // false) AND the chain's second jump is a polarity-FLIPPED
            // PJIT, try the STRICT merged-boolop recognizer first. The
            // f1 shape's first operand jumps on FALSE to the or's second
            // operand and the and's last operand joins on TRUE straight
            // to the body; try_merge_or_cond misreads that operand region
            // as the body and the real body as the exit, inverting the
            // condition to `if not a or not b: if c:`. The strict
            // recognizer gets it right (Or(And(a,b),c)).
            //
            // The flipped-polarity requirement keeps the 3.8+ folded
            // `not A or B` shape out: there PJIF(A->BODY) is the or-join
            // and the following PJIF(B->skip) is SAME-polarity; capturing
            // the body's nested guard as j2 (its skip coinciding with the
            // outer skip) inverted `if not A or B: if not C: raise` into
            // `if (A and B) and C: raise` (configparser 3.7-3.9
            // _validate_value_types -- the RAISE body defeats the
            // body-is-operand veto inside the recognizer).
            //
            // Do NOT preempt when jump_if_true is TRUE (a PJIT-headed
            // shape-A `(a or b) and c`, e.g. compileall compile_path):
            // preempting there reshuffled the continue/print nesting on
            // 3.10-3.13. ADOPT the strict result only when it carries no
            // Not(): the bogus folds are exactly the DeMorgan-negated
            // ones (abc 2.7).
            if !jump_if_true {
                let j0_is_pjit = self
                    .idx_of
                    .get(&self.cur_next)
                    .and_then(|&bi2| {
                        (bi2..self.instrs.len())
                            .take_while(|&k| self.instrs[k].offset < target)
                            .find(|&k| {
                                matches!(
                                    self.instrs[k].op,
                                    Op::POP_JUMP_IF_FALSE
                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                        | Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                )
                            })
                            .map(|k| {
                                matches!(
                                    self.instrs[k].op,
                                    Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                                )
                            })
                    })
                    .unwrap_or(false);
                if j0_is_pjit {
                    if let Some((merged, then_start, e)) =
                        self.try_merge_py2_boolop(&cond, jump_if_true, target)
                    {
                        if !expr_contains_not(&merged) {
                            let mut blk = Block::new(BlockType::If, then_start, e);
                            blk.cond = Some(merged);
                            blk.cond_set = true;
                            blk.jump_if_true = false;
                            blk.stack_depth = self.stack.len();
                            self.blocks.push(blk);
                            // the operand regions were consumed by the scratch sim
                                                        self.skip_until = Some(then_start);
                            return;
                        }
                    }
                }
            }
            // 3.8+ `while A or B:` header: the While block is already open
            // at the loop top (back-edge prescan) with its cond unparsed;
            // this PJIT(A) targets the body start and the gap to it is the
            // second operand ending in PJF(B) to the loop exit. The
            // generic or-probe bails on the body's back edge ("leave it
            // to the while machinery") and the fall-through renders the
            // header as rotated guards inside `while True:` — merge into
            // the While cond instead (_collections_abc 3.8/3.9 index:
            // `while stop is None or i < stop:` rendered `while True: if
            // stop is not None: if not i < stop: break`, semantically
            // right but sig-off: `is not`+PJF+JABS instead of `is`+PJIT)
            if jump_if_true && self.legacy_handler.is_none() {
                if std::env::var("PYCDC_ORC_DBG").is_ok() {
                    eprintln!("WOR hdr-probe off={} target={} top={:?}", self.cur_offset, target, self.blocks.last().map(|t| (t.kind as u8, t.start, t.end, t.cond_set)));
                }
                // the prescan may have synthesized `while True:` for this
                // loop (its or-header defeats is_cond_expr_top): a True
                // cond is the replaceable placeholder
                let while_hdr = self.blocks.last().map_or(false, |t| {
                    matches!(t.kind, BlockType::While)
                        && (!t.cond_set
                            || matches!(
                                t.cond.as_ref().map(|c| &**c),
                                Some(Expr::Name(n)) if n == "True"
                            )
                            || matches!(
                                t.cond.as_ref().map(|c| &**c),
                                Some(Expr::Const(o))
                                    if matches!(&**o, PyObject::Int(1))
                            ))
                        && t.end != usize::MAX
                        && t.start <= self.cur_offset
                        && target > self.cur_next
                        && target < t.end
                });
                if while_hdr {
                    let w_end = self.blocks.last().map(|t| t.end).unwrap_or(0);
                    let merged_or = (|| {
                        let gi = *self.idx_of.get(&self.cur_next)?;
                        let ti2 = *self.idx_of.get(&target)?;
                        let mut pjf = None;
                        for k in gi..ti2 {
                            let x = self.instrs[k];
                            if matches!(
                                x.op,
                                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                            ) {
                                if pjf.is_some() {
                                    return None;
                                }
                                // the second operand's false jump must be
                                // the loop's exhaustion exit
                                if x.target != Some(w_end) {
                                    return None;
                                }
                                pjf = Some(k);
                            } else if matches!(
                                x.op,
                                Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                            ) || !is_pure_value_op(x.op)
                            {
                                return None;
                            }
                        }
                        let sk = pjf?;
                        let second = self.sim_value_region(gi, sk)?;
                        let mut or_vals = Vec::new();
                        flatten_boolop(cond.clone(), BoolOpKind::Or, &mut or_vals);
                        flatten_boolop(second, BoolOpKind::Or, &mut or_vals);
                        Some(Rc::new(Expr::BoolOp {
                            op: BoolOpKind::Or,
                            values: or_vals,
                        }) as ExprRef)
                    })();
                    if std::env::var("PYCDC_ORC_DBG").is_ok() {
                        eprintln!("WOR merged={}", merged_or.is_some());
                    }
                    if let Some(mc) = merged_or {
                        let top = self.blocks.last_mut().unwrap();
                        top.cond = Some(mc);
                        top.cond_set = true;
                        top.jump_if_true = false;
                        top.cond_end = target;
                        self.skip_until = Some(target);
                        return;
                    }
                }
            }
            // DNF `if (A1 and A2) or (B1 and B2): body` -- recognize
            // BEFORE try_merge_or_cond, which misfolds this shape
            if let Some((merged, body_start, body_end)) = if jump_if_true {
                self.try_or_group_chain_312(&cond, target)
            } else {
                self.try_or_group_chain(&cond, target)
            } {
                {
                    let mut blk = Block::new(BlockType::If, body_start, body_end);
                    blk.cond = Some(merged);
                    blk.cond_set = true;
                    blk.jump_if_true = false;
                    blk.stack_depth = self.stack.len();
                    self.blocks.push(blk);
                                        self.skip_until = Some(body_start);
                    return;
                }
            }
            // `if a or b:` (and mixed-polarity and-chains): this cond jump
            // targets the BODY start; the region up to it is the second
            // operand ending in an opposite-polarity cond jump to the if's
            // exit. Merge into one BoolOp cond over [target, exit).
            if let Some((merged_cond, body_start, exit, chain_blocks)) =
                self.try_merge_or_cond(&cond, jump_if_true, target)
            {
                // chain-or: the absorbed chain-link If blocks (whose conds
                // were folded into the merged condition) come off the stack
                // innermost-first; their bytecode is covered by the skip
                for _ in 0..chain_blocks {
                    self.blocks.pop();
                }
                if std::env::var("PYCDC_ORC_DBG").is_ok() {
                    eprintln!("ORC off={} merged={:?} body=[{},{}) chain={}", self.cur_offset, merged_cond, body_start, exit, chain_blocks);
                }
                // a body-targeting or-group merged directly UNDER an open
                // and-link: `if a and (b or c):` — the first operand's
                // PJIF opened an If ending at the shared exit, and the
                // or-group's merged exit IS that end. Pushing a second If
                // nests the group (`if a: if b or c:` — compileall 3.11
                // compile_dir/compile_file `ddir is not None and (stripdir
                // is not None or prependdir is not None)`, the near-pass
                // sig diff). Fold into the open cond instead: the same And
                // merge split_cond does for same-exit links, extended to a
                // body-targeting group. The span between the open link and
                // the group body must be operand material only (value ops /
                // cond jumps / padding — no statements), else the open If
                // is a genuine enclosing guard whose body already started.
                let mut and_fold = false;
                if let Some(top) = self.blocks.last() {
                    if top.kind == BlockType::If
                        && top.cond_set
                        && top.end == exit
                        && top.stmts.is_empty()
                        && top.short_circuit.is_none()
                        && top.clamp_from.is_none()
                        && top.start < body_start
                    {
                        if let (Some(&si), Some(&bi)) =
                            (self.idx_of.get(&top.start), self.idx_of.get(&body_start))
                        {
                            and_fold = bi > si
                                && self.instrs[si..bi].iter().all(|x| {
                                    is_pure_value_op(x.op)
                                        || matches!(
                                            x.op,
                                            Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                        )
                                        || matches!(
                                            x.op,
                                            Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                                | Op::POP_JUMP_IF_NONE
                                                | Op::POP_JUMP_IF_NOT_NONE
                                                | Op::POP_JUMP_FORWARD_IF_NONE
                                                | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                                                | Op::POP_JUMP_BACKWARD_IF_NONE
                                                | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                                                | Op::JUMP_IF_TRUE_OR_POP
                                                | Op::JUMP_IF_FALSE_OR_POP
                                        )
                                });
                        }
                    }
                }
                if and_fold {
                    if let Some(top) = self.blocks.last_mut() {
                        if let Some(prev) = top.cond.take() {
                            let mut values = Vec::new();
                            flatten_boolop(prev, BoolOpKind::And, &mut values);
                            flatten_boolop(merged_cond.clone(), BoolOpKind::And, &mut values);
                            top.cond = Some(Rc::new(Expr::BoolOp {
                                op: BoolOpKind::And,
                                values,
                            }));
                            self.skip_until = Some(body_start);
                            return;
                        }
                    }
                }
                let mut blk = Block::new(BlockType::If, body_start, exit);
                blk.cond = Some(merged_cond);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                                self.skip_until = Some(body_start);
                return;
            }
            // historical-order retry of the strict recognizer (the Not-free
            // preference above declined its result)
            if let Some((merged, then_start, e)) =
                self.try_merge_py2_boolop(&cond, jump_if_true, target)
            {
                let mut blk = Block::new(BlockType::If, then_start, e);
                blk.cond = Some(merged);
                blk.cond_set = true;
                blk.jump_if_true = false;
                blk.stack_depth = self.stack.len();
                self.blocks.push(blk);
                // the operand regions were consumed by the scratch sim
                                self.skip_until = Some(then_start);
                return;
            }
        }
        // 3.12+ rotated while with a THREADED exit: `<cond>; PJIT body;
        // NOT_TAKEN; JUMP_BACKWARD <enclosing loop top / exit>` and a body
        // back edge looping onto the cond top. Neither section 6 (the back
        // edge lies past the jump target) nor the prescan (the top is not
        // free) claims this loop — open it here.
        if jump_if_true && self.version.at_least(3, 12) {
            let ci_cur = self.cur_offset;
            // the body back edge: a backward jump onto a pure cond-expr
            // top ending at this jump. A `continue` in the body matches
            // too — the REAL back edge is the LAST one (the body end)
            let back_edge = self
                .instrs
                .iter()
                .filter(|ins| {
                    ins.is_backward
                        && ins.offset > ci_cur
                        && matches!(
                            ins.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                        && ins.target.map_or(false, |bt| {
                            bt < ci_cur && self.is_cond_expr_top(bt, ci_cur)
                        })
                })
                .max_by_key(|ins| ins.offset);
            // the exit trampoline right after this jump
            let exit_jump = self
                .idx_of
                .get(&ci_cur)
                .and_then(|&cj| self.instrs.get(cj + 1))
                .filter(|x| matches!(x.op, Op::NOT_TAKEN | Op::NOP))
                .and_then(|_| {
                    self.idx_of.get(&ci_cur).and_then(|&cj| self.instrs.get(cj + 2))
                })
                .filter(|x| {
                    x.is_backward
                        && matches!(
                            x.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                });
            if let (Some(be), Some(xj)) = (back_edge, exit_jump) {
                if let Some(ct) = be.target {
                    let mut blk = Block::new(BlockType::While, ct, be.end());
                    blk.cond = Some(cond);
                    blk.cond_set = true;
                    blk.cond_end = self.cur_next;
                    self.blocks.push(blk);
                    // the trampoline is this loop's exhaustion exit: any
                    // jump onto it from inside the body is a `break`
                    self.threaded_break_at.insert(xj.offset);
                                        self.skip_until = Some(target);
                    return;
                }
            }
        }
        // inline comprehension filter: `... if cond`
        // 3.12-only line-break detection: a filter whose guard sits on a
        // DIFFERENT source line than its FOR_ITER compiles to the
        // PJIF->shared-backedge shape; same-line filters compile to
        // PJIT+continue (_py_abc __new__ set-comp) — record the break so
        // codegen reproduces the layout (3.13+ always uses the PJIT form)
        let comp_if_break = self
            .inline_comp
            .as_ref()
            .and_then(|comp| {
                if !self.version.at_least(3, 12) || self.version.at_least(3, 13)
                {
                    return None;
                }
                let fl = comp
                    .for_iter_offsets
                    .last()
                    .and_then(|fo| self.idx_of.get(fo))
                    .and_then(|&fi| self.instrs[fi].line);
                let cl = self
                    .idx_of
                    .get(&self.cur_offset)
                    .and_then(|&ci2| self.instrs[ci2].line);
                match (fl, cl) {
                    (Some(a), Some(b)) => Some(a != b),
                    _ => None,
                }
            })
            .unwrap_or(false);
        if let Some(comp) = &mut self.inline_comp {
            if self.cur_offset < comp.end {
                // NB: no negate_cond here — the push below cancels the
                // polarity flip (simplify_not(Not(c)) == c); folding the
                // comparison would invert the filter
                let c = if jump_if_true { cond } else { simplify_not(cond) };
                if let Some(cur) = &mut comp.cur {
                    if comp_if_break {
                        cur.if_break = true;
                    }
                    cur.ifs.push(c);
                }
                return;
            }
        }
        // 0) a cond jump whose target is the end of an open Else block and
        // which is NOT an elif condition closes the else body first. The
        // elif test would create a nested If at the same target, so keep
        // the Else open in that case.
        if let Some(top) = self.blocks.last() {
            if matches!(top.kind, BlockType::Else | BlockType::TryElse)
                && top.end == target
                && !top.is_elif
                && self.cur_offset != top.start
            {
                self.close_blocks_at(target);
            }
        }

        // 1) short-circuit merge: a JUMP_IF_*_OR_POP block ending here
        if let Some(top) = self.blocks.last() {
            if matches!(top.kind, BlockType::If) && top.short_circuit.is_some() && top.end == target
            {
                let or_form = top.short_circuit.unwrap();
                let left = top.cond.clone().unwrap();
                let mut b = self.blocks.pop().unwrap();
                let _ = &mut b;
                let right = self.pop_expr();
                let kind = if or_form {
                    BoolOpKind::Or
                } else {
                    BoolOpKind::And
                };
                let merged = Rc::new(Expr::BoolOp {
                    op: kind,
                    values: vec![left, right],
                });
                self.push(merged);
                return;
            }
        }

        // 2) rotated while: duplicated cond jump to the same exit — ignore.
        // Same polarity matches the loop cond's own re-eval copy; an
        // OPPOSITE-polarity jump landing exactly on the loop exit is an
        // and-chain's negated operand (`while A and not B:` = PJF(A)exit;
        // <B>; PJIT(B)exit) — a source `if c: break` never compiles to a
        // lone opposite-polarity jump at the exit (it needs PJF-to-merge
        // + JABS-to-exit), and an in-body guard's merge lands on the back
        // edge, not past it (asynchat 3.8 find_prefix_at_end rendered
        // guard-break `if endswith: break`, sig-off by the extra JABS)
        let dup_while = self.blocks.last().map_or(false, |top| {
            matches!(top.kind, BlockType::While)
                && top.cond_set
                && (top.jump_if_true == jump_if_true
                    // 3.12+ rotates the whole multi-operand cond into a
                    // post-body re-eval copy claimed by the while-True
                    // prescan (cmd 3.12 columnize) — the opposite-polarity
                    // merge there folds the re-eval into a phantom loop;
                    // pre-3.12 lays the header at the loop top where the
                    // merge is the source shape
                    || (self.version.major == 3
                        && !self.version.at_least(3, 12)
                        && top.end == target))
                // SETUP_LOOP-era exits land on the loop's POP_BLOCK, one
                // instruction before the block end
                && (top.end == target
                    // the entry threading followed the unconditional
                    // jump AT the loop end (the pre-checked rotated
                    // while's exit edge onto the enclosing loop's back
                    // edge — _android_support 3.13 write: PJIF re-eval
                    // arrives with target threaded past the while's
                    // JUMP_BACKWARD to the for top)
                    || self
                        .idx_of
                        .get(&top.end)
                        .and_then(|&ei| self.instrs.get(ei))
                        .map_or(false, |x| {
                            x.target == Some(target)
                                && matches!(
                                    x.op,
                                    Op::JUMP_BACKWARD
                                        | Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        | Op::JUMP
                                        | Op::JUMP_FORWARD
                                )
                        })
                    || self.is_pop_block_before(target, top.end)
                    // 3.11+ rotated while whose post-loop flow is sunk
                    // returns: the exit return lands right before the
                    // function-tail return copy the block end points at
                    || self.is_term_pad_before(target, top.end, false)
                    // 3.11 per-operand duplicated epilogues: `while A
                    // and B:` gives each false exit its own `LOAD None;
                    // RETURN` stub, so operand B's jump lands one stub
                    // PAST the loop's recorded end (asynchat 3.11
                    // initiate_send rendered `while A:` + guard `if B:`).
                    // Bound to the cond region: a body jump must not
                    // reach this clause (the `if num_sent:` guard one
                    // instruction past the back edge was swallowed as a
                    // "duplicated cond" — the whole loop body sits
                    // between cond_end and any real operand-B jump)
                    || (target > top.end
                        && top.cond_end != usize::MAX
                        && self.cur_offset < top.cond_end + 96
                        && self.is_term_pad_before(top.end, target, true)))
                && ((top.cond_end != usize::MAX && top.cond_end < self.cur_offset)
                    // the SETUP_LOOP-era While (section 3b) never records
                    // cond_end; on 3.8+ the MAX sentinel means "opened by
                    // a non-cond mechanism" and must fall through instead
                    || (top.cond_end == usize::MAX
                        && !self.version.at_least(3, 8)))
        });
        if dup_while {
            let (mirrored, and_chain) = {
                let top = self.blocks.last().unwrap();
                // a genuine duplicated cond RE-EVALUATES the identical
                // operand run; a second AND operand shares the exit but
                // its region differs (2.7 `while A and B:` - ignoring it
                // lost the merge and left a spurious inner if)
                let m = match (
                    self.idx_of.get(&top.start),
                    self.idx_of.get(&top.cond_end),
                    self.idx_of.get(&self.cur_offset),
                ) {
                    (Some(&si), Some(&ci2), Some(&ui))
                        if ci2 > si && ci2 + (ci2 - si) <= ui =>
                    {
                        let n = ci2 - si;
                        self.instrs[ci2..ci2 + n]
                            .iter()
                            .zip(self.instrs[si..ci2].iter())
                            .all(|(a, b)| a.op == b.op && a.arg == b.arg)
                    }
                    _ => false,
                };
                // AND-chain continuation of an initialized While cond
                // (SETUP_LOOP era `while A and B:` - both links jump to
                // the loop's exit): merge when the operand region between
                // the two cond jumps is pure value
                // the SETUP_LOOP-era path (section 3b) leaves cond_end
                // at the MAX sentinel - fall back to the block start;
                // the first link's own cond jump is tolerated by the
                // same-chain rule inside the region scan
                let from = if top.cond_end == usize::MAX {
                    top.start
                } else {
                    top.cond_end
                };
                // 3.12+ rotated while re-eval copy: a plain back edge
                // follows this jump and the operand span re-evaluates the
                // While's recorded cond (single operand: _compression
                // 3.12/3.13 seek `while read():`; negated tail: cmd 3.12
                // columnize `while texts and not texts[-1]:`) — the span
                // is the loop's own cond copy, not a second and-operand.
                // A genuine and-chain contributes a DIFFERENT operand
                // (cmd 3.13 parseline, 3.9 `if A: while B:` merge shape).
                let back_edge_follows = self
                    .idx_of
                    .get(&self.cur_next)
                    .and_then(|&ni| self.instrs.get(ni))
                    .map_or(false, |nx| {
                        nx.is_backward
                            && matches!(
                                nx.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP
                            )
                    });
                let sim_eq = match (
                    self.idx_of
                        .get(&from)
                        .copied()
                        .zip(self.idx_of.get(&self.cur_offset).copied())
                        .and_then(|(fi, ci)| {
                            self.sim_value_region(fi, ci)
                        }),
                    top.cond.clone(),
                ) {
                    (Some(v), Some(c)) => {
                        format!("{:?}", simplify_not(v))
                            == format!("{:?}", simplify_not(c))
                    }
                    _ => false,
                };
                // multi-operand rotated re-eval whose LAST operand is the
                // negated tail (`while A and not B:` re-eval copy: PJF(A),
                // <B>, PJIT(B), JB top): the span before the tail's jump
                // re-evaluates the recorded cond (cmd 3.12 columnize's
                // `while texts and not texts[-1]:` re-eval merged into a
                // phantom duplicate while)
                let neg_tail_eq = {
                    (self
                        .idx_of
                        .get(&from)
                        .copied()
                        .zip(self.idx_of.get(&self.cur_offset).copied()))
                        .and_then(|(fi, ci)| {
                            let mut tj = None;
                            for k in fi..ci {
                                if matches!(
                                    self.instrs[k].op,
                                    Op::POP_JUMP_IF_FALSE
                                        | Op::POP_JUMP_FORWARD_IF_FALSE
                                        | Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_FORWARD_IF_TRUE
                                ) {
                                    tj = Some(k);
                                }
                            }
                            let tj = tj?;
                            let tail_pol = matches!(
                                self.instrs[tj].op,
                                Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                            );
                            if tail_pol == top.jump_if_true {
                                return None;
                            }
                            let v = self.sim_value_region(fi, tj)?;
                            let c = top.cond.clone()?;
                            Some(
                                format!("{:?}", simplify_not(v))
                                    == format!("{:?}", simplify_not(c)),
                            )
                        })
                        .unwrap_or(false)
                };
                let a = !m
                    && self.is_split_cond_region(
                        from,
                        self.cur_offset,
                        target,
                        jump_if_true,
                    )
                    && !(back_edge_follows && (sim_eq || neg_tail_eq));
                (m, a)
            };
            if mirrored {
                return;
            }
            let same_pol = self
                .blocks
                .last()
                .map_or(false, |t| t.jump_if_true == jump_if_true);
            if !and_chain {
                if same_pol {
                    // not a pure-value And continuation (e.g. a walrus tail
                    // re-eval carrying its STORE): historical behavior —
                    // treat as the rotated duplicate and ignore
                    return;
                }
                // a rotated MULTI-operand cond re-evaluates every operand
                // after the body: an opposite-polarity jump to the exit
                // past the cond region is one of those re-eval tests, not
                // an in-body guard (asynchat 3.11 find_prefix_at_end: the
                // re-eval PJF(l) rendered `if not l: break`). Single-
                // operand conds keep the guard/break reading.
                let (boolop_cond, past_cond) = self
                    .blocks
                    .last()
                    .map(|t| {
                        (
                            t.cond
                                .as_ref()
                                .map_or(false, |c| matches!(&**c, Expr::BoolOp { .. })),
                            t.cond_end != usize::MAX && self.cur_offset > t.cond_end,
                        )
                    })
                    .unwrap_or((false, false));
                if boolop_cond && past_cond {
                    return;
                }
                // opposite polarity without a pure-value operand region:
                // a genuine in-body branch toward the loop exit — fall
                // through to the guard/break handling below
            } else {
                let new_cond_end = self
                    .idx_of
                    .get(&self.cur_offset)
                    .and_then(|&ci| self.instrs.get(ci))
                    .map(|x| x.end())
                    .unwrap_or(self.cur_offset);
                if let Some(top) = self.blocks.last_mut() {
                    let prev = top.cond.take().unwrap();
                    let c2 = if jump_if_true {
                        negate_cond(cond)
                    } else {
                        cond
                    };
                    let mut values = Vec::new();
                    flatten_boolop(prev, BoolOpKind::And, &mut values);
                    flatten_boolop(c2, BoolOpKind::And, &mut values);
                    top.cond = Some(Rc::new(Expr::BoolOp {
                        op: BoolOpKind::And,
                        values,
                    }));
                    top.cond_end = new_cond_end;
                }
                // merged pre-check chain of a rotated while (csv 3.13
                // _guess_delimiter): convert to the real While now
                if self.try_pre_rot_fallthrough(target, jump_if_true) {
                    return;
                }
                return;
            }
        }

        // 3) BoolOp merge inside an open If whose end == target — only for
        // split conditions (`if a and b:` = two cond jumps over a pure
        // value region); a second independent if inside the body whose
        // exit happens to coincide must stay nested.
        //
        // Rotated-while veto: when the value region between the two jumps
        // is a loop's PREHEADER condition, the loop top follows this jump
        // with a re-evaluated condition (pure-value span ending in a
        // backward jump to the top). Merging would fold the guard into
        // the loop condition (`if size<0: while read(): pass` →
        // `while read() and size<0:` — 3.11 _compression.seek).
        let ins_limit = self.cur_offset.saturating_sub(
            self.blocks.last().map(|b| b.start).unwrap_or(self.cur_offset),
        );
        let rotated_while_follows = ins_limit > 0
            && ins_limit <= 256
            && self
            .idx_of
            .get(&self.cur_next)
            .map_or(false, |&ki| {
                let head = self.cur_next;
                let mut k = ki;
                let mut steps = 0;
                // bound: the re-eval span mirrors the value region
                // between the two cond jumps
                let span_limit = ins_limit.saturating_mul(2) + 8;
                while let Some(ins) = self.instrs.get(k) {
                    // a BACKWARD COND JUMP to the loop top ends the
                    // re-evaluation: this jump is a rotated while's first
                    // cond test (3.11 shape). 3.8-3.10 keep the plain
                    // POP_JUMP_IF_* names for backward jumps — the 3.10
                    // `while read(): pass` re-eval is a backward PJIT
                    // (_compression 3.10 seek: without it the pre-check
                    // PJIF fused into the guard's and-chain)
                    if ins.is_backward
                        && matches!(
                            ins.op,
                            Op::POP_JUMP_BACKWARD_IF_TRUE
                                | Op::POP_JUMP_BACKWARD_IF_FALSE
                                | Op::POP_JUMP_IF_TRUE
                                | Op::POP_JUMP_IF_FALSE
                                | Op::JUMP_IF_FALSE
                                | Op::JUMP_IF_TRUE
                        )
                    {
                        return steps > 0
                            && ins.target.map_or(false, |t| t >= head && t <= ins.offset);
                    }
                    // 3.12+ rotated while: the re-evaluated cond exits
                    // through a FORWARD PJIF and the back edge is a
                    // PLAIN JUMP_BACKWARD to the body top — a back edge
                    // re-running the scanned span is the same rotated
                    // while (_compression 3.12/3.13 seek: `if size<0:
                    // while read(): pass` folded into a 3-operand
                    // and-chain with a duplicated read call). Only a
                    // back edge whose target lies INSIDE the scanned
                    // span counts; an earlier loop's back edge (target
                    // before head) still fails the scan below.
                    if ins.is_backward
                        && matches!(
                            ins.op,
                            Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP
                        )
                    {
                        return steps > 0
                            && ins.target.map_or(false, |t| {
                                t >= head && t < ins.offset
                            });
                    }
                    if ins.is_backward || !is_pure_value_op(ins.op)
                        && !matches!(
                            ins.op,
                            Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE
                                | Op::TO_BOOL
                                | Op::POP_JUMP_IF_FALSE
                                | Op::POP_JUMP_IF_TRUE
                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                | Op::JUMP_IF_FALSE_OR_POP
                                | Op::JUMP_IF_TRUE_OR_POP
                        )
                    {
                        return false;
                    }
                    k += 1;
                    steps += 1;
                    if steps > span_limit {
                        return false;
                    }
                }
                false
            });
        // 3.12+ rotated while, second veto: this cond jump is the loop's
        // re-evaluated cond exit when a PLAIN backward jump follows it
        // immediately and lands inside [block.start, cur) — the back edge
        // to the body top. A genuine and-chain body never starts with a
        // backward jump into its own cond region (`if A and B: continue`
        // hops to the loop top BELOW the block start).
        let rotated_back_edge_after = self
            .blocks
            .last()
            .map_or(false, |top| {
                matches!(top.kind, BlockType::If)
                    && self
                        .idx_of
                        .get(&self.cur_next)
                        .and_then(|&ki| self.instrs.get(ki))
                        .map_or(false, |nx| {
                            nx.is_backward
                                && matches!(
                                    nx.op,
                                    Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        | Op::JUMP_ABSOLUTE
                                        | Op::JUMP
                                )
                                && nx.target.map_or(false, |t| {
                                    t >= top.start && t < self.cur_offset
                                })
                        })
            });
        // mixed-polarity links (PJIF(A) + PJIT(B), both targeting the
        // same skip) are `if A and not B:` — the c2 normalization below
        // already negates by THIS jump's polarity, so admitting the
        // mixed shape needs no other change. Without it the chain
        // renders nested, which only recompiles identically while no
        // else arm follows; with one (copyreg 3.8 _slotnames
        // `elif startswith and not endswith: ... else: append`) the
        // else arm flattened out of the chain
        // 3.8+ `if A: while B:` shared-exit shape: this cond jump is a
        // WHILE head, not an and-link, when a body back edge loops onto
        // THIS operand's own run [top.start, cur_offset). A genuine
        // `while A and B:` back edge re-runs the WHOLE chain and lands
        // before top.start; a back edge landing inside the second
        // operand's run means only that operand is re-evaluated
        // (cgi 3.8/3.9 read_binary `if todo >= 0: while todo > 0:`
        // fused into an and-chain and lost the loop).
        let pending_inner_while_head = self
            .blocks
            .last()
            .map_or(false, |top| {
                matches!(top.kind, BlockType::If)
                    && self.instrs.iter().any(|ins| {
                        ins.offset >= self.cur_next
                            && ins.offset < target
                            && ins.is_backward
                            && matches!(
                                ins.op,
                                Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP
                            )
                            && ins
                                .target
                                .map_or(false, |t| t >= top.start && t < self.cur_offset)
                    })
            });
        let split_cond = !rotated_while_follows
            && !rotated_back_edge_after
            && !pending_inner_while_head
            && self.blocks.last().map_or(false, |top| {
                matches!(top.kind, BlockType::If)
                    && (top.end == target
                        // 3.10 per-exit sunk tail duplication: inside a
                        // finally copy every false exit carries its OWN
                        // `LOAD v; RETURN` copy, so an and-chain's links
                        // target sibling copies instead of one shared
                        // exit (cmd 3.10 cmdloop finally `if
                        // use_rawinput and completekey:` — A's PJIF
                        // lands on return-copy 370, B's on 374).
                        // Identical value runs = the same source exit;
                        // merge and re-point the block at this link's
                        // copy.
                        || (self.equivalent_sunk_exit(top.end, target)
                            // the second link must not be a loop's
                            // cond: its exit can coincidentally be a
                            // sibling sunk copy of the guard's exit
                            // (cgi 3.11 read `if todo >= 0:` + `while
                            // todo > 0:` — merging ate the loop). A
                            // back edge inside the merged span onto a
                            // not-yet-open top is the while pre-check
                            // signature.
                            && !self.pending_while_back_edge(top.start, target)))
                    && top.cond_set
                    && top.short_circuit.is_none()
                    // a chain-exit clamped guard's opening jump flew to
                    // the chain tail, not to this shared target - the
                    // links of a split condition always share ONE
                    // target, so this is an independent nested guard
                    // (_strptime 3.3 ampm chain)
                    && top.clamp_from.is_none()
                    // 3.10+ rotated-while cond re-evaluation arrives as
                    // links whose merge is handled by the dup_while
                    // machinery; admitting mixed polarity there folds
                    // the re-eval into a nested guard and breaks the
                    // loop (b16 while_and 3.11, cmd 3.10
                    // `while texts and not texts[-1]`). <=3.9 needs the
                    // mixed merge for `A and not B` chains with else
                    // arms (copyreg _slotnames 3.8) — but only in that
                    // polarity order: a PJIT link followed by a PJIF
                    // link is `if not A:` + `if B:` nested, whose fused
                    // rendering recompiles UNARY_NOT + PJIF while the
                    // nested guards recompile PJIT + PJIF byte-exact
                    // (asyncore 3.5 handle_write_event)
                    && ((!self.version.at_least(3, 10)
                        && !(top.jump_if_true && !jump_if_true))
                        || top.jump_if_true == jump_if_true
                        // mixed polarity on 3.10+ is safe only INSIDE an
                        // already-open loop body with the shared target
                        // strictly before the loop's end: rotated-while
                        // conds/re-evals merge at loop setup time (no
                        // loop block open yet — b16 while_and 3.11/3.13,
                        // v38_walrus) or land on the loop exit (cmd 3.10
                        // re-eval, caught by find_loop_exit), while a
                        // statement-level `if A and not B: ... else:`
                        // lands on its else arm inside the loop body
                        // (copyreg 3.13/3.14 _slotnames elif chain — the
                        // nested rendering dropped the else arm out of
                        // the chain)
                        || self
                            .blocks
                            .iter()
                            .rev()
                            .find(|b| {
                                matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                )
                            })
                            .map_or(false, |b| {
                                b.start < top.start && target < b.end
                            })
                            && self.find_loop_exit(target).is_none()
                            // the chain body must not contain a WHILE
                            // back edge: a backward jump to a top that
                            // is strictly before this If chain and is
                            // not any open loop's top means the links
                            // are a pending while cond (`while A and
                            // not B:` in cmd 3.10 columnize — fusing
                            // into the If left a phantom
                            // `while texts: pass`), NOT a statement
                            // and-chain inside an established loop body
                            && !self.pending_while_back_edge(top.start, target)
                        // statement-level and-chain whose LAST link is
                        // jump-on-TRUE against a PJFF first link: either a
                        // NONE test (3.10+ compiles `is None` / `is not
                        // None` to the dedicated POP_JUMP_*_IF_(NOT_)NONE
                        // ops with jump-on-TRUE polarity — compileall 3.11
                        // compile_dir `if workers != 1 and
                        // ProcessPoolExecutor is not None:` rendered nested
                        // - the else arm attached to the inner if and the
                        // workers==1 path lost the serial loop), OR a plain
                        // negated tail `A and B and not C` whose `not C`
                        // compiles to a PJIT onto the SAME shared exit
                        // (compileall 3.11 _walk_dir `... and not
                        // os.path.islink(fullname)` rendered as a nested
                        // `if not islink:`). The rotated-while
                        // discriminator is pending_while_back_edge: a
                        // while's pre-check/re-eval span [top.start,
                        // target) holds the backward edge to its
                        // not-yet-open top (w310 columnize, b16 while_and),
                        // a statement and-chain's span does not. The
                        // opposite polarity (PJIT link then PJIF link =
                        // `if not A:` + `if B:` nested) stays rejected —
                        // its fused form recompiles UNARY_NOT + PJIF while
                        // the nested guards recompile PJIT + PJIF
                        // byte-exact (asyncore 3.5 handle_write_event).
                        || (self.version.at_least(3, 10)
                            && !top.jump_if_true
                            && jump_if_true
                            && self
                                .idx_of
                                .get(&self.cur_offset)
                                .and_then(|&ci| self.instrs.get(ci))
                                .map_or(false, |x| {
                                    matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_NONE
                                            | Op::POP_JUMP_FORWARD_IF_NONE
                                            | Op::POP_JUMP_BACKWARD_IF_NONE
                                            | Op::POP_JUMP_IF_NOT_NONE
                                            | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                                            | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                            | Op::POP_JUMP_BACKWARD_IF_TRUE
                                    )
                                })
                            && self.find_loop_exit(target).is_none()
                            && !self.is_loop_top_target(target)
                            && !self
                                .pending_while_back_edge(top.start, target))
                        // mirror NONE case: the FIRST link is the NONE
                        // test (`X is not None` compiles to PJF_NONE with
                        // raw jump-on-TRUE polarity, normalized to `is not
                        // None` at open) and the CURRENT link is a plain
                        // PJIF: `X is not None and Y` (compileall 3.11
                        // compile_file `limit_sl_dest is not None and
                        // os.path.islink(fullname)` rendered nested). The
                        // merged form is bytecode-identical to the nested
                        // guard-last-stmt shape (both links share ONE
                        // exit), so merging only matches source. The
                        // genuine `if not A: if B:` exclusion does NOT
                        // apply: there the top's opening jump is a PLAIN
                        // PJIT, not a NONE op — check the opening
                        // instruction (it ends exactly at top.start). Same
                        // three loop guards as the forward NONE case.
                        || (self.version.at_least(3, 10)
                            && top.jump_if_true
                            && !jump_if_true
                            && self
                                .instrs
                                .iter()
                                .find(|x| x.end() == top.start)
                                .map_or(false, |x| {
                                    matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_NONE
                                            | Op::POP_JUMP_FORWARD_IF_NONE
                                            | Op::POP_JUMP_BACKWARD_IF_NONE
                                            | Op::POP_JUMP_IF_NOT_NONE
                                            | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                                            | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                                    )
                                })
                            && self.find_loop_exit(target).is_none()
                            && !self.is_loop_top_target(target)
                            && !self
                                .pending_while_back_edge(top.start, target)))
                    && top.stmts.is_empty()
                    && self.is_split_cond_region(top.start, self.cur_offset, target, jump_if_true)
            });
if split_cond {
            if let Some(top) = self.blocks.last_mut() {
                if top.end != target {
                    // sibling sunk-copy exit: the merged chain now
                    // skips over on this link's target
                    top.end = target;
                }
                let prev = top.cond.take().unwrap();
                // two same-target cond jumps always AND: the body runs only
                // when NEITHER jump is taken (`if a and b` = two PJIFs,
                // `if not a and not b` = two PJITs)
                let kind = BoolOpKind::And;
                // `top.cond` stores the branch-taken polarity; the second
                // jump's operand must be normalized the same way (`if not a
                // and not b` compiles to two PJITs and must merge to
                // And(Not a, Not b))
                // branch-taken polarity: negate (cancels double negation
                // and inverts single-op comparisons)
                let c2 = if jump_if_true { negate_cond(cond) } else { cond };
                let mut values = Vec::new();
                flatten_boolop(prev, kind, &mut values);
                flatten_boolop(c2, kind, &mut values);
                top.cond = Some(Rc::new(Expr::BoolOp { op: kind, values }));
                if matches!(kind, BoolOpKind::And)
                    && self.try_pre_rot_fallthrough(target, jump_if_true)
                {
                    return;
                }
                return;
            }
        }

        // 3) uninitialized While block (SETUP_LOOP era): the first cond
        // jump is the loop condition only when its target region contains
        // the body back edge (`while True:` has no cond jump at all, and a
        // backward cond jump is handled below as the `if c: break` shape)
        let while_end = self
            .blocks
            .last()
            .filter(|b| matches!(b.kind, BlockType::While) && !b.cond_set)
            .map(|b| b.end);
        let cond_like = match (
            self.idx_of.get(&self.cur_offset),
            self.idx_of.get(&target),
            while_end.and_then(|e| self.idx_of.get(&e).copied()),
        ) {
            (Some(&ci), Some(&ti), Some(wei)) if ci < ti => {
                // the body must loop back to the top
                let region = &self.instrs[ci..ti];
                let back = region.iter().any(|i| i.is_backward);
                if !back {
                    false
                } else if Some(target) == while_end
                    || while_end.map_or(false, |we| self.is_pop_block_before(target, we))
                {
                    // PJIF straight to the loop exit (or its POP_BLOCK, the
                    // SETUP_LOOP-era exit shape): canonical `while c:`
                    true
                } else if wei > ti {
                    // while/else candidate: the else region [target, loop
                    // end) must contain no back edge, break, or return
                    let else_region = &self.instrs[ti..wei];
                    !else_region.iter().any(|i| {
                        i.is_backward
                            || i.op == Op::BREAK_LOOP
                            || matches!(i.op, Op::RETURN_VALUE | Op::RETURN_CONST)
                    }) && !region.iter().any(|i| i.op == Op::BREAK_LOOP)
                } else {
                    false
                }
            }
            _ => false,
        };
        let pop_block_equiv = self
            .blocks
            .last()
            .map_or(false, |b| self.is_pop_block_before(target, b.end));
        // ends of open If/Else blocks (collected before the mutable
        // borrow below): an arm-end skip may fly to any of them
        let open_chain_ends: Vec<usize> = self
            .blocks
            .iter()
            .filter(|b| matches!(b.kind, BlockType::If | BlockType::Else))
            .map(|b| b.end)
            .collect();
        if let Some(top) = self.blocks.last_mut() {
            if matches!(top.kind, BlockType::While) && !top.cond_set && cond_like {
                let c = if jump_if_true {
                    negate_cond(cond)
                } else {
                    cond
                };
                top.cond = Some(c);
                top.cond_set = true;
                top.jump_if_true = jump_if_true;
                if target != top.end && !pop_block_equiv {
                    // exit target differs from SETUP_LOOP end -> while/else
                    top.loop_else_end = Some(target);
                } else if pop_block_equiv && target < top.end {
                    // py2.6/2.7 while-else: the exit target IS the
                    // POP_BLOCK; code between it and the SETUP_LOOP target
                    // is the else body. End the loop at the POP_BLOCK so
                    // its close separates the else region.
                    if let Some(&pi) = self.idx_of.get(&target) {
                        let pb_end = self.instrs[pi].end();
                        // a forward JUMP at the POP_BLOCK's end targeting
                        // the loop end is an ENCLOSING branch's arm-end
                        // skip, not a fall-through into an else body:
                        // the span past it is the branch's else ARM
                        // (asyncore 3.5-3.7 loop: `if count is None:
                        // while map: ... else: while ...` — marking the
                        // arm as while-else nested the second loop
                        // under the first and the recompile lost the
                        // arm-end JF)
                        let arm_end_skip = self
                            .idx_of
                            .get(&pb_end)
                            .map_or(false, |&ji| {
                                let j = &self.instrs[ji];
                                !j.is_backward
                                    && matches!(
                                        j.op,
                                        Op::JUMP_FORWARD
                                            | Op::JUMP
                                            | Op::JUMP_ABSOLUTE
                                    )
                                    && (j.target == Some(top.end)
                                        // the arm-end skip of an
                                        // enclosing if/elif chain: the
                                        // loop is an arm's LAST
                                        // statement and its exit jump
                                        // flies over the remaining elif
                                        // arms to the chain end (an
                                        // open If/Else block's end).
                                        // py2.7 Queue put/get: the
                                        // SETUP_LOOP exit pointed at
                                        // the chain's merge trampoline
                                        // and [POP_BLOCK+1,
                                        // setup_target) misread as a
                                        // while-ELSE arm swallowed the
                                        // `elif timeout < 0:` and
                                        // timed-wait `else:` arms
                                        || j.target
                                            .map_or(false, |t| {
                                                open_chain_ends.contains(&t)
                                            }))
                            });
                        if !arm_end_skip {
                            top.loop_else_end = Some(top.end);
                        }
                        top.end = pb_end;
                    }
                }
                return;
            }
        }

        // 3c) SETUP_LOOP-era rotated while with a MULTI-JUMP condition
        // (`while a or b:`, 3.0-3.7): the first cond jump lands on the
        // BODY start and the following operand jumps land on the loop
        // exit (or the POP_BLOCK right before the SETUP_LOOP target).
        // Without this the loop degrades to `while True: if a or b:
        // <body>` -- the or-merge consumes the exit jump as the if's
        // skip, leaving the loop with NO exit path: a runtime INFINITE
        // LOOP whenever the condition starts false (b27_boolgroup
        // g_while_or, 3.5-3.7). Fold the operands (jump-to-body links
        // contribute positively, jump-to-exit links negated, Or-joined
        // in layout order -- the same convention section 6's 3.10+
        // multijump handler uses), decompile [body, back_edge) as the
        // loop body, and close the While right here.
        if !self.version.at_least(3, 8) {
            let while_info = self.blocks.last().and_then(|t| {
                if matches!(t.kind, BlockType::While)
                    && !t.cond_set
                    && t.start <= self.cur_offset
                    && target > self.cur_offset
                    && target < t.end
                {
                    Some((t.start, t.end))
                } else {
                    None
                }
            });
            if let Some((loop_start, while_end)) = while_info {
                let exit_ok = |t: usize| {
                    t == while_end || self.is_pop_block_before(t, while_end)
                };
                let is_cj = |o: Op| {
                    matches!(
                        o,
                        Op::POP_JUMP_IF_FALSE
                            | Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_FALSE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                    )
                };
                let is_jt = |o: Op| {
                    matches!(o, Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE)
                };
                let mut ok = false;
                if let (Some(&ci), Some(&ti)) =
                    (self.idx_of.get(&self.cur_offset), self.idx_of.get(&target))
                {
                    // J1 joins the body: it contributes positively when
                    // it jumps on TRUE, negated when it jumps on FALSE
                    let mut operands: Vec<ExprRef> = vec![if jump_if_true {
                        cond.clone()
                    } else {
                        simplify_not(cond.clone())
                    }];
                    let mut region_start = ci + 1;
                    let mut k = ci + 1;
                    let mut last_end = None;
                    let mut good = true;
                    while k < ti {
                        let ins = self.instrs[k];
                        if is_cj(ins.op) {
                            let t = match ins.target {
                                Some(t) => t,
                                None => {
                                    good = false;
                                    break;
                                }
                            };
                            if !exit_ok(t) {
                                good = false;
                                break;
                            }
                            match self.sim_value_region(region_start, k) {
                                Some(v) => {
                                    operands.push(if is_jt(ins.op) {
                                        simplify_not(v)
                                    } else {
                                        v
                                    });
                                }
                                None => {
                                    good = false;
                                    break;
                                }
                            }
                            last_end = Some(ins.end());
                            region_start = k + 1;
                        } else if !is_pure_value_op(ins.op)
                            && !matches!(
                                ins.op,
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG
                            )
                        {
                            good = false;
                            break;
                        }
                        k += 1;
                    }
                    // the last operand jump must land right at the body
                    // the body start may only be targeted by J1 itself
                    // (the or-join); any OTHER jump landing on it means a
                    // shared label / duplicated body -- not a plain
                    // rotated-while condition
                    let extra_target = self.instrs.iter().any(|x| {
                        x.offset != self.cur_offset && x.target == Some(target)
                    });
                    if good
                        && last_end == Some(target)
                        && operands.len() >= 2
                        && !extra_target
                    {
                        ok = true;
                    }
                    if ok {
                        let mut flat: Vec<ExprRef> = Vec::new();
                        for v in operands {
                            flatten_boolop(v, BoolOpKind::Or, &mut flat);
                        }
                        let merged = Rc::new(Expr::BoolOp {
                            op: BoolOpKind::Or,
                            values: flat,
                        });
                        // the loop's own back edge bounds the body
                        let back_edge = self
                            .idx_of
                            .get(&target)
                            .and_then(|&bi| {
                                self.instrs[bi..]
                                    .iter()
                                    .find(|x| {
                                        x.is_backward
                                            && x.target == Some(loop_start)
                                            && matches!(
                                                x.op,
                                                Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            )
                                    })
                                    .map(|x| x.offset)
                            })
                            .unwrap_or(while_end);
                        let body = self.decompile_region(target, back_edge);
                        let blk_idx = self
                            .blocks
                            .iter()
                            .rposition(|b| {
                                matches!(b.kind, BlockType::While)
                                    && b.start == loop_start
                                    && !b.cond_set
                            })
                            .unwrap();
                        let mut blk = self.blocks.remove(blk_idx);
                        blk.cond = Some(merged);
                        blk.stmts = body;
                        self.blocks.push(blk);
                        self.close_blocks_at(target);
                                                self.skip_until = Some(back_edge);
                        return;
                    }
                }
            }
        }

        // 4) except-block matching (3.10+ CHECK_EXC_MATCH style)
        if let Expr::Compare { operands, ops } = &*cond {
            if ops.len() == 1 && matches!(ops[0], CmpOp::ExceptionMatch) {
                let pattern = operands[1].clone();
                self.open_except_block(target, Some(pattern));
                return;
            }
        }

        // 5) assert detection. Canonical shape (all versions):
        //   <cond>; PJIT L; LOAD AssertionError; [<msg>; CALL 1]; RAISE 1; L:
        // i.e. the raise block is the jump's fall-through and the target
        // lands right after it.
        if jump_if_true {
            if let Some(msg) = self.is_assert_fallthrough(target) {
                self.push_stmt(Stmt::Assert { test: cond, msg });
                                self.skip_until = Some(target);
                return;
            }
            // multi-operand or-assert (3.12+ TO_BOOL chains and all
            // versions' or-forms): every operand success-jumps onto the
            // continuation past a shared raise block
            if let Some((extra, msg)) = self.try_or_assert(target) {
                let mut values = Vec::new();
                flatten_boolop(cond.clone(), BoolOpKind::Or, &mut values);
                flatten_boolop(extra, BoolOpKind::Or, &mut values);
                let test = Rc::new(Expr::BoolOp {
                    op: BoolOpKind::Or,
                    values,
                });
                self.push_stmt(Stmt::Assert { test, msg });
                self.skip_until = Some(target);
                return;
            }
        }
        // `assert not c` mirrors it: PJIF whose FALSE path skips the
        // fall-through raise block (source `if c: raise AssertionError`
        // is bytecode-identical; assert is the canonical reading)
        if !jump_if_true && !self.version.at_least(3, 12) {
            if let Some(msg) = self.is_assert_fallthrough(target) {
                self.push_stmt(Stmt::Assert {
                    test: negate_cond(cond),
                    msg,
                });
                                self.skip_until = Some(target);
                return;
            }
        }
        // `if not cond: raise AssertionError` written as a statement: the
        // raise block is the jump target
        if !jump_if_true && self.is_assert_target(target) {
            let msg = self.try_extract_assert_msg(target);
            self.push_stmt(Stmt::Assert {
                test: cond,
                msg,
            });
                        self.skip_until = Some(target);
            return;
        }

        // 5.5) backward conditional jumps inside loops
        if target < self.cur_offset {
            let n = self.blocks.len();
            for i in (0..n).rev() {
                if matches!(self.blocks[i].kind, BlockType::While | BlockType::For) {
                    let b = &self.blocks[i];
                    let matches_loop = b.start == target
                        || b.cond_end == target
                        || (b.start <= target && target < b.cond_end);
                    if !matches_loop {
                        continue;
                    }
                    // a nested `while c2:` whose exhaustion exit was
                    // threaded by the compiler onto the ENCLOSING loop's
                    // top: the fall-through region holds a backward
                    // unconditional jump to this condition's own expression
                    // top. Open the nested While BEFORE the or-continue
                    // chain machinery (the threading looks exactly like a
                    // fused continue head otherwise).
                    if !jump_if_true {
                        if let Some(&ci0) = self.idx_of.get(&self.cur_offset) {
                            let enclosing_top = self.blocks[i].start;
                            let is_ujump = |o: Op| {
                                matches!(
                                    o,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                            };
                            let mut wtop = None;
                            let mut wend = None;
                            for ins in self.instrs.iter().skip(ci0 + 1) {
                                if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                                    break;
                                }
                                if let Some(t) = ins.target {
                                    if ins.is_backward && is_ujump(ins.op) {
                                        if wtop.is_none()
                                            && t < self.cur_offset
                                            && self.is_cond_expr_top(t, self.cur_offset)
                                        {
                                            wtop = Some(t);
                                            continue;
                                        }
                                        if wtop.is_some() && t == enclosing_top
                                        {
                                            // enclosing-top back jump AFTER
                                            // the nested back edge: either
                                            // the nested `break` (body
                                            // continues after it) or the
                                            // exhaustion exit threading
                                            // (last one bounds the body) —
                                            // keep the LAST candidate (its
                                            // END, so the jump itself stays
                                            // inside the body for break
                                            // emission)
                                            wend = Some(ins.end());
                                        }
                                    }
                                }
                            }
                            if let (Some(wt), Some(we)) = (wtop, wend) {
                                let cond_end = self.instrs[ci0].end();
                                let mut blk = Block::new(BlockType::While, wt, we);
                                blk.cond = Some(cond);
                                blk.cond_set = true;
                                blk.cond_end = cond_end;
                                self.threaded_break_at.insert(we);
                                self.blocks.push(blk);
                                return;
                            }
                        }
                    }
                    // fused `if a or b: continue` chain: this jump carries
                    // the first operand straight to the loop top; the
                    // remaining operands and the continue body follow
                    if let Some((merged, body_start, body_end)) =
                        self.try_or_continue_chain(target, &cond)
                    {
                        // nested-guard vs fused-or discriminator: the
                        // first operand's jump target. A fused `if not A
                        // or B: continue` sends it to the CONTINUE
                        // trampoline — a backward jump with the rest of
                        // the loop body still following it. A NESTED
                        // `if A: if B: continue; rest` sends it to the
                        // loop's TAIL back edge — nothing but pads and
                        // the loop-exit machinery follow. The two forms
                        // recompile to different targets for this very
                        // jump (cmd 3.10 do_help: nested PJIF lands on
                        // the tail 338, the fused rendering recompiled
                        // to the rest-merge 260 — the module's only
                        // residual sig line; configparser 3.12
                        // RawConfigParser.__init__ is the genuine fused
                        // shape and keeps its merge).
                        // `target` arrives normalized to the loop top;
                        // the RAW jump target tells the two shapes apart
                        let raw_target = self
                            .idx_of
                            .get(&self.cur_offset)
                            .and_then(|&ci| self.instrs[ci].target)
                            .unwrap_or(target);
                        let loop_end = self
                            .blocks
                            .iter()
                            .rev()
                            .find(|b| {
                                matches!(
                                    b.kind,
                                    BlockType::While | BlockType::For
                                )
                            })
                            .map(|b| b.end);
                        let nested_tail_target = loop_end.map_or(false, |le| {
                            self.idx_of.get(&raw_target).map_or(false, |&ti| {
                                let t = &self.instrs[ti];
                                t.is_backward
                                    && matches!(
                                        t.op,
                                        Op::JUMP_ABSOLUTE
                                            | Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    )
                                    && !self.instrs[ti + 1..]
                                        .iter()
                                        .take_while(|x| x.offset < le)
                                        .any(|x| {
                                            !matches!(
                                                x.op,
                                                Op::NOP
                                                    | Op::NOT_TAKEN
                                                    | Op::CACHE
                                                    | Op::EXTENDED_ARG
                                                    | Op::JUMP_ABSOLUTE
                                                    | Op::JUMP_BACKWARD
                                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                                    | Op::JUMP_FORWARD
                                                    | Op::JUMP
                                                    | Op::POP_BLOCK
                                                    | Op::POP_TOP
                                                    | Op::FOR_ITER
                                                    | Op::END_FOR
                                                    | Op::END_SEND
                                            ) && !x.is_backward
                                        })
                            })
                        });
                        if !nested_tail_target {
                            let mut blk = Block::new(BlockType::If, body_start, body_end);
                            blk.cond = Some(merged);
                            blk.cond_set = true;
                            blk.stack_depth = self.stack.len();
                            self.blocks.push(blk);
                                                    self.skip_until = Some(body_start);
                            return;
                        }
                    }
                    if jump_if_true && self.blocks[i].cond_set {
                        // a GENUINE rotated-while back edge is the loop's
                        // last jump — no unconditional back edge follows
                        // it. When the forward region still holds the
                        // loop's JABS/JUMP_BACKWARD to its top (after a
                        // break/raise/continue block), this cond jump is
                        // `if c: continue`-style: fall through to the
                        // arm below that opens an If ending at that back
                        // edge instead of closing the loop here.
                        let loop_start0 = self.blocks[i].start;
                        let has_later_back_edge = self
                            .idx_of
                            .get(&self.cur_offset)
                            .map_or(false, |&ci0| {
                                self.instrs.iter().skip(ci0 + 1).any(|ins| {
                                    ins.is_backward
                                        && ins.target == Some(loop_start0)
                                        && matches!(
                                            ins.op,
                                            Op::JUMP_ABSOLUTE
                                                | Op::JUMP_BACKWARD
                                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        )
                                })
                            });
                        if !has_later_back_edge {
                            // 3.10+ rotated while back edge: close inner
                            // blocks, then the loop EXACTLY ONCE — its close
                            // may push a WhileElse continuation that must stay
                            // open for the else region that follows
                            while self.blocks.len() > i + 1 {
                                self.force_close_top(target);
                            }
                            self.force_close_top(target);
                            return;
                        }
                    }
                    // backward cond jump to the loop top (`if c: break` /
                    // `if not c: break` shape): the then-body runs until
                    // THIS loop's unconditional back edge (not a nested
                    // loop's)
                    let loop_start = self.blocks[i].start;
                    let loop_end = self.blocks[i].end;
                    if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                        for inst in self.instrs.iter().skip(ci + 1) {
                            if inst.is_backward
                                && inst.target == Some(loop_start)
                                && matches!(
                                    inst.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                )
                            {
                                // fused and-chain: the PREVIOUS operand's
                                // jump-to-loop-top opened a fused If over
                                // the SAME then-body (its end == this back
                                // edge) and is still open and empty — merge
                                // this operand into its cond instead of
                                // nesting a second guard (copyreg 3.3
                                // _reduce_ex `if hasattr(...) and not
                                // base.__flags__ & _HEAPTYPE: break`
                                // rendered nested: PJIT+JABS glue instead
                                // of UNARY_NOT+PJF)
                                let mergeable =
                                    self.blocks.last().map_or(false, |top| {
                                        matches!(top.kind, BlockType::If)
                                            && top.end == inst.start
                                            && top.cond_set
                                            && top.else_end.is_none()
                                            && top.short_circuit.is_none()
                                            && top.stmts.is_empty()
                                            && top.start < self.cur_offset
                                            && self.is_split_cond_region(
                                                top.start,
                                                self.cur_offset,
                                                inst.start,
                                                jump_if_true,
                                            )
                                    });
                                if mergeable {
                                    if let Some(top) = self.blocks.last_mut() {
                                        let prev = top.cond.take().unwrap();
                                        let c2 = if jump_if_true {
                                            negate_cond(cond.clone())
                                        } else {
                                            cond.clone()
                                        };
                                        let mut values = Vec::new();
                                        flatten_boolop(prev, BoolOpKind::And, &mut values);
                                        flatten_boolop(c2, BoolOpKind::And, &mut values);
                                        top.cond = Some(Rc::new(Expr::BoolOp {
                                            op: BoolOpKind::And,
                                            values,
                                        }));
                                    }
                                    // merged pre-check chain of a rotated
                                    // while (csv 3.13 _guess_delimiter):
                                    // convert to the real While now
                                    if self.try_pre_rot_fallthrough(target, jump_if_true) {
                                        return;
                                    }
                                    return;
                                }
                                let mut blk =
                                    Block::new(BlockType::If, self.cur_next, inst.start);
                                let c = if jump_if_true {
                                    negate_cond(cond.clone())
                                } else {
                                    cond.clone()
                                };
                                blk.cond = Some(c);
                                blk.cond_set = true;
                                self.blocks.push(blk);
                                return;
                            }
                            // a RETURN may sit inside the then region —
                            // 3.8/3.9 jump-threading leaves the loop's
                            // (dead) back edge AFTER it; only stop at a
                            // forward escape out of the loop that ISN'T
                            // a break chunk: `if c: stmt; break` keeps
                            // the structural back edge after the break's
                            // POP_TOP + jump-to-exit, and bailing there
                            // dropped the guard entirely (ast 3.8
                            // visit_Constant `if isinstance(value, cls):
                            // type_name = name; break`)
                            if inst.target.map_or(false, |t| {
                                t > inst.offset && self.find_loop_exit(t).is_some()
                            }) {
                                let prev_real = (ci..self.instrs.len())
                                    .rev()
                                    .find(|&k2| {
                                        k2 < self.instrs.iter().position(|x| std::ptr::eq(x, inst)).unwrap_or(0)
                                            && !matches!(
                                                self.instrs[k2].op,
                                                Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                            )
                                    });
                                // a forward jump onto THIS loop's own
                                // registered exit is the break itself
                                // (3.8 while-True break is a bare
                                // JABS->exit with no iterator pop —
                                // codecs 3.8 StreamReader.read `if not
                                // newdata: break`); a POP_TOP/POP_ITER
                                // prefix marks the for-break idiom
                                let is_break_chunk = inst
                                    .target
                                    .map_or(false, |t| t == loop_end)
                                    || prev_real.map_or(false, |k2| {
                                        matches!(
                                            self.instrs[k2].op,
                                            Op::POP_TOP | Op::POP_ITER
                                        )
                                    });
                                if !is_break_chunk {
                                    break;
                                }
                            }
                        }
                    }
                    return;
                }
            }
        }

        // 6) while loop (3.8+): a backward jump inside the jump-target
        // region that lands at the current instruction offset marks a loop.
        let cur = self.cur_offset;
        if std::env::var("PYCDC_S6_DBG").is_ok() {
            eprintln!("S6DBG: off={cur} target={target}");
        }
        if let (Some(&ci), Some(&ti)) = (self.idx_of.get(&cur), self.idx_of.get(&target)) {
            if ti > ci {
                // 3.13 pre-checked rotated while inside a loop
                // (_android_support 3.13 write: `for line in ...:
                // while line: <body>`): the pre-check PJIT jumps INTO
                // the body top (target) and its fall-through is a
                // backward jump onto the ENCLOSING loop's top (the
                // cond-false path is the outer continue); the body ends
                // with a re-eval of the same cond (forward cond jump +
                // backward jump to the body top) followed by the exit
                // edge. The regular admission below finds no back edge
                // landing on this cond's top, and the while-True
                // prescan then synthesizes a phantom `while True:` with
                // the re-eval rendered as `if line: continue` (and no
                // exit). Open the real While here instead.
                let pre_rot: Option<(usize, usize)> = 'pre_rot: {
                    // fall-through = backward jump onto an enclosing
                    // loop top
                    let mut f = ci + 1;
                    while matches!(
                        self.instrs.get(f).map(|x| x.op),
                        Some(Op::NOP)
                            | Some(Op::NOT_TAKEN)
                            | Some(Op::CACHE)
                            | Some(Op::EXTENDED_ARG)
                    ) {
                        f += 1;
                    }
                    let fall_ok = self.instrs.get(f).map_or(false, |x| {
                        x.is_backward
                            && matches!(
                                x.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::JUMP
                            )
                            && x.target.map_or(false, |ft| {
                                self.blocks.iter().any(|b| {
                                    matches!(
                                        b.kind,
                                        BlockType::While | BlockType::For
                                    ) && (b.start == ft
                                        || (b.cond_end != usize::MAX
                                            && b.cond_end == ft))
                                })
                            })
                    });
                    if !fall_ok {
                        break 'pre_rot None;
                    }
                    // body-tail re-eval: a forward cond jump followed
                    // (after pads) by a backward jump onto the body top
                    let mut rev: Option<(usize, usize)> = None;
                    let mut k = ti;
                    while k < self.instrs.len() {
                        let x = &self.instrs[k];
                        if x.offset.saturating_sub(target) > 4000 {
                            break;
                        }
                        if matches!(
                            x.op,
                            Op::POP_JUMP_IF_FALSE
                                | Op::POP_JUMP_IF_TRUE
                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                | Op::POP_JUMP_FORWARD_IF_TRUE
                        ) && !x.is_backward
                        {
                            let mut n = k + 1;
                            while matches!(
                                self.instrs.get(n).map(|y| y.op),
                                Some(Op::NOP)
                                    | Some(Op::NOT_TAKEN)
                                    | Some(Op::CACHE)
                            ) {
                                n += 1;
                            }
                            if let Some(y) = self.instrs.get(n) {
                                if y.is_backward
                                    && y.target == Some(target)
                                    && matches!(
                                        y.op,
                                        Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                            | Op::JUMP_ABSOLUTE
                                            | Op::JUMP
                                    )
                                {
                                    rev = x.target.map(|ex| (k, ex));
                                    break;
                                }
                            }
                        }
                        if matches!(
                            x.op,
                            Op::RETURN_VALUE | Op::RETURN_CONST | Op::END_FOR
                        ) {
                            break;
                        }
                        k += 1;
                    }
                    let Some((rj, reval_exit)) = rev else {
                        break 'pre_rot None;
                    };
                    // the re-eval's operand run must sim-equal this
                    // jump's cond
                    let mut s = rj;
                    while s > ti {
                        let p = self.instrs[s - 1].op;
                        if is_pure_value_op(p)
                            || matches!(
                                p,
                                Op::TO_BOOL
                                    | Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::CACHE
                            )
                        {
                            s -= 1;
                        } else {
                            break;
                        }
                    }
                    let cond_fmt = format!("{:?}", simplify_not(cond.clone()));
                    let ok = self.sim_value_region(s, rj).map_or(false, |v| {
                        format!("{:?}", simplify_not(v)) == cond_fmt
                    });
                    if ok {
                        Some((rj, reval_exit))
                    } else {
                        None
                    }
                };
                if let Some((_rj, reval_exit)) = pre_rot {
                    // cond_end = end of the PRE-CHECK jump: the dup_while
                    // re-eval matcher requires cond_end < cur_offset when
                    // the tail re-eval copy arrives (a later cond_end
                    // fails the clause and the re-eval renders as a
                    // degenerate `if line: continue` guard)
                    let cond_end = self.instrs[ci].end();
                    let mut blk = Block::new(BlockType::While, target, reval_exit);
                    // the jump enters the BODY on true: a PJIT pre-check
                    // means the source cond is the operand as-is
                    let wcond = if jump_if_true {
                        cond.clone()
                    } else {
                        negate_cond(cond.clone())
                    };
                    blk.cond = Some(wcond);
                    blk.cond_set = true;
                    blk.cond_end = cond_end;
                    blk.jump_if_true = !jump_if_true;
                    blk.stack_depth = self.stack.len();
                    self.blocks.push(blk);
                    self.skip_until = Some(target);
                    return;
                }
                if self.try_pre_rot_fallthrough(target, jump_if_true) {
                    return;
                }
                for inst in &self.instrs[ci..ti] {
                    if let Some(t) = inst.target {
                        // back edge to the cond jump itself or to the start
                        // of the condition expression (rotated while loops:
                        // the back edge skips the duplicated initial cond)
                        if std::env::var("PYCDC_S6_DBG").is_ok()
                            && inst.is_backward
                        {
                            eprintln!(
                                "S6DBG: back off={} t={t} cur={cur} next={} eq_cur={} eq_next={} cexpr={}",
                                inst.offset,
                                self.cur_next,
                                t == cur,
                                t == self.cur_next,
                                if t < cur { self.is_cond_expr_top(t, cur) } else { false }
                            );
                        }
                        // the back edge must belong to THIS cond, not
                        // to an inner loop whose cond top coincides with
                        // cur_next: a pure-value run from t ending in a
                        // forward cond jump that exits at/past `target`
                        // is an inner `while c:` head + its exit
                        // (asyncore 3.8 loop: the outer `if count is
                        // None:` PJIF@42 saw the inner while's back
                        // edge JABS@58->44 == cur_next and opened a
                        // phantom While, rendering `while count is
                        // None:` + while-else)
                        // pre-3.12 ONLY: 3.12+ rotated whiles re-eval
                        // the cond after the body with a forward PJIF
                        // exit + a plain JUMP_BACKWARD body-top edge —
                        // the same run shape (the S6 second-arm and
                        // _compression 3.12/3.13 seek rely on it)
                        let inner_cond_exit = |t: usize| -> bool {
                            if self.version.at_least(3, 12) {
                                return false;
                            }
                            self.idx_of.get(&t).map_or(false, |&tk| {
                                let mut k = tk;
                                let mut steps = 0;
                                while let Some(x) = self.instrs.get(k) {
                                    if matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                    ) {
                                        // the run ending at THIS jump is
                                        // its own cond expr, not an inner
                                        // loop's head
                                        if x.offset == self.cur_offset {
                                            return false;
                                        }
                                        return !x.is_backward
                                            && x.target
                                                .map_or(false, |xt| {
                                                    xt >= target
                                                });
                                    }
                                    if !is_pure_value_op(x.op)
                                        && !matches!(
                                            x.op,
                                            Op::NOP
                                                | Op::NOT_TAKEN
                                                | Op::CACHE
                                                | Op::TO_BOOL
                                        )
                                    {
                                        return false;
                                    }
                                    k += 1;
                                    steps += 1;
                                    if steps > 40 {
                                        return false;
                                    }
                                }
                                false
                            })
                        };
                        // a back edge landing on the cond jump's
                        // fall-through (the body top) never re-evaluates
                        // the cond: when that top is a SETUP_* (a try
                        // block re-entered each iteration) this is
                        // `if cond: while True: try: ...`, a one-shot
                        // guard around a while-True loop - registering a
                        // rotated While here fuses the guard into the loop
                        // cond (`while cond:`) and strands the loop's
                        // handler-break / following elif arms (_osx_support
                        // 3.9 compiler_fixup). The prescan while-True
                        // synthesis owns that top; this cond jump stays a
                        // plain If.
                        let setup_body_top = |off: usize| {
                            self.idx_of.get(&off).map_or(false, |&k| {
                                matches!(
                                    self.instrs[k].op,
                                    Op::SETUP_FINALLY
                                        | Op::SETUP_EXCEPT
                                        | Op::SETUP_CLEANUP
                                )
                            })
                        };
                        if inst.is_backward
                            && t < target
                            && (t == cur
                                || (t == self.cur_next
                                    && !inner_cond_exit(t)
                                    && !setup_body_top(t))
                                || (t < cur
                                    && self.is_cond_expr_top(t, cur)
                                    && !inner_cond_exit(t)))
                        {
                            let cond_end = self.instrs[ci].end();
                            let mut blk = Block::new(BlockType::While, t, target);
                            let mut wcond = if jump_if_true {
                                negate_cond(cond)
                            } else {
                                cond
                            };
                            // a rotated `while A and not B:` (3.11): the
                            // first operand's PJF opened an If shell that
                            // ends exactly at this jump's target and has
                            // collected nothing — A belongs to the while
                            // cond, not to a wrapper guard (asynchat 3.11
                            // find_prefix_at_end rendered `if l: while not
                            // endswith: ... if not l: break`)
                            let splice = self.blocks.last().map_or(false, |tp| {
                                matches!(tp.kind, BlockType::If)
                                    && tp.cond.is_some()
                                    && tp.end == target
                                    && tp.else_end.is_none()
                                    && tp.short_circuit.is_none()
                                    && tp.stmts.is_empty()
                                    && tp.start < cur
                            }) && {
                                // the loop region must RE-EVALUATE the
                                // shell cond: a cond jump to the exit
                                // inside (t, target) fed by a pure-value
                                // run that sim-equals the shell cond.
                                // A one-shot guard around a rotated while
                                // (`if size<0: while read(): pass`,
                                // _compression seek) has no such
                                // re-evaluation and must stay a guard.
                                self.blocks
                                    .last()
                                    .and_then(|tp| tp.cond.clone())
                                    .map_or(false, |ac| {
                                        let (Some(&bi), Some(&ei)) = (
                                            self.idx_of.get(&t),
                                            self.idx_of.get(&target),
                                        ) else {
                                            return false;
                                        };
                                        let mut cj = None;
                                        for k in bi..ei {
                                            let x = self.instrs[k];
                                            if matches!(
                                                x.op,
                                                Op::POP_JUMP_IF_FALSE
                                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                                    | Op::POP_JUMP_IF_TRUE
                                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                            ) && x.target == Some(target)
                                            {
                                                cj = Some(k);
                                                break;
                                            }
                                        }
                                        let Some(ck) = cj else {
                                            return false;
                                        };
                                        let mut s = ck;
                                        while s > bi
                                            && is_pure_value_op(self.instrs[s - 1].op)
                                        {
                                            s -= 1;
                                        }
                                        self.sim_value_region(s, ck).map_or(
                                            false,
                                            |v| {
                                                format!("{:?}", simplify_not(v))
                                                    == format!(
                                                        "{:?}",
                                                        simplify_not(ac)
                                                    )
                                            },
                                        )
                                    })
                            };
                            if splice {
                                let a_cond = self
                                    .blocks
                                    .last()
                                    .and_then(|tp| tp.cond.clone())
                                    .unwrap();
                                let mut flat = Vec::new();
                                flatten_boolop(a_cond, BoolOpKind::And, &mut flat);
                                flatten_boolop(wcond, BoolOpKind::And, &mut flat);
                                wcond = Rc::new(Expr::BoolOp {
                                    op: BoolOpKind::And,
                                    values: flat,
                                });
                                self.blocks.pop();
                            }
                            blk.cond = Some(wcond);
                            blk.cond_set = true;
                            blk.cond_end = cond_end;
                            blk.jump_if_true = jump_if_true;
                            self.blocks.push(blk);
                            return;
                        }
                        // rotated while with a MULTI-JUMP condition (3.10/
                        // 3.11 `while (x := f()) and g:`): the initial
                        // tests each exit-jump here, and the duplicated
                        // tail condition's backward TRUE-jump re-enters at
                        // the body top (t lies between this jump and the
                        // exit). Claim it: cond = the whole initial test
                        // chain, body = [t, target).
                        // the rotated back edge is a backward TRUE-jump
                        // (`while (x := f()) and g:`) or, for a negated
                        // tail operand, a backward FALSE-jump (`while l
                        // and not endswith(...):` re-eval ends in
                        // PJIB-to-body-top — asynchat 3.11
                        // find_prefix_at_end rendered `if l: while not
                        // ...: if not l: break`)
                        let rotated_reentry = if jump_if_true {
                            inst.is_backward
                                && matches!(
                                    inst.op,
                                    Op::POP_JUMP_BACKWARD_IF_FALSE
                                )
                        } else {
                            inst.is_backward
                                && matches!(
                                    inst.op,
                                    Op::POP_JUMP_IF_TRUE
                                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                                )
                        };
                        if rotated_reentry
                            && t >= self.cur_next
                            && t < target
                            && self.is_rotated_multijump_while(ci, ti, t)
                            // the re-entry must land at/past the merged
                            // chain's body top: a backward re-eval that
                            // jumps INTO the middle of the initial test
                            // chain means the loop's real cond starts
                            // there — the earlier tests are wrapper
                            // guards with their own exit stubs (cgi 3.11
                            // read_binary `if todo >= 0: while todo > 0:`
                            // fused into `while todo >= 0 and todo > 0:`,
                            // duplicating the first test in the re-eval)
                            && self
                                .merge_forward_cond_chain_bt(ci, target)
                                .map_or(true, |(_, bt)| t >= bt)
                        {
                            let mut blk = Block::new(BlockType::While, t, target);
                            let mut merged = cond.clone();
                            let mc = self.merge_forward_cond_chain(ci, target);
                            if let Some(c2) = mc {
                                let mut flat = Vec::new();
                                flatten_boolop(cond.clone(), BoolOpKind::And, &mut flat);
                                flatten_boolop(c2, BoolOpKind::And, &mut flat);
                                merged = Rc::new(Expr::BoolOp {
                                    op: BoolOpKind::And,
                                    values: flat,
                                });
                                // the tail re-eval must cover the WHOLE
                                // merged chain: a backward jump whose own
                                // operand run sim-equals only a SUFFIX
                                // means the earlier operands are wrapper
                                // guards with their own exit stubs, not
                                // loop cond (cgi 3.11 read_binary `if
                                // todo >= 0: while todo > 0:` — the
                                // re-eval re-ran only `todo > 0`; the
                                // fusion duplicated the first test in
                                // the recompiled re-eval)
                                let Some(&ii) = self.idx_of.get(&inst.offset) else {
                                    return;
                                };
                                // walk the re-eval copies backwards:
                                // pure-value runs separated by forward
                                // cond jumps that exit like the chain's
                                // own links (the loop exit or its own
                                // LOAD-None/RETURN stub)
                                let is_pad = |x: &crate::bytecode::Instruction| {
                                    matches!(
                                        x.op,
                                        Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::CACHE
                                            | Op::EXTENDED_ARG
                                    )
                                };
                                let exit_ok = |t2: usize| -> bool {
                                    if t2 == target {
                                        return true;
                                    }
                                    self.idx_of.get(&t2).map_or(false, |&xi| {
                                        matches!(
                                            self.instrs[xi].op,
                                            Op::LOAD_CONST | Op::RETURN_CONST
                                        ) && (matches!(
                                            self.instrs
                                                .get(xi + 1)
                                                .map(|x| x.op),
                                            Some(Op::RETURN_VALUE)
                                                | Some(Op::RETURN_CONST)
                                        ) || matches!(
                                            self.instrs[xi].op,
                                            Op::RETURN_CONST
                                        ))
                                    })
                                };
                                let mut reval_vals: Vec<ExprRef> = Vec::new();
                                let mut kk = ii;
                                let mut complete = true;
                                loop {
                                    let mut rs = kk;
                                    while rs > 0 {
                                        let p = &self.instrs[rs - 1];
                                        if is_pad(p)
                                            || is_pure_value_op(p.op)
                                            || matches!(p.op, Op::TO_BOOL)
                                        {
                                            rs -= 1;
                                        } else {
                                            break;
                                        }
                                    }
                                    match self.sim_value_region(rs, kk) {
                                        Some(v) => reval_vals.push(v),
                                        None => {
                                            complete = false;
                                            break;
                                        }
                                    }
                                    // continue past a preceding re-eval
                                    // link jump?
                                    let mut j = rs;
                                    while j > 0 && is_pad(&self.instrs[j - 1]) {
                                        j -= 1;
                                    }
                                    if j > 0 {
                                        let pj = &self.instrs[j - 1];
                                        if matches!(
                                            pj.op,
                                            Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                        ) && !pj.is_backward
                                            && pj.target.map_or(false, exit_ok)
                                        {
                                            kk = j - 1;
                                            continue;
                                        }
                                    }
                                    break;
                                }
                                if complete && !reval_vals.is_empty() {
                                    reval_vals.reverse();
                                    let mut flat_rv = Vec::new();
                                    for v in reval_vals {
                                        flatten_boolop(v, BoolOpKind::And, &mut flat_rv);
                                    }
                                    let rv: ExprRef = Rc::new(Expr::BoolOp {
                                        op: BoolOpKind::And,
                                        values: flat_rv,
                                    });
                                    if format!("{:?}", simplify_not(rv.clone()))
                                        != format!("{:?}", simplify_not(merged.clone()))
                                    {
                                        continue;
                                    }
                                }
                            }
                            // an operand tested BEFORE this jump into an
                            // enclosing If that ends exactly at this
                            // jump's target is the rotated while's first
                            // cond operand, not a wrapper guard: `while A
                            // and not B:` = PJF(A) opens If[.,172), the
                            // initial PJIT(B) lands here with the re-eval
                            // PJIB below (asynchat 3.11
                            // find_prefix_at_end rendered `if l: while
                            // not endswith: ... if not l: break`). Splice
                            // A in front, pop the shell If.
                            let splice = self.blocks.last().map_or(false, |tp| {
                                matches!(tp.kind, BlockType::If)
                                    && tp.cond.is_some()
                                    && tp.end == target
                                    && tp.else_end.is_none()
                                    && tp.short_circuit.is_none()
                                    && tp.stmts.is_empty()
                                    && tp.start < self.cur_offset
                            });
                            if splice {
                                let a_cond = self
                                    .blocks
                                    .last()
                                    .and_then(|tp| tp.cond.clone())
                                    .unwrap();
                                let mut flat = Vec::new();
                                flatten_boolop(a_cond, BoolOpKind::And, &mut flat);
                                flatten_boolop(merged, BoolOpKind::And, &mut flat);
                                merged = Rc::new(Expr::BoolOp {
                                    op: BoolOpKind::And,
                                    values: flat,
                                });
                                self.blocks.pop();
                            }
                            blk.cond = Some(merged);
                            blk.cond_set = true;
                            blk.cond_end = self.cur_next;
                            self.blocks.push(blk);
                            // skip the remaining initial-condition tests;
                            // resume at the body top
                                                        self.skip_until = Some(t);
                            return;
                        }
                    }
                }
            }
        }

        // 3.14+: `if c: break` compiles to a conditional jump straight to
        // the loop exit with the back edge as fall-through
        if self.find_loop_exit(target).is_some() {
            // jump-threaded `if c: <arm>; break`: the arm's terminal
            // unconditional jump targets the SAME loop exit as this cond
            // jump — the compiler threaded the if's merge through the
            // break (3.8/3.9 asynchat handle_read: `if index != lb:
            // collects; break`). The guard-break flip below would invert
            // the condition and duplicate the break; open the If with its
            // real merge at the terminal jump so the arm renders in the
            // original polarity and the terminal jump renders the
            // source-level break after the If.
            if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                let mut merge_at = None;
                let mut depth = 0usize;
                for x in self.instrs[ci + 1..].iter() {
                    if x.offset >= target {
                        break;
                    }
                    match x.op {
                        Op::JUMP_FORWARD
                        | Op::JUMP
                        | Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                            if !x.is_backward && x.target == Some(target) =>
                        {
                            if depth == 0 {
                                merge_at = Some(x.offset);
                            }
                            break;
                        }
                        Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_TRUE => {
                            // an and-chain sibling operand exiting to the
                            // SAME loop exit is not nesting (codecs 3.8
                            // readline `if line and not keepends: ...
                            // break` — the depth bump hid the terminal
                            // break jump and the first link flipped to a
                            // phantom `if not line: break`)
                            if x.target != Some(target) {
                                depth += 1;
                            }
                        }
                        Op::RETURN_VALUE | Op::RETURN_CONST | Op::RERAISE => {
                            break;
                        }
                        _ => {}
                    }
                }
                if let Some(m) = merge_at {
                    let c = if jump_if_true {
                        negate_cond(cond)
                    } else {
                        cond
                    };
                    let mut blk = Block::new(BlockType::If, self.cur_next, m);
                    blk.cond = Some(c);
                    blk.cond_set = true;
                    blk.jump_if_true = false;
                    blk.stack_depth = self.stack.len();
                    self.blocks.push(blk);
                    return;
                }
            }
            let c = if jump_if_true {
                cond
            } else {
                negate_cond(cond)
            };
            self.push_stmt(Stmt::If {
                cond: c,
                body: vec![Stmt::Break],
                orelse: Vec::new(),
            });
            return;
        }

        // py2/<=3.7: `if cond: stmt` at the END of a loop body compiles the
        // false-jump straight to the loop top (fusing skip and continue):
        // [PJIF loop_top; stmts; JUMP_ABS loop_top; JUMP_ABS loop_top]. The
        // then-body ends at the first backward jump to the loop top.
        if !jump_if_true {
            let loop_top = self
                .blocks
                .iter()
                .rev()
                .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
                .map(|b| b.start);
            if let Some(lt) = loop_top {
                if target == lt {
                    let mut then_end = None;
                    if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                        for ins in self.instrs.iter().skip(ci + 1) {
                            if ins.is_backward && ins.target == Some(lt) {
                                then_end = Some(ins.offset);
                                break;
                            }
                            if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                                break;
                            }
                            if ins.offset >= lt && lt > self.cur_offset {
                                break;
                            }
                        }
                    }
                    // fused and-chain: the PREVIOUS operand's PJIF opened
                    // a fused If over the same then-body (same backward
                    // terminus) and is still open and empty — merge this
                    // operand into its cond instead of nesting a second
                    // guard (copyreg 3.3 _reduce_ex `if hasattr(...) and
                    // not base.__flags__ & _HEAPTYPE: break` rendered as
                    // two nested ifs: PJIT+JABS glue instead of
                    // UNARY_NOT+PJF)
                    if let Some(te) = then_end {
                        let mergeable = self.blocks.last().map_or(false, |top| {
                            matches!(top.kind, BlockType::If)
                                && top.end == te
                                && top.cond_set
                                && top.else_end.is_none()
                                && top.short_circuit.is_none()
                                && top.stmts.is_empty()
                                && top.start < self.cur_offset
                                && self.is_split_cond_region(
                                    top.start,
                                    self.cur_offset,
                                    te,
                                    jump_if_true,
                                )
                        });
                        if mergeable {
                            if let Some(top) = self.blocks.last_mut() {
                                let prev = top.cond.take().unwrap();
                                let c2 = if jump_if_true {
                                    negate_cond(cond)
                                } else {
                                    cond
                                };
                                let mut values = Vec::new();
                                flatten_boolop(prev, BoolOpKind::And, &mut values);
                                flatten_boolop(c2, BoolOpKind::And, &mut values);
                                top.cond = Some(Rc::new(Expr::BoolOp {
                                    op: BoolOpKind::And,
                                    values,
                                }));
                            }
                            if self
                                .try_pre_rot_fallthrough(target, jump_if_true)
                            {
                                return;
                            }
                            return;
                        }
                    }
                    if let Some(te) = then_end {
                        let mut blk = Block::new(BlockType::If, self.cur_next, te);
                        blk.cond = Some(cond);
                        blk.cond_set = true;
                        blk.jump_if_true = false;
                        blk.stack_depth = self.stack.len();
                        self.blocks.push(blk);
                        return;
                    }
                }
            }
        }
        // close inner blocks that end at the current instruction before
        // opening the new one
        self.close_blocks_at(self.cur_offset);

        // 3.12/3.13 return-position ternary with CONSTANT arms: the
        // compiler expands `return A if C else B` into per-arm
        // LOAD_CONST + RETURN_VALUE, while a plain if/else return uses
        // RETURN_CONST arms — rendering the statement form recompiles
        // to RETURN_CONST and breaks sig-exactness (bz2 3.13 mode
        // property). Non-const arms are ambiguous (both forms compile
        // identically) and stay with the statement rendering. 3.14
        // compiles both forms identically — keep the statement there
        if self.version.at_least(3, 12) && !self.version.at_least(3, 14) {
            let arm = |start_off: usize| -> Option<(ExprRef, usize)> {
                let mut k = *self.idx_of.get(&start_off)?;
                self.match_skip_pad(&mut k);
                let ins = self.instrs.get(k)?;
                if ins.op != Op::LOAD_CONST {
                    return None;
                }
                let v = Rc::new(Expr::Const(
                    self.code.consts.get(ins.arg as usize)?.clone(),
                ));
                k += 1;
                self.match_skip_pad(&mut k);
                let r = self.instrs.get(k)?;
                if r.op != Op::RETURN_VALUE {
                    return None;
                }
                Some((v, r.end()))
            };
            if let (Some((t_val, t_end)), Some((e_val, e_end))) =
                (arm(self.cur_next), arm(target))
            {
                if t_end == target && e_end > target {
                    let (then_v, else_v) = if jump_if_true {
                        (e_val, t_val)
                    } else {
                        (t_val, e_val)
                    };
                    self.push_stmt(Stmt::Return(Some(Rc::new(
                        Expr::Ternary {
                            cond,
                            then_expr: then_v,
                            else_expr: else_v,
                        },
                    ))));
                    self.skip_until = Some(e_end);
                    return;
                }
            }
        }
        // an If opened here whose merge `target` is also the else_end of
        // an enclosing already-closed-arm If would swallow that else arm
        // (codecs 3.8 StreamReader.read: the handler's `if firstline:`
        // then-arm ends in `if len(lines)<=1: raise` whose no-else merge
        // is the POP_BLOCK PAST the outer `else: raise` — the flat inner
        // span ran the outer else raise into the inner then arm and lost
        // the arm-end JUMP_FORWARD). Clamp the span at the outer arm end
        // when the region between holds no other jump into [arm_end,
        // target): the arm is entered only by the outer cond jump, which
        // has already been consumed
        let mut if_end = target;
        // Some(original target) when the chain-exit clamp below lowers
        // if_end: the guard's opening jump flies to the chain tail, not
        // to the clamped end (see Block::clamp_from)
        let mut chain_exit_clamp: Option<usize> = None;
        // chain-exit guard: a cond jump inside an OPEN ELSE ARM whose
        // target ESCAPES the arm by landing on the chain-tail trampoline
        // (a back edge to the enclosing loop top past the arm's end) is
        // an elif-chain guard - its false exit flies to the loop
        // continue, but its fall-through body must terminate at the
        // arm's own merge edge. An If spanning past the arm end keeps
        // the arm open across the merge trampoline, and the arm-tail
        // back edge grows a spurious in-guard `continue` instead of
        // folding as the chain exit (_strptime 3.5/3.6 ampm chain:
        // If[88,152] straddled Else[76,110]; the arm rendered
        // `hour += 12; continue`). Nested guards of the same arm are
        // clamped too (`elif a == z: if h != 12:` - both false exits
        // fly to the chain tail). If-only arms are NEVER clamped on
        // their own: an escaping merge there is the shared if/else
        // confluence (the arm's else region falls through to the same
        // trampoline) and clamping fuses the If with its own else_start
        // (repro: the inner `if h == 12` merge 110 past Else[76,110]
        // clamped to 76, the arm folded as a chain exit and the elif
        // nested one level too deep).
        if if_end > self.cur_next {
            let is_tramp = |o: usize| {
                self.idx_of
                    .get(&o)
                    .and_then(|&ti| self.instrs.get(ti))
                    .map_or(false, |x| {
                        x.is_backward
                            && matches!(
                                x.op,
                                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP
                            )
                            && self.is_loop_top_target(x.target.unwrap_or(0))
                    })
            };
            let arm = self
                .blocks
                .iter()
                .rev()
                .find(|b| {
                    matches!(b.kind, BlockType::If | BlockType::Else)
                        && b.end != usize::MAX
                        && b.start <= self.cur_next
                        && b.end > self.cur_next
                });
            let escapes = arm
                .map(|b| (b.kind, b.start, b.end))
                .map_or(false, |(kind, astart, aend)| {
                    if_end > aend
                        && (kind == BlockType::Else
                            || self.blocks.iter().any(|e| {
                                e.kind == BlockType::Else
                                    && e.end != usize::MAX
                                    && e.start <= astart
                                    && aend <= e.end
                                    && if_end > e.end
                            }))
                });
            if escapes && is_tramp(if_end) {
                if let Some(b) = arm {
                    // LOCAL merge trampoline: the first targeted backward
                    // edge to the loop top within (cur_next, arm.end] is
                    // the chain's own continue merge - the guard body
                    // falls through into it. Clamping there (instead of
                    // blindly at the arm end) keeps a dead duplicate
                    // trampoline pair (arm-end JABS->merge; JABS->chain
                    // tail, pre-3.8 compilers) inside the arm region
                    // where the dup is inert glue; ending the guard
                    // BEFORE the pair lets the dup fire the chain fold
                    // with an empty spine and re-arm a phantom Else that
                    // flattens the remaining chain arms (_strptime 3.3
                    // ampm chain: the 1001 dup re-armed Else[1007,1599]
                    // and the M..Z arms sank under `else: continue`).
                    // No local trampoline: clamp at the arm end (the
                    // merge IS the arm boundary, _strptime 3.5/3.6).
                    let merge = self
                        .instrs
                        .iter()
                        .find(|x| {
                            x.offset > self.cur_next
                                && x.offset <= b.end
                                && x.is_backward
                                && matches!(
                                    x.op,
                                    Op::JUMP_ABSOLUTE
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP
                                )
                                && self
                                    .is_loop_top_target(x.target.unwrap_or(0))
                                && self.targets.contains(&x.offset)
                        })
                        .map(|x| x.offset);
                    chain_exit_clamp = Some(if_end);
                    if_end = merge.unwrap_or(b.end);
                }
            }
        }
        if !self.version.at_least(3, 11) {
            if let Some((outer_end, outer_else)) = self
                .blocks
                .iter()
                .rev()
                .find(|b| {
                    matches!(b.kind, BlockType::If)
                        && !b.jump_if_true
                        && b.else_end.is_none()
                        && b.end < target
                        && b.end > self.cur_next
                })
                .map(|b| (b.end, target))
            {
                // the outer's else-arm span [outer_end, target) must be a
                // plain terminator region (no jumps, at most a couple of
                // instructions), and this body's region must not jump
                // INTO the arm — the arm is entered only by the outer
                // cond jump, which has already been consumed
                let arm_plain = match (
                    self.idx_of.get(&outer_end),
                    self.idx_of.get(&target),
                ) {
                    (Some(&ae), Some(&be)) => {
                        be > ae
                            && be - ae <= 3
                            && self.instrs[ae..be]
                                .iter()
                                .all(|x| x.target.is_none())
                    }
                    _ => false,
                };
                // the inner then-arm must end in a terminator (its
                // arm-end skip is then fused with the else-skip by the
                // compiler, which is why the inner merge overshoots the
                // arm) — a plain inner if keeps its own arm-end skip and
                // the clamp would steal the OUTER else arm (py2
                // CGIHTTPServer translate_path `if path_parts: ... else:
                // tail_part = ''` reattached to the inner `if tail_part:`)
                let then_terminates = self
                    .idx_of
                    .get(&outer_end)
                    .map_or(false, |&be_idx| {
                        let mut t = be_idx;
                        while t > 0 {
                            t -= 1;
                            let p = &self.instrs[t];
                            if matches!(
                                p.op,
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE
                            ) {
                                continue;
                            }
                            // step over the arm-end skip(s) fused onto
                            // the inner merge
                            if !p.is_backward
                                && matches!(
                                    p.op,
                                    Op::JUMP_FORWARD
                                        | Op::JUMP
                                        | Op::JUMP_ABSOLUTE
                                )
                                && p.target == Some(target)
                            {
                                continue;
                            }
                            return matches!(
                                p.op,
                                Op::RETURN_VALUE
                                    | Op::RETURN_CONST
                                    | Op::RAISE_VARARGS
                                    | Op::RERAISE
                            );
                        }
                        false
                    });
                let span_clean = self
                    .idx_of
                    .get(&self.cur_next)
                    .zip(self.idx_of.get(&outer_end))
                    .map_or(false, |(a, b)| {
                        self.instrs[*a..*b].iter().all(|x| {
                            x.target.map_or(true, |t| {
                                t < outer_end || t >= outer_else
                            })
                        })
                    });
                if arm_plain && then_terminates && span_clean {
                    if_end = outer_end;
                }
            }
        }
        // 7) regular if statement: the fall-through region [next, target)
        // is the then-body. With POP_JUMP_IF_TRUE the fall-through runs when
        // the condition is false, so negate.
        // 3.14 exception: `if not A in B:` keeps the operand's CONTAINS/
        // IS/COMPARE op UNFLIPPED and inverts the jump instead (arm order
        // swaps; codecs make_encoding_map) — rendering the folded
        // `not in`/`is not` form recompiles to CONTAINS-NOT-IN + PJIF
        // and breaks sig-exactness. The explicit Unary Not reproduces
        // the original op+polarity
        // COPY/TO_BOOL + cond jump = value-preserving branch (3.12+ and/or
        // chains, chained comparisons); plain statements are guarded at
        // close time by requiring an empty body and a live stack value
        // TO_BOOL only marks a value-preserving branch when the jump
        // target holds the chain else-arm (SWAP 2; POP_TOP) — a plain
        // `if x:` in 3.13+ also carries TO_BOOL and must stay a statement
        // 3.13 value-form boolops interpose TO_BOOL between the COPY and
        // the cond jump — look through it via the instruction index
        let copy_to_bool_before = self
            .idx_of
            .get(&self.cur_offset)
            .map_or(false, |&bi| {
                bi >= 2
                    && self.instrs[bi - 1].op == Op::TO_BOOL
                    && self.instrs[bi - 2].op == Op::COPY
            });
        let value_merge = (matches!(self.prev_op_at_exec, Some(Op::COPY))
            || (matches!(self.prev_op_at_exec, Some(Op::TO_BOOL))
                && (copy_to_bool_before
                    || self.is_chain_else_arm(target)
                    || self.is_chain_else_arm_rot(target))))
        .then(|| {
                if jump_if_true {
                    BoolOpKind::Or
                } else {
                    BoolOpKind::And
                }
            });
        // value-merge operands contribute POSITIVELY (the COPY idiom
        // carries the operand value itself to the merge) — negating a
        // PJIT link folds its comparison and the close-time
        // simplify_not cannot recover it (calendar 3.13 isleap)
        let c = if jump_if_true && value_merge.is_none() {
            if self.version.at_least(3, 14) {
                simplify_not_or_wrap(cond)
            } else {
                negate_cond(cond)
            }
        } else {
            cond
        };
        // 3.14 value-position `A and B or C`: the whole chain merges here
        // (the per-jump value_merge blocks below would mis-nest it).
        // !jump_if_true path only, where `c` is `cond` un-negated.
        if !jump_if_true {
            if let Some((merged, m)) = self.try_value_and_or_314(&c, target) {
                self.push(merged);
                                self.skip_until = Some(m);
                return;
            }
        }
        // 3.12+ chained comparison: the then arm recomputes the next link
        // and merges at its own end (a consuming instruction or a forward
        // jump), NOT at the else arm (`SWAP 2; POP_TOP`) — closing there
        // would let the consumer eat the un-merged link value. A nested
        // link's arm holds another cond jump: keep the else-arm end so the
        // inner block closes first and the outer merges with its result.
        let chain_merge = match &value_merge {
            Some(BoolOpKind::And) if self.is_chain_else_arm(target) => {
                self.chain_then_merge(target)
            }
            _ => None,
        };
        let blk_end = chain_merge.unwrap_or(if_end);
        // shared-exit elif: the then body's terminal exit is a forward
        // conditional jump (a nested guard like `if j < 0: return j`)
        // flying PAST the else-arm head to a merge M that the arm also
        // reaches. The compiler fused the arm-end skip with the guard's
        // exit, so no JUMP_FORWARD out of the body marks the else region
        // and the chain detaches — the arm renders as top-level ifs that
        // RE-RUN after the then body (_markupbase 3.12/3.13
        // _parse_doctype_subset: `if c == '<': ... elif c == '%'` lost
        // the elif and raised "unexpected char '<'" on fall-through).
        // Mark else_end = M at creation so close attaches the Else arm
        // (the generic forward-jump marking at the body's JUMP_FORWARD
        // never fires — the body has none, only the guard's cond jump).
        let mut shared_exit_else: Option<usize> = None;
        if !jump_if_true
            && value_merge.is_none()
            && chain_merge.is_none()
            && blk_end == target
            && target > self.cur_next
        {
            if let (Some(&bi), Some(&ti)) =
                (self.idx_of.get(&self.cur_next), self.idx_of.get(&target))
            {
                // collect the merge M: every forward cond jump in the
                // body flying past the arm head must agree on one M, and
                // the body must not fall through into the arm (its last
                // meaningful instruction is a terminator or an
                // unconditional forward jump)
                let mut guard: Option<usize> = None;
                let mut guard_ok = true;
                let mut last_term = false;
                for k in bi..ti {
                    let x = &self.instrs[k];
                    if matches!(
                        x.op,
                        Op::NOP
                            | Op::NOT_TAKEN
                            | Op::CACHE
                            | Op::EXTENDED_ARG
                            | Op::RESUME
                    ) {
                        continue;
                    }
                    if matches!(
                        x.op,
                        Op::POP_JUMP_IF_FALSE
                            | Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_FALSE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                    ) {
                        if let Some(t) = x.target {
                            if t > target {
                                match guard {
                                    Some(m) if m == t => {}
                                    None => guard = Some(t),
                                    _ => guard_ok = false,
                                }
                            }
                        }
                    }
                    last_term = matches!(
                        x.op,
                        Op::RETURN_VALUE
                            | Op::RETURN_CONST
                            | Op::RAISE_VARARGS
                            | Op::RERAISE
                    ) || (!x.is_backward
                        && matches!(
                            x.op,
                            Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
                        ));
                }
                if !guard_ok || !last_term {
                    guard = None;
                }
                if let Some(m) = guard {
                    let body_start = self.cur_next;
                    // every body jump that reaches the arm head lands
                    // exactly on M (a jump onto `target` itself or past
                    // M would split/escape the arm region)
                    let body_exits_ok = self.instrs[bi..ti].iter().all(|x| {
                        x.is_backward
                            || x.target.map_or(true, |t| t < target || t == m)
                    });
                    let arm_ok = body_exits_ok
                        && self.idx_of.get(&m).map_or(false, |&mi| {
                        mi > ti
                            // the arm reaches M either by a forward jump
                            // landing on it (min_elif: the `%` arm's JF)
                            // or by pure fall-through (a straight-line
                            // else arm: _markupbase 3.12
                            // _parse_doctype_attlist `else: name,j=…`)
                            && (self.instrs[ti..mi].iter().any(|x| {
                                !x.is_backward
                                    && matches!(
                                        x.op,
                                        Op::JUMP_FORWARD
                                            | Op::JUMP_ABSOLUTE
                                            | Op::JUMP
                                    )
                                    && x.target == Some(m)
                            }) || self.is_straight_line_span(target, m))
                            // arm jumps never enter the then body and
                            // never fly past M (backward edges are
                            // continue back-edges, always fine)
                            && self.instrs[ti..mi].iter().all(|x| {
                                x.target.map_or(true, |t| {
                                    x.is_backward
                                        || (t < body_start || t >= target)
                                            && t <= m
                                })
                            })
                            // no OUTSIDE instruction (other than this
                            // If's own cond jump, already consumed)
                            // jumps into the arm region — the arm is
                            // entered only at its head
                            && self.instrs.iter().all(|x| {
                                (x.offset >= target && x.offset < m)
                                    || x.offset == self.cur_offset
                                    || !x.target.map_or(false, |t| {
                                        t >= target && t < m
                                    })
                            })
                    });
                    if arm_ok {
                        shared_exit_else = Some(m);
                    }
                }
            }
        }
        let mut blk = Block::new(BlockType::If, self.cur_next, blk_end);
        blk.clamp_from = chain_exit_clamp.filter(|_| blk_end == if_end);
        blk.merge_pos = value_merge.is_some();
        blk.value_merge = value_merge;
        blk.chain_link = matches!(&value_merge, Some(BoolOpKind::And))
            && self.is_chain_else_arm(target);
        blk.cond = Some(c);
        blk.cond_set = true;
        blk.jump_if_true = jump_if_true;
        blk.stack_depth = self.stack.len();
        blk.else_end = shared_exit_else;
        self.blocks.push(blk);
    }


    /// Detect the canonical `assert` raise block as the fall-through of a
    /// Multi-operand or-assert: `assert A or B [or C]` compiles every
    /// deciding operand to a success jump onto the continuation L which
    /// sits right past a shared fall-through raise block:
    ///   [A]; PJIT L; [pads]; [B]; PJFF L; [pads];
    ///   LOAD AssertionError; [<msg>; CALL 1]; RAISE 1; L:
    /// (each operand jumps on the polarity that DECIDES truth: PJIT
    /// contributes the operand, PJFF contributes its negation).
    /// Per-jump If rendering produced `if not A: if B: raise
    /// AssertionError` which recompiles to LOAD_GLOBAL AssertionError
    /// instead of the compiler's LOAD_COMMON_CONSTANT / assert shape
    /// (_pylong 3.14 compute_powers `assert need_hi or not extra`).
    /// Returns (merged test, msg) or None.
    fn try_or_assert(&self, target: usize) -> Option<(ExprRef, Option<ExprRef>)> {
        let &ci = self.idx_of.get(&self.cur_offset)?;
        if target <= self.cur_offset {
            return None;
        }
        let Some(&ti) = self.idx_of.get(&target) else {
            return None;
        };
        let mut parts: Vec<ExprRef> = Vec::new();
        let mut k = ci + 1;
        let mut region_start = ci + 1;
        let mut msg: Option<ExprRef> = None;
        let mut raise_ok = false;
        while k < ti {
            let ins = &self.instrs[k];
            match ins.op {
                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG => {
                    k += 1;
                }
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_FALSE
                | Op::POP_JUMP_BACKWARD_IF_TRUE => {
                    if ins.target != Some(target) {
                        return None;
                    }
                    if k <= region_start {
                        return None;
                    }
                    let Some(operand) = self
                        .sim_value_region(region_start, k)
                        .or_else(|| self.sim_value_region_ex(region_start, k, true))
                    else {
                        return None;
                    };
                    let jt = matches!(
                        ins.op,
                        Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                            | Op::POP_JUMP_BACKWARD_IF_TRUE
                    );
                    parts.push(if jt {
                        operand
                    } else {
                        Rc::new(Expr::Unary {
                            op: UnaryOp::Not,
                            operand,
                        })
                    });
                    k += 1;
                    region_start = k;
                }
                Op::LOAD_ASSERTION_ERROR => {
                    // raise block: must run to `target` with nothing but
                    // the msg expression left by this operand scan. An
                    // EMPTY parts list is the single-operand assert —
                    // leave it to is_assert_fallthrough.
                    if parts.is_empty() {
                        return None;
                    }
                    let (m, ok) = self.assert_raise_tail(k + 1, target)?;
                    msg = m;
                    raise_ok = ok;
                    break;
                }
                Op::LOAD_COMMON_CONSTANT if ins.arg == 0 => {
                    if parts.is_empty() {
                        return None;
                    }
                    let (m, ok) = self.assert_raise_tail(k + 1, target)?;
                    msg = m;
                    raise_ok = ok;
                    break;
                }
                Op::LOAD_GLOBAL | Op::LOAD_NAME
                    if !self.version.at_least(3, 9) =>
                {
                    let idx = if ins.op == Op::LOAD_GLOBAL
                        && self.version.at_least(3, 10)
                    {
                        (ins.arg as usize) >> 1
                    } else {
                        ins.arg as usize
                    };
                    if self.const_name(idx) != "AssertionError" {
                        return None;
                    }
                    if parts.is_empty() {
                        return None;
                    }
                    let (m, ok) = self.assert_raise_tail(k + 1, target)?;
                    msg = m;
                    raise_ok = ok;
                    break;
                }
                _ => {
                    if !is_pure_value_op(ins.op)
                        && !matches!(ins.op, Op::TO_BOOL)
                    {
                        return None;
                    }
                    k += 1;
                }
            }
        }
        if !raise_ok || parts.is_empty() {
            return None;
        }
        let mut values = Vec::new();
        for p in parts {
            flatten_boolop(p, BoolOpKind::Or, &mut values);
        }
        if values.is_empty() {
            return None;
        }
        let test = if values.len() == 1 {
            values.pop().unwrap()
        } else {
            Rc::new(Expr::BoolOp {
                op: BoolOpKind::Or,
                values,
            })
        };
        Some((test, msg))
    }

    /// The raise tail of an assert block starting at index `k`: pads,
    /// an optional msg expression + CALL 1, then RAISE_VARARGS 1
    /// landing exactly on `target`. Returns (msg, ok).
    fn assert_raise_tail(
        &self,
        k: usize,
        target: usize,
    ) -> Option<(Option<ExprRef>, bool)> {
        let Some(&ti) = self.idx_of.get(&target) else {
            return None;
        };
        let mut j = k;
        let mut raise_idx = None;
        let mut call_idx = None;
        while j < ti {
            let ins = &self.instrs[j];
            if matches!(ins.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE) {
                j += 1;
                continue;
            }
            if ins.op == Op::RAISE_VARARGS && ins.arg == 1 {
                raise_idx = Some(j);
                break;
            }
            if matches!(ins.op, Op::CALL | Op::CALL_FUNCTION) && ins.arg <= 1 {
                call_idx = Some(j);
            }
            if ins.target.is_some()
                && !matches!(ins.op, Op::CALL | Op::CALL_FUNCTION)
            {
                return Some((None, false));
            }
            if !is_pure_value_op(ins.op)
                && !matches!(ins.op, Op::TO_BOOL | Op::PUSH_NULL | Op::PRECALL)
            {
                return Some((None, false));
            }
            j += 1;
        }
        let Some(ri) = raise_idx else {
            return Some((None, false));
        };
        if self.effective_offset(self.instrs[ri].end())
            != self.effective_offset(target)
        {
            return Some((None, false));
        }
        let msg = match call_idx {
            Some(cj) if cj > k => self.sim_value_region(k, cj),
            _ => None,
        };
        Some((msg, true))
    }

    /// cond jump: returns Some(msg_option) when [cur_next, target) is
    /// exactly `LOAD AssertionError; [<msg expr>; CALL 1]; RAISE_VARARGS 1`.
    fn is_assert_fallthrough(&self, target: usize) -> Option<Option<ExprRef>> {
        let &i0 = self.idx_of.get(&self.cur_offset)?;
        let mut k = i0 + 1;
        loop {
            let skip = matches!(
                self.instrs.get(k).map(|x| x.op),
                Some(Op::TO_BOOL) | Some(Op::COPY) | Some(Op::NOP) | Some(Op::NOT_TAKEN)
            ) || (!self.version.at_least(3, 0)
                && matches!(self.instrs.get(k).map(|x| x.op), Some(Op::POP_TOP)));
            if !skip {
                break;
            }
            k += 1;
        }
        let err_load = match self.instrs.get(k) {
            Some(ins) if ins.op == Op::LOAD_ASSERTION_ERROR => true,
            // 3.14: LOAD_COMMON_CONSTANT arg 0 = AssertionError
            // (dis._common_constants)
            Some(ins) if ins.op == Op::LOAD_COMMON_CONSTANT => ins.arg == 0,
            // LOAD_GLOBAL/LOAD_NAME AssertionError is the assert shape
            // only PRE-3.9: 3.9 introduced the dedicated
            // LOAD_ASSERTION_ERROR (3.8 asserts still LOAD_GLOBAL, so
            // there the canonical reading stays assert), and from 3.9
            // on a LOAD_GLOBAL AssertionError is a manual `raise
            // AssertionError(...)` that must render as the raise
            // (asyncore 3.9 compact_traceback: `if not tb: raise
            // AssertionError(...)` rebuilt to `assert tb, ...` whose
            // recompile swapped in LOAD_ASSERTION_ERROR)
            Some(ins)
                if matches!(ins.op, Op::LOAD_GLOBAL | Op::LOAD_NAME)
                    && !self.version.at_least(3, 9) =>
            {
                let idx = if ins.op == Op::LOAD_GLOBAL && self.version.at_least(3, 10) {
                    (ins.arg as usize) >> 1
                } else {
                    ins.arg as usize
                };
                self.const_name(idx) == "AssertionError"
            }
            _ => false,
        };
        if !err_load {
            return None;
        }
        let msg_start = k + 1;
        // find the terminating RAISE_VARARGS 1; jumps (other than in msg
        // expressions we don't expect) invalidate the shape
        let mut raise_idx = None;
        let mut call_idx = None;
        let mut j = msg_start;
        while j < self.instrs.len() && j <= i0 + 60 {
            let ins = &self.instrs[j];
            if ins.op == Op::RAISE_VARARGS && ins.arg == 1 {
                raise_idx = Some(j);
                break;
            }
            if matches!(ins.op, Op::CALL | Op::CALL_FUNCTION) && ins.arg <= 1 {
                call_idx = Some(j);
            }
            if ins.target.is_some()
                && !matches!(ins.op, Op::CALL | Op::CALL_FUNCTION | Op::FOR_ITER)
            {
                return None;
            }
            if matches!(ins.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                return None;
            }
            j += 1;
        }
        let ri = raise_idx?;
        // the raise must land on `target`, possibly through dead padding
        // jumps (py2 emits JUMP_FORWARD 0 after the raise for BOTH the
        // assert and the manual-raise shape, so it proves nothing there).
        // 3.x: `assert` lands on the target DIRECTLY, while a manual
        // `if not c: raise AssertionError(...)` keeps an arm-end glue
        // JUMP_FORWARD (3.3 verified; 3.5-3.8 asserts have no glue) —
        // glue there means manual raise, not assert (asyncore 3.3
        // compact_traceback)
        let mut off = self.instrs[ri].end();
        loop {
            if self.effective_offset(off) == self.effective_offset(target) {
                break;
            }
            let advanced = match self.idx_of.get(&off) {
                Some(&pi) => {
                    let p = &self.instrs[pi];
                    if matches!(p.op, Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE)
                        && p.target == Some(target)
                    {
                        if self.version.major >= 3 {
                            return None;
                        }
                        let nxt = p.end();
                        off = nxt;
                        true
                    } else {
                        false
                    }
                }
                None => false,
            };
            if !advanced {
                return None;
            }
        }
        let msg = match call_idx {
            Some(ci2) if ci2 > msg_start && ci2 < ri => {
                self.sim_value_region(msg_start, ci2)
            }
            _ => None,
        };
        Some(msg)
    }

    /// True when every instruction in [from, to) is pure value computation.
    fn is_pure_value_region(&self, from: usize, to: usize) -> bool {
        let Some(&fi) = self.idx_of.get(&from) else {
            return false;
        };
        for ins in self.instrs.iter().skip(fi) {
            if ins.offset >= to {
                return true;
            }
            if !is_pure_value_op(ins.op) {
                return false;
            }
        }
        true
    }

    /// Like is_pure_value_region but tolerates the already-merged chain
    /// cond jumps (same polarity, same target) and padding — `if a and b
    /// and c:` has the first PJIF inside the [a, b, c) value region
    fn is_split_cond_region(
        &self,
        from: usize,
        to: usize,
        target: usize,
        _jump_if_true: bool,
    ) -> bool {
        let Some(&fi) = self.idx_of.get(&from) else {
            return false;
        };
        for ins in self.instrs.iter().skip(fi) {
            if ins.offset >= to {
                return true;
            }
            if matches!(ins.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE) {
                continue;
            }
            let same_chain_cj = matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
                    // 3.10+ NONE tests are chain links too (`X is not
                    // None` mid-chain compiles to POP_JUMP_*_IF_NONE
                    // onto the shared exit — code 3.13/3.14
                    // showsyntaxerror's 5-link chain split before the
                    // tail link when the NONE op failed this scan)
                    | Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_FORWARD_IF_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NONE
                    | Op::POP_JUMP_IF_NOT_NONE
                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                    | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
            ) && ins.target == Some(target);
            // polarity-free chain-link test: a cond jump onto the shared
            // exit IS a link of the and-chain whatever its jump polarity
            // — negated operands (`not X`) compile to PJITs onto the SAME
            // exit and may sit mid-chain (`A and not B and C`: PJIF, PJIT,
            // PJIF). Each operand's negation is normalized at its own
            // split_cond merge (c2 = negate_cond for PJIT links), so the
            // region scan only confirms these are links of ONE
            // shared-exit chain, not nested guards (which target their
            // own body/else end, != target) (compileall 3.11 _walk_dir
            // `... and not os.path.islink`; code 3.13/3.14
            // showsyntaxerror `source and typ is SyntaxError and not
            // value.text and value.lineno is not None and len(lines) >=
            // value.lineno` split before link 5 when the mid-chain PJIT
            // was polarity-rejected against the PJIF tail link)
            if !is_pure_value_op(ins.op) && !same_chain_cj {
                return false;
            }
        }
        true
    }

    /// 3.12+ chained-comparison else arm: `SWAP 2; POP_TOP` at the jump
    /// target (keeps the comparison result, drops the shared operand).
    fn is_chain_else_arm(&self, target: usize) -> bool {
        let Some(&i) = self.idx_of.get(&target) else {
            return false;
        };
        matches!(self.instrs.get(i).map(|x| x.op), Some(Op::SWAP))
            && matches!(self.instrs.get(i + 1).map(|x| x.op), Some(Op::POP_TOP))
    }

    /// <=3.11 chained-comparison else arm: `ROT_TWO; POP_TOP` at the
    /// JUMP_IF_FALSE_OR_POP target.
    fn is_chain_else_arm_rot(&self, target: usize) -> bool {
        let Some(&i) = self.idx_of.get(&target) else {
            return false;
        };
        matches!(self.instrs.get(i).map(|x| x.op), Some(Op::ROT_TWO))
            && matches!(self.instrs.get(i + 1).map(|x| x.op), Some(Op::POP_TOP))
    }

    /// True when every instruction in [from, to) is compiler padding
    /// (NOT_TAKEN/NOP/CACHE) — 3.14 pads `if c: break` trampolines with
    /// NOT_TAKEN between the block start and its back edge.
    fn padding_only_between(&self, from: usize, to: usize) -> bool {
        if from >= to {
            return false;
        }
        // `from`/`to` may land on an EXTENDED_ARG prefix byte, which
        // idx_of does not key (it keys post-prefix offsets and ends,
        // and the prefix start collides with the PREVIOUS instruction's
        // end) — resolve to the instruction whose `start` covers the
        // offset. EXTENDED_ARG is jump ENCODING, not a statement: count
        // it as padding (cgitb 3.8/3.9 html `if name in done:
        // continue` — the guard arm is `EXTARG; JABS` and starts at the
        // EXTARG byte; the emptiness check failed, jfold read the
        // explicit continue as a fused chain exit and wrapped the rest
        // of the loop body into a folded Else[MAX] region).
        let resolve = |off: usize| -> Option<usize> {
            if let Some(i) = self.instrs.iter().position(|x| x.start == off) {
                return Some(i);
            }
            self.idx_of.get(&off).copied()
        };
        let (Some(a), Some(b)) = (resolve(from), resolve(to)) else {
            return false;
        };
        (a..b).all(|k| {
            matches!(
                self.instrs[k].op,
                Op::NOT_TAKEN | Op::NOP | Op::CACHE | Op::EXTENDED_ARG
            )
        })
    }

    /// Arm a skip for a value-merge block's false-path region. py2.6
    /// chained comparisons close at (or after) the else arm's own offset,
    /// leaving `skip_until = else_end` stale — the `ROT_TWO; POP_TOP`
    /// cleanup would still run and eat the merged chain value. When the
    /// arm starts at or behind the current position, skip past it.
    fn skip_chain_else_arm(&mut self, else_end: usize) {
        let mut skip = else_end;
        if else_end <= self.cur_offset
            && (self.is_chain_else_arm_rot(else_end) || self.is_chain_else_arm(else_end))
        {
            if let Some(&i) = self.idx_of.get(&else_end) {
                if let Some(pop) = self.instrs.get(i + 1) {
                    skip = pop.end();
                }
            }
        }
                self.skip_until = Some(skip);
    }

    /// Merge offset of a chained-comparison then arm: scan pure value ops
    /// from `from` — a closing jump gives its target, any consuming op is
    /// the merge itself. `None` when the arm holds a nested link (a
    /// conditional jump): the nested block closes first and the outer
    /// link falls back to the shared else-arm offset.
    fn chain_then_merge_from(&self, from: usize, target: usize) -> Option<usize> {
        let ci = self.idx_of.get(&from).copied()?;
        // a consumer only ends the arm AFTER the link's comparison has
        // been seen — a CALL inside the NEXT OPERAND's computation (e.g.
        // `r = a() < b() < c()`) is part of the arm, not its merge
        let mut link_done = false;
        for ins in self.instrs.iter().skip(ci) {
            if ins.offset >= target {
                return None;
            }
            if matches!(ins.op, Op::NOT_TAKEN | Op::NOP | Op::CACHE) {
                continue;
            }
            match ins.op {
                Op::JUMP_FORWARD | Op::JUMP => return ins.target,
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_FALSE
                | Op::POP_JUMP_BACKWARD_IF_TRUE
                | Op::JUMP_IF_FALSE_OR_POP
                | Op::JUMP_IF_TRUE_OR_POP
                | Op::JUMP_IF_FALSE
                | Op::JUMP_IF_TRUE => return None,
                // stack shuffles inside the arm (a nested link sets its
                // operands up with SWAP/COPY) are not consumers
                Op::SWAP
                | Op::ROT_TWO
                | Op::ROT_THREE
                | Op::ROT_FOUR
                | Op::ROT_N
                | Op::DUP_TOP
                | Op::DUP_TOP_TWO => continue,
                Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP => {
                    link_done = true;
                    continue;
                }
                // consumers of the link value end the arm right here —
                // CALL is value-pure in general but eats the chain result
                // as an argument, so it must not be scanned past
                Op::CALL
                | Op::CALL_FUNCTION
                | Op::CALL_METHOD
                | Op::CALL_FUNCTION_KW
                | Op::CALL_FUNCTION_EX
                | Op::POP_TOP
                | Op::RETURN_VALUE
                | Op::RETURN_CONST
                | Op::YIELD_VALUE
                | Op::STORE_NAME
                | Op::STORE_FAST
                | Op::STORE_DEREF
                | Op::STORE_ATTR
                | Op::STORE_SUBSCR
                | Op::STORE_GLOBAL => {
                    if link_done {
                        return Some(ins.offset);
                    }
                    continue;
                }
                op if is_pure_value_op(op) => continue,
                _ => return Some(ins.offset),
            }
        }
        None
    }

    /// 3.12+ chain then-arm: starts with the POP_TOP that drops the
    /// retained link value, then the next link's computation. 3.14 pads
    /// the arm head with NOT_TAKEN.
    fn chain_then_merge(&self, target: usize) -> Option<usize> {
        let mut ci = self.idx_of.get(&self.cur_next).copied()?;
        while matches!(
            self.instrs.get(ci).map(|x| x.op),
            Some(Op::NOT_TAKEN) | Some(Op::NOP) | Some(Op::CACHE)
        ) {
            ci += 1;
        }
        if self.instrs.get(ci)?.op != Op::POP_TOP {
            return None;
        }
        self.chain_then_merge_from(self.instrs[ci].end(), target)
    }

    /// True when the code at `target` immediately raises AssertionError.
    fn is_assert_target(&self, target: usize) -> bool {
        let Some(&i) = self.idx_of.get(&target) else {
            return false;
        };
        // 3.10+: [TO_BOOL?] LOAD_ASSERTION_ERROR RAISE_VARARGS 1
        // <=3.9: LOAD_ASSERTION_ERROR RAISE_VARARGS 1
        let instrs = &self.instrs;
        let mut k = i;
        // skip harmless prologue ops
        while matches!(
            instrs.get(k).map(|x| x.op),
            Some(Op::TO_BOOL) | Some(Op::COPY) | Some(Op::POP_TOP)
        ) {
            k += 1;
        }
        if instrs.get(k).map(|x| x.op) != Some(Op::LOAD_ASSERTION_ERROR) {
            return false;
        }
        k += 1;
        // optional: message expression then RAISE_VARARGS 2
        matches!(instrs.get(k).map(|x| (x.op, x.arg)), Some((Op::RAISE_VARARGS, 1)))
            || self.scan_to_raise2(k)
    }

    fn scan_to_raise2(&self, from: usize) -> bool {
        let mut k = from;
        let mut steps = 0;
        while let Some(inst) = self.instrs.get(k) {
            match inst.op {
                Op::RAISE_VARARGS => return inst.arg == 2,
                Op::LOAD_ASSERTION_ERROR | Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_IF_TRUE => {
                    return false
                }
                _ => {
                    k += 1;
                    steps += 1;
                    if steps > 16 {
                        return false;
                    }
                }
            }
        }
        false
    }

    /// Simulate the message expression between LOAD_ASSERTION_ERROR and
    /// RAISE_VARARGS 2 (constant messages only, which is the common case).
    fn try_extract_assert_msg(&self, target: usize) -> Option<ExprRef> {
        let &i = self.idx_of.get(&target)?;
        let instrs = &self.instrs;
        let mut k = i;
        while matches!(instrs.get(k).map(|x| x.op), Some(Op::TO_BOOL) | Some(Op::COPY)) {
            k += 1;
        }
        if instrs.get(k).map(|x| x.op) != Some(Op::LOAD_ASSERTION_ERROR) {
            return None;
        }
        k += 1;
        // expect: LOAD_CONST <msg>; RAISE_VARARGS 2
        if instrs.get(k).map(|x| x.op) == Some(Op::LOAD_CONST)
            && instrs.get(k + 1).map(|x| (x.op, x.arg)) == Some((Op::RAISE_VARARGS, 2))
        {
            let idx = instrs[k].arg as usize;
            return self.code.consts.get(idx).map(|o| Rc::new(Expr::Const(o.clone())));
        }
        None
    }

    /// A pending mismatch target still holds an unparsed clause head:
    /// a typed clause starts with DUP_TOP (the dispatch); a BARE
    /// `except:` clause starts with the POP_TOP x3 prelude and runs
    /// its body to a POP_EXCEPT exit — while the chain's dead
    /// mismatch-cleanup tail also starts with POP_TOP x3 but folds
    /// straight into END_FINALLY (asyncore 3.8 close_all: the bare
    /// third clause at the mismatch target read as cleanup, the chain
    /// emitted after clause 2 and the `except:` body leaked to
    /// function level)
    fn pending_clause_head_at(&self, m: usize) -> bool {
        let Some(&mi) = self.idx_of.get(&m) else {
            return false;
        };
        if self.instrs.get(mi).map(|x| x.op) == Some(Op::DUP_TOP) {
            return true;
        }
        let mut k = mi;
        let mut pops = 0;
        while pops < 3 && self.instrs.get(k).map(|x| x.op) == Some(Op::POP_TOP) {
            k += 1;
            pops += 1;
        }
        if pops < 3 {
            return false;
        }
        let mut saw_stmt = false;
        for x in self.instrs[k..].iter().take(80) {
            match x.op {
                Op::POP_EXCEPT => return saw_stmt,
                Op::END_FINALLY => return false,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE => {}
                _ => saw_stmt = true,
            }
        }
        false
    }

    fn open_except_block(&mut self, target: usize, pattern: Option<ExprRef>) {
        if self.legacy_try.is_some() {
            // handler body collects into the legacy handler, not a block
            self.legacy_handler = Some(LegacyHandler {
                type_: pattern,
                name: None,
                body: Vec::new(),
                block_depth: self.blocks.len(),
                pop_seen: false, bare_raise_fold: false,
            });
            // a previous handler's unconfirmed cleanup marker must not
            // swallow this handler's `as` name store
            self.pending_as_cleanup = None;
            self.held_cleanup_store = None;
            self.legacy_handler_end = Some(target);
            if let Some(l) = self.legacy_try.as_mut() {
                l.pending_mismatch.push(target);
            }
            self.in_handler_prelude = true;
            return;
        }
        // The Try block on the stack ends at the handler start (== where we
        // are now). Open an Except block ending at `target` (the jump out of
        // the handler).
        let start = self.blocks.last().map(|b| b.end).unwrap_or(0);
        let mut eb = Block::new(BlockType::Except, start, target);
        eb.handler_type = pattern;
        self.blocks.push(eb);
    }

    /// JUMP_IF_TRUE_OR_POP / JUMP_IF_FALSE_OR_POP: begin a short-circuit
    /// region. The value stays on the stack; at the target we merge.
    fn handle_short_circuit(&mut self, or_form: bool, target: usize) {
        // tail-duplicated body copy: the else path is a verbatim copy of
        // the terminating then body — the link still merges into it
        let dup_body = self.dup_copy_redirect.contains_key(&target);
        let target = self.dup_copy_redirect.get(&target).copied().unwrap_or(target);
        // pycdc-style: mark a pending merge by pushing an If block whose
        // "cond" is the left operand; closing merges into BoolOp.
        let left = self.pop_expr();
        // <=3.11 chained comparison: the else arm at `target` is
        // ROT_TWO/POP_TOP (<=3.10) or SWAP 2/POP_TOP (3.11) and the then
        // arm's consumer (CALL/STORE/...) is the real merge — end the
        // block there so the value merges before the consumer runs.
        // Without this the else-arm SWAP executes against the live stack
        // (rotating the enclosing call's operands) before the close skips
        // its POP_TOP.
        let chain = !or_form
            && (self.is_chain_else_arm_rot(target)
                || self.is_chain_else_arm(target)
                || dup_body);
        let blk_end = if chain {
            self.chain_then_merge_from(self.cur_next, target)
                .unwrap_or(target)
        } else {
            target
        };
        let mut blk = Block::new(BlockType::If, self.cur_next, blk_end);
        blk.cond = Some(left);
        blk.cond_set = true;
        blk.short_circuit = Some(or_form);
        blk.chain_link = chain;
        blk.stack_depth = self.stack.len();
        self.blocks.push(blk);
    }

    /// 3.8-3.10 try/finally inside a loop with break: the break path
    /// inlines the finally copy and jumps out —
    ///   FOR; SETUP_FIN h; <cond>; PJIF b2; POP_BLOCK;
    ///   <copy>; JF/JABS exit; b2:<body2>; POP_BLOCK; <copy>; JB FOR
    ///   h: <copy>; RERAISE; exit: ...
    /// Rebuild the split try from spans; the loop closes at the exit
    /// landing (its end == FOR_ITER's exit target). Returns true when
    /// the jump was consumed.
    fn legacy_split_finally_rebuild(&mut self, target: usize) -> bool {
                // 3.8-3.10 try/finally inside a loop with break: the
                // break path inlines the finally copy and jumps out —
                //   FOR; SETUP_FIN h; <cond>; PJIF b2; POP_BLOCK;
                //   <copy>; JF exit; b2:<body2>; POP_BLOCK; <copy>; JB FOR
                //   h: <copy>; RERAISE; exit: ...
                // rebuild the split try from spans; the loop closes at
                // the exit landing (its end == FOR_ITER's exit target)
                if !self.version.at_least(3, 11)
                    && matches!(
                        self.blocks.last().map(|b| b.kind),
                        Some(BlockType::If)
                    )
                    && target > self.cur_offset
                {
                    let n = self.blocks.len();
                    let ii = n - 1;
                    let ti = (0..ii).rev().find(|&i| self.blocks[i].kind == BlockType::Try);
                    let has_loop = self
                        .blocks
                        .iter()
                        .any(|b| matches!(b.kind, BlockType::While | BlockType::For));
                    if let (Some(ti), true) = (ti, has_loop) {
                        let b2_start = self.blocks[ii].end;
                        let try_start = self.blocks[ti].start;
                        // legacy SETUP_FINALLY opens the Try with
                        // end == the handler start
                        let handler = self.blocks[ti]
                            .finally_target
                            .or_else(|| self.legacy_try.as_ref().map(|l| l.handler_start))
                            .unwrap_or(self.blocks[ti].end);
                        let cond_jump = self
                            .instrs
                            .iter()
                            .find(|x| {
                                x.offset >= try_start
                                    && x.offset < b2_start
                                    && matches!(
                                        x.op,
                                        Op::POP_JUMP_IF_FALSE
                                            | Op::POP_JUMP_FORWARD_IF_FALSE
                                            | Op::POP_JUMP_IF_TRUE
                                            | Op::POP_JUMP_FORWARD_IF_TRUE
                                    )
                                    && x.target == Some(b2_start)
                            })
                            .map(|x| (x.offset, x.op));
                        // scan the fall-through span for its POP_BLOCK and
                        // the loop back edge that follows the second copy
                        let mut pb2 = None;
                        let mut jabs = None;
                        if handler != usize::MAX {
                            for x in self.instrs.iter() {
                                if x.offset < b2_start || x.offset >= handler {
                                    continue;
                                }
                                if x.op == Op::POP_BLOCK && pb2.is_none() {
                                    pb2 = Some(x.offset);
                                    continue;
                                }
                                if pb2.is_some()
                                    && ((x.op == Op::JUMP_ABSOLUTE && x.is_backward)
                                        || x.op == Op::JUMP_FORWARD
                                        || x.op == Op::JUMP_BACKWARD
                                        || x.op == Op::JUMP)
                                {
                                    // the loop back edge after the second
                                    // copy: JABS (for) or a rotated-while
                                    // JF to the cond re-test
                                    jabs = Some(x.offset);
                                    break;
                                }
                            }
                        }
                        if let (Some(pb2), Some(jabs), Some((cj_off, cj_op))) =
                            (pb2, jabs, cond_jump)
                        {
                            if jabs > pb2 && handler > jabs && handler < target {
                                let fin_stop = self
                                    .idx_of
                                    .get(&handler)
                                    .and_then(|&hi| {
                                        self.instrs[hi..]
                                            .iter()
                                            .take(200)
                                            .find(|x| {
                                                matches!(
                                                    x.op,
                                                    Op::RERAISE
                                                        | Op::END_FINALLY
                                                        | Op::JUMP_ABSOLUTE
                                                )
                                            })
                                            .map(|x| x.offset)
                                    })
                                    .unwrap_or(handler);
                                // discard the open If/Try — their stmts
                                // are inlined finally copies, rebuilt below
                                while self.blocks.len() > ti {
                                    self.blocks.pop();
                                }
                                self.legacy_try = None;
                                self.legacy_handler = None;
                                self.legacy_handler_end = None;
                                self.region_result_expr = None;
                                let _ = self.decompile_region(try_start, cj_off);
                                let mut cond_e = self
                                    .region_result_expr
                                    .take()
                                    .unwrap_or_else(|| self.name_expr("???"));
                                if matches!(
                                    cj_op,
                                    Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                                ) {
                                    cond_e = Rc::new(Expr::Unary {
                                        op: UnaryOp::Not,
                                        operand: cond_e,
                                    });
                                }
                                let mut body = vec![Stmt::If {
                                    cond: cond_e,
                                    body: vec![Stmt::Break],
                                    orelse: Vec::new(),
                                }];
                                body.extend(self.decompile_region(b2_start, pb2));
                                let fin = self.decompile_region(handler, fin_stop);
                                self.push_stmt(Stmt::Try {
                                    body,
                                    handlers: Vec::new(),
                                    orelse: Vec::new(),
                                    finalbody: fin,
                                });
                                                                self.skip_until = Some(target);
                                return true;
                            }
                        }
                    }
                }
        false
    }

    /// A forward jump flying over an enclosing loop's exhaustion exit to
    /// the continuation is a `break` over a while/for-else region —
    /// register the else end so find_loop_exit sees it. Other jumps
    /// targeting the same merge are tolerated when they originate INSIDE
    /// the else region (the else body's own guards converge on the merge;
    /// e.g. 3.12 `if a and b: break` in a for-else loop, codeop).
    /// A backward jump between `from` and `to` whose target is not the
    /// (cond) start of any open loop block: the back edge of a while
    /// loop whose cond head is the If chain currently being fused — the
    /// chain is the while's condition, not a statement inside a loop
    /// body. Covers BOTH the pre-3.11 plain back edge (JABS before the
    /// chain's merge, cmd 3.8/3.9) and the 3.10+ ROTATED re-eval whose
    /// back edge is a backward CONDITIONAL jump to the body top
    /// (cmd 3.10 columnize: PJIF->body_top sits inside the fused span).
    /// Backward jumps landing on an OPEN loop's top are legitimate
    /// in-body continues (copyreg 3.13 elif chain over `for name`).
    fn pending_while_back_edge(&self, from: usize, to: usize) -> bool {
        self.instrs.iter().any(|ins| {
            ins.offset >= from
                && ins.offset < to
                && ins.is_backward
                && (matches!(
                    ins.op,
                    Op::JUMP_BACKWARD
                        | Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                ) || matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_TRUE
                        // 3.11+ rotated-while re-eval links loop back via
                        // the BACKWARD cond variants - including the NONE
                        // family (`while A and B is not None:` re-eval's
                        // last link is POP_JUMP_BACKWARD_IF_NOT_NONE onto
                        // the body top; missing it let the pre-check NONE
                        // link merge into a statement guard and the loop
                        // ran once - b16 while_and 3.11)
                        | Op::POP_JUMP_BACKWARD_IF_FALSE
                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                        | Op::POP_JUMP_IF_NONE
                        | Op::POP_JUMP_FORWARD_IF_NONE
                        | Op::POP_JUMP_BACKWARD_IF_NONE
                        | Op::POP_JUMP_IF_NOT_NONE
                        | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                        | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                ))
                && ins.target.map_or(false, |t| {
                    !self.blocks.iter().any(|b| {
                        matches!(b.kind, BlockType::While | BlockType::For)
                            && (b.start == t || b.cond_end == t)
                    })
                })
        })
    }

    /// A `break` flying to `target` over the else region of open If
    /// guards below it: mark those guards' else_end so the region stays
    /// an elif/else arm instead of flattening into a post-guard sibling
    /// that would wrongly EXECUTE after the break (_osx_support 3.9
    /// compiler_fixup: `if stripArch: while True: try/except-break
    /// elif not arm64: for...` - flattened, the arm64 check also ran on
    /// the break path). Validation mirrors the inline break-over-else
    /// marking in the JUMP_ABSOLUTE arm: the region either rejoins the
    /// loop iteration (back edge to the loop top) or merges at the break
    /// target (its last forward jump - arm-end cond jump or nested-for
    /// exhaustion - lands exactly on target, with no terminator between).
    fn mark_guard_else_over_break(&mut self, target: usize) {
        let loop_top = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map(|b| b.start);
        let mut to_mark: Vec<usize> = Vec::new();
        for (i, b) in self.blocks.iter().enumerate() {
            if matches!(b.kind, BlockType::If)
                && b.else_end.is_none()
                && b.short_circuit.is_none()
                && b.end != usize::MAX
                && b.end > self.cur_offset
                && target > b.end
            {
                let (Some(&si), Some(&ei)) =
                    (self.idx_of.get(&b.end), self.idx_of.get(&target))
                else {
                    continue;
                };
                if si >= ei {
                    continue;
                }
                let span = &self.instrs[si..ei];
                let rejoins = loop_top.map_or(false, |lt| {
                    span.iter().any(|x| x.is_backward && x.target == Some(lt))
                });
                let merges = !span.iter().any(|x| {
                    matches!(
                        x.op,
                        Op::RETURN_VALUE
                            | Op::RETURN_CONST
                            | Op::RAISE_VARARGS
                            | Op::RERAISE
                    )
                }) && span
                    .iter()
                    .rev()
                    .any(|x| {
                        !x.is_backward
                            && x.target == Some(target)
                            && matches!(
                                x.op,
                                Op::JUMP_FORWARD
                                    | Op::JUMP
                                    | Op::JUMP_ABSOLUTE
                                    | Op::POP_JUMP_IF_FALSE
                                    | Op::POP_JUMP_IF_TRUE
                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                    | Op::FOR_ITER
                                    | Op::FOR_LOOP
                            )
                    });
                if rejoins || merges {
                    to_mark.push(i);
                }
            }
        }
        for i in to_mark {
            if let Some(b) = self.blocks.get_mut(i) {
                b.else_end = Some(target);
            }
        }
    }

    /// True when [from, to) is pure straight-line code: at least one
    /// instruction, no jumps (any target), no backward edges, no
    /// terminators — the region only falls through to `to`.
    fn is_straight_line_span(&self, from: usize, to: usize) -> bool {
        let (Some(&si), Some(&ei)) = (self.idx_of.get(&from), self.idx_of.get(&to)) else {
            return false;
        };
        si < ei
            && self.instrs[si..ei].iter().all(|x| {
                x.target.is_none()
                    && !x.is_backward
                    && !matches!(
                        x.op,
                        Op::RETURN_VALUE
                            | Op::RETURN_CONST
                            | Op::RAISE_VARARGS
                            | Op::RERAISE
                    )
            })
    }

    fn register_break_over_else(&mut self, target: usize) {
        for b in self.blocks.iter_mut().rev() {
            if matches!(b.kind, BlockType::While | BlockType::For) {
                if b.end < target && b.loop_else_end.is_none() {
                    let b_end = b.end;
                    let b_start = b.start;
                    // other edges to the merge may sit in the else
                    // region [b_end, target) OR inside the loop body —
                    // 3.12+ `break` is POP_TOP + JUMP_FORWARD over the
                    // whole else, so sibling breaks target the merge
                    // from before b_end (copyreg 3.13 _reduce_ex__: two
                    // in-body breaks made others_ok fail, the for-else
                    // `base = object` sank into the loop and the breaks
                    // rendered `pass`). Jumps from BEFORE the loop are
                    // still foreign flow and disqualify.
                    let b_is_for = b.kind == BlockType::For;
                    let others_ok = self
                        .instrs
                        .iter()
                        .filter(|i| {
                            i.target == Some(target) && i.offset != self.cur_offset
                        })
                        .all(|i| {
                            if i.offset >= target {
                                return false;
                            }
                            if i.offset >= b_end {
                                // an exit jump from inside the else
                                // region itself
                                return true;
                            }
                            // an in-body targeter must be a genuine
                            // for-break (POP_TOP/POP_ITER + a forward
                            // unconditional jump: JUMP_FORWARD on
                            // 3.12+, forward JUMP_ABSOLUTE on ≤3.10 —
                            // copyreg 3.9 _reduce_ex has two POP_TOP +
                            // JUMP_ABSOLUTE breaks over the for-else)
                            // — an if/else arm-end jump to the merge is
                            // NOT a break (asyncore 3.8/3.9 loop: the
                            // rotated while's arm end grew a spurious
                            // break under the wide form)
                            b_is_for
                                && i.offset > b_start
                                && !i.is_backward
                                && matches!(
                                    i.op,
                                    Op::JUMP_FORWARD
                                        | Op::JUMP
                                        | Op::JUMP_ABSOLUTE
                                )
                                && self
                                    .idx_of
                                    .get(&i.offset)
                                    .and_then(|&ii| {
                                        (ii > 0).then(|| self.instrs[ii - 1].op)
                                    })
                                    .map_or(false, |p| {
                                        matches!(
                                            p,
                                            Op::POP_TOP | Op::POP_ITER
                                        )
                                    })
                        });
                    if others_ok {
                        b.loop_else_end = Some(target);
                    }
                }
                break;
            }
        }
    }

    fn handle_jump_forward(&mut self, target: usize) -> bool {
        self.handle_jump_forward_depth(target, 0)
    }

    fn handle_jump_forward_depth(&mut self, target: usize, pass: usize) -> bool {
        let target = self.dup_copy_redirect.get(&target).copied().unwrap_or(target);
        self.close_blocks_at(self.cur_offset);
        // a jump to an enclosing loop's exit is a `break` flying over the
        // whole loop tail — it says nothing about else regions of the
        // branch blocks it passes (marking them here stretches an else to
        // the loop exit: 3.11 _compression.read's `if eof:` arm)
        let to_loop_exit = self.find_loop_exit(target).is_some();
        // a forward jump flying over an OPEN (non-top) If block's end
        // boundary implies an else region [end, target) for that block
        for b in self.blocks.iter_mut().rev().skip(1) {
            if matches!(b.kind, BlockType::If)
                && b.short_circuit.is_none()
                && b.else_end.is_none()
                && !to_loop_exit
                && b.end < target
                && b.end > self.cur_offset
            {
                b.else_end = Some(target);
            }
        }
        // break-over-else: a `break` (forward jump to the enclosing
        // loop's exit) flying over an open If's else arm. The generic
        // marking above is vetoed by `to_loop_exit` because the jump
        // says nothing about a branch's else region in general (3.11
        // _compression.read `if eof:`). But when the overflown arm
        // [end, target) is PURE straight-line code — no jumps, no
        // terminators, falling through exactly to the break target —
        // it is unambiguously the If's else arm sharing the loop-exit
        // merge, and leaving it unmarked drops it to a post-if sibling
        // that re-runs after the then-body (_markupbase 3.12/3.13
        // _parse_doctype_entity: `if rawdata[i:i+1]=='%': while…: break
        // else: j=i` rendered `j=i` unconditionally after the loop).
        if to_loop_exit {
            let mut to_mark: Vec<usize> = Vec::new();
            for (i, b) in self.blocks.iter().enumerate().rev().skip(1) {
                if matches!(b.kind, BlockType::If)
                    && b.short_circuit.is_none()
                    && b.else_end.is_none()
                    && b.end < target
                    && b.end > self.cur_offset
                    && self.is_straight_line_span(b.end, target)
                {
                    to_mark.push(i);
                }
            }
            for i in to_mark {
                self.blocks[i].else_end = Some(target);
            }
        }
        // 3.6 elif scaffolding: `if c1: continue elif c2: body2` — the
        // then arm terminates with the loop back edge (the continue) and
        // the compiler STILL emits the else-skip JUMP_FORWARD right after
        // it (dead: unreachable fall-through, untargeted). The continue
        // machinery already closed the If (its statement sits at the top
        // of the enclosing block), so the elif chain breaks: the elif
        // test renders as an independent if, changing semantics for
        // non-c1 values (ast 3.6 NodeTransformer.generic_visit:
        // `elif not isinstance(value, AST): extend` ran for every
        // non-AST value). Re-open the chain: pop the closed If back off
        // and treat [cur_next, target) as its Else region.
        if target > self.cur_next && !self.targets.contains(&self.cur_offset) {
            let dead_after_continue = self
                .idx_of
                .get(&self.cur_offset)
                .and_then(|&ci| {
                    (ci > 0).then(|| &self.instrs[ci - 1])
                })
                .map_or(false, |prev| {
                    prev.is_backward
                        && matches!(
                            prev.op,
                            Op::JUMP_ABSOLUTE
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                | Op::JUMP
                        )
                        && prev
                            .target
                            .map_or(false, |t| self.is_loop_top_target(t))
                })
                && self.blocks.last().map_or(false, |b| {
                    matches!(
                        b.stmts.last(),
                        Some(Stmt::If { orelse, body, .. })
                            if orelse.is_empty()
                                && matches!(body.last(), Some(Stmt::Continue))
                    )
                });
            if dead_after_continue {
                if let Some(top) = self.blocks.last_mut() {
                    if let Some(Stmt::If { cond, body, .. }) = top.stmts.pop() {
                        let else_start = self.cur_next;
                        self.pending_then.push(body);
                        let mut else_blk =
                            Block::new(BlockType::Else, else_start, target);
                        else_blk.cond = Some(cond);
                        else_blk.is_elif =
                            self.starts_with_cond_jump(else_start, target);
                        self.blocks.push(else_blk);
                        return true;
                    }
                }
            }
        }
        if let Some(top) = self.blocks.last() {
            match top.kind {
                BlockType::If if top.else_end.is_none() && top.short_circuit.is_none() => {
                    if to_loop_exit {
                        // a consumed `break` flying over this branch's
                        // remainder to the loop exit — not an else hop
                        return true;
                    }
                    if target > top.end {
                        // end of then-body jumping over the else branch
                        if let Some(t) = self.blocks.last_mut() {
                            t.else_end = Some(target);
                        }
                        return true;
                    }
                    if target == top.end {
                        // a legacy try chain still open inside this if:
                        // this jump is nested-structure machinery (the
                        // body-end hop over the handler chain, or the
                        // handler-exit hop to the merge) — closing now
                        // would strand the chain's flush (RERAISE /
                        // region end) outside the if, hoisting the Try.
                        // The block closes naturally at its end, after
                        // the flush landed inside it.
                        if self.legacy_try.is_some() {
                            return true;
                        }
                        // dead-code skip: then-body complete, no else clause
                        // — close now so an enclosing block can transition
                        // to its own else region at the next instruction.
                        // A 3.12 chained-comparison merge (value_merge)
                        // ends here: close folds the links, and the jump
                        // skips the dead `SWAP 2; POP_TOP` else arm.
                        let is_chain_merge = self
                            .blocks
                            .last()
                            .map_or(false, |b| b.value_merge.is_some());
                        self.force_close_top(self.cur_next);
                        if is_chain_merge {
                                                        self.skip_until = Some(target);
                            return true;
                        }
                        // an elif arm's nested if may share the chain
                        // merge as its end (3.12 threads `if rounds is
                        // not None:` straight to the merge): after
                        // closing it, the NEW top's else transition must
                        // still see this jump — re-dispatch once
                        // walk past inner blocks whose region already
                        // ended at/before here (they close naturally at
                        // the target) and re-dispatch on the first block
                        // that must still process this jump (the elif
                        // Else spanning the merge); bounded recursion
                        if pass < 3 {
                            let mut idx = None;
                            let n = self.blocks.len();
                            for j in (0..n).rev() {
                                let b = &self.blocks[j];
                                if matches!(b.kind, BlockType::If | BlockType::Else)
                                    && b.end == target
                                {
                                    idx = Some(j);
                                    break;
                                }
                                if b.end > target {
                                    break;
                                }
                            }
                            if idx.is_some() {
                                return self.handle_jump_forward_depth(target, pass + 1);
                            }
                        }
                        return true;
                    }
                    return true;
                }
                BlockType::If if top.short_circuit.is_some() => {
                    if target >= top.end && top.chain_link {
                        // 3.10/3.11 chained comparison: the then arm jumps
                        // straight to the merge, over the else arm whose
                        // ROT_TWO/POP_TOP cleanup would swap the merged
                        // value with the stack below it — close (folding
                        // the links) and skip the dead cleanup
                        let end = top.end;
                        self.force_close_top(end);
                                                self.skip_until = Some(target);
                        return true;
                    }
                    // value-merge region: remember where the false path ends
                    if let Some(t) = self.blocks.last_mut() {
                        t.else_end = Some(target);
                    }
                    return true;
                }
                BlockType::Else | BlockType::Except => {
                    // A forward jump that EXITS the else/except body (strictly
                    // past its end) closes it now; when an Else block was
                    // created from an elif region mark it so the closer can
                    // rebuild the chain. A forward jump landing INSIDE the
                    // region, or exactly ON its end, is nested-structure
                    // machinery — e.g. a legacy try's body-jump to its own
                    // else, or its handler-exit jump to the merge (which is
                    // the else block's end): the try's else body still lies
                    // ahead and must be walked into the legacy try first. The
                    // block closes naturally when the walk reaches its end.
                    if target > top.end {
                        self.close_blocks_at(top.end);
                    }
                    return true;
                }
                BlockType::While | BlockType::For if target > top.end => {
                    // jump over the loop-else region: mark it now so the
                    // upcoming close creates the Else block
                    if let Some(t) = self.blocks.last_mut() {
                        t.loop_else_end = Some(target);
                    }
                    return true;
                }
                BlockType::Try => {
                    // try body finished; else clause runs to target, then finally
                    let finally_target = top.finally_target;
                    let end = top.end;
                    if let Some(t) = self.blocks.last_mut() {
                        t.loop_else_end = Some(target);
                    }
                    let _ = (finally_target, end);
                    return true;
                }
                _ => {}
            }
        }
        true
    }

    /// elif detection: `elif c:` and `else: if c:` compile identically, so
    /// we canonicalize — if the first jump inside the else region is a
    /// conditional jump, treat the region as an elif continuation.
    fn starts_with_cond_jump(&self, pos: usize, limit: usize) -> bool {
        for inst in self.instrs.iter() {
            if inst.start < pos {
                continue;
            }
            if inst.start >= limit {
                return false;
            }
            if inst.op == Op::CACHE {
                continue;
            }
            if inst.target.is_some() {
                return matches!(
                    inst.op,
                    Op::POP_JUMP_IF_FALSE
                        | Op::POP_JUMP_IF_TRUE
                        // py2.6 peek-style statement cond jumps: an elif in
                        // 2.6 starts its else region with JUMP_IF_* the same
                        // way 2.7+ does with POP_JUMP_IF_*
                        | Op::JUMP_IF_FALSE
                        | Op::JUMP_IF_TRUE
                        | Op::POP_JUMP_FORWARD_IF_FALSE
                        | Op::POP_JUMP_FORWARD_IF_TRUE
                        | Op::POP_JUMP_BACKWARD_IF_FALSE
                        | Op::POP_JUMP_BACKWARD_IF_TRUE
                        | Op::POP_JUMP_IF_NONE
                        | Op::POP_JUMP_FORWARD_IF_NONE
                        | Op::POP_JUMP_BACKWARD_IF_NONE
                        | Op::POP_JUMP_IF_NOT_NONE
                        | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                        | Op::POP_JUMP_BACKWARD_IF_NOT_NONE
                );
            }
            if matches!(inst.op, Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS) {
                return false;
            }
        }
        false
    }

    /// The end of an else region is the earlier of its JUMP_FORWARD target
    /// and the first boundary that a jump INSIDE the region exits to (the
    /// compiler may leave the else body with a conditional jump instead of
    /// falling through). Targets of jumps internal to nested structures
    /// (with/try/loop cleanup) must not truncate the region.
    /// py2.7 arm-end-jump boundary refinement for an elif else region:
    /// the THEN arm's terminal JABS targets the OUTERMOST merge, so the
    /// else_end derived from it can overshoot into the enclosing chain's
    /// next else arm (DocXMLRPCServer 2.7 generate_html_documentation:
    /// the inner chain's else swallowed the outer `else: assert`). When
    /// an arm-end jump inside the region lands at an interior offset T
    /// and [T, G) holds only terminal jumps and padding — G being the
    /// next JUMP-TARGETED offset (the enclosing chain's next arm head) —
    /// the region's statement flow truly ends at T: bound it there. The
    /// region's own terminal jump then marks the enclosing branch's else
    /// on close. A fall-through continuation inside the region is never
    /// jump-targeted, so genuine trailing statements keep the old bound.
    /// Bound an unbounded (`usize::MAX`) else/elif region at the
    /// innermost enclosing loop's end when one exists: the arm is part
    /// of the loop body and must close with the loop, or post-loop
    /// statements are trapped in the arm (_osx_support 3.9
    /// _default_sysroot: the `if cache is None:` after the for landed
    /// inside the elif chain's last arm because the folded Else ran to
    /// MAX and outlived the For's close).
    ///
    /// Only fire when NO If/Else block is open above the loop: with an
    /// open guarded branch the chain machinery still owns the region's
    /// extent and bounds it at the branch merge - capping at the loop
    /// end there swallows the branch's own else arm into the chain
    /// (filecmp 3.3 phase2: the outer `else: funny.append` of `if ok:`
    /// landed inside the inner elif chain, growing a spurious
    /// `continue`).
    fn cap_else_at_loop(&self, pos: usize, end: usize) -> usize {
        if end != usize::MAX {
            return end;
        }
        let mut loop_end = None;
        for bl in self.blocks.iter().rev() {
            match bl.kind {
                BlockType::While | BlockType::For => {
                    loop_end = Some(bl.end);
                    break;
                }
                // folded chain siblings: every arm of the chain gets its
                // own region and the LAST one must still close with the
                // loop (_osx_support 3.9 _default_sysroot: the `elif
                // in_incdirs:` arm region swallowed the post-loop `if
                // _cache_default_sysroot is None:` when left at MAX)
                BlockType::Else => continue,
                // an open guarded If above the loop: the chain machinery
                // still owns this region's extent and bounds it at the
                // branch merge - capping at the loop end swallows the
                // branch's own else arm into the chain (filecmp 3.3
                // phase2: the outer `else: funny.append` of `if ok:`
                // landed inside the inner elif chain, growing a spurious
                // `continue`)
                BlockType::If => return end,
                _ => {}
            }
        }
        match loop_end.filter(|e| *e != usize::MAX && *e > pos) {
            Some(e) => {
                // stop BEFORE the loop's natural back edge: the region
                // must close with the loop body, but if it still covers
                // the back-edge jump, that jump reads as an explicit
                // `continue` inside the arm (asynchat 3.7 handle_read:
                // a no-op trailing `continue` broke sig-exactness)
                let mut cap = e;
                if let Some(bl) = self
                    .blocks
                    .iter()
                    .rev()
                    .find(|bl| matches!(bl.kind, BlockType::While | BlockType::For))
                {
                    let top = self.effective_offset(bl.start);
                    if let Some(&ei) = self.idx_of.get(&e) {
                        if let Some(&si) = self.idx_of.get(&bl.start) {
                            // the LAST backward edge onto the loop top
                            // before the exit is the natural iteration
                            // end (several arms may back-edge: each
                            // `continue`-shaped exit of the chain)
                            if let Some(x) = self.instrs[si..ei]
                                .iter()
                                .rev()
                                .find(|x| {
                                    x.is_backward
                                        && x.target.map_or(false, |t| {
                                            self.effective_offset(t) == top
                                        })
                                })
                            {
                                cap = x.offset;
                            }
                        }
                    }
                }
                if cap > pos { cap } else { end }
            }
            None => end,
        }
    }

    fn clamp_elif_real_end(&self, pos: usize, real_end: usize) -> usize {
        let (Some(&si), Some(&ei)) = (self.idx_of.get(&pos), self.idx_of.get(&real_end)) else {
            return real_end;
        };
        // merge-trampoline bound: a backward edge to the innermost loop
        // top inside the region that a THEN-arm cond jump (sitting
        // BEFORE the region start) also targets is the if/else's local
        // fall-through merge - the enclosing chain's next arm starts
        // right past it. The arm-end forward jump flew to the chain-tail
        // trampoline (else_end), stretching the region over the merge
        // and the following sibling arms; walking the edge as in-region
        // content grows a spurious `continue` and traps the siblings
        // (_strptime 3.5/3.6 ampm chain: Else[976,1603] swallowed the
        // M..Z arms; the same shape on 3.8+ threads guard ends past the
        // trampoline and mis-nests the arm).
        let loop_top = self
            .blocks
            .iter()
            .rev()
            .find(|b| matches!(b.kind, BlockType::While | BlockType::For))
            .map(|b| b.start);
        if let Some(lt) = loop_top {
            for k in si..ei {
                let x = &self.instrs[k];
                if !(x.is_backward
                    && x.target == Some(lt)
                    && matches!(
                        x.op,
                        Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP
                    ))
                {
                    continue;
                }
                let cond_targeted = self.instrs[..si].iter().rev().any(|pj| {
                    pj.target == Some(x.offset)
                        && matches!(
                            pj.op,
                            Op::POP_JUMP_IF_FALSE
                                | Op::POP_JUMP_IF_TRUE
                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                | Op::JUMP_IF_FALSE
                                | Op::JUMP_IF_TRUE
                        )
                });
                if cond_targeted {
                    return x.offset;
                }
            }
        }
        for k in si..ei {
            let x = self.instrs[k];
            let is_arm_end = !x.is_backward
                && matches!(x.op, Op::JUMP_ABSOLUTE | Op::JUMP_FORWARD | Op::JUMP);
            if !is_arm_end {
                continue;
            }
            let Some(t) = x.target else { continue };
            if t <= pos || t >= real_end {
                continue;
            }
            // G: the next jump-targeted offset AFTER t (t itself is
            // targeted by this very arm-end jump; the wanted G is the
            // enclosing chain's next arm head)
            let Some(g) = self
                .targets
                .iter()
                .copied()
                .filter(|&o| o > t && o <= real_end)
                .min()
            else {
                continue;
            };
            let only_glue = self
                .instrs
                .iter()
                .filter(|y| y.offset >= t && y.offset < g)
                .all(|y| {
                    matches!(y.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)
                        || (!y.is_backward
                            && matches!(
                                y.op,
                                Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
                            ))
                });
            if only_glue {
                return t;
            }
        }
        real_end
    }

    fn next_boundary(&self, from: usize, limit: usize) -> usize {
        let mut best = limit;
        // a target t is INTERNAL when some jump inside [from, t) lands in
        // (from, t] — with/try/loop cleanup targets must not truncate the
        // region; genuine early exits (jumps from before the region or
        // unconditional back edges out of it) still do
        for &t in &self.targets {
            if t <= from || t >= best {
                continue;
            }
            let internal = self
                .instrs
                .iter()
                .skip_while(|i| i.offset < from)
                .take_while(|i| i.offset < t)
                .any(|i| i.target.map_or(false, |it| it > from && it <= t))
                // a loop BACK EDGE from inside the region landing on t
                // makes t a loop top within the region (3.8+ has no
                // SETUP_LOOP: an else-region for-loop's back edge targets
                // its FOR_ITER), not an early boundary. Backward
                // `continue` jumps from before t still bound the region.
                || self
                    .instrs
                    .iter()
                    .skip_while(|i| i.offset < t)
                    .take_while(|i| i.offset < limit)
                    .any(|i| i.is_backward && i.target == Some(t))
                // out-of-line cleanup REJOIN: with/finally exception
                // cleanups resume the main flow with a backward jump
                // (3.12/3.13: WITH_EXCEPT_START ... POP_EXCEPT;
                // POP_TOPs; JUMP_BACKWARD — 3.14 dropped
                // WITH_EXCEPT_START for LOAD_SPECIAL __exit__ and
                // resumes via JUMP_BACKWARD_NO_INTERRUPT). The landing
                // point is machinery, not an early region boundary
                // (cProfile 3.12/3.14 main: the else arm truncated at
                // the with exit, `spec`/`globs`/try ejected to the
                // outer level and `progname` read unbound on the -m
                // path)
                || self.instrs.iter().any(|i| {
                    i.is_backward
                        && i.target == Some(t)
                        && self
                            .idx_of
                            .get(&i.offset)
                            .map_or(false, |&ii| {
                                // either the 3.12/3.13 with cleanup
                                // (WITH_EXCEPT_START nearby, plain
                                // JUMP_BACKWARD rejoin) or the 3.11+
                                // non-interrupting resume op
                                // (JUMP_BACKWARD_NO_INTERRUPT after
                                // POP_EXCEPT). Scoped to JBNI for the
                                // POP_EXCEPT marker: a plain backward
                                // jump after POP_EXCEPT is an
                                // `except: continue/break` source edge
                                // whose loop-top target IS a legit
                                // region bound (widening it there
                                // tore 19 3.14 modules' boundaries)
                                let pop_exc = i.op == Op::JUMP_BACKWARD_NO_INTERRUPT
                                    && self.instrs[ii.saturating_sub(10)..ii]
                                        .iter()
                                        .any(|p| p.op == Op::POP_EXCEPT)
                                    // the landing point must be a WITH
                                    // success exit: an inline __exit__
                                    // call run ([None...] CALL; POP_TOP,
                                    // 3.14 LOAD_SPECIAL __exit__) ends
                                    // right at t — a generic JBNI resume
                                    // onto plain statements is a real
                                    // region boundary
                                    && self
                                        .idx_of
                                        .get(&t)
                                        .map_or(false, |&ti| {
                                            ti >= 6
                                                && self.instrs[ti - 1].op
                                                    == Op::POP_TOP
                                                && matches!(
                                                    self.instrs[ti - 2].op,
                                                    Op::CALL | Op::CALL_FUNCTION
                                                )
                                                && {
                                                    // the __exit__ call
                                                    // feeds on a run of
                                                    // None args (3.12+:
                                                    // LOAD None x3; CALL
                                                    // — 3.14 the same via
                                                    // LOAD_SMALL_INT/
                                                    // borrowed locals);
                                                    // demand at least
                                                    // two None consts in
                                                    // the operand window
                                                    self.instrs
                                                        [ti.saturating_sub(10)..ti - 2]
                                                        .iter()
                                                        .filter(|p| {
                                                            p.op == Op::LOAD_CONST
                                                                && self
                                                                    .code
                                                                    .consts
                                                                    .get(p.arg as usize)
                                                                    .map_or(false, |o| {
                                                                        matches!(&**o, PyObject::None)
                                                                    })
                                                        })
                                                        .count()
                                                        >= 2
                                                }
                                        });
                                let with_exc = self.instrs[ii.saturating_sub(10)..ii]
                                    .iter()
                                    .any(|p| {
                                        matches!(
                                            p.op,
                                            Op::WITH_EXCEPT_START
                                        )
                                    });
                                pop_exc || with_exc
                            })
                });
            if !internal {
                best = t;
            }
        }
        best
    }

    /// If `target` is an exit point of some enclosing loop (the offset
    /// right after its back edge / a FOR_ITER exit), return its block index.
    /// find_loop_exit, extended with the post-loop-ELSE merge: a break
    /// flying over a for/while-else lands past the else arm — the same
    /// spot the else arm's own skip jump targets, so the merge IS a jump
    /// target and find_loop_exit's untargeted-merge clause rejects it
    /// (codeop 3.13 _maybe_compile `if line and line[0] != '#': break`
    /// over the for-else: the else arm's PJIF also lands on the merge).
    /// Accept when every targeter is either past the loop's exhaustion
    /// exit (else-arm material) or a forward unconditional jump from the
    /// walk frontier (this break chunk itself).
    fn jump_is_loop_exit_or_merge(&self, t: usize) -> bool {
        if self.find_loop_exit(t).is_some() {
            return true;
        }
        self.blocks.iter().rev().any(|b| {
            matches!(b.kind, BlockType::While | BlockType::For)
                && t > b.end
                && self
                    .instrs
                    .iter()
                    .filter(|x| x.target == Some(t))
                    .all(|x| {
                        x.offset > b.end
                            || (x.offset > self.cur_offset
                                && !x.is_backward
                                && matches!(
                                    x.op,
                                    Op::JUMP_FORWARD
                                        | Op::JUMP
                                        | Op::JUMP_ABSOLUTE
                                ))
                    })
        })
    }

    fn find_loop_exit(&self, target: usize) -> Option<usize> {
        let te = self.effective_offset(target);
        for (i, b) in self.blocks.iter().enumerate() {
            if !matches!(b.kind, BlockType::While | BlockType::For) {
                continue;
            }
            if let Some(exit) = self.loop_exit_offset(b) {
                if self.effective_offset(exit) == te {
                    return Some(i);
                }
                // a break flying over a for/while-else region: any offset
                // strictly between the exhaustion exit and the else end is
                // also a loop exit
                if let Some(le) = b.loop_else_end {
                    if exit < target && target <= le {
                        return Some(i);
                    }
                }
                // for-else detected at close time may not be recorded yet:
                // accept a forward jump that lands past the block end on an
                // instruction no jump targets (post-else continuation)
                if target > b.end && !self.targets.contains(&target) {
                    return Some(i);
                }
                // a break flying over the enclosing if's SIBLING elif
                // branch: the loop exit flows into a guard chain whose
                // guards all short-circuit to the branch merge, and a
                // break taken inside the if-branch must skip the elif
                // entirely, landing on that merge (_osx_support 3.12
                // compiler_fixup: `except ValueError: break` hops to the
                // post-elif merge past `_supports_arm64_builds`)
                if target > b.end {
                    if let (Some(&si), Some(&ei)) =
                        (self.idx_of.get(&b.end), self.idx_of.get(&target))
                    {
                        if si < ei {
                            let mut sees_guard = false;
                            let ok = self.instrs[si..ei].iter().all(|x| {
                                if x.is_backward {
                                    return true;
                                }
                                match x.target {
                                    Some(t) if t > target => false,
                                    Some(t) if t == target => {
                                        if matches!(
                                            x.op,
                                            Op::POP_JUMP_IF_TRUE
                                                | Op::POP_JUMP_IF_FALSE
                                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                                | Op::POP_JUMP_FORWARD_IF_FALSE
                                                | Op::JUMP_IF_TRUE
                                                | Op::JUMP_IF_FALSE
                                                | Op::JUMP_IF_NOT_EXC_MATCH
                                        ) {
                                            sees_guard = true;
                                        }
                                        true
                                    }
                                    _ => true,
                                }
                            });
                            if ok && sees_guard {
                                return Some(i);
                            }
                        }
                    }
                }
                // 3.12+ relocated handler zone: the loop's end was capped
                // at the first out-of-line chain, so the block end is not
                // the true exit — a clause's break hop flies over the
                // WHOLE zone to the continuation. Recognize targets that
                // no exception-table entry covers (everything inside the
                // zone is covered; the continuation past it is not)
                if let Some(hz) = self.handler_zone {
                    if hz <= b.end
                        && target > b.end
                        && !self.exc_entries.iter().any(|e| {
                            e.start <= target && target < e.end
                        })
                        && !self.chain_heads.contains(&target)
                    {
                        return Some(i);
                    }
                }
                // a break jumping over the loop epilogue (END_FOR and the
                // iterator-drop POP_TOPs) lands on the real continuation
                if target > b.end {
                    if let Some(&ei) = self.idx_of.get(&b.end) {
                        let epilogue = self.instrs[ei..]
                            .iter()
                            .take_while(|x| x.offset < target)
                            .all(|x| {
                                matches!(
                                    x.op,
                                    Op::END_FOR
                                        | Op::POP_TOP
                                        | Op::POP_ITER
                                        | Op::NOP
                                        | Op::NOT_TAKEN
                                )
                            })
                            && self.instrs.get(ei).map_or(false, |x| x.offset < target);
                        if epilogue {
                            return Some(i);
                        }
                    }
                }
            }
        }
        None
    }

    /// Skip NOP/NOT_TAKEN padding so jump targets that differ only by
    /// padding compare equal.
    fn effective_offset(&self, mut off: usize) -> usize {
        loop {
            let Some(&i) = self.idx_of.get(&off) else {
                return off;
            };
            let ins = &self.instrs[i];
            if ins.offset != off {
                return off;
            }
            if matches!(ins.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE) {
                off = ins.end();
                continue;
            }
            return off;
        }
    }

    /// The merge point of a pre-3.11 handler chain starting at `h`:
    /// the first jump target past `h` that no jump from inside the
    /// handler span reaches (the flow re-enters the mainline there).
    /// Chains whose handler terminates in a RETURN/RAISE have no
    /// POP_EXCEPT/END_FINALLY and no forward merge jump — the
    /// trampoline the arm-end jumps thread to is this target (bdb
    /// 3.5/3.6 effective: the bare-except handler ends in a return and
    /// the merge is the loop trampoline after the chain).
    fn chain_merge_past(&self, h: usize) -> Option<usize> {
        let mut cands: Vec<usize> = self
            .targets
            .iter()
            .copied()
            .filter(|&t| t > h)
            .collect();
        cands.sort_unstable();
        for t in cands {
            let targeted_from_inside = self
                .instrs
                .iter()
                .skip_while(|x| x.offset < h)
                .take_while(|x| x.offset < t)
                .any(|x| x.target == Some(t));
            if !targeted_from_inside {
                return Some(t);
            }
        }
        None
    }

    fn loop_exit_offset(&self, b: &Block) -> Option<usize> {
        match b.kind {
            BlockType::For => Some(b.end),
            BlockType::While => {
                if b.cond_end != usize::MAX && b.start < b.end {
                    // rotated while: exit = target of the cond jump, i.e.
                    // the instruction whose end == cond_end
                    self.instrs
                        .iter()
                        .find(|i| i.end() == b.cond_end && i.target.is_some())?
                        .target
                } else if b.end < usize::MAX && b.start < b.end {
                    // SETUP_LOOP era: the block end IS the loop exit
                    Some(b.end)
                } else {
                    // 3.8+ `while True`: no SETUP_LOOP and no cond jump;
                    // back edge jumps to b.start, the following instruction
                    // offset is the exit
                    self.back_edge_exit(b.start)
                }
            }
            _ => None,
        }
    }

    /// True when `off` is a POP_BLOCK whose end reaches `end` (the
    /// SETUP_LOOP-era cond jump targets the loop's POP_BLOCK, one byte
    /// before the block end).
    fn is_pop_block_before(&self, off: usize, end: usize) -> bool {
        self.idx_of
            .get(&off)
            .and_then(|&i| self.instrs.get(i))
            .map_or(false, |x| x.op == Op::POP_BLOCK && x.end() <= end)
    }

    /// True when [off, end) holds only terminator/padding instructions
    /// (RETURN/NOP/NOT_TAKEN/CACHE) with at least one return: `off` is a
    /// loop exit whose block end overshot into sunk function-tail return
    /// copies (3.11+ rotated while in tail flow, chunk.skip).
    /// py2.7 dead glue: an UNTARGETED forward unconditional jump sitting
    /// right after another forward unconditional jump — the previous edge
    /// already left the region, this one is unreachable fall-through
    /// padding. Executing it marks a phantom else_end on the overflown
    /// If (CGIHTTPServer 2.7 run_cgi: the glue after the else region's
    /// arm-end JABS gave the region's guard If an else arm holding the
    /// whole Try)
    fn is_dup_forward_jump(&self) -> bool {
        if self.targets.contains(&self.cur_offset) {
            return false;
        }
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        let x = &self.instrs[ci];
        if !x.target.map_or(false, |t| t > x.offset) {
            return false;
        }
        let mut p = ci;
        while p > 0 && self.instrs[p - 1].op == Op::EXTENDED_ARG {
            p -= 1;
        }
        if p == 0 {
            return false;
        }
        let prev = &self.instrs[p - 1];
        !prev.is_backward
            && matches!(
                prev.op,
                Op::JUMP_FORWARD | Op::JUMP_ABSOLUTE | Op::JUMP
            )
            && prev.target.map_or(false, |t| t > prev.offset)
    }

    /// True when the chain at `h` holds an except dispatch (3.8-3.10:
    /// DUP_TOP; pattern; COMPARE_OP exception-match / JUMP_IF_NOT_EXC_
    /// MATCH) before its terminating RERAISE/END_FINALLY — a pure
    /// finally copy region has neither
    fn chain_has_exc_dispatch(&self, h: usize) -> bool {
        let Some(&hi) = self.idx_of.get(&h) else {
            return false;
        };
        for x in self.instrs[hi..].iter().take(60) {
            match x.op {
                Op::JUMP_IF_NOT_EXC_MATCH => return true,
                Op::COMPARE_OP
                    if cmp_from_index(
                        compare_op_index(x.arg as u32, self.version),
                    ) == CmpOp::ExceptionMatch =>
                {
                    return true;
                }
                Op::RERAISE | Op::END_FINALLY => return false,
                _ => {}
            }
        }
        false
    }

    fn is_dead_forward_glue(&self) -> bool {
        if !self.is_dup_forward_jump() {
            return false;
        }
        // Skip the duplicate edge only inside a live legacy-try region:
        // there the chain machinery re-walks the pad and the glue's
        // execution would mark a phantom else_end on the overflown If
        // (CGIHTTPServer 2.7 run_cgi: JABS 945→951 after the else
        // region's arm-end JABS 942→948 stretched the guard If's else
        // over the whole Try). Outside a try region the same shape is
        // load-bearing: the padding JABS 1599 after the arm-end JABS
        // 1004 is the closing edge of the inner `elif ampm == ...`
        // If[976,1599] (3.3/2.7 _strptime); skipping it strands that
        // block open and the chain's arm-end back edge tears the whole
        // elif ladder down into `continue` + fresh `if`
        self.legacy_try.is_some()
    }

    fn is_term_pad_before(&self, off: usize, end: usize, allow_load_none: bool) -> bool {
        if off >= end {
            return false;
        }
        let Some(&i) = self.idx_of.get(&off) else {
            return false;
        };
        let mut saw_return = false;
        for x in &self.instrs[i..] {
            if x.offset >= end {
                break;
            }
            match x.op {
                Op::RETURN_VALUE | Op::RETURN_CONST => saw_return = true,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE => {}
                // the sunk stub's value load (3.11 emits LOAD None;
                // RETURN_VALUE, not RETURN_CONST) — only for the
                // per-operand-epilogue clause (allow_load_none): the
                // pre-end clause must keep rejecting value loads or an
                // in-body guard one stub before the loop end reads as a
                // duplicated rotated cond (asynchat 3.11 `if num_sent:`)
                Op::LOAD_CONST
                    if allow_load_none
                        && matches!(
                            self.code.consts.get(x.arg as usize).map(|o| &**o),
                            Some(PyObject::None)
                        ) => {}
                _ => return false,
            }
        }
        saw_return
    }

    /// 3.8+ for-else: when the For closes at the FOR_ITER exhaustion exit,
    /// a following unconditional jump over untargeted code marks an else
    /// region [pos, jump_target). Plain loops have no such jump (the next
    /// statement follows directly or a nested structure intervenes).
    /// SETUP_LOOP-era for-else region check: a plain loop end is
    /// `POP_BLOCK; JUMP_FORWARD -> setup_target` — the exhaustion exit
    /// hopping to the merge (e.g. the then arm of an if/else whose loop
    /// shares its SETUP_LOOP target with the if's merge, copy._reconstruct
    /// on 3.5-3.7). Treating that as a for-else attaches the IF's else
    /// branch to the FOR (the shallow-copy loop then runs after the deep
    /// one instead of instead of it). A genuine else region holds
    /// statements after the POP_BLOCK.
    fn setup_for_else_region(&self, exit: usize, setup_end: usize) -> bool {
        let Some(&pi) = self.idx_of.get(&exit) else {
            return false;
        };
        let mut k = pi;
        while matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::POP_BLOCK) | Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
        ) {
            k += 1;
        }
        if let Some(ins) = self.instrs.get(k) {
            if matches!(
                ins.op,
                Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
            ) && !ins.is_backward
                && ins.target == Some(setup_end)
            {
                return false;
            }
            // a backward jump out of the loop-exit region is NOT a for-else
            // body start: it's the enclosing if/loop body's exit (compiler
            // optimized a `JUMP_FORWARD else_end` into `JUMP_ABSOLUTE
            // loop_top` because the for sits at the end of an if body inside
            // a loop). Treating [exit, setup_end) as a for-else here swallows
            // the following elif into a phantom `else: continue` and flattens
            // the elif (ast 3.6 NodeVisitor.generic_visit).
            if matches!(
                ins.op,
                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP_BACKWARD_NO_INTERRUPT
            ) && ins.is_backward
            {
                return false;
            }
        }
        true
    }

    fn probe_for_else(&self, pos: usize) -> Option<usize> {
        let Some(&pi) = self.idx_of.get(&pos) else {
            return None;
        };
        // merge candidate: forward cond jumps inside the else body (its
        // own guards) converge on the merge; unconditional forward jumps
        // with no other source end a jump-terminated else body
        let mut cand: Option<usize> = None;
        for ins in self.instrs.iter().skip(pi) {
            if let Some(ct) = cand {
                if ins.offset >= ct {
                    return Some(ct);
                }
            }
            if let Some(t) = ins.target {
                if matches!(
                    ins.op,
                    Op::JUMP_ABSOLUTE
                        | Op::JUMP_FORWARD
                        | Op::JUMP
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                ) && t > pos
                    && !self.targets.contains(&t)
                {
                    return Some(t);
                }
                let is_fwd_cond = !ins.is_backward
                    && t > ins.offset
                    && matches!(
                        ins.op,
                        Op::POP_JUMP_IF_FALSE
                            | Op::POP_JUMP_IF_TRUE
                            | Op::POP_JUMP_FORWARD_IF_FALSE
                            | Op::POP_JUMP_FORWARD_IF_TRUE
                            | Op::POP_JUMP_BACKWARD_IF_FALSE
                            | Op::POP_JUMP_BACKWARD_IF_TRUE
                            | Op::POP_JUMP_IF_NONE
                            | Op::POP_JUMP_FORWARD_IF_NONE
                            | Op::POP_JUMP_IF_NOT_NONE
                            | Op::POP_JUMP_FORWARD_IF_NOT_NONE
                    );
                if is_fwd_cond {
                    match cand {
                        None => {
                            cand = Some(t);
                            continue;
                        }
                        Some(ct) if ct == t => continue,
                        _ => return None, // divergent guards: nested structure
                    }
                }
                // any other targeted jump: nested structure, no for-else
                return None;
            }
            if matches!(
                ins.op,
                Op::NOP
                    | Op::NOT_TAKEN
                    | Op::CACHE
                    | Op::POP_TOP
                    | Op::END_FOR
                    | Op::POP_ITER
            ) {
                continue;
            }
            if cand.is_some() {
                // else-body statements: keep scanning toward the merge
                continue;
            }
            // plain statement code with no jump: no else region
            return None;
        }
        None
    }

    fn back_edge_exit(&self, loop_start: usize) -> Option<usize> {
        for inst in self.instrs.iter() {
            if inst.is_backward && inst.target == Some(loop_start) {
                return self.instrs.iter().find(|i| i.start > inst.end()).map(|i| i.start);
            }
        }
        None
    }

    /// True when [top, cur) contains only condition-evaluation instructions
    /// (loads/constants/compares), meaning `top` is the start of the cond
    /// expression of a rotated while loop.
    fn is_cond_expr_top(&self, top: usize, cur: usize) -> bool {
        if top == cur {
            return true;
        }
        let Some(&ti) = self.idx_of.get(&top) else {
            return false;
        };
        let Some(&ci) = self.idx_of.get(&cur) else {
            return false;
        };
        if ti >= ci {
            return false;
        }
        let mut prev: Option<Op> = None;
        let mut prev_arg = 0u32;
        let ok = self.instrs[ti..ci].iter().all(|inst| {
            let good = match inst.op {
                Op::RETURN_VALUE
                | Op::RETURN_CONST
                | Op::POP_TOP
                | Op::STORE_SUBSCR
                | Op::STORE_ATTR => false,
                Op::STORE_FAST | Op::STORE_NAME | Op::STORE_GLOBAL | Op::STORE_DEREF => {
                    // walrus: the value was duplicated right before
                    matches!(prev, Some(Op::DUP_TOP))
                        || (prev == Some(Op::COPY) && prev_arg == 1)
                }
                // value-producing calls are fine inside conditions
                Op::CALL
                | Op::CALL_FUNCTION
                | Op::CALL_METHOD
                | Op::CALL_FUNCTION_KW
                | Op::CALL_FUNCTION_EX => true,
                _ => match inst.target {
                    // value-level branch (ternary/boolop): self-contained
                    // when every target stays inside the region
                    Some(t) => t >= top && t <= cur,
                    None => true,
                },
            };
            prev = Some(inst.op);
            prev_arg = inst.arg;
            good
        });
        ok
    }

    /// True when a backward jump targets an enclosing loop's top while
    /// inner blocks (ifs or nested loops) are still open — a `continue`.
    /// The final back edge of a loop arrives with the loop as the topmost
    /// block and closes it instead.
    /// py3 legacy (3.0-3.10): the handler-exit back edge right after
    /// POP_EXCEPT is a source-level `continue` only when it flies over
    /// real loop-body statements (b15: try is not the loop's last
    /// statement). When only chain material (cleanup pops, END_FINALLY/
    /// RERAISE stubs, the next clause's match prelude) lies between it
    /// and the loop's natural back edge / POP_BLOCK, it is the implicit
    /// fall-through — rendering a Continue inserts a CONTINUE_LOOP the
    /// original bytecode does not have (code.py 3.5 interact).
    fn handler_exit_jabs_is_continue(&self, jabs_idx: usize) -> bool {
        let mut saw_real = false;
        // the chain's own else region is chain STRUCTURE, not skipped
        // loop-body material: the handler-exit edge hops over it, but
        // its statements execute on the try-success path — counting
        // them as skipped body turns the collecting edge into an
        // explicit continue inside the except arm (csv 3.5 has_header:
        // `except (ValueError, TypeError): hasHeader += 1; continue`)
        let (chain_es, chain_ee) = self
            .legacy_try
            .as_ref()
            .map(|l| (l.else_start, l.else_stop))
            .unwrap_or((None, usize::MAX));
        // statements AT OR PAST the enclosing loop's exit are POST-loop
        // code, not body material the edge skips: a genuine `continue`
        // only bypasses statements between the handler and the loop's
        // natural back edge, all of which lie below the exit
        // (_sitebuiltins 3.10 __setup: the handler-exit JABS is the
        // chain's collecting edge — the try is the whole loop body —
        // but the post-loop `data.split` LOAD_METHOD read as skipped
        // body and rendered `except OSError: continue`)
        let jump_target = self
            .instrs
            .get(jabs_idx)
            .and_then(|x| x.target)
            .map(|t| self.effective_offset(t));
        let loop_end = jump_target.and_then(|te| {
            self.blocks
                .iter()
                .find(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (self.effective_offset(b.start) == te
                            || (b.cond_end != usize::MAX
                                && self.effective_offset(b.cond_end) == te))
                })
                .map(|b| b.end)
                .filter(|e| *e != usize::MAX)
        });
        // pending clause heads ahead: their chain material (dispatch,
        // body, cleanups) lies between this exit edge and the loop's
        // back edge — a later clause's body op (its RAISE, a CALL...)
        // must not count as skipped real body (asyncore 3.8 close_all
        // clause 1: clause 2's RAISE_VARARGS read as body material and
        // the structural clause exit rendered `continue`, whose
        // as-clause unwind recompiles CALL_FINALLY-style vs the
        // original BEGIN_FINALLY fall-through). Hop each pending
        // clause: head .. first POP_EXCEPT + its exit jump.
        let pending_heads: Vec<usize> = self
            .legacy_try
            .as_ref()
            .map(|l| {
                let mut v: Vec<usize> = l
                    .pending_mismatch
                    .iter()
                    .copied()
                    .filter(|&m| {
                        m > self.instrs.get(jabs_idx).map_or(0, |j| j.offset)
                    })
                    .collect();
                v.sort();
                v
            })
            .unwrap_or_default();
        let mut k = jabs_idx + 1;
        while k < self.instrs.len() {
            let x = &self.instrs[k];
            // hop trigger: a pending mismatch head, or any clause-head
            // pattern (typed dispatch DUP_TOP / bare except POP_TOP x3)
            // — later clauses register their heads only when their
            // dispatch is parsed, which has not happened yet while the
            // enclosing clause is still folding
            let clause_head = pending_heads.contains(&x.offset)
                || x.op == Op::DUP_TOP
                || (x.op == Op::POP_TOP
                    && self.instrs.get(k + 1).map(|y| y.op) == Some(Op::POP_TOP)
                    && self.instrs.get(k + 2).map(|y| y.op) == Some(Op::POP_TOP));
            if clause_head {
                let mut m = k;
                let mut exit_after = None;
                let mut is_clause = true;
                while m < self.instrs.len() {
                    match self.instrs[m].op {
                        Op::POP_EXCEPT => {
                            exit_after = Some(m + 1);
                            break;
                        }
                        // a cleanup tail (POP x3; END_FINALLY) or a
                        // re-raise stub is NOT a clause body — hopping
                        // over it would swallow the real statements
                        // that follow (csv 3.5/3.6 has_header lost its
                        // source-level continue)
                        Op::END_FINALLY | Op::RERAISE => {
                            is_clause = false;
                            break;
                        }
                        _ => m += 1,
                    }
                    if m - k > 400 {
                        is_clause = false;
                        break;
                    }
                }
                if is_clause {
                    match exit_after {
                        Some(a) => {
                            k = a + 1;
                            continue;
                        }
                        None => return saw_real,
                    }
                }
            }
            if let Some(le) = loop_end {
                if x.offset >= le {
                    return saw_real;
                }
            }
            if let Some(es) = chain_es {
                if x.offset >= es && x.offset < chain_ee {
                    k += 1;
                    continue;
                }
            }
            let stop = match x.op {
                Op::JUMP_ABSOLUTE | Op::JUMP_BACKWARD | Op::JUMP | Op::JUMP_BACKWARD_NO_INTERRUPT
                    if x.is_backward => true,
                Op::POP_BLOCK | Op::FOR_ITER => true,
                Op::POP_TOP | Op::POP_EXCEPT | Op::END_FINALLY | Op::RERAISE
                | Op::DUP_TOP | Op::COPY | Op::SWAP | Op::NOP | Op::NOT_TAKEN
                | Op::CACHE | Op::EXTENDED_ARG | Op::LOAD_CONST
                | Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF
                | Op::DELETE_FAST | Op::DELETE_NAME | Op::DELETE_DEREF
                | Op::LOAD_FAST | Op::LOAD_NAME | Op::LOAD_GLOBAL
                | Op::LOAD_DEREF | Op::LOAD_ATTR | Op::COMPARE_OP
                | Op::JUMP_IF_NOT_EXC_MATCH | Op::CHECK_EXC_MATCH
                | Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::JUMP_IF_FALSE_OR_POP | Op::JUMP_IF_TRUE_OR_POP => false,
                _ => {
                    saw_real = true;
                    false
                }
            };
            if stop {
                return saw_real;
            }
            k += 1;
        }
        saw_real
    }

    fn is_continue_jump(&self, target: usize) -> bool {
        // in the ELSE-AFTER-CHAIN layout (3.5/3.6: the try's else region
        // lies past the handler chain and is only reachable via the body-
        // end forward jump), a backward edge from inside the handler span
        // BEFORE the else region was walked is the except arm's collecting
        // edge, not a source-level `continue` — letting the continue
        // machinery take it closes the enclosing else arm and strands the
        // not-yet-emitted Try at loop level (csv 3.5 has_header:
        // `else: continue` + flattened try/except/else). Chains without
        // a discovered else region (py2 asyncore close_all, ast 3.8
        // shapes where the edge precedes else_start discovery) keep the
        // historic classification.
        if let Some(l) = &self.legacy_try {
            if !l.handlers.is_empty() {
                if let Some(es) = l.else_start {
                    if self.cur_offset >= l.handler_start && self.cur_offset < es
                    {
                        return false;
                    }
                }
            }
        }
        let mut depth = 0usize;
        // a still-live region block above the loop (an open folded-chain
        // Else[MAX], an unclosed If) means the loop is not done: the jump
        // may be the chain's collecting back edge, which must fold the
        // chain instead of falling through to handle_jump_backward
        // (ast 3.6 NodeTransformer.generic_visit: the elif chain's tail
        // edge saw the layout-exhausted For as transparent, the Else
        // never folded, and the function's final `return node` landed
        // inside the else arm)
        let mut live_region_above = false;
        for b in self.blocks.iter().rev() {
            if matches!(b.kind, BlockType::Main) {
                break;
            }
            if matches!(b.kind, BlockType::While | BlockType::For)
                && b.end != usize::MAX
                && b.end <= self.cur_offset
            {
                // layout-exhausted loop awaiting its close: transparent
                // only when nothing above it is still live
                if live_region_above {
                    return depth > 0;
                }
                continue;
            }
            if !matches!(b.kind, BlockType::While | BlockType::For) {
                if b.end == usize::MAX || b.end > self.cur_offset {
                    live_region_above = true;
                }
                depth += 1;
                continue;
            }
            if matches!(b.kind, BlockType::While | BlockType::For) {
                if b.start == target
                    || (b.cond_end != usize::MAX
                        && (b.cond_end == target
                            || (b.start <= target && target < b.cond_end)))
                {
                    return depth > 0;
                }
                if b.start < target && target < b.end {
                    // a jump landing INSIDE an open try block's body is
                    // an arm merge to the try's body end (its POP_BLOCK),
                    // not a continue: the try's own body-end edge
                    // provides the iteration continuation. Emitting a
                    // Continue here recompiled to CONTINUE_LOOP + an
                    // extra arm-end jump instead of the single merge
                    // JABS (bdb 3.3/2.7 effective's inner try arm)
                    let into_open_try = self.blocks.iter().any(|t| {
                        matches!(t.kind, BlockType::Try)
                            && t.start <= target
                            && target < t.end
                    });
                    return depth > 0 && !into_open_try;
                }
                depth += 1;
            }
        }
        false
    }

    fn close_inner_blocks_to_loop(&mut self) {
        // find innermost enclosing loop and close everything above it
        let n = self.blocks.len();
        for i in (0..n).rev() {
            if matches!(self.blocks[i].kind, BlockType::While | BlockType::For) {
                while self.blocks.len() > i + 1 {
                    let pos = self
                        .blocks
                        .last()
                        .map(|b| {
                            // an If force-closed by a break flying over its
                            // not-yet-walked else region: the Else opens at
                            // the block's END (its cond-jump target), not
                            // at its start (3.8 asynchat handle_read)
                            if matches!(b.kind, BlockType::If)
                                && b.else_end.is_some()
                                && b.end != usize::MAX
                            {
                                b.end
                            } else {
                                b.start
                            }
                        })
                        .unwrap_or(0);
                    self.force_close_top(pos);
                    // the close just opened an ahead-of-walk Else region
                    // (the break's If had its else_end marked): STOP —
                    // force-closing it here would pair it with an empty
                    // orelse before the walk ever enters it; the region's
                    // own back edge folds the chain instead
                    if let Some(t) = self.blocks.last() {
                        if matches!(t.kind, BlockType::Else)
                            && t.end != usize::MAX
                            && t.start >= self.cur_offset
                            && t.end > self.cur_offset
                        {
                            return;
                        }
                    }
                }
                return;
            }
        }
    }

    /// 3.8+ has no SETUP_LOOP: a `while True:` body ends with an
    /// unconditional backward jump and has no cond jump at its top.
    /// Register those loops so the block opens when execution reaches the
    /// top and closes at the back edge.
    fn prescan_dup_copies(&mut self) {
        if !self.version.at_least(3, 8) || self.inline_comp.is_some() {
            return;
        }
        let is_cond = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
                    | Op::POP_JUMP_BACKWARD_IF_FALSE
                    | Op::POP_JUMP_BACKWARD_IF_TRUE
                    | Op::JUMP_IF_FALSE_OR_POP
                    | Op::JUMP_IF_TRUE_OR_POP
                    | Op::JUMP_IF_FALSE
                    | Op::JUMP_IF_TRUE
                    | Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_FORWARD_IF_NONE
                    | Op::POP_JUMP_IF_NOT_NONE
                    | Op::POP_JUMP_FORWARD_IF_NOT_NONE
            )
        };
        let is_terminator = |o: Op| {
            matches!(
                o,
                Op::RAISE_VARARGS
                    | Op::RETURN_VALUE
                    | Op::RETURN_CONST
                    | Op::JUMP_FORWARD
                    | Op::JUMP
                    | Op::JUMP_ABSOLUTE
                    | Op::JUMP_BACKWARD
                    | Op::RERAISE
            )
        };
        let is_padding = |o: Op| matches!(o, Op::NOP | Op::NOT_TAKEN | Op::CACHE);
        // every offset some jump points at
        let mut jumped: HashSet<usize> = HashSet::new();
        for ins in self.instrs.iter() {
            if let Some(t) = ins.target {
                jumped.insert(t);
            }
        }
        let n = self.instrs.len();
        for i in 0..n {
            let ins = self.instrs[i];
            if !is_cond(ins.op) {
                continue;
            }
            let Some(t) = ins.target else { continue };
            if t <= ins.offset {
                continue;
            }
            let Some(&ti) = self.idx_of.get(&t) else {
                continue;
            };
            // cleanup prefix at the else landing: [ROT_TWO|SWAP 2;] POP_TOP
            let mut c = ti;
            if matches!(self.instrs.get(c).map(|x| x.op), Some(Op::ROT_TWO))
                && matches!(self.instrs.get(c + 1).map(|x| x.op), Some(Op::POP_TOP))
            {
                c += 2;
            } else if matches!(self.instrs.get(c).map(|x| x.op), Some(Op::SWAP))
                && self.instrs.get(c).map(|x| x.arg) == Some(2)
                && matches!(self.instrs.get(c + 1).map(|x| x.op), Some(Op::POP_TOP))
            {
                c += 2;
            } else if matches!(self.instrs.get(c).map(|x| x.op), Some(Op::POP_TOP)) {
                c += 1;
            } else {
                continue;
            }
            // scan through the chain material between this jump and the
            // else landing; the body starts after the LAST cond jump
            // (chain links re-jump to the same copy on failure)
            let mut last_j = None;
            let mut k = i + 1;
            while k < ti {
                let op = self.instrs[k].op;
                if is_padding(op) || is_pure_value_op(op) {
                    k += 1;
                    continue;
                }
                if matches!(
                    op,
                    Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP | Op::TO_BOOL
                ) {
                    k += 1;
                    continue;
                }
                if is_cond(op) {
                    last_j = Some(k);
                    k += 1;
                    continue;
                }
                // non-chain material: the terminating body starts right
                // after the last link
                break;
            }
            let Some(lj) = last_j else { continue };
            let Some(mut b) = (lj + 1..ti).find(|&x| !is_padding(self.instrs[x].op)) else {
                continue;
            };
            let body_start = self.instrs[b].offset;
            // the shared body must not be jumped into from elsewhere
            if jumped.iter().any(|&jt| jt > body_start && jt < t) {
                continue;
            }
            // body end E: through the first terminator (capped)
            let mut e = None;
            let mut m = b;
            while m < n && m - b < 40 {
                if is_terminator(self.instrs[m].op) {
                    e = Some(m + 1);
                    break;
                }
                if self.instrs[m].is_backward {
                    break;
                }
                m += 1;
            }
            let Some(e) = e else { continue };
            // E must land at or before the copy cleanup start
            if self.instrs[e - 1].end() > self.instrs[c].offset {
                continue;
            }
            // the copy must match [B, E) instruction-for-instruction
            // (ignoring padding)
            let mut bi = b;
            let mut ci = c;
            let mut matched = 0usize;
            let mut ok = true;
            while bi < e {
                if is_padding(self.instrs[bi].op) {
                    bi += 1;
                    continue;
                }
                while ci < n && is_padding(self.instrs[ci].op) {
                    ci += 1;
                }
                let Some(cin) = self.instrs.get(ci) else {
                    ok = false;
                    break;
                };
                let bin = &self.instrs[bi];
                if cin.op != bin.op
                    || cin.arg != bin.arg
                    || cin.target != bin.target
                    || cin.is_backward != bin.is_backward
                {
                    ok = false;
                    break;
                }
                matched += 1;
                bi += 1;
                ci += 1;
            }
            // matched >= 1 is safe: the mandatory cleanup POP_TOP at
            // the else landing only exists in compiler chain machinery
            // (a source-level duplicate statement has no stack value to
            // discard), and the body must be a verified terminator run
            if !ok || matched < 1 || bi != e || ci >= n {
                continue;
            }
            // no other jump may land strictly inside the copy region
            let copy_start_off = self.instrs[ti].offset;
            let copy_end = self.instrs[ci - 1].end();
            if jumped
                .iter()
                .any(|&jt| jt > copy_start_off && jt < copy_end)
            {
                continue;
            }
            self.dup_copy_redirect.insert(t, body_start);
            self.dup_copy_skip.push((copy_start_off, copy_end));
        }
    }

    fn prescan_while_true(&mut self) {
        if !self.version.at_least(3, 8) || self.inline_comp.is_some() {
            return;
        }
        let is_back_jump = |i: &Instruction| {
            i.is_backward
                && matches!(
                    i.op,
                    Op::JUMP_ABSOLUTE
                        | Op::JUMP_BACKWARD
                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                )
        };
        let is_cond_jump = |o: Op| {
            matches!(
                o,
                Op::POP_JUMP_IF_FALSE
                    | Op::POP_JUMP_IF_TRUE
                    | Op::POP_JUMP_FORWARD_IF_FALSE
                    | Op::POP_JUMP_FORWARD_IF_TRUE
                    | Op::JUMP_IF_FALSE_OR_POP
                    | Op::JUMP_IF_TRUE_OR_POP
                    | Op::POP_JUMP_IF_NONE
                    | Op::POP_JUMP_IF_NOT_NONE
            )
        };
        // loop tops claimed by rotated-while cond jumps (section 6 handles
        // those), by FOR_ITER loops, and by SETUP_* blocks
        let mut claimed: Vec<usize> = Vec::new();
        let back_ops = |o: Op| {
            matches!(
                o,
                Op::JUMP_ABSOLUTE
                    | Op::JUMP_BACKWARD
                    | Op::JUMP_BACKWARD_NO_INTERRUPT
            )
        };
        // rotated whiles whose exit test PRECEDES the back edge in layout
        // (3.14 walrus-while: `<cond expr>; PJIF_NONE exit; NOT_TAKEN;
        // <body>; JUMP_BACKWARD top`): the back edge lies outside [cj, t),
        // so scan the region BEFORE the exit jump as well
        for (ci, cj) in self.instrs.iter().enumerate() {
            if !is_cond_jump(cj.op) || cj.target.map_or(true, |t| t <= cj.offset) {
                continue;
            }
            for ins in &self.instrs[..ci] {
                if ins.is_backward
                    && back_ops(ins.op)
                    && ins.target.map_or(false, |bt| {
                        bt < ins.offset && self.is_cond_expr_top(bt, cj.offset)
                    })
                {
                    if let Some(bt) = ins.target {
                        claimed.push(bt);
                    }
                }
            }
        }
        for (ci, cj) in self.instrs.iter().enumerate() {
            if !is_cond_jump(cj.op) {
                continue;
            }
            let Some(t) = cj.target else { continue };
            if t <= cj.offset {
                continue;
            }
            let Some(&ti) = self.idx_of.get(&t) else {
                continue;
            };
            // back edges between this cond jump and its target:
            // * target starts a pure cond-expr region ending at this jump
            //   -> rotated while, claim its top (block while-True synthesis)
            // * otherwise this is a 3.14-style `if c: break` flying over
            //   the ENCLOSING loop's own back edge — that loop's top must
            //   stay unclaimed, and this region claims nothing
            let straddle: Vec<usize> = self.instrs[ci..ti]
                .iter()
                .filter(|ins| ins.is_backward && back_ops(ins.op))
                .filter_map(|ins| ins.target)
                .collect();
            if !straddle.is_empty() {
                for bt in straddle {
                    if self.is_cond_expr_top(bt, cj.offset) {
                        claimed.push(bt);
                    }
                }
                continue;
            }
            for ins in &self.instrs[ci..ti] {
                if let Some(bt) = ins.target {
                    // only UNCONDITIONAL back edges mark a rotated-while
                    // cond head here: a backward COND jump to bt is a
                    // `continue` fused onto an enclosing while-True's top
                    // (cgi 3.8 read_multi: the chained-comparison link's
                    // PJFF->258 claimed the outer `while True:` top as a
                    // cond head and the whole outer loop was lost)
                    if ins.is_backward
                        && bt <= cj.offset
                        && back_ops(ins.op)
                    {
                        claimed.push(bt);
                    }
                }
            }
        }
        for ins in &self.instrs {
            if matches!(
                ins.op,
                Op::FOR_ITER | Op::FOR_LOOP | Op::SETUP_LOOP | Op::SETUP_FINALLY | Op::SETUP_EXCEPT
            ) {
                if let Some(t) = ins.target {
                    claimed.push(t);
                }
                if matches!(ins.op, Op::FOR_ITER | Op::FOR_LOOP) {
                    claimed.push(ins.offset);
                }
            }
        }
        let mut found: Vec<(usize, usize, usize)> = Vec::new();
        for (bi, bj) in self.instrs.iter().enumerate() {
            if !is_back_jump(bj) {
                continue;
            }
            let Some(t) = bj.target else { continue };
            if claimed.contains(&t) {
                continue;
            }
            // the region [t, bj) must be straight-line loop body: every
            // jump inside stays within the region (or is a dead duplicate
            // back edge); breaks out of it disqualify the shape
            let Some(&ti) = self.idx_of.get(&t) else {
                continue;
            };
            if ti > bi {
                continue;
            }
            // reject back edges that belong to an out-of-line handler
            // cleanup: scanning back from the jump, a PUSH_EXC_INFO comes
            // before any inner back edge (a real loop body would show its
            // nested loops' back edges first). Such jumps are suppressed
            // -exception continuations (with/try), not `while True` edges.
            let mut handler_origin = false;
            // chain heads the body jumps OVER: their dead handler code
            // (PUSH_EXC_INFO etc.) must not count as live back-scan hits
            let mut skipped_chains: Vec<(usize, usize)> = Vec::new();
            for ins in &self.instrs[ti..bi] {
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                    && ins.target.map_or(false, |t| t > ins.offset)
                {
                    if let Some(&hi) = self.idx_of.get(&ins.offset) {
                        if self.instrs[hi + 1..]
                            .iter()
                            .take(3)
                            .any(|x| x.op == Op::PUSH_EXC_INFO)
                        {
                            let ext = self.chain_extent(ins.offset + 2);
                            skipped_chains.push((ins.offset, ext.max(ins.offset + 2)));
                        }
                    }
                }
            }
            for k in (ti..bi).rev() {
                let ins = &self.instrs[k];
                if skipped_chains
                    .iter()
                    .any(|(js, je)| ins.offset > *js && ins.offset < *je)
                {
                    continue;
                }
                if ins.op == Op::PUSH_EXC_INFO {
                    handler_origin = true;
                    break;
                }
                if ins.is_backward
                    && matches!(
                        ins.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                            | Op::FOR_ITER
                            | Op::FOR_LOOP
                    )
                {
                    break;
                }
            }
            if handler_origin {
                continue;
            }
            // generator/async resume machinery is never a source loop:
            // JUMP_BACKWARD_NO_INTERRUPT is exclusively the yield-resume
            // edge; a bare back edge directly after YIELD_VALUE/RESUME or
            // inside a SEND/CLEANUP_THROW region belongs to the protocol.
            // A real `while True` body may CONTAIN yields — its back edge
            // sits after body statements, not the resume point.
            let prev_op = if bi > 0 { Some(self.instrs[bi - 1].op) } else { None };
            let prev2_op = if bi > 1 { Some(self.instrs[bi - 2].op) } else { None };
            // direct yield-resume edge: YIELD_VALUE; [RESUME;] back-jump
            // (a lone RESUME follows every 3.11+ CALL — not a signal)
            let resume_edge = matches!(prev_op, Some(Op::YIELD_VALUE))
                || (matches!(prev_op, Some(Op::RESUME))
                    && matches!(prev2_op, Some(Op::YIELD_VALUE)));
            if bj.op == Op::JUMP_BACKWARD_NO_INTERRUPT
                || resume_edge
                || self.instrs[ti..bi].iter().any(|ins| {
                    matches!(
                        ins.op,
                        Op::YIELD_FROM
                            | Op::SEND
                            | Op::GET_YIELD_FROM_ITER
                            | Op::CLEANUP_THROW
                    )
                })
            {
                continue;
            }
            let mut breaks: Vec<usize> = Vec::new();
            // 3.10 while-True lays a line-marker NOP at the loop head:
            // `continue` targets the NOP (22) while the body's own back
            // edge targets the instruction after it (24) — one logical
            // top, two offsets. Normalize back edges through
            // effective_offset so the continue does not disqualify the
            // REAL loop span (binhex 3.10 HexBin.__init__: the rejected
            // (24,68) span left the fake (22,56) continue-derived loop,
            // trapping it inside the preceding isinstance guard and
            // stranding the `if ch == b':': break`)
            // the NOP must be a line marker IMMEDIATELY before the top
            let nop_top = ti > 0
                && self.instrs[ti - 1].op == Op::NOP
                && self.instrs[ti - 1].offset < t;
            let clean = self.instrs[ti..bi].iter().all(|ins| {
                ins.target.map_or(true, |it| {
                    if (it >= t && it <= bj.offset)
                        || (ins.is_backward && it == t)
                        || (nop_top
                            && ins.is_backward
                            && ins.offset < bj.offset
                            && self.idx_of.get(&it).map_or(false, |&ii| {
                                ii + 1 == ti
                            }))
                    {
                        true
                    } else if matches!(
                        ins.op,
                        Op::SETUP_FINALLY
                            | Op::SETUP_EXCEPT
                            | Op::SETUP_CLEANUP
                            | Op::SETUP_LOOP
                            | Op::SETUP_WITH
                            | Op::SETUP_ASYNC_WITH
                    ) {
                        // a SETUP's target is its exception-time handler /
                        // exit protocol, not a source-level jump: neither
                        // an in-region flow target nor a `break`
                        // (_osx_support 3.9 compiler_fixup `while True:
                        // try: ... except ValueError: break` - the handler
                        // target 34 past the back edge was miscounted as a
                        // uniform break exit, and the loop top being a
                        // SETUP made section-6's rotated-while arm claim
                        // the one-shot `if stripArch` guard as the loop
                        // cond, merging `if c: while True:` into `while c:`
                        // and turning the handler's break into `pass` -
                        // an infinite loop at runtime). When the SETUP is
                        // the loop TOP itself (`while True: try:`), its
                        // handler-target forward jump past the chain is
                        // the handler-break's loop exit - record it (the
                        // break flies over any guard-else arms to the
                        // merge, so the span must reach it or the loop
                        // closes before its own break and the break
                        // degrades to `pass` with the following elif arms
                        // skipped)
                        if self.instrs[ti].offset == t
                            && !ins.is_backward
                            && it > bj.offset
                        {
                            let ext = self.chain_extent(it);
                            if it < ext {
                                breaks.push(ext);
                            } else {
                                breaks.push(it);
                            }
                        }
                        true
                    } else if !ins.is_backward && it > bj.offset {
                        // a `break` flying to the loop exit
                        breaks.push(it);
                        true
                    } else {
                        false
                    }
                })
            });
            if !clean {
                continue;
            }
            let uniform_exit = breaks.first().copied().and_then(|e| {
                if breaks.iter().all(|b| *b == e) {
                    Some(e)
                } else {
                    None
                }
            });
            match uniform_exit {
                Some(e) => found.push((t, e, bi)),
                None => found.push((t, bj.end(), bi)),
            }
        }
        // multiple back edges to the SAME top (3.14 threads each break
        // to a return, leaving several): an inner edge's span misreads
        // the jump into a later then-arm as a break — per top, keep the
        // OUTERMOST (last) edge that passed the body checks
        let mut resolved: Vec<(usize, usize)> = Vec::new();
        let mut best: Vec<(usize, usize, usize)> = Vec::new();
        let mut order: Vec<usize> = Vec::new();
        for (t, e, bi) in found {
            if let Some(pos) = best.iter().position(|x| x.0 == t) {
                if bi > best[pos].2 {
                    best[pos] = (t, e, bi);
                }
            } else {
                order.push(t);
                best.push((t, e, bi));
            }
        }
        for t in order {
            if let Some(x) = best.iter().find(|x| x.0 == t) {
                resolved.push((t, x.1));
            }
        }
        // NOP-marker tops: a continue-derived fake span (top = the NOP,
        // end = an inner cond target) and the real back-edge span (top =
        // NOP+2) share one logical top — group ONLY when the earlier
        // offset is a NOP line marker immediately before the other, and
        // keep the span from the LAST (outermost) back edge. Raw offsets
        // otherwise: effective_offset also skips 3.11+ RESUME-era
        // NOT_TAKEN/CACHE padding and shifted loop opens there
        // (_sitebuiltins/_weakrefset/code 3.11-3.13 regressed under the
        // wide form)
        let nop_before = |off: usize| -> bool {
            self.idx_of
                .get(&off)
                .map_or(false, |&i| i > 0 && self.instrs[i - 1].op == Op::NOP)
        };
        let mut dedup: Vec<(usize, usize, usize)> = Vec::new();
        for (i, (t, e)) in resolved.into_iter().enumerate() {
            let te = self.effective_offset(t);
            let grp = dedup
                .iter()
                .position(|(t2, _, _)| {
                    *t2 == t
                        || ((nop_before(t) || nop_before(*t2))
                            && self.effective_offset(*t2) == te)
                });
            match grp {
                Some(k) => {
                    // keep the later (outermost back edge) span; the
                    // group key must be the NON-marker top: back_edge_exit
                    // keys off a backward edge targeting exactly the
                    // start, and only the real top has one (the continue
                    // targets the NOP)
                    // the marker top IS the NOP; the real top is the
                    // offset after it
                    let at_nop = |off: usize| {
                        self.idx_of
                            .get(&off)
                            .map_or(false, |&i| self.instrs[i].op == Op::NOP)
                    };
                    let key = if at_nop(t) { dedup[k].0 } else { t };
                    dedup[k] = (key, e, i);
                }
                None => dedup.push((t, e, i)),
            }
        }
        dedup.sort_by_key(|x| x.2);
        self.while_true_loops =
            dedup.into_iter().map(|(t, e, _)| (t, e)).collect();
    }

    /// 3.12+ pre-checked rotated while, FALL-THROUGH-TO-BODY variant
    /// (csv 3.13 _guess_delimiter): convert the merged pre-check If into
    /// the real While when the fall-through is a prescan-claimed
    /// while-True top and the tail re-eval mirrors the pre-check chain.
    fn try_pre_rot_fallthrough(&mut self, target: usize, jump_if_true: bool) -> bool {
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        // 3.12+ pre-checked rotated while, FALL-THROUGH-TO-BODY
        // variant (csv 3.13 _guess_delimiter `while len(delims)
        // == 0 and consistency >= threshold:`): the pre-check
        // chain's last jump falls through onto the body top —
        // which the while-True prescan claimed — and the tail
        // re-eval chain mirrors the pre-check instruction-for-
        // instruction before the back edge. Convert the merged
        // pre-check If (split_cond already folded the and-chain)
        // into the real While and un-claim the prescan top.
        if self.version.at_least(3, 12) && !jump_if_true {
            let fall_top = self
                .idx_of
                .get(&self.cur_next)
                .map(|&fi2| self.instrs[fi2].offset);
            let claimed = fall_top
                .and_then(|ft| {
                    self.while_true_loops
                        .iter()
                        .find(|(t, _)| *t == ft)
                        .copied()
                });
            if let (Some(ft), Some((wtop, wend))) = (fall_top, claimed) {
                // back edge: the last backward jump onto wtop
                let back = self
                    .instrs
                    .iter()
                    .filter(|x| {
                        x.offset < wend
                            && x.is_backward
                            && x.target == Some(wtop)
                            && matches!(
                                x.op,
                                Op::JUMP_BACKWARD
                                    | Op::JUMP_ABSOLUTE
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                            )
                    })
                    .map(|x| x.offset)
                    .last();
                if let Some(bo) = back {
                    // walk the pre-check chain back from this
                    // jump: contiguous pure-value runs and
                    // same-exit same-polarity cond jumps
                    // chain start = walk back over [pure-value operand
                    // runs + same-exit PJIF links]; stop at the first
                    // non-pure instruction (the preceding statement)
                    let mut s = ci;
                    let mut chain_lo = ci;
                    loop {
                        while s > 0 {
                            let p = &self.instrs[s - 1];
                            if is_pure_value_op(p.op)
                                || matches!(
                                    p.op,
                                    Op::TO_BOOL
                                        | Op::NOP
                                        | Op::NOT_TAKEN
                                        | Op::CACHE
                                )
                            {
                                s -= 1;
                                chain_lo = s;
                                continue;
                            }
                            break;
                        }
                        if s > 0
                            && matches!(
                                self.instrs[s - 1].op,
                                Op::POP_JUMP_IF_FALSE
                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                            )
                            && self.instrs[s - 1].target == Some(target)
                        {
                            s -= 1;
                            continue;
                        }
                        break;
                    }
                    let seq = |a: usize, b: usize| -> Vec<(u8, u32)> {
                        self.instrs[a..=b]
                            .iter()
                            .filter(|x| {
                                !matches!(
                                    x.op,
                                    Op::NOP | Op::NOT_TAKEN | Op::CACHE
                                )
                            })
                            // jumps compare by absolute TARGET: the
                            // 3.13 PJIF arg is a relative delta that
                            // differs between the pre-check and the
                            // re-eval copy even with the same exit
                            .map(|x| {
                                (
                                    x.op as u8,
                                    x.target.map(|t| t as u32).unwrap_or(x.arg),
                                )
                            })
                            .collect()
                    };
                    let pre_seq = seq(chain_lo, ci);
                    // re-eval chain: same-length span ending at
                    // the instruction before the back edge
                    let pre_len = ci - chain_lo + 1;
                    let bi_opt = self.idx_of.get(&bo).copied();
                    if let (true, Some(bi)) =
                        (pre_len > 0 && bi_opt.map_or(false, |bi2| bi2 >= pre_len), bi_opt)
                    {
                        let re_seq = seq(bi - pre_len, bi - 1);
                        // re-eval chain must end at a same-exit
                        // cond jump and mirror the pre-check
                        let re_last_cj = self.instrs[bi - 1].target
                            == Some(target)
                            && matches!(
                                self.instrs[bi - 1].op,
                                Op::POP_JUMP_IF_FALSE
                                    | Op::POP_JUMP_FORWARD_IF_FALSE
                            );
                                if re_last_cj && re_seq == pre_seq {
                            // the merged pre-check If must be
                            // open on top (split_cond folded the
                            // chain) and start at/before the
                            // chain's first operand
                            // the merged pre-check If starts at the
                            // FIRST jump's fall-through (past operand
                            // 1's run) — require only that it lies
                            // within the chain span and ends at the
                            // shared exit
                            let chain_start_off =
                                self.instrs[s].offset;
                            let ok_top = self
                                .blocks
                                .last()
                                .map_or(false, |b| {
                                    b.kind == BlockType::If
                                        && b.cond_set
                                        && b.end == target
                                        && b.start >= chain_start_off
                                        && b.start <= self.cur_offset
                                });
                            if ok_top {
                                let wcond = self
                                    .blocks
                                    .last()
                                    .and_then(|b| b.cond.clone())
                                    .unwrap();
                                self.blocks.pop();
                                self.while_true_loops
                                    .retain(|(t, _)| *t != wtop);
                                let mut blk = Block::new(
                                    BlockType::While,
                                    wtop,
                                    target,
                                );
                                blk.cond = Some(wcond);
                                blk.cond_set = true;
                                blk.cond_end = self.instrs[ci].end();
                                blk.jump_if_true = false;
                                blk.stack_depth = self.stack.len();
                                self.blocks.push(blk);
                                self.skip_until = Some(wtop);
                                return true;
                            }
                        }
                    }
                    let _ = ft;
                }
            }
        }
        false
    }

    /// OR-shaped pre-checked rotated while detection/conversion. See the
    /// call site in handle_cond_jump. `cond` is this (A-link) jump's
    /// operand, `target` the shared body top.
    fn try_pre_rot_or(&mut self, cond: &ExprRef, target: usize) -> bool {
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let next_real = |i: usize| -> Option<usize> {
            let mut k = i + 1;
            while k < self.instrs.len() && is_pad(&self.instrs[k]) {
                k += 1;
            }
            (k < self.instrs.len()).then_some(k)
        };
        // A operand region must be non-empty
        let mut a_lo = ci;
        while a_lo > 0 {
            let p = &self.instrs[a_lo - 1];
            if is_pure_value_op(p.op) || matches!(p.op, Op::TO_BOOL) || is_pad(p) {
                a_lo -= 1;
            } else {
                break;
            }
        }
        if a_lo == ci {
            return false;
        }
        // B region: [cur_next, jb) pure values ending in a forward
        // PJIF-family jump to the loop exit; its fall-through is the
        // body top (comparing EFFECTIVE offsets: a 3.13 NOP line marker
        // can sit at the top)
        let Some(&ni) = self.idx_of.get(&self.cur_next) else {
            return false;
        };
        let mut k = ni;
        while k < self.instrs.len() {
            let ins = &self.instrs[k];
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) && !ins.is_backward
            {
                break;
            }
            if !is_pure_value_op(ins.op)
                && !matches!(ins.op, Op::TO_BOOL)
                && !is_pad(ins)
            {
                return false;
            }
            k += 1;
        }
        if k >= self.instrs.len() || k <= ni {
            return false;
        }
        let jb = k;
        let Some(exit) = self.instrs[jb].target else {
            return false;
        };
        if exit <= self.instrs[jb].offset {
            return false;
        }
        let ft_ok = next_real(jb).map_or(false, |i2| {
            self.effective_offset(self.instrs[i2].offset)
                == self.effective_offset(target)
        });
        if !ft_ok {
            return false;
        }
        // final back edge: the LAST backward unconditional jump onto the
        // body top between the B jump and the loop exit
        let Some(be_idx) = self
            .instrs
            .iter()
            .filter(|x| {
                x.offset < exit
                    && x.offset > self.instrs[jb].offset
                    && x.is_backward
                    && x.target == Some(target)
                    && matches!(
                        x.op,
                        Op::JUMP_BACKWARD
                            | Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                    )
            })
            .map(|x| x.offset)
            .last()
            .and_then(|bo| self.idx_of.get(&bo).copied())
        else {
            return false;
        };
        // B' region: [.., be_idx) ends with a jump matching jb (op +
        // absolute exit target); its operand run mirrors B's
        let b_run: Vec<u8> = self.instrs[ni..jb]
            .iter()
            .filter(|x| !is_pad(x))
            .map(|x| x.op as u8)
            .collect();
        if b_run.is_empty() || be_idx == 0 {
            return false;
        }
        let bjump = &self.instrs[be_idx - 1];
        if is_pad(bjump)
            || bjump.op != self.instrs[jb].op
            || bjump.target != Some(exit)
            || bjump.is_backward
        {
            return false;
        }
        let mut b_lo = be_idx - 1;
        let mut run: Vec<u8> = Vec::new();
        while b_lo > 0 {
            let p = &self.instrs[b_lo - 1];
            if is_pad(p) {
                b_lo -= 1;
                continue;
            }
            if is_pure_value_op(p.op) || matches!(p.op, Op::TO_BOOL) {
                run.push(p.op as u8);
                b_lo -= 1;
                continue;
            }
            break;
        }
        run.reverse();
        if run != b_run {
            return false;
        }
        // mid JB -> body top between the A' and B' regions
        if b_lo == 0 {
            return false;
        }
        let mid = &self.instrs[b_lo - 1];
        if !(mid.is_backward
            && mid.target == Some(target)
            && matches!(
                mid.op,
                Op::JUMP_BACKWARD
                    | Op::JUMP_ABSOLUTE
                    | Op::JUMP_BACKWARD_NO_INTERRUPT
            ))
        {
            return false;
        }
        // A' region: ends with the polarity-inverse of this A jump,
        // targeting the B' region start; operand run mirrors A's
        if b_lo < 2 {
            return false;
        }
        let a_jump_idx = b_lo - 2;
        let Some(ajump) = self.instrs.get(a_jump_idx) else {
            return false;
        };
        if is_pad(ajump) {
            return false;
        }
        let inverse_ok = match (self.instrs[ci].op, ajump.op) {
            (Op::POP_JUMP_IF_NONE, Op::POP_JUMP_IF_NOT_NONE)
            | (Op::POP_JUMP_IF_NOT_NONE, Op::POP_JUMP_IF_NONE)
            | (Op::POP_JUMP_FORWARD_IF_NONE, Op::POP_JUMP_FORWARD_IF_NOT_NONE)
            | (Op::POP_JUMP_FORWARD_IF_NOT_NONE, Op::POP_JUMP_FORWARD_IF_NONE)
            | (Op::POP_JUMP_BACKWARD_IF_NONE, Op::POP_JUMP_BACKWARD_IF_NOT_NONE)
            | (Op::POP_JUMP_BACKWARD_IF_NOT_NONE, Op::POP_JUMP_BACKWARD_IF_NONE)
            | (Op::POP_JUMP_IF_TRUE, Op::POP_JUMP_IF_FALSE)
            | (Op::POP_JUMP_IF_FALSE, Op::POP_JUMP_IF_TRUE)
            | (Op::POP_JUMP_FORWARD_IF_TRUE, Op::POP_JUMP_FORWARD_IF_FALSE)
            | (Op::POP_JUMP_FORWARD_IF_FALSE, Op::POP_JUMP_FORWARD_IF_TRUE) => {
                true
            }
            _ => false,
        };
        if !inverse_ok || ajump.target != Some(self.instrs[b_lo].offset) {
            return false;
        }
        let a_run: Vec<u8> = self.instrs[a_lo..ci]
            .iter()
            .filter(|x| !is_pad(x))
            .map(|x| x.op as u8)
            .collect();
        let mut a2_lo = a_jump_idx;
        let mut arun: Vec<u8> = Vec::new();
        while a2_lo > 0 {
            let p = &self.instrs[a2_lo - 1];
            if is_pad(p) {
                a2_lo -= 1;
                continue;
            }
            if is_pure_value_op(p.op) || matches!(p.op, Op::TO_BOOL) {
                arun.push(p.op as u8);
                a2_lo -= 1;
                continue;
            }
            break;
        }
        arun.reverse();
        if arun != a_run || a_run.is_empty() {
            return false;
        }
        // everything matched: build `while A or B:` over [target, exit)
        let b_expr = match self.sim_value_region(ni, jb) {
            Some(e) => e,
            None => return false,
        };
        let merged: ExprRef = Rc::new(Expr::BoolOp {
            op: BoolOpKind::Or,
            values: vec![cond.clone(), b_expr],
        });
        self.while_true_loops.retain(|(t, _)| *t != target);
        let mut blk = Block::new(BlockType::While, target, exit);
        blk.cond = Some(merged);
        blk.cond_set = true;
        blk.cond_end = self.instrs[ci].end();
        blk.jump_if_true = false;
        blk.stack_depth = self.stack.len();
        self.blocks.push(blk);
        // drop the tail re-eval when the walk reaches it (its mid link
        // targets the B' region head, which dup_while cannot match)
        let reval_start = self.instrs[a2_lo].offset;
        self.or_rot_revals.push((reval_start, self.instrs[be_idx].end()));
        self.skip_until = Some(target);
        true
    }

    fn handle_jump_backward(&mut self, raw_target: usize) {
        // a backward target landing on an EXTENDED_ARG prefix byte (the
        // decoder keys idx_of by post-prefix offset/end, so the prefix
        // start collides with the PREVIOUS instruction's end — cgitb
        // 3.8/3.9 html's outer-for back edge targeted 158 = GET_ITER's
        // end = the EXTARG start of FOR_ITER@160) fails every loop
        // match and leaks a stray `continue`. Remap ONLY when the raw
        // target resolves to an EXTARG-prefixed instruction's start
        // (3.12+ relative backward jumps already decode to logical
        // offsets — a blanket remap broke configparser/_strptime
        // 3.10-3.13 loop matching).
        let target = {
            let resolves_to_loop = |t: usize| {
                self.blocks.iter().any(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && (b.start == t || b.cond_end == t)
                })
            };
            let alt = self
                .instrs
                .iter()
                .find(|x| x.start == raw_target && x.start != x.offset)
                .map(|x| x.offset);
            // 3.10+ rotated-while/JUMP_BACKWARD flows register and
            // match back-edge targets in the RAW form and route the
            // apparent mismatch through the dup_while/jfold machinery
            // (configparser 3.13 _read_inner, _strptime 3.10+: remapping
            // there diverted the edges into the plain loop-close path
            // and tore the chains) — remap only in the pre-3.10
            // non-rotated era
            match alt {
                Some(a)
                    if !self.version.at_least(3, 10)
                        && a != raw_target
                        && !resolves_to_loop(raw_target)
                        && resolves_to_loop(a)
                        // remap ONLY the loop's NATURAL back edge (no
                        // later backward jump to the same top): an
                        // explicit `continue` in mid-body relies on the
                        // raw-mismatch fallback to emit its Continue
                        // (_strptime 3.8/3.9 TimeRE_cache.__getitem__'s
                        // eight continues were swallowed by the matched
                        // loop-close path under an unconditional remap)
                        && !self.instrs.iter().any(|x| {
                            x.offset > self.cur_offset
                                && x.is_backward
                                && (x.target == Some(raw_target)
                                    || x.target == Some(a))
                        }) =>
                {
                    a
                }
                _ => raw_target,
            }
        };
        // unreachable back-edge padding: unoptimized compilers (py2.6)
        // emit JUMP_ABSOLUTE to the loop top right after a RAISE/RETURN
        // ending a then-arm. Fall-through from a terminator is impossible
        // and nothing jumps onto this edge, so it is dead — emitting a
        // `continue` for it lands inside the terminating arm and flags
        // the frame incomplete before the real back edge arrives.
        {
            let dominated_by_terminator = self
                .idx_of
                .get(&self.cur_offset)
                .and_then(|&ci| ci.checked_sub(1).map(|p| &self.instrs[p]))
                .map_or(false, |prev| {
                    matches!(
                        prev.op,
                        Op::RAISE_VARARGS | Op::RETURN_VALUE | Op::RETURN_CONST
                    )
                });
            if dominated_by_terminator && !self.targets.contains(&self.cur_offset) {
                return;
            }
        }
        // dead duplicate back edge after a `break`: the compiler lays a
        // fall-through JABS-to-loop-top right after the break's exit jump
        // when the break flew out of a branch arm (3.8 asynchat
        // handle_read: `if index: ...; break else: collect-all` — the
        // break at 444→exit is followed by dead glue 446→top). Taking it
        // as a real back edge tears down the just-rescued open else
        // region before the walk enters it.
        {
            let dominated_by_break = self
                .idx_of
                .get(&self.cur_offset)
                .and_then(|&ci| ci.checked_sub(1).map(|p| &self.instrs[p]))
                .map_or(false, |prev| {
                    !prev.is_backward
                        && matches!(
                            prev.op,
                            Op::JUMP_ABSOLUTE
                                | Op::JUMP_FORWARD
                                | Op::JUMP
                                | Op::JUMP_BACKWARD
                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                        )
                        && prev
                            .target
                            .map_or(false, |t| t > prev.offset)
                        && prev.target.map_or(false, |t| {
                            self.find_loop_exit(t).is_some()
                        })
                });
            if dominated_by_break && !self.targets.contains(&self.cur_offset) {
                return;
            }
        }
        // 3.8-3.10 inline finally inside a loop body: the back edge
        // follows the inline finally copy — fold the chain FIRST so the
        // Try lands in the loop body before the loop closes
        let fold_inline_fin = !self.version.at_least(3, 11)
            && self
                .legacy_try
                .as_ref()
                .map_or(false, |l| {
                    l.has_finally
                        && l.else_start
                            .map_or(false, |es| self.cur_offset >= es)
                })
            && self.blocks.iter().any(|b| {
                matches!(b.kind, BlockType::While | BlockType::For)
                    && (b.start == target || b.cond_end == target)
            });
        if !fold_inline_fin
            && !self.version.at_least(3, 11)
            && self.legacy_try
                .as_ref()
                // only when the chain's handler region lies PAST this
                // back edge (loop body IS the try); a chain already
                // inside/past its handler folds through the regular path
                .map_or(false, |l| l.handler_start > self.cur_offset)
            && self.pending_loop_close_at_chain.is_none()
            && self.blocks.iter().any(|b| {
                matches!(b.kind, BlockType::While | BlockType::For)
                    && (b.start == target || b.cond_end == target)
            })
        {
            // the loop body IS an unfinished legacy try chain (an except
            // chain whose handler lies past this back edge): keep the
            // loop open, let the chain fold inside it, then close it
            self.pending_loop_close_at_chain = Some(target);
            if let Some(b) = self.blocks.iter_mut().rev().find(|b| {
                matches!(b.kind, BlockType::While | BlockType::For)
                    && (b.start == target || b.cond_end == target)
            }) {
                // a prescan-synthesized while-True with a recorded exit
                // (a `while True: try: ... except: break` whose handler
                // break flies to it): cap the keep-open extension AT that
                // exit instead of MAX, so the handler break still matches
                // the loop exit while the chain walks - MAX made
                // find_loop_exit miss and the break degrade to `pass`
                // with the following guard-else arms skipped (_osx_support
                // 3.9 compiler_fixup)
                let recorded = self
                    .while_true_loops
                    .iter()
                    .find(|(t, _)| *t == b.start)
                    .map(|(_, e)| *e);
                b.end = match recorded {
                    Some(e) if e > self.cur_offset => e,
                    _ => usize::MAX,
                };
            }
            return;
        }
        if fold_inline_fin {
            self.flush_pending_stores();
            if let Some(l) = self.legacy_try.take() {
                // the out-of-line handler copy is exception-path only —
                // skip it so its statements do not leak into the flow
                let skip_to = self
                    .idx_of
                    .get(&l.handler_start)
                    .and_then(|&hi| {
                        self.instrs[hi..]
                            .iter()
                            .take(200)
                            .find(|x| matches!(x.op, Op::RERAISE | Op::END_FINALLY))
                            .map(|x| x.end())
                    })
                    .filter(|e| *e > self.cur_offset);
                self.restore_legacy_nest();
                self.push_legacy_try(l);
                if let Some(s) = skip_to {
                    if self.skip_until.map_or(true, |cur| cur < s) {
                                                self.skip_until = Some(s);
                    }
                }
            }
        }
        // dead back-edge padding: the loop owning this top already closed
        if self
            .closed_loop_tops
            .iter()
            .any(|t| self.effective_offset(*t) == self.effective_offset(target))
        {
            return;
        }
        // back edge at the end of the try body or inside the handler chain
        // (`continue`-equivalent): not the loop's own back edge, ignore it
        // so the loop stays open for the handler chain / else region that
        // follows; the chain machinery emits the Try at the real back edge
        if self.legacy_try.as_ref().map_or(false, |l| {
            (self.cur_offset >= l.handler_start
                && l.else_start.map_or(true, |es| self.cur_offset < es))
                || (l.handlers.is_empty()
                    && l.else_start.is_none()
                    && self.cur_offset < l.handler_start)
        }) {
            if self.legacy_handler.is_some() && !self.in_handler_prelude {
                // handler still open (past its prelude): an explicit
                // `continue` in the handler body — the implicit post-handler
                // back edge comes after POP_EXCEPT/END_FINALLY folded it.
                // py2 emits dead duplicate back edges after the continue;
                // only the first is real.
                let already = self
                    .legacy_handler
                    .as_ref()
                    .map_or(false, |h| matches!(h.body.last(), Some(Stmt::Continue)));
                // py2 has no POP_EXCEPT fold, so the handler is STILL
                // open at its back edge, and a LONE JABS to the loop top
                // is ambiguous: the implicit handler fall-through (try is
                // the loop's last statement — atexit _run_exitfuncs) and
                // an explicit standalone `except: continue` that skips
                // the rest of the body (anydbm import loop) compile
                // identically. Discriminate by what the jump flies over:
                // real body statements between the chain and the loop's
                // natural back edge / POP_BLOCK make it a continue;
                // hitting the chain end first makes it implicit (the
                // emitted Continue would duplicate the fall-through edge
                // on recompile). An explicit continue after body
                // statements still shows the dead duplicate JABS (py2
                // emits it right after), caught mid-scan.
                let explicit = if self.version.major == 2 {
                    match self.idx_of.get(&self.cur_offset) {
                        Some(&ci) => {
                            let jt = self.instrs[ci].target;
                            let bound = self
                                .blocks
                                .iter()
                                .rev()
                                .find(|b| {
                                    matches!(b.kind, BlockType::While | BlockType::For)
                                        && b.start == target
                                })
                                .map(|b| b.end)
                                .unwrap_or(usize::MAX);
                            // explicit continue after body statements:
                            // py2 emits the dead duplicate JABS ADJACENT
                            // to the statement's own jump (a same-target
                            // backward jump further out is the NEXT
                            // handler's edge — atexit misfire lesson)
                            let dup_adjacent = self
                                .instrs
                                .get(ci + 1)
                                .map_or(false, |x| {
                                    x.is_backward
                                        && matches!(
                                            x.op,
                                            Op::JUMP_ABSOLUTE | Op::JUMP
                                        )
                                        && x.target == jt
                                });
                            let mut verdict = if dup_adjacent {
                                Some(true)
                            } else {
                                None
                            };
                            for x in self.instrs[ci + 1..].iter() {
                                if verdict.is_some() || x.offset >= bound {
                                    break;
                                }
                                match x.op {
                                    // the loop's natural back edge / exit:
                                    // the chain ended with nothing skipped
                                    Op::JUMP_ABSOLUTE | Op::JUMP if x.is_backward => {
                                        verdict = Some(false);
                                        break;
                                    }
                                    Op::POP_BLOCK | Op::BREAK_LOOP => {
                                        verdict = Some(false);
                                        break;
                                    }
                                    // END_FINALLY is chain glue: the
                                    // loop's natural back edge sits AFTER
                                    // it — an explicit continue's own
                                    // jump precedes it (ast 2.6
                                    // iter_fields), an implicit
                                    // fall-through shows no edge before
                                    // it (atexit)
                                    Op::END_FINALLY => {}
                                    // forward jump past the chain: the
                                    // handler exit hops over following
                                    // body flow
                                    Op::JUMP_FORWARD
                                    | Op::JUMP
                                    | Op::JUMP_ABSOLUTE
                                        if !x.is_backward
                                            && x.target
                                                .map_or(false, |t| t > x.offset) =>
                                    {
                                        verdict = Some(true);
                                        break;
                                    }
                                    _ => {}
                                }
                            }
                            verdict.unwrap_or(true)
                        }
                        None => true,
                    }
                } else {
                    true
                };
                if !already
                    && explicit
                    && self
                        .blocks
                        .iter()
                        .any(|b| matches!(b.kind, BlockType::While | BlockType::For) && b.start == target)
                {
                    self.push_stmt(Stmt::Continue);
                }
            }
            return;
        }
        self.close_blocks_at(self.cur_offset);
        let n = self.blocks.len();
        if std::env::var("PYCDC_EG_DBG").is_ok() {
            eprintln!(
                "EG jb [{}] pos={} target={} blocks={:?}",
                self.code.name, self.cur_offset, target,
                self.blocks.iter().map(|b| format!("{:?}[{},{}]{}", b.kind, b.start, b.end, if b.cond_end!=usize::MAX { format!("c{}",b.cond_end) } else { String::new() })).collect::<Vec<_>>()
            );
        }
        for i in (0..n).rev() {
            if matches!(self.blocks[i].kind, BlockType::While | BlockType::For) {
                let b = &self.blocks[i];
                // rotated while back edge: jumps to the body top right after
                // the cond evaluation — pure loop continuation, no-op
                if b.cond_end != usize::MAX && target == b.cond_end && b.start < target {
                    return;
                }
                // 3.12+: the then-branch of an if/else inside a loop can
                // end with JUMP_BACKWARD straight to the loop top (the
                // compiler fuses "skip else" and "continue"). Close the
                // then-part, open the Else region ending at the loop's own
                // back edge, and let that back edge close everything.
                if b.start == target || b.cond_end == target {
                    // pick the block this jump TERMINATES: an open pending
                    // If whose arm ends exactly at this jump (the next
                    // instruction is the block's end -- the jump is the
                    // arm's last act) or which starts at this jump (the
                    // degenerate `if c: break` fusion). An inner If that
                    // merely ENCLOSES the jump keeps its own end
                    // (compileall compile_path: the mechanism used to grab
                    // the innermost `if quiet<2:` guard, park a degenerate
                    // Else on it, and flatten the real else arm into the
                    // loop body).
                    let next_off = self
                        .idx_of
                        .get(&self.cur_offset)
                        .and_then(|&ci2| self.instrs.get(ci2 + 1).map(|x| x.offset));
                    let mut ti: Option<usize> = None;
                    for j in (0..self.blocks.len()).rev() {
                        let qualifies = matches!(self.blocks[j].kind, BlockType::If)
                            && self.blocks[j].else_end.is_none()
                            && self.blocks[j].short_circuit.is_none()
                            && self.blocks[j].end > self.cur_offset;
                        if !qualifies {
                            break;
                        }
                        if self.blocks[j].start == self.cur_offset
                            || Some(self.blocks[j].end) == next_off
                        {
                            ti = Some(j);
                            break;
                        }
                    }
                    if let Some(t_idx) = ti {
                        // an arm EMPTY at this jump is an explicit
                        // continue guard (`if c: continue` — the arm's
                        // only content is this backward jump and the
                        // region after is the fall-through loop body,
                        // not an else arm): emit the Continue inside
                        // the arm and keep the loop open. The else-wrap
                        // below is for MULTI-statement then arms whose
                        // arm-end the compiler fused onto the back edge
                        // (compileall 3.7 compile_path); running it on
                        // an empty arm rendered `if name in done: pass`
                        // + else-wrapped body and leaked a stray
                        // `continue` at the natural back edge (cgitb
                        // 3.8/3.9 html). An empty then arm can never
                        // produce the fused shape (a `pass` arm emits
                        // no arm-end jump at all), so this is unambiguous.
                        if self.blocks[t_idx].stmts.is_empty()
                            && self.blocks[t_idx].start < self.cur_offset
                        {
                            self.blocks[t_idx].stmts.push(Stmt::Continue);
                            return;
                        }
                        // degenerate fusion: the back edge IS the whole
                        // then-region (`if c: break` with fall-through
                        // continue) — record the continue and close; the
                        // Else region holds the break block and the close
                        // normalizer flips the polarity back
                        if self.blocks[t_idx].start == self.cur_offset {
                            let end = self.blocks[t_idx].end;
                            while self.blocks.len() > t_idx + 1 {
                                let e2 = self.blocks.last().map(|t| t.end).unwrap_or(end);
                                self.force_close_top(e2);
                            }
                            let t = self.blocks.last_mut().unwrap();
                            t.stmts.push(Stmt::Continue);
                            self.force_close_top(end);
                            return;
                        }
                        let else_end = self
                            .instrs
                            .iter()
                            .filter(|x| {
                                x.is_backward
                                    && x.target == Some(target)
                                    && x.offset > self.cur_offset
                            })
                            .map(|x| x.offset)
                            .next()
                            .unwrap_or(b.end);
                        while self.blocks.len() > t_idx + 1 {
                            let e2 = self
                                .blocks
                                .last()
                                .map(|t| t.end)
                                .unwrap_or(self.cur_offset);
                            self.force_close_top(e2);
                        }
                        let t = self.blocks.last_mut().unwrap();
                        t.else_end = Some(else_end);
                        let end = t.end;
                        self.force_close_top(end);
                        return;
                    }
                }
                if b.start == target || b.end == target {
                    // SETUP_LOOP-era while: every continue and the final
                    // back edge target the loop top; the loop closes only
                    // when its POP_BLOCK follows this jump
                    let is_setup_era = !self.version.at_least(3, 8)
                        && b.cond_end == usize::MAX
                        && b.end < usize::MAX
                        && self.idx_of.contains_key(&b.end);
                    if is_setup_era {
                        // py2.7+ exits straight into POP_BLOCK; py2.6's
                        // peek-jump condition retains its value, so the
                        // exit is `POP_TOP; POP_BLOCK` — the loop-end back
                        // edge must not be mistaken for a `continue`.
                        let next_is_pop_block =
                            match self.idx_of.get(&self.cur_offset) {
                                Some(&ci) => {
                                    // hop over dead duplicate back edges:
                                    // unoptimized compilers (3.3) emit
                                    // the loop-body end JABS-to-top
                                    // TWICE — the real final back edge
                                    // then has the duplicate (not the
                                    // POP_BLOCK) as its next instruction
                                    // and was misread as a `continue`
                                    // (fileinput 3.3 _test: extra
                                    // continue in the opts loop)
                                    let mut ni = ci + 1;
                                    while let Some(x) = self.instrs.get(ni) {
                                        if x.is_backward
                                            && x.target == Some(target)
                                            && matches!(
                                                x.op,
                                                Op::JUMP_ABSOLUTE
                                                    | Op::JUMP
                                                    | Op::JUMP_BACKWARD
                                            )
                                            // a duplicate targeted only
                                            // by its inner loop's
                                            // SETUP_LOOP (no break ever
                                            // lands on it) is dead too
                                            // (copyreg 3.3 _slotnames:
                                            // the trampoline 240 blocked
                                            // the hop, misreading the
                                            // real final back edge 237
                                            // as a `continue`)
                                            && self
                                                .instrs
                                                .iter()
                                                .filter(|i| {
                                                    i.target == Some(x.offset)
                                                })
                                                .all(|i| i.op == Op::SETUP_LOOP)
                                        {
                                            ni += 1;
                                            continue;
                                        }
                                        break;
                                    }
                                    match self.instrs.get(ni) {
                                        Some(x) if x.op == Op::POP_BLOCK => true,
                                        Some(x) if x.op == Op::POP_TOP => self
                                            .instrs
                                            .get(ni + 1)
                                            .map_or(false, |y| {
                                                y.op == Op::POP_BLOCK
                                            }),
                                        _ => false,
                                    }
                                }
                                None => false,
                            };
                        if !next_is_pop_block {
                            self.push_stmt(Stmt::Continue);
                            return;
                        }
                    }
                    self.closed_loop_tops.push(b.start);
                    // async-for: the back edge is followed by the
                    // CLEANUP_THROW paths and END_ASYNC_FOR — dead for the
                    // linear walk, skip to the continuation
                    let is_async_for = b.is_async
                        && matches!(b.kind, BlockType::For);
                    if is_async_for {
                        if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                            for ins in self.instrs.iter().skip(ci + 1) {
                                if ins.op == Op::END_ASYNC_FOR {
                                                                        self.skip_until = Some(ins.end());
                                    break;
                                }
                                if !matches!(
                                    ins.op,
                                    Op::CLEANUP_THROW
                                        | Op::JUMP_BACKWARD
                                        | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        | Op::JUMP_ABSOLUTE
                                        | Op::POP_TOP
                                        | Op::NOP
                                        | Op::NOT_TAKEN
                                ) {
                                    break;
                                }
                            }
                        }
                    }
                    // close everything above the loop, then the loop itself
                    // exactly once — its close may push a continuation block
                    // (ForElse) that must stay open for the following region
                    while self.blocks.len() > i + 1 {
                        let p = self.blocks.last().map(|x| x.start).unwrap_or(target);
                        self.force_close_top(p);
                    }
                    self.force_close_top(target);
                    return;
                }
                if b.start < target && target < b.end {
                    // back edge into the middle of this loop
                    //
                    // a forward hop onto a dead duplicate back edge
                    // (nothing jumps to the hop itself; the landing edge
                    // is backward to this loop's top) is a chain-collect
                    // trampoline: the compiler routes an if/else arm end
                    // through it and open branch blocks still have their
                    // else regions AHEAD in the walk — force-closing them
                    // here orphans those regions and the walk follows the
                    // hop out of the loop, dropping the rest of the body
                    // (bdb 3.5/3.6 effective: the inner `else: return
                    // (b, True)` and the whole conditional-breakpoint
                    // else branch vanished). Let the trampoline's own
                    // back edge close the loop naturally; keep the
                    // branch blocks open and emit no continue (the edge
                    // is structural, not a source-level statement).
                    let collect_tramp = !self.targets.contains(&self.cur_offset)
                        && self
                            .idx_of
                            .get(&target)
                            .and_then(|&ti| self.instrs.get(ti))
                            .map_or(false, |x| {
                                x.is_backward
                                    && x.target == Some(b.start)
                                    && matches!(
                                        x.op,
                                        Op::JUMP_ABSOLUTE
                                            | Op::JUMP
                                            | Op::JUMP_BACKWARD
                                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    )
                            })
                        && self.blocks.iter().rev().skip(i + 1).any(|x| {
                            matches!(
                                x.kind,
                                BlockType::If | BlockType::Else
                            ) && x.end > self.cur_next
                        });
                    if collect_tramp {
                        return;
                    }
                    while self.blocks.len() > i + 1 {
                        self.force_close_top(target);
                    }
                    self.push_stmt(Stmt::Continue);
                    return;
                }
            }
        }
        // 3.10+ nested break to an EXTARG-prefixed outer-loop head:
        // when the outer for-loop is large enough that its head carries
        // an EXTENDED_ARG prefix, EVERY back edge targets the prefix's
        // first byte (outer.start - prefix_len), not the FOR_ITER offset
        // (outer.start), so the loop match above (keyed on b.start ==
        // target) misses them. A back edge emitted from INSIDE an inner
        // loop nested in that outer loop is a BREAK of the inner loop:
        // the compiler fused "exit inner + iterate outer" into one
        // JUMP_BACKWARD to the outer head, skipping the inner END_FOR
        // (the inner loop is the outer body's last statement, so its
        // exit merges with the outer iteration). The SAME jump at the
        // loop-body top level (a sunk elif-arm back edge) is a natural
        // outer iteration and must stay a flattened continue — the
        // inner-loop guard separates the two. Remapping the prefix or
        // registering the For block at the prefix instead flips
        // is_continue_jump/the jfold `folded` test for the sunk elif-arm
        // edges and mis-nests the whole chain (_strptime 3.13 'y' arm),
        // so the break is recognized here, at the catch-all, where the
        // elif arms never reach. _strptime 3.13 'Z' branch: the
        // inner-for breaks at L699/L702 rendered as continues, letting
        // the timezone loop run on instead of exiting.
        if self.version.at_least(3, 10) {
            let outer_start = self
                .blocks
                .iter()
                .rev()
                .find(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && self.instrs.iter().any(|x| {
                            x.start == target
                                && x.offset == b.start
                                && x.start != x.offset
                        })
                })
                .map(|b| b.start);
            if let Some(outer_start) = outer_start {
                let in_inner_loop = self.blocks.iter().any(|b| {
                    matches!(b.kind, BlockType::While | BlockType::For)
                        && b.start > outer_start
                        && b.start <= self.cur_offset
                });
                if in_inner_loop {
                    self.push_stmt(Stmt::Break);
                    // the break sits in an if/else arm whose sibling arm
                    // follows at the block's end: mark else_end so the
                    // close opens the Else region instead of flattening
                    // the sibling into the loop body (the guard's PJFF
                    // already targeted b.end; a backward break never
                    // set else_end the way a forward arm-exit does)
                    if let Some(top) = self.blocks.last_mut() {
                        if matches!(top.kind, BlockType::If)
                            && top.else_end.is_none()
                            && top.end > self.cur_offset
                        {
                            top.else_end = Some(top.end);
                        }
                    }
                    self.close_inner_blocks_to_loop();
                    return;
                }
            }
        }
        // backward jump that matches no open loop: only emit `continue`
        // when one is actually on the block stack
        if self
            .blocks
            .iter()
            .any(|b| matches!(b.kind, BlockType::While | BlockType::For))
        {
            self.push_stmt(Stmt::Continue);
        } else if self.broken_loop_top == Some(target) {
            // dead back-edge padding after a `break` closed the loop
        } else if self
            .closed_loop_tops
            .iter()
            .any(|t| self.effective_offset(*t) == self.effective_offset(target))
        {
            // dead back-edge padding after the loop already closed
        } else if self.version.at_least(3, 11)
            && self.exc_entries.iter().any(|e| {
                // the jump sits INSIDE an out-of-line handler chain and
                // exits to the main flow: a clause whose body is empty
                // ends `POP_EXCEPT; JUMP_BACKWARD <merge>` (chunk.skip:
                // `except OSError: pass` resumes at the while top). The
                // clause region sub-walk runs it with the loop out of
                // scope (or already closed by the flow's sunk return).
                // Genuine handler `continue`s are rebuilt with the LIVE
                // block stack before this fallback ever runs.
                let ext = self.chain_extent(e.target);
                e.target <= self.cur_offset
                    && self.cur_offset < ext
                    && (target < e.target || target >= ext)
            })
        {
            // 3.11+ handler-exit resume jump — silently consumed
        } else if self
            .blocks
            .first()
            .map_or(false, |b| b.kind == BlockType::Main && b.start > 0)
            && self
                .idx_of
                .get(&target)
                .zip(self.blocks.first().map(|b| b.start))
                .map_or(false, |(&ti, region_start)| {
                    self.instrs[ti].offset < region_start
                })
        {
            // region sub-walk (block stack headed by a Main with a
            // nonzero start = decompile_region): the loop owning this
            // back edge was opened by the MAIN walk (the loop encloses
            // the try whose region is being collected), so it is not
            // on the sub-walk's stack. A backward jump onto an
            // instruction that DOMINATES the region start is that
            // loop's natural tail back edge - the region's statements
            // are already collected; consume it silently
            // (_py_warnings 3.14 warn: the for-in-range tail edge
            // sits inside the split protected range)
        } else {
            self.mark_unclean();
        }
    }

    fn handle_for_iter(&mut self, target: usize, is_async: bool) {
        if !self.pending_stores.is_empty() {
            self.flushing = true;
            self.flush_pending_stores();
            self.flushing = false;
        }
        let iter = self.pop_expr();
        // FOR_ITER leaves the iterator and pushes the next item; the item is
        // consumed by the following STORE (the loop target), so keep the
        // iterator on the stack and let emit_store swallow it.
        self.push(iter.clone());
        self.awaiting_for_target = true;
        // Reuse an open uninitialized While block (SETUP_LOOP era) or open
        // a fresh For block (3.8+).
        let mut convert = false;
        if let Some(top) = self.blocks.last_mut() {
            if matches!(top.kind, BlockType::While) && !top.cond_set {
                convert = true;
            }
        }
        if convert {
            let top = self.blocks.last_mut().unwrap();
            top.kind = BlockType::For;
            // back edges target the FOR_ITER instruction itself, so the
            // block must start there (matches the fresh-For path below)
            top.start = self.cur_offset;
            top.iter = Some(iter);
            top.target = None;
            top.is_async = is_async;
            top.cond_set = true;
            // the FOR_ITER exhaustion exit differs from the SETUP_LOOP
            // target exactly when a for-else region sits between the two:
            // lower the block end to the exit and remember the loop pop
            if target < top.end {
                top.for_setup_end = Some(top.end);
                top.end = target;
            }
        } else {
            // start = FOR_ITER offset so the back edge matches it
            let mut fb = Block::new(BlockType::For, self.cur_offset, target);
            fb.cond_end = self.cur_next;
            fb.iter = Some(iter);
            fb.is_async = is_async;
            fb.cond_set = true;
            self.blocks.push(fb);
        }
    }

    fn handle_pop_block(&mut self) {
        // `with ...: if c: return expr` — the return sits inside an if
        // arm still OPEN at this POP_BLOCK, and the inline with-exit
        // protocol tail follows it. Fold the return into the innermost
        // block (the if arm) and close only that block — the With stays
        // open for a sibling arm's own POP_BLOCK fold (bz2 3.8
        // BZ2File.tell: `if self._mode == _MODE_READ: return
        // self._buffer.tell()` rendered a bare `return`, the CALL_METHOD
        // value lost to the protocol walk).
        if let Some(top) = self.blocks.last() {
            if matches!(top.kind, BlockType::If | BlockType::Else)
                && self
                    .blocks
                    .iter()
                    .rev()
                    .skip(1)
                    .any(|b| b.kind == BlockType::With)
            {
                if let Some(&ni) = self.idx_of.get(&self.cur_next) {
                    if let Some(after) = self.with_return_tail_end(ni) {
                        if matches!(self.stack.last(), Some(Sv::E(_))) {
                            let wend = self
                                .blocks
                                .iter()
                                .rev()
                                .find(|b| b.kind == BlockType::With)
                                .map(|b| b.end)
                                .unwrap_or(usize::MAX);
                            self.fold_with_return(wend, after);
                            return;
                        }
                    }
                }
            }
        }
        // 3.8-3.10: this POP_BLOCK is a NESTED try's body-end but if/else
        // arms opened inside that body are still open (their end is the
        // post-try sunk-copy landing, past this POP_BLOCK — bz2 3.10
        // close `finally: {try: {if closefp: fp.close()} finally: ...}`:
        // the arm trapped the inline-finally stores and the epilogue
        // flush emitted an empty Try). Close the arm blocks first so the
        // Try close below runs.
        if !self.version.at_least(3, 11) {
            while let Some(top) = self.blocks.last() {
                if matches!(top.kind, BlockType::If | BlockType::Else)
                    && top.start < self.cur_offset
                    && top.end > self.cur_offset
                    && self
                        .blocks
                        .iter()
                        .rev()
                        .skip(1)
                        .next()
                        .map_or(false, |b| {
                            b.kind == BlockType::Try
                                && b.start < self.cur_offset
                                && self.cur_offset < b.end
                        })
                    // this POP_BLOCK must be the try body's OWN end: a
                    // RETURN/RAISE/BREAK escape inside an if arm carries
                    // its own POP_BLOCK before the terminator
                    // (_collections_abc 3.8 Sequence.index `if v is
                    // value or v == value: return i` — closing the arm
                    // at the return's POP_BLOCK left `if ...: pass` +
                    // an unconditional `return i`)
                    && !matches!(
                        self
                            .idx_of
                            .get(&self.cur_offset)
                            .and_then(|&pi| self.instrs.get(pi + 1))
                            .map(|x| x.op),
                        Some(Op::RETURN_VALUE)
                            | Some(Op::RETURN_CONST)
                            | Some(Op::RAISE_VARARGS)
                            | Some(Op::BREAK_LOOP)
                            // 3.8 return-in-try escape protocol:
                            // POP_BLOCK; CALL_FINALLY; RETURN (codeop
                            // 3.8 _maybe_compile `if code: return code`
                            // — closing the arm here ejected the return)
                            | Some(Op::CALL_FINALLY)
                    )
                    // a VALUE return escape out of the try (asyncore
                    // 3.8 recv `if not data: ...; return b'' else:
                    // return data`: POP_BLOCK; [loads]; RETURN_VALUE
                    // with the value riding the stack) or a return
                    // under an inline finally copy (codeop 3.9
                    // _maybe_compile `if code: return code` — the copy
                    // follows the POP_BLOCK and the value rides under
                    // it) is the arm's own exit, not the body end.
                    // Only a NONE-return sunk-copy tail ([stores/copy
                    // ops;] LOAD None; RETURN — bz2 3.10 close) marks
                    // the body end: check the first non-pad instruction
                    // before the next RETURN_VALUE/RETURN_CONST.
                    && !{
                        let mut k2 = self
                            .idx_of
                            .get(&self.cur_offset)
                            .map_or(usize::MAX, |pi| pi + 1);
                        let k0 = k2;
                        let mut steps = 0;
                        let mut value_escape = false;
                        let mut saw_call = false;
                        // end index (exclusive) of a complete expression-
                        // statement call (CALL + POP_TOP) right after the
                        // POP_BLOCK: the inline finally copy's head
                        let mut copy_end = None;
                        'scan: while let Some(x) = self.instrs.get(k2) {
                            steps += 1;
                            if steps > 48 {
                                break;
                            }
                            if matches!(
                                x.op,
                                Op::CALL | Op::CALL_FUNCTION | Op::CALL_METHOD
                            ) {
                                saw_call = true;
                            } else if saw_call && x.op == Op::POP_TOP {
                                copy_end = Some(k2 + 1);
                            }
                            if x.target.is_some()
                                || matches!(
                                    x.op,
                                    Op::POP_EXCEPT
                                        | Op::END_FINALLY
                                        | Op::RERAISE
                                        | Op::BEGIN_FINALLY
                                        | Op::POP_FINALLY
                                        | Op::WITH_CLEANUP_START
                                        | Op::WITH_CLEANUP_FINISH
                                        | Op::SETUP_FINALLY
                                        | Op::SETUP_EXCEPT
                                        | Op::SETUP_CLEANUP
                                        | Op::CALL_FINALLY
                                )
                            {
                                // a jump or unwind-protocol instruction
                                // before any return: this POP_BLOCK is
                                // an arm's escape edge (3.8 `if doc:
                                // ...; return` inside try/except
                                // escapes via POP_BLOCK; POP_EXCEPT;
                                // LOAD None; RETURN), not a body end
                                // with a sunk tail
                                value_escape = true;
                                break 'scan;
                            }
                            if matches!(
                                x.op,
                                Op::RETURN_VALUE | Op::RETURN_CONST
                            ) {
                                // prev non-pad instruction decides
                                let mut p = k2;
                                let mut prev_is_none = false;
                                while p > 0 {
                                    p -= 1;
                                    let pp = &self.instrs[p];
                                    if matches!(
                                        pp.op,
                                        Op::NOP
                                            | Op::NOT_TAKEN
                                            | Op::CACHE
                                            | Op::EXTENDED_ARG
                                    ) {
                                        continue;
                                    }
                                    prev_is_none = pp.op == Op::LOAD_CONST
                                        && matches!(
                                            self
                                                .code
                                                .consts
                                                .get(pp.arg as usize)
                                                .map(|o| &**o),
                                            Some(PyObject::None)
                                        );
                                    break;
                                }
                                // 3.10 per-arm duplication: the span
                                // right after this POP_BLOCK is the
                                // inline finally copy (opcode-mirrors
                                // the enclosing Try's out-of-line
                                // handler head) and the return past it
                                // is the function-tail return sunk into
                                // the arm — a body end with a sunk tail,
                                // NOT the arm's own value escape
                                // (_bootsubprocess 3.10 wait:
                                // `POP_BLOCK; os._exit(1); return
                                // self.returncode` — the value-escape
                                // verdict kept Else[54,92] open and the
                                // arm swallowed the copy and the sunk
                                // return, hoisting the whole try out of
                                // the `if pid == 0:` branch). A genuine
                                // arm escape (`return f()` riding the
                                // stack, codeop 3.9) carries its value
                                // UNDER the copy: the span before its
                                // RETURN does not mirror the handler.
                                let fin_copy_mirror =
                                    copy_end.map_or(false, |ce| {
                                        let len = ce - k0;
                                        self.blocks
                                            .iter()
                                            .rev()
                                            .skip(1)
                                            .next()
                                            .filter(|b| {
                                                b.kind == BlockType::Try
                                            })
                                            .and_then(|b| {
                                                self.idx_of.get(&b.end)
                                            })
                                            .map_or(false, |&hi| {
                                                hi + len
                                                    <= self.instrs.len()
                                                    && (k0..ce)
                                                        .zip(hi..hi + len)
                                                        .all(|(a, b)| {
                                                            let ia =
                                                                &self.instrs[a];
                                                            let ib =
                                                                &self.instrs[b];
                                                            op_family_eq(
                                                                ia.op,
                                                                ib.op,
                                                            ) && (!matches!(
                                                                ia.op,
                                                                Op::LOAD_CONST
                                                                    | Op::LOAD_GLOBAL
                                                            ) || ia.arg
                                                                == ib.arg)
                                                        })
                                            })
                                    });
                                value_escape = !(prev_is_none
                                    || fin_copy_mirror
                                    || x.op == Op::RETURN_CONST
                                        && matches!(
                                            self
                                                .code
                                                .consts
                                                .get(x.arg as usize)
                                                .map(|o| &**o),
                                            Some(PyObject::None)
                                        ));
                                break 'scan;
                            }
                            k2 += 1;
                        }
                        value_escape
                    }
                {
                    let at = self.cur_offset;
                    self.force_close_top_cascade(at);
                    continue;
                }
                break;
            }
        }
        // 3.8-3.10 `with` nested in an if arm: the per-path body-end
        // POP_BLOCKs sit INSIDE the arm (its end is the sibling path's
        // POP_BLOCK). Close the arm first so the With-own scan below
        // can run — otherwise the else-path's protocol copy walks as a
        // garbage else arm and the exception handler renders
        // `if not None: pass` (aifc 3.10 __main__ tail). The span to
        // the with handler must be pure exit-protocol material; the
        // own-scan revalidates before actually closing the With.
        if !self.version.at_least(3, 11) {
            while let Some(top) = self.blocks.last() {
                if matches!(top.kind, BlockType::If | BlockType::Else)
                    && top.start < self.cur_offset
                    && top.end > self.cur_offset
                    && self
                        .blocks
                        .iter()
                        .rev()
                        .skip(1)
                        .next()
                        .map_or(false, |b| {
                            b.kind == BlockType::With
                                && b.start < self.cur_offset
                                && self.cur_offset < b.end
                        })
                {
                    let at = self.cur_offset;
                    self.force_close_top_cascade(at);
                    // re-run the With arm for THIS POP_BLOCK: closing
                    // the arm exposed the With as top, but the generic
                    // dispatch below would otherwise wait for the next
                    // path's POP_BLOCK and leave this path's protocol
                    // copy walking as statements
                    if let Some(top2) = self.blocks.last() {
                        if matches!(top2.kind, BlockType::With) {
                            self.handle_pop_block();
                        }
                    }
                    continue;
                }
                break;
            }
        }
        // POP_BLOCK ends Try (no finally) or With or loop bodies (<=3.7).
        if let Some(top) = self.blocks.last() {
            match top.kind {
                BlockType::Try => {
                    let end = top.end;
                    self.force_close_top(end);
                }
                BlockType::With => {
                    // `with ...: return expr` (3.8-3.10): the value is on
                    // the stack and the tail after this POP_BLOCK is the
                    // inline exit protocol ending in RETURN_VALUE. Fold
                    // the return into the with body before the generic
                    // own-POP_BLOCK scan (which either fails on the bare
                    // RETURN — 3.9/3.10 rendered the protocol as
                    // `expr(None, None, None); return` inside the body —
                    // or passes and lets WITH_CLEANUP_START eat the value
                    // — 3.8 rendered `pass` + a lost return).
                    if let Some(&ni) = self.idx_of.get(&self.cur_next) {
                        if self.with_return_tail_end(ni).is_some()
                            && matches!(self.stack.last(), Some(Sv::E(_)))
                        {
                            let after = self.with_return_tail_end(ni).unwrap();
                            let end = top.end;
                            self.fold_with_return(end, after);
                            return;
                        }
                    }
                    // an inner loop/try may have closed via its back
                    // edge/handler, orphaning ITS POP_BLOCK — only the
                    // with's OWN POP_BLOCK closes it: the whole span from
                    // here to the cleanup handler (top.end) must be
                    // exit/cleanup material ([LOAD None;] WITH_CLEANUP*
                    // for sync withs, LOAD None; DUP; DUP; CALL;
                    // GET_AWAITABLE; YIELD_FROM; POP_TOP; JF for async).
                    // An orphaned inner POP_BLOCK is followed by real
                    // body statements and fails the scan.
                    let own = match (
                        self.idx_of.get(&self.cur_offset),
                        self.idx_of.get(&top.end),
                    ) {
                        (Some(&pi), Some(&ei)) if ei > pi + 1 => {
                            let mut all_clean = true;
                            let mut saw_exit = false;
                            // 3.9/3.10 sync withs inline the exit call as
                            // LOAD None; DUP_TOP; DUP_TOP; CALL_FUNCTION 3
                            // (3.11+: LOAD None x3; PRECALL; CALL) with no
                            // WITH_CLEANUP op — count the None operands so
                            // the protocol call marks saw_exit, letting a
                            // generator's sunk bare-return tail
                            // (LOAD None; RETURN) pass the scan
                            // (_threading_local 3.10 _patch: own=false left
                            // the With open past its POP_BLOCK; the tail
                            // return rendered inside the body and the
                            // WITH_EXCEPT_START handler walked as
                            // `if not None: pass`)
                            let mut nones = 0usize;
                            for x in &self.instrs[pi + 1..ei] {
                                match x.op {
                                    Op::WITH_CLEANUP_START
                                    | Op::WITH_CLEANUP_FINISH
                                    | Op::WITH_CLEANUP
                                    | Op::WITH_EXCEPT_START
                                    | Op::GET_AWAITABLE
                                    | Op::YIELD_FROM
                                    | Op::END_ASYNC_FOR
                                    | Op::END_FINALLY
                                    | Op::END_SEND => saw_exit = true,
                                    Op::LOAD_CONST => {
                                        if matches!(
                                            self.code
                                                .consts
                                                .get(x.arg as usize)
                                                .map(|o| &**o),
                                            Some(PyObject::None)
                                        ) {
                                            nones += 1;
                                        }
                                    }
                                    Op::DUP_TOP => nones += 1,
                                    Op::CALL_FUNCTION | Op::CALL
                                        if nones >= 3 && x.arg <= 3 =>
                                    {
                                        saw_exit = true;
                                    }
                                    Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::CACHE
                                    | Op::DUP_TOP_TWO
                                    | Op::ROT_TWO
                                    | Op::ROT_THREE
                                    | Op::ROT_FOUR
                                    | Op::SWAP
                                    | Op::COPY
                                    | Op::POP_TOP
                                    | Op::CALL
                                    | Op::CALL_FUNCTION
                                    | Op::CALL_METHOD
                                    | Op::SEND
                                    | Op::RESUME
                                    | Op::RESUME_CHECK
                                    | Op::JUMP_BACKWARD_NO_INTERRUPT
                                    | Op::EXTENDED_ARG => {}
                                    Op::JUMP_FORWARD | Op::JUMP => {
                                        if x.is_backward {
                                            all_clean = false;
                                            break;
                                        }
                                    }
                                    // the success-path return may be sunk
                                    // between the cleanup protocol and the
                                    // out-of-line handler (3.10) — loads
                                    // and returns are benign AFTER the
                                    // protocol started
                                    Op::LOAD_FAST
                                    | Op::LOAD_NAME
                                    | Op::LOAD_GLOBAL
                                    | Op::LOAD_DEREF
                                    | Op::LOAD_FAST_LOAD_FAST
                                    | Op::LOAD_FAST_BORROW
                                    | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
                                    | Op::LOAD_SMALL_INT
                                    | Op::RETURN_VALUE
                                    | Op::RETURN_CONST
                                        if saw_exit => {}
                                    _ => {
                                        all_clean = false;
                                        break;
                                    }
                                }
                            }
                            all_clean && saw_exit
                        }
                        _ => true,
                    };
                    if own {
                        let end = top.end;
                        self.force_close_top(end);
                    }
                }
                BlockType::Container => {
                    // try/finally container closed at END_FINALLY; ignore
                }
                BlockType::While | BlockType::For
                    if top.end == self.cur_next && top.cond_set =>
                {
                    // SETUP_LOOP-era loop whose end is exactly this
                    // POP_BLOCK: close here so a following else region
                    // (loop_else_end) opens as WhileElse/ForElse
                    let end = top.end;
                    self.force_close_top(end);
                }
                _ => {}
            }
        }
    }

    fn handle_with_setup(&mut self, handler_target: Option<usize>, is_async: bool) {
        let ctx_e = match self.pending_async_with_ctx.take() {
            Some(c) => {
                // <=3.10: consume the awaited __aenter__ placeholder left
                // by BEFORE_ASYNC_WITH + YIELD_FROM
                let _ = self.pop_expr();
                c
            }
            None => self.pop_expr(),
        };
        // SETUP_WITH pushes the bound __exit__ (and 3.2+ two more dummies)
        self.with_exits += 1;
        if let Some(h) = handler_target {
            self.with_handler_starts.insert(h);
        }
        let item = WithItem {
            ctx: ctx_e,
            target: None,
        };
        // the SETUP_WITH* jump target is the exception-time cleanup handler;
        // the normal-exit POP_BLOCK usually sits right before it
        let start = self.cur_next;
        let end = self
            .with_regions
            .get(&start)
            .copied()
            .or(handler_target)
            .unwrap_or(usize::MAX);
        let mut wb = Block::new(BlockType::With, start, end);
        wb.is_async = is_async;
        wb.with_item = Some(item);
        self.blocks.push(wb);
        // The interpreter pushes __exit__ bound methods plus the __enter__
        // result; model the result with a placeholder expression: the
        // following STORE_* turns into the `as` target, POP_TOP discards it.
        self.push(self.name_expr(WITH_RESULT_PLACEHOLDER));
    }

    /// 3.12+ removed the dead JUMP_FORWARD that <=3.11 emitted after an
    /// arm-terminating raise. That jump was load-bearing for the walk:
    /// it marked the enclosing branch's else region before the arm's
    /// label offset was reached. Without it, statements at the labeled
    /// offset (an enclosing else arm) leak into the terminated arm's
    /// still-open If. When a raise terminates an arm and the next
    /// offset is a jump label strictly inside that arm's block span,
    /// close the terminated arm and mark the enclosing branch's else
    /// merge so the standard else-transition opens the arm.
    fn close_terminated_branch_arms(&mut self) {
        // <=3.11 still emits the dead JUMP_FORWARD after the raise; its
        // handle_jump_forward marking is the established path and this
        // hook would double-close (configparser/base64 3.10 blowups)
        if !self.version.at_least(3, 12) {
            return;
        }
        let next = self.cur_next;
        if !self.targets.contains(&next) {
            return;
        }
        // close the innermost open If/Else whose region continues past
        // the label — its arm just terminated at the raise
        let mut marked = false;
        while let Some(top) = self.blocks.last() {
            if !matches!(top.kind, BlockType::If | BlockType::Else) {
                break;
            }
            if top.end <= next {
                break;
            }
            self.force_close_top(next);
            marked = true;
            break;
        }
        if !marked {
            return;
        }
        // the label may be the ENCLOSING branch's else-arm start (its
        // block ends exactly at the label): mark its else merge so the
        // standard else-transition opens the arm instead of flattening
        // it into the parent (the 3.11 dead JF supplied this target;
        // 3.12 removed the jump). The merge is the first offset past
        // the label that some earlier instruction targets.
        // merge = smallest target past the label that some jump from
        // BEFORE the label aims at (the then-arm side): inner labels of
        // the else arm are targeted from inside the arm itself
        let merge = self
            .instrs
            .iter()
            .filter(|x| {
                x.offset < next
                    && x.target.map_or(false, |t| t > next)
            })
            .map(|x| x.target.unwrap())
            .min();
        let merge = match merge {
            Some(m) => m,
            None => return,
        };
        if let Some(top) = self.blocks.last_mut() {
            if matches!(top.kind, BlockType::If)
                && top.end == next
                && top.else_end.is_none()
                && top.short_circuit.is_none()
                && merge > next
            {
                top.else_end = Some(merge);
            }
        }
    }

    fn handle_with_body_end(&mut self) {
        // WITH_CLEANUP(_FINISH) / WITH_EXCEPT_START: close the With block
        if let Some(top) = self.blocks.last() {
            if top.kind == BlockType::With {
                let pos = top.start.max(1);
                self.force_close_top(pos);
            }
        }
    }

    /// `with ...: return expr` tail matcher: starting at the ROT_TWO /
    /// SWAP 2 that lifts the return value over the unmodeled __exit__
    /// slot, match the inline exit protocol up to its RETURN_VALUE and
    /// return the offset just past it. Shapes:
    /// - 3.8: ROT_TWO; BEGIN_FINALLY; WITH_CLEANUP_START;
    ///   WITH_CLEANUP_FINISH; POP_FINALLY; RETURN_VALUE
    /// - 3.9/3.10: ROT_TWO; LOAD None; DUP_TOP; DUP_TOP; CALL_FUNCTION 3;
    ///   POP_TOP; RETURN_VALUE
    /// - 3.11+: SWAP 2; LOAD None x3; [PRECALL]; CALL; POP_TOP;
    ///   RETURN_VALUE
    fn with_return_tail_end(&self, k0: usize) -> Option<usize> {
        let first = self.instrs.get(k0)?;
        if !(first.op == Op::ROT_TWO
            || (first.op == Op::SWAP && (first.arg == 2 || first.arg == 3)))
        {
            return None;
        }
        let mut k = k0 + 1;
        // 3.13/3.14 open the tail with SWAP 3; SWAP 2 (the value rides
        // over two unmodeled exit-protocol slots); fold at the FIRST swap
        // so the popped value is the body's return expression
        if first.op == Op::SWAP
            && first.arg == 3
            && !matches!(
                self.instrs.get(k).map(|x| (x.op, x.arg)),
                Some((Op::SWAP, 2))
            )
        {
            return None;
        }
        if matches!(self.instrs.get(k).map(|x| (x.op, x.arg)), Some((Op::SWAP, 2))) {
            k += 1;
        }
        let mut nones = 0;
        let mut call = false;
        let mut pop_after_call = false;
        let mut cleanup = false;
        while k < self.instrs.len() {
            let x = &self.instrs[k];
            match x.op {
                Op::BEGIN_FINALLY | Op::WITH_CLEANUP_FINISH => k += 1,
                Op::WITH_CLEANUP_START | Op::WITH_CLEANUP => {
                    cleanup = true;
                    k += 1;
                }
                Op::POP_FINALLY => k += 1,
                Op::LOAD_CONST
                    if matches!(
                        self.code.consts.get(x.arg as usize).map(|o| &**o),
                        Some(PyObject::None)
                    ) =>
                {
                    nones += 1;
                    k += 1;
                }
                Op::DUP_TOP => {
                    nones += 1;
                    k += 1;
                }
                Op::PRECALL | Op::NOP | Op::CACHE | Op::NOT_TAKEN | Op::PUSH_NULL => {
                    k += 1;
                }
                Op::CALL_FUNCTION | Op::CALL => {
                    if nones < 3 {
                        return None;
                    }
                    call = true;
                    k += 1;
                }
                // async with: the __aexit__ CALL's result is awaited
                // before the POP_TOP - the SEND/YIELD_VALUE suspension
                // protocol sits between them (contextlib 3.12
                // AsyncContextDecorator.__call__.inner: `async with
                // self._recreate_cm(): return await func(*args,
                // **kwds)`; without this the fold aborted and the
                // exit machinery rendered `await None(None, None)`)
                Op::GET_AWAITABLE
                | Op::SEND
                | Op::END_SEND
                | Op::YIELD_VALUE
                | Op::YIELD_FROM
                | Op::RESUME
                | Op::RESUME_CHECK
                | Op::JUMP_BACKWARD_NO_INTERRUPT
                    if call =>
                {
                    k += 1;
                }
                Op::POP_TOP if call => {
                    pop_after_call = true;
                    k += 1;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST => {
                    if cleanup || (call && pop_after_call) {
                        return Some(x.end());
                    }
                    return None;
                }
                _ => return None,
            }
        }
        None
    }

    /// Extend a with-return skip over the exception-time handler that
    /// follows the folded tail: its WITH_EXCEPT_START/PUSH_EXC_INFO glue
    /// would otherwise render as `if not None: pass` garbage (3.9/3.10
    /// repro) or a stray `None(None, None)` call (3.11+). Bounded by the
    /// 3.11+ exception-table target span; pre-3.11 stops at the first
    /// non-handler material.
    fn with_handler_skip_end(&self, from: usize) -> usize {
        let Some(&k0) = self.idx_of.get(&from) else {
            return from;
        };
        if !matches!(
            self.instrs[k0].op,
            Op::WITH_EXCEPT_START | Op::PUSH_EXC_INFO
        ) && !self.with_handler_starts.contains(&from)
        {
            return from;
        }
        let table_bound = self
            .exc_entries
            .iter()
            .find(|e| e.target == from)
            .map(|e| e.end)
            .unwrap_or(usize::MAX);
        let mut k = k0;
        while k < self.instrs.len() {
            let x = &self.instrs[k];
            if x.offset >= table_bound {
                break;
            }
            match x.op {
                Op::WITH_EXCEPT_START
                | Op::PUSH_EXC_INFO
                | Op::POP_TOP
                | Op::POP_EXCEPT
                | Op::RERAISE
                | Op::END_FINALLY
                | Op::COPY
                | Op::SWAP
                | Op::NOP
                | Op::CACHE
                | Op::NOT_TAKEN
                | Op::RESUME
                | Op::RESUME_CHECK
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_TRUE
                | Op::JUMP_IF_TRUE_OR_POP
                // an ASYNC with's handler awaits the __aexit__ result:
                // the suspension protocol sits between
                // WITH_EXCEPT_START and the POP_JUMP/RERAISE (3.10
                // contextlib inner: the scan broke at GET_AWAITABLE
                // and the handler glue rendered `if not None: pass`)
                | Op::GET_AWAITABLE
                | Op::YIELD_FROM
                | Op::YIELD_VALUE
                | Op::SEND
                | Op::END_SEND
                | Op::JUMP_BACKWARD_NO_INTERRUPT
                | Op::CLEANUP_THROW
                | Op::EXTENDED_ARG => k += 1,
                Op::LOAD_CONST
                    if matches!(
                        self.code.consts.get(x.arg as usize).map(|o| &**o),
                        Some(PyObject::None)
                    ) =>
                {
                    k += 1;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST => return x.end(),
                _ => break,
            }
        }
        self.instrs
            .get(k)
            .map(|x| x.offset)
            .unwrap_or(from)
    }

    /// 3.11+ late with-return fold: the With block closed at its region
    /// end and its Stmt::With is the parent's last statement. Match the
    /// exit-protocol tail at `inst` (ROT_TWO / SWAP 2), pop the value
    /// into the with body's `return`, and skip protocol + handler.
    fn try_fold_late_with_return(&mut self, inst: &Instruction) -> bool {
        if self.with_exits == 0 || !matches!(self.stack.last(), Some(Sv::E(_))) {
            return false;
        }
        let Some(&ki) = self.idx_of.get(&inst.offset) else {
            return false;
        };
        let Some(after) = self.with_return_tail_end(ki) else {
            return false;
        };
        // probe the target shape BEFORE popping so a failed fold leaves
        // the stack untouched
        if !matches!(
            self.blocks.last().and_then(|b| b.stmts.last()),
            Some(Stmt::With { .. })
        ) {
            return false;
        }
        let value = self.pop_expr();
        let ret = match &*value {
            Expr::Const(o) if matches!(&**o, PyObject::None) => Stmt::Return(None),
            _ => Stmt::Return(Some(value)),
        };
        if let Some(top) = self.blocks.last_mut() {
            if let Some(Stmt::With { body, .. }) = top.stmts.last_mut() {
                body.push(ret);
            }
        }
        self.with_exits = self.with_exits.saturating_sub(1);
        let skip_end = self.with_handler_skip_end(after);
        if self.skip_until.map_or(true, |s| s < skip_end) {
                        self.skip_until = Some(skip_end);
        }
        true
    }

    /// Fold a with-return tail: the value on the stack becomes the with
    /// body's `return`, the With block closes, and the exit protocol plus
    /// exception-time handler are skipped.
    fn fold_with_return(&mut self, with_end: usize, tail_after: usize) {
        let value = self.pop_expr();
        let ret = match &*value {
            Expr::Const(o) if matches!(&**o, PyObject::None) => Stmt::Return(None),
            _ => Stmt::Return(Some(value)),
        };
        if let Some(top) = self.blocks.last_mut() {
            top.stmts.push(ret);
        }
        self.force_close_top(with_end);
        self.with_exits = self.with_exits.saturating_sub(1);
        let skip_end = self.with_handler_skip_end(tail_after);
        if self.skip_until.map_or(true, |s| s < skip_end) {
                        self.skip_until = Some(skip_end);
        }
    }

    /// Walk-end flush preparation: if/else arms opened over the
    /// chain's inline-finally copy may still be open (the copy's sunk
    /// tail returns never close them by position). Close them while the
    /// chain is ACTIVE and the else-region redirect is temporarily
    /// extended to the handler start, so their statements route into
    /// finalbody ahead of the flushed Try — otherwise they land as
    /// siblings and the Try loses its finally (cmd 3.10 cmdloop).
    fn close_legacy_region_arms(&mut self) {
        let (es, stop, hs) = match self.legacy_try.as_ref() {
            Some(l) if l.has_finally => match l.else_start {
                Some(es) => (es, l.else_stop, l.handler_start),
                None => return,
            },
            _ => return,
        };
        if stop >= hs {
            return;
        }
        let has_arm = self.blocks.iter().any(|b| {
            matches!(b.kind, BlockType::If | BlockType::Else)
                && b.start >= es
                && b.end > stop
                && b.end <= hs
        });
        if !has_arm {
            return;
        }
        let saved_cur = self.cur_offset;
        if let Some(l) = self.legacy_try.as_mut() {
            l.else_stop = hs;
        }
        self.cur_offset = es;
        loop {
            let arm = match self.blocks.last() {
                Some(b)
                    if matches!(b.kind, BlockType::If | BlockType::Else)
                        && b.start >= es
                        && b.end <= hs =>
                {
                    (b.end, b.stmts.is_empty())
                }
                _ => break,
            };
            if arm.1 {
                // emptied by the region redirect (its content already
                // sits in finalbody): drop the shell without emitting
                // an `if cond: pass` wrapper
                self.blocks.pop();
            } else {
                self.force_close_top_cascade(arm.0);
            }
        }
        self.cur_offset = saved_cur;
    }

    /// After a nested chain flushed and its stashed outer chain was
    /// restored: when the restored chain's own inline-finally region
    /// already ENDED (the walk is past its else_stop, inside the nested
    /// chain's handler material), its finalbody is complete — flush it
    /// here and end the walk. Waiting strands it: the exception-time
    /// handler copy that follows would walk as real code (duplicate
    /// statements) and the teardown flush would land the Try after all
    /// of it (_bootsubprocess 3.10 check_output).
    fn flush_completed_restored_chain(&mut self) {
        let ready = self.legacy_try.as_ref().map_or(false, |l| {
            l.has_finally
                && l.else_start.is_some()
                && self.cur_offset > l.else_stop
                && self.cur_offset < l.handler_start
        }) && !matches!(
            self.blocks.last().map(|b| b.kind),
            Some(BlockType::If) | Some(BlockType::Else)
        );
        if !ready {
            return;
        }
        let l = self.legacy_try.take().unwrap();
        self.flush_pending_stores();
        self.restore_legacy_nest();
        self.push_legacy_try(l);
        self.skip_until = Some(usize::MAX);
    }

    fn close_finally(&mut self) {
        // END_FINALLY / POP_FINALLY closes Finally (and Container) blocks
        if let Some(top) = self.blocks.last() {
            if top.kind == BlockType::Finally {
                let pos = top.start;
                self.force_close_top(pos);
            }
        }
        if let Some(top) = self.blocks.last() {
            if top.kind == BlockType::Container {
                let pos = top.start;
                self.force_close_top(pos);
            }
        }
    }

    fn handle_slice_ops(&mut self, inst: &Instruction) {
        let mk = |start: Option<ExprRef>, stop: Option<ExprRef>| -> ExprRef {
            Rc::new(Expr::Slice(Box::new(SliceExpr {
                start,
                stop,
                step: None,
            })))
        };
        match inst.op {
            Op::SLICE_0 => {
                let seq = self.pop_expr();
                self.push(Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, None),
                }));
            }
            Op::SLICE_1 => {
                let start = self.pop_expr();
                let seq = self.pop_expr();
                self.push(Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), None),
                }));
            }
            Op::SLICE_2 => {
                let stop = self.pop_expr();
                let seq = self.pop_expr();
                self.push(Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, Some(stop)),
                }));
            }
            Op::SLICE_3 => {
                let stop = self.pop_expr();
                let start = self.pop_expr();
                let seq = self.pop_expr();
                self.push(Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), Some(stop)),
                }));
            }
            // py2 STORE_SLICE+n: the assigned VALUE is pushed FIRST —
            // stack bottom..top is [value, seq, start?, stop?]
            Op::STORE_SLICE_0 => {
                let seq = self.pop_expr();
                let val = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, None),
                });
                self.emit_store(target, val);
            }
            Op::STORE_SLICE_1 => {
                let start = self.pop_expr();
                let seq = self.pop_expr();
                let val = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), None),
                });
                self.emit_store(target, val);
            }
            Op::STORE_SLICE_2 => {
                let stop = self.pop_expr();
                let seq = self.pop_expr();
                let val = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, Some(stop)),
                });
                self.emit_store(target, val);
            }
            Op::STORE_SLICE_3 => {
                let stop = self.pop_expr();
                let start = self.pop_expr();
                let seq = self.pop_expr();
                let val = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), Some(stop)),
                });
                self.emit_store(target, val);
            }
            Op::STORE_SLICE => {
                // 3.12+: the value is pushed FIRST — stack bottom..top is
                // [value, seq, start, stop], so stop pops first
                let stop = self.pop_expr();
                let start = self.pop_expr();
                let seq = self.pop_expr();
                let val = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(none_if_const_none(start), none_if_const_none(stop)),
                });
                self.emit_store(target, val);
            }
            Op::DELETE_SLICE_0 => {
                let seq = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, None),
                });
                self.emit_delete(target);
            }
            Op::DELETE_SLICE_1 => {
                let start = self.pop_expr();
                let seq = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), None),
                });
                self.emit_delete(target);
            }
            Op::DELETE_SLICE_2 => {
                let stop = self.pop_expr();
                let seq = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(None, Some(stop)),
                });
                self.emit_delete(target);
            }
            Op::DELETE_SLICE_3 => {
                let stop = self.pop_expr();
                let start = self.pop_expr();
                let seq = self.pop_expr();
                let target = Rc::new(Expr::Subscript {
                    value: seq,
                    index: mk(Some(start), Some(stop)),
                });
                self.emit_delete(target);
            }
            _ => self.mark_unclean(),
        }
    }
}

/// Value-level equality of constant operands — 3.14's LOAD_SMALL_INT
/// rebuilds small ints per instruction, so pointer equality is not enough
/// for the shared operand of a chained comparison.
fn const_value_eq(a: &PyObject, b: &PyObject) -> bool {
    match (a, b) {
        (PyObject::Int(x), PyObject::Int(y)) => x == y,
        (PyObject::Float(x, _), PyObject::Float(y, _)) => x == y,
        (PyObject::Str(x), PyObject::Str(y)) => x == y,
        (PyObject::Bytes(x), PyObject::Bytes(y)) => x == y,
        (PyObject::None, PyObject::None)
        | (PyObject::True, PyObject::True)
        | (PyObject::False, PyObject::False) => true,
        _ => false,
    }
}

/// Merge `a op1 b` + `b op2 c` (sharing operand b) into a chained
/// comparison `a op1 b op2 c`.
/// A chained-comparison link simulated on a scratch stack starts from an
/// empty stack, but the real stack still holds the shared middle operand
/// (left there by the SWAP/COPY setup) — the sim's underflow placeholder
/// `???` appears as the link's first operand. Replace it with the previous
/// link's last operand.
fn repair_chain_operand(prev: &ExprRef, sim: ExprRef) -> ExprRef {
    fn is_placeholder(e: &ExprRef) -> bool {
        matches!(&**e, Expr::Name(n) if n.contains("???"))
    }
    if !is_placeholder(&sim) {
        // placeholder may sit inside a comparison
        if let Expr::Compare { operands, ops } = &*sim {
            if operands.first().map_or(false, is_placeholder) {
                if let Expr::Compare { operands: po, .. } = &**prev {
                    if let Some(shared) = po.last() {
                        let mut fixed = operands.clone();
                        fixed[0] = shared.clone();
                        return Rc::new(Expr::Compare {
                            operands: fixed,
                            ops: ops.clone(),
                        });
                    }
                }
            }
        }
        return sim;
    }
    if let Expr::Compare { operands: po, .. } = &**prev {
        if let Some(shared) = po.last() {
            return shared.clone();
        }
    }
    sim
}

fn merge_chain_compare(cond: &ExprRef, v: &ExprRef) -> Option<ExprRef> {
    let Expr::Compare { operands, ops } = &**cond else {
        return None;
    };
    // the left side may already be a merged multi-operand chain
    if operands.len() < 2 || ops.len() + 1 != operands.len() {
        return None;
    }
    let Expr::Compare { operands: o2, ops: ops2 } = &**v else {
        return None;
    };
    // the else arm keeps `cond` itself: the chain ends here
    if o2.len() == 2 && ops2.len() == 1 && expr_eq(cond, v) {
        return Some(cond.clone());
    }
    // `v` may already be a merged chain (nested links close inner-first)
    if o2.len() < 2 || ops2.len() + 1 != o2.len() {
        return None;
    }
    let shared = match (&*operands[1], &*o2[0]) {
        (Expr::Name(a), Expr::Name(b)) => a == b,
        (Expr::Const(c1), Expr::Const(c2)) => Rc::ptr_eq(c1, c2) || const_value_eq(c1, c2),
        (Expr::Attribute { value: v1, attr: a1 }, Expr::Attribute { value: v2, attr: a2 }) => {
            a1 == a2 && expr_eq(v1, v2)
        }
        // calls/subscripts/etc: deep structural equality (side-effecting
        // operands must not be duplicated across the merged chain)
        _ => expr_eq(&operands[1], &o2[0]),
    };
    if !shared {
        return None;
    }
    let mut merged_ops = ops.clone();
    merged_ops.extend(ops2.iter().copied());
    let mut merged_operands = vec![operands[0].clone()];
    merged_operands.extend(o2.iter().cloned());
    Some(Rc::new(Expr::Compare {
        operands: merged_operands,
        ops: merged_ops,
    }))
}

fn keywords_empty(_args: &[ExprRef]) -> bool {
    true
}

/// Sentinel used by the comprehension mini-simulator for the NULL/self slot.
fn null_marker() -> ExprRef {
    Rc::new(Expr::Name("\u{0}null".to_string()))
}

fn is_null_marker(e: &ExprRef) -> bool {
    matches!(&**e, Expr::Name(n) if n.starts_with('\u{0}'))
}

fn star_args_none(_args: &[ExprRef]) -> bool {
    true
}

/// CALL_FUNCTION_EX args come as one tuple, possibly assembled by
/// BUILD_TUPLE_UNPACK(_WITH_CALL): flatten it into positional args plus an
/// optional trailing *args.
fn flatten_ex_args(e: ExprRef) -> (Vec<ExprRef>, Option<ExprRef>) {
    let mut pos = Vec::new();
    let mut star = None;
    let items: Vec<ExprRef> = match &*e {
        Expr::Tuple(v) => v.clone(),
        // 3.14 CALL_FUNCTION_EX: the empty args slot is a CONST tuple
        Expr::Const(o) => match &**o {
            PyObject::Tuple(v) => v
                .iter()
                .map(|it| Rc::new(Expr::Const(it.clone())) as ExprRef)
                .collect(),
            _ => return (Vec::new(), Some(e.clone())),
        },
        // a bare (non-tuple) operand is the whole unpacked iterable:
        // `f(*args)` pushes args directly with no BUILD_TUPLE
        other => return (Vec::new(), Some(Rc::new(other.clone()))),
    };
    for it in items {
        match &*it {
            Expr::Starred(inner) => {
                if star.is_none() {
                    star = Some(inner.clone());
                } else if let Some(prev) = star.take() {
                    // multiple stars: keep them as positional Starred items
                    pos.push(Rc::new(Expr::Starred(prev)));
                    star = Some(inner.clone());
                }
            }
            Expr::Tuple(inner) if star.is_none() => {
                // BUILD_TUPLE group of plain positional args
                pos.extend(inner.iter().cloned());
            }
            other => pos.push(Rc::new(other.clone())),
        }
    }
    (pos, star)
}

fn flatten_ex_kwargs(e: ExprRef) -> (Vec<(Option<String>, ExprRef)>, Option<ExprRef>) {
    match &*e {
        Expr::Dict(entries) => {
            let starred: usize = entries
                .iter()
                .filter(|(k, _)| matches!(&**k, Expr::Starred(_)))
                .count();
            if starred == 1 && entries.len() == 1 {
                // `f(**a)` — the single star is the whole kwargs
                if let Expr::Starred(inner) = &*entries[0].0 {
                    return (Vec::new(), Some(inner.clone()));
                }
            }
            if starred > 0 {
                // mixed or multiple stars: keep the merged dict whole so
                // the source ordering (later wins) is preserved —
                // rendered as `f(**{...})`
                return (Vec::new(), Some(e.clone()));
            }
            let mut kws = Vec::new();
            for (k, v) in entries {
                let name = match &**k {
                    Expr::Const(o) => match &**o {
                        PyObject::Str(s) => Some(s.clone()),
                        PyObject::Bytes(b) => {
                            Some(String::from_utf8_lossy(b).into_owned())
                        }
                        _ => None,
                    },
                    _ => None,
                };
                kws.push((name, v.clone()));
            }
            (kws, None)
        }
        Expr::Starred(inner) => (Vec::new(), Some(inner.clone())),
        other => (Vec::new(), Some(Rc::new(other.clone()))),
    }
}

fn is_comp_callable(e: &ExprRef) -> bool {
    match &**e {
        Expr::Function(fd) => matches!(
            fd.code.name.as_str(),
            "<listcomp>" | "<setcomp>" | "<dictcomp>" | "<genexpr>"
        ),
        Expr::Name(n) => n == "/*generator*/",
        _ => false,
    }
}

/// True when the condition tree carries an explicit boolean NOT anywhere
/// in its boolop/compare structure. Used to decide merge precedence: the
/// strict merged-boolop recognizer is adopted first only for Not-free
/// results (bogus DeMorgan folds are exactly the Not-carrying ones).
fn expr_contains_not(e: &ExprRef) -> bool {
    match &**e {
        Expr::Unary { op, operand } => {
            matches!(op, UnaryOp::Not) || expr_contains_not(operand)
        }
        Expr::BoolOp { values, .. } => values.iter().any(expr_contains_not),
        Expr::Compare { operands, .. } => operands.iter().any(expr_contains_not),
        _ => false,
    }
}

fn flatten_boolop(e: ExprRef, kind: BoolOpKind, out: &mut Vec<ExprRef>) {
    match &*e {
        Expr::BoolOp { op, values } if *op == kind => {
            for v in values {
                flatten_boolop(v.clone(), kind, out);
            }
        }
        _ => out.push(e),
    }
}

const WITH_RESULT_PLACEHOLDER: &str = "/*with-result*/";

/// Opcode equivalence modulo the LOAD_FAST borrow/check variants (3.13+
/// emits LOAD_FAST_BORROW inline where out-of-line copies keep LOAD_FAST)
fn op_family_eq(a: Op, b: Op) -> bool {
    fn fam(o: Op) -> Op {
        match o {
            Op::LOAD_FAST_BORROW | Op::LOAD_FAST_CHECK | Op::LOAD_FAST_AND_CLEAR => {
                Op::LOAD_FAST
            }
            Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => Op::LOAD_FAST_LOAD_FAST,
            x => x,
        }
    }
    fam(a) == fam(b)
}

/// Shallow structural equality used for augmented-assign target matching.
fn expr_eq(a: &ExprRef, b: &ExprRef) -> bool {
    match (&**a, &**b) {
        (Expr::Name(x), Expr::Name(y)) => x == y,
        (Expr::Attribute { value: v1, attr: a1 }, Expr::Attribute { value: v2, attr: a2 }) => {
            a1 == a2 && expr_eq(v1, v2)
        }
        (Expr::Subscript { value: v1, index: i1 }, Expr::Subscript { value: v2, index: i2 }) => {
            expr_eq(v1, v2) && expr_eq(i1, i2)
        }
        (Expr::Const(c1), Expr::Const(c2)) => Rc::ptr_eq(c1, c2) || const_value_eq(c1, c2),
        (
            Expr::Call {
                func: f1,
                args: a1,
                keywords: k1,
                star_args: s1,
                star_kwargs: w1,
            },
            Expr::Call {
                func: f2,
                args: a2,
                keywords: k2,
                star_args: s2,
                star_kwargs: w2,
            },
        ) => {
            s1.is_none() == s2.is_none()
                && w1.is_none() == w2.is_none()
                && (s1.is_none() || expr_eq(s1.as_ref().unwrap(), s2.as_ref().unwrap()))
                && (w1.is_none() || expr_eq(w1.as_ref().unwrap(), w2.as_ref().unwrap()))
                && expr_eq(f1, f2)
                && a1.len() == a2.len()
                && a1.iter().zip(a2).all(|(x, y)| expr_eq(x, y))
                && k1.len() == k2.len()
                && k1.iter()
                    .zip(k2)
                    .all(|((n1, v1), (n2, v2))| n1 == n2 && expr_eq(v1, v2))
        }
        (
            Expr::Binary { op: o1, left: l1, right: r1 },
            Expr::Binary { op: o2, left: l2, right: r2 },
        ) => o1 == o2 && expr_eq(l1, l2) && expr_eq(r1, r2),
        (Expr::Unary { op: o1, operand: x1 }, Expr::Unary { op: o2, operand: x2 }) => {
            o1 == o2 && expr_eq(x1, x2)
        }
        (Expr::Tuple(x1), Expr::Tuple(x2)) | (Expr::List(x1), Expr::List(x2)) => {
            x1.len() == x2.len() && x1.iter().zip(x2).all(|(u, v)| expr_eq(u, v))
        }
        (Expr::Compare { operands: o1, ops: s1 }, Expr::Compare { operands: o2, ops: s2 }) => {
            s1 == s2 && o1.len() == o2.len() && o1.iter().zip(o2).all(|(u, v)| expr_eq(u, v))
        }
        (Expr::BoolOp { op: o1, values: v1 }, Expr::BoolOp { op: o2, values: v2 }) => {
            o1 == o2 && v1.len() == v2.len() && v1.iter().zip(v2).all(|(u, v)| expr_eq(u, v))
        }
        _ => Rc::ptr_eq(a, b),
    }
}

/// Pure value-computation opcodes (no statements, no control flow):
/// a region of only these between two cond jumps means the second jump
/// is part of the same condition, not a nested statement.
impl<'a> Ctx<'a> {
    /// 3.8+ walrus: the value expression was duplicated (DUP_TOP <=3.10,
    /// COPY 1 on 3.11+) right before this store, and the next instruction
    /// is NOT another store (that would be a chained `a = b = v`).
    fn walrus_at_name(&self, inst: &Instruction, name: &str) -> bool {
        // the class-cell idiom (`LOAD __class__; DUP_TOP; STORE_NAME
        // __classcell__`) looks exactly like a walrus — exclude the
        // compiler-generated cell names
        if name.starts_with("__class")
            || name.starts_with("__firstlineno")
            || name.starts_with("__static_attributes")
        {
            return false;
        }
        self.walrus_at(inst)
    }

    fn walrus_at(&self, inst: &Instruction) -> bool {
        if !self.version.at_least(3, 8) {
            return false;
        }
        let Some(&ci) = self.idx_of.get(&inst.offset) else {
            return false;
        };
        if ci == 0 {
            return false;
        }
        let prev = &self.instrs[ci - 1];
        let dup =
            prev.op == Op::DUP_TOP || (prev.op == Op::COPY && prev.arg == 1);
        if !dup {
            return false;
        }
        let is_store = |o: Option<Op>| {
            matches!(
                o,
                Some(Op::STORE_FAST)
                    | Some(Op::STORE_NAME)
                    | Some(Op::STORE_DEREF)
                    | Some(Op::STORE_GLOBAL)
                    | Some(Op::STORE_FAST_MAYBE_NULL)
            )
        };
        if is_store(self.instrs.get(ci + 1).map(|x| x.op)) {
            return false;
        }
        // chained assignment with 3+ targets (`a = b = c = v`) emits
        // DUP; STORE a; DUP; STORE b; STORE c — the first store's next is
        // another DUP, but this is a chain run, not a walrus
        let next_dup = self.instrs.get(ci + 1).map(|x| {
            x.op == Op::DUP_TOP || (x.op == Op::COPY && x.arg == 1)
        }) == Some(true);
        if next_dup && is_store(self.instrs.get(ci + 2).map(|x| x.op)) {
            return false;
        }
        true
    }
}

fn is_pure_value_op(op: Op) -> bool {
    matches!(
        op,
        Op::PUSH_NULL
            | Op::PRECALL
            | Op::LOAD_FAST
            | Op::LOAD_FAST_CHECK
            | Op::LOAD_FAST_BORROW
            | Op::LOAD_FAST_LOAD_FAST
            | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
            | Op::LOAD_SMALL_INT
            | Op::LOAD_COMMON_CONSTANT
            | Op::LOAD_SUPER_ATTR
            | Op::LOAD_NAME
            | Op::LOAD_GLOBAL
            | Op::LOAD_CONST
            | Op::LOAD_ATTR
            | Op::LOAD_DEREF
            | Op::LOAD_METHOD
            | Op::LOAD_BUILD_CLASS
            | Op::LOAD_CLOSURE
            | Op::LOAD_CLASSDEREF
            | Op::COMPARE_OP
            | Op::IS_OP
            | Op::CONTAINS_OP
            | Op::BINARY_OP
            // pre-3.11 per-operator binary opcodes (3.11 folded them
            // into BINARY_OP, which is already pure — the legacy names
            // must match so condition-region scans work on <=3.10)
            | Op::BINARY_ADD
            | Op::BINARY_SUBTRACT
            | Op::BINARY_MULTIPLY
            | Op::BINARY_TRUE_DIVIDE
            | Op::BINARY_FLOOR_DIVIDE
            | Op::BINARY_DIVIDE
            | Op::BINARY_MODULO
            | Op::BINARY_POWER
            | Op::BINARY_LSHIFT
            | Op::BINARY_RSHIFT
            | Op::BINARY_AND
            | Op::BINARY_OR
            | Op::BINARY_XOR
            | Op::BINARY_MATRIX_MULTIPLY
            | Op::BINARY_SUBSCR
            | Op::BINARY_SLICE
            | Op::BUILD_SLICE
            | Op::SLICE_0
            | Op::SLICE_1
            | Op::SLICE_2
            | Op::SLICE_3
            | Op::CALL
            | Op::CALL_FUNCTION
            | Op::CALL_METHOD
            | Op::CALL_FUNCTION_KW
            // 3.13+ keyword call; f-string/`%`-format value ops
            | Op::CALL_KW
            | Op::FORMAT_SIMPLE
            | Op::FORMAT_WITH_SPEC
            | Op::CONVERT_VALUE
            | Op::BUILD_TUPLE
            | Op::BUILD_LIST
            | Op::BUILD_MAP
            | Op::BUILD_SET
            | Op::BUILD_STRING
            | Op::UNARY_NOT
            | Op::UNARY_NEGATIVE
            | Op::UNARY_POSITIVE
            | Op::UNARY_INVERT
            | Op::TO_BOOL
            | Op::FORMAT_VALUE
            | Op::COPY
            | Op::NOP
            | Op::NOT_TAKEN
            | Op::CACHE
            | Op::EXTENDED_ARG
    )
}

fn negate_cond(e: ExprRef) -> ExprRef {
    // CPython's AST optimizer inverts single-op comparisons under `not`
    // (`not x is None` -> `x is not None`); mirror that so escape-jump
    // polarity renders the canonical source form. Eq/NotEq fold too —
    // `==` is exactly `not !=` at the bytecode level.
    if let Expr::Compare { operands, ops } = &*e {
        if ops.len() == 1 {
            let inv = match ops[0] {
                CmpOp::Is => Some(CmpOp::IsNot),
                CmpOp::IsNot => Some(CmpOp::Is),
                CmpOp::In => Some(CmpOp::NotIn),
                CmpOp::NotIn => Some(CmpOp::In),
                CmpOp::Eq => Some(CmpOp::NotEq),
                CmpOp::NotEq => Some(CmpOp::Eq),
                _ => None,
            };
            if let Some(op) = inv {
                return Rc::new(Expr::Compare {
                    operands: operands.clone(),
                    ops: vec![op],
                });
            }
        }
    }
    simplify_not_or_wrap(e)
}

fn simplify_not_or_wrap(e: ExprRef) -> ExprRef {
    if let Expr::Unary {
        op: UnaryOp::Not,
        operand,
    } = &*e
    {
        return operand.clone();
    }
    Rc::new(Expr::Unary {
        op: UnaryOp::Not,
        operand: e,
    })
}

/// Re-fold a De Morgan-expanded boolean chain back to the source
/// shape: `not A or not B [or ...]` -> `not (A and B)` (and the dual).
/// CPython compiles `if not (A and B):` operand-per-operand with jumps
/// to the BODY, and the walker rebuilds that as an Or of negations —
/// rendering the expansion verbatim recompiles to flipped-polarity
/// instructions (bdb 3.7 dispatch_exception: `is`+PJIF rendered as
/// `is not`+PJIT, the last 4 sig lines before PASS).
fn refold_demorgan(cond: ExprRef) -> ExprRef {
    let (kind, dual) = match &*cond {
        Expr::BoolOp { op: BoolOpKind::Or, values } if values.len() >= 2 => {
            (values, BoolOpKind::And)
        }
        Expr::BoolOp { op: BoolOpKind::And, values } if values.len() >= 2 => {
            (values, BoolOpKind::Or)
        }
        _ => return cond,
    };
    // ONLY when every operand is a NOT of a pure-value expression: then
    // the walker could not have come from a JUMP_IF_*_OR_POP value chain
    // (those require at least one non-negated value operand) and the
    // chain was assembled from per-operand body/skip jumps of a folded
    // `not (A and B)` source. Mixed chains (`self.stopframe and frame
    // is not ...`, bdb 3.7 stop_here) DO come from value chains, where
    // CPython compiles the expanded and the folded form differently
    // (JIFOP value flow vs per-operand jumps) — refolding swaps the
    // recompiled shape (configparser 3.3/3.5/3.6 +2500 sig lines).
    // Truthy-name operands (`not self._comm_chunk_read or ...`, aifc
    // 3.5/3.6) likewise keep their expanded source shape.
    let all_pure_not = kind.iter().all(|v| {
        if let Expr::Unary { op: UnaryOp::Not, operand } = &**v {
            matches!(
                operand.as_ref(),
                Expr::Compare { .. } | Expr::Binary { .. } | Expr::Call { .. }
            )
        } else {
            false
        }
    });
    if !all_pure_not {
        return cond;
    }
    let inner: Vec<ExprRef> = kind
        .iter()
        .map(|v| match &**v {
            Expr::Unary { operand, .. } => operand.clone(),
            _ => v.clone(),
        })
        .collect();
    Rc::new(Expr::Unary {
        op: UnaryOp::Not,
        operand: Rc::new(Expr::BoolOp {
            op: dual,
            values: inner,
        }),
    })
}

fn simplify_not(e: ExprRef) -> ExprRef {
    match &*e {
        Expr::Unary {
            op: UnaryOp::Not,
            operand,
        } => operand.clone(),
        _ => e,
    }
}

/// 3.14: extended slices arrive as `slice(a, b, c)` calls or marshalled
/// slice constants; normalize both to Expr::Slice.
fn normalize_slice_call(idx: ExprRef) -> ExprRef {
    match &*idx {
        Expr::Call { func, args, keywords, star_args: None, star_kwargs: None }
            if keywords.is_empty()
                && matches!(&**func, Expr::Name(n) if n == "slice")
                && (2..=3).contains(&args.len()) =>
        {
            Rc::new(Expr::Slice(Box::new(SliceExpr {
                start: none_if_const_none(args[0].clone()),
                stop: none_if_const_none(args[1].clone()),
                step: args.get(2).cloned().and_then(none_if_const_none),
            })))
        }
        Expr::Const(o) => match &**o {
            PyObject::Slice(a, b, c) => Rc::new(Expr::Slice(Box::new(SliceExpr {
                start: none_if_const_const(a.clone()),
                stop: none_if_const_const(b.clone()),
                step: none_if_const_const(c.clone()),
            }))),
            _ => idx,
        },
        _ => idx,
    }
}

fn none_if_const_const(o: ObjectRef) -> Option<ExprRef> {
    if matches!(&*o, PyObject::None) {
        None
    } else {
        Some(Rc::new(Expr::Const(o)))
    }
}

fn none_if_const_none(e: ExprRef) -> Option<ExprRef> {
    match &*e {
        Expr::Const(o) if matches!(&**o, PyObject::None) => None,
        _ => Some(e),
    }
}

fn expr_to_fstring(e: ExprRef) -> FString {
    match &*e {
        Expr::FString(f) => f.as_ref().clone(),
        // a plain constant spec string is literal spec text
        Expr::Const(o) => match &**o {
            PyObject::Str(s) => FString {
                parts: vec![FStringPart::Literal(s.clone())],
            },
            PyObject::Bytes(b) => FString {
                parts: vec![FStringPart::Literal(
                    String::from_utf8_lossy(b).into_owned(),
                )],
            },
            _ => FString {
                parts: vec![FStringPart::Value {
                    value: e,
                    conversion: None,
                    format_spec: None,
                }],
            },
        },
        other => FString {
            parts: vec![FStringPart::Value {
                value: Rc::new(other.clone()),
                conversion: None,
                format_spec: None,
            }],
        },
    }
}

fn cmp_from_index(idx: usize) -> CmpOp {
    match idx {
        0 => CmpOp::Lt,
        1 => CmpOp::LtE,
        2 => CmpOp::Eq,
        3 => CmpOp::NotEq,
        4 => CmpOp::Gt,
        5 => CmpOp::GtE,
        6 => CmpOp::In,
        7 => CmpOp::NotIn,
        8 => CmpOp::Is,
        9 => CmpOp::IsNot,
        10 => CmpOp::ExceptionMatch,
        _ => CmpOp::Eq,
    }
}

// =====================  stack events, calls, functions, classes  =====================

impl<'a> Ctx<'a> {
    fn handle_pop_top(&mut self) {
        // 3.12+ value-preserving boolop/chain arm: COPY 1 + TO_BOOL
        // before the guard's cond jump retains the tested operand under
        // the arm; the arm's leading POP_TOP drops that copy before the
        // second operand evaluates — it is arm bookkeeping, NOT an
        // expression statement (_colorize 3.13 can_colorize `return
        // hasattr(file, 'isatty') and file.isatty()`: the retained
        // hasattr call leaked as a body statement and the value merge
        // never saw an empty body)
        if self.version.at_least(3, 12) {
            let armed = self
                .blocks
                .last()
                .map_or(false, |b| b.value_merge.is_some() && b.stmts.is_empty())
                && self
                    .idx_of
                    .get(&self.cur_offset)
                    .and_then(|&pi| (pi > 0).then(|| &self.instrs[pi - 1]))
                    .map_or(false, |p| {
                        matches!(p.op, Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_IF_TRUE)
                            && !p.is_backward
                    });
            if armed {
                self.pop();
                return;
            }
        }
        // import-star intrinsic placeholder: pure cleanup, never a stmt
        if self.import_star_pop_pending {
            self.import_star_pop_pending = false;
            self.pop();
            return;
        }
        // closing POP_TOP of a multi-name from-import: the module marker
        // sits under the accumulated pending names — emit the merged
        // statement here (the interleaved IMPORT_FROM/STORE sequence
        // deferred its flush to this point)
        if !self.import_names.is_empty()
            && matches!(self.stack.last(), Some(Sv::ImportModule { .. }))
        {
            self.pop();
            self.flush_import();
            return;
        }
        // `return v` inside a loop: `SWAP 2; POP_TOP` (3.12+) or
        // `ROT_TWO; POP_TOP` (3.8-3.11) before the RETURN drops the loop
        // iterator, which the VM keeps below the value but our simulation
        // does not — swallow the pop. Legacy handler preludes reuse the
        // same ops for exception bookkeeping: never no-op inside them.
        // a terminating handler's post-POP_EXCEPT cleanup (3.8-3.10
        // `except: return X`: BUILD value; ROT_FOUR; POP_EXCEPT; ROT_TWO;
        // POP_TOP; RETURN) drops the unmodeled exception slots with the
        // same shuffle — pop_seen separates it from the prelude's
        // triple-POP_TOPs, which must keep popping (bdb 3.8/3.9
        // effective: the cleanup POP_TOP ate the return tuple and the
        // clause rendered `except: b, False`)
        let terminating_handler_cleanup = self
            .legacy_handler
            .as_ref()
            .map_or(false, |h| h.pop_seen);
        if matches!(self.prev_op_at_exec, Some(Op::SWAP) | Some(Op::ROT_TWO))
            && (terminating_handler_cleanup
                || (self.legacy_handler.is_none() && self.legacy_try.is_none()))
        {
            // 3.11 returns out of nested loops drop ONE iterator per
            // enclosing loop: a run of SWAP/POP pairs precedes the RETURN
            let next_returns = self
                .idx_of
                .get(&self.cur_offset)
                .map_or(false, |&pi| {
                    let mut k = pi + 1;
                    let mut steps = 0;
                    while let Some(nx) = self.instrs.get(k) {
                        if matches!(nx.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                            return true;
                        }
                        if !matches!(
                            nx.op,
                            Op::SWAP
                                | Op::ROT_TWO
                                | Op::POP_TOP
                                | Op::NOP
                                | Op::NOT_TAKEN
                        ) || steps >= 8
                        {
                            return false;
                        }
                        k += 1;
                        steps += 1;
                    }
                    false
                });
            if next_returns {
                return;
            }
        }
        // py2 if-statement: the else branch starts with a POP_TOP that
        // discards the cond value we already popped at the JUMP_IF_*
        if self.py2_else_pop_at == Some(self.cur_offset) {
            self.py2_else_pop_at = None;
            return;
        }
        // handler-entry prelude pops (exception bookkeeping we do not model)
        if self.legacy_handler.is_some() && self.in_handler_prelude {
            self.pop();
            return;
        }
        // inside an inline comprehension, POP_TOP is iterator/cleanup
        // bookkeeping (3.13 pairs END_FOR with POP_TOP), never a statement
        if self.inline_comp.is_some() {
            self.pop();
            return;
        }
        // 3.12+ and/or chains: COPY duplicates the value before the cond
        // jump; the POP_TOP right after the jump discards the original.
        if matches!(
            self.prev_op_at_exec,
            Some(Op::POP_JUMP_IF_FALSE)
                | Some(Op::POP_JUMP_IF_TRUE)
                | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
                | Some(Op::POP_JUMP_FORWARD_IF_TRUE)
                | Some(Op::POP_JUMP_BACKWARD_IF_FALSE)
                | Some(Op::POP_JUMP_BACKWARD_IF_TRUE)
                | Some(Op::JUMP_IF_FALSE_OR_POP)
                | Some(Op::JUMP_IF_TRUE_OR_POP)
                | Some(Op::JUMP_IF_FALSE)
                | Some(Op::JUMP_IF_TRUE)
                | Some(Op::TO_BOOL)
                | Some(Op::END_FOR)
        ) {
            self.pop();
            return;
        }
        // py2 chained imports end with POP_TOP of the module marker
        if let Some(Sv::ImportModule { .. }) = self.stack.last() {
            if self.finalize_from_import() {
                return;
            }
        }
        let sv = self.pop();
        match sv {
            Some(Sv::E(e)) => {
                if let Expr::Yield(_) | Expr::YieldFrom(_) = &*e {
                    self.push_stmt(Stmt::Expr(e));
                    return;
                }
                // 2.6 `with ctx:` (no as): the enter result is POP_TOPped
                // right before the with's SETUP_FINALLY — the With block
                // already represents the statement
                if self.version.major == 2 {
                    let is_enter_call = matches!(&*e, Expr::Call { func, .. }
                        if matches!(&**func, Expr::Attribute { attr, .. } if attr == "__enter__"));
                    if is_enter_call {
                        let next_is_with_setup = self
                            .idx_of
                            .get(&self.cur_offset)
                            .and_then(|&pi| self.instrs.get(pi + 1))
                            .map_or(false, |nx| {
                                nx.op == Op::SETUP_FINALLY
                                    && nx.target.map_or(false, |t| {
                                        self.idx_of.get(&t).map_or(false, |&ti| {
                                            self.instrs[ti].op == Op::WITH_CLEANUP
                                        })
                                    })
                            });
                        if next_is_with_setup {
                            return;
                        }
                    }
                }
                // a with-result value discarded: `with ctx:` without as
                if let Expr::Name(n) = &*e {
                    if n == WITH_RESULT_PLACEHOLDER || n == "/*generator*/" {
                        return;
                    }
                }
                self.push_stmt(Stmt::Expr(e));
            }
            Some(Sv::ImportModule { module, level, fromlist }) => {
                if !self.import_names.is_empty() {
                    // `from module import a, b` finished
                    let names = std::mem::take(&mut self.import_names);
                    self.import_module = None;
                    self.push_stmt(Stmt::ImportFrom { module, level, names });
                } else if fromlist.is_none() {
                    self.push_stmt(Stmt::Import {
                        names: vec![(module, None)],
                    });
                } else {
                    let _ = fromlist;
                }
            }
            Some(Sv::ImportFrom { .. }) => {
                // leftover single from-import name (import without store?)
                self.finalize_from_import();
            }
            Some(Sv::Null) => {}
            None => {}
        }
    }

    /// Fold consecutive ImportFrom markers on the stack into one
    /// `from module import a, b` statement. Returns true when handled.
    fn finalize_from_import(&mut self) -> bool {
        // count trailing ImportFrom markers with the same module
        let n = self.stack.len();
        let mut count = 0usize;
        let mut module: Option<(u32, String)> = None;
        while count < n {
            match &self.stack[n - 1 - count] {
                Sv::ImportFrom { level, module: m, .. } => {
                    let key = (*level, m.clone());
                    match &module {
                        None => module = Some(key),
                        Some(k) if *k == key => {}
                        _ => break,
                    }
                    count += 1;
                }
                Sv::ImportModule { level, module: m, .. } if count > 0 => {
                    let key = (*level, m.clone());
                    if module.as_ref() == Some(&key) {
                        // consume the module marker too
                        count += 1;
                        let drain = self.stack.split_off(n - count);
                        let names: Vec<(String, Option<String>)> = drain
                            .into_iter()
                            .filter_map(|sv| match sv {
                                Sv::ImportFrom { name, .. } => Some((name, None)),
                                _ => None,
                            })
                            .collect();
                        let (level, module) = module.unwrap();
                        self.push_stmt(Stmt::ImportFrom {
                            module,
                            level,
                            names,
                        });
                        return true;
                    }
                    break;
                }
                _ => break,
            }
        }
        false
    }

    /// Pop a raw stack value for STORE_* instructions so that import
    /// markers are handled without going through pop_expr.
    fn pop_store_value(&mut self) -> Sv {
        loop {
            match self.stack.pop() {
                Some(Sv::Null) => continue,
                Some(other) => return other,
                None => {
                    // inside legacy handler preludes the VM stack carries
                    // phantom exception values we do not model; an empty
                    // simulation stack there is not an error
                    if self.legacy_handler.is_none() {
                        self.mark_unclean();
                    }
                    return Sv::E(Rc::new(Expr::Const(Rc::new(PyObject::None))));
                }
            }
        }
    }

    /// Like pop_store_value but NEVER marks unclean on underflow — for the
    /// 3.12+ inline comprehension variable restore, whose exception-path
    /// copy pops from an already-drained stack (the normal path RETURNed
    /// first). The restore statement is suppressed by emit_store anyway.
    fn pop_store_value_quiet(&mut self) -> Sv {
        loop {
            match self.stack.pop() {
                Some(Sv::Null) => continue,
                Some(other) => return other,
                None => {
                    return Sv::E(Rc::new(Expr::Const(Rc::new(PyObject::None))));
                }
            }
        }
    }

    /// Store routing that understands import markers.
    fn emit_store_sv(&mut self, target: ExprRef, sv: Sv) {
        if matches!(sv, Sv::ImportFrom { .. } | Sv::ImportModule { .. }) {
            // an import store is not the handler's `as` name
            self.legacy_handler_name_store = false;
        }
        match sv {
            Sv::E(val) => self.emit_store(target, val),
            Sv::ImportFrom { level, module, name } => {
                let asname = match &*target {
                    Expr::Name(t) if *t != name => Some(t.clone()),
                    _ => None,
                };
                self.import_names.push((name, asname));
                match &self.import_module {
                    Some((l, m)) if *l == level && *m == module => {}
                    _ => self.import_module = Some((level, module)),
                }
                if !matches!(self.stack.last(), Some(Sv::ImportFrom { .. })) {
                    // interleaved modern layout (IMPORT_FROM; STORE) x N:
                    // each store consumes its marker, so the stack check
                    // alone flushes every name as its own statement —
                    // keep accumulating while the sequence continues (the
                    // next instruction is another IMPORT_FROM); the
                    // sequence-closing POP_TOP emits the merged form
                    let seq_continues = self
                        .idx_of
                        .get(&self.cur_offset)
                        .and_then(|&ci| self.instrs.get(ci + 1))
                        .map_or(false, |x| x.op == Op::IMPORT_FROM);
                    if !seq_continues {
                        self.flush_import();
                    }
                }
            }
            Sv::ImportModule { module, fromlist, .. } => {
                if let Some(fromlist_e) = fromlist {
                    // from module import *  stored to a name? (py2 star)
                    let names = match &*fromlist_e {
                        Expr::Const(o) => match &**o {
                            PyObject::Tuple(items) => items
                                .iter()
                                .filter_map(|it| match &**it {
                                    PyObject::Str(s) => Some((s.clone(), None)),
                                    _ => None,
                                })
                                .collect(),
                            _ => Vec::new(),
                        },
                        _ => Vec::new(),
                    };
                    if names.len() == 1 {
                        let asname = match &*target {
                            Expr::Name(t) if *t != names[0].0 => Some(t.clone()),
                            _ => None,
                        };
                        self.push_stmt(Stmt::ImportFrom {
                            module,
                            level: 0,
                            names: vec![(names[0].0.clone(), asname)],
                        });
                        return;
                    }
                    self.push_stmt(Stmt::ImportFrom {
                        module,
                        level: 0,
                        names,
                    });
                } else {
                    // `import a.b` binds the top module (STORE a);
                    // `import a.b as c` stores c
                    let asname = match &*target {
                        Expr::Name(t) => {
                            let top = module.split('.').next().unwrap_or(&module);
                            if t.as_str() != top && dotted_last(module.as_str()) != t.as_str() {
                                Some(t.clone())
                            } else if t.as_str() != top {
                                // stored the leaf name for a dotted module:
                                // plain `import a.b` form
                                None
                            } else {
                                None
                            }
                        }
                        _ => None,
                    };
                    self.push_stmt(Stmt::Import {
                        names: vec![(module, asname)],
                    });
                }
            }
            Sv::Null => {
                self.mark_unclean();
            }
        }
    }

    /// Common path for every store instruction: unpack bookkeeping,
    /// import stores, function/class def detection, else plain assignment.
    fn emit_store(&mut self, target: ExprRef, val: ExprRef) {
        if self.legacy_handler_cleanup {
            self.legacy_handler_cleanup = false;
            if let Expr::Name(n) = &*target {
                self.swallowed_cleanup_del = Some(n.clone());
            }
            return;
        }
        // post-handler `as`-name cleanup: hold `name = None` until the
        // matching `del name` confirms it; anything else flushes it as a
        // real assignment. Inside a handler-body region walk no `del`
        // statement output is wanted — swallow the hold outright (the
        // region ends before the exception-path duplicate anyway).
        if let Expr::Name(n) = &*target {
            if self.pending_as_cleanup.as_deref() == Some(n.as_str())
                && matches!(&*val, Expr::Const(o) if matches!(&**o, PyObject::None))
            {
                if matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main))
                    && self.blocks.len() == 1
                {
                    // region-walk outright swallow: arm the chained del
                    // expectation (as the legacy path does) and KEEP pac
                    // — 3.12 duplicates the eager pair into every exit
                    // arm (codeop: else-arm pair confirmed via this
                    // path must not consume the marker before the
                    // exception-path stub pair arrives)
                    self.swallowed_cleanup_del = Some(n.clone());
                    return;
                }
                self.held_cleanup_store = Some((target, val));
                return;
            }
        }
        if self.legacy_handler_name_store {
            self.legacy_handler_name_store = false;
            if matches!(&*target, Expr::Name(_)) {
                if let Some(h) = self.legacy_handler.as_mut() {
                    if h.name.is_none() {
                        h.name = Some(target);
                        return;
                    }
                }
            }
            // not a valid as-name (attribute/subscript store): fall through
            // and emit it as a normal assignment
        }
        // post-comprehension restore of a cleared outer variable
        if let Expr::Name(n) = &*target {
            if let Some(pos) = self.pending_restore_vars.iter().position(|v| v == n) {
                self.pending_restore_vars.remove(pos);
                return;
            }
        }
        // inline comprehension: the first store after each FOR_ITER is the
        // loop target; later stores of cleared variables are the post-loop
        // restores (not statements)
        if let Some(comp) = &mut self.inline_comp {
            if !comp.target_seen && self.unpack_frames.is_empty() {
                if let Some(cur) = &mut comp.cur {
                    cur.target = Some(target);
                }
                comp.target_seen = true;
                self.awaiting_for_target = false;
                return;
            }
            // post-loop restore swallow: only when no unpack frame is
            // collecting — an in-loop tuple-target store (`for k, v in`)
            // also hits a cleared var but must complete the frame
            if self.unpack_frames.is_empty() {
                if let Expr::Name(n) = &*target {
                    if comp.cleared_vars.contains(n) {
                        return;
                    }
                }
            }
        }
        // FOR_ITER just executed: this store is the loop target (unless a
        // tuple target is being unpacked, handled at frame completion)
        if self.awaiting_for_target && self.unpack_frames.is_empty() {
            self.awaiting_for_target = false;
            if let Some(top) = self.blocks.last_mut() {
                if matches!(top.kind, BlockType::For) {
                    // value is the iterator expression itself (we pushed it
                    // back in handle_for_iter); don't emit an assignment
                    top.target = Some(target);
                    return;
                }
            }
        }
        // `with ctx as target:` — the stored value is the __enter__ result
        if let Expr::Name(n) = &*val {
            if n == WITH_RESULT_PLACEHOLDER {
                for blk in self.blocks.iter_mut().rev() {
                    if blk.kind == BlockType::With {
                        if let Some(item) = blk.with_item.as_mut() {
                            item.target = Some(target);
                            return;
                        }
                    }
                }
                if let Some(items) = self.pending_with.last_mut() {
                    if let Some(item) = items.last_mut() {
                        item.target = Some(target);
                        return;
                    }
                }
            }
        }
        // drop stale exhausted frames (stores rerouted elsewhere)
        while matches!(self.unpack_frames.last(), Some((0, _, _, _))) {
            self.unpack_frames.pop();
            self.unpack_targets.0.pop();
            self.unpack_target_lines.pop();
        }
        if let Some(frame) = self.unpack_frames.last_mut() {
            frame.0 -= 1;
            let done = frame.0 == 0;
            let (count, star_at) = (frame.1, frame.2);
            let index = count - 1 - frame.0;
            let starred = star_at == Some(index);
            if let Some(targets) = self.unpack_targets.0.last_mut() {
                targets.push((target, starred));
            }
            if let Some(lines) = self.unpack_target_lines.last_mut() {
                lines.push(self.cur_line);
            }
            if done {
                let (_, _, _, value) = self.unpack_frames.pop().unwrap();
                let targets = self.unpack_targets.0.pop().unwrap();
                let lines = self.unpack_target_lines.pop().unwrap_or_default();
                let tuple: ExprRef = Rc::new(Expr::Tuple(
                    targets
                        .into_iter()
                        .map(|(t, star)| {
                            if star {
                                Rc::new(Expr::Starred(t))
                            } else {
                                t
                            }
                        })
                        .collect(),
                ));
                if self.unpack_frames.is_empty() {
                    // source line wraps inside the target list: record
                    // the break positions so codegen reproduces them
                    // (3.13+ fuses only same-line stores)
                    let wraps: Vec<u16> = lines
                        .windows(2)
                        .enumerate()
                        .filter(|(_, w)| {
                            matches!((w[0], w[1]), (Some(a), Some(b)) if a != b)
                        })
                        .map(|(i, _)| (i + 1) as u16)
                        .collect();
                    if !wraps.is_empty() {
                        self.pending_unpack_wrap = wraps;
                    }
                    self.assign_or_for_target(tuple, value);
                } else {
                    // nested: the completed tuple is the parent's next target
                    let parent = self.unpack_frames.last_mut().unwrap();
                    parent.0 -= 1;
                    let pdone = parent.0 == 0;
                    let (pcount, pstar) = (parent.1, parent.2);
                    let pindex = pcount - 1 - parent.0;
                    let pstarred = pstar == Some(pindex);
                    if let Some(targets) = self.unpack_targets.0.last_mut() {
                        targets.push((tuple, pstarred));
                    }
                    if let Some(lines) = self.unpack_target_lines.last_mut() {
                        lines.push(self.cur_line);
                    }
                    if pdone {
                        let (_, _, _, pvalue) = self.unpack_frames.pop().unwrap();
                        let ptargets = self.unpack_targets.0.pop().unwrap();
                        let plines =
                            self.unpack_target_lines.pop().unwrap_or_default();
                        if self.unpack_frames.is_empty() {
                            let pwraps: Vec<u16> = plines
                                .windows(2)
                                .enumerate()
                                .filter(|(_, w)| {
                                    matches!((w[0], w[1]), (Some(a), Some(b)) if a != b)
                                })
                                .map(|(i, _)| (i + 1) as u16)
                                .collect();
                            if !pwraps.is_empty() {
                                self.pending_unpack_wrap = pwraps;
                            }
                        }
                        let ptuple: ExprRef = Rc::new(Expr::Tuple(
                            ptargets
                                .into_iter()
                                .map(|(t, star)| {
                                    if star {
                                        Rc::new(Expr::Starred(t))
                                    } else {
                                        t
                                    }
                                })
                                .collect(),
                        ));
                        self.assign_or_for_target(ptuple, pvalue);
                    }
                }
            }
            return;
        }
        self.emit_assign_single(target, val);
    }

    /// Route a completed (possibly tuple) store: either it is the target of
    /// the for loop we just opened, or a normal assignment.
    fn assign_or_for_target(&mut self, target: ExprRef, value: ExprRef) {
        if self.awaiting_for_target {
            self.awaiting_for_target = false;
            if let Some(top) = self.blocks.last_mut() {
                if matches!(top.kind, BlockType::For) {
                    top.target = Some(target);
                    return;
                }
            }
        }
        // inline comprehension whose loop target was an unpacked tuple
        if let Some(comp) = &mut self.inline_comp {
            if !comp.target_seen {
                if let Some(cur) = &mut comp.cur {
                    cur.target = Some(target);
                }
                comp.target_seen = true;
                return;
            }
        }
        self.emit_assign_single(target, value);
    }

    fn emit_assign_single(&mut self, target: ExprRef, val: ExprRef) {
        // py2 class creation: BUILD_CLASS result stored to a name
        if self.pending_py2_class.is_some() {
            if let (Some((name_e, bases_e, methods)), Expr::Name(cname)) =
                (self.pending_py2_class.take(), &*target)
            {
                let _ = name_e;
                let bases = match &*bases_e {
                    Expr::Tuple(v) => v.clone(),
                    // py2 `class X:` pushes the empty bases as a CONST tuple
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(items) => items
                            .iter()
                            .map(|i| Rc::new(Expr::Const(i.clone())) as ExprRef)
                            .collect(),
                        _ => vec![bases_e.clone()],
                    },
                    other => vec![Rc::new(other.clone())],
                };
                // the class body is the MAKE_FUNCTION'd code object that
                // CALL_FUNCTION executed into the namespace dict (`methods`),
                // not the stored BUILD_CLASS result; py2 stores it either as
                // a bare Function or as the zero-arg Call of that Function
                let extract_code = |e: &ExprRef| -> Option<Rc<CodeObject>> {
                    match &**e {
                        Expr::Function(fd) => Some(fd.code.clone()),
                        Expr::Call { func, args, keywords, .. }
                            if args.is_empty() && keywords.is_empty() =>
                        {
                            match &**func {
                                Expr::Function(fd) => Some(fd.code.clone()),
                                _ => None,
                            }
                        }
                        _ => None,
                    }
                };
                let body_src = extract_code(&methods).or_else(|| extract_code(&val));
                let mut body = match body_src {
                    Some(code) => self
                        .decompile_class_body(&code, cname)
                        .unwrap_or_else(|| vec![Stmt::Pass]),
                    None => vec![Stmt::Pass],
                };
                // py2 class bodies end with `return locals()` (the namespace
                // the CALL_FUNCTION consumed) — not real source
                while matches!(
                    body.last(),
                    Some(Stmt::Return(Some(e)))
                        if matches!(&**e, Expr::Name(n) if n == "locals()")
                ) {
                    body.pop();
                }
                if body.is_empty() {
                    body.push(Stmt::Pass);
                }
                let decorators = std::mem::take(&mut self.pending_class_decorators);
                self.push_stmt(Stmt::ClassDef {
                    name: cname.clone(),
                    bases,
                    keywords: Vec::new(),
                    star_args: None,
                    star_kwargs: None,
                    decorators,
                    body,
                });
                return;
            }
        }
        // augmented assignment: `x += 1` compiled to a binary op whose LHS is
        // the target, followed by a store back into the same target
        if let Some((aug_target, op)) = self.pending_aug.take() {
            if expr_eq(&aug_target, &target) {
                if let Expr::Binary { right, .. } = &*val {
                    self.push_stmt(Stmt::AugAssign {
                        target,
                        op,
                        value: right.clone(),
                    });
                    return;
                }
            } else {
                // stale marker
                self.pending_aug = Some((aug_target, op));
                self.pending_aug = None;
            }
        }
        // function definition
        if let Expr::Function(fd) = &*val {
            if let Expr::Name(fname) = &*target {
                let fd = fd;
                let name = fname.clone();
                let mut body = self
                    .decompile_function(&fd.code)
                    .unwrap_or_else(|| vec![Stmt::Pass]);
                let mut fd2 = (**fd).clone();
                fd2.name = name;
                fd2.returns = fd2.params.returns_annotation.take();
                fd2.is_async = fd2.code.is_coroutine() || fd2.code.is_async_generator();
                fold_py2_tuple_params(&mut fd2.params, &fd.code.varnames, &mut body);
                let fdef = Rc::new(fd2);
                self.push_stmt(Stmt::FuncDef(fdef, body));
                return;
            }
        }
        // decorated class (3.11+): the stored value is deco(build_class(...))
        let mut class_decorators: Vec<ExprRef> = Vec::new();
        let mut val = val;
        loop {
            let peeled = match &*val {
                Expr::Call { func, args, keywords, star_args: None, star_kwargs: None }
                    if args.len() == 1 && keywords.is_empty() =>
                {
                    match &*args[0] {
                        Expr::Call { func: f2, .. }
                            if matches!(&**f2, Expr::Name(n) if n == "__build_class__") =>
                        {
                            Some((func.clone(), args[0].clone()))
                        }
                        _ => None,
                    }
                }
                _ => None,
            };
            match peeled {
                Some((deco, inner)) => {
                    class_decorators.push(deco);
                    val = inner;
                }
                None => break,
            }
        }
        // class definition (py3): __build_class__ call result stored
        if let Expr::Call { func, args, keywords, .. } = &*val {
            if let Expr::Name(fn_name) = &**func {
                if fn_name == "__build_class__" {
                    if let Expr::Name(cname) = &*target {
                        if args.len() >= 2 {
                            let func_e = args[0].clone();
                            let name_e = args[1].clone();
                            let bases = args[2..].to_vec();
                            let kws: Vec<(Option<String>, ExprRef)> =
                                keywords.iter().cloned().collect();
                            if let Expr::Function(fd) = &*func_e {
                                let class_name = match &*name_e {
                                    Expr::Const(o) => match &**o {
                                        PyObject::Str(s) => s.clone(),
                                        _ => cname.clone(),
                                    },
                                    _ => cname.clone(),
                                };
                                let body = self
                                    .decompile_class_body(&fd.code, &class_name)
                                    .unwrap_or_else(|| vec![Stmt::Pass]);
                                let mut star_args = None;
                                let mut star_kwargs = None;
                                let mut real_bases = Vec::new();
                                let mut real_kws = Vec::new();
                                for b in bases {
                                    match &*b {
                                        Expr::Starred(e) => {
                                            if star_args.is_none() {
                                                star_args = Some(e.clone());
                                            } else {
                                                star_kwargs = Some(e.clone());
                                            }
                                        }
                                        other => real_bases.push(Rc::new(other.clone())),
                                    }
                                }
                                for (k, v) in kws {
                                    match k {
                                        Some(kn) => real_kws.push((Some(kn), v)),
                                        None => match &*v {
                                            Expr::Starred(e) => star_kwargs = Some(e.clone()),
                                            _ => real_kws.push((None, v)),
                                        },
                                    }
                                }
                                let mut decorators = class_decorators;
                                decorators
                                    .extend(std::mem::take(&mut self.pending_class_decorators));
                                self.push_stmt(Stmt::ClassDef {
                                    name: class_name,
                                    bases: real_bases,
                                    keywords: real_kws,
                                    star_args,
                                    star_kwargs,
                                    decorators,
                                    body,
                                });
                                return;
                            }
                        }
                    }
                }
            }
        }
        // plain assignment — may be part of a same-line store group
        // (`a, b = b, a` or `a = b = expr`)
        let same_group = self.last_store_line == self.cur_line && self.cur_line.is_some();
        if !same_group {
            self.flush_pending_stores();
            self.group_start = self.cur_offset;
        }
        self.last_store_line = self.cur_line;
        self.pending_stores.push((target, val));
    }

    fn flush_import(&mut self) {
        let module = self.import_module.take();
        if !self.import_names.is_empty() {
            if let Some((level, module)) = module {
                let names = std::mem::take(&mut self.import_names);
                self.push_stmt(Stmt::ImportFrom { module, level, names });
                return;
            }
        }
        self.import_names.clear();
    }

    fn emit_delete(&mut self, target: ExprRef) {
        if self.legacy_handler_cleanup {
            self.legacy_handler_cleanup = false;
            return;
        }
        if let Expr::Name(n) = &*target {
            if self.swallowed_cleanup_del.as_deref() == Some(n.as_str()) {
                self.swallowed_cleanup_del = None;
                return;
            }
        }
        self.swallowed_cleanup_del = None;
        if let Expr::Name(n) = &*target {
            if self.pending_as_cleanup.as_deref() == Some(n.as_str()) {
                // a CONFIRMED pair (held `name = None` + this del) may
                // have siblings: 3.12 eager as-cleanup is duplicated
                // into EVERY exit arm of the clause body (codeop
                // _maybe_compile: then-arm return, else-arm
                // fall-through, exception-path stub) — keep the marker
                // armed so the later pairs swallow too. A LONE del
                // disarms as before (_strptime explicit-del semantics)
                let had_held = self.held_cleanup_store.is_some();
                self.held_cleanup_store = None;
                if !had_held {
                    self.pending_as_cleanup = None;
                }
                return;
            }
        }
        // drop stale exhausted frames (stores rerouted elsewhere)
        while matches!(self.unpack_frames.last(), Some((0, _, _, _))) {
            self.unpack_frames.pop();
            self.unpack_targets.0.pop();
            self.unpack_target_lines.pop();
        }
        if let Some(frame) = self.unpack_frames.last_mut() {
            frame.0 -= 1;
            let done = frame.0 == 0;
            if let Some(targets) = self.unpack_targets.0.last_mut() {
                targets.push((target, false));
            }
            if done {
                self.unpack_frames.pop();
                let targets = self.unpack_targets.0.pop().unwrap();
                let list: Vec<ExprRef> = targets.into_iter().map(|(t, _)| t).collect();
                self.push_stmt(Stmt::Delete(list));
            }
            return;
        }
        if let Some(last) = self.blocks.last_mut() {
            if let Some(Stmt::Delete(v)) = last.stmts.last_mut() {
                v.push(target);
                return;
            }
        }
        self.push_stmt(Stmt::Delete(vec![target]));
    }

    /// 3.9/3.10: exits without CALL_FINALLY duplicate the finally body
    /// inline right before a `return` inside the try. The copy renders as
    /// real statements in the exiting arm while the genuine finally also
    /// renders from the handler region (codeop 3.9 _maybe_compile
    /// duplicated `err1 = err2 = None`). When the innermost open block's
    /// statement tail mirrors the finally-copy region (the open Try's
    /// handler start to its END_FINALLY/RERAISE) exactly, drop the copy
    /// statements and the triggering return: rendering the bare `return`
    /// lets the compiler regenerate the copy on recompile, and the
    /// post-try tail flow supplies the function's own tail return.
    fn swallow_inline_finally_return(&mut self) -> bool {
        if !self.version.at_least(3, 9)
            || self.version.at_least(3, 11)
            || self.legacy_handler.is_some()
        {
            return false;
        }
        let h = match self
            .blocks
            .iter()
            .rev()
            .find(|b| b.kind == BlockType::Try)
            .map(|b| b.end)
        {
            Some(h) => h,
            None => return false,
        };
        // the return must sit in the try flow, before the handler region
        if self.cur_offset >= h {
            return false;
        }
        let Some(&hi) = self.idx_of.get(&h) else {
            return false;
        };
        // copy region extent: the handler's own copy ends at its
        // END_FINALLY/RERAISE
        let mut stop_i = None;
        for k in hi..(hi + 60).min(self.instrs.len()) {
            if matches!(self.instrs[k].op, Op::END_FINALLY | Op::RERAISE) {
                stop_i = Some(k);
                break;
            }
        }
        let Some(stop_i) = stop_i else {
            return false;
        };
        if stop_i <= hi || stop_i - hi > 32 {
            return false;
        }
        // the copy's trailing stores may still sit in pending_stores (the
        // return is their flush trigger) — land them in the arm first so
        // the mirror sees the complete statement tail
        if !self.pending_stores.is_empty() {
            self.flushing = true;
            self.flush_pending_stores();
            self.flushing = false;
        }
        let consumed = self.mirror_finally_copy(hi, stop_i);
        if consumed == 0 {
            return false;
        }
        if let Some(top) = self.blocks.last_mut() {
            let n = top.stmts.len();
            top.stmts.truncate(n - consumed);
        }
        true
    }

    /// Backward-mirror the finally-copy instruction range [hi, stop_i)
    /// against the innermost block's statement tail; returns the number
    /// of trailing statements that exactly account for the whole range.
    fn mirror_finally_copy(&self, hi: usize, stop_i: usize) -> usize {
        let Some(top) = self.blocks.last() else {
            return 0;
        };
        let mut ci = stop_i;
        let mut si = top.stmts.len();
        let mut consumed = 0usize;
        while ci > hi && si > 0 {
            let nc = match &top.stmts[si - 1] {
                Stmt::Assign { targets, value, .. } => {
                    self.match_assign_backwards(ci, hi, targets, value)
                }
                Stmt::Expr(e) => self.match_call_backwards(ci, hi, e),
                _ => None,
            };
            let Some(nc) = nc else {
                break;
            };
            ci = nc;
            si -= 1;
            consumed += 1;
        }
        if ci == hi && consumed > 0 {
            consumed
        } else {
            0
        }
    }

    /// `a = b = None` (chained None stores) against a backward copy tail:
    /// [LOAD_CONST None; DUP_TOP x (n-1); STORE x n]
    fn match_assign_backwards(
        &self,
        ci: usize,
        hi: usize,
        targets: &[ExprRef],
        value: &ExprRef,
    ) -> Option<usize> {
        let none_val = matches!(&**value, Expr::Const(o) if matches!(&**o, PyObject::None));
        if !none_val || targets.is_empty() {
            return None;
        }
        let mut stores = Vec::new();
        let mut c = ci;
        while c > hi
            && matches!(
                self.instrs[c - 1].op,
                Op::STORE_FAST | Op::STORE_NAME | Op::STORE_DEREF
            )
        {
            stores.push(c - 1);
            c -= 1;
        }
        stores.reverse();
        if stores.len() != targets.len() {
            return None;
        }
        let names_ok = targets.iter().zip(stores.iter()).all(|(t, &ii)| {
            matches!(&**t, Expr::Name(n)
                if self.store_del_name(ii).as_deref() == Some(n.as_str()))
        });
        if !names_ok {
            return None;
        }
        let mut c2 = c;
        let mut dups = 0usize;
        while c2 > hi && self.instrs[c2 - 1].op == Op::DUP_TOP {
            dups += 1;
            c2 -= 1;
        }
        if dups + 1 != targets.len() || c2 <= hi {
            return None;
        }
        let load = &self.instrs[c2 - 1];
        if load.op != Op::LOAD_CONST
            || !matches!(
                self.code.consts.get(load.arg as usize).map(|o| &**o),
                Some(PyObject::None)
            )
        {
            return None;
        }
        Some(c2 - 1)
    }

    /// `recv.meth()` / `recv.attr.meth()` cleanup call against a backward
    /// copy tail: [LOAD recv; (LOAD_ATTR attr;)? LOAD_METHOD meth;
    /// CALL n; POP_TOP?]
    fn match_call_backwards(&self, ci: usize, hi: usize, e: &ExprRef) -> Option<usize> {
        let Expr::Call { func, args, keywords, star_args, star_kwargs } = &**e else {
            return None;
        };
        if !keywords.is_empty() || star_args.is_some() || star_kwargs.is_some() || args.len() > 1
        {
            return None;
        }
        let Expr::Attribute { value: recv, attr } = &**func else {
            return None;
        };
        let mut c = ci;
        if c > hi && self.instrs[c - 1].op == Op::POP_TOP {
            c -= 1;
        }
        if c <= hi
            || !matches!(
                self.instrs[c - 1].op,
                Op::CALL_METHOD | Op::CALL_FUNCTION | Op::CALL
            )
            || self.instrs[c - 1].arg as usize != args.len()
        {
            return None;
        }
        c -= 1;
        // argument load (single-arg cleanup calls like print(x) are rare
        // in finally copies; support zero args plus one plain load)
        if args.len() == 1 {
            // accept any single load instruction for the argument
            if c <= hi
                || !matches!(
                    self.instrs[c - 1].op,
                    Op::LOAD_FAST | Op::LOAD_NAME | Op::LOAD_DEREF | Op::LOAD_CONST
                        | Op::LOAD_GLOBAL | Op::LOAD_ATTR
                )
            {
                return None;
            }
            c -= 1;
        }
        // method name
        if c <= hi
            || !matches!(
                self.instrs[c - 1].op,
                Op::LOAD_METHOD | Op::LOAD_ATTR
            )
        {
            return None;
        }
        let mi = c - 1;
        let meth_name = if self.instrs[mi].op == Op::LOAD_ATTR {
            // LOAD_ATTR here only appears pre-3.12 callable-attr form or
            // the receiver attribute chain; compare raw name index
            self.const_name(self.instrs[mi].arg as usize)
        } else {
            self.const_name(self.instrs[mi].arg as usize)
        };
        if meth_name != *attr {
            return None;
        }
        c = mi;
        // receiver
        match &**recv {
            Expr::Name(n) => {
                if c <= hi {
                    return None;
                }
                if self.load_name_at(c - 1).as_deref() != Some(n.as_str()) {
                    return None;
                }
                Some(c - 1)
            }
            Expr::Attribute { value: rv, attr: ra } => {
                let Expr::Name(rn) = &**rv else {
                    return None;
                };
                if c <= hi + 1 || self.instrs[c - 1].op != Op::LOAD_ATTR {
                    return None;
                }
                if self.const_name(self.instrs[c - 1].arg as usize) != *ra {
                    return None;
                }
                if self.load_name_at(c - 2).as_deref() != Some(rn.as_str()) {
                    return None;
                }
                Some(c - 2)
            }
            _ => None,
        }
    }

    /// LOAD_FAST/NAME/DEREF name at instruction index
    fn load_name_at(&self, idx: usize) -> Option<String> {
        let ins = self.instrs.get(idx)?;
        match ins.op {
            Op::LOAD_FAST => Some(self.local_name(ins.arg as usize)),
            Op::LOAD_NAME => Some(self.const_name(ins.arg as usize)),
            Op::LOAD_DEREF => Some(
                self.code
                    .deref_name(ins.arg as usize)
                    .unwrap_or("?")
                    .to_string(),
            ),
            _ => None,
        }
    }

    /// 3.11+ function-tail try/except[/else] whose implicit `return None`
    /// the compiler SANK into both exits: the success path ends with a
    /// RETURN None right before the out-of-line chain, and the chain's
    /// last clause ends `POP_EXCEPT; RETURN_CONST None` (3.12+) or
    /// `POP_EXCEPT; LOAD None; RETURN_VALUE` (3.11). Neither copy is a
    /// source statement and NO jump delimits an else region — the
    /// success-side copy at offset R is the boundary: else = [body_end, R).
    /// Returns (R, chain_end); the caller skips to chain_end so both the
    /// copy and the chain (already parsed as handlers) are not re-walked.
    /// Sunk value-return mirror detection for a 3.11+ zero-cost
    /// try/except/else: the handler chain's tail is
    /// `POP_EXCEPT; <non-jump ops>; RETURN_VALUE` (the clause RETURNS
    /// through a sunk copy of the function's tail statement) and the
    /// mainline after the try body holds the identical (op, arg)
    /// sequence. The mainline copy starts the function tail, so the
    /// inline else arm is [body_end, mirror) and the walk resumes at the
    /// mirror to emit the tail once. Returns (else_end, merge).
    fn sunk_return_mirror_merge(
        &self,
        body_end: usize,
        handler: usize,
        chain_end: usize,
    ) -> Option<(usize, usize)> {
        if !self.version.at_least(3, 11) || chain_end <= handler {
            return None;
        }
        let (&hi, &ci) = (self.idx_of.get(&handler)?, self.idx_of.get(&chain_end)?);
        // the sunk tail: a POP_EXCEPT followed by a pure value build-up
        // ending in RETURN_VALUE (the clause RETURNS through the sunk
        // copy). The chain's closing COPY/POP_EXCEPT/RERAISE stubs also
        // hold POP_EXCEPTs - pick the one whose forward span to a
        // RETURN_VALUE carries no jump/exception material.
        let mut found: Option<(usize, usize)> = None;
        for k in hi..ci {
            if self.instrs[k].op != Op::POP_EXCEPT {
                continue;
            }
            for r in k + 1..ci {
                let x = &self.instrs[r];
                if x.op == Op::RETURN_VALUE {
                    found = Some((k, r));
                    break;
                }
                if x.is_jump()
                    || matches!(
                        x.op,
                        Op::RERAISE
                            | Op::CHECK_EXC_MATCH
                            | Op::PUSH_EXC_INFO
                            | Op::END_FINALLY
                            | Op::POP_EXCEPT
                    )
                {
                    break;
                }
            }
        }
        let (pi, ri) = found?;
        // 3.14 mixes borrow/check LOAD variants between the sunk copy
        // (plain LOAD_FAST) and the mainline (LOAD_FAST_BORROW): they
        // load the SAME local - canonicalize for the mirror compare
        let canon = |op: Op| -> Op {
            match op {
                Op::LOAD_FAST_BORROW | Op::LOAD_FAST_CHECK => Op::LOAD_FAST,
                Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW => {
                    Op::LOAD_FAST_LOAD_FAST
                }
                o => o,
            }
        };
        let tail: Vec<(Op, u32)> = self.instrs[pi + 1..=ri]
            .iter()
            .map(|x| (canon(x.op), x.arg))
            .collect();
        // require a NON-DEGENERATE tail: at least one value op before
        // the RETURN. A lone RETURN_VALUE (the clause's value was
        // loaded+SWAPed UNDER the POP_EXCEPT, _collections_abc 3.12
        // MutableMapping.pop `return default`) matches every return in
        // the mainline and claimed the else arm's own return as the
        // mirror, losing it. A bare `LOAD None; RETURN` tail is
        // try_tail_sunk_pair's stricter domain - skip it here.
        if tail.len() < 2 {
            return None;
        }
        if tail.len() == 2
            && tail[0].0 == Op::LOAD_CONST
            && matches!(
                self.code.consts.get(tail[0].1 as usize).map(|o| &**o),
                Some(PyObject::None)
            )
        {
            return None;
        }
        // the tail must START with a value build (a LOAD): stack-shuffle
        // heads (SWAP/POP_TOP/COPY) are handler-exit machinery that also
        // ends mainline tuple returns - matching them mid-sequence
        // claimed the mainline return's own tail as the mirror and ate
        // its value build (bdb 3.14 effective: `return b, True` lost
        // its tuple and the walk hit RETURN underflow)
        if matches!(
            tail[0].0,
            Op::SWAP
                | Op::POP_TOP
                | Op::POP_EXCEPT
                | Op::COPY
                | Op::ROT_TWO
                | Op::ROT_THREE
                | Op::ROT_FOUR
                | Op::END_SEND
                | Op::RESUME
        ) {
            return None;
        }
        // mainline mirror scan: find the identical sequence at/after
        // body_end (the tail return the else arm falls through to)
        let Some(&bi) = self.idx_of.get(&body_end) else {
            return None;
        };
        for m in bi..self.instrs.len().saturating_sub(tail.len()) {
            if self.instrs[m].offset < body_end || self.instrs[m].offset >= handler {
                continue;
            }
            if (0..tail.len()).all(|j| {
                (canon(self.instrs[m + j].op), self.instrs[m + j].arg) == tail[j]
            }) {
                let x = self.instrs[m].offset;
                if x > body_end {
                    return Some((x, x));
                }
                return None;
            }
        }
        None
    }

    fn try_tail_sunk_pair(
        &self,
        body_end: usize,
        handler: usize,
        chain_end: usize,
    ) -> Option<(usize, usize)> {
        if !self.version.at_least(3, 11)
            || self.code.is_generator()
            || self.code.is_async_generator()
            // module level: the gap before the chain holds the module's
            // real tail statements (sunk into the handler by 3.12+, see
            // dedup_sunk_handler_tails) far more often than an else —
            // datetime/decimal `__all__` reads as a phantom else body
            || self.code.name == "<module>"
        {
            return None;
        }
        // the chain must be the function's LAST code: the sunk tail pair
        // only exists for a tail-position try (its handler copies the
        // implicit function terminator). A try nested inside a finally
        // copy or a loop has real code after its chain (cmd.cmdloop's
        // readline import inside the finally fired without this bound
        // and decompiled the whole following span as a phantom else)
        let he = self.idx_of.get(&handler).copied()?;
        let ce = self.idx_of.get(&chain_end).copied().unwrap_or(self.instrs.len());
        let mut tail_only = true;
        for x in &self.instrs[ce.min(self.instrs.len())..] {
            if x.offset <= chain_end {
                continue;
            }
            if !matches!(
                x.op,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::RESUME | Op::RETURN_CONST
            ) {
                tail_only = false;
                break;
            }
        }
        if !tail_only {
            return None;
        }
        // chain tail: skipping cleanup stubs backward (bounded — stub
        // runs are short; an unbounded skip could wander into an earlier
        // clause's genuine return), the last real instruction must be a
        // bare None return
        let mut ri = None;
        let mut k = ce;
        let mut hops = 0;
        while k > he && hops < 16 {
            k -= 1;
            hops += 1;
            let x = &self.instrs[k];
            match x.op {
                Op::RERAISE | Op::POP_EXCEPT | Op::COPY | Op::SWAP | Op::NOP
                | Op::NOT_TAKEN | Op::CACHE | Op::END_FINALLY => continue,
                Op::RETURN_VALUE | Op::RETURN_CONST => {
                    ri = Some(k);
                    break;
                }
                _ => return None,
            }
        }
        let ri = ri?;
        let ret = &self.instrs[ri];
        let bare = match ret.op {
            Op::RETURN_CONST => matches!(
                self.code.consts.get(ret.arg as usize).map(|o| &**o),
                Some(PyObject::None)
            ),
            Op::RETURN_VALUE => ri > 0 && {
                let p = &self.instrs[ri - 1];
                p.op == Op::LOAD_CONST
                    && matches!(
                        self.code.consts.get(p.arg as usize).map(|o| &**o),
                        Some(PyObject::None)
                    )
            },
            _ => false,
        };
        if !bare {
            return None;
        }
        // success-side copy: the LAST bare None return in the gap between
        // the try body and the chain head; the else body lies before it
        let be = self.idx_of.get(&body_end).copied()?;
        let mut r_off = None;
        for x in self.instrs[be..he].iter() {
            let bare_x = match x.op {
                Op::RETURN_CONST => matches!(
                    self.code.consts.get(x.arg as usize).map(|o| &**o),
                    Some(PyObject::None)
                ),
                Op::RETURN_VALUE => x.offset > 0 && {
                    // the value LOAD sits immediately before the return
                    self.idx_of
                        .get(&x.offset)
                        .and_then(|&xi| xi.checked_sub(1).map(|p| &self.instrs[p]))
                        .map(|p| {
                            p.op == Op::LOAD_CONST
                                && matches!(
                                    self.code.consts.get(p.arg as usize).map(|o| &**o),
                                    Some(PyObject::None)
                                )
                        })
                        .unwrap_or(false)
                },
                _ => false,
            };
            if bare_x {
                r_off = Some(x.offset);
            }
        }
        let r = r_off?;
        if r <= body_end {
            return None;
        }
        // the gap must be plain else-body flow: a chain head or a loop
        // back edge there means this is not the sunk-tail shape
        for x in self.instrs[be..he].iter() {
            if x.offset >= r {
                break;
            }
            if x.op == Op::PUSH_EXC_INFO {
                return None;
            }
            if (x.op == Op::JUMP_BACKWARD
                || x.op == Op::JUMP_BACKWARD_NO_INTERRUPT
                || ((x.op == Op::JUMP_ABSOLUTE || x.op == Op::JUMP) && x.is_backward))
                && x.offset < r
            {
                return None;
            }
        }
        Some((r, chain_end))
    }

    /// 3.10 tail-position try: the compiler sinks the implicit
    /// function/module terminator `return None` into BOTH the success
    /// path (just before handler_start) and each handler exit
    /// (POP_EXCEPT; LOAD None; RETURN), with no shared merge tail.
    /// Neither copy is a source statement: the success-path copy at
    /// module level would even be a `return` outside function. Detect
    /// the pair: a None return here plus a None return after
    /// POP_EXCEPT in the handler chain.
    /// 3.8-3.10 sunk tail-RAISE pair: when a function's post-try
    /// continuation is a terminating `raise X`, the compiler can
    /// duplicate it into BOTH exits — the success path (immediately
    /// before the handler head) and the handler path (immediately after
    /// the last POP_EXCEPT) — with no merge jump at all
    /// (_sitebuiltins 3.10 Quitter.__call__: `try: sys.stdin.close()
    /// except: pass` + `raise SystemExit(code)`). Both copies walked as
    /// statements land in the enclosing block BEFORE the chain flushes,
    /// rendering `raise; raise; try: ...`. Detect the pair:
    /// Some(true) = this raise is the success-side copy (drop it),
    /// Some(false) = the handler-side copy (flush the chain first so
    /// the single rendered raise follows the Try).
    fn sunk_raise_pair_side(&self, raise_off: usize, arg: u32) -> Option<bool> {
        if !self.version.at_least(3, 8) || self.version.at_least(3, 11) {
            return None;
        }
        if self.legacy_handler.is_some() || !self.legacy_nest.is_empty() {
            return None;
        }
        let lt = self.legacy_try.as_ref()?;
        if lt.has_finally || lt.else_start.is_some() || arg == 0 {
            return None;
        }
        let hs = lt.handler_start;
        // the mirrored copy's value run: straight-line expression ops
        // from `start` ending in RAISE_VARARGS with the same arg
        let mirrored_run = |start: usize| -> bool {
            let Some(&si) = self.idx_of.get(&start) else {
                return false;
            };
            let mut j = si;
            let mut steps = 0;
            while steps < 24 {
                steps += 1;
                let Some(x) = self.instrs.get(j) else {
                    return false;
                };
                match x.op {
                    Op::NOP | Op::CACHE | Op::NOT_TAKEN => {
                        j += 1;
                        continue;
                    }
                    Op::RAISE_VARARGS => return x.arg == arg,
                    Op::LOAD_GLOBAL
                    | Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
                    | Op::LOAD_DEREF
                    | Op::LOAD_CLOSURE
                    | Op::LOAD_BUILD_CLASS
                    | Op::CALL_FUNCTION
                    | Op::CALL_METHOD
                    | Op::CALL_FUNCTION_KW
                    | Op::CALL_FUNCTION_EX
                    | Op::PRECALL
                    | Op::CALL
                    | Op::KW_NAMES
                    | Op::BINARY_OP
                    | Op::BINARY_SUBSCR
                    | Op::BUILD_TUPLE
                    | Op::BUILD_LIST
                    | Op::BUILD_MAP
                    | Op::BUILD_SET
                    | Op::BUILD_STRING
                    | Op::FORMAT_VALUE
                    | Op::COMPARE_OP
                    | Op::CONTAINS_OP
                    | Op::IS_OP
                    | Op::LIST_EXTEND
                    | Op::DICT_MERGE => {
                        j += 1;
                    }
                    _ => return false,
                }
            }
            false
        };
        if raise_off < hs {
            // success-side copy: the raise must be the LAST thing before
            // the handler head, the chain not yet parsed, and a mirrored
            // raise must sit after a POP_EXCEPT inside the chain
            if !lt.handlers.is_empty() {
                return None;
            }
            let mut k = match self.idx_of.get(&raise_off) {
                Some(&i) => i + 1,
                None => return None,
            };
            while matches!(
                self.instrs.get(k).map(|x| x.op),
                Some(Op::NOP) | Some(Op::CACHE) | Some(Op::EXTENDED_ARG)
            ) {
                k += 1;
            }
            if self.instrs.get(k).map(|x| x.offset) != Some(hs) {
                return None;
            }
            let mut m = k;
            let mut steps = 0;
            while m < self.instrs.len() && steps < 120 {
                steps += 1;
                match self.instrs[m].op {
                    Op::POP_EXCEPT => {
                        // optional `as` cleanup between POP_EXCEPT and
                        // the sunk copy
                        let mut j = m + 1;
                        while matches!(
                            self.instrs.get(j).map(|x| x.op),
                            Some(Op::NOP) | Some(Op::CACHE) | Some(Op::NOT_TAKEN)
                        ) {
                            j += 1;
                        }
                        let as_cleanup = matches!(
                            self.instrs.get(j).map(|x| x.op),
                            Some(Op::LOAD_CONST)
                        ) && matches!(
                            self.instrs.get(j + 1).map(|x| x.op),
                            Some(Op::STORE_FAST)
                                | Some(Op::STORE_NAME)
                                | Some(Op::STORE_DEREF)
                        ) && matches!(
                            self.instrs.get(j + 2).map(|x| x.op),
                            Some(Op::DELETE_FAST)
                                | Some(Op::DELETE_NAME)
                                | Some(Op::DELETE_DEREF)
                        );
                        let from = if as_cleanup { j + 3 } else { j };
                        let start = self.instrs.get(from).map(|x| x.offset);
                        if let Some(s) = start {
                            if mirrored_run(s) {
                                return Some(true);
                            }
                        }
                        // clause exit jump / next clause material: keep
                        // scanning for a later POP_EXCEPT
                    }
                    Op::RERAISE | Op::END_FINALLY => break,
                    _ => {}
                }
                m += 1;
            }
            return None;
        }
        // handler-side copy: the chain's clauses are collected, this
        // raise follows the handler region's last POP_EXCEPT through a
        // straight-line value run, and the success-side mirror sits
        // immediately before the handler head
        if lt.handlers.is_empty() {
            return None;
        }
        let Some(&hi) = self.idx_of.get(&hs) else {
            return None;
        };
        let mut j = hi;
        while j > 0
            && matches!(
                self.instrs[j - 1].op,
                Op::NOP | Op::CACHE | Op::NOT_TAKEN
            )
        {
            j -= 1;
        }
        if j == 0
            || self.instrs[j - 1].op != Op::RAISE_VARARGS
            || self.instrs[j - 1].arg != arg
        {
            return None;
        }
        // backward value-run check: only expression ops between the
        // raise and the handler region's POP_EXCEPT
        let Some(&ri) = self.idx_of.get(&raise_off) else {
            return None;
        };
        let mut b = ri;
        let mut saw_pop_except = false;
        while b > hi {
            let p = self.instrs[b - 1];
            if p.op == Op::POP_EXCEPT {
                saw_pop_except = true;
                break;
            }
            if !matches!(
                p.op,
                Op::NOP
                    | Op::CACHE
                    | Op::NOT_TAKEN
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
                    | Op::LOAD_DEREF
                    | Op::CALL_FUNCTION
                    | Op::CALL_METHOD
                    | Op::CALL_FUNCTION_KW
                    | Op::PRECALL
                    | Op::CALL
                    | Op::KW_NAMES
                    | Op::BINARY_OP
                    | Op::BINARY_SUBSCR
                    | Op::BUILD_TUPLE
                    | Op::BUILD_LIST
                    | Op::BUILD_MAP
                    | Op::BUILD_SET
                    | Op::BUILD_STRING
                    | Op::FORMAT_VALUE
            ) {
                return None;
            }
            b -= 1;
        }
        if saw_pop_except {
            Some(false)
        } else {
            None
        }
    }

    /// The success-side copy of a sunk return pair: a `LOAD None; RETURN`
    /// run immediately before the open chain's handler head (padding
    /// skipped). Its presence proves the compiler duplicated the post-try
    /// return into both exits; its absence means an in-handler RETURN is
    /// the source's own `except E: return` (3.8/3.9 never sink).
    fn has_pre_handler_return_mirror(&self) -> bool {
        let Some(lt) = self.legacy_try.as_ref() else {
            return false;
        };
        let Some(&hi) = self.idx_of.get(&lt.handler_start) else {
            return false;
        };
        let is_none_load = |i: usize| {
            self.instrs.get(i).map(|x| {
                x.op == Op::LOAD_CONST
                    && matches!(
                        self.code.consts.get(x.arg as usize).map(|o| &**o),
                        Some(PyObject::None)
                    )
            }) == Some(true)
        };
        let is_ret = |i: usize| {
            matches!(
                self.instrs.get(i).map(|x| x.op),
                Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
            )
        };
        let mut j = hi;
        while j > 0
            && matches!(
                self.instrs[j - 1].op,
                Op::NOP | Op::CACHE | Op::NOT_TAKEN | Op::EXTENDED_ARG
            )
        {
            j -= 1;
        }
        j >= 2 && is_ret(j - 1) && is_none_load(j - 2)
    }

    /// 3.10 value-return sunk copies: when a post-if/else merge
    /// `return v` is the function's last statement, the compiler sinks
    /// an identical `LOAD v; RETURN` copy into every early exit (try
    /// body end, handler exit) so each path terminates in place. The
    /// copies are machinery: rendering them duplicates the return in
    /// the body/handler and blocks the flat-render recompile from
    /// regenerating the sinks (cProfile 3.10 main: `return parser`
    /// inside the try body and the BrokenPipeError clause). Detect by
    /// an exact normalized-run mirror against the function's FINAL
    /// return run, with the copy sitting at the chain body end or
    /// inside the chain span.
    /// 3.10 for-loop break with the post-loop value return SUNK into
    /// the break path: `for ...: if A: <stmts>; break / else: <tail>` +
    /// `return v` compiles the break as POP_TOP (iterator) followed
    /// DIRECTLY by a copy of the tail return run (no jump), then a dead
    /// JABS back edge (copy 3.10 _deepcopy_tuple: rendering the copy as
    /// `return y` lost the break/for-else and recompiled with the
    /// return-from-loop ROT_TWO cleanup order). Fold: emit Break, skip
    /// to the exhaustion exit so the else machinery runs, and flag the
    /// ForElse close to lift the else arm's trailing mirror Return to
    /// function level.
    fn try_fold_sunk_for_break(&mut self) -> bool {
        // 3.10+: the break path carries POP_TOP(iterator) + a direct
        // copy of the tail return (3.11 SWAP 2 prelude, 3.12-3.14 keep
        // the bare shape — copy _deepcopy_tuple is sig-exact on all)
        if !self.version.at_least(3, 10) {
            return false;
        }
        if self.legacy_handler.is_some() || self.legacy_try.is_some() {
            return false;
        }
        let Some(lb) = self.blocks.iter().rev().find(|b| {
            matches!(b.kind, BlockType::For)
        }) else {
            return false;
        };
        let (lb_start, lb_end) = (lb.start, lb.end);
        if !(lb_start < self.cur_offset && self.cur_offset < lb_end) {
            return false;
        }
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let norm = |x: &crate::bytecode::Instruction| (x.op as u8, x.arg);
        let Some(&pi) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        // forward: [value loads] RETURN
        let mut k = pi + 1;
        let mut hops = 0;
        while k < self.instrs.len() && hops < 8 {
            let x = &self.instrs[k];
            if is_pad(x) {
                k += 1;
                continue;
            }
            if matches!(
                x.op,
                Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_DEREF
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
            ) {
                k += 1;
                hops += 1;
                continue;
            }
            break;
        }
        let ret_at = k;
        if !matches!(
            self.instrs.get(ret_at).map(|x| x.op),
            Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
        ) {
            return false;
        }
        let run_a: Vec<(u8, u32)> = self.instrs[pi + 1..=ret_at]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        // a bare RETURN (value already built under the iterator, e.g.
        // 3.11 SWAP 2; POP_TOP; RETURN of an in-loop `return a, b`)
        // trivially mirrors any tail return — require at least one
        // value load so the mirror is meaningful (csv 3.11
        // _guess_delimiter: the bare-RETURN fold turned the in-loop
        // return into a break and sank the whole function tail into a
        // phantom for-else)
        if run_a.len() < 2 {
            return false;
        }
        // the function's final return run must mirror it
        let n = self.instrs.len();
        if n < 2 || ret_at >= n - 1 {
            return false;
        }
        let mut f = n - 1;
        if !matches!(
            self.instrs[f].op,
            Op::RETURN_VALUE | Op::RETURN_CONST
        ) {
            return false;
        }
        let mut fb = f;
        let mut fhops = 0;
        while fb > 0 && fhops < 8 {
            let p = &self.instrs[fb - 1];
            if is_pad(p)
                || matches!(
                    p.op,
                    Op::LOAD_FAST
                        | Op::LOAD_NAME
                        | Op::LOAD_GLOBAL
                        | Op::LOAD_DEREF
                        | Op::LOAD_CONST
                        | Op::LOAD_ATTR
                        | Op::LOAD_METHOD
                )
            {
                fb -= 1;
                fhops += 1;
                continue;
            }
            break;
        }
        let run_f: Vec<(u8, u32)> = self.instrs[fb..=f]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        if run_f != run_a {
            return false;
        }
        // after the copy: only a dead back edge to the loop top
        let mut early_guard = false;
        let mut m = ret_at + 1;
        while m < self.instrs.len() && is_pad(&self.instrs[m]) {
            m += 1;
        }
        let dead_edge_ok = match self.instrs.get(m) {
            Some(x)
                if x.is_backward
                    && x.target == Some(lb_start)
                    && matches!(
                        x.op,
                        Op::JUMP_ABSOLUTE
                            | Op::JUMP_BACKWARD
                            | Op::JUMP_BACKWARD_NO_INTERRUPT
                    ) =>
            {
                true
            }
            Some(x) if x.offset >= lb_end => true,
            // early-guard break (cgitb 3.12 scanvars `if ttype ==
            // NEWLINE: break` as the loop's FIRST statement): the sunk
            // copy is followed directly by the live loop body — no dead
            // edge exists. Accept when the copy's RETURN is the mirror
            // (checked above) and the loop body resumes right after;
            // only the copy is skipped, the walk continues in the loop.
            // No for-else registration in this variant: the exhaustion
            // exit falls straight into the tail return run (an empty
            // [lb_end, fb) span) — registering would grow a phantom
            // else and move the tail return inside it.
            Some(x2) if x2.offset < lb_end
                && matches!(
                    self.blocks.last().map(|b| (b.kind == BlockType::If, b.end)),
                    Some((true, te)) if te == x2.offset
                ) =>
            {
                // the copy is the WHOLE body of an `if guard:` ending
                // exactly where the loop body resumes
                early_guard = true;
                true
            }
            _ => false,
        };
        if !dead_edge_ok {
            return false;
        }
        // the exhaustion path may hold a for-ELSE arm whose flow ends in
        // the same sunk return run ([lb_end, fb) = else stmts, [fb,..] =
        // the tail copy): register the else end so the For close builds
        // the Else block and the tail return renders at function level
        let else_end_off = self.instrs[fb].offset;
        // the else arm exists iff REAL statements sit between the loop's
        // exhaustion exit and the tail return run — the early-guard
        // variant has no dead back edge to lean on, so decide by span
        // content (cgitb scanvars: END_FOR only → no else; b16
        // two_loops_same_fn: END_FOR; POP_TOP; appends → real else)
        let has_else_span = else_end_off > lb_end
            && self
                .idx_of
                .get(&lb_end)
                .map_or(false, |&li| {
                    self.instrs[li..fb].iter().any(|x| {
                        !matches!(
                            x.op,
                            Op::END_FOR
                                | Op::POP_ITER
                                | Op::POP_TOP
                                | Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE
                                | Op::EXTENDED_ARG
                        )
                    })
                });
        if (!early_guard && else_end_off > lb_end) || (early_guard && has_else_span) {
            if let Some(b) = self.blocks.iter_mut().rev().find(|b| {
                matches!(b.kind, BlockType::For) && b.start == lb_start
            }) {
                if b.loop_else_end.is_none() {
                    b.loop_else_end = Some(else_end_off);
                }
            }
        }
        self.push_stmt(Stmt::Break);
        if !early_guard {
            self.sunk_loop_return_lift = true;
            if self.skip_until.map_or(true, |sk| sk < lb_end) {
                self.skip_until = Some(lb_end);
            }
        } else {
            // skip only the copy; the loop body resumes right after it
            let after = self.instrs[m].offset;
            if self.skip_until.map_or(true, |sk| sk < after) {
                self.skip_until = Some(after);
            }
        }
        true
    }

    fn sunk_value_return_mirror(&self, ret_offset: usize) -> bool {
        if !self.version.at_least(3, 10)
            || self.version.at_least(3, 11)
            || self.code.is_generator()
            || self.code.is_async_generator()
            || self.code.name == "<module>"
        {
            return false;
        }
        let Some(l) = self.legacy_try.as_ref().map(|l| l.handler_start) else {
            return false;
        };
        let Some(&ri) = self.idx_of.get(&ret_offset) else {
            return false;
        };
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let norm = |x: &crate::bytecode::Instruction| (x.op as u8, x.arg);
        // value run before this return (bounded)
        let mut b = ri;
        let mut hops = 0;
        while b > 0 && hops < 8 {
            let p = &self.instrs[b - 1];
            if is_pad(p) {
                b -= 1;
                hops += 1;
                continue;
            }
            if matches!(
                p.op,
                Op::LOAD_FAST
                    | Op::LOAD_NAME
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_DEREF
                    | Op::LOAD_CONST
                    | Op::LOAD_ATTR
                    | Op::LOAD_METHOD
            ) {
                b -= 1;
                hops += 1;
                continue;
            }
            break;
        }
        let run_a: Vec<(u8, u32)> = self.instrs[b..=ri]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        if run_a.len() < 2
            || !matches!(
                run_a.last().map(|t| t.0),
                Some(op) if op == Op::RETURN_VALUE as u8
            )
        {
            return false;
        }
        // position: body end (next meaningful == handler head) or inside
        // the chain span
        let next_meaningful = self.instrs[ri + 1..]
            .iter()
            .find(|x| !is_pad(x))
            .map(|x| x.offset);
        let chain_end = self.chain_extent(l);
        let at_body_end = next_meaningful == Some(l);
        // inside the chain, a sunk copy sits on the clause's EXIT path —
        // past its POP_EXCEPT (and any as-cleanup). A genuine `return v`
        // INSIDE a clause body can mirror the function tail exactly
        // (crypt 3.10 _add_method: `if e.errno in {...}: return False`
        // mirrors the final `return False`) and must not be dropped
        let in_chain = ret_offset > l
            && ret_offset < chain_end
            && self
                .idx_of
                .get(&l)
                .zip(self.idx_of.get(&ret_offset))
                .map_or(false, |(&hi, &ri2)| {
                    self.instrs[hi..ri2].iter().any(|x| x.op == Op::POP_EXCEPT)
                });
        if !at_body_end && !in_chain {
            return false;
        }
        // the function's final return run must mirror this one exactly
        let n = self.instrs.len();
        if n < 2 || ri >= n - 2 {
            return false;
        }
        let mut f = n - 1;
        if !matches!(
            self.instrs[f].op,
            Op::RETURN_VALUE | Op::RETURN_CONST
        ) {
            return false;
        }
        let mut fb = f;
        let mut fhops = 0;
        while fb > 0 && fhops < 8 {
            let p = &self.instrs[fb - 1];
            if is_pad(p)
                || matches!(
                    p.op,
                    Op::LOAD_FAST
                        | Op::LOAD_NAME
                        | Op::LOAD_GLOBAL
                        | Op::LOAD_DEREF
                        | Op::LOAD_CONST
                        | Op::LOAD_ATTR
                        | Op::LOAD_METHOD
                )
            {
                fb -= 1;
                fhops += 1;
                continue;
            }
            break;
        }
        let run_f: Vec<(u8, u32)> = self.instrs[fb..=f]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        if run_f != run_a || self.instrs[f].offset <= chain_end {
            return false;
        }
        // a sunk copy is the clause's LAST flow: only compiler stub
        // material may follow it (bounded window). A source-level
        // `return v` inside a handler is followed by the rest of the
        // clause (`raise` -> RAISE_VARARGS, more matches, real
        // statements) — crypt 3.10 _add_method's `if e.errno in {...}:
        // return False` mirrors the final `return False` exactly and
        // rendered `pass` under the position-only form. The try-body-end
        // copy (at_body_end) is exempt: its chain lies AHEAD
        if in_chain {
            // scan bound: the chain's own extent, extended over trailing
            // stub runs to the first mainline instruction
            let mut scan_bound = chain_end;
            if let Some(&ci2) = self.idx_of.get(&chain_end) {
                for x in self.instrs[ci2..].iter().take(16) {
                    if matches!(
                        x.op,
                        Op::RERAISE | Op::END_FINALLY | Op::POP_EXCEPT
                            | Op::POP_TOP | Op::COPY | Op::SWAP | Op::NOP
                            | Op::NOT_TAKEN | Op::CACHE
                    ) {
                        scan_bound = x.end();
                    } else {
                        break;
                    }
                }
            }
            // every normal exit of the chain must carry an identical copy
        // (the compiler sinks the merge return into ALL of them). A
        // clause whose body merely ENDS in a matching return with
        // another exit falling through to the real tail is a genuine
        // source return (code 3.10 runsource Case-1 `return False` vs
        // the final `return False`)
        {
            let run_at = |idx: usize| -> Option<Vec<(u8, u32)>> {
                if !matches!(
                    self.instrs.get(idx).map(|x| x.op),
                    Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
                ) {
                    return None;
                }
                let mut bb = idx;
                let mut hh = 0;
                while bb > 0 && hh < 8 {
                    let p = &self.instrs[bb - 1];
                    if is_pad(p)
                        || matches!(
                            p.op,
                            Op::LOAD_FAST
                                | Op::LOAD_NAME
                                | Op::LOAD_GLOBAL
                                | Op::LOAD_DEREF
                                | Op::LOAD_CONST
                                | Op::LOAD_ATTR
                                | Op::LOAD_METHOD
                        )
                    {
                        bb -= 1;
                        hh += 1;
                        continue;
                    }
                    break;
                }
                Some(
                    self.instrs[bb..=idx]
                        .iter()
                        .filter(|x| !is_pad(x))
                        .map(norm)
                        .collect(),
                )
            };
            let mut exits = 0usize;
            let mut copies = 0usize;
            if let Some(&hi) = self.idx_of.get(&l) {
                // the body-end copy sits immediately before the chain
                // head (at_body_end branch) — count it too
                let wstart = hi.saturating_sub(6);
                for k in wstart..hi {
                    if matches!(
                        self.instrs[k].op,
                        Op::RETURN_VALUE | Op::RETURN_CONST
                    ) && run_at(k).as_ref() == Some(&run_a)
                    {
                        copies += 1;
                    }
                }
                for k in hi..self.instrs.len() {
                    let x = &self.instrs[k];
                    if x.offset >= scan_bound {
                        break;
                    }
                    let is_exit_jump = match x.op {
                        Op::JUMP_FORWARD | Op::JUMP => !x.is_backward,
                        Op::JUMP_ABSOLUTE => false,
                        _ => false,
                    };
                    if is_exit_jump
                        && x.target.map_or(false, |t| t >= scan_bound)
                    {
                        exits += 1;
                    }
                    if matches!(
                        x.op,
                        Op::RETURN_VALUE | Op::RETURN_CONST
                    ) && run_at(k).as_ref() == Some(&run_a)
                    {
                        copies += 1;
                    }
                }
            }
            // this return + any body-end copy are the copies; a
            // fall-through exit (no jump) with no copy disqualifies —
            // UNLESS the clause is EMPTY (`pass`) and the chain carries
            // an ELSE region: then the success path flows into the else
            // (no body-end copy exists) and the clause-exit copy is the
            // ONLY sunk tail (_osx_support 3.10 _get_system_version
            // `try: open(...) except OSError: pass else: <body>` + tail
            // `return _SYSTEM_VERSION`: copies=1, exits=0 — the empty
            // pass clause's exit carried the sunk tail and the else arm
            // flattened). A clause with a GENUINE statement (code 3.10
            // runsource `except: self.showsyntaxerror(...); return
            // False` — a CALL before the return) is a real source-level
            // return that happens to mirror the tail; it must NOT drop.
            let has_else_region = self
                .legacy_try
                .as_ref()
                .map_or(false, |l| {
                    l.else_start.map_or(false, |es| es > l.handler_start)
                });
            // clause-empty test: between the handler head and this
            // return, only exception-matching / stack-cleanup / the sunk
            // value-load may appear. Any CALL, STORE, BUILD (beyond the
            // match tuple), or control flow marks a genuine clause body.
            let clause_empty = self
                .idx_of
                .get(&l)
                .zip(self.idx_of.get(&ret_offset))
                .map_or(false, |(&hi2, &ri2)| {
                    !self.instrs[hi2..ri2].iter().any(|x| {
                        !matches!(
                            x.op,
                            Op::NOP
                                | Op::NOT_TAKEN
                                | Op::CACHE
                                | Op::EXTENDED_ARG
                                | Op::DUP_TOP
                                | Op::POP_TOP
                                | Op::POP_EXCEPT
                                | Op::JUMP_IF_NOT_EXC_MATCH
                                | Op::RERAISE
                                | Op::BUILD_TUPLE
                                | Op::LOAD_FAST
                                | Op::LOAD_NAME
                                | Op::LOAD_GLOBAL
                                | Op::LOAD_DEREF
                                | Op::LOAD_CONST
                                | Op::LOAD_ATTR
                                | Op::LOAD_METHOD
                        )
                    })
                });
            if copies + exits != 2
                && !(has_else_region && clause_empty && copies + exits == 1)
            {
                return false;
            }
        }
        // stubs are allowed until the chain's terminating RERAISE run
            // has been seen; the first non-stub AFTER that is the resumed
            // mainline flow (cProfile 3.10: the else arm's LOAD parser
            // follows the chain's RERAISE stubs), while a non-stub BEFORE
            // it is more clause code (crypt's RAISE_VARARGS)
            let mut saw_reraise = false;
            for x in self.instrs[ri + 1..].iter().take(14) {
                match x.op {
                    Op::RERAISE => saw_reraise = true,
                    Op::END_FINALLY
                    | Op::POP_EXCEPT
                    | Op::POP_TOP
                    | Op::COPY
                    | Op::SWAP
                    | Op::LOAD_CONST
                    | Op::STORE_FAST
                    | Op::STORE_NAME
                    | Op::STORE_DEREF
                    | Op::DELETE_FAST
                    | Op::DELETE_NAME
                    | Op::DELETE_DEREF
                    | Op::NOP
                    | Op::NOT_TAKEN
                    | Op::CACHE
                    | Op::JUMP_FORWARD
                    | Op::JUMP => {}
                    _ => {
                        if !saw_reraise {
                            return false;
                        }
                        break;
                    }
                }
            }
        }
        true
    }

    fn sunk_tail_terminator(&self, ret_offset: usize, is_none_value: bool) -> bool {
        if !is_none_value
            || !self.version.at_least(3, 10)
            || self.code.is_generator()
            || self.code.is_async_generator()
        {
            return false;
        }
        let Some(l) = self.legacy_try.as_ref() else {
            return false;
        };
        if l.has_finally || ret_offset >= l.handler_start {
            return false;
        }
        // next meaningful instruction after this return must be the
        // handler head (a truly last statement is followed by code end)
        let mut k = match self.idx_of.get(&ret_offset) {
            Some(&i) => i + 1,
            None => return false,
        };
        while matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::NOP) | Some(Op::CACHE) | Some(Op::EXTENDED_ARG)
        ) {
            k += 1;
        }
        if self.instrs.get(k).map(|x| x.offset) != Some(l.handler_start) {
            return false;
        }
        // the sunk copy sits IMMEDIATELY after a handler's POP_EXCEPT
        // (POP_EXCEPT; LOAD None; RETURN) - a scan that wandered past
        // the chain's RERAISE would find the function's own implicit
        // tail return and misfire on genuine source-level `return` in
        // the try body (chunk.skip). An `except E as e` handler wraps
        // its body in an as-cleanup SETUP_FINALLY whose region also
        // holds the sunk pair - walk through it, bounded.
        let mut m = k;
        let mut steps = 0;
        while let Some(ins) = self.instrs.get(m) {
            steps += 1;
            if steps > 120 {
                break;
            }
            match ins.op {
                Op::POP_EXCEPT => {
                    let is_none_load = |k: usize| {
                        self.instrs.get(k).map(|x| {
                            x.op == Op::LOAD_CONST
                                && matches!(
                                    self.code.consts.get(x.arg as usize).map(|o| &**o),
                                    Some(PyObject::None)
                                )
                        }) == Some(true)
                    };
                    let mut j = m + 1;
                    loop {
                        while matches!(
                            self.instrs.get(j).map(|x| x.op),
                            Some(Op::NOP) | Some(Op::CACHE) | Some(Op::NOT_TAKEN)
                        ) {
                            j += 1;
                        }
                        // `except E as e` cleanup: LOAD None; STORE e;
                        // DELETE e sits between POP_EXCEPT and the sunk
                        // tail return - skip the run
                        if is_none_load(j)
                            && matches!(
                                self.instrs.get(j + 1).map(|x| x.op),
                                Some(Op::STORE_FAST)
                                    | Some(Op::STORE_NAME)
                                    | Some(Op::STORE_DEREF)
                            )
                            && matches!(
                                self.instrs.get(j + 2).map(|x| x.op),
                                Some(Op::DELETE_FAST)
                                    | Some(Op::DELETE_NAME)
                                    | Some(Op::DELETE_DEREF)
                            )
                        {
                            j += 3;
                            continue;
                        }
                        if is_none_load(j)
                            && matches!(
                                self.instrs.get(j + 1).map(|x| x.op),
                                Some(Op::RETURN_VALUE) | Some(Op::RETURN_CONST)
                            )
                        {
                            return true;
                        }
                        break;
                    }
                }
                // the chain's mismatch tail: nothing past it belongs to
                // the handler
                Op::RERAISE | Op::END_FINALLY => break,
                _ => {}
            }
            m += 1;
        }
        false
    }

    /// 3.12+ sunk break: `if c: break` where the loop exit is a single
    /// return compiles WITHOUT a break jump — the arm falls through into
    /// a sunk COPY of the exit return (NOP landing pad + mirrored value
    /// loads + RETURN). Rendering the copy literally loses sig fidelity
    /// (the source `break` regenerates pad+copy on recompile;
    /// _compression 3.12 seek). When this return sits alone in an If arm
    /// inside a loop and its instruction run mirrors the run at the
    /// loop's exit, it is the sunk copy: emit Break instead.
    fn is_sunk_break_copy(&self) -> bool {
        if !self.version.at_least(3, 12) || self.legacy_handler.is_some() {
            return false;
        }
        let Some(top) = self.blocks.last() else {
            return false;
        };
        if !matches!(top.kind, BlockType::If) || !top.stmts.is_empty() {
            return false;
        }
        let Some(li) = self
            .blocks
            .iter()
            .rposition(|b| matches!(b.kind, BlockType::While | BlockType::For))
        else {
            return false;
        };
        if li + 1 != self.blocks.len() - 1 {
            // the If must sit directly inside the loop
            return false;
        }
        let exit = match self.loop_exit_offset(&self.blocks[li]) {
            Some(e) => e,
            None => return false,
        };
        // this return's run: walk back over value loads to the arm's
        // first non-padding instruction
        let Some(&ri) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        let arm_start = top.start;
        let mut b = ri;
        while b > 0 {
            let p = &self.instrs[b - 1];
            if p.offset < arm_start {
                break;
            }
            if matches!(p.op, Op::RETURN_VALUE | Op::RETURN_CONST) {
                break;
            }
            b -= 1;
        }
        // the sunk copy sits on a NOP landing pad: the arm's leading
        // instructions up to the value run must contain at least one
        // pad. A genuine mid-loop `if c: return -1` starts its run at
        // the arm's first instruction (_markupbase 3.13
        // _parse_doctype_subset mirrored the function-tail `return -1`
        // and lost a source-level return)
        if !self.instrs[b..ri].iter().any(|x| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE)
        }) && self.instrs.get(b).map_or(true, |x| x.offset == arm_start)
        {
            return false;
        }
        let norm = |x: &crate::bytecode::Instruction| (x.op as u8, x.arg);
        let is_pad = |x: &crate::bytecode::Instruction| {
            matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
        };
        let run_a: Vec<(u8, u32)> = self.instrs[b..=ri]
            .iter()
            .filter(|x| !is_pad(x))
            .map(norm)
            .collect();
        if run_a.is_empty()
            || !matches!(
                run_a.last().map(|t| t.0),
                Some(op) if op == Op::RETURN_VALUE as u8
                    || op == Op::RETURN_CONST as u8
            )
        {
            return false;
        }
        let Some(&ei) = self.idx_of.get(&exit) else {
            return false;
        };
        let n = run_a.len();
        let run_b: Vec<(u8, u32)> = self.instrs[ei..]
            .iter()
            .filter(|x| !is_pad(x))
            .take(n)
            .map(norm)
            .collect();
        if run_b.len() != n || run_a != run_b {
            return false;
        }
        // the mirrored exit run must TERMINATE the code object: the sunk
        // copy of a break replaces the whole post-loop tail. A mirror
        // found mid-function is an accidental match on a repeated tiny
        // return run (_markupbase 3.13 `if j == -1: return -1` inside a
        // `while 1:` matched a later `return -1` and rendered break)
        self.instrs[ei + n..].iter().all(is_pad)
    }

    fn emit_return(&mut self, e: Option<ExprRef>) {
        // 3.10 sunk tail terminator: drop both implicit copies (this
        // arm) and let the chain fold at its RERAISE
        let is_none_value = match &e {
            None => true,
            Some(v) => matches!(&**v, Expr::Const(o) if matches!(&**o, PyObject::None)),
        };
        if self.legacy_handler.is_none()
            && self.sunk_tail_terminator(self.cur_offset, is_none_value)
        {
            return;
        }
        // 3.10 value-return sunk copy of the function's final return
        // (try body end / handler exit): drop it — the merge return
        // renders from the main flow (cProfile 3.10 main)
        if !is_none_value && self.sunk_value_return_mirror(self.cur_offset) {
            // record the fold marker ONLY when a legacy chain flush
            // will consume it to rebuild the sibling else arm (the
            // batch-187 wait() shape). With no chain record the drop
            // stands alone and a dangling marker would misfire on the
            // next unrelated If close — _osx_support 3.10
            // _get_system_version's enclosing `if _SYSTEM_VERSION is
            // None:` guard was rebuilt into a phantom else arm
            if self.legacy_try.is_some() || !self.legacy_nest.is_empty() {
                self.sunk_return_fold_at = Some(self.cur_offset);
            }
            return;
        }
        // 3.10 fully-sunk tail: a nested chain parsed INSIDE the outer
        // chain's inline-finally copy region carries the function-tail
        // return sunk onto its clause-exit path
        // (`POP_EXCEPT; LOAD v; RETURN` where the source clause is
        // `pass`). The real tail return renders from the success-path
        // copy; this duplicate must drop. Discriminator: the mirrored
        // nested clause in the OUTER out-of-line handler copy carries
        // NO matching return (it re-raises instead) — a source-level
        // `return v` inside a finally body would appear in BOTH copies
        // (_bootsubprocess 3.10 check_output `except OSError: pass`
        // rendered `return stdout`).
        if !is_none_value
            && self.version.at_least(3, 10)
            && !self.version.at_least(3, 11)
            && self.legacy_handler.is_some()
        {
            let outer = self.legacy_nest.iter().find_map(|n| {
                n.outer_try.as_ref().filter(|o| {
                    o.has_finally
                        && o.else_start.map_or(false, |es| {
                            self.cur_offset >= es
                                && self.cur_offset < o.handler_start
                        })
                })
            });
            if let Some(o) = outer {
                let is_pad = |x: &crate::bytecode::Instruction| {
                    matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
                };
                let is_load = |op: Op| {
                    matches!(
                        op,
                        Op::LOAD_FAST
                            | Op::LOAD_NAME
                            | Op::LOAD_GLOBAL
                            | Op::LOAD_DEREF
                            | Op::LOAD_CONST
                            | Op::LOAD_ATTR
                            | Op::LOAD_METHOD
                    )
                };
                let run_of = |ri: usize| -> Option<Vec<(u8, u32)>> {
                    let mut b = ri;
                    let mut hops = 0;
                    while b > 0 && hops < 8 {
                        let p = &self.instrs[b - 1];
                        if is_pad(p) || is_load(p.op) {
                            b -= 1;
                            hops += 1;
                            continue;
                        }
                        break;
                    }
                    let run: Vec<(u8, u32)> = self.instrs[b..=ri]
                        .iter()
                        .filter(|x| !is_pad(x))
                        .map(|x| (x.op as u8, x.arg))
                        .collect();
                    (run.len() >= 2
                        && matches!(run.last().map(|t| t.0), Some(op) if op == Op::RETURN_VALUE as u8))
                    .then_some(run)
                };
                let mirrored_in_handler = self
                    .idx_of
                    .get(&self.cur_offset)
                    .zip(self.idx_of.get(&o.handler_start))
                    .map_or(false, |(&ri, &hi)| {
                        let run_a = match run_of(ri) {
                            Some(r) => r,
                            None => return false,
                        };
                        let hend = self.chain_extent(o.handler_start);
                        (hi..self.instrs.len())
                            .take_while(|&k| self.instrs[k].offset < hend)
                            .any(|k| {
                                matches!(
                                    self.instrs[k].op,
                                    Op::RETURN_VALUE | Op::RETURN_CONST
                                ) && run_of(k).as_ref() == Some(&run_a)
                            })
                    });
                if !mirrored_in_handler {
                    return;
                }
            }
        }
        // 3.8-3.10 multi-exit inline finally copies: every path out of
        // the copy region ends in a sunk `LOAD None; RETURN` (copies of
        // the implicit function tail). Copies PAST the chain's recorded
        // else_stop (the inline_end scan stopped at the FIRST sunk
        // return) but before the handler are duplicates of exits of a
        // branching finally body — rendering them emits stray `return`s
        // ahead of the flushed Try (cmd 3.10 cmdloop `finally: {if A:
        // if B: try/except}` — the if-false exits each carry their own
        // tail copy)
        if is_none_value
            && self.legacy_handler.is_none()
            && !self.version.at_least(3, 11)
            && self.legacy_nest.is_empty()
            && self
                .legacy_try
                .as_ref()
                .map_or(false, |l| {
                    l.has_finally
                        && l.else_start.is_some()
                        && self.cur_offset > l.else_stop
                        && self.cur_offset < l.handler_start
                })
        {
            // this is the inline copy's last sunk tail return before the
            // exception-time handler copy: the handler region is pure
            // duplication (3.8-3.10 finally copies) — never walk it (cmd
            // 3.10 cmdloop rendered the handler copy as a duplicate
            // `finally` body). The chain flushes at the walk-end
            // teardown with its finalbody already collected.
            let is_last_tail = self
                .legacy_try
                .as_ref()
                .map_or(false, |l| {
                    self.instrs
                        .iter()
                        .skip_while(|x| x.offset <= self.cur_offset)
                        .take_while(|x| x.offset < l.handler_start)
                        .all(|x| {
                            matches!(
                                x.op,
                                Op::LOAD_CONST
                                    | Op::RETURN_VALUE
                                    | Op::RETURN_CONST
                                    | Op::NOP
                                    | Op::NOT_TAKEN
                                    | Op::CACHE
                                    | Op::EXTENDED_ARG
                            )
                        })
                });
            if is_last_tail {
                self.skip_until = Some(usize::MAX);
            }
            return;
        }
        // <=3.10: the function-tail `LOAD None; RETURN` epilogue reached
        // by a nested try's body-end jump that flew over the handler
        // chains (parse_skipped_nested_chain territory): a legacy
        // handler is still open collecting, so emitting would leak a
        // bare `return` into the handler body (audiodev 2.7 AudioDev:
        // the tail landed after the nested Try inside
        // `except ImportError:`). Only the true epilogue qualifies —
        // from here to the code end nothing but terminators and pads,
        // so an except body's own final `return` (chain material or
        // real statements follow it) is untouched
        if is_none_value
            && !self.version.at_least(3, 11)
            && self.legacy_nest_depth == 0
            && self.code.name != "<module>"
            && self
                .skipped_chain_landing
                .map_or(false, |l| self.cur_offset >= l)
            && self.blocks.iter().all(|b| matches!(b.kind, BlockType::Main))
            && (self.legacy_handler.is_some()
                || self.legacy_nest.iter().any(|n| n.outer_handler.is_some()))
            && self
                .idx_of
                .get(&self.cur_offset)
                .map_or(false, |&ci| {
                    self.instrs[ci..].iter().all(|x| {
                        matches!(
                            x.op,
                            Op::RETURN_VALUE
                                | Op::RETURN_CONST
                                | Op::LOAD_CONST
                                | Op::JUMP_ABSOLUTE
                                | Op::JUMP_FORWARD
                                | Op::JUMP
                                | Op::END_FINALLY
                                | Op::POP_BLOCK
                                | Op::NOP
                        )
                    })
                })
        {
            return;
        }
        // 3.11+ narrowed protected range: a try body's tail `return None`
        // sits JUST PAST body_end (RETURN cannot raise, so the table
        // excludes it) and gets walked into the enclosing branch as a
        // stray. When this return is exactly that tail — it starts right
        // at the emitted Try's body end and the handler chain follows it
        // immediately — route it into the try body and skip over the
        // chain (chunk.skip 3.11). A GAP between the body end and the
        // return means the flow continued past the try (aifc __init__:
        // then-arm terminating return after the try) — leave it to the
        // branch-tail strip in postprocess.
        if self.version.at_least(3, 11)
            && self.legacy_handler.is_none()
            && self.pending_try_ctx.is_none()
            // module level has its own synthetic-return handling below
            // (break-in-loop / branch-tail marking) — never reroute a
            // module-level return into a try body ('return' outside
            // function)
            && self.code.name != "<module>"
        {
            if let Some(top) = self.blocks.last() {
                // function level (Main) admitted for VALUE returns:
                // codecs open 3.11 `try: ...; return srw except: ...`
                // — the try flushed at body_end with the narrowed
                // value loads + RETURN just past it
                let is_branch =
                    matches!(top.kind, BlockType::If | BlockType::Else)
                        || (matches!(top.kind, BlockType::Main)
                            && !is_none_value);
                let end_at = top.end;
                if is_branch && self.cur_offset < end_at {
                    if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                        // walk back over the value load(s) of this return
                        let mut b = ci;
                        let mut hops = 0;
                        while b > 0 && hops < 8 {
                            let p = &self.instrs[b - 1];
                            if matches!(
                                p.op,
                                Op::LOAD_CONST | Op::NOP | Op::NOT_TAKEN | Op::CACHE
                            ) || (!is_none_value
                                && matches!(
                                    p.op,
                                    Op::LOAD_FAST
                                        | Op::LOAD_NAME
                                        | Op::LOAD_GLOBAL
                                        | Op::LOAD_DEREF
                                        | Op::LOAD_ATTR
                                        | Op::LOAD_METHOD
                                        | Op::LOAD_FAST_LOAD_FAST
                                        | Op::LOAD_FAST_BORROW
                                        | Op::LOAD_SMALL_INT
                                ))
                            {
                                b -= 1;
                                hops += 1;
                                continue;
                            }
                            break;
                        }
                        let back = self.instrs.get(b).map(|x| x.offset);
                        // forward: this return, then the chain head, then
                        // only chain material up to the branch end
                        let mut chain_head = None;
                        let mut k = ci + 1;
                        while k < self.instrs.len() {
                            let x = &self.instrs[k];
                            if x.offset >= end_at {
                                break;
                            }
                            match x.op {
                                Op::RETURN_VALUE | Op::RETURN_CONST
                                | Op::NOP | Op::NOT_TAKEN | Op::CACHE => {
                                    k += 1;
                                }
                                Op::PUSH_EXC_INFO => {
                                    chain_head = Some(x.offset);
                                    break;
                                }
                                _ => {
                                    k = usize::MAX;
                                    break;
                                }
                            }
                        }
                        if let (Some(back), Some(h)) = (back, chain_head) {
                            let targeted = self
                                .instrs
                                .iter()
                                .skip(b + 1)
                                .take_while(|x| x.offset < h)
                                .any(|x| self.targets.contains(&x.offset));
                            // the return's value loads must begin right
                            // at the emitted try's body end (only padding
                            // between): the narrowed-range tail shape.
                            // aifc's then-arm return sits past the body's
                            // final POP_TOP and must stay branch-level.
                            // body_end may point one value-load PAST the
                            // back-walk start when the flush position was
                            // the return itself (codecs open 3.11: ltb=
                            // 180 = end of LOAD srw@178 = back) — allow
                            // be in [back, back+16] too; everything
                            // between back and the return stays
                            // value-load material either way
                            let adjacent =
                                self.last_try_body_end.map_or(false, |be| {
                                    if is_none_value {
                                        // strict form (chunk.skip): the
                                        // LOAD None starts AT/after the
                                        // body end with pads between —
                                        // a GAP means the flow continued
                                        // past the try (aifc)
                                        return be <= back
                                            && back - be <= 16
                                            && !self.instrs.iter().any(|x| {
                                                x.offset >= be
                                                    && x.offset < back
                                                    && !matches!(
                                                        x.op,
                                                        Op::NOP
                                                            | Op::NOT_TAKEN
                                                            | Op::CACHE
                                                    )
                                            });
                                    }
                                    let (lo, hi) = if be <= back {
                                        (be, back)
                                    } else if be <= back + 16 {
                                        (back, be)
                                    } else {
                                        return false;
                                    };
                                    hi - lo <= 16
                                        && !self.instrs.iter().any(|x| {
                                            x.offset >= lo
                                                && x.offset < hi
                                                && !matches!(
                                                    x.op,
                                                    Op::NOP
                                                        | Op::NOT_TAKEN
                                                        | Op::CACHE
                                                )
                                                && !matches!(
                                                    x.op,
                                                    Op::LOAD_FAST
                                                        | Op::LOAD_NAME
                                                        | Op::LOAD_GLOBAL
                                                        | Op::LOAD_DEREF
                                                        | Op::LOAD_CONST
                                                        | Op::LOAD_ATTR
                                                        | Op::LOAD_METHOD
                                                        | Op::LOAD_FAST_LOAD_FAST
                                                        | Op::LOAD_FAST_BORROW
                                                        | Op::LOAD_SMALL_INT
                                                )
                                        })
                                });
                            // a chain whose last clause is a bare `except:`
                            // ending in RERAISE 0 always re-raises: the try
                            // cannot fall through, so this return TERMINATES
                            // the branch after the try (aifc __init__ shape,
                            // which recompiles to the original only with the
                            // return at branch level) — it is not the tail
                            // copy of a fall-through try (chunk.skip)
                            let ext = self.chain_extent(h);
                            let chain_always_raises = self
                                .instrs
                                .iter()
                                .rev()
                                .find(|x| {
                                    x.offset >= h && x.offset < ext
                                        && !matches!(
                                            x.op,
                                            Op::NOP
                                                | Op::NOT_TAKEN
                                                | Op::CACHE
                                                | Op::COPY
                                                | Op::SWAP
                                                | Op::POP_EXCEPT
                                                | Op::RERAISE
                                        )
                                })
                                .map_or(false, |x| {
                                    x.op == Op::RAISE_VARARGS && x.arg == 0
                                });
                            // an always-raising chain vetoes recovery
                            // ONLY when the protected body itself
                            // terminates (aifc __init__: initfp always
                            // raises — the return is the branch's, not
                            // the body's). A normally-ending body falls
                            // through into its own tail return even
                            // when every exception path re-raises
                            // (codecs open 3.11 `try: ...; return srw
                            // except: file.close(); raise`)
                            let body_terminal = self
                                .last_try_body_end
                                .and_then(|be| {
                                    self.instrs
                                        .iter()
                                        .rev()
                                        .find(|x| {
                                            x.offset < be
                                                && !matches!(
                                                    x.op,
                                                    Op::NOP
                                                        | Op::NOT_TAKEN
                                                        | Op::CACHE
                                                        | Op::POP_TOP
                                                )
                                        })
                                        .map(|x| {
                                            matches!(
                                                x.op,
                                                Op::RAISE_VARARGS
                                                    | Op::RETURN_VALUE
                                                    | Op::RETURN_CONST
                                                    | Op::RERAISE
                                            )
                                        })
                                })
                                .unwrap_or(false);
                            // line-table discriminator for VALUE
                            // returns: the return's source line must
                            // precede the handler clause's first line —
                            // a try body's tail return is always above
                            // its `except`. copyreg _reduce_ex 3.13:
                            // the post-try if/else returns (line 92/94)
                            // sit lexically BEFORE the out-of-line
                            // chain of the EARLIER try (except line 75)
                            // — sinking moved them; folding them into
                            // the body is wrong
                            let handler_line = self
                                .instrs
                                .iter()
                                .filter(|x| x.offset > h)
                                .find_map(|x| x.line);
                            let ret_line = self
                                .idx_of
                                .get(&self.cur_offset)
                                .and_then(|&ci2| self.instrs[ci2].line);
                            let line_ok = is_none_value
                                || match (ret_line, handler_line) {
                                    (Some(r), Some(hl)) => r < hl,
                                    _ => true,
                                };
                            if std::env::var("PYCDC_REC_DBG").is_ok() {
                                eprintln!("REC off={} targeted={} adjacent={} always={} body_term={} line_ok={} h={} end_at={} ltb={:?}", self.cur_offset, targeted, adjacent, chain_always_raises, body_terminal, line_ok, h, end_at, self.last_try_body_end);
                            }
                            if !targeted
                                && adjacent
                                && (!chain_always_raises
                                    || (!is_none_value && !body_terminal))
                                && line_ok
                                && h < end_at
                            {
                                let ext = self.chain_extent(h);
                                let value = match &e {
                                    Some(v) => match &**v {
                                        Expr::Const(o)
                                            if matches!(&**o, PyObject::None) =>
                                        {
                                            None
                                        }
                                        _ => Some(v.clone()),
                                    },
                                    None => None,
                                };
                                let stmt = Stmt::Return(value);
                                // the Try block already emitted at the
                                // body end (close_blocks_at ran before
                                // this instruction): it is the container's
                                // last statement — append into its body
                                let pushed =
                                    if let Some(top) = self.blocks.last_mut() {
                                        if let Some(Stmt::Try {
                                            body,
                                            finalbody,
                                            ..
                                        }) = top.stmts.last_mut()
                                        {
                                            if finalbody.is_empty() {
                                                body.push(stmt);
                                                true
                                            } else {
                                                false
                                            }
                                        } else {
                                            false
                                        }
                                    } else {
                                        false
                                    };
                                if pushed {
                                    if self.skip_until.map_or(true, |s| s < ext) {
                                                                                self.skip_until = Some(ext);
                                    }
                                    return;
                                }
                            }
                        }
                    }
                }
            }
        }
        if std::env::var("PYCDC_REC_DBG").is_ok() && self.code.name == "open" {
            eprintln!("REC2 off={} ptc={:?} ptb={:?} top={:?} topstmts={}", self.cur_offset,
                self.pending_try_ctx.as_ref().map(|t| (t.start, t.body_end, t.region_end, t.except_handler)),
                self.pending_try_body.iter().map(|b| b.len()).collect::<Vec<_>>(),
                self.blocks.last().map(|b| format!("{:?}", b.kind)),
                self.blocks.last().map(|b| b.stmts.len()).unwrap_or(999));
        }
        // 3.11+: the exception-table region often ends exactly at the
        // RETURN that closes the try body (only the value computation is
        // protected). If the pending body is empty and the value was
        // computed inside the region, this return IS the try body — flush
        // the chain first so the return lands inside it.
        // The try may sit at function top (blocks == [Main]) or be nested
        // in guard If/Else blocks (`if cond: try: return X except E: ..`)
        // — accept any stack of If/Else over the Main base. Restricting to
        // Main-only dropped the whole try for an if-nested `try: return X`
        // (t_b: `except ValueError: self.log()` lost; annotationlib 3.14
        // evaluate's `if isinstance(cell, CellType): try: return
        // cell.cell_contents except ValueError: pass`). Loops/Try/With
        // tops still take their own paths.
        let main_or_guards = {
            let mut ok = false;
            for (bi, b) in self.blocks.iter().enumerate() {
                if bi == 0 {
                    if b.kind != BlockType::Main {
                        ok = false;
                        break;
                    }
                    ok = true;
                } else if !matches!(b.kind, BlockType::If | BlockType::Else) {
                    ok = false;
                    break;
                }
            }
            ok
        };
        // main-only is the original (always-fire) shape; the nested-guard
        // relaxation also fires for an if-nested `try: return X except E:
        // ..`. For a TERMINATING handler (`except E: raise ..` / return) the
        // if-branch always terminates and the post-if continuation is an
        // INLINE SIBLING reached via the guard's false edge, sitting
        // BETWEEN the body return and the out-of-line chain — so the
        // skip-to-chain-extent below must NOT run (it would swallow the
        // sibling); the walk processes the sibling and the chain-head
        // skipper eats the already-parsed out-of-line chain (base64 3.12
        // _bytes_from_decode_data `if isinstance(s,str): try: return
        // s.encode(..) except UnicodeEncodeError: raise ValueError(..)` +
        // sibling `if isinstance(s,bytes_types)` + memoryview try). A
        // fall-through handler (pass / non-terminating body) flows to the
        // continuation through the chain, so the skip is right there
        // (t_b self.log(), min_trypass / annotationlib evaluate `except
        // ValueError: pass`). A RETURN in the span is the fall-through
        // continuation inlined after a non-terminating clause, and the
        // chain's trailing RERAISE is no-match cleanup — only a clause-level
        // `raise <expr>` (RAISE_VARARGS arg>0) marks termination.
        let main_only = self.blocks.len() == 1
            && matches!(self.blocks.last().map(|b| b.kind), Some(BlockType::Main));
        let nested_handler_terminates = self
            .pending_try_ctx
            .as_ref()
            .and_then(|tc| tc.except_handler)
            .map_or(false, |h| {
                let ext = self.chain_extent(h);
                self.instrs.iter().any(|x| {
                    x.offset >= h
                        && x.offset < ext
                        && x.op == Op::RAISE_VARARGS
                        && x.arg > 0
                })
            });
        if self.version.at_least(3, 11)
            && self.legacy_handler.is_none()
            && main_or_guards
        {
            let at_region_edge = self
                .pending_try_ctx
                .as_ref()
                .map_or(false, |tc| {
                    self.cur_offset >= tc.start && self.cur_offset <= tc.region_end + 8
                });
            if at_region_edge
                && self
                    .pending_try_body
                    .last()
                    .map_or(false, |b| b.is_empty())
                && !(self.code.name == "<module>"
                    && match &e {
                        None => true,
                        Some(v) => matches!(&**v, Expr::Const(o) if matches!(&**o, PyObject::None)),
                    })
            {
                if let Some(tc) = self.pending_try_ctx.take() {
                    let at = self.cur_offset;
                    let value = match e {
                        Some(v) => match &*v {
                            Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                            _ => Some(v),
                        },
                        None => None,
                    };
                    if let Some(body) = self.pending_try_body.last_mut() {
                        body.push(Stmt::Return(value));
                    }
                    let exc_h = tc.except_handler;
                    self.emit_try_tail(tc, at);
                    // the chain lies AHEAD with machinery in between
                    // (copy 3.12 _deepcopy_tuple: the listcomp unwind
                    // stub [76,86) separates the body return from the
                    // except chain): the walk would enter the stub and
                    // the handler-zone rule ends the function. Hop the
                    // whole chain region to its mainline resume — what
                    // the chain-head skipper would compute once the
                    // walk reaches the head.
                    // for a nested terminating handler the continuation is
                    // an INLINE sibling between the body return and the
                    // out-of-line chain — do NOT skip to the chain extent
                    // (that swallows the sibling); let the walk run the
                    // sibling and the chain-head skipper eat the parsed
                    // chain when reached.
                    if self.skip_until.is_none()
                        && !(nested_handler_terminates && !main_only)
                    {
                        if let Some(h) = exc_h {
                            if h > self.cur_offset {
                                let ext = self.chain_extent(h);
                                let mut resume = ext;
                                let mut probe = ext;
                                for _ in 0..4 {
                                    let hop = self
                                        .idx_of
                                        .get(&probe)
                                        .and_then(|&xi| self.instrs.get(xi))
                                        .and_then(|x| {
                                            if matches!(
                                                x.op,
                                                Op::JUMP_FORWARD | Op::JUMP
                                            ) && !x.is_backward
                                            {
                                                x.target
                                                    .filter(|t| *t > x.offset)
                                            } else {
                                                None
                                            }
                                        });
                                    match hop {
                                        Some(t) => {
                                            resume = t;
                                            probe = t;
                                        }
                                        None => break,
                                    }
                                }
                                if resume > self.cur_offset {
                                    self.skip_until = Some(resume);
                                }
                            }
                        }
                    }
                    return;
                }
            }
        }
        // 3.8-3.10 function-tail try/finally: the inline finally body ends
        // with LOAD None; RETURN — the epilogue return. Flush the collected
        // try/finally first (the walk ends here), drop the return, and skip
        // the out-of-line finally copy that follows.
        let epilogue_none = match &e {
            None => true,
            Some(v) => matches!(&**v, Expr::Const(o) if matches!(&**o, PyObject::None)),
        };
        if epilogue_none
            && self.legacy_handler.is_none()
            && self.legacy_try.as_ref().map_or(false, |l| {
                l.has_finally
                    && l.else_start
                        .map_or(false, |es| self.cur_offset >= es && self.cur_offset <= l.else_stop)
            })
        {
            let mut l = self.legacy_try.take().unwrap();
            self.flush_pending_stores();
            self.fold_stashed_inner_chain(&mut l);
            self.restore_legacy_nest();
            self.push_legacy_try(l);
                        self.skip_until = Some(usize::MAX);
            return;
        }
        // 3.8-3.10 function-tail try/finally whose inline finally body
        // ends with a VALUE return (`...; finally: ...; return v`): the
        // success-path statements were redirected into finalbody; flush
        // the try so it lands BEFORE the return, skip the out-of-line
        // finally copy, and emit the return after it.
        // 3.8-3.10: `try: return v; except ...` — the success-path return
        // sits between the body's POP_BLOCK and the handler chain; it is
        // the try body's last statement (its value load was protected).
        // Route it into the collected body, not past the try.
        // a nested try INSIDE a stashed outer chain's inline-finally
        // region: this return-none is the finally copy's sunk function
        // tail, not the nested body's `return v` — leave it to
        // emit_return's sunk_tail_terminator swallow (cmd 3.10 cmdloop
        // `finally: {if A: if B: try/except ImportError: pass}` — the
        // fold rendered a spurious `return` inside the nested try and
        // derailed the whole chain)
        let in_stashed_finally_region = self.legacy_nest.iter().any(|n| {
            n.outer_try
                .as_ref()
                .map_or(false, |o| {
                    o.has_finally
                        && o.else_start.map_or(false, |es| {
                            self.cur_offset >= es && self.cur_offset <= o.else_stop
                        })
                })
        });
        if self.legacy_handler.is_none()
            && !in_stashed_finally_region
            && self.cur_offset
                < self.legacy_try.as_ref().map(|l| l.handler_start).unwrap_or(0)
            && self.legacy_try.as_ref().map_or(false, |l| {
                !l.has_finally && l.handlers.is_empty() && l.orelse.is_empty()
            })
        {
            // batch-111 veto: a TAIL-position try whose post-try return
            // was sunk into BOTH exits (copyreg 3.10 _slotnames) — the
            // handler opens with a mirrored copy. Routing this return
            // into the body renders it INSIDE the try; keep it at
            // function level (push_legacy_try inserts the Try before
            // trailing returns) and skip the handler-side copy when the
            // chain walk reaches it
            let mirror = self
                .legacy_try
                .as_ref()
                .and_then(|l| self.legacy_sunk_pair_return(l, self.cur_offset));
            if let Some(ms) = mirror {
                let resume = self
                    .idx_of
                    .get(&ms)
                    .and_then(|&mi| {
                        let mut k = mi;
                        let mut hops = 0;
                        while k < self.instrs.len() && hops < 12 {
                            let x = &self.instrs[k];
                            if matches!(
                                x.op,
                                Op::RETURN_VALUE | Op::RETURN_CONST
                            ) {
                                return Some(x.end());
                            }
                            if matches!(
                                x.op,
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG
                            ) || matches!(
                                x.op,
                                Op::LOAD_FAST
                                    | Op::LOAD_NAME
                                    | Op::LOAD_GLOBAL
                                    | Op::LOAD_DEREF
                                    | Op::LOAD_CONST
                                    | Op::LOAD_ATTR
                                    | Op::LOAD_METHOD
                            ) {
                                k += 1;
                                hops += 1;
                                continue;
                            }
                            break;
                        }
                        None
                    })
                    .unwrap_or(usize::MAX);
                self.sunk_pair_drop = Some((ms, resume));
            } else {
                // the body-return routing requires the value to have
                // RIDDEN the stack over the body's POP_BLOCK (`try:
                // return v` computes v protected, then POP_BLOCK;
                // RETURN). When real value/call instructions sit
                // between that POP_BLOCK and this return, the
                // expression was evaluated AFTER the body closed —
                // the return is post-try code and must render AFTER
                // the Try (cmd 3.10 onecmd `try: func = getattr(...)
                // except AttributeError: return self.default(line)`
                // followed by `return func(arg)`: routing pulled the
                // call INSIDE the try, so an AttributeError raised by
                // func(arg) would wrongly hit the clause, and the
                // recompile moved the POP_BLOCK past the CALL)
                // narrow detector: an expression-EVALUATION op (call /
                // binary op) between the body's POP_BLOCK and this
                // return means the value was computed AFTER the body
                // closed. Protocol material that legitimately sits in
                // that window (as-cleanup LOAD None; STORE; DELETE,
                // CALL_FINALLY, finally-copy loads/stores, 3.11's
                // narrowed-region JUMP_BACKWARD glue) contains no such
                // op for a genuine `try: return v`.
                let value_ran_past_pop_block = {
                    // index of this return, for the protocol lookbehind
                    let ri = self.idx_of.get(&self.cur_offset).copied();
                    self.instrs
                    .iter()
                    .rev()
                    .skip_while(|x| x.offset >= self.cur_offset)
                    .take_while(|x| {
                        !matches!(
                            x.op,
                            Op::POP_BLOCK
                                | Op::RETURN_VALUE
                                | Op::RETURN_CONST
                                | Op::RERAISE
                                | Op::DUP_TOP
                                | Op::PUSH_EXC_INFO
                                | Op::SETUP_FINALLY
                                | Op::SETUP_EXCEPT
                        )
                    })
                    .any(|x| {
                        // the sync-with exit protocol (3.9/3.10:
                        // POP_BLOCK; LOAD None; DUP; DUP; CALL 3;
                        // POP_TOP; <value>; RETURN — codeop 3.10
                        // _maybe_compile's `return None` rides over
                        // it) is NOT value evaluation: a CALL whose
                        // two predecessors are DUP_TOP is __exit__
                        let is_with_exit_call = matches!(
                            x.op,
                            Op::CALL | Op::CALL_FUNCTION
                        ) && ri.map_or(false, |r| {
                            let xi = self.instrs.iter().position(|y| y.offset == x.offset);
                            xi.map_or(false, |k| {
                                k < r
                                    && matches!(
                                        self.instrs.get(k - 1).map(|y| y.op),
                                        Some(Op::DUP_TOP)
                                    )
                                    && matches!(
                                        self.instrs.get(k - 2).map(|y| y.op),
                                        Some(Op::DUP_TOP)
                                    )
                            })
                        });
                        !is_with_exit_call
                            && matches!(
                            x.op,
                            Op::CALL
                                | Op::CALL_FUNCTION
                                | Op::CALL_METHOD
                                | Op::CALL_FUNCTION_KW
                                | Op::CALL_FUNCTION_EX
                                | Op::CALL_FUNCTION_VAR
                                | Op::CALL_FUNCTION_VAR_KW
                                | Op::CALL_KW
                                | Op::BINARY_OP
                                | Op::BINARY_SUBSCR
                                | Op::BINARY_ADD
                                | Op::BINARY_SUBTRACT
                                | Op::BINARY_MULTIPLY
                                | Op::BINARY_TRUE_DIVIDE
                                | Op::BINARY_FLOOR_DIVIDE
                                | Op::BINARY_MODULO
                                | Op::BINARY_POWER
                                | Op::COMPARE_OP
                                | Op::BUILD_TUPLE
                                | Op::BUILD_LIST
                                | Op::BUILD_MAP
                                | Op::BUILD_SET
                                | Op::BUILD_STRING
                                | Op::LIST_EXTEND
                                | Op::SET_UPDATE
                                | Op::DICT_UPDATE
                                | Op::DICT_MERGE
                                | Op::FORMAT_VALUE
                                | Op::FORMAT_SIMPLE
                                | Op::FORMAT_WITH_SPEC
                            )
                    })
                };
                if !value_ran_past_pop_block {
                    let value = match e {
                        Some(v) => match &*v {
                            Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                            _ => Some(v),
                        },
                        None => None,
                    };
                    if let Some(l) = self.legacy_try.as_mut() {
                        l.body.push(Stmt::Return(value));
                    }
                    return;
                }
                // post-try return: do NOT route it into the body and do
                // NOT flush the unparsed chain here — push it now; the
                // chain folds at its own end and push_legacy_try /
                // the walk-end flush insert the Try BEFORE trailing
                // returns, restoring source order
            }
        }
        if self.legacy_handler.is_none()
            && self.legacy_try.as_ref().map_or(false, |l| {
                l.has_finally
                    && l.else_start
                        .map_or(false, |es| self.cur_offset >= es && self.cur_offset <= l.else_stop)
            })
        {
            // the chain's material end: first terminator at/after the
            // out-of-line handler head (its inline copies and the sunk
            // returns between this offset and the handler are pure
            // duplication)
            let resume = self
                .legacy_try
                .as_ref()
                .and_then(|l| self.idx_of.get(&l.handler_start))
                .and_then(|&hi| {
                    self.instrs[hi..]
                        .iter()
                        .find(|x| {
                            matches!(
                                x.op,
                                Op::RERAISE | Op::END_FINALLY | Op::JUMP_ABSOLUTE
                            )
                        })
                        .map(|x| x.end())
                });
            // a chain nested INSIDE a branch arm whose sibling flow
            // continues past the chain: skipping to the code end (the
            // function-tail behavior) would drop the rest of the
            // function (_bootsubprocess 3.10 wait: the child branch's
            // try/finally sunk return ended the walk and the parent
            // else arm + tail return vanished). Resume past the chain's
            // terminator instead, and when this sunk return mirrors the
            // function's real tail return (same value-load run), drop
            // it — the arm falls through to the tail like the source
            let past_flow = resume.map_or(false, |r| {
                self.blocks.iter().any(|b| {
                    b.kind != BlockType::Main && b.end >= r
                })
            });
            let tail_mir = {
                let is_pad = |x: &crate::bytecode::Instruction| {
                    matches!(x.op, Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG)
                };
                let is_load = |o: Op| {
                    matches!(
                        o,
                        Op::LOAD_FAST
                            | Op::LOAD_NAME
                            | Op::LOAD_GLOBAL
                            | Op::LOAD_DEREF
                            | Op::LOAD_CONST
                            | Op::LOAD_ATTR
                            | Op::LOAD_METHOD
                    )
                };
                let run_of = |ri: usize| -> Option<Vec<(u8, u32)>> {
                    let mut b = ri;
                    let mut hops = 0;
                    while b > 0 && hops < 8 {
                        let p = &self.instrs[b - 1];
                        if is_pad(p) || is_load(p.op) {
                            b -= 1;
                            hops += 1;
                            continue;
                        }
                        break;
                    }
                    let run: Vec<(u8, u32)> = self.instrs[b..=ri]
                        .iter()
                        .filter(|x| !is_pad(x))
                        .map(|x| (x.op as u8, x.arg))
                        .collect();
                    (run.len() >= 2
                        && matches!(run.last().map(|t| t.0), Some(op) if op == Op::RETURN_VALUE as u8))
                    .then_some(run)
                };
                resume
                    .and_then(|r| {
                        self.idx_of.get(&self.cur_offset).copied().and_then(|ci| {
                            self.instrs
                                .iter()
                                .rposition(|x| {
                                    matches!(x.op, Op::RETURN_VALUE | Op::RETURN_CONST)
                                        && x.offset >= r
                                })
                                .and_then(|ti| {
                                    let a = run_of(ci)?;
                                    let b = run_of(ti)?;
                                    Some(a == b)
                                })
                        })
                    })
                    .unwrap_or(false)
            };
            let mut l = self.legacy_try.take().unwrap();
            self.flush_pending_stores();
            self.fold_stashed_inner_chain(&mut l);
            self.restore_legacy_nest();
            self.push_legacy_try(l);
            if past_flow {
                self.skip_until = resume;
                if tail_mir {
                    // record the suppressed sunk return: the If close at
                    // the resume point rebuilds the sibling else arm from
                    // it (3.10 sunk-copy else rebuild)
                    self.sunk_return_fold_at = Some(self.cur_offset);
                    return;
                }
            } else {
                self.skip_until = Some(usize::MAX);
            }
            let value = match e {
                Some(v) => match &*v {
                    Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                    _ => Some(v),
                },
                None => None,
            };
            self.push_stmt(Stmt::Return(value));
            return;
        }
        let value = match e {
            Some(v) => match &*v {
                Expr::Const(o) if matches!(&**o, PyObject::None) => None,
                _ => Some(v),
            },
            None => None,
        };
        // module-level implicit `return None` is synthetic (3.12+ even emits
        // RETURN_CONST None at the end of every top-level branch)
        if value.is_none() && self.code.name == "<module>" {
            // a `break` inside a MODULE-level loop compiles to
            // LOAD None; RETURN (the loop exit IS the module return):
            // with a loop block still open this is a break, not the
            // synthetic end-of-module return
            if self
                .blocks
                .iter()
                .any(|b| matches!(b.kind, BlockType::While | BlockType::For))
            {
                self.push_stmt(Stmt::Break);
                self.close_inner_blocks_to_loop();
                return;
            }
            // When it terminates an if-branch, it replaces the classic
            // JUMP_FORWARD-over-else: mark the else region as running to
            // the end of the module stream.
            if let Some(top) = self.blocks.last_mut() {
                if matches!(top.kind, BlockType::If) && top.else_end.is_none() {
                    let code_end = self.instrs.last().map(|i| i.end()).unwrap_or(0);
                    top.else_end = Some(code_end);
                }
            }
            return;
        }
        // a bare `return None` falling through at a loop's EXIT while the
        // loop block is still open (3.11+ rotated while: the exit return
        // lands before the block end, which spans to the function-tail
        // return copy): it resumes the flow past the loop and is the
        // implicit terminator — close the loop and drop it. Genuine body
        // returns have real code between them and the block end, or are
        // the whole remaining body (`while c: return` keeps its return).
        if value.is_none() && self.legacy_handler.is_none() {
            if let Some(top) = self.blocks.last() {
                if matches!(top.kind, BlockType::While | BlockType::For)
                    && top.start < self.cur_offset
                    && self.cur_offset < top.end
                {
                    let end = top.end;
                    let mut tail_returns = 0;
                    let mut only_terms = true;
                    if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                        for x in &self.instrs[ci + 1..] {
                            // include the instruction AT the block end:
                            // for the rotated-while exit the function-tail
                            // return copy sits exactly there
                            if x.offset > end {
                                break;
                            }
                            match x.op {
                                Op::RETURN_VALUE | Op::RETURN_CONST => {
                                    tail_returns += 1;
                                }
                                Op::NOP | Op::NOT_TAKEN | Op::CACHE => {}
                                _ => {
                                    only_terms = false;
                                    break;
                                }
                            }
                        }
                    }
                    if only_terms && tail_returns >= 1 {
                        let at = self.cur_offset;
                        self.close_blocks_at(at);
                        return;
                    }
                }
            }
        }
        if self.is_sunk_break_copy() {
            self.push_stmt(Stmt::Break);
            return;
        }
        self.push_stmt(Stmt::Return(value));
    }

    fn apply_binary(&mut self, op_text: &str) {
        let rhs = self.pop_expr();
        let lhs = self.pop_expr();
        let op = binop_from_text(op_text);
        self.push(Rc::new(Expr::Binary { op, left: lhs, right: rhs }));
    }

    /// In-place operators: CPython emits DUP + load target + value +
    /// BINARY_OP(+arg>=13 in 3.11 BINARY_OP) + ROT + STORE. We detect the
    /// pending augmented store and emit AugAssign directly.
    fn apply_inplace(&mut self, op_text: &str, raw_arg: u32) {
        let _ = raw_arg;
        let rhs = self.pop_expr();
        let lhs = self.pop_expr();
        let op = binop_from_text(op_text);
        // Look ahead: next instructions should store back into lhs.
        let e: ExprRef = Rc::new(Expr::Binary {
            op,
            left: lhs.clone(),
            right: rhs,
        });
        // The augmented-assign store is recognized in emit_store via the
        // pending_aug flag when the target matches lhs.
        self.pending_aug = Some((lhs, op));
        self.push(e);
    }

    fn call_function_py(
        &mut self,
        argc: usize,
        names_tuple: Option<ExprRef>,
        is_method: bool,
    ) {
        // Python 2 / 3.0-3.5 CALL_FUNCTION: low byte = positional count,
        // high byte = keyword count. 3.6+ CALL_FUNCTION_KW pushes a names
        // tuple and argc counts positional + keyword together.
        let kw_names: Vec<Option<String>> = match &names_tuple {
            Some(e) => match &**e {
                Expr::Const(o) => match &**o {
                    PyObject::Tuple(items) => items
                        .iter()
                        .map(|it| match &**it {
                            PyObject::Str(s) => Some(s.clone()),
                            _ => None,
                        })
                        .collect(),
                    _ => Vec::new(),
                },
                _ => Vec::new(),
            },
            None => Vec::new(),
        };
        let (npos, nkw) = if names_tuple.is_some() {
            (argc.saturating_sub(kw_names.len()), kw_names.len())
        } else if self.version.at_least(3, 6) {
            (argc, 0)
        } else {
            ((argc & 0xFF) as usize, ((argc >> 8) & 0xFF) as usize)
        };
        let args;
        let mut keywords = Vec::new();
        if names_tuple.is_none() && nkw > 0 && !self.version.at_least(3, 6) {
            // pre-3.6 kwargs sit on top as (name_const, value) pairs
            for _ in 0..nkw {
                let v = self.pop_expr();
                let ke = self.pop_expr();
                let k = match &*ke {
                    Expr::Const(o) => match &**o {
                        PyObject::Str(s) => Some(s.clone()),
                        PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                        _ => None,
                    },
                    _ => None,
                };
                keywords.push((k, v));
            }
            keywords.reverse();
            args = self.pop_n_exprs(npos);
        } else if nkw > 0 {
            // 3.6+ CALL_FUNCTION_KW: keyword values sit on top (source
            // order), positionals below them
            let vals = self.pop_n_exprs(nkw);
            for (i, v) in vals.into_iter().enumerate() {
                keywords.push((kw_names.get(i).cloned().flatten(), v));
            }
            args = self.pop_n_exprs(npos);
        } else {
            args = self.pop_n_exprs(npos);
        }
        // CALL_METHOD (3.7-3.10): LOAD_METHOD pushed a self/NULL marker
        // above the method; pop it between the args and the callable.
        let marker = if is_method { self.pop() } else { None };
        // <=3.10 async-with inline __aexit__ call: the exit callable was
        // never modeled, so the stack is already empty here — swallow the
        // desugared call without an underflowing pop_callable
        if self.with_exits > 0
            && self.stack.is_empty()
            && keywords.is_empty()
            && star_args_none(&args)
            && args.iter().all(|a| matches!(&**a, Expr::Const(o) if matches!(&**o, PyObject::None)))
        {
            self.with_exits -= 1;
            let next_awaitable = self
                .idx_of
                .get(&self.cur_offset)
                .map_or(false, |&ci| {
                    self.instrs[ci + 1..]
                        .iter()
                        .take(3)
                        .any(|nx| nx.op == Op::GET_AWAITABLE)
                });
            if next_awaitable {
                self.with_exit_await_drop = true;
            }
            return;
        }
        let func = self.pop_callable();
        // normal with exit (<=3.10): __exit__(None, None, None) where the
        // exit callable is not modeled on our stack
        let none_args = star_args_none(&args)
            && args.iter().all(|a| matches!(&**a, Expr::Const(o) if matches!(&**o, PyObject::None)));
        let func_is_exit_slot = matches!(&*func, Expr::Const(o) if matches!(&**o, PyObject::None))
            || matches!(&*func, Expr::Name(n) if n.contains("underflow"));
        if self.with_exits > 0 && keywords.is_empty() && none_args && func_is_exit_slot {
            self.with_exits -= 1;
            // async with (<=3.10): the __aexit__ result is awaited right
            // after the swallowed call — drop that protocol cleanly
            let next_awaitable = self
                .idx_of
                .get(&self.cur_offset)
                .map_or(false, |&ci| {
                    self.instrs[ci + 1..]
                        .iter()
                        .take(3)
                        .any(|nx| nx.op == Op::GET_AWAITABLE)
                });
            if next_awaitable {
                self.with_exit_await_drop = true;
            }
            return;
        }
        // decorator application via CALL_FUNCTION (<=3.10)
        if args.len() == 1 && keywords.is_empty() {
            if let Expr::Function(fd) = &*args[0] {
                let mut fd = (**fd).clone();
                // decorators apply bottom-up; the renderer prints source
                // order (top-down), so each newly applied (outer) decorator
                // goes to the front
                fd.decorators.insert(0, func.clone());
                self.push(Rc::new(Expr::Function(Rc::new(fd))));
                return;
            }
            // py2 decorated class: the decorator call wraps the BUILD_CLASS
            // marker — record it for the pending class and pass the marker
            // through to the store
            if self.pending_py2_class.is_some()
                && matches!(&*args[0], Expr::Name(n) if n == "/*class-object*/")
            {
                self.pending_class_decorators.insert(0, func.clone());
                self.push(args.into_iter().next().unwrap());
                return;
            }
        }
        let call_e: ExprRef = Rc::new(Expr::Call {
            func,
            args,
            keywords,
            star_args: None,
            star_kwargs: None,
        });
        match self.try_make_comprehension(&call_e, marker) {
            Some(comp) => self.push(comp),
            None => self.push(call_e),
        }
    }

    fn call_function_py2_var(&mut self, argc: usize) {
        // py2: CALL_FUNCTION_VAR — starargs on top
        let star = self.pop_expr();
        let (npos, nkw) = (argc & 0xFF, (argc >> 8) & 0xFF);
        let args = self.pop_n_exprs(npos as usize);
        let mut keywords = Vec::new();
        for _ in 0..nkw {
            let v = self.pop_expr();
            let k = self.pop_expr();
            let ks = match &*k {
                Expr::Const(o) => match &**o {
                    PyObject::Str(s) => Some(s.clone()),
                    PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                    _ => None,
                },
                _ => None,
            };
            keywords.push((ks, v));
        }
        keywords.reverse();
        let func = self.pop_callable();
        self.push(Rc::new(Expr::Call {
            func,
            args,
            keywords,
            star_args: Some(star),
            star_kwargs: None,
        }));
    }

    /// py2/3.0-3.5 CALL_FUNCTION_KW: [callable, pos*na, (name,val)*nk,
    /// kwdict] — the **kwargs dict always rides on top
    fn call_function_py2_kw(&mut self, argc: usize) {
        let kwargs = self.pop_expr();
        let (npos, nkw) = (argc & 0xFF, (argc >> 8) & 0xFF);
        let args = self.pop_n_exprs(npos as usize);
        let mut keywords = Vec::new();
        for _ in 0..nkw {
            let v = self.pop_expr();
            let k = self.pop_expr();
            let ks = match &*k {
                Expr::Const(o) => match &**o {
                    PyObject::Str(s) => Some(s.clone()),
                    PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                    _ => None,
                },
                _ => None,
            };
            keywords.push((ks, v));
        }
        keywords.reverse();
        let func = self.pop_callable();
        self.push(Rc::new(Expr::Call {
            func,
            args,
            keywords,
            star_args: None,
            star_kwargs: Some(kwargs),
        }));
    }

    fn call_function_py2_varkw(&mut self, argc: usize) {
        let kwargs = self.pop_expr();
        let star = self.pop_expr();
        let (npos, nkw) = (argc & 0xFF, (argc >> 8) & 0xFF);
        let args = self.pop_n_exprs(npos as usize);
        let mut keywords = Vec::new();
        for _ in 0..nkw {
            let v = self.pop_expr();
            let k = self.pop_expr();
            let ks = match &*k {
                Expr::Const(o) => match &**o {
                    PyObject::Str(s) => Some(s.clone()),
                    PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                    _ => None,
                },
                _ => None,
            };
            keywords.push((ks, v));
        }
        keywords.reverse();
        let func = self.pop_callable();
        self.push(Rc::new(Expr::Call {
            func,
            args,
            keywords,
            star_args: Some(star),
            star_kwargs: Some(kwargs),
        }));
    }

    /// 3.11+ CALL (and 3.7-3.10 CALL_METHOD share the same pop order):
    /// stack is `[marker, callable, args...]`, so pop args, then the
    /// callable, then the self/NULL marker. The callable expression for a
    /// method is already `Attribute { value: receiver }`, so the marker is
    /// only validated, not consumed into the AST.
    fn call_311(&mut self, argc: usize, _is_method: bool) {
        let args = self.pop_n_exprs(argc);
        // CALL slot layouts differ by callee kind:
        // * plain call:            [NULL, callable, args...]  (PUSH_NULL)
        // * method (LOAD_ATTR/METHOD): [self, callable, args...]
        // * genexpr instantiation: [callable, iterable] with argc==0 —
        //   the iterable sits ABOVE the function and becomes the marker
        // Peek before popping to choose the right order.
        let n = self.stack.len();
        let genexpr_case = n >= 2
            && matches!(&self.stack[n - 1], Sv::E(_))
            && matches!(&self.stack[n - 2], Sv::E(f) if is_comp_callable(f));
        let (callable, marker) = if self.version.at_least(3, 14) || genexpr_case {
            // 3.14+: [callable, self_or_null, args...] — marker pops first.
            // genexpr instantiation (<=3.13): [genfunc, iterable].
            let marker = self.pop_expr_raw();
            let callable = self.pop_expr();
            (callable, marker)
        } else {
            // 3.11-3.13: NULL may sit above the callable (PUSH_NULL after
            // the load, 3.13 style) — a skipped NULL IS the marker, so only
            // pop a second slot when nothing was skipped
            let (callable, skipped_null) = self.pop_expr_skipped();
            let marker = if skipped_null {
                None
            } else {
                self.pop_expr_raw()
            };
            (callable, marker)
        };

        // The callable expression for a method is already
        // Attribute { value: receiver }; the marker is only needed for
        // comprehension detection.
        let func = callable;

        let kw_names = std::mem::take(&mut self.last_kw_names);
        let (pos_args, keywords) = if !kw_names.is_empty() && kw_names.len() <= args.len() {
            // 3.11/3.12 KW_NAMES names the TRAILING k args of the call;
            // the leading ones are positional
            let npos = args.len() - kw_names.len();
            let mut it = args.into_iter();
            let pos: Vec<ExprRef> = it.by_ref().take(npos).collect();
            let kws: Vec<(Option<String>, ExprRef)> =
                it.zip(kw_names.into_iter()).map(|(a, k)| (k, a)).collect();
            (pos, kws)
        } else {
            (args, Vec::new())
        };

        // decorator application: calling with a Function object argument
        // (3.12+ uses CALL 0 with the decorator *below* the function)
        if pos_args.len() == 1 && keywords.is_empty() {
            if let Expr::Function(fd) = &*pos_args[0] {
                let mut fd = (**fd).clone();
                fd.decorators.insert(0, func.clone());
                self.push(Rc::new(Expr::Function(Rc::new(fd))));
                return;
            }
        }
        // 3.12 decorated CLASS: `LOAD deco; ...build_class...; CALL n;
        // CALL 0` leaves the built class as the callable and the decorator
        // in the marker slot; rebuild deco(build_class(...)) so the
        // store-time class recognition can peel the decorator
        if pos_args.is_empty() && keywords.is_empty() {
            if let Expr::Call { func: f2, .. } = &*func {
                if matches!(&**f2, Expr::Name(n) if n == "__build_class__") {
                    if let Some(Sv::E(deco)) = &marker {
                        self.push(Rc::new(Expr::Call {
                            func: deco.clone(),
                            args: vec![func],
                            keywords: Vec::new(),
                            star_args: None,
                            star_kwargs: None,
                        }));
                        return;
                    }
                }
            }
        }
        // comprehension instantiation takes precedence over decorator shapes
        let comp_callable = is_comp_callable(&func);
        if !comp_callable {
            if let Expr::Function(fd) = &*func {
                if pos_args.is_empty() && keywords.is_empty() {
                    if let Some(Sv::E(deco)) = marker.clone() {
                        let mut fd = (**fd).clone();
                        fd.decorators.insert(0, deco);
                        self.push(Rc::new(Expr::Function(Rc::new(fd))));
                        return;
                    }
                }
            }
            // 3.14 decorator shape: marker slot holds the function, callable
            // is the decorator (`deco(func)` via CALL 0)
            if pos_args.is_empty() && keywords.is_empty() {
                if let Some(Sv::E(m)) = &marker {
                    if let Expr::Function(fd) = &**m {
                        let mut fd = (**fd).clone();
                        fd.decorators.insert(0, func.clone());
                        self.push(Rc::new(Expr::Function(Rc::new(fd))));
                        return;
                    }
                    // decorated class via CALL 0: the built class sits in
                    // the marker slot — rebuild deco(build_class(...))
                    if let Expr::Call { func: f2, .. } = &**m {
                        if matches!(&**f2, Expr::Name(n) if n == "__build_class__") {
                            self.push(Rc::new(Expr::Call {
                                func,
                                args: vec![m.clone()],
                                keywords: Vec::new(),
                                star_args: None,
                                star_kwargs: None,
                            }));
                            return;
                        }
                    }
                }
            }
        }

        // normal with exit: the compiler calls the stored __exit__ with
        // (None, None, None); our model does not keep __exit__ on the stack,
        // so recognize and swallow the call
        let none_args =
            pos_args.iter().all(|a| matches!(&**a, Expr::Const(o) if matches!(&**o, PyObject::None)));
        let func_is_none = matches!(&*func, Expr::Const(o) if matches!(&**o, PyObject::None));
        let func_is_underflow =
            matches!(&*func, Expr::Name(n) if n.contains("underflow"));
        let marker_is_none_slot = match &marker {
            None | Some(Sv::Null) => true,
            Some(Sv::E(m)) => matches!(&**m, Expr::Const(o) if matches!(&**o, PyObject::None)),
            Some(_) => false,
        };
        if self.with_exits > 0
            && keywords.is_empty()
            && marker_is_none_slot
            && none_args
            && (func_is_none || func_is_underflow)
        {
            self.with_exits -= 1;
            // async with (3.11+): the __aexit__ result is awaited right
            // after the swallowed call — the protocol has no awaitable on
            // our modeled stack, so drop it cleanly (no underflow)
            let next_awaitable = self
                .idx_of
                .get(&self.cur_offset)
                .map_or(false, |&ci| {
                    self.instrs[ci + 1..]
                        .iter()
                        .take(3)
                        .any(|nx| nx.op == Op::GET_AWAITABLE)
                });
            if next_awaitable {
                self.with_exit_await_drop = true;
            }
            return;
        }

        // Comprehension instantiation consumes the marker as the iterable,
        // so try it first (it only matches a Function/genexpr callable).
        let comp_callable_e: ExprRef = Rc::new(Expr::Call {
            func: func.clone(),
            args: pos_args.clone(),
            keywords: keywords.clone(),
            star_args: None,
            star_kwargs: None,
        });
        if let Some(comp) = self.try_make_comprehension(&comp_callable_e, marker.clone()) {
            self.push(comp);
            return;
        }
        // 3.14+: a non-NULL marker holding a real expression is an implicit
        // first argument (CPython CALL treats a non-NULL self_or_null slot as
        // a bound-method-style leading arg). LOAD_COMMON_CONSTANT pushes the
        // callable with NO NULL marker, so `assert x, msg` lowers to
        // [AssertionError, msg]; CALL 0 consumes msg as self_or_null and
        // raises AssertionError(msg). For an Attribute callable the marker is
        // the method receiver, already embedded in the Attribute -> discard.
        let mut final_args = pos_args;
        if self.version.at_least(3, 14) && !matches!(&*func, Expr::Attribute { .. }) {
            if let Some(Sv::E(m)) = &marker {
                if !matches!(&**m, Expr::Const(o) if matches!(&**o, PyObject::None)) {
                    final_args.insert(0, m.clone());
                }
            }
        }
        self.push(Rc::new(Expr::Call {
            func,
            args: final_args,
            keywords,
            star_args: None,
            star_kwargs: None,
        }));
    }

    /// Pop the callable for py2-style CALL_FUNCTION, skipping a NULL marker.
    fn pop_callable(&mut self) -> ExprRef {
        self.pop_expr()
    }

    fn make_function(&mut self, inst: &Instruction, flags: u32) {
        // Stack layout by era:
        //  py2-3.2: [defaults..., code] (MAKE_CLOSURE inserts closure tuple
        //           below code)
        //  3.3-3.10: [..., code, qualname] — qualname on top (PEP 3155)
        //  3.11+: qualname lives in the code object; code on top
        let code_e = if self.version.at_least(3, 3) && !self.version.at_least(3, 11) {
            let qualname = self.pop_expr();
            let _ = qualname;
            self.pop_expr()
        } else {
            self.pop_expr()
        };
        let code_obj = match &*code_e {
            Expr::Const(o) => match &**o {
                PyObject::Code(c) => c.clone(),
                _ => {
                    self.mark_unclean();
                    return;
                }
            },
            _ => {
                self.mark_unclean();
                return;
            }
        };

        let params;
        let returns: Option<ExprRef> = None;

        if self.version.at_least(3, 6) {
            // flags in argument order on stack: annotations(3.6-3.12),
            // kwdefaults, defaults, closure — pushed as:
            // stack bottom..top: [closure?, defaults?, kwdefaults?, annotations?, qualname, code]
            // MAKE_FUNCTION pops code, qualname, then per flags.
            let mut defaults_t: Option<ExprRef> = None;
            let mut kwdefaults_d: Option<ExprRef> = None;
            let mut ann: Option<ExprRef> = None;
            let mut _closure: Option<ExprRef> = None;

            let has_ann = if self.version.at_least(3, 13) {
                false // annotations arrive via SET_FUNCTION_ATTRIBUTE
            } else {
                flags & 0x04 != 0
            };
            if flags & 0x08 != 0 {
                _closure = Some(self.pop_expr());
            }
            if has_ann {
                ann = Some(self.pop_expr());
            }
            if flags & 0x02 != 0 {
                kwdefaults_d = Some(self.pop_expr());
            }
            if flags & 0x01 != 0 {
                defaults_t = Some(self.pop_expr());
            }

            params = self.build_params(&code_obj, defaults_t, kwdefaults_d, ann);
            if self.version.at_least(3, 13) && flags & 0x04 != 0 {
                // 3.13: 0x04 = closure? no: 3.13 flags: 0x01 defaults,
                // 0x02 kwdefaults, 0x04 annotations? handled above
            }
        } else {
            // <= 3.5: defaults are individual stack values; MAKE_CLOSURE
            // (py2.1+/3.3-3.5) pushes the closure tuple ABOVE the defaults:
            // [defaults..., closure, code, qualname]
            // py2: MAKE_FUNCTION arg = number of defaults on the stack.
            // 3.0-3.5: arg = ndefaults | (nkwdefault_pairs << 8) — the
            // kwdefault name/value pairs sit BELOW the positional defaults
            // and must be consumed even though the legacy signature has no
            // slot for them
            let (ndefaults, nkw_pairs) = if self.version.major >= 3 {
                ((flags & 0xFF) as usize, (flags >> 8) as usize)
            } else {
                (flags as usize, 0usize)
            };
            if inst.op == Op::MAKE_CLOSURE {
                let _closure = self.pop_expr();
            }
            // stack order of the flat kwdefault pairs vs the positional
            // defaults flipped between 3.4 and 3.5: <=3.4 pushes the kw
            // pairs FIRST (defaults on top: configparser 3.3 get()),
            // 3.5+ pushes the defaults first (kw pairs on top — codecs
            // 3.5 CodecInfo.__new__ mis-assigned the kw pair name as a
            // positional default when the pops ran in the wrong order)
            let mut defaults = Vec::new();
            let mut kw_pairs: Vec<(String, ExprRef)> = Vec::new();
            let pop_defaults = |slf: &mut Self, out: &mut Vec<ExprRef>| {
                for _ in 0..ndefaults {
                    out.push(slf.pop_expr());
                }
                out.reverse();
            };
            let pop_kw = |slf: &mut Self,
                          out: &mut Vec<(String, ExprRef)>| {
                for _ in 0..nkw_pairs {
                    let v = slf.pop_expr();
                    let n = slf.pop_expr();
                    if let Expr::Const(o) = &*n {
                        if let PyObject::Str(s) = &**o {
                            out.push((s.clone(), v));
                        }
                    }
                }
                out.reverse();
            };
            if self.version.at_least(3, 5) {
                pop_kw(self, &mut kw_pairs);
                pop_defaults(self, &mut defaults);
            } else {
                pop_defaults(self, &mut defaults);
                pop_kw(self, &mut kw_pairs);
            }
            params = self.build_params_legacy(&code_obj, defaults, kw_pairs);
        }

        // decorators: 2.6-3.5 applied via MAKE_FUNCTION wrapper calls;
        // 3.x modern: decorators are call wrappers around the function.
        let decorators = std::mem::take(&mut self.pending_decorators);

        let is_lambda = code_obj.name == "<lambda>";
        let is_async = code_obj.is_coroutine() || code_obj.is_async_generator();
        let fdef = Rc::new(FunctionDef {
            name: code_obj.name.clone(),
            code: code_obj,
            params,
            decorators,
            returns,
            is_async,
        });
        if is_lambda {
            // body: single return expression — extract from the lambda code
            let body = self.lambda_body(&fdef.code);
            self.push(Rc::new(Expr::Lambda {
                params: Box::new(fdef.params.clone()),
                body,
            }));
        } else {
            self.push(Rc::new(Expr::Function(fdef)));
        }
    }

    fn build_params(
        &mut self,
        code: &Rc<CodeObject>,
        defaults_t: Option<ExprRef>,
        kwdefaults_d: Option<ExprRef>,
        ann: Option<ExprRef>,
    ) -> Parameters {
        let argcount = code.arg_count as usize;
        let posonly = code.posonly_arg_count as usize;
        let kwonly = code.kwonly_arg_count as usize;
        let varargs = code.has_varargs();
        let varkw = code.has_varkeywords();

        // localsplus/varnames: positional args first, then kwonly, then
        // *args/**kwargs (3.11+ varnames already excludes non-LOCAL entries)
        let all_names: Vec<String> = code.varnames.clone();

        let defaults: Vec<ExprRef> = match &defaults_t {
            Some(e) => match &**e {
                Expr::Const(o) => match &**o {
                    PyObject::Tuple(items) => items
                        .iter()
                        .map(|i| Rc::new(Expr::Const(i.clone())) as ExprRef)
                        .collect(),
                    _ => Vec::new(),
                },
                Expr::Tuple(items) => items.clone(),
                other => vec![Rc::new(other.clone())],
            },
            None => Vec::new(),
        };

        // annotations (3.6-3.12): dict const or BUILD map on stack
        let mut ann_map: HashMap<String, ExprRef> = HashMap::new();
        let mut ret_ann: Option<ExprRef> = None;
        if let Some(a) = ann {
            match &*a {
                Expr::Const(o) => match &**o {
                    PyObject::Tuple(items)
                        if items.len() >= 2
                            && items.len() % 2 == 0
                            && items.iter().step_by(2).all(|it| matches!(&**it, PyObject::Str(_)))
                            && self.version.at_least(3, 12) =>
                    {
                        // 3.12+: flat (name, value, name, value, ...) pairs
                        for pair in items.chunks(2) {
                            if let PyObject::Str(name) = &*pair[0] {
                                let v: ExprRef = Rc::new(Expr::Const(pair[1].clone()));
                                if name == "return" {
                                    ret_ann = Some(v);
                                } else {
                                    ann_map.insert(name.clone(), v);
                                }
                            }
                        }
                    }
                    PyObject::Tuple(items) if items.len() == 2 => {
                        // 3.10+: (names_tuple, values_tuple)
                        let names: Vec<String> = match &*items[0] {
                            PyObject::Tuple(ns) => ns
                                .iter()
                                .filter_map(|n| match &**n {
                                    PyObject::Str(s) => Some(s.clone()),
                                    _ => None,
                                })
                                .collect(),
                            _ => Vec::new(),
                        };
                        let values: Vec<ExprRef> = match &*items[1] {
                            PyObject::Tuple(vs) => vs
                                .iter()
                                .map(|v| Rc::new(Expr::Const(v.clone())) as ExprRef)
                                .collect(),
                            _ => Vec::new(),
                        };
                        for (n, v) in names.into_iter().zip(values) {
                            if n == "return" {
                                ret_ann = Some(v);
                            } else {
                                ann_map.insert(n, v);
                            }
                        }
                    }
                    PyObject::Dict(entries) => {
                        for (k, v) in entries {
                            if let PyObject::Str(ks) = &**k {
                                if ks == "return" {
                                    ret_ann = Some(Rc::new(Expr::Const(v.clone())));
                                } else {
                                    ann_map
                                        .insert(ks.clone(), Rc::new(Expr::Const(v.clone())));
                                }
                            }
                        }
                    }
                    _ => {}
                },
                Expr::Dict(entries) => {
                    for (k, v) in entries {
                        if let Expr::Const(o) = &**k {
                            if let PyObject::Str(ks) = &**o {
                                if ks == "return" {
                                    ret_ann = Some(v.clone());
                                } else {
                                    ann_map.insert(ks.clone(), v.clone());
                                }
                            }
                        }
                    }
                }
                Expr::Tuple(items)
                    if items.len() >= 2
                        && items.len() % 2 == 0
                        && items
                            .iter()
                            .step_by(2)
                            .all(|it| matches!(&**it, Expr::Const(o) if matches!(&**o, PyObject::Str(_)))) =>
                {
                    // runtime-built flat (name, value, ...) pairs (3.10+)
                    for pair in items.chunks(2) {
                        if let Expr::Const(o) = &*pair[0] {
                            if let PyObject::Str(name) = &**o {
                                if name == "return" {
                                    ret_ann = Some(pair[1].clone());
                                } else {
                                    ann_map.insert(name.clone(), pair[1].clone());
                                }
                            }
                        }
                    }
                }
                Expr::Tuple(items) if items.len() == 2 => {
                    // 3.10 style (names_tuple_const, values_tuple_const)
                    let names: Vec<String> = match &*items[0] {
                        Expr::Const(o) => match &**o {
                            PyObject::Tuple(ns) => ns
                                .iter()
                                .filter_map(|n| match &**n {
                                    PyObject::Str(s) => Some(s.clone()),
                                    _ => None,
                                })
                                .collect(),
                            _ => Vec::new(),
                        },
                        _ => Vec::new(),
                    };
                    let values: Vec<ExprRef> = match &*items[1] {
                        Expr::Const(o) => match &**o {
                            PyObject::Tuple(vs) => vs
                                .iter()
                                .map(|v| Rc::new(Expr::Const(v.clone())) as ExprRef)
                                .collect(),
                            _ => Vec::new(),
                        },
                        _ => Vec::new(),
                    };
                    for (n, v) in names.into_iter().zip(values) {
                        if n == "return" {
                            ret_ann = Some(v);
                        } else {
                            ann_map.insert(n, v);
                        }
                    }
                }
                _ => {}
            }
        }

        let kw_defaults_map: HashMap<String, ExprRef> = match &kwdefaults_d {
            Some(e) => match &**e {
                Expr::Const(o) => match &**o {
                    PyObject::Dict(entries) => entries
                        .iter()
                        .filter_map(|(k, v)| match &**k {
                            PyObject::Str(ks) => Some((ks.clone(), Rc::new(Expr::Const(v.clone())) as ExprRef)),
                            _ => None,
                        })
                        .collect(),
                    _ => HashMap::new(),
                },
                Expr::Dict(entries) => entries
                    .iter()
                    .filter_map(|(k, v)| match &**k {
                        Expr::Const(o) => match &**o {
                            PyObject::Str(ks) => Some((ks.clone(), v.clone())),
                            _ => None,
                        },
                        _ => None,
                    })
                    .collect(),
                _ => HashMap::new(),
            },
            None => HashMap::new(),
        };

        let mk_param = |name: &str| Param {
            name: name.to_string(),
            annotation: ann_map.get(name).cloned(),
        };

        let mut params = Parameters::empty();
        params.posonly_count = posonly;
        for n in all_names.iter().take(argcount) {
            params.args.push(mk_param(n));
        }
        let mut idx = argcount;
        for n in all_names.iter().skip(argcount).take(kwonly) {
            let p = Param {
                name: n.clone(),
                annotation: ann_map.get(n).cloned(),
            };
            let d = kw_defaults_map.get(n).cloned();
            params.kwonly.push(p);
            params.kw_defaults.push(d);
            idx += 1;
        }
        if varargs {
            if let Some(n) = all_names.get(idx) {
                params.vararg = Some(mk_param(n));
                idx += 1;
            }
        }
        if varkw {
            if let Some(n) = all_names.get(idx) {
                params.kwarg = Some(mk_param(n));
            }
        }
        params.defaults = defaults;
        params.returns_annotation = ret_ann;
        params
    }

    fn build_params_legacy(
        &mut self,
        code: &Rc<CodeObject>,
        defaults: Vec<ExprRef>,
        kw_pairs: Vec<(String, ExprRef)>,
    ) -> Parameters {
        let argcount = code.arg_count as usize;
        let kwonly = code.kwonly_arg_count as usize;
        let varargs = code.has_varargs();
        let varkw = code.has_varkeywords();
        let mut params = Parameters::empty();
        for n in code.varnames.iter().take(argcount) {
            params.args.push(Param {
                name: sanitize_varname(n),
                annotation: None,
            });
        }
        let mut idx = argcount;
        for n in code.varnames.iter().skip(argcount).take(kwonly) {
            params.kwonly.push(Param {
                name: n.clone(),
                annotation: None,
            });
            let d = kw_pairs.iter().find(|(k, _)| k == n).map(|(_, v)| v.clone());
            params.kw_defaults.push(d);
            idx += 1;
        }
        if varargs {
            if let Some(n) = code.varnames.get(idx) {
                params.vararg = Some(Param {
                    name: n.clone(),
                    annotation: None,
                });
                idx += 1;
            }
        }
        if varkw {
            if let Some(n) = code.varnames.get(idx) {
                params.kwarg = Some(Param {
                    name: n.clone(),
                    annotation: None,
                });
            }
        }
        params.defaults = defaults;
        params
    }

    fn set_function_attribute_313(&mut self, flags: u32) {
        // 3.13+: SET_FUNCTION_ATTRIBUTE (func, attr -- func): the function
        // is on TOP, the attribute value below it
        let func_e = self.pop_expr();
        let value = self.pop_expr();
        let mut params_opt: Option<Parameters> = None;
        let mut returns_opt: Option<ExprRef> = None;
        let mut params = match &*func_e {
            Expr::Function(fd) => fd.params.clone(),
            Expr::Lambda { params, .. } => (**params).clone(),
            _ => {
                // not a function we track; restore stack best-effort
                self.push(value);
                self.push(func_e);
                return;
            }
        };
        if flags & 0x10 != 0 {
            // 3.14 PEP 649: value is the __annotate__ function whose body
            // returns the annotations dict
            if let Expr::Function(afd) = &*value {
                if afd.code.name == "__annotate__" {
                    if let Ok(d) = decompile(&afd.code, self.version) {
                        for stmt in &d.body {
                            if let Stmt::Return(Some(e)) = stmt {
                                apply_annotations_313_dictexpr(&mut params, e);
                            }
                        }
                    }
                }
            }
        }
        match flags {
            0x01 => params.defaults = tuple_items(&value),
            0x02 => {
                let map = dict_items(&value);
                params.kw_defaults = params
                    .kwonly
                    .iter()
                    .map(|p| map.iter().find(|(k, _)| k == &p.name).map(|(_, v)| v.clone()))
                    .collect();
            }
            0x04 => {
                let raw = self.code.flags & crate::code::CO_FUTURE_ANNOTATIONS != 0;
                apply_annotations_313(&mut params, &value, raw)
            }
            0x08 => returns_opt = Some(value.clone()),
            _ => {}
        }
        let _ = &mut params_opt;
        let out = match &*func_e {
            Expr::Function(fd) => {
                let mut fd = (**fd).clone();
                fd.params = params;
                if let Some(r) = returns_opt {
                    fd.returns = Some(r);
                }
                Rc::new(Expr::Function(Rc::new(fd))) as ExprRef
            }
            Expr::Lambda { body, .. } => Rc::new(Expr::Lambda {
                params: Box::new(params),
                body: body.clone(),
            }),
            _ => func_e.clone(),
        };
        self.push(out);
    }

    fn lambda_body(&mut self, code: &CodeObject) -> ExprRef {
        // lambda code: build expression from the (short) instruction stream
        let inner = decompile(code, self.version);
        match inner {
            Ok(d) => {
                for stmt in &d.body {
                    if let Stmt::Return(Some(e)) = stmt {
                        return e.clone();
                    }
                    if let Stmt::Expr(e) = stmt {
                        return e.clone();
                    }
                }
                // yield lambdas etc.
                for stmt in &d.body {
                    if let Stmt::Return(None) = stmt {
                        return Rc::new(Expr::Const(Rc::new(PyObject::None)));
                    }
                }
                self.mark_unclean();
                self.name_expr("/*lambda?*/")
            }
            Err(_) => {
                self.mark_unclean();
                self.name_expr("/*lambda?*/")
            }
        }
    }

    fn decompile_function(&mut self, code: &Rc<CodeObject>) -> Option<Vec<Stmt>> {
        self.decompile_scoped(code, false)
    }

    /// Decompile a class body: pushes the class name onto the scope so
    /// methods can unmangle `_Class__attr` back to `__attr`.
    fn decompile_class_body(&mut self, code: &Rc<CodeObject>, name: &str) -> Option<Vec<Stmt>> {
        self.class_scope.push(name.to_string());
        let r = self.decompile_scoped(code, true);
        self.class_scope.pop();
        r
    }

    fn decompile_scoped(&mut self, code: &Rc<CodeObject>, scope_self: bool) -> Option<Vec<Stmt>> {
        let scope: Vec<String> = if scope_self {
            let mut v = self.class_scope.clone();
            v.push(code.name.clone());
            v
        } else {
            self.class_scope.clone()
        };
        match decompile_in_scope(code, self.version, &scope) {
            Ok(d) => {
                if !d.clean {
                    self.mark_unclean();
                }
                let mut body = postprocess_body(d.body, code);
                // Function docstrings never appear in bytecode: CPython
                // stores them in consts[0]. Up to 3.13 the compiler always
                // reserves slot 0 (None when there is no docstring), so a
                // leading string const IS the docstring; 3.14 dropped the
                // reserved slot and marks it with CO_HAS_DOCSTRING instead.
                if !scope_self && code.name != "<module>" {
                    let marked = if self.version.at_least(3, 14) {
                        code.flags & 0x0400_0000 != 0
                    } else {
                        true
                    };
                    // skip only when the walk ALREADY emitted the
                    // docstring const as the first Expr — a body
                    // starting with an ordinary expression statement
                    // (a bare call like `self.mutex.acquire()`) must
                    // still get its docstring injected (Queue 2.7
                    // task_done/join/qsize/empty/full/put/get lost
                    // theirs to the over-wide Expr guard)
                    let already_doc = matches!(
                        body.first(),
                        Some(Stmt::Expr(e))
                            if matches!(&**e, Expr::Const(c)
                                if matches!(&**c, PyObject::Str(_) | PyObject::Bytes(_)))
                    );
                    if marked && !already_doc {
                        if let Some(c0) = code.consts.first() {
                            if matches!(&**c0, PyObject::Str(_) | PyObject::Bytes(_)) {
                                body.insert(0, Stmt::Expr(Rc::new(Expr::Const(c0.clone()))));
                            }
                        }
                    }
                }
                // regenerate the implicit tail pair the flat rendering
                // of an all-arms-returning if/else would drop on
                // recompile (see bytecode_tail_return_pair); only when
                // the body still ends in a VALUE return — a bare
                // trailing return already reproduces the pair
                if d.tail_pair
                    && matches!(body.last(), Some(Stmt::Return(Some(_))))
                {
                    body.push(Stmt::Return(None));
                }
                Some(body)
            }
            Err(_) => {
                self.mark_unclean();
                None
            }
        }
    }
}

impl<'a> Ctx<'a> {
    fn handle_collection_op(&mut self, inst: &Instruction, arg: u32) {
        match inst.op {
            Op::LIST_EXTEND | Op::SET_UPDATE => {
                let iter = self.pop_expr();
                let coll = self.pop_expr();
                let items = match &*coll {
                    Expr::List(v) => v.clone(),
                    Expr::Set(v) => v.clone(),
                    Expr::Tuple(v) => v.to_vec(),
                    other => vec![Rc::new(other.clone())],
                };
                let mut all = items;
                match &*iter {
                    Expr::Const(o) => match &**o {
                        PyObject::Tuple(t) | PyObject::List(t) | PyObject::FrozenSet(t) => {
                            all.extend(t.iter().map(|c| Rc::new(Expr::Const(c.clone())) as ExprRef));
                        }
                        _ => all.push(iter),
                    },
                    other => all.push(Rc::new(Expr::Starred(Rc::new(other.clone())))),
                }
                let e = match inst.op {
                    Op::LIST_EXTEND => Expr::List(all),
                    _ => Expr::Set(all),
                };
                self.push(Rc::new(e));
            }
            Op::DICT_UPDATE | Op::DICT_MERGE => {
                let other = self.pop_expr();
                let dict = self.pop_expr();
                let mut entries = match &*dict {
                    Expr::Dict(d) => d.clone(),
                    _ => Vec::new(),
                };
                match &*other {
                    Expr::Dict(d) => entries.extend(d.iter().cloned()),
                    o => entries.push((
                        Rc::new(Expr::Starred(Rc::new(o.clone()))),
                        self.name_expr(""),
                    )),
                }
                self.push(Rc::new(Expr::Dict(entries)));
            }
            Op::LIST_APPEND | Op::SET_ADD => {
                let item = self.pop_expr();
                let len = self.stack.len();
                let idx = len.saturating_sub(arg as usize);
                let coll = self
                    .stack
                    .get(idx)
                    .and_then(|sv| match sv {
                        Sv::E(e) => Some(e.clone()),
                        _ => None,
                    })
                    .unwrap_or_else(|| Rc::new(Expr::List(vec![])));
                let mut items = match &*coll {
                    Expr::List(v) => v.clone(),
                    Expr::Set(v) => v.clone(),
                    _ => vec![],
                };
                items.push(item);
                let e = match inst.op {
                    Op::LIST_APPEND => Expr::List(items),
                    _ => Expr::Set(items),
                };
                let new: ExprRef = Rc::new(e);
                if let Some(Sv::E(slot)) = self.stack.get_mut(idx) {
                    *slot = new;
                }
            }
            Op::MAP_ADD => {
                // CPython operand order: 3.8+ pushes key then value
                // (value on top); pre-3.8 (incl. py2.7 dict comps) pushes
                // value then key (key on top)
                let (key, value) = if self.version.at_least(3, 8) {
                    let value = self.pop_expr();
                    let key = self.pop_expr();
                    (key, value)
                } else {
                    let key = self.pop_expr();
                    let value = self.pop_expr();
                    (key, value)
                };
                let len = self.stack.len();
                let idx = len.saturating_sub(arg as usize);
                let coll = self
                    .stack
                    .get(idx)
                    .and_then(|sv| match sv {
                        Sv::E(e) => Some(e.clone()),
                        _ => None,
                    })
                    .unwrap_or_else(|| Rc::new(Expr::Dict(vec![])));
                let mut entries = match &*coll {
                    Expr::Dict(d) => d.clone(),
                    _ => vec![],
                };
                entries.push((key, value));
                let new: ExprRef = Rc::new(Expr::Dict(entries));
                if let Some(Sv::E(slot)) = self.stack.get_mut(idx) {
                    *slot = new;
                }
            }
            Op::LIST_TO_TUPLE => {
                let e = self.pop_expr();
                let items = match &*e {
                    Expr::List(v) => v.clone(),
                    other => vec![Rc::new(other.clone())],
                };
                self.push(Rc::new(Expr::Tuple(items)));
            }
            Op::COPY_DICT_WITHOUT_KEYS => {
                // match/case dict rest binding — not supported yet
                self.mark_unclean();
            }
            _ => self.mark_unclean(),
        }
    }
}

fn tuple_items(e: &ExprRef) -> Vec<ExprRef> {
    match &**e {
        Expr::Const(o) => match &**o {
            PyObject::Tuple(items) => items
                .iter()
                .map(|i| Rc::new(Expr::Const(i.clone())) as ExprRef)
                .collect(),
            _ => Vec::new(),
        },
        Expr::Tuple(items) => items.clone(),
        _ => Vec::new(),
    }
}

fn dict_items(e: &ExprRef) -> Vec<(String, ExprRef)> {
    let mut out = Vec::new();
    match &**e {
        Expr::Const(o) => match &**o {
            PyObject::Dict(entries) => {
                for (k, v) in entries {
                    if let PyObject::Str(ks) = &**k {
                        out.push((ks.clone(), Rc::new(Expr::Const(v.clone())) as ExprRef));
                    }
                }
            }
            _ => {}
        },
        Expr::Dict(entries) => {
            for (k, v) in entries {
                if let Expr::Const(o) = &**k {
                    if let PyObject::Str(ks) = &**o {
                        out.push((ks.clone(), v.clone()));
                    }
                }
            }
        }
        _ => {}
    }
    out
}

/// Apply annotations from a runtime Dict expression (PEP 649 __annotate__).
fn apply_annotations_313_dictexpr(params: &mut Parameters, value: &ExprRef) {
    let Expr::Dict(entries) = &**value else { return };
    for (k, v) in entries {
        let Expr::Const(o) = &**k else { continue };
        let PyObject::Str(name) = &**o else { continue };
        if name == "return" {
            params.returns_annotation = Some(v.clone());
            continue;
        }
        for p in params.args.iter_mut() {
            if p.name == *name {
                p.annotation = Some(v.clone());
            }
        }
        for p in params.kwonly.iter_mut() {
            if p.name == *name {
                p.annotation = Some(v.clone());
            }
        }
        if let Some(p) = params.vararg.as_mut() {
            if p.name == *name {
                p.annotation = Some(v.clone());
            }
        }
        if let Some(p) = params.kwarg.as_mut() {
            if p.name == *name {
                p.annotation = Some(v.clone());
            }
        }
    }
}

fn apply_annotations_313(params: &mut Parameters, value: &ExprRef, raw_strings: bool) {
    // PEP 563 (`from __future__ import annotations`): annotation values
    // are Const source-text strings — render them RAW (Name carries the
    // text verbatim through codegen); a quoted string literal would
    // re-stringify with quotes and break sig-exactness
    let conv = |e: &ExprRef| -> ExprRef {
        if raw_strings {
            if let Expr::Const(o) = &**e {
                if let PyObject::Str(t) = &**o {
                    return Rc::new(Expr::Name(t.clone()));
                }
            }
        }
        e.clone()
    };
    // 3.13+: annotations as a flat runtime tuple (name, value, ...) —
    // including the "return" entry. The tuple arrives as a LOAD-ed
    // constant (Const(Tuple)) — normalize through tuple_items
    {
        let items = tuple_items(value);
        if items.len() >= 2 && items.len() % 2 == 0 {
            let mut handled = true;
            for pair in items.chunks(2) {
                let Expr::Const(o) = &*pair[0] else {
                    handled = false;
                    break;
                };
                let PyObject::Str(name) = &**o else {
                    handled = false;
                    break;
                };
                if name == "return" {
                    params.returns_annotation = Some(conv(&pair[1]));
                    continue;
                }
                let mut done = false;
                for p in params.args.iter_mut() {
                    if p.name == *name {
                        p.annotation = Some(conv(&pair[1]));
                        done = true;
                    }
                }
                for p in params.kwonly.iter_mut() {
                    if p.name == *name {
                        p.annotation = Some(conv(&pair[1]));
                        done = true;
                    }
                }
                if let Some(p) = params.vararg.as_mut() {
                    if p.name == *name {
                        p.annotation = Some(conv(&pair[1]));
                        done = true;
                    }
                }
                if let Some(p) = params.kwarg.as_mut() {
                    if p.name == *name {
                        p.annotation = Some(conv(&pair[1]));
                        done = true;
                    }
                }
                let _ = done;
            }
            if handled {
                return;
            }
        }
    }
    // fallback: dict form
    for (name, ann) in dict_items(value) {
        if name == "return" {
            params.returns_annotation = Some(ann);
            continue;
        }
        let mut found = false;
        for p in params.args.iter_mut() {
            if p.name == name {
                p.annotation = Some(ann.clone());
                found = true;
            }
        }
        for p in params.kwonly.iter_mut() {
            if p.name == name {
                p.annotation = Some(ann.clone());
                found = true;
            }
        }
        if let Some(p) = params.vararg.as_mut() {
            if p.name == name {
                p.annotation = Some(ann.clone());
                found = true;
            }
        }
        if let Some(p) = params.kwarg.as_mut() {
            if p.name == name {
                p.annotation = Some(ann.clone());
                found = true;
            }
        }
        let _ = found;
    }
    // tuple form
    if let Expr::Const(o) = &**value {
        if let PyObject::Tuple(items) = &**o {
            if items.len() == 2 {
                if let (PyObject::Tuple(ns), PyObject::Tuple(vs)) = (&*items[0], &*items[1]) {
                    for (n, v) in ns.iter().zip(vs.iter()) {
                        if let PyObject::Str(name) = &**n {
                            let ann: ExprRef = Rc::new(Expr::Const(v.clone()));
                            if name == "return" {
                                params.returns_annotation = Some(ann);
                                continue;
                            }
                            for p in params.args.iter_mut() {
                                if p.name == *name {
                                    p.annotation = Some(ann.clone());
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fn binop_from_text(op_text: &str) -> BinaryOp {
    match op_text {
        "+" => BinaryOp::Add,
        "-" => BinaryOp::Sub,
        "*" => BinaryOp::Mult,
        "/" => BinaryOp::Div,
        "//" => BinaryOp::FloorDiv,
        "%" => BinaryOp::Mod,
        "**" => BinaryOp::Pow,
        "<<" => BinaryOp::LShift,
        ">>" => BinaryOp::RShift,
        "|" => BinaryOp::BitOr,
        "^" => BinaryOp::BitXor,
        "&" => BinaryOp::BitAnd,
        "@" => BinaryOp::MatMult,
        _ => BinaryOp::Add,
    }
}

fn dotted_last(module: &str) -> &str {
    module.rsplit('.').next().unwrap_or(module)
}

/// py2 names synthetic tuple-parameter locals `.0`, `.1`, ...; these are
/// not valid identifiers — rename to `_0`, `_1` when they leak through
/// without being folded back into `(a, b)` signature form.
fn sanitize_varname(n: &str) -> String {
    if n.starts_with('.') {
        n.replace('.', "_")
    } else {
        n.to_string()
    }
}

/// Render an unpack target as py2 tuple-parameter text: `(a, b)`.
fn tuple_param_text(e: &ExprRef) -> Option<String> {
    match &**e {
        Expr::Name(n) => Some(n.clone()),
        Expr::Tuple(items) => {
            let mut parts = Vec::new();
            for it in items {
                parts.push(tuple_param_text(it)?);
            }
            Some(format!("({})", parts.join(", ")))
        }
        _ => None,
    }
}

/// py2 `def f((a, b))`: the compiler creates a synthetic `.N` parameter
/// and emits the unpack `a, b = _N` at the body's head. Fold the unpacks
/// back into the signature (valid py2 tuple-param syntax) and drop the
/// statements. `varnames` are the code object's raw locals (params were
/// already sanitized to `_N`).
fn fold_py2_tuple_params(params: &mut Parameters, varnames: &[String], body: &mut Vec<Stmt>) {
    for (pi, p) in params.args.iter_mut().enumerate() {
        if !varnames.get(pi).map_or(false, |n| n.starts_with('.')) {
            continue;
        }
        let san = sanitize_varname(varnames.get(pi).map(|s| s.as_str()).unwrap_or(""));
        let mut found = None;
        for (bi, stmt) in body.iter().enumerate().take(8) {
            if let Stmt::Assign { targets, value, .. } = stmt {
                if targets.len() == 1 && matches!(&**value, Expr::Name(n) if *n == san) {
                    if let Some(text) = tuple_param_text(&targets[0]) {
                        found = Some((bi, text));
                        break;
                    }
                }
            }
        }
        if let Some((bi, text)) = found {
            p.name = text;
            body.remove(bi);
        }
    }
}

/// Cleanup applied to a decompiled function/module body:
/// * drop synthetic `__qualname__` / `__module__` assignments (class bodies)
/// * convert leading `__doc__ = 'x'` assignments into docstring statements
/// * drop a trailing `return None` in function bodies
/// Conservative structural equality for the statements that can appear
/// in a compiler-duplicated tail (assignments, expression statements,
/// returns, imports, simple control flow). Anything exotic -> false.
fn stmt_eq(a: &Stmt, b: &Stmt) -> bool {
    match (a, b) {
        (Stmt::Expr(x), Stmt::Expr(y)) => expr_eq(x, y),
        (
            Stmt::Assign {
                targets: t1,
                value: v1,
                ..
            },
            Stmt::Assign {
                targets: t2,
                value: v2,
                ..
            },
        ) => {
            t1.len() == t2.len()
                && t1.iter().zip(t2.iter()).all(|(x, y)| expr_eq(x, y))
                && expr_eq(v1, v2)
        }
        (Stmt::Return(x), Stmt::Return(y)) => match (x, y) {
            (None, None) => true,
            (Some(a), Some(b)) => expr_eq(a, b),
            _ => false,
        },
        (Stmt::Pass, Stmt::Pass) | (Stmt::Break, Stmt::Break) | (Stmt::Continue, Stmt::Continue) => {
            true
        }
        (
            Stmt::Import { names: n1 },
            Stmt::Import { names: n2 },
        ) => n1 == n2,
        (
            Stmt::ImportFrom {
                module: m1,
                level: l1,
                names: n1,
            },
            Stmt::ImportFrom {
                module: m2,
                level: l2,
                names: n2,
            },
        ) => m1 == m2 && l1 == l2 && n1 == n2,
        (Stmt::Global(g1), Stmt::Global(g2)) => g1 == g2,
        (Stmt::Nonlocal(g1), Stmt::Nonlocal(g2)) => g1 == g2,
        (
            Stmt::If {
                cond: c1,
                body: b1,
                orelse: o1,
            },
            Stmt::If {
                cond: c2,
                body: b2,
                orelse: o2,
            },
        ) => expr_eq(c1, c2) && stmts_eq(b1, b2) && stmts_eq(o1, o2),
        _ => false,
    }
}

fn stmts_eq(a: &[Stmt], b: &[Stmt]) -> bool {
    a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| stmt_eq(x, y))
}

fn ends_scope(s: &Stmt) -> bool {
    matches!(
        s,
        Stmt::Return(_) | Stmt::Raise { .. } | Stmt::Break | Stmt::Continue
    )
}

/// 3.12+ tail-position try: instead of jumping back to the mainline
/// continuation, the compiler sinks a copy of it into the last handler
/// after POP_EXCEPT (datetime/decimal `try: from _x import * except
/// ImportError: from _y import *` + module tail). The sub-walk emits
/// the sunk copy inside the handler AND the mainline walk emits it
/// again after the try. Strip the duplication: when the last handler's
/// body ends with exactly the statements that follow the try through
/// the END of the enclosing scope, and that tail is terminator-shaped
/// (a source-level duplicate could not end the scope), the handler
/// copy is the compiler artifact.
fn dedup_sunk_handler_tails(stmts: &mut Vec<Stmt>, scope_end_open: bool) {
    for s in stmts.iter_mut() {
        match s {
            Stmt::Try {
                body,
                handlers,
                orelse,
                finalbody,
            } => {
                dedup_sunk_handler_tails(body, false);
                for h in handlers.iter_mut() {
                    dedup_sunk_handler_tails(&mut h.body, false);
                }
                dedup_sunk_handler_tails(orelse, false);
                dedup_sunk_handler_tails(finalbody, false);
            }
            Stmt::If { body, orelse, .. }
            | Stmt::While { body, orelse, .. }
            | Stmt::For { body, orelse, .. } => {
                dedup_sunk_handler_tails(body, false);
                dedup_sunk_handler_tails(orelse, false);
            }
            _ => {}
        }
    }
    let n = stmts.len();
    for i in 0..n.saturating_sub(1) {
        // the tail must run to the end of the enclosing scope: either
        // terminator-shaped, or the module top level (whose implicit
        // `return None` never becomes a statement)
        let tail = &stmts[i + 1..];
        if tail.is_empty() || !(ends_scope(tail.last().unwrap()) || scope_end_open) {
            continue;
        }
        let (k, hlen) = {
            let Stmt::Try {
                handlers,
                finalbody,
                ..
            } = &stmts[i]
            else {
                continue;
            };
            if !finalbody.is_empty() {
                continue;
            }
            let Some(last) = handlers.last() else {
                continue;
            };
            if last.is_star {
                continue;
            }
            let mut k = 0;
            while k < tail.len() && k < last.body.len() {
                let x = &last.body[last.body.len() - 1 - k];
                let y = &tail[k];
                if !stmt_eq(x, y) {
                    break;
                }
                k += 1;
            }
            (k, last.body.len())
        };
        if k >= 1 && k <= hlen {
            if let Stmt::Try { handlers, .. } = &mut stmts[i] {
                if let Some(last) = handlers.last_mut() {
                    last.body.truncate(hlen - k);
                    if last.body.is_empty() {
                        last.body.push(Stmt::Pass);
                    }
                }
            }
        }
        let _ = hlen;
    }
}

/// Sig fidelity for flattened terminal if/else chains: when the source's
/// last statement was an if/else whose arms all return, the compiler
/// appends the implicit `LOAD None; RETURN` pair (it cannot prove the
/// arms exhaustive). A terminal then-arm makes the compiler omit the
/// else jump, so the walk flattens the else to sequential statements
/// ending in the arm's own `return v` — recompiling that flat form
/// drops the tail pair and the sig misses its last two lines
/// (_dummy_thread 3.3 acquire). True when the instruction tail shows
/// the pair right after a preceding return; the caller (after ALL body
/// postprocessing — postprocess_body runs twice and its tail-return
/// strip would eat the synthesized statement) appends an explicit
/// `return None` only if the body still ends in a value return.
/// Offset of the implicit tail pair's first instruction when the code's
/// instruction tail is `RETURN; LOAD None; RETURN` (<=3.11) or
/// `RETURN; RETURN_CONST None` (3.12+) — the pair proves the source's
/// last statement was an if/else whose arms all return (a flat chain of
/// terminal-armed ifs recompiles without the pair). None for modules,
/// lambdas and generators.
fn tail_pair_load_offset(
    code: &CodeObject,
    instrs: &[Instruction],
    version: PythonVersion,
) -> Option<usize> {
    if code.name == "<module>"
        || code.name == "<lambda>"
        || code.is_generator()
        || code.is_async_generator()
    {
        return None;
    }
    // 3.10+ sinks `return None` copies per ending branch/try arm —
    // adjacent copies at the code end forge the tail-pair signature for
    // shapes that never had an implicit pair (if c: try/finally), and
    // the rebuild then misfires badly (aifc 3.11 +653). 3.8/3.9 still
    // emit the genuine shared pair (_dummy_thread acquire ends
    // `RETURN False; LOAD None; RETURN`).
    if version.at_least(3, 10) {
        return None;
    }
    let is_none_load = |i: usize| {
        instrs[i].op == Op::LOAD_CONST
            && matches!(
                code.consts.get(instrs[i].arg as usize).map(|o| &**o),
                Some(PyObject::None)
            )
    };
    let is_ret = |i: usize| matches!(instrs[i].op, Op::RETURN_VALUE | Op::RETURN_CONST);
    let n = instrs.len();
    // pair: RETURN; LOAD None; RETURN (the LOAD sits between the two)
    if n >= 3 && is_ret(n - 3) && is_none_load(n - 2) && is_ret(n - 1) {
        return Some(instrs[n - 2].offset);
    }
    None
}

fn bytecode_tail_return_pair(
    code: &CodeObject,
    instrs: &[Instruction],
    version: PythonVersion,
) -> bool {
    tail_pair_load_offset(code, instrs, version).is_some()
}

fn postprocess_body(mut body: Vec<Stmt>, code: &CodeObject) -> Vec<Stmt> {
    // 3.6+ evaluates module/class-body annotations into the scope's
    // `__annotations__` dict (`x: T = v` -> STORE x; T; LOAD
    // __annotations__; LOAD 'x'; STORE_SUBSCR). The walk renders these
    // as raw subscript assigns, which recompile WITHOUT the leading
    // SETUP_ANNOTATIONS (3.7+ class / 3.10+ module scope) the original
    // bytecode had. Fold each `__annotations__['x'] = T` back into an
    // AnnAssign, merging an immediately preceding `x = v` into the
    // value slot so the recompiler reproduces both stores and the
    // SETUP_ANNOTATIONS prologue.
    {
        let mut i = 0;
        while i < body.len() {
            let key = match &body[i] {
                Stmt::Assign { targets, value, .. } if targets.len() == 1 => {
                    match &*targets[0] {
                        Expr::Subscript { value: base, index } => {
                            let is_ann_dict = matches!(&**base, Expr::Name(n) if n == "__annotations__");
                            let key = match &**index {
                                Expr::Const(o) => match &**o {
                                    PyObject::Str(s) => Some(s.clone()),
                                    _ => None,
                                },
                                _ => None,
                            };
                            if is_ann_dict { key.map(|k| (k, value.clone())) } else { None }
                        }
                        _ => None,
                    }
                }
                _ => None,
            };
            let Some((name, ann)) = key else {
                i += 1;
                continue;
            };
            // merge an immediately preceding plain assign to the same name
            let mut merged_value: Option<ExprRef> = None;
            if i > 0 {
                if let Stmt::Assign { targets, value, .. } = &body[i - 1] {
                    if targets.len() == 1
                        && matches!(&*targets[0], Expr::Name(n) if *n == name)
                    {
                        merged_value = Some(value.clone());
                    }
                }
            }
            let has_value = merged_value.is_some();
            let ann_stmt = Stmt::AnnAssign {
                target: Rc::new(Expr::Name(name)),
                annotation: ann,
                value: merged_value,
            };
            if has_value {
                body.remove(i - 1);
                body[i - 1] = ann_stmt;
            } else {
                body[i] = ann_stmt;
            }
            i += 1;
        }
    }
    // __module__ / __qualname__ / __doc__ handling for class bodies
    let mut idx = 0;
    while idx < body.len() {
        let mut remove = false;
        if let Stmt::Assign { targets, value, .. } = &body[idx] {
            if targets.len() == 1 {
                if let Expr::Name(n) = &*targets[0] {
                    if n == "__module__" {
                        if let Expr::Name(_) | Expr::Const(_) = &**value {
                            remove = true;
                        }
                    } else if n == "__qualname__" {
                        if let Expr::Const(_) = &**value {
                            remove = true;
                        }
                    } else if n == "__classcell__"
                        || n == "__classdictcell__"
                        || n == "__classdict__"
                        || n == "__firstlineno__"
                        || n == "__static_attributes__"
                    {
                        remove = true;
                    } else if n == "__doc__" {
                        if let Expr::Const(o) = &**value {
                            if matches!(&**o, PyObject::Str(_) | PyObject::Bytes(_) | PyObject::None) {
                                // rewrite as docstring const expr
                                body[idx] = Stmt::Expr(Rc::new(Expr::Const(o.clone())));
                            }
                        }
                    }
                }
            }
        }
        if remove {
            body.remove(idx);
        } else {
            idx += 1;
        }
    }
    // 3.11+ emits the finally body twice (inline sunk flow + handler);
    // the walk renders the sunk copy right after the Try — drop statements
    // immediately following a Try that mirror its finalbody exactly
    {
        let mut i = 0;
        while i < body.len() {
            let fin_dbg: Option<Vec<String>> = match &body[i] {
                Stmt::Try { finalbody, .. } if !finalbody.is_empty() => Some(
                    finalbody.iter().map(|s| format!("{s:?}")).collect(),
                ),
                _ => None,
            };
            if let Some(fin_dbg) = fin_dbg {
                let mut j = i + 1;
                let mut k = 0;
                while j < body.len()
                    && k < fin_dbg.len()
                    && format!("{:?}", body[j]) == fin_dbg[k]
                {
                    j += 1;
                    k += 1;
                }
                if k == fin_dbg.len() && j > i + 1 {
                    body.drain(i + 1..j);
                }
            }
            i += 1;
        }
    }
    // trailing `return None` — including the tail-position copies the
    // compiler sinks into ending `if` branches (3.11+ emits one
    // RETURN_CONST None per ending branch: `if c: try:.. finally:..`
    // leaks a spurious `return` after the try inside the then-arm)
    if code.name != "<module>" && code.name != "<lambda>" {
        // does this statement list end in an explicit `return <value>`
        // (a non-None return)?
        fn ends_value_return(stmts: &[Stmt]) -> bool {
            matches!(stmts.last(), Some(Stmt::Return(Some(_))))
        }
        fn strip_tail_returns(stmts: &mut Vec<Stmt>) {
            loop {
                match stmts.last_mut() {
                    Some(Stmt::Return(None)) => {
                        stmts.pop();
                    }
                    Some(Stmt::If { body, orelse, .. }) => {
                        // A trailing `return None` in one arm is the
                        // compiler's sunk copy of the function's implicit
                        // tail ONLY when no arm returns a value. When a
                        // sibling arm ends in `return <value>`, the if/else
                        // is a genuine value-returning branch pair: each
                        // arm's return is EXPLICIT source, so a `return
                        // None` arm must be KEPT (stripping it drops the
                        // arm's result and lets flow fall through to the
                        // sibling/continuation - _osx_support
                        // _find_executable returned `executable` instead of
                        // None when the search loop found nothing; the
                        // explicit return is the function's last statement
                        // so it is NOT recoverable as an implicit tail).
                        let keep = ends_value_return(body)
                            || ends_value_return(orelse);
                        if !keep {
                            strip_tail_returns(body);
                            strip_tail_returns(orelse);
                        }
                        return;
                    }
                    _ => return,
                }
            }
        }
        strip_tail_returns(&mut body);
    }
    // class bodies using zero-arg super() end with `return __class__`
    // (3.13+: an unnamed cell local shows up as a bad-local marker)
    if let Some(Stmt::Return(Some(e))) = body.last() {
        if let Expr::Name(n) = &**e {
            if n == "__class__" || n.contains("bad-local") || n.contains("__class") {
                body.pop();
            }
        }
    }
    // 3.12+ sunk-tail duplication in tail-position try handlers
    let is_module = code.name == "<module>";
    dedup_sunk_handler_tails(&mut body, is_module);
    // empty-generator idiom: CPython dead-code-eliminates an unreachable
    // `while False: yield None` (the canonical empty generator, e.g.
    // _collections_abc Iterable.__iter__) leaving only the generator flag —
    // a rendered body without any yield would turn the generator function
    // into a plain function (iter()/next() break with TypeError).
    // Synthesize the canonical unreachable yield to preserve generator-ness.
    if (code.is_generator() || code.is_async_generator())
        && code.name != "<module>"
        && !stmts_contain_yield(&body)
    {
        if matches!(body.last(), Some(Stmt::Pass)) {
            body.pop();
        }
        body.push(Stmt::While {
            cond: Rc::new(Expr::Const(Rc::new(PyObject::False))),
            body: vec![Stmt::Expr(Rc::new(Expr::Yield(Some(Rc::new(
                Expr::Const(Rc::new(PyObject::None)),
            )))))],
            orelse: Vec::new(),
        });
    }
    body
}

/// True when any yield/yield-from expression occurs in these statements
/// (nested function/class bodies excluded — their yields belong to them).
fn stmts_contain_yield(stmts: &[Stmt]) -> bool {
    fn expr_has_yield(e: &ExprRef) -> bool {
        match &**e {
            Expr::Yield(_) | Expr::YieldFrom(_) => true,
            Expr::Unary { operand, .. } => expr_has_yield(operand),
            Expr::Binary { left, right, .. }
            | Expr::Named { target: left, value: right } => {
                expr_has_yield(left) || expr_has_yield(right)
            }
            Expr::BoolOp { values, .. }
            | Expr::Compare { operands: values, .. }
            | Expr::Tuple(values)
            | Expr::List(values)
            | Expr::Set(values) => values.iter().any(expr_has_yield),
            Expr::Call {
                func,
                args,
                keywords,
                star_args,
                star_kwargs,
            } => {
                expr_has_yield(func)
                    || args.iter().any(expr_has_yield)
                    || keywords.iter().any(|(_, v)| expr_has_yield(v))
                    || star_args.as_ref().map_or(false, |s| expr_has_yield(s))
                    || star_kwargs.as_ref().map_or(false, |s| expr_has_yield(s))
            }
            Expr::Ternary {
                cond,
                then_expr,
                else_expr,
            } => {
                expr_has_yield(cond)
                    || expr_has_yield(then_expr)
                    || expr_has_yield(else_expr)
            }
            Expr::Subscript { value, index } => {
                expr_has_yield(value) || expr_has_yield(index)
            }
            Expr::Attribute { value, .. } => expr_has_yield(value),
            Expr::Starred(v) => expr_has_yield(v),
            _ => false,
        }
    }
    stmts.iter().any(|s| match s {
        Stmt::Expr(e) => expr_has_yield(e),
        Stmt::Assign { targets, value, .. } => {
            expr_has_yield(value) || targets.iter().any(expr_has_yield)
        }
        Stmt::AugAssign { value, .. } => expr_has_yield(value),
        Stmt::AnnAssign { value, .. } => {
            value.as_ref().map_or(false, |v| expr_has_yield(v))
        }
        Stmt::Return(e) => e.as_ref().map_or(false, expr_has_yield),
        Stmt::Delete(es) => es.iter().any(expr_has_yield),
        Stmt::If { cond, body, orelse }
        | Stmt::While { cond, body, orelse } => {
            expr_has_yield(cond)
                || stmts_contain_yield(body)
                || stmts_contain_yield(orelse)
        }
        Stmt::For {
            target,
            iter,
            body,
            orelse,
            ..
        } => {
            expr_has_yield(target)
                || expr_has_yield(iter)
                || stmts_contain_yield(body)
                || stmts_contain_yield(orelse)
        }
        Stmt::Try {
            body,
            handlers,
            orelse,
            finalbody,
        } => {
            stmts_contain_yield(body)
                || handlers.iter().any(|h| stmts_contain_yield(&h.body))
                || stmts_contain_yield(orelse)
                || stmts_contain_yield(finalbody)
        }
        Stmt::With { items, body, .. } => {
            stmts_contain_yield(body)
                || items.iter().any(|it| {
                    expr_has_yield(&it.ctx)
                        || it.target.as_ref().map_or(false, |v| expr_has_yield(v))
                })
        }
        Stmt::Raise { exc, cause, .. } => {
            exc.as_ref().map_or(false, |e| expr_has_yield(e))
                || cause.as_ref().map_or(false, |e| expr_has_yield(e))
        }
        Stmt::Assert { test, msg } => {
            expr_has_yield(test)
                || msg.as_ref().map_or(false, |m| expr_has_yield(m))
        }
        Stmt::Match { subject, cases } => {
            expr_has_yield(subject)
                || cases.iter().any(|c| {
                    c.guard.as_ref().map_or(false, |g| expr_has_yield(g))
                        || stmts_contain_yield(&c.body)
                })
        }
        // yields inside a nested def/class belong to THAT scope
        _ => false,
    })
}


// =====================  match/case (3.10+)  =====================

impl<'a> Ctx<'a> {
    /// 3.10+ match statement entry: at a case-head instruction with the
    /// subject on the value stack, parse the whole match region, emit it
    /// as one statement and skip the walked bytecode.
    fn try_parse_match(&mut self) -> bool {
        if !self.version.at_least(3, 10) {
            return false;
        }
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return false;
        };
        // No-dup first case: `match subject: case Cls(...)` with a single
        // non-wildcard case has no COPY/DUP before the class load, so the
        // main loop already consumed `LOAD cls` + `LOAD_CONST names` and the
        // stack is [subject, cls, names]. (When a dup IS present, this fn is
        // triggered from the COPY/DUP op, so ci points there, not here.)
        // Recover cls (parse_match_class can't re-simulate consumed ops) and
        // leave subject on top so the normal head/subject checks apply.
        if self.instrs[ci].op == Op::MATCH_CLASS
            && ci > 0
            && matches!(self.instrs.get(ci - 1).map(|x| x.op), Some(Op::LOAD_CONST))
            && self.stack.len() >= 3
        {
            let names = self.pop_expr(); // names tuple const (read from bytecode instead)
            let _ = names;
            let cls = self.pop_expr(); // skips a NULL marker if LOAD cls pushed one
            self.pending_match_class = Some(cls);
        }
        let head_ok = self.match_case_head_at(ci);
        if !head_ok {
            self.pending_match_class = None;
            return false;
        }
        // the subject must already be evaluated
        if !matches!(self.stack.last(), Some(Sv::E(_))) {
            self.pending_match_class = None;
            return false;
        }
        // parse on a trial basis: the region parser must consume at least
        // one case and produce a bounded end offset
        let subject = match self.stack.last() {
            Some(Sv::E(e)) => e.clone(),
            _ => {
                self.pending_match_class = None;
                return false;
            }
        };
        let Some((stmt, end_off)) = self.parse_match_region(subject, ci) else {
            self.pending_match_class = None;
            return false;
        };
        self.pop();
        self.flush_pending_stores();
        self.push_stmt(stmt);
                self.skip_until = Some(end_off);
        true
    }

    /// True when `instrs[i..]` begins a match case head: an optional
    /// subject-preserving dup, then a recognizable pattern test.
    fn match_case_head_at(&self, i: usize) -> bool {
        let mut k = i;
        // last-case value tests consume the subject directly (no dup)
        let mut dup_seen = false;
        while matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::DUP_TOP) | Some(Op::COPY)
        ) {
            if matches!(self.instrs.get(k).map(|x| x.op), Some(Op::COPY))
                && self.instrs[k].arg != 1
            {
                break;
            }
            dup_seen = true;
            k += 1;
        }
        let _ = dup_seen;
        matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::MATCH_SEQUENCE) | Some(Op::MATCH_MAPPING)
        ) || self.match_class_head_at(k)
            || self.match_value_head_at(k)
    }

    /// `LOAD cls...; LOAD_CONST <names tuple>; MATCH_CLASS` at k
    fn match_class_head_at(&self, k: usize) -> bool {
        let mut j = k;
        let mut steps = 0;
        while let Some(ins) = self.instrs.get(j) {
            if ins.op == Op::MATCH_CLASS {
                // `j >= k`: a no-dup first case (`match s: case Cls(...)`)
                // has the cls/names already consumed by the main loop, so
                // MATCH_CLASS sits at the head (j == k); the names tuple is
                // still verifiable at instrs[j-1].
                return matches!(self.instrs.get(j - 1).map(|x| x.op), Some(Op::LOAD_CONST))
                    && self
                        .code
                        .consts
                        .get(self.instrs[j - 1].arg as usize)
                        .map_or(false, |c| matches!(&**c, PyObject::Tuple(_)));
            }
            if !is_pure_value_op(ins.op) || steps > 8 {
                return false;
            }
            j += 1;
            steps += 1;
        }
        false
    }

    /// `<pure value ops>; COMPARE_OP ==; PJIF` at k (a value-pattern test)
    fn match_value_head_at(&self, k: usize) -> bool {
        // `case None:` — the head is the NOT_NONE jump itself
        if matches!(
            self.instrs.get(k).map(|x| x.op),
            Some(Op::POP_JUMP_IF_NOT_NONE) | Some(Op::POP_JUMP_FORWARD_IF_NOT_NONE)
        ) {
            return true;
        }
        let mut j = k;
        let mut steps = 0;
        while let Some(ins) = self.instrs.get(j) {
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                // the instruction before (through padding) must be
                // COMPARE_OP == or an identity IS_OP (singletons)
                return j > k
                    && self.match_prev_real(j).map_or(false, |pj| {
                        (matches!(self.instrs[pj].op, Op::COMPARE_OP)
                            && cmp_from_index(compare_op_index(
                                self.instrs[pj].arg as u32,
                                self.version,
                            )) == CmpOp::Eq)
                            || (self.instrs[pj].op == Op::IS_OP
                                && self.instrs[pj].arg == 0)
                    });
            }
            if (!is_pure_value_op(ins.op) && ins.op != Op::IS_OP) || steps > 24 {
                return false;
            }
            j += 1;
            steps += 1;
        }
        false
    }

    /// Index of the previous non-padding instruction before `j`.
    fn match_prev_real(&self, j: usize) -> Option<usize> {
        let mut k = j;
        while k > 0 {
            k -= 1;
            if !matches!(
                self.instrs[k].op,
                Op::NOP | Op::NOT_TAKEN | Op::CACHE | Op::EXTENDED_ARG
            ) {
                return Some(k);
            }
        }
        None
    }

    /// The literal operand of the `CMP ==` right before instruction `i`
    /// (a value sub-pattern check inside a class pattern).
    fn match_prev_value_const(&self, i: usize) -> Option<ExprRef> {
        let cj = self.match_prev_real(i)?;
        if self.instrs[cj].op != Op::COMPARE_OP {
            return None;
        }
        let li = self.match_prev_real(cj)?;
        let ins = &self.instrs[li];
        match ins.op {
            Op::LOAD_CONST => Some(Rc::new(Expr::Const(
                self.code.consts.get(ins.arg as usize)?.clone(),
            ))),
            Op::LOAD_SMALL_INT => Some(Rc::new(Expr::Const(Rc::new(PyObject::Int(
                ins.arg as i32,
            ))))),
            _ => None,
        }
    }

    /// Advance past compiler padding.
    fn match_skip_pad(&self, i: &mut usize) {
        while matches!(
            self.instrs.get(*i).map(|x| x.op),
            Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE) | Some(Op::EXTENDED_ARG)
        ) {
            *i += 1;
        }
    }

    /// Parse one pattern test starting at `i` (after the case-head dups).
    /// Returns (pattern, fail_offset, next_idx).
    fn parse_match_pattern(
        &mut self,
        i: usize,
        boundary: Option<usize>,
    ) -> Option<(Pattern, usize, usize)> {
        let ins = self.instrs.get(i)?;
        match ins.op {
            Op::MATCH_SEQUENCE => self.parse_match_sequence(i),
            Op::MATCH_MAPPING => self.parse_match_mapping(i),
            _ => {
                if self.match_class_head_at(i) {
                    self.parse_match_class(i)
                } else {
                    self.parse_match_value(i, boundary)
                }
            }
        }
    }

    /// One or more `COPY/DUP; <value>; CMP ==; PJIF` arms. Or-arms chain:
    /// an arm's fail target that is itself a case head continues the OR.
    fn parse_match_value(
        &mut self,
        i0: usize,
        boundary: Option<usize>,
    ) -> Option<(Pattern, usize, usize)> {
        let mut arms: Vec<Pattern> = Vec::new();
        let mut i = i0;
        let mut fail;
        let mut body_start: Option<usize> = None;
        loop {
            self.match_skip_pad(&mut i);
            // optional per-arm subject dup
            while matches!(
                self.instrs.get(i).map(|x| x.op),
                Some(Op::DUP_TOP) | Some(Op::COPY)
            ) && (self.instrs[i].op == Op::DUP_TOP || self.instrs[i].arg == 1)
            {
                i += 1;
                self.match_skip_pad(&mut i);
            }
            // `case None:` — the test IS the jump (3.10+)
            if matches!(
                self.instrs.get(i).map(|x| x.op),
                Some(Op::POP_JUMP_IF_NOT_NONE) | Some(Op::POP_JUMP_FORWARD_IF_NOT_NONE)
            ) {
                arms.push(Pattern::Value(Rc::new(Expr::Const(Rc::new(
                    PyObject::None,
                )))));
                fail = self.instrs[i].target?;
                i += 1;
                self.match_skip_pad(&mut i);
                if let Some(ins) = self.instrs.get(i) {
                    if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                        && ins.target.map_or(false, |t| t > ins.offset)
                    {
                        if body_start.is_none() {
                            body_start = Some(ins.target.unwrap());
                        }
                        i += 1;
                    }
                }
                let Some(&fi) = self.idx_of.get(&fail) else {
                    break;
                };
                let mut fk = fi;
                self.match_skip_pad(&mut fk);
                let within = match boundary {
                    Some(b) => self.instrs[fk].offset < b,
                    None => false,
                };
                let continues = within && self.match_case_head_at(fk);
                if !continues {
                    break;
                }
                i = fk;
                fail = 0;
                continue;
            }
            // scan the value region up to its terminating cond jump
            let region_start = i;
            let mut j = i;
            let mut jidx = None;
            while let Some(ins) = self.instrs.get(j) {
                if matches!(
                    ins.op,
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                ) && j > region_start
                    && self.match_prev_real(j).map_or(false, |pj| {
                        pj >= region_start
                            && (matches!(self.instrs[pj].op, Op::COMPARE_OP)
                                && cmp_from_index(compare_op_index(
                                    self.instrs[pj].arg as u32,
                                    self.version,
                                )) == CmpOp::Eq
                                // singleton patterns (True/False) test
                                // by identity
                                || (self.instrs[pj].op == Op::IS_OP
                                    && self.instrs[pj].arg == 0))
                    })
                {
                    jidx = Some(j);
                    break;
                }
                if !is_pure_value_op(ins.op) && self.instrs[j].op != Op::IS_OP {
                    return None;
                }
                j += 1;
                if j - i > 24 {
                    return None;
                }
            }
            let jk = jidx?;
            // the region ends at the COMPARE_OP; the pattern value is its
            // left operand (the subject side stays unconsumed)
            let cmp_idx = self.match_prev_real(jk)?;
            let value = self.sim_value_region(region_start, cmp_idx)?;
            arms.push(Pattern::Value(value));
            fail = self.instrs[jk].target?;
            i = jk + 1;
            // 3.11+ or-arms: arm success jumps to a shared success block
            // (POP cleanups then the case body); record the first one as
            // the body start
            self.match_skip_pad(&mut i);
            if let Some(ins) = self.instrs.get(i) {
                if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                    && ins.target.map_or(false, |t| t > ins.offset)
                {
                    if body_start.is_none() {
                        body_start = Some(ins.target.unwrap());
                    }
                    i += 1;
                }
            }
            // another or-arm?
            let Some(&fi) = self.idx_of.get(&fail) else {
                break;
            };
            let mut fk = fi;
            self.match_skip_pad(&mut fk);
            // An or-arm's fail target stays INSIDE this case's span
            // (before the next case head / cleanup boundary); a fail
            // target AT the boundary is the next case.
            // 3.11+ shared-success or-chain: every non-final arm's
            // success JUMP_FORWARD hops to the shared body block, and
            // its fail target IS the next or-arm — which the region's
            // boundary scan flagged as the next case head, so it lands
            // exactly AT the boundary. A single-pattern case has no
            // success hop (fall-through into the body), so the hop is
            // the or-chain discriminator (_strptime 3.13 repl
            // `case 'Y' | 'y' | 'G':` split into three duplicated cases)
            let arm_has_success_hop = body_start.is_some();
            let within = if let Some(bs) = body_start {
                // or-chain: every arm fails FORWARD to the next arm and
                // all arms live before the shared success block — the
                // boundary (first flagged case head) is arm 2 itself, so
                // chain links are bounded by body_start instead
                self.instrs[fk].offset < bs
            } else {
                match boundary {
                    Some(b) => self.instrs[fk].offset < b,
                    None => false,
                }
            };
            let _ = arm_has_success_hop;
            let continues = within
                && self.instrs[fk].offset > self.instrs[jk].offset
                && self.match_case_head_at(fk);
            if !continues {
                break;
            }
            i = fk;
            fail = 0;
        }
        if arms.is_empty() {
            return None;
        }
        let pattern = if arms.len() == 1 {
            arms.pop().unwrap()
        } else {
            Pattern::Or(arms)
        };
        if let Some(bs) = body_start {
            if let Some(&bi) = self.idx_of.get(&bs) {
                return Some((pattern, fail, bi));
            }
        }
        Some((pattern, fail, i))
    }

    /// Sequence pattern: MATCH_SEQUENCE; PJIF; GET_LEN; n; CMP; PJIF;
    /// UNPACK_SEQUENCE/UNPACK_EX; per-element literal tests + capture
    /// stores.
    fn parse_match_sequence(&mut self, i0: usize) -> Option<(Pattern, usize, usize)> {
        let mut i = i0 + 1;
        self.match_skip_pad(&mut i);
        // first PJIF (type test)
        if !matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE) | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
        ) {
            return None;
        }
        let fail = self.instrs[i].target?;
        i += 1;
        self.match_skip_pad(&mut i);
        // GET_LEN; n; CMP (== fixed length / >= star); PJIF same fail
        if self.instrs.get(i).map(|x| x.op) != Some(Op::GET_LEN) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        let star_len = match self.instrs.get(i).map(|x| x.op) {
            Some(Op::LOAD_CONST) => false,
            Some(Op::LOAD_SMALL_INT) => false,
            _ => return None,
        };
        let _ = star_len;
        let len_ins = self.instrs[i];
        let min_len = if len_ins.op == Op::LOAD_SMALL_INT {
            len_ins.arg as usize
        } else {
            match &*self.code.consts.get(len_ins.arg as usize)?.clone() {
                PyObject::Int(v) => (*v).max(0) as usize,
                _ => return None,
            }
        };
        i += 1;
        self.match_skip_pad(&mut i);
        let star = match self.instrs.get(i).map(|x| x.op) {
            Some(Op::COMPARE_OP) => {
                let c = cmp_from_index(compare_op_index(self.instrs[i].arg as u32, self.version));
                match c {
                    CmpOp::GtE => true,
                    CmpOp::Eq => false,
                    _ => return None,
                }
            }
            _ => return None,
        };
        i += 1;
        self.match_skip_pad(&mut i);
        if !matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE) | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
        ) {
            return None;
        }
        if self.instrs[i].target? != fail {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        // unpack + element handling
        let mut items: Vec<Pattern> = Vec::new();
        let mut star_pat: Option<(Pattern, usize)> = None;
        match self.instrs.get(i).map(|x| x.op) {
            Some(Op::POP_TOP) if min_len == 0 => {
                // empty sequence pattern `case []:` — no unpack; one
                // POP_TOP drops the sequence, the subject dup pops at
                // the case boundary like every other case
                i += 1;
            }
            Some(Op::UNPACK_SEQUENCE) => {
                let n = self.instrs[i].arg as usize;
                i += 1;
                let mut elem_done = 0usize;
                while elem_done < n {
                    elem_done += 1;
                    self.match_skip_pad(&mut i);
                    match self.instrs.get(i)?.op {
                        Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL | Op::STORE_NAME => {
                            let name = if self.instrs[i].op == Op::STORE_NAME {
                                self.const_name(self.instrs[i].arg as usize)
                            } else {
                                self.local_name(self.instrs[i].arg as usize)
                            };
                            i += 1;
                            items.push(if name == "_" {
                                Pattern::Wildcard
                            } else {
                                Pattern::Capture(name)
                            });
                        }
                        Op::STORE_FAST_LOAD_FAST => {
                            // capture that also re-loads (guard follows)
                            let name =
                                self.local_name(((self.instrs[i].arg >> 4) & 0xF) as usize);
                            i += 1;
                            items.push(Pattern::Capture(name));
                        }
                        Op::STORE_FAST_STORE_FAST => {
                            // 3.13+ paired store: consumes TWO elements.
                            // The loop counts elements, so handle the pair
                            // by pushing both and bumping the counter.
                            let a = self.local_name(((self.instrs[i].arg >> 4) & 0xF) as usize);
                            let b = self.local_name((self.instrs[i].arg & 0xF) as usize);
                            i += 1;
                            items.push(if a == "_" {
                                Pattern::Wildcard
                            } else {
                                Pattern::Capture(a)
                            });
                            items.push(if b == "_" {
                                Pattern::Wildcard
                            } else {
                                Pattern::Capture(b)
                            });
                            elem_done += 1;
                        }
                        _ => {
                            // literal element: <value>; CMP ==; PJIF fail
                            let region_start = i;
                            let mut j = i;
                            let mut jk = None;
                            while let Some(ins) = self.instrs.get(j) {
                                if matches!(
                                    ins.op,
                                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
                                ) {
                                    jk = Some(j);
                                    break;
                                }
                                if !is_pure_value_op(ins.op) {
                                    return None;
                                }
                                j += 1;
                            }
                            let jk = match jk {
                                Some(x) => x,
                                None => {
                                    return None;
                                }
                            };
                            // later element checks may jump PAST the fail
                            // POP_TOP straight to the next case head
                            let tgt = self.instrs[jk].target?;
                            let fail_ok = tgt == fail
                                || self
                                    .idx_of
                                    .get(&fail)
                                    .map_or(false, |&fi| {
                                        self.instrs[fi].end() == tgt
                                            || (tgt > fail
                                                && tgt
                                                    <= self.instrs[fi].end() + 2)
                                    });
                            if !fail_ok {
                                return None;
                            }
                            let Some(cmp_idx2) = self.match_prev_real(jk) else {
                                return None;
                            };
                            let value = self.sim_value_region(region_start, cmp_idx2)?;
                            items.push(Pattern::Value(value));
                            i = jk + 1;
                        }
                    }
                }
            }
            Some(Op::UNPACK_EX) => {
                let arg = self.instrs[i].arg as usize;
                let before = arg & 0xFF;
                let after = arg >> 8;
                i += 1;
                let total = before + 1 + after;
                let mut names: Vec<String> = Vec::new();
                while names.len() < total {
                    self.match_skip_pad(&mut i);
                    let op = self.instrs.get(i)?.op;
                    let name = match op {
                        Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL => {
                            let n = self.local_name(self.instrs[i].arg as usize);
                            i += 1;
                            n
                        }
                        Op::STORE_NAME => {
                            let n = self.const_name(self.instrs[i].arg as usize);
                            i += 1;
                            n
                        }
                        Op::STORE_FAST_STORE_FAST => {
                            let a = self.local_name(((self.instrs[i].arg >> 4) & 0xF) as usize);
                            let b = self.local_name((self.instrs[i].arg & 0xF) as usize);
                            i += 1;
                            names.push(a);
                            b
                        }
                        Op::STORE_FAST_LOAD_FAST => {
                            let a = self.local_name(((self.instrs[i].arg >> 4) & 0xF) as usize);
                            i += 1;
                            names.push(a.clone());
                            a
                        }
                        _ => return None,
                    };
                    names.push(name);
                }
                if names.len() != total {
                    return None;
                }
                for (idx, name) in names.into_iter().enumerate() {
                    let pat = if name == "_" {
                        Pattern::Wildcard
                    } else {
                        Pattern::Capture(name)
                    };
                    if idx == before {
                        star_pat = Some((pat, after));
                    } else {
                        items.push(pat);
                    }
                }
                let _ = min_len;
            }
            _ => {
                return None;
            }
        }
        let pat = Pattern::Sequence {
            items,
            star: star_pat.map(|(p, a)| (Box::new(p), a)),
        };
        // 3.11+ or-arm: success jumps to the shared body block
        self.match_skip_pad(&mut i);
        if let Some(ins) = self.instrs.get(i) {
            if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                && ins.target.map_or(false, |t| t > ins.offset)
            {
                if let Some(&bi) = self.idx_of.get(&ins.target.unwrap()) {
                    return Some((pat, fail, bi));
                }
            }
        }
        Some((pat, fail, i))
    }

    /// Mapping pattern: MATCH_MAPPING; PJIF; GET_LEN; n; CMP >=; PJIF;
    /// LOAD_CONST keys; MATCH_KEYS; then version-specific value
    /// extraction; capture stores follow the value tests.
    fn parse_match_mapping(&mut self, i0: usize) -> Option<(Pattern, usize, usize)> {
        let mut i = i0 + 1;
        self.match_skip_pad(&mut i);
        if !matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE) | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
        ) {
            return None;
        }
        let fail = self.instrs[i].target?;
        i += 1;
        self.match_skip_pad(&mut i);
        if self.instrs.get(i).map(|x| x.op) != Some(Op::GET_LEN) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        let len_ins = self.instrs.get(i)?;
        let nkeys = if len_ins.op == Op::LOAD_SMALL_INT {
            len_ins.arg as usize
        } else if len_ins.op == Op::LOAD_CONST {
            self.code.consts.get(len_ins.arg as usize)?.as_int()? as usize
        } else {
            return None;
        };
        i += 1;
        self.match_skip_pad(&mut i);
        if self.instrs.get(i).map(|x| x.op) != Some(Op::COMPARE_OP) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        if !matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE) | Some(Op::POP_JUMP_FORWARD_IF_FALSE)
        ) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        // LOAD_CONST keys tuple; MATCH_KEYS
        if self.instrs.get(i).map(|x| x.op) != Some(Op::LOAD_CONST) {
            return None;
        }
        let keys: Vec<ExprRef> =
            match &**self.code.consts.get(self.instrs[i].arg as usize)? {
                PyObject::Tuple(items) => items
                    .iter()
                    .map(|it| Rc::new(Expr::Const(it.clone())) as ExprRef)
                    .collect(),
                _ => return None,
            };
        i += 1;
        self.match_skip_pad(&mut i);
        if self.instrs.get(i).map(|x| x.op) != Some(Op::MATCH_KEYS) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        // keys-result test: 3.10 PJIF; 3.12+ COPY 1; POP_JUMP_IF_NONE
        if matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::COPY) | Some(Op::DUP_TOP)
        ) {
            i += 1;
            self.match_skip_pad(&mut i);
        }
        if !matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::POP_JUMP_IF_FALSE)
                | Some(Op::POP_JUMP_IF_NONE)
                | Some(Op::POP_JUMP_FORWARD_IF_NONE)
        ) {
            return None;
        }
        i += 1;
        self.match_skip_pad(&mut i);
        // scan forward: collect capture stores until the subject POP_TOP
        // that precedes the body; everything else is extraction boilerplate
        let mut caps: Vec<String> = Vec::new();
        // key-slot events in scan order: literal value sub-patterns
        // (`{'kind': 'circle'}`) interleave with capture stores
        let mut values: Vec<(usize, ExprRef)> = Vec::new();
        let mut seen = 0usize;
        let mut scan = 0;
        let mut saw_dict_without = false;
        let body_start;
        loop {
            let ins = self.instrs.get(i).copied()?;
            scan += 1;
            if scan > 60 {
                return None;
            }
            match ins.op {
                Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL => {
                    caps.push(self.local_name(ins.arg as usize));
                    seen += 1;
                    i += 1;
                }
                Op::STORE_NAME => {
                    caps.push(self.const_name(ins.arg as usize));
                    seen += 1;
                    i += 1;
                }
                Op::STORE_FAST_STORE_FAST => {
                    caps.push(self.local_name(((ins.arg >> 4) & 0xF) as usize));
                    caps.push(self.local_name((ins.arg & 0xF) as usize));
                    seen += 2;
                    i += 1;
                }
                Op::STORE_FAST_LOAD_FAST => {
                    caps.push(self.local_name(((ins.arg >> 4) & 0xF) as usize));
                    seen += 1;
                    i += 1;
                }
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE => {
                    // a value sub-pattern check consumes a key slot
                    if let Some(lit) = self.match_prev_value_const(i) {
                        values.push((seen, lit));
                        seen += 1;
                    }
                    i += 1;
                }
                Op::POP_TOP if seen > 0 => {
                    while matches!(self.instrs.get(i).map(|x| x.op), Some(Op::POP_TOP)) {
                        i += 1;
                    }
                    self.match_skip_pad(&mut i);
                    body_start = i;
                    break;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS => return None,
                Op::COPY_DICT_WITHOUT_KEYS => {
                    // 3.10 extraction: key values first, the rest dict last
                    saw_dict_without = true;
                    i += 1;
                }
                _ => i += 1,
            }
        }
        // captures fill the key slots not consumed by literal value
        // sub-patterns; an extra one is the **rest binding (it precedes
        // them in 3.11+ stores, follows in the 3.10 COPY_DICT_WITHOUT_KEYS
        // extraction)
        let needed = nkeys.saturating_sub(values.len());
        let rest;
        let value_caps;
        if caps.len() == needed {
            rest = None;
            value_caps = caps;
        } else if caps.len() == needed + 1 {
            if saw_dict_without {
                rest = caps.pop();
            } else {
                rest = Some(caps.remove(0));
            }
            value_caps = caps;
        } else {
            return None;
        }
        if !(seen == nkeys || (rest.is_some() && seen == nkeys + 1)) {
            return None;
        }
        // merge: value sub-patterns occupy their scanned slot positions,
        // captures fill the rest in order
        let mut slot_pat: Vec<Option<Pattern>> = vec![None; nkeys];
        for (pos, lit) in values {
            if pos < nkeys {
                slot_pat[pos] = Some(Pattern::Value(lit));
            }
        }
        let mut cap_iter = value_caps.into_iter();
        for s in slot_pat.iter_mut() {
            if s.is_none() {
                let Some(name) = cap_iter.next() else {
                    return None;
                };
                *s = Some(if name == "_" {
                    Pattern::Wildcard
                } else {
                    Pattern::Capture(name)
                });
            }
        }
        let items: Vec<(ExprRef, Pattern)> = keys
            .into_iter()
            .zip(slot_pat.into_iter())
            .map(|(k, p)| (k, p.unwrap_or(Pattern::Wildcard)))
            .collect();
        let rest = rest.map(|r| if r == "_" { "_".to_string() } else { r });
        let pat = Pattern::Mapping { items, rest };
        // 3.11+ or-arm: success jumps to the shared body block
        let mut mi = body_start;
        self.match_skip_pad(&mut mi);
        if let Some(ins) = self.instrs.get(mi) {
            if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                && ins.target.map_or(false, |t| t > ins.offset)
            {
                if let Some(&bi) = self.idx_of.get(&ins.target.unwrap()) {
                    return Some((pat, fail, bi));
                }
            }
        }
        Some((pat, fail, body_start))
    }

    /// Class pattern: `LOAD cls; LOAD_CONST names; MATCH_CLASS n;
    /// COPY; PJIF_NONE|PJIF; UNPACK_SEQUENCE n; capture stores`.
    fn parse_match_class(&mut self, i0: usize) -> Option<(Pattern, usize, usize)> {
        let mut i = i0;
        let cls_start = i;
        while self.instrs.get(i).map(|x| x.op) != Some(Op::MATCH_CLASS) {
            if !is_pure_value_op(self.instrs.get(i)?.op) {
                return None;
            }
            i += 1;
        }
        let mc = self.instrs[i];
        let names_ins = self.instrs.get(i - 1)?;
        if names_ins.op != Op::LOAD_CONST {
            return None;
        }
        let kw_names: Vec<String> =
            match &**self.code.consts.get(names_ins.arg as usize)? {
                PyObject::Tuple(items) => items
                    .iter()
                    .map(|it| match &**it {
                        PyObject::Str(s) => Some(s.clone()),
                        _ => None,
                    })
                    .collect::<Option<Vec<_>>>()?,
                _ => return None,
            };
        // No-dup first case: the cls load was already consumed by the main
        // loop and recovered onto pending_match_class (cls_start == i means
        // there are no forward value ops to re-simulate).
        let cls = if cls_start == i {
            self.pending_match_class.take()?
        } else {
            self.sim_value_region(cls_start, i - 1)?
        };
        // MATCH_CLASS arg = POSITIONAL pattern count in every version;
        // the names tuple holds the keyword names
        let mc_arg = mc.arg as usize;
        let nattr_total = mc_arg + kw_names.len();
        let npos = nattr_total.saturating_sub(kw_names.len());
        i += 1;
        self.match_skip_pad(&mut i);
        // 3.12+: COPY 1; POP_JUMP_IF_NONE; 3.10: PJIF directly
        if matches!(
            self.instrs.get(i).map(|x| x.op),
            Some(Op::COPY) | Some(Op::DUP_TOP)
        ) {
            i += 1;
            self.match_skip_pad(&mut i);
        }
        let fail;
        match self.instrs.get(i).map(|x| x.op) {
            Some(Op::POP_JUMP_IF_NONE)
            | Some(Op::POP_JUMP_FORWARD_IF_NONE)
            | Some(Op::POP_JUMP_IF_FALSE)
            | Some(Op::POP_JUMP_FORWARD_IF_FALSE) => {
                fail = self.instrs[i].target?;
                i += 1;
            }
            _ => return None,
        }
        self.match_skip_pad(&mut i);
        // one slot per extracted attribute: a capture name, or a literal
        // value sub-pattern checked inline (`case Point(0, y=1)`)
        let cap = |n: String| {
            if n == "_" {
                Pattern::Wildcard
            } else {
                Pattern::Capture(n)
            }
        };
        let mut slots: Vec<Option<Pattern>> = vec![None; nattr_total];
        let mut captures: Vec<String> = Vec::new();
        if self.instrs.get(i).map(|x| x.op) == Some(Op::UNPACK_SEQUENCE) {
            if self.instrs[i].arg as usize != nattr_total {
                return None;
            }
            i += 1;
            // UNPACK_SEQUENCE leaves attribute 0 on TOP of the simulated
            // slot stack; SWAP/ROT reach deeper slots, CMP consumes one,
            // stores capture one
            let mut stack: Vec<usize> = (0..nattr_total).rev().collect();
            let mut filled = 0usize;
            while filled < nattr_total {
                self.match_skip_pad(&mut i);
                let ins = self.instrs.get(i).copied()?;
                match ins.op {
                    Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL => {
                        let s = stack.pop()?;
                        if slots[s].is_none() {
                            slots[s] = Some(cap(self.local_name(ins.arg as usize)));
                            filled += 1;
                        }
                        i += 1;
                    }
                    Op::STORE_NAME => {
                        let s = stack.pop()?;
                        if slots[s].is_none() {
                            slots[s] = Some(cap(self.const_name(ins.arg as usize)));
                            filled += 1;
                        }
                        i += 1;
                    }
                    Op::STORE_FAST_STORE_FAST => {
                        let a = stack.pop()?;
                        let b = stack.pop()?;
                        if slots[a].is_none() {
                            slots[a] = Some(cap(self.local_name(((ins.arg >> 4) & 0xF) as usize)));
                            filled += 1;
                        }
                        if slots[b].is_none() {
                            slots[b] = Some(cap(self.local_name((ins.arg & 0xF) as usize)));
                            filled += 1;
                        }
                        i += 1;
                    }
                    Op::STORE_FAST_LOAD_FAST => {
                        let a = stack.pop()?;
                        if slots[a].is_none() {
                            slots[a] = Some(cap(self.local_name(((ins.arg >> 4) & 0xF) as usize)));
                            filled += 1;
                        }
                        i += 1;
                    }
                    Op::SWAP => {
                        let n = ins.arg as usize;
                        if n < 2 || n > stack.len() {
                            return None;
                        }
                        let l = stack.len();
                        stack.swap(l - n, l - 1);
                        i += 1;
                    }
                    Op::ROT_TWO => {
                        let l = stack.len();
                        if l < 2 {
                            return None;
                        }
                        stack.swap(l - 1, l - 2);
                        i += 1;
                    }
                    Op::ROT_THREE => {
                        let l = stack.len();
                        if l < 3 {
                            return None;
                        }
                        let v = stack.remove(l - 3);
                        stack.push(v);
                        i += 1;
                    }
                    Op::COPY | Op::DUP_TOP => {
                        let t = *stack.last()?;
                        stack.push(t);
                        i += 1;
                    }
                    Op::LOAD_CONST | Op::LOAD_SMALL_INT | Op::LOAD_GLOBAL
                    | Op::LOAD_NAME | Op::LOAD_ATTR | Op::LOAD_FAST
                    | Op::LOAD_DEREF | Op::BUILD_TUPLE | Op::PUSH_NULL
                    | Op::LOAD_METHOD | Op::CALL | Op::CALL_FUNCTION
                    | Op::BINARY_OP | Op::COMPARE_OP => {
                        // part of an inline value sub-pattern check — the
                        // operands never touch the attribute slot stack
                        i += 1;
                    }
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE => {
                        // `CMP == <lit>; PJIF fail` consumed the top slot
                        // as a literal value pattern: recover the literal
                        // from the comparison's other operand. The first
                        // check jumps to the fail POP_TOP; later checks
                        // jump PAST it (the list pop already happened)
                        let fail_ok = ins.target.map_or(false, |t| {
                            t == fail
                                || self
                                    .idx_of
                                    .get(&fail)
                                    .map_or(false, |&fi| {
                                        self.instrs[fi].end() == t
                                            || t > fail && t <= self.instrs[fi].end() + 2
                                    })
                        });
                        if !fail_ok {
                            return None;
                        }
                        let lit = self.match_prev_value_const(i)?;
                        let s = stack.pop()?;
                        if slots[s].is_none() {
                            slots[s] = Some(Pattern::Value(lit));
                            filled += 1;
                        }
                        i += 1;
                    }
                    Op::POP_TOP => {
                        // discard the MATCH_CLASS result list
                        i += 1;
                        break;
                    }
                    _ => return None,
                }
            }
            if filled != nattr_total {
                return None;
            }
        } else if nattr_total > 0 && !self.version.at_least(3, 12) {
            // 3.10/3.11 per-attribute extraction:
            //   [DUP_TOP; LOAD_CONST idx; BINARY_SUBSCR; ROT_*; POP_TOP;]*
            //   STORE name / literal CMP check — attributes in
            // positional-then-keyword order
            let mut slot = 0usize;
            while slot < nattr_total {
                self.match_skip_pad(&mut i);
                let ins = self.instrs.get(i).copied()?;
                match ins.op {
                    Op::STORE_FAST | Op::STORE_FAST_MAYBE_NULL => {
                        slots[slot] = Some(cap(self.local_name(ins.arg as usize)));
                        slot += 1;
                        i += 1;
                    }
                    Op::STORE_NAME => {
                        slots[slot] = Some(cap(self.const_name(ins.arg as usize)));
                        slot += 1;
                        i += 1;
                    }
                    Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE => {
                        // inline literal check of the extracted attribute
                        let lit = self.match_prev_value_const(i)?;
                        slots[slot] = Some(Pattern::Value(lit));
                        slot += 1;
                        i += 1;
                    }
                    Op::DUP_TOP
                    | Op::LOAD_CONST
                    | Op::LOAD_SMALL_INT
                    | Op::LOAD_GLOBAL
                    | Op::LOAD_NAME
                    | Op::COMPARE_OP
                    | Op::BINARY_SUBSCR
                    | Op::ROT_TWO
                    | Op::ROT_THREE
                    | Op::ROT_FOUR
                    | Op::ROT_N
                    | Op::SWAP
                    | Op::COPY
                    | Op::POP_TOP => i += 1,
                    _ => return None,
                }
            }
        } else if nattr_total == 0 {
            // bare `case int():` — no attribute extraction
        } else {
            return None;
        }
        if captures.len() == nattr_total && slots.iter().all(|s| s.is_none()) {
            // the per-attribute extraction path filled captures in slot
            // order (positional first, then keyword)
            for (s, n) in slots.iter_mut().zip(captures.into_iter()) {
                *s = Some(cap(n));
            }
        }
        if slots.iter().any(|s| s.is_none()) {
            return None;
        }
        let patterns: Vec<Pattern> = slots
            .iter()
            .take(npos)
            .map(|s| s.clone().unwrap_or(Pattern::Wildcard))
            .collect();
        let keywords: Vec<(String, Pattern)> = kw_names
            .into_iter()
            .zip(slots.into_iter().skip(npos))
            .map(|(k, v)| (k, v.unwrap_or(Pattern::Wildcard)))
            .collect();
        let pat = Pattern::Class { cls, patterns, keywords };
        // 3.11+ or-arm: success jumps to the shared body block
        self.match_skip_pad(&mut i);
        if let Some(ins) = self.instrs.get(i) {
            if matches!(ins.op, Op::JUMP_FORWARD | Op::JUMP)
                && ins.target.map_or(false, |t| t > ins.offset)
            {
                if let Some(&bi) = self.idx_of.get(&ins.target.unwrap()) {
                    return Some((pat, fail, bi));
                }
            }
        }
        Some((pat, fail, i))
    }

    /// Optional guard after a pattern: `<value region>; [TO_BOOL]; PJIF
    /// fail; [NOT_TAKEN]`. Returns (guard, next_idx).
    fn parse_match_guard(&mut self, i0: usize, fail: usize) -> Option<(Option<ExprRef>, usize)> {
        let mut i = i0;
        self.match_skip_pad(&mut i);
        // a capture store may have re-pushed the bound value for the guard
        // (STORE_FAST_LOAD_FAST): include it so the sim sees the name
        let mut region_start = i;
        if let Some(p) = self.match_prev_real(i) {
            if p < i && self.instrs[p].op == Op::STORE_FAST_LOAD_FAST {
                region_start = p;
            }
        }
        let mut j = i;
        let mut jk = None;
        while let Some(ins) = self.instrs.get(j) {
            if matches!(
                ins.op,
                Op::POP_JUMP_IF_FALSE | Op::POP_JUMP_FORWARD_IF_FALSE
            ) {
                jk = Some(j);
                break;
            }
            if matches!(
                ins.op,
                Op::STORE_FAST
                    | Op::STORE_FAST_MAYBE_NULL
                    | Op::STORE_NAME
                    | Op::STORE_GLOBAL
                    | Op::STORE_DEREF
                    | Op::STORE_SUBSCR
                    | Op::STORE_ATTR
                    | Op::STORE_FAST_STORE_FAST
                    | Op::STORE_FAST_LOAD_FAST
                    | Op::UNPACK_SEQUENCE
                    | Op::UNPACK_EX
            ) || (!matches!(ins.op, Op::TO_BOOL) && !is_pure_value_op(ins.op))
            {
                return Some((None, i0));
            }
            j += 1;
            if j - i > 40 {
                return Some((None, i0));
            }
        }
        let jk = match jk {
            Some(x) => x,
            None => return Some((None, i0)),
        };
        let gfail = self.instrs[jk].target?;
        // the guard's fail target is the case fail label, or (3.10) the
        // instruction right after it (the subject-cleanup POP the
        // pattern-fail path still needs was already consumed)
        let ok = gfail == fail
            || self
                .idx_of
                .get(&fail)
                .and_then(|&fi| self.instrs.get(fi + 1))
                .map_or(false, |nx| nx.offset == gfail);
        if !ok {
            return Some((None, i0));
        }
        let cmp_idx = match self.match_prev_real(jk) {
            Some(x) => x,
            None => return Some((None, i0)),
        };
        let _ = cmp_idx;
        match self.sim_value_region(region_start, jk) {
            Some(guard) => Some((Some(guard), jk + 1)),
            None => Some((None, i0)),
        }
    }

    /// Parse a whole match statement whose first case head is at index
    /// `i0`, with `subject` already evaluated. Returns the statement and
    /// the offset just past the match.
    /// The post-match merge offset: the nearest forward JUMP_FORWARD/JUMP
    /// target from a fall-through case body that lands at/after `from`.
    /// A `case _:` wildcard sits at the last value case's PJIF fail target,
    /// while the post-match code sits at the fall-through bodies' jump
    /// target — scanning back for that target distinguishes them.
    fn match_post_merge(&self, from: usize) -> Option<usize> {
        let from_off = self.instrs.get(from).map(|x| x.offset)?;
        let mut best: Option<usize> = None;
        for k in (0..from).rev() {
            let x = &self.instrs[k];
            if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE)
                && !x.is_backward
            {
                if let Some(t) = x.target {
                    if t >= from_off {
                        best = Some(t);
                        break;
                    }
                }
            }
        }
        best
    }

    fn parse_match_region(&mut self, subject: ExprRef, i0: usize) -> Option<(Stmt, usize)> {
        let mut cases: Vec<MatchCase> = Vec::new();
        let mut i = i0;
        let mut end_idx = None;
        while i < self.instrs.len() {
            self.match_skip_pad(&mut i);
            if i >= self.instrs.len() {
                break;
            }
            // wildcard case: POP_TOP then the body (no pattern test)
        // failure-cleanup pops landing here (the last case's fail target)
        // are not statements — step over them
        while self.instrs[i].op == Op::POP_TOP
            && self.targets.contains(&self.instrs[i].offset)
        {
            i += 1;
            self.match_skip_pad(&mut i);
            if i >= self.instrs.len() {
                break;
            }
        }
        if i >= self.instrs.len() {
            break;
        }
        if self.instrs[i].op == Op::POP_TOP && !self.targets.contains(&self.instrs[i].offset) {
                let mut bs = i + 1;
                self.match_skip_pad(&mut bs);
                let body = self.parse_match_case_body(bs, None)?;
                cases.push(MatchCase {
                    pattern: Pattern::Wildcard,
                    guard: None,
                    body: body.0,
                });
                end_idx = Some(body.1);
                break;
            }
            if !self.match_case_head_at(i) {
                break;
            }
            // consume case-head dups
            let mut k = i;
            while matches!(
                self.instrs.get(k).map(|x| x.op),
                Some(Op::DUP_TOP) | Some(Op::COPY)
            ) && (self.instrs[k].op == Op::DUP_TOP || self.instrs[k].arg == 1)
            {
                k += 1;
                self.match_skip_pad(&mut k);
            }
            // scan for the next case boundary: the first jump-targeted
            // offset after this head that itself starts a case head. For a
            // single-pattern case this is the NEXT case (fail jumps there);
            // for an or-pattern it is the second arm (the case's own span
            // ends before it, so the fail target never reaches it).
            let mut boundary = None;
            {
                let mut s = k + 1;
                while s < self.instrs.len() {
                    let soff = self.instrs[s].offset;
                    if self.targets.contains(&soff) && self.match_case_head_at(s) {
                        boundary = Some(soff);
                        break;
                    }
                    s += 1;
                }
            }
            let (pattern, fail, after_pat) = self.parse_match_pattern(k, boundary)?;
            // 3.11+ shared or-success block: after_pat already points at
            // the cleanup POPs preceding the body
            let shared_success = self
                .idx_of
                .get(&self.instrs[after_pat].offset)
                .map_or(false, |_| {
                    self.instrs[after_pat].op == Op::POP_TOP
                        && self.targets.contains(&self.instrs[after_pat].offset)
                        && after_pat > k
                });
            let (guard, after_guard) = if shared_success {
                (None, after_pat)
            } else {
                self.parse_match_guard(after_pat, fail)?
            };
            let mut bs = after_guard;
            if shared_success {
                while matches!(self.instrs.get(bs).map(|x| x.op), Some(Op::POP_TOP)) {
                    bs += 1;
                }
                self.match_skip_pad(&mut bs);
            }
            self.match_skip_pad(&mut bs);
            // subject POP_TOP before the body
            if self.instrs.get(bs).map(|x| x.op) == Some(Op::POP_TOP) {
                bs += 1;
                self.match_skip_pad(&mut bs);
            }
            // Bound a fall-through body to the case's fail target so the
            // LAST pattern case doesn't swallow the post-match code. Only
            // valid when the body starts BEFORE the fail target — a 3.11+
            // shared or-pattern body sits PAST the fail target, where a bound
            // would truncate it to nothing.
            let body_bound = if self.instrs[bs].offset < fail {
                Some(fail)
            } else {
                None
            };
            let body = self.parse_match_case_body(bs, body_bound)?;
            // Did this case's body end with a backward jump to an enclosing
            // loop top? If so the fail target is reached ONLY by the fail
            // jump (the body loops back, never falls through), so a non-head
            // body there is a `case _:` wildcard — unlike a fall-through last
            // case whose fail target is the post-match code.
            let body_loop_back = body.1 > bs
                && matches!(
                    self.instrs.get(body.1 - 1).map(|x| x.op),
                    Some(Op::JUMP_BACKWARD)
                );
            cases.push(MatchCase {
                pattern,
                guard,
                body: body.0,
            });
            // next case head: at the fail label, past cleanup pops/jumps
            let Some(&fi) = self.idx_of.get(&fail) else {
                break;
            };
            let mut nk = fi;
            let mut popped_cleanup = false;
            let mut hopped_jump = false;
            loop {
                self.match_skip_pad(&mut nk);
                match self.instrs.get(nk).map(|x| x.op) {
                    Some(Op::POP_TOP) => {
                        popped_cleanup = true;
                        nk += 1;
                    }
                    Some(Op::JUMP_FORWARD) | Some(Op::JUMP) | Some(Op::JUMP_ABSOLUTE) => {
                        let t = self.instrs[nk].target?;
                        if t <= self.instrs[nk].offset {
                            break;
                        }
                        let Some(&ti) = self.idx_of.get(&t) else {
                            break;
                        };
                        hopped_jump = true;
                        nk = ti;
                    }
                    _ => break,
                }
            }
            if nk >= self.instrs.len() {
                break;
            }
            if !self.match_case_head_at(nk) {
                if self.instrs[nk].op == Op::POP_TOP {
                    // a cleanup pop still pending — let the loop-top
                    // wildcard branch handle it
                    i = nk;
                    continue;
                }
                // A trailing `case _:` wildcard sits at the previous case's
                // fail target with NO pattern test of its own. Recognize it
                // when the scan skipped a cleanup POP_TOP, OR the previous
                // case body looped back to an enclosing loop (so its fail
                // target is reached only by the fail jump = wildcard, not a
                // fall-through to post-match code). A forward jump out of the
                // match is the real end, never a wildcard.
                //
                // Guard: a LAST case in a loop can compile to the inverted
                // `<value>; COMPARE ==; POP_JUMP_IF_TRUE body; JUMP_BACKWARD`
                // form, which match_case_head_at (PJIF_FALSE-oriented) does
                // not flag as a head. Don't swallow it as a wildcard.
                let inverted_head = {
                    let mut s = nk;
                    let mut steps = 0;
                    let mut found = false;
                    while let Some(ins) = self.instrs.get(s) {
                        if matches!(
                            ins.op,
                            Op::POP_JUMP_IF_TRUE | Op::POP_JUMP_FORWARD_IF_TRUE
                        ) && self.match_prev_real(s).map_or(false, |pj| {
                            pj >= nk
                                && matches!(self.instrs[pj].op, Op::COMPARE_OP)
                                && cmp_from_index(compare_op_index(
                                    self.instrs[pj].arg as u32,
                                    self.version,
                                )) == CmpOp::Eq
                        }) {
                            found = true;
                            break;
                        }
                        if !is_pure_value_op(ins.op) || steps > 12 {
                            break;
                        }
                        s += 1;
                        steps += 1;
                    }
                    found
                };
                // A `case _:` wildcard whose body TERMINATES (raise/return)
                // has NO subject POP_TOP (the terminator discards the
                // stack) and its predecessor body fell through (no loop
                // back), so neither popped_cleanup nor body_loop_back
                // holds. Recognize it: nk holds a terminator BEFORE the
                // post-match merge (the fall-through bodies' JUMP_FORWARD
                // target). annotationlib 3.14 ForwardRef.evaluate
                // `match format: case STRING: return ..; case VALUE: ..;
                // case _: raise NotImplementedError(format)` — the wildcard
                // raise detached to a top-level unconditional raise,
                // breaking the VALUE/FORWARDREF fall-through.
                let no_pop_term_wildcard = !popped_cleanup
                    && !body_loop_back
                    && {
                        let post_match = self.match_post_merge(nk);
                        let mut m = nk;
                        let mut term_before_merge = false;
                        while m < self.instrs.len() {
                            let mo = self.instrs[m].offset;
                            if post_match == Some(mo) {
                                break;
                            }
                            match self.instrs[m].op {
                                Op::RAISE_VARARGS
                                | Op::RETURN_VALUE
                                | Op::RETURN_CONST => {
                                    // REQUIRE a distinct post-match merge:
                                    // a fall-through case body's
                                    // JUMP_FORWARD target. Without it the
                                    // "wildcard" is just the post-match
                                    // tail-duplicated return (the last
                                    // case's fail target IS the post-match
                                    // code) — _strptime 3.13 TimeRE repl
                                    // `match format_char: case 'Y'|..:
                                    // year=True; case 'd': ..` + post
                                    // `return self[format_char]` grew a
                                    // spurious `case _:`. annotationlib's
                                    // genuine wildcard raise sits BEFORE the
                                    // VALUE/FORWARDREF arms' JUMP_FORWARD
                                    // merge.
                                    term_before_merge = post_match
                                        .map_or(false, |pm| mo < pm);
                                    break;
                                }
                                Op::CHECK_EXC_MATCH
                                | Op::PUSH_EXC_INFO
                                | Op::MATCH_CLASS
                                | Op::MATCH_SEQUENCE
                                | Op::MATCH_MAPPING => break,
                                _ => m += 1,
                            }
                        }
                        term_before_merge
                    };
                if (popped_cleanup || body_loop_back || no_pop_term_wildcard)
                    && !inverted_head
                    // the advance hopped through an explicit forward
                    // jump (the or-chain's no-match exit JF): what it
                    // targets is deliberately skipped code — the
                    // post-match flow, never a wildcard arm (repl 3.13:
                    // POP_TOP; JF->tail would have grown `case _:
                    // return self[format_char]`)
                    && !hopped_jump
                    && !matches!(
                        self.instrs[nk].op,
                        Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE
                    )
                {
                    let body = self.parse_match_case_body(nk, None)?;
                    cases.push(MatchCase {
                        pattern: Pattern::Wildcard,
                        guard: None,
                        body: body.0,
                    });
                    end_idx = Some(body.1);
                    break;
                }
                end_idx = Some(nk);
                break;
            }
            if self.instrs[nk].offset <= self.instrs[i].offset {
                break;
            }
            i = nk;
        }
        if cases.is_empty() {
            return None;
        }
        let end_off = match end_idx {
            Some(e) => self.instrs.get(e).map(|x| x.offset),
            None => None,
        }
        .or_else(|| self.instrs.last().map(|x| x.end()))?;
        // a post-match IMMEDIATE `return v` gets tail-duplicated into
        // the case bodies by the compiler (_strptime 3.13 repl: the
        // shared or-success block AND the 'd' arm each carry a copy of
        // `return self[format_char]`, the genuine tail follows the
        // match). When the tail is literally the first statement after
        // the region, strip the mirrored trailing case-body returns —
        // the post-match walk renders it once. A case-internal-only
        // return has no post-match twin and is untouched.
        // idx_of also maps instruction END offsets — require the scan to
        // start at a genuine instruction AT end_off, else the fallback
        // end (last case's own RETURN end) resolves back to that very
        // return and the strip eats the wildcard body (v310_match)
        if let Some(ei) = self
            .idx_of
            .get(&end_off)
            .copied()
            .filter(|&ei2| self.instrs[ei2].offset == end_off)
        {
            let mut k = ei;
            while matches!(
                self.instrs.get(k).map(|x| x.op),
                Some(Op::NOP) | Some(Op::NOT_TAKEN) | Some(Op::CACHE)
            ) {
                k += 1;
            }
            let start = k;
            let mut tail_e: Option<ExprRef> = None;
            while k < self.instrs.len() {
                let x = &self.instrs[k];
                if x.op == Op::RETURN_VALUE {
                    tail_e = self.sim_value_region(start, k);
                    break;
                }
                if x.op == Op::RETURN_CONST {
                    tail_e = Some(self.const_expr(x.arg as usize));
                    break;
                }
                if !is_pure_value_op(x.op) {
                    break;
                }
                k += 1;
            }
            if let Some(te) = tail_e {
                for c in cases.iter_mut() {
                    if let Some(Stmt::Return(Some(v))) = c.body.last() {
                        if expr_eq(v, &te) {
                            c.body.pop();
                        }
                    }
                }
            }
        }
        Some((Stmt::Match { subject, cases }, end_off))
    }

    /// A case body runs to its RETURN/RAISE, its forward jump out of the
    /// match, its backward jump to an enclosing loop top, or — for a LAST
    /// case whose body falls through with no terminating jump — to `bound`
    /// (the case's fail target = match end). Bounding stops the last pattern
    /// case from swallowing the post-match code. Returns (statements, index
    /// after the body).
    fn parse_match_case_body(
        &mut self,
        from_idx: usize,
        bound: Option<usize>,
    ) -> Option<(Vec<Stmt>, usize)> {
        let mut j = from_idx;
        // forward conditional-jump targets seen inside the body (if/else
        // and ternary else arms). A RETURN/RAISE that still has a pending
        // else-arm target AHEAD of it is an ARM end, not the body end —
        // stopping there orphans the else arm past the case body
        // (annotationlib 3.14 _template_to_ast_literal `case _: y = a if
        // c else b; return y` — the compiler sank `return y` into both
        // ternary arms, so the first RETURN closes only the if-true arm).
        let mut pending_else: Vec<usize> = Vec::new();
        while j < self.instrs.len() {
            let ins = self.instrs[j];
            // fall-through body bound: stop AT the fail target (exclusive)
            if j > from_idx {
                if let Some(b) = bound {
                    if ins.offset >= b {
                        let stmts =
                            self.decompile_region(self.instrs[from_idx].offset, b);
                        return Some((stmts, j));
                    }
                }
            }
            match ins.op {
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_IF_NONE
                | Op::POP_JUMP_IF_NOT_NONE
                | Op::JUMP_IF_FALSE_OR_POP
                | Op::JUMP_IF_TRUE_OR_POP => {
                    if !ins.is_backward {
                        if let Some(t) = ins.target {
                            if t > ins.offset {
                                pending_else.push(t);
                            }
                        }
                    }
                    j += 1;
                }
                Op::RETURN_VALUE | Op::RETURN_CONST | Op::RAISE_VARARGS => {
                    let off = ins.offset;
                    let else_ahead = pending_else.iter().any(|&t| t > off);
                    if else_ahead {
                        // an if/else (or ternary) else arm still lies
                        // ahead — this RETURN only ends the current arm
                        pending_else.retain(|&t| t <= off);
                        j += 1;
                        continue;
                    }
                    let to = ins.end();
                    let stmts = self.decompile_region(self.instrs[from_idx].offset, to);
                    return Some((stmts, j + 1));
                }
                Op::JUMP_FORWARD | Op::JUMP | Op::JUMP_ABSOLUTE => {
                    if let Some(t) = ins.target {
                        if t > ins.offset {
                            // an if/else or ternary arm-end jump with a
                            // pending else arm still AHEAD (the jump
                            // skips over it to the merge) is NOT the body
                            // end — jump to the merge and keep scanning
                            // (nested ternary kwargs in a CALL_KW:
                            // annotationlib 3.14 ast.Interpolation(
                            // conversion=.. if .. else .., format_spec=..
                            // if .. else ..)).
                            let else_ahead =
                                pending_else.iter().any(|&x| x > ins.offset);
                            if else_ahead {
                                pending_else.retain(|&x| x > t);
                                let Some(&ti) = self.idx_of.get(&t) else {
                                    return None;
                                };
                                j = ti;
                                continue;
                            }
                            let to = ins.end();
                            let stmts =
                                self.decompile_region(self.instrs[from_idx].offset, to);
                            let Some(&ti) = self.idx_of.get(&t) else {
                                return Some((stmts, j + 1));
                            };
                            return Some((stmts, ti));
                        }
                    }
                    return None;
                }
                Op::JUMP_BACKWARD => {
                    // A case body inside a loop ends by jumping BACKWARD to
                    // the loop top (not a forward jump out of the match).
                    let to = ins.end();
                    let stmts = self.decompile_region(self.instrs[from_idx].offset, to);
                    return Some((stmts, j + 1));
                }
                _ => j += 1,
            }
        }
        None
    }
}

// =====================  comprehensions  =====================

impl<'a> Ctx<'a> {
    /// Try to turn a completed call into a comprehension. The callee is a
    /// Function whose code object is named `<listcomp>` etc. The iterable is
    /// passed either as a normal argument (3.12+, 2.7 listcomp) or via the
    /// self/marker slot (3.7-3.11 LOAD_METHOD convention).
    fn try_make_comprehension(
        &mut self,
        call_e: &ExprRef,
        marker: Option<Sv>,
    ) -> Option<ExprRef> {
        let Expr::Call { func, args, .. } = &**call_e else {
            return None;
        };
        let fd = match &**func {
            Expr::Function(fd) => fd.clone(),
            Expr::Name(n) if n == "/*generator*/" => {
                // genexpr passed as a call argument: code object remembered
                // at RETURN_GENERATOR
                let code = self.pending_gen_code.take()?;
                Rc::new(FunctionDef {
                    name: code.name.clone(),
                    code,
                    params: Parameters::empty(),
                    decorators: Vec::new(),
                    returns: None,
                    is_async: false,
                })
            }
            _ => return None,
        };
        let kind = match fd.code.name.as_str() {
            "<listcomp>" => CompKind::List,
            "<setcomp>" => CompKind::Set,
            "<dictcomp>" => CompKind::Dict,
            "<genexpr>" | "<async_generator>" => CompKind::Generator,
            _ => return None,
        };

        // locate the iterable argument
        let iter: ExprRef = if let Some(Sv::E(e)) = marker {
            e
        } else if !args.is_empty()
            && !matches!(&*args[0], Expr::Name(n) if n == "/*generator*/")
        {
            args[0].clone()
        } else {
            return None;
        };

        let outer = iter.clone();
        match self.build_comprehension(&fd.code, kind, iter) {
            Some((elt, key, gens)) => {
                let mut generators = gens;
                if generators.is_empty() {
                    return None;
                }
                // the first generator's iterator is the passed-in iterable
                generators[0].iter = outer;
                Some(Rc::new(Expr::Comprehension {
                    kind,
                    elt,
                    key,
                    generators,
                }))
            }
            None => None,
        }
    }

    /// Decode a comprehension code object into (elt, key, generators).
    /// The implicit `.0` parameter holds the outermost iterator (replaced
    /// by the caller with the real iterable expression).
/// Value-producing opcodes valid inside a comprehension ternary arm.
fn comp_arm_value_op(o: Op) -> bool {
    matches!(
        o,
        Op::LOAD_FAST
            | Op::LOAD_FAST_CHECK
            | Op::LOAD_FAST_BORROW
            | Op::LOAD_FAST_AND_CLEAR
            | Op::LOAD_FAST_LOAD_FAST
            | Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW
            | Op::LOAD_NAME
            | Op::LOAD_GLOBAL
            | Op::LOAD_CONST
            | Op::LOAD_DEREF
            | Op::LOAD_ATTR
            | Op::LOAD_METHOD
            | Op::LOAD_SMALL_INT
            | Op::LOAD_COMMON_CONSTANT
            | Op::PUSH_NULL
            | Op::CALL
            | Op::CALL_FUNCTION
            | Op::CALL_METHOD
            | Op::CALL_FUNCTION_KW
            | Op::CALL_FUNCTION_EX
            | Op::CALL_INTRINSIC_1
            | Op::CALL_INTRINSIC_2
            | Op::KW_NAMES
            | Op::PRECALL
            | Op::BINARY_OP
            | Op::BINARY_ADD
            | Op::BINARY_SUBTRACT
            | Op::BINARY_MULTIPLY
            | Op::BINARY_TRUE_DIVIDE
            | Op::BINARY_FLOOR_DIVIDE
            | Op::BINARY_MODULO
            | Op::BINARY_POWER
            | Op::BINARY_LSHIFT
            | Op::BINARY_RSHIFT
            | Op::BINARY_AND
            | Op::BINARY_OR
            | Op::BINARY_XOR
            | Op::BINARY_DIVIDE
            | Op::BINARY_MATRIX_MULTIPLY
            | Op::BINARY_SUBSCR
            | Op::COMPARE_OP
            | Op::IS_OP
            | Op::CONTAINS_OP
            | Op::UNARY_NOT
            | Op::UNARY_NEGATIVE
            | Op::UNARY_POSITIVE
            | Op::UNARY_INVERT
            | Op::BUILD_TUPLE
            | Op::BUILD_LIST
            | Op::BUILD_SET
            | Op::BUILD_MAP
            | Op::BUILD_STRING
            | Op::BUILD_CONST_KEY_MAP
            | Op::BUILD_SLICE
            | Op::FORMAT_VALUE
            | Op::FORMAT_SIMPLE
            | Op::FORMAT_WITH_SPEC
            | Op::CONVERT_VALUE
            | Op::COPY
            | Op::SWAP
            | Op::TO_BOOL
            | Op::NOP
            | Op::NOT_TAKEN
            | Op::CACHE
            | Op::EXTENDED_ARG
            | Op::RESUME
    )
}

/// When the cond jump at `ii` in a comprehension code object is a
/// ternary element's cond (`A if C else B` — the jump targets the ELSE
/// arm and a forward JF skips it to the merge), validate the whole
/// (possibly nested) ternary and return the merge offset.
fn genexpr_ternary_merge(
    instrs: &[crate::bytecode::Instruction],
    ii: usize,
) -> Option<usize> {
    let inst = instrs.get(ii)?;
    let t = inst.target?;
    if t <= inst.offset {
        return None;
    }
    // then arm: value ops — and, for an and/or-chain cond, further cond
    // links whose jumps share the else-arm target t (base64 3.11
    // b85decode `b'z' if foldnuls and not word else ...`: the chain's
    // last link is followed by the then arm) — terminated by a forward
    // JF skipping the else arm
    let is_cj = |o: Op| {
        matches!(
            o,
            Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
        )
    };
    let mut jf_target = None;
    for x in instrs.iter().skip(ii + 1) {
        if x.offset >= t {
            break;
        }
        if matches!(x.op, Op::JUMP_FORWARD | Op::JUMP)
            && !x.is_backward
            && x.target.map_or(false, |mt| mt > t)
        {
            jf_target = x.target;
            break;
        }
        if is_cj(x.op) && x.target == Some(t) && !x.is_backward {
            continue;
        }
        if !Self::comp_arm_value_op(x.op) {
            return None;
        }
    }
    let m = jf_target?;
    let ti = instrs.iter().position(|x| x.offset == t)?;
    let mi = instrs.iter().position(|x| x.offset == m)?;
    if mi <= ti {
        return None;
    }
    // else arm [t, m): value ops or nested ternaries ending before m
    let mut j = ti;
    while j < mi {
        let x = instrs[j];
        if Self::comp_arm_value_op(x.op) {
            j += 1;
            continue;
        }
        if matches!(
            x.op,
            Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
        ) {
            let nm = Self::genexpr_ternary_merge(instrs, j)?;
            let nmi = instrs.iter().position(|x2| x2.offset == nm)?;
            if nmi > mi {
                return None;
            }
            j = nmi;
            continue;
        }
        return None;
    }
    Some(m)
}

    fn build_comprehension(
        &mut self,
        code: &CodeObject,
        _kind: CompKind,
        outer_iter: ExprRef,
    ) -> Option<(ExprRef, Option<ExprRef>, Vec<Comprehension>)> {
        let table = table_for(self.version).ok()?;
        let instrs = crate::bytecode::decode_instructions(code, table, self.version);

        struct PartialGen {
            target: Option<ExprRef>,
            iter: ExprRef,
            ifs: Vec<ExprRef>,
            is_async: bool,
            /// 3.12 genexpr filter line-break quirk: a PJIF filter whose
            /// skip target is the shared back edge means the source had
            /// the `if` clause on its own line (batch 114's inline-comp
            /// quirk applies to code-object genexprs too — cabc 3.12
            /// Set.__rsub__ recompiled to the PJIT+continue form)
            if_break: bool,
        }

        let mut partials: Vec<PartialGen> = Vec::new();
        let mut elt: Option<ExprRef> = None;
        let mut key: Option<ExprRef> = None;
        // UNPACK_SEQUENCE loop targets: collect the following stores into a
        // tuple target
        let mut unpack_remaining = 0usize;
        let mut unpack_names: Vec<ExprRef> = Vec::new();

        let mut stack: Vec<ExprRef> = Vec::new();
        let iter0 = outer_iter;
        let mut pending_async = false;

        let name_of_arg = |code: &CodeObject, idx: usize| -> String {
            code.names
                .get(idx)
                .and_then(|o| match &**o {
                    PyObject::Str(s) => Some(s.clone()),
                    PyObject::Bytes(b) => Some(String::from_utf8_lossy(b).into_owned()),
                    _ => None,
                })
                .unwrap_or_else(|| "?".into())
        };

        let mut prev_inst: Option<(Op, u32)> = None;
        // ternary ELEMENT conds awaiting their arm values at the element
        // producer (`(A if C else B) for x in it` — C's jump targets the
        // else arm, NOT a filter skip). A stack: nested ternaries push
        // outer-first and combine inner-first at the producer.
        // tern_chain_t tracks the else-arm target of the and-chain whose
        // links are being merged into the LAST pushed cond
        let mut tern_conds: Vec<ExprRef> = Vec::new();
        let mut tern_chain_t: Option<usize> = None;
        // first operand of a filter or-chain awaiting its partner (see
        // the cond-jump arm)
        let mut pending_or_filter: Option<ExprRef> = None;
        for (ii, inst) in instrs.iter().enumerate() {
            let prev = prev_inst.replace((inst.op, inst.arg));
            // walrus inside a comprehension: DUP_TOP (<=3.10) / COPY 1
            // (3.11+) then a non-loop store; both duplicated slots fold
            // into a Named expression that becomes the element value
            let walrus = self.version.at_least(3, 8)
                && (matches!(prev, Some((Op::DUP_TOP, _)))
                    || matches!(prev, Some((Op::COPY, 1))))
                && matches!(
                    inst.op,
                    Op::STORE_FAST | Op::STORE_DEREF | Op::STORE_GLOBAL | Op::STORE_NAME
                )
                && !matches!(
                    instrs.get(ii + 1).map(|x| x.op),
                    Some(Op::STORE_FAST)
                        | Some(Op::STORE_NAME)
                        | Some(Op::STORE_DEREF)
                        | Some(Op::STORE_GLOBAL)
                );
            if walrus {
                let name = match inst.op {
                    Op::STORE_FAST => code
                        .varnames
                        .get(inst.arg as usize)
                        .cloned()
                        .unwrap_or_default(),
                    Op::STORE_DEREF => code
                        .deref_name(inst.arg as usize)
                        .unwrap_or("?")
                        .to_string(),
                    Op::STORE_GLOBAL | Op::STORE_NAME => name_of_arg(code, inst.arg as usize),
                    _ => String::new(),
                };
                let v = stack.pop();
                stack.pop(); // the duplicated original
                if let Some(v) = v {
                    stack.push(Rc::new(Expr::Named {
                        target: Rc::new(Expr::Name(name)),
                        value: v,
                    }));
                }
                continue;
            }
            match inst.op {
                Op::DUP_TOP => {
                    if let Some(t) = stack.last().cloned() {
                        stack.push(t);
                    }
                }
                Op::COPY => {
                    let n = inst.arg as usize;
                    if n >= 1 && stack.len() >= n {
                        let v = stack[stack.len() - n].clone();
                        stack.push(v);
                    }
                }
                Op::STORE_GLOBAL | Op::STORE_NAME => {
                    // non-walrus stores do not occur in comprehension code;
                    // consume the value to keep the stack balanced
                    stack.pop();
                }
                Op::RESUME
                | Op::NOP
                | Op::CACHE
                | Op::RETURN_VALUE
                | Op::RETURN_CONST
                | Op::END_FOR
                | Op::POP_ITER
                | Op::NOT_TAKEN
                | Op::POP_TOP
                | Op::JUMP_BACKWARD
                | Op::JUMP_BACKWARD_NO_INTERRUPT
                | Op::JUMP_ABSOLUTE
                | Op::JUMP_FORWARD
                | Op::JUMP
                | Op::GET_ANEXT
                | Op::END_ASYNC_FOR
                | Op::GET_YIELD_FROM_ITER
                | Op::PRECALL
                | Op::EXTENDED_ARG => {}
                Op::GET_ITER => {}
                Op::GET_AITER => {
                    pending_async = true;
                }
                Op::LOAD_FAST | Op::LOAD_FAST_CHECK | Op::LOAD_FAST_BORROW | Op::LOAD_FAST_AND_CLEAR => {
                    let name = code.varnames.get(inst.arg as usize).cloned();
                    match name {
                        Some(n) if n == ".0" => {
                            stack.push(iter0.clone());
                        }
                        Some(n) => stack.push(Rc::new(Expr::Name(n))),
                        None => stack.push(Rc::new(Expr::Name(format!(".{}", inst.arg)))),
                    }
                }
                Op::LOAD_FAST_BORROW_LOAD_FAST_BORROW | Op::LOAD_FAST_LOAD_FAST => {
                    for idx in [(inst.arg >> 4) as usize, (inst.arg & 0xF) as usize] {
                        match code.varnames.get(idx).cloned() {
                            Some(n) if n == ".0" => stack.push(iter0.clone()),
                            Some(n) => stack.push(Rc::new(Expr::Name(n))),
                            None => stack.push(Rc::new(Expr::Name(format!(".{idx}")))),
                        }
                    }
                }
                Op::LOAD_SMALL_INT => {
                    stack.push(Rc::new(Expr::Const(Rc::new(PyObject::Int(inst.arg as i32)))));
                }
                Op::LOAD_DEREF | Op::LOAD_CLOSURE | Op::LOAD_CLASSDEREF => {
                    let n = code
                        .deref_name(inst.arg as usize)
                        .unwrap_or("?")
                        .to_string();
                    stack.push(Rc::new(Expr::Name(n)));
                }
                Op::LOAD_CONST => {
                    if let Some(o) = code.consts.get(inst.arg as usize) {
                        stack.push(Rc::new(Expr::Const(o.clone())));
                    }
                }
                Op::LOAD_NAME => {
                    let n = name_of_arg(code, inst.arg as usize);
                    stack.push(Rc::new(Expr::Name(n)));
                }
                Op::LOAD_GLOBAL => {
                    let idx = if self.version.at_least(3, 11) {
                        (inst.arg >> 1) as usize
                    } else {
                        inst.arg as usize
                    };
                    let n = name_of_arg(code, idx);
                    stack.push(Rc::new(Expr::Name(n)));
                }
                Op::LOAD_ATTR | Op::LOAD_METHOD => {
                    let idx = if inst.op == Op::LOAD_ATTR && self.version.at_least(3, 12) {
                        (inst.arg >> 1) as usize
                    } else {
                        inst.arg as usize
                    };
                    let is_method = inst.op == Op::LOAD_METHOD
                        || (inst.op == Op::LOAD_ATTR
                            && self.version.at_least(3, 12)
                            && inst.arg & 1 != 0);
                    let attr = name_of_arg(code, idx);
                    if let Some(v) = stack.pop() {
                        let e: ExprRef = Rc::new(Expr::Attribute { value: v.clone(), attr });
                        if is_method {
                            if self.version.at_least(3, 14) {
                                stack.push(e);
                                stack.push(v);
                            } else if self.version.at_least(3, 11) {
                                stack.push(v);
                                stack.push(e);
                            } else {
                                stack.push(e);
                                stack.push(v);
                            }
                        } else {
                            stack.push(e);
                        }
                    }
                }
                Op::FOR_ITER => {
                    let it = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    partials.push(PartialGen {
                        target: None,
                        iter: it,
                        ifs: Vec::new(),
                        is_async: std::mem::take(&mut pending_async), if_break: false, });
                }
                Op::STORE_FAST_LOAD_FAST => {
                    let idx = ((inst.arg >> 4) & 0xF) as usize;
                    let name = code.varnames.get(idx).cloned().unwrap_or_default();
                    if let Some(last) = partials.last_mut() {
                        if last.target.is_none() {
                            last.target = Some(Rc::new(Expr::Name(name.clone())));
                        }
                    }
                    // the LOAD half pushes the value back
                    match code.varnames.get((inst.arg & 0xF) as usize).cloned() {
                        Some(n) if n == ".0" => stack.push(iter0.clone()),
                        Some(n) => stack.push(Rc::new(Expr::Name(n))),
                        None => stack.push(Rc::new(Expr::Name("?".to_string()))),
                    }
                }
                Op::STORE_FAST_STORE_FAST => {
                    // 3.13+ paired store: feeds two names to the unpack
                    // target (`for k, v in ...`) or binds simple targets
                    let na = code
                        .varnames
                        .get(((inst.arg >> 4) & 0xF) as usize)
                        .cloned()
                        .unwrap_or_default();
                    let nb = code
                        .varnames
                        .get((inst.arg & 0xF) as usize)
                        .cloned()
                        .unwrap_or_default();
                    for name in [na, nb] {
                        if unpack_remaining > 0 {
                            unpack_names.push(Rc::new(Expr::Name(name)));
                            unpack_remaining -= 1;
                            if unpack_remaining == 0 {
                                let tuple = Rc::new(Expr::Tuple(std::mem::take(
                                    &mut unpack_names,
                                )));
                                if let Some(last) = partials.last_mut() {
                                    last.target = Some(tuple);
                                }
                            }
                            continue;
                        }
                        if let Some(last) = partials.last_mut() {
                            if last.target.is_none() {
                                last.target = Some(Rc::new(Expr::Name(name)));
                                continue;
                            }
                        }
                        stack.pop();
                    }
                }
                Op::STORE_FAST | Op::STORE_DEREF => {
                    let name = if inst.op == Op::STORE_FAST {
                        code.varnames
                            .get(inst.arg as usize)
                            .cloned()
                            .unwrap_or_default()
                    } else {
                        code.deref_name(inst.arg as usize)
                            .unwrap_or("?")
                            .to_string()
                    };
                    if unpack_remaining > 0 {
                        unpack_names.push(Rc::new(Expr::Name(name)));
                        unpack_remaining -= 1;
                        if unpack_remaining == 0 {
                            let tuple = Rc::new(Expr::Tuple(std::mem::take(
                                &mut unpack_names,
                            )));
                            if let Some(last) = partials.last_mut() {
                                last.target = Some(tuple);
                            }
                        }
                        continue;
                    }
                    if let Some(last) = partials.last_mut() {
                        if last.target.is_none() {
                            last.target = Some(Rc::new(Expr::Name(name)));
                            continue;
                        }
                    }
                    // tuple targets or other stores: pop value
                    let v = stack.pop();
                    if name.starts_with('.') {
                        // tuple unpack of loop target
                        if let Some(last) = partials.last_mut() {
                            last.target = Some(v.unwrap_or_else(|| Rc::new(Expr::Name(name))));
                        }
                    }
                }
                Op::UNPACK_SEQUENCE => {
                    // the iterable stays for the element expression; the
                    // next `arg` stores form the tuple loop target
                    unpack_remaining = inst.arg as usize;
                    unpack_names.clear();
                }
                Op::POP_JUMP_IF_FALSE
                | Op::POP_JUMP_IF_TRUE
                | Op::POP_JUMP_FORWARD_IF_FALSE
                | Op::POP_JUMP_FORWARD_IF_TRUE
                | Op::POP_JUMP_BACKWARD_IF_FALSE
                | Op::POP_JUMP_BACKWARD_IF_TRUE
                | Op::JUMP_IF_FALSE_OR_POP
                | Op::JUMP_IF_TRUE_OR_POP
                // py2.6 value-preserving cond jumps: the comprehension
                // `if` filter compiles to JUMP_IF_FALSE with POP_TOPs
                // on both paths (the builder treats POP_TOP as a
                // balance no-op, so popping the cond here is correct).
                // Missing from this arm, py2.6 genexpr/listcomp
                // filters were silently DROPPED (abc 2.6
                // ABCMeta.__new__ `set(name for name, value in
                // namespace.items() if getattr(value,
                // '__isabstractmethod__', False))` lost its if — the
                // abstracts set collected every name)
                | Op::JUMP_IF_FALSE
                | Op::JUMP_IF_TRUE => {
                    if let Some(c) = stack.pop() {
                        // ternary element: this jump's target is the ELSE
                        // arm; a forward JF between the jump and the target
                        // skips the else arm to the merge, and both arm
                        // spans are pure value runs (possibly holding
                        // nested ternaries) — calendar 3.14 formatweek
                        // `(f"..." if d == highlight_day else
                        // self.formatday(...)) for ...` rendered the cond
                        // as a FILTER and dropped the then arm; base64
                        // 3.11 b85decode nests two ternaries
                        if let Some(m_off) = Self::genexpr_ternary_merge(&instrs, ii) {
                            let t_off = inst.target.unwrap_or(usize::MAX);
                            let jump_true_op = matches!(
                                inst.op,
                                Op::POP_JUMP_IF_TRUE
                                    | Op::POP_JUMP_FORWARD_IF_TRUE
                                    | Op::POP_JUMP_BACKWARD_IF_TRUE
                                    | Op::JUMP_IF_TRUE
                            );
                            let cj = if jump_true_op {
                                negate_cond(c.clone())
                            } else {
                                c.clone()
                            };
                            if tern_chain_t == Some(t_off) {
                                // continuation link of the same and-chain
                                if let Some(prev) = tern_conds.last().cloned() {
                                    let mut vals = Vec::new();
                                    flatten_boolop(prev, BoolOpKind::And, &mut vals);
                                    flatten_boolop(cj, BoolOpKind::And, &mut vals);
                                    if let Some(lastc) = tern_conds.last_mut() {
                                        *lastc = Rc::new(Expr::BoolOp {
                                            op: BoolOpKind::And,
                                            values: vals,
                                        });
                                    }
                                }
                            } else {
                                tern_conds.push(cj);
                                tern_chain_t = Some(t_off);
                            }
                            let _ = m_off;
                            continue;
                        }
                        tern_chain_t = None;
                        // `if A or B` filter: A's PJIT hops to the body
                        // merge (a forward label inside the gen, past
                        // the following operand); when the partner
                        // operand's own jump arrives, fold the two into
                        // one Or filter. Rendering them as two `if`
                        // clauses ANDs them - a semantic flip
                        // (_collections_abc 3.6/3.7 Sequence.count
                        // `v is value or v == value`). A pending first
                        // operand whose partner never arrives (a
                        // PJIT-to-end `if not A` shape or scan end)
                        // flushes as its own clause, keeping the
                        // historic rendering for those.
                        let jump_true = matches!(
                            inst.op,
                            Op::POP_JUMP_IF_TRUE
                                | Op::POP_JUMP_FORWARD_IF_TRUE
                                | Op::POP_JUMP_BACKWARD_IF_TRUE
                                | Op::JUMP_IF_TRUE
                        );
                        let target = inst.target.unwrap_or(usize::MAX);
                        let gen_end = instrs.last().map(|x| x.end()).unwrap_or(0);
                        // a true-jump onto the generator's own loop top
                        // (or any backward target) is the `if not C:
                        // continue` filter form, NOT an or-chain hop
                        // (those target the append merge forward):
                        // negate it (cmd 3.7 complete_help: `if not
                        // isinstance(list[i], str)` rendered without
                        // the Not, inverting the filter)
                        let to_loop_top = jump_true
                            && (target <= inst.offset
                                || instrs
                                    .iter()
                                    .any(|x| x.offset == target && x.op == Op::FOR_ITER));
                        let mut f = if to_loop_top {
                            negate_cond(c.clone())
                        } else {
                            c.clone()
                        };
                        if jump_true && !to_loop_top && target < gen_end {
                            if let Some(p) = pending_or_filter.take() {
                                f = Rc::new(Expr::BoolOp {
                                    op: BoolOpKind::Or,
                                    values: vec![p, c.clone()],
                                });
                            } else {
                                pending_or_filter = Some(c);
                                continue;
                            }
                        } else if let Some(p) = pending_or_filter.take() {
                            f = Rc::new(Expr::BoolOp {
                                op: BoolOpKind::Or,
                                values: vec![p, c],
                            });
                        }
                        if let Some(last) = partials.last_mut() {
                            last.ifs.push(f);
                            if !jump_true {
                                if let Some(ti2) =
                                    instrs.iter().position(|x| x.offset == target)
                                {
                                    if instrs[ti2].is_backward
                                        && matches!(
                                            instrs[ti2].op,
                                            Op::JUMP_BACKWARD
                                                | Op::JUMP_ABSOLUTE
                                                | Op::JUMP_BACKWARD_NO_INTERRUPT
                                        )
                                    {
                                        last.if_break = true;
                                    }
                                }
                            }
                        }
                    }
                }
                Op::LIST_APPEND | Op::SET_ADD => {
                    // the element is being produced: any filter operand
                    // still awaiting an or-partner is a lone filter -
                    // commit it (dropping it lost `_weakrefset` 3.12/3.13
                    // genexpr filters entirely)
                    if let Some(p) = pending_or_filter.take() {
                        if let Some(last) = partials.last_mut() {
                            last.ifs.push(p);
                        }
                    }
                    while stack.len() >= 2 {
                        let Some(tc) = tern_conds.pop() else { break };
                        let else_v = stack.pop().unwrap();
                        let then_v = stack.pop().unwrap();
                        stack.push(Rc::new(Expr::Ternary {
                            cond: tc,
                            then_expr: then_v,
                            else_expr: else_v,
                        }));
                    }
                    let item = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    elt.get_or_insert(item);
                }
                Op::MAP_ADD => {
                    // 3.8+: value on top; pre-3.8 (incl. py2.7): key on top
                    let (k, v) = if self.version.at_least(3, 8) {
                        let v = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                        let k = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                        (k, v)
                    } else {
                        let k = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                        let v = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                        (k, v)
                    };
                    key.get_or_insert(k);
                    elt.get_or_insert(v);
                }
                Op::YIELD_VALUE => {
                    if let Some(p) = pending_or_filter.take() {
                        if let Some(last) = partials.last_mut() {
                            last.ifs.push(p);
                        }
                    }
                    while stack.len() >= 2 {
                        let Some(tc) = tern_conds.pop() else { break };
                        let else_v = stack.pop().unwrap();
                        let then_v = stack.pop().unwrap();
                        stack.push(Rc::new(Expr::Ternary {
                            cond: tc,
                            then_expr: then_v,
                            else_expr: else_v,
                        }));
                    }
                    let item = stack.pop().unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    elt.get_or_insert(item);
                }
                // f-string building (3.6+; `'%s' % x` compiles to this on
                // 3.11+, and comprehension elements may be f-strings)
                Op::FORMAT_VALUE | Op::FORMAT_SIMPLE => {
                    let conversion = match inst.arg & 0x3 {
                        1 => Some('s'),
                        2 => Some('r'),
                        3 => Some('a'),
                        _ => None,
                    };
                    let format_spec = if inst.op == Op::FORMAT_VALUE
                        && inst.arg & 0x04 != 0
                    {
                        stack.pop()
                    } else {
                        None
                    };
                    let value = stack
                        .pop()
                        .unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    let part = FStringPart::Value {
                        value,
                        conversion,
                        format_spec: format_spec.map(|f| Box::new(expr_to_fstring(f))),
                    };
                    stack.push(Rc::new(Expr::FString(Box::new(FString {
                        parts: vec![part],
                    }))));
                }
                Op::FORMAT_WITH_SPEC => {
                    let format_spec = stack.pop();
                    let value = stack
                        .pop()
                        .unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    let part = FStringPart::Value {
                        value,
                        conversion: None,
                        format_spec: format_spec.map(|f| Box::new(expr_to_fstring(f))),
                    };
                    stack.push(Rc::new(Expr::FString(Box::new(FString {
                        parts: vec![part],
                    }))));
                }
                Op::CONVERT_VALUE => {
                    let conversion = match inst.arg {
                        1 => Some('s'),
                        2 => Some('r'),
                        3 => Some('a'),
                        _ => None,
                    };
                    let value = stack
                        .pop()
                        .unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())));
                    let part = FStringPart::Value {
                        value,
                        conversion,
                        format_spec: None,
                    };
                    stack.push(Rc::new(Expr::FString(Box::new(FString {
                        parts: vec![part],
                    }))));
                }
                Op::BUILD_STRING => {
                    let n = inst.arg as usize;
                    let mut parts_e: Vec<ExprRef> = Vec::with_capacity(n);
                    for _ in 0..n {
                        if let Some(p) = stack.pop() {
                            parts_e.push(p);
                        }
                    }
                    parts_e.reverse();
                    let mut out_parts = Vec::new();
                    for p in parts_e {
                        match &*p {
                            Expr::Const(o) => match &**o {
                                PyObject::Str(s2) => {
                                    out_parts.push(FStringPart::Literal(s2.clone()))
                                }
                                _ => out_parts.push(FStringPart::Value {
                                    value: p.clone(),
                                    conversion: None,
                                    format_spec: None,
                                }),
                            },
                            Expr::FString(fs) => out_parts.extend(fs.parts.iter().cloned()),
                            _ => out_parts.push(FStringPart::Value {
                                value: p.clone(),
                                conversion: None,
                                format_spec: None,
                            }),
                        }
                    }
                    stack.push(Rc::new(Expr::FString(Box::new(FString {
                        parts: out_parts,
                    }))));
                }
                Op::BINARY_OP => {
                    let rhs = stack.pop();
                    let lhs = stack.pop();
                    if let (Some(l), Some(r)) = (lhs, rhs) {
                        let name = crate::bytecode::binary_op_name(inst.arg, self.version)
                            .unwrap_or("+");
                        let op = binop_from_text(name);
                        stack.push(Rc::new(Expr::Binary {
                            op,
                            left: l,
                            right: r,
                        }));
                    }
                }
                Op::BINARY_ADD
                | Op::BINARY_SUBTRACT
                | Op::BINARY_MULTIPLY
                | Op::BINARY_TRUE_DIVIDE
                | Op::BINARY_FLOOR_DIVIDE
                | Op::BINARY_MODULO
                | Op::BINARY_POWER
                | Op::BINARY_SUBSCR => {
                    let rhs = stack.pop();
                    let lhs = stack.pop();
                    if let (Some(l), Some(r)) = (lhs, rhs) {
                        if inst.op == Op::BINARY_SUBSCR {
                            stack.push(Rc::new(Expr::Subscript { value: l, index: r }));
                        } else {
                            let name = match inst.op {
                                Op::BINARY_ADD => "+",
                                Op::BINARY_SUBTRACT => "-",
                                Op::BINARY_MULTIPLY => "*",
                                Op::BINARY_TRUE_DIVIDE => "/",
                                Op::BINARY_FLOOR_DIVIDE => "//",
                                Op::BINARY_MODULO => "%",
                                Op::BINARY_POWER => "**",
                                _ => "+",
                            };
                            stack.push(Rc::new(Expr::Binary {
                                op: binop_from_text(name),
                                left: l,
                                right: r,
                            }));
                        }
                    }
                }
                Op::COMPARE_OP | Op::IS_OP | Op::CONTAINS_OP => {
                    let rhs = stack.pop();
                    let lhs = stack.pop();
                    if let (Some(l), Some(r)) = (lhs, rhs) {
                        let idx = if inst.op == Op::COMPARE_OP {
                            compare_op_index(inst.arg, self.version)
                        } else if inst.op == Op::IS_OP {
                            if inst.arg == 1 { 9 } else { 8 }
                        } else if inst.arg == 1 {
                            7
                        } else {
                            6
                        };
                        stack.push(Rc::new(Expr::Compare {
                            operands: vec![l, r],
                            ops: vec![cmp_from_index(idx)],
                        }));
                    }
                }
                Op::UNARY_NOT => {
                    if let Some(v) = stack.pop() {
                        stack.push(Rc::new(Expr::Unary {
                            op: UnaryOp::Not,
                            operand: v,
                        }));
                    }
                }
                Op::MAKE_FUNCTION | Op::MAKE_CLOSURE => {
                    // mini-sim: turn the code constant into a Function value
                    let mut popped = stack.pop();
                    // 3.3-3.10: qualname sits above the code constant
                    if self.version.at_least(3, 3) && !self.version.at_least(3, 11) {
                        let is_code = matches!(&popped, Some(e) if matches!(&**e, Expr::Const(o) if matches!(&**o, PyObject::Code(_))));
                        if !is_code {
                            popped = stack.pop();
                        }
                    }
                    let mut handled = false;
                    if let Some(e) = popped {
                        if let Expr::Const(o) = &*e {
                            if let PyObject::Code(c) = &**o {
                                if c.name == "<lambda>" {
                                    // lambda element inside a comprehension:
                                    // build the real Lambda (params come from
                                    // the code object; pre-3.13 defaults ride
                                    // the MAKE_FUNCTION flags)
                                    let c2 = c.clone();
                                    let defaults_e = if inst.arg & 0x01 != 0 {
                                        stack.pop()
                                    } else {
                                        None
                                    };
                                    let kwdefaults_e = if inst.arg & 0x02 != 0 {
                                        stack.pop()
                                    } else {
                                        None
                                    };
                                    let params = self.build_params(
                                        &c2,
                                        defaults_e,
                                        kwdefaults_e,
                                        None,
                                    );
                                    let body = self.lambda_body(&c2);
                                    stack.push(Rc::new(Expr::Lambda {
                                        params: Box::new(params),
                                        body,
                                    }));
                                    handled = true;
                                } else {
                                    stack.push(Rc::new(Expr::Function(Rc::new(FunctionDef {
                                        name: c.name.clone(),
                                        code: c.clone(),
                                        params: Parameters::empty(),
                                        decorators: Vec::new(),
                                        returns: None,
                                        is_async: false,
                                    }))));
                                    handled = true;
                                }
                            }
                        }
                        if !handled {
                            stack.push(e);
                        }
                    }
                }
                Op::CALL_FUNCTION_VAR | Op::CALL_FUNCTION_VAR_KW => {
                    // <=3.4 `f(*t)`: [callable, pos..., *args] (+ **kw
                    // below *args for VAR_KW); pre-3.6 argc encoding
                    let npos = (inst.arg & 0xFF) as usize;
                    let underflow = || Rc::new(Expr::Name("?".to_string()));
                    let star = stack.pop().unwrap_or_else(underflow);
                    let star_kw = if inst.op == Op::CALL_FUNCTION_VAR_KW {
                        stack.pop()
                    } else {
                        None
                    };
                    let mut args = Vec::new();
                    for _ in 0..npos {
                        if let Some(a) = stack.pop() {
                            args.push(a);
                        }
                    }
                    args.reverse();
                    let func = stack.pop().unwrap_or_else(underflow);
                    stack.push(Rc::new(Expr::Call {
                        func,
                        args,
                        keywords: Vec::new(),
                        star_args: Some(star),
                        star_kwargs: star_kw,
                    }));
                }
                Op::CALL_FUNCTION_EX => {
                    // `f(*t)` / `f(*a, **k)` element: [callable(+marker),
                    // args-iterable, (kwargs dict when arg&1)]
                    let underflow = || Rc::new(Expr::Name("?".to_string()));
                    let star_kw = if inst.arg & 1 != 0 {
                        stack.pop()
                    } else {
                        None
                    };
                    let star = stack.pop().unwrap_or_else(underflow);
                    let func = if self.version.at_least(3, 14) {
                        if matches!(stack.last(), Some(m) if is_null_marker(m)) {
                            stack.pop();
                        }
                        stack.pop().unwrap_or_else(underflow)
                    } else if self.version.at_least(3, 11) {
                        let f = stack.pop().unwrap_or_else(underflow);
                        if matches!(stack.last(), Some(m) if is_null_marker(m)) {
                            stack.pop();
                        }
                        f
                    } else {
                        stack.pop().unwrap_or_else(underflow)
                    };
                    stack.push(Rc::new(Expr::Call {
                        func,
                        args: Vec::new(),
                        keywords: Vec::new(),
                        star_args: Some(star),
                        star_kwargs: star_kw,
                    }));
                }
                Op::CALL_FUNCTION | Op::CALL | Op::CALL_METHOD => {
                    let n = if inst.op == Op::CALL_FUNCTION && !self.version.at_least(3, 6) {
                        (inst.arg & 0xFF) as usize
                    } else {
                        inst.arg as usize
                    };
                    let mut args = Vec::new();
                    for _ in 0..n {
                        if let Some(a) = stack.pop() {
                            args.push(a);
                        }
                    }
                    args.reverse();
                    // comprehension instantiation: [genfunc, iterable]
                    let sn = stack.len();
                    if sn >= 2 && n == 0 {
                        let comp_fn = matches!(&*stack[sn - 2], Expr::Function(fd)
                            if matches!(fd.code.name.as_str(),
                                "<listcomp>" | "<setcomp>" | "<dictcomp>" | "<genexpr>"));
                        if comp_fn {
                            let iter = stack.pop().unwrap();
                            let func = stack.pop().unwrap();
                            if let Expr::Function(fd) = &*func {
                                let kind = match fd.code.name.as_str() {
                                    "<listcomp>" => CompKind::List,
                                    "<setcomp>" => CompKind::Set,
                                    "<dictcomp>" => CompKind::Dict,
                                    _ => CompKind::Generator,
                                };
                                if let Some((elt, key, gens)) =
                                    self.build_comprehension(&fd.code, kind, iter)
                                {
                                    stack.push(Rc::new(Expr::Comprehension {
                                        kind,
                                        elt,
                                        key,
                                        generators: gens,
                                    }));
                                    continue;
                                }
                            }
                        }
                    }
                    let underflow = || Rc::new(Expr::Name("?".to_string()));
                    let func = if inst.op == Op::CALL_FUNCTION {
                        // pre-3.7 calling convention: no marker slot
                        stack.pop().unwrap_or_else(underflow)
                    } else if self.version.at_least(3, 14) {
                        // plain call: [NULL, callable, args] — the
                        // callable is on top. Method call (LOAD_ATTR
                        // arg&1): [attr, receiver, args] — the receiver
                        // rides on top and must be dropped, the attr is
                        // the callable (_py_abc 3.14 __instancecheck__'s
                        // genexp rendered `cls(c)` — the receiver popped
                        // as the func — instead of
                        // `cls.__subclasscheck__(c)`)
                        if stack.len() >= 2
                            && matches!(&*stack[stack.len() - 2], Expr::Attribute { .. })
                        {
                            stack.pop(); // receiver marker
                            stack.pop().unwrap_or_else(underflow)
                        } else {
                            if matches!(stack.last(), Some(m) if is_null_marker(m)) {
                                stack.pop();
                            }
                            stack.pop().unwrap_or_else(underflow)
                        }
                    } else if self.version.at_least(3, 11) {
                        // [marker, callable, args]
                        let f = stack.pop().unwrap_or_else(underflow);
                        if is_null_marker(&f) {
                            // PUSH_NULL sat above the callable (plain call)
                            stack.pop().unwrap_or_else(underflow)
                        } else if matches!(&*f, Expr::Attribute { .. }) {
                            stack.pop(); // method receiver slot
                            f
                        } else {
                            if matches!(stack.last(), Some(m) if is_null_marker(m)) {
                                stack.pop();
                            }
                            f
                        }
                    } else {
                        // 3.7-3.10: CALL_METHOD has [callable, marker, args]
                        if inst.op == Op::CALL_METHOD {
                            stack.pop();
                        }
                        stack.pop().unwrap_or_else(underflow)
                    };
                    // comprehension instantiation with the iterator passed
                    // as the single argument (<=3.11 listcomp/genexpr)
                    if args.len() == 1 && keywords_empty(&args) {
                        if let Expr::Function(fd) = &*func {
                            let kind = match fd.code.name.as_str() {
                                "<listcomp>" => Some(CompKind::List),
                                "<setcomp>" => Some(CompKind::Set),
                                "<dictcomp>" => Some(CompKind::Dict),
                                "<genexpr>" => Some(CompKind::Generator),
                                _ => None,
                            };
                            if let Some(kind) = kind {
                                if let Some((elt, key, gens)) = self.build_comprehension(
                                    &fd.code,
                                    kind,
                                    args[0].clone(),
                                ) {
                                    stack.push(Rc::new(Expr::Comprehension {
                                        kind,
                                        elt,
                                        key,
                                        generators: gens,
                                    }));
                                    continue;
                                }
                            }
                        }
                    }
                    stack.push(Rc::new(Expr::Call {
                        func,
                        args,
                        keywords: Vec::new(),
                        star_args: None,
                        star_kwargs: None,
                    }));
                }
                Op::BUILD_TUPLE | Op::BUILD_LIST | Op::BUILD_SET => {
                    let n = inst.arg as usize;
                    let mut items = Vec::new();
                    for _ in 0..n {
                        if let Some(v) = stack.pop() {
                            items.push(v);
                        }
                    }
                    items.reverse();
                    let e = match inst.op {
                        Op::BUILD_TUPLE => Expr::Tuple(items),
                        Op::BUILD_LIST => Expr::List(items),
                        _ => Expr::Set(items),
                    };
                    stack.push(Rc::new(e));
                }
                Op::TO_BOOL => {}
                // slice construction inside a comprehension element:
                // without this the operands stay on the stack and a
                // following BINARY_SUBSCR pairs the wrong two (calendar
                // 3.6-3.11 monthdatescalendar `[dates[i:i+7] for i in
                // ...]` rendered `i[i+7]`, dropping the captured `dates`
                // freevar - which also lost the STORE_DEREF closure and
                // the whole following elif chain's nesting). Only
                // BUILD_SLICE is handled here: py2 SLICE_0-3 / 3.12
                // BINARY_SLICE inside comprehensions are left to the
                // historic `_ => {}` fall-through (handling them shifted
                // other py2/3.x comprehension elts and regressed
                // bisect/cProfile/StringIO/ast/base64 AST matches).
                Op::BUILD_SLICE => {
                    let none_if = |e: ExprRef| -> Option<ExprRef> {
                        match &*e {
                            Expr::Const(o)
                                if matches!(&**o, PyObject::None) =>
                            {
                                None
                            }
                            _ => Some(e),
                        }
                    };
                    let under = || Rc::new(Expr::Name("?".to_string()));
                    let (start, stop, step) = if inst.arg == 3 {
                        let step = none_if(stack.pop().unwrap_or_else(under));
                        let stop = none_if(stack.pop().unwrap_or_else(under));
                        let start = none_if(stack.pop().unwrap_or_else(under));
                        (start, stop, step)
                    } else {
                        let stop = none_if(stack.pop().unwrap_or_else(under));
                        let start = none_if(stack.pop().unwrap_or_else(under));
                        (start, stop, None)
                    };
                    stack.push(Rc::new(Expr::Slice(Box::new(SliceExpr {
                        start,
                        stop,
                        step,
                    }))));
                }
                // 3.11+ plain-call marker slot: a non-method callable is
                // followed by PUSH_NULL, and CALL pops [callable, marker].
                // Ignoring it lets CALL's method-receiver heuristic eat the
                // operand below (configparser 3.13 _strip_inline genexpr's
                // `re.escape(prefix)` swallowed the leading f-string const).
                Op::PUSH_NULL => {
                    stack.push(Rc::new(Expr::Name("\u{0}null".to_string())));
                }
                _ => {}
            }
        }

        let elt = elt?;
        if partials.is_empty() {
            return None;
        }
        let gens: Vec<Comprehension> = partials
            .into_iter()
            .map(|p| Comprehension {
                target: p.target.unwrap_or_else(|| Rc::new(Expr::Name("_".to_string()))),
                iter: p.iter,
                ifs: p.ifs,
                is_async: p.is_async,
                if_line_break: p.if_break,
            })
            .collect();
        Some((elt, key, gens))
    }
}

// =====================  PEP 709 inline comprehensions (3.12+)  =====================

impl<'a> Ctx<'a> {
    /// Look backwards from the current FOR_ITER for the comprehension
    /// prologue: `GET_ITER; [LOAD_FAST_AND_CLEAR/SWAP...]; BUILD_{LIST,SET,
    /// MAP} 0; [SWAP...]`. Returns the comprehension kind when matched.
    fn detect_inline_comp(&self) -> Option<CompKind> {
        // PEP 709 inline comprehensions (3.12+) and py2.7 module-level
        // list/set/dict comprehensions share the same shape
        let inline_era = self.version.at_least(3, 12) || self.version.major == 2;
        if !inline_era {
            return None;
        }
        let cur = self.cur_offset;
        let ci = *self.idx_of.get(&cur)?;
        // walk back to the FOR_ITER
        let mut i = ci;
        while self.instrs.get(i).map(|x| x.offset) != Some(cur) && i > 0 {
            i -= 1;
        }
        // scan backwards: skip SWAPs, find BUILD_x 0, then GET_ITER before it
        let mut j = i;
        let mut kind = None;
        let mut steps = 0;
        while j > 0 && steps < 14 {
            j -= 1;
            steps += 1;
            // hop over a completed nested comprehension region (py2: the
            // outer comp's iterable was itself an inline comp)
            let off = self.instrs[j].offset;
            if let Some((rs, _)) = self
                .completed_comp_regions
                .iter()
                .find(|(rs, re)| off >= *rs && off < *re)
            {
                let rs = *rs;
                if let Some(&rj) = self.idx_of.get(&rs) {
                    j = rj; // loop pre-decrements to the instruction BEFORE
                            // the nested region — its own BUILD_x belongs
                            // to the nested comp, not the outer one
                    continue;
                }
            }
            let inst = &self.instrs[j];
            match inst.op {
                // 3.13 places GET_ITER right before FOR_ITER; 3.12 places it
                // before the LOAD_FAST_AND_CLEAR prologue; py2.7 has
                // BUILD_x 0; <iter expr>; GET_ITER; FOR_ITER
                Op::SWAP
                | Op::GET_ITER
                | Op::GET_AITER
                | Op::NOP
                | Op::LOAD_NAME
                | Op::LOAD_FAST
                | Op::LOAD_CONST
                | Op::LOAD_GLOBAL
                | Op::LOAD_DEREF
                | Op::LOAD_METHOD
                | Op::LOAD_ATTR
                | Op::CALL
                | Op::CALL_FUNCTION
                | Op::CALL_METHOD
                | Op::BUILD_TUPLE
                | Op::BUILD_LIST
                | Op::DUP_TOP
                | Op::COPY => {
                    // 2.6 stashes the accumulator in a synthetic `_[N]`
                    // name between BUILD_LIST and the loop
                    if matches!(inst.op, Op::BUILD_LIST | Op::BUILD_TUPLE) && inst.arg == 0 {
                        // empty collection build = comprehension accumulator
                        kind = Some(CompKind::List);
                        break;
                    }
                    continue;
                }
                Op::STORE_NAME
                    if self.version.major == 2
                        && self.const_name(inst.arg as usize).starts_with("_[") =>
                {
                    continue;
                }
                Op::STORE_FAST
                    if self.version.major == 2
                        && self.local_name(inst.arg as usize).starts_with("_[") =>
                {
                    continue;
                }
                Op::BUILD_SET if inst.arg == 0 => {
                    kind = Some(CompKind::Set);
                    break;
                }
                Op::BUILD_MAP if inst.arg == 0 => {
                    kind = Some(CompKind::Dict);
                    break;
                }
                _ => return None,
            }
        }
        let kind = kind?;
        if self.version.major == 2 {
            // py2: BUILD_x 0; <iter expr>; GET_ITER; FOR_ITER — verify a
            // GET_ITER sits between the build and the loop
            let ok = self.instrs[j..i]
                .iter()
                .any(|x| matches!(x.op, Op::GET_ITER | Op::GET_AITER));
            return if ok { Some(kind) } else { None };
        }
        // before the BUILD: LOAD_FAST_AND_CLEAR*/SWAP/... then GET_ITER
        let mut k = j;
        let mut steps = 0;
        while k > 0 && steps < 8 {
            k -= 1;
            steps += 1;
            let inst = &self.instrs[k];
            match inst.op {
                Op::GET_ITER | Op::GET_AITER => return Some(kind),
                Op::SWAP | Op::LOAD_FAST_AND_CLEAR => continue,
                _ => return None,
            }
        }
        None
    }

    /// offset of the BUILD_x 0 that opened the current py2 comprehension
    fn comp_prologue_start(&self) -> usize {
        let Some(&ci) = self.idx_of.get(&self.cur_offset) else {
            return self.cur_offset;
        };
        let mut j = ci;
        let mut steps = 0;
        while j > 0 && steps < 16 {
            j -= 1;
            steps += 1;
            let ins = &self.instrs[j];
            if matches!(ins.op, Op::BUILD_LIST | Op::BUILD_SET | Op::BUILD_MAP)
                && (ins.arg == 0 || ins.op == Op::BUILD_MAP)
            {
                return ins.offset;
            }
        }
        self.cur_offset
    }

    fn start_inline_comp(&mut self, kind: CompKind, inst: &Instruction) {
        // the iterable is on top (GET_ITER kept it); consume it into the
        // generator model
        let iter = self.pop_expr();
        // cleared variables from the prologue: collect LOAD_FAST_AND_CLEAR
        // across SWAP/BUILD/GET_ITER until a non-prologue instruction
        let mut cleared = Vec::new();
        let cur = self.cur_offset;
        if let Some(&ci) = self.idx_of.get(&cur) {
            for back in (0..ci).rev().take(12) {
                let ins = &self.instrs[back];
                match ins.op {
                    Op::LOAD_FAST_AND_CLEAR => {
                        cleared.push(self.local_name(ins.arg as usize));
                    }
                    Op::SWAP
                    | Op::GET_ITER
                    | Op::GET_AITER
                    | Op::NOP
                    | Op::BUILD_LIST
                    | Op::BUILD_SET
                    | Op::BUILD_MAP
                    | Op::COPY => continue,
                    _ => break,
                }
            }
        }
        // pre-scan: collect every FOR_ITER offset and the region end
        let ci = *self.idx_of.get(&cur).unwrap_or(&0);
        let mut for_offsets = vec![inst.offset];
        let mut depth = 1usize;
        let mut end_off = usize::MAX;
        if self.version.major == 2 {
            // py2: no END_FOR; the outermost FOR_ITER exit ends the region
            end_off = inst.target.unwrap_or(usize::MAX);
            for ins in self.instrs.iter().skip(ci + 1) {
                if ins.offset >= end_off {
                    break;
                }
                if matches!(ins.op, Op::FOR_ITER) {
                    for_offsets.push(ins.offset);
                }
            }
        } else {
            for ins in self.instrs.iter().skip(ci + 1) {
                match ins.op {
                    Op::FOR_ITER | Op::FOR_LOOP => {
                        depth += 1;
                        for_offsets.push(ins.offset);
                    }
                    Op::END_FOR => {
                        depth -= 1;
                        if depth == 0 {
                            end_off = ins.offset;
                            break;
                        }
                    }
                    Op::RETURN_VALUE | Op::RETURN_CONST => break,
                    _ => {}
                }
            }
        }
        // an active comprehension becomes the parent of this nested one
        if let Some(parent) = self.inline_comp.take() {
            self.inline_comp_stack.push(parent);
        }
        // keep the iterator on the stack like the VM does; the loop-target
        // store will consume it
        self.push(iter.clone());
        let cleared_all = cleared;
        self.inline_comp = Some(InlineComp {
            kind,
            start: self.comp_prologue_start(),
            iter: iter.clone(),
            end: end_off,
            for_iter_offsets: for_offsets,
            gens: Vec::new(),
            cur: Some(PartialGen {
                target: None,
                iter,
                ifs: Vec::new(),
                if_break: false,
            }),
            elt: None,
            key: None,
            cleared_vars: cleared_all,
            target_seen: false,
        });
        self.comp_target_store = true;
    }

    fn comp_add_element(&mut self, inst: &Instruction) {
        let (value, key) = if inst.op == Op::MAP_ADD {
            // 3.8+: value on top, key below
            let value = self.pop_expr();
            let key = self.pop_expr();
            (value, Some(key))
        } else {
            (self.pop_expr(), None)
        };
        if let Some(comp) = &mut self.inline_comp {
            if let Some(k) = key {
                comp.key.get_or_insert(k);
            }
            comp.elt.get_or_insert(value);
        }
    }

    /// True when the offset lies inside the active comprehension region.
    fn in_comp_region(&self, offset: usize) -> bool {
        self.inline_comp
            .as_ref()
            .map_or(false, |c| offset > c.for_iter_offsets[0] && offset < c.end)
    }

    /// True when the instructions immediately before `offset` contain a
    /// BUILD_{LIST,SET,MAP} 0 — the marker of a NEW (nested) comprehension
    /// level rather than an extra generator of the current one.
    fn has_build_prologue(&self, offset: usize) -> bool {
        let Some(&ci) = self.idx_of.get(&offset) else {
            return false;
        };
        for back in (0..ci).rev().take(6) {
            let ins = &self.instrs[back];
            match ins.op {
                Op::SWAP | Op::LOAD_FAST_AND_CLEAR | Op::LOAD_FAST | Op::GET_ITER
                | Op::GET_AITER | Op::NOP | Op::LOAD_NAME | Op::LOAD_DEREF
                | Op::LOAD_CONST | Op::COPY => continue,
                Op::BUILD_LIST | Op::BUILD_SET | Op::BUILD_MAP => {
                    return ins.arg == 0;
                }
                _ => return false,
            }
        }
        false
    }

    /// Nested FOR_ITER inside an inline comprehension: complete the current
    /// generator and start a new one with the popped iterable.
    fn push_nested_comp_gen(&mut self) {
        // additional generator of the same comprehension.
        // 3.12+: the iterator stays on the stack (POP_ITER removes it at
        // the loop end). py2: there is no POP_ITER — the single end-of-comp
        // pop covers only the outermost iterator, so consume this one here
        // (start_inline_comp pushed it back for the target store)
        let iter = if self.version.major == 2 {
            self.pop_expr()
        } else {
            self.stack
                .last()
                .and_then(|sv| match sv {
                    Sv::E(e) => Some(e.clone()),
                    _ => None,
                })
                .unwrap_or_else(|| Rc::new(Expr::Name("?".to_string())))
        };
        if self.version.major == 2 {
            // keep the iterator available for the loop-target store flow
            self.push(iter.clone());
        }
        if let Some(comp) = &mut self.inline_comp {
            if let Some(done) = comp.cur.take() {
                comp.gens.push(Comprehension {
                    target: done
                        .target
                        .unwrap_or_else(|| Rc::new(Expr::Name("_".to_string()))),
                    iter: done.iter,
                    ifs: done.ifs,
                    is_async: false,
                    if_line_break: done.if_break,
                });
            }
            comp.cur = Some(PartialGen {
                target: None,
                iter,
                ifs: Vec::new(),
                if_break: false,
            });
            comp.target_seen = false;
        }
        self.comp_target_store = true;
    }

    /// Called at the outermost END_FOR: build the comprehension expression.
    /// For a nested comprehension the result becomes the parent's element.
    fn finish_inline_comp(&mut self) {
        let Some(mut comp) = self.inline_comp.take() else {
            return;
        };
        if self.version.major == 2 && comp.start < comp.end && comp.end != usize::MAX {
            self.completed_comp_regions.push((comp.start, comp.end));
        }
        if let Some(done) = comp.cur.take() {
            comp.gens.push(Comprehension {
                target: done
                    .target
                    .unwrap_or_else(|| Rc::new(Expr::Name("_".to_string()))),
                iter: done.iter,
                ifs: done.ifs,
                is_async: false,
                if_line_break: done.if_break,
            });
        }
        let elt = comp
            .elt
            .take()
            .unwrap_or_else(|| Rc::new(Expr::Name("_".to_string())));
        let expr: ExprRef = Rc::new(Expr::Comprehension {
            kind: comp.kind,
            elt,
            key: comp.key.take(),
            generators: std::mem::take(&mut comp.gens),
        });
        // the BUILD_LIST/SET/MAP placeholder on the stack is replaced by the
        // comprehension expression (it may sit below a leftover iterator)
        let mut replaced = false;
        let n = self.stack.len();
        for i in (0..n).rev().take(3) {
            if let Sv::E(e) = &self.stack[i] {
                if matches!(&**e, Expr::List(_) | Expr::Set(_) | Expr::Dict(_)) {
                    self.stack[i] = Sv::E(expr.clone());
                    replaced = true;
                    // 3.13+ emits `END_FOR; POP_TOP/POP_ITER`: the VM's
                    // cleanup drops the exhausted iterator that sat ABOVE
                    // the result — we never modeled that slot, so eat the
                    // upcoming cleanup instead of letting it swallow the
                    // comprehension
                    if self.version.at_least(3, 13) && i + 1 == n {
                        if let Some(&ci) = self.idx_of.get(&self.cur_offset) {
                            if matches!(
                                self.instrs.get(ci + 1).map(|x| x.op),
                                Some(Op::POP_TOP) | Some(Op::POP_ITER)
                            ) {
                                                                self.skip_until = Some(self.instrs[ci + 1].end());
                            }
                        }
                    }
                    break;
                }
            }
        }
        if let Some(mut parent) = self.inline_comp_stack.pop() {
            // nested comprehension: parent resumes; its LIST_APPEND will
            // pop this expression as the parent's element
            for v in comp.cleared_vars {
                if !parent.cleared_vars.contains(&v) {
                    parent.cleared_vars.push(v);
                }
            }
            self.inline_comp = Some(parent);
            if !replaced {
                self.push(expr);
            }
        } else {
            for v in comp.cleared_vars.iter() {
                if !self.comp_restore_vars.contains(v) {
                    self.comp_restore_vars.push(v.clone());
                }
            }
            for v in comp.cleared_vars.drain(..) {
                if !self.pending_restore_vars.contains(&v) {
                    self.pending_restore_vars.push(v);
                }
            }
            if !replaced {
                self.push(expr);
            }
        }
    }
}
